local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["npc:denalan"] = {n="德纳兰",s="德纳兰在奥拉密斯湖研究泰达希尔的奇异植物，寻找消除腐化的方法。他照料着湖边的一小块园地，请年轻的冒险者采集样本、调查林精，并试验附魔土壤。",h="德纳兰在奥拉密斯湖研究泰达希尔的奇异植物，寻找消除腐化的方法。他照料着湖边的一小块园地，请年轻的冒险者采集样本、调查林精，并试验附魔土壤。",kw={"黑苔","植物学","德纳兰","草药师","卡多雷","奥拉密斯湖","奥肯斯古尔","种植箱","泰达希尔","林精"},ang={["class:Druid"]="身为德鲁伊，你或许会发现自己与德纳兰的湖畔试验志趣相投。他的工作帮助塞纳里奥议会追查并清除在泰达希尔根系中蔓延的污秽。",["profession:Herbalism"]="身为草药师，你传承着kaldorei研究植物的传统。采集和培育野生植物，有助于揭示自然界更深层的病患。",["race:NightElf"]="身为暗夜精灵，你也参与了kaldorei早期的探索，试图了解新家园泰达希尔那些意料之外的缺陷与成长中的阵痛。"},sec={{t="奥拉密斯湖畔的植物学家",b="德纳兰在奥拉密斯湖东岸研究植物。他在一顶布棚下工作，身旁放着野外工具和一排排种植箱。许多卡多雷专注于战备警戒或高深的德鲁伊仪式，他却将日子倾注于草药学。他选择这块园地，而非达纳苏斯宏伟的兽穴，以便研究新世界之树栽下后生长出的奇异植物。"},{t="调查泰达希尔的病变",b="德纳兰正在调查泰达希尔本土野生生物日益加剧的躁动。林精是由木质躯干和嫩芽构成的林地生灵，通常性情温顺，如今却变得越来越好斗。他为土壤附魔，在人工环境中培育野生种子，研究腐化如何渗入根系。他检视的样本包括闪光的叶片、发光的水果和缠满苔藓的植物，试图找出侵扰森林枝干的污秽。"}},faq={{q="在哪里可以找到德纳兰？",a="德纳兰位于泰达希尔南部的奥拉密斯湖东岸，在多兰纳尔以南。他的小营地就在水边，里面有一顶棚子和经过耕作的苗床。",al={"德纳兰位置","德纳兰在哪里","德纳兰地图"}},{q="德纳兰在营地里研究什么？",a="德纳兰研究泰达希尔的奇异植物，以及当地林地之灵的攻击行为。他用附魔种植箱培育林精种子，检视奇特的样本，寻找清除新世界之树生态系统中腐化的方法。",al={"德纳兰做什么","德纳兰的目的","德纳兰为什么在湖边"}},{q="林精为什么攻击人？",a="林精是泰达希尔枝干上土生土长的植物状自然之灵。它们通常十分平和，但随着非自然的腐化在世界之树的土壤和根系中蔓延，它们变得狂暴而反复无常。德纳兰这样的研究者通过研究它们的种子，探究这种变化的原因。",al={"林精为什么好斗","林精背景故事","腐化的林精"}},{q="德纳兰的种植箱有什么用途？",a="德纳兰用经过特殊处理、填满附魔土壤的苗床，培育野生种子和奇异植物的插枝。这些苗床让他能够避开野外的污染，观察森林植物对净化土壤的反应。",al={"德纳兰种植箱","德纳兰的土壤","德纳兰的土壤箱"}},{q="德纳兰与谁合作？",a="德纳兰与达纳苏斯的德鲁伊雷利亚·绿树合作，后者和他一样对林精感兴趣。多兰纳尔的一位同事也会给他送来达纳苏斯的稀土。",al={"德纳兰的盟友","德纳兰向谁汇报"}},{q="德纳兰检视的布满苔藓的心脏是什么？",a="布满苔藓的心脏是一枚染疫的植物核心，取自泰达希尔一只名为恶臭的黑苔兽的腐化林精。德纳兰将它放在附魔土壤中研究，以了解扭曲岛上植物的非自然疾病。",al={"布满苔藓的心脏","布满苔藓的心脏任务","黑苔的心脏"}}},fp="7,221,27.392.0,36.404.0,25.168.0,44.258.0,41.253.0,42.212.0,27.165.0,52.232.0"}
P.entries["npc:dendrite-starblaze"] = {n="德迪利特·星焰",s="在永夜港，德迪利特·星焰指引着来到月光林地的德鲁伊。身为塞纳里奥议会的导师，他接纳暗夜精灵和牛头人学徒。他召唤他们来到这片神圣的林地，掌握这里的仪式，从净化毒素到与自然的各种形态交流。",h="在永夜港，德迪利特·星焰指引着来到月光林地的德鲁伊。身为塞纳里奥议会的导师，他接纳暗夜精灵和牛头人学徒。他召唤他们来到这片神圣的林地，掌握这里的仪式，从净化毒素到与自然的各种形态交流。",kw={"水栖形态","塞纳里奥议会","救死扶伤","德迪利特·星焰","德鲁伊","重新学习","月光林地","暗夜精灵","永夜港"},ang={["class:Druid"]="当你初次传送到月光林地时，德迪利特会指引你治愈疾病，并寻求与水栖形态沟通。",["race:NightElf"]="身为Kaldorei的新学徒，你会在永夜港见到德迪利特，他在那里恪守守护自然的古老仪式，欢迎你加入塞纳里奥教团。",["race:Tauren"]="身为来自莫高雷的Shu'halo德鲁伊，你能从德迪利特身上看到，塞纳里奥议会的纽带如何超越部落与联盟之间的仇怨。"},sec={{t="圣地中的引路人",b="当德鲁伊新手学会传送: 月光林地时，德迪利特是最早在永夜港迎接他们的人之一。他遵循塞纳里奥议会的使命，超越联盟与部落的界限。暗夜精灵和牛头人德鲁伊在这片圣地的枝叶下情同手足，卡多雷的传统与牛头人的道路在此交汇。"},{t="荒野的试炼",b="德迪利特引导学徒深入了解自然之道。他派他们查验受污染的水源，寻找能够祛毒除疫的草药。随后，他主持水下试炼，在水面之下考验他们的耐心与毅力，之后才准许他们与水栖形态沟通。"}},faq={{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位暗夜精灵德鲁伊，也是塞纳里奥议会的导师，居于月光林地的永夜港。他引导成长中的德鲁伊完成必要的仪式与训练。",al={"德迪利特·星焰","德迪利特是谁","星焰 月光林地"}},{q="一位暗夜精灵为何会训练部落的牛头人？",a="塞纳里奥议会超然于联盟与部落的政治分歧之外。在月光林地，暗夜精灵和牛头人遵循古老的兄弟誓约，共同修习德鲁伊之道，将世俗纷争留在山口之外。",al={"德迪利特为何训练部落","德迪利特 牛头人德鲁伊","跨阵营德鲁伊导师"}},{q="德迪利特·星焰提供哪些任务？",a="德迪利特引导德鲁伊完成祛毒和治病的试炼，随后指引他们进行掌握水栖形态所需的沟通。",al={"德迪利特任务","星焰任务列表"}},{q="在哪里可以找到德迪利特·星焰？",a="德迪利特位于月光林地的永夜港，就在月神湖北岸。",al={"德迪利特位置","星焰在哪里","德迪利特·星焰地图"}},{q="年轻的德鲁伊初次如何抵达德迪利特身边？",a="各族的训练师会在德鲁伊新手修习至第十阶左右时，传授传送: 月光林地。这个法术会将他们直接送到月光林地，德迪利特就在那里等候。",al={"如何前往德迪利特处","传送至月光林地任务"}},{q="其他职业的冒险者能与他交谈吗？",a="其他职业的冒险者可以前往永夜港，与德迪利特交谈。对于未修习塞纳里奥议会德鲁伊传统的人，他不提供训练、试炼或任务。",al={"非德鲁伊 德迪利特","战士能否与星焰交谈"}}},fx={["3038adca"]={q="德迪利特·星焰想要什么？",a="德迪利特引导初出茅庐的德鲁伊踏上自然与平衡之路。他通过向荒野之灵致敬的试炼——例如与巨熊之灵沟通，以及掌握毒素与水之力——确保所有学徒，无论出身如何，都能学会塞纳里奥议会的职责与古老修行。",al={"德迪利特·星焰的目标","德迪利特想要什么","德迪利特·星焰的动机"}},ef589fff={q="德迪利特·星焰为何在月光林地？",a="月光林地是神圣的中立之地，塞纳里奥议会在此避开尘世的阵营纷争，举行集会。德迪利特驻守永夜港，担任新晋德鲁伊的导师，教授他们成长所必需的基础知识并主持试炼。",al={"德迪利特为何在这里","德迪利特·星焰在月光林地的位置","德迪利特为何在永夜港"}},["7aee8496"]={q="德迪利特·星焰与谁有关联？",a="德迪利特是塞纳里奥议会的使者和导师。他与暗夜精灵和牛头人出身的德鲁伊密切合作，听从荒野之灵的召唤和塞纳留斯的教诲，而非达纳苏斯或部落的政治旗帜。",al={"德迪利特·星焰的阵营","德迪利特·星焰与塞纳里奥议会","德迪利特效忠谁"}}},fp="18,270,27.297.0,18.290.0,26.165.0,40.236.0,42.119.0,38.91.0,54.163.0,44.154.0"}
P.entries["npc:deputy-feldon"] = {n="菲尔顿副队长",s="在 湖畔镇大桥 南侧，菲尔顿副队长守望着通往湖畔镇的道路。成群的豺狼人正悄然逼近城镇，他紧张地保持着警戒。",h="在 湖畔镇大桥 南侧，菲尔顿副队长守望着通往湖畔镇的道路。成群的豺狼人正悄然逼近城镇，他紧张地保持着警戒。",kw={"桥","菲尔顿副队长","菲尔顿","豺狼人","卫兵","湖畔镇","赤脊山"},ang={["faction:Alliance"]="身为联盟的勇士，你能看到暴风城外围领地的处境有多艰难：当地卫兵需要过往的勇士相助，才能维持国王治下的安宁。"},sec={{t="忧心忡忡的卫兵",b="菲尔顿副队长在湖畔镇的桥南侧站岗，守卫着一条贸易与出行的要道。黑石兽人从北方步步紧逼，成群的豺狼人则横行于南部丘陵，让镇上的卫兵疲于应付。菲尔顿一旦离开岗位，湖畔镇外围的防守就会削弱。他只能依靠过往的冒险者击退豺狼人，免得它们切断城镇与外界的联系。"}},faq={{q="菲尔顿副队长是谁？",a="菲尔顿副队长是湖畔镇的卫兵，驻守在赤脊山通往南部主干道的桥南侧。",al={"菲尔顿","菲尔顿 是谁","菲尔顿副队长的职责"}},{q="菲尔顿副队长为什么担忧豺狼人？",a="通往艾尔文森林的道路沿途已经发现了豺狼人的营地。菲尔顿担心它们会继续深入人类腹地，让湖畔镇不再是唯一遭到围困的城镇。卫兵的装备不足以应付它们。",al={"为什么是豺狼人","菲尔顿 的豺狼人问题","步步逼近的豺狼人"}},{q="菲尔顿为什么不亲自对付豺狼人？",a="湖畔镇的卫兵人手不足，还要同时应对兽人和豺狼人。菲尔顿一旦离开桥边的岗位，城镇入口就会无人把守。",al={"菲尔顿 为什么不战斗","菲尔顿 的职责"}},{q="在哪里能找到菲尔顿副队长？",a="菲尔顿副队长在 湖畔镇大桥 南侧不远处的道路上站岗，守卫着城镇南面的通道。",al={"菲尔顿 的位置","菲尔顿 在哪里"}}},fp="13,118,15.375.0,21.133.0,42.219.0,48.151.0,33.121.0"}
P.entries["npc:deputy-rainer"] = {n="瑞尼尔副队长",s="在西泉要塞，瑞尼尔副队长守卫着艾尔文的西部边境，抵御来自西部荒野的威胁。这位暴风城军队军官协调着当地的防务，但援军迟迟未到。",h="在西泉要塞，瑞尼尔副队长守卫着艾尔文的西部边境，抵御来自西部荒野的威胁。这位暴风城军队军官协调着当地的防务，但援军迟迟未到。",kw={"瑞尼尔副队长","艾尔文森林","格里安·斯托曼","霍格","治安官杜汉","河爪","西泉要塞","西部荒野"},ang={["faction:Alliance"]="身为联盟的英雄，你会看到，当王国的常规支援无法抵达时，暴风城的边远驻军如何应对困境。"},sec={{t="守卫西部边境",b="西泉要塞守卫着艾尔文森林的西部边缘，道路从这里通往西部荒野。暴风城的政务陷入停滞，大批军队或远驻他乡，或受困于官僚体制，像这样的边境哨所因而兵力不足。瑞尼尔副队长带着手头仅有的兵力，在塔楼外组织防御。\n\n河爪豺狼人和四处游荡的盗贼威胁着当地的道路。瑞尼尔依靠过往旅人和受雇的冒险者，维护林间小径的安全。"},{t="通往西部荒野之路",b="瑞尼尔副队长提防着河爪族群，并提醒旅人小心臭名昭著的豺狼人首领霍格。他也向人们传达河对岸动荡地区的消息。艾尔文边境的混乱源于西部荒野那些无法无天的农田，因此他派遣有能力的志愿者越过边境，前去支援格里安·斯托曼和处境艰难的人民军。"}},faq={{q="瑞尼尔副队长是谁？",a="瑞尼尔副队长是一名暴风城军队军官，驻守在艾尔文森林西部边缘的西泉要塞。他负责道路安全，并雇用冒险者对抗附近的威胁。",al={"瑞尼尔 艾尔文","瑞尼尔是谁","西泉要塞军官"}},{q="西泉要塞为何兵力不足？",a="暴风城军队的大部分兵力都部署在别处，而首都的政局混乱，使常规援军无法抵达边远地区。闪金镇的治安官杜汉不得不依靠独立行动的冒险者来帮助瑞尼尔。",al={"西泉要塞为何没有卫兵","要塞为何陷入困境","西泉要塞需要帮助"}},{q="瑞尼尔正在应对哪些威胁？",a="瑞尼尔设法遏制要塞南面树林中的河爪豺狼人、四处游荡的盗贼，以及臭名昭著的豺狼人首领霍格，后者专门袭击边境沿线的旅人。",al={"西泉要塞附近有哪些敌人","河爪豺狼人 西泉要塞","西泉要塞豺狼人"}},{q="清除豺狼人后，瑞尼尔会派冒险者去哪里？",a="要塞附近的豺狼人被击退后，瑞尼尔会派经验丰富的冒险者越过西部边境，进入西部荒野。他们会在那里帮助哨兵岭的格里安·斯托曼和人民军。",al={"瑞尼尔之后去哪里","瑞尼尔任务 西部荒野","西泉要塞之后"}}},fx={["8453208a"]={q="瑞尼尔副队长站在哪一边？",a="瑞尼尔是暴风城军队的一名忠诚军官，为暴风城王国和联盟效力。他驻守在西泉要塞，听命于闪金镇的治安官杜汉，竭力保护艾尔文森林西部边境，抵御不断逼近的混乱。",al={"瑞尼尔副队长的阵营","瑞尼尔为谁效力","瑞尼尔是联盟吗"}},b0214c4a={q="瑞尼尔副队长想要什么？",a="瑞尼尔希望招募有能力的志愿者，保卫艾尔文森林的西部边界。军队兵力捉襟见肘，因此他希望削减南面凶悍的河爪豺狼人群，保护商路免受盗贼侵扰，并终结霍格的威胁。",al={"瑞尼尔想要什么","瑞尼尔副队长的目标","瑞尼尔有什么请求"}},["5835f036"]={q="瑞尼尔副队长为什么在这里？",a="瑞尼尔驻守在西泉要塞，守卫艾尔文森林与西部荒野之间的边界。野兽和匪徒不断渡河向东涌来，他便在哨塔外站岗，协调巡逻，招募旅人守住边境。",al={"瑞尼尔为什么在西泉要塞","瑞尼尔副队长为什么在这里"}},b3def1b5={q="瑞尼尔副队长与谁有关联？",a="瑞尼尔向闪金镇驻军指挥官治安官杜汉汇报。他还与边界另一侧、西部荒野的格里安·斯托曼及人民军合作，指引久经考验的战士西行，支援他们对抗迪菲亚潜行者。",al={"瑞尼尔隶属于谁","瑞尼尔的关系","瑞尼尔向谁汇报"}}},fp="13,195,26.476.0,20.344.0,21.179.0,38.229.0,41.178.0,61.203.0"}
P.entries["npc:devrak"] = {n="迪弗拉克",s="在十字路口，迪弗拉克让部落的驭风者随时待命，往来于卡利姆多各地。这位兽人飞行管理员负责在杜隆塔尔、莫高雷、边境哨站与部落主城之间运送信使和补给。",h="在十字路口，迪弗拉克让部落的驭风者随时待命，往来于卡利姆多各地。这位兽人飞行管理员负责在杜隆塔尔、莫高雷、边境哨站与部落主城之间运送信使和补给。",kw={"贫瘠之地","十字路口","迪弗拉克","飞行管理员","奥格瑞玛","雷霆崖","驭风者","双足飞龙"},ang={["faction:Horde"]="对往来于卡利姆多的部落冒险者而言，迪弗拉克是不可或缺的盟友，也是连接兽人、巨魔和牛头人领地的重要纽带。",["race:Orc"]="在贫瘠之地干旱的腹地，迪弗拉克展现了兽人与卡利姆多驭风者相处的天赋，与这些凶猛的野兽建立羁绊，确保空中优势。"},sec={{t="十字路口兽栏的看守者",b="在十字路口，迪弗拉克照料着驭风者，将部落分散各地的领地连接起来。这座哨站坐落在卡利姆多主要商路的交汇处，暴露在烈日之下，容易遭到野猪人、半人马和联盟斥候的袭击。在这里，迅捷的飞行至关重要。迪弗拉克为经验丰富的旅人和初来乍到的信使安排训练有素的驭风者，载着他们越过草原，抵达莫高雷的群山或杜隆塔尔的岩石峡谷。"},{t="大酋长与酋长的补给",b="迪弗拉克也协助运送来自边境的补给。贫瘠之地的猎人带来肉和毛皮，他则协助将这些物资送往奥格瑞玛的炉灶和雷霆崖的制皮匠手中。他引荐新信使认识各片大陆上的飞行管理员，让通往部落腹地的空中航线保持畅通。"},{t="致命的兽栏",b="迪弗拉克在十字路口的职责不只是照料野兽。当聚落遭到攻击时，他会召来愤怒的双足飞龙，用带毒的尾刺和利爪攻击入侵者。对任何来犯者而言，他的兽栏都是危险的目标。"}},faq={{q="迪弗拉克在十字路口担任什么职务？",a="迪弗拉克是贫瘠之地十字路口的部落飞行管理员。他照料哨站的驭风者，提供通往卡利姆多各处相连聚落的飞行路线，并协调信使、士兵和贸易货物的运输。",al={"迪弗拉克是谁","迪弗拉克做什么","迪弗拉克的职责","十字路口飞行管理员"}},{q="迪弗拉克能送我飞往哪里？",a="从十字路口出发，迪弗拉克可以送你前往奥格瑞玛、雷霆崖等主城，以及灰谷、石爪山脉、尘泥沼泽、千针石林和南部边境的哨站。你必须先与那些地方的飞行管理员交谈。",al={"迪弗拉克飞行路线","从十字路口能飞往哪里","十字路口飞行路线"}},{q="迪弗拉克提供哪些任务？",a="迪弗拉克会派年轻的部落冒险者将鲜肉送给奥格瑞玛的格雷什卡，并将成捆的皮革送往雷霆崖，借此帮助他们熟悉飞行网络。",al={"迪弗拉克的任务","十字路口飞行任务"}},{q="十字路口遭到攻击时，迪弗拉克如何自卫？",a="如果联盟袭击者或充满敌意的野兽进攻十字路口，迪弗拉克就能召来愤怒的双足飞龙协助自己。这些生物会用尖牙和利爪赶走来犯者。",al={"迪弗拉克能战斗吗","击杀迪弗拉克","迪弗拉克的防御"}},{q="十字路口设有飞行管理员为何如此重要？",a="贫瘠之地是连接卡利姆多中部各地的交通命脉。十字路口连接着杜隆塔尔、莫高雷、灰谷和石爪山，而迪弗拉克的兽栏让部落得以迅速调动兵力、协调补给，省去数日的徒步跋涉。",al={"十字路口飞行管理员为何重要","十字路口的地理意义"}},{q="迪弗拉克照料哪些生物？",a="迪弗拉克照料的是驭风者，也叫双足飞龙。这些长着双翼、形似龙类的掠食者栖息在卡利姆多的山峰和台地上，部落与它们结下友谊，依靠它们飞越崎岖地形。",al={"迪弗拉克有哪些坐骑","十字路口坐骑"}}},fp="6,198,31.424.0,43.297.0,14.224.0,40.237.0,24.266.0,30.156.0,61.162.0,60.234.0,34.190.0"}
P.entries["npc:dextren-ward"] = {n="迪克斯特·瓦德",s="暴风城监狱中，迪克斯特·瓦德仍身陷囹圄，四周正发生一场血腥暴动。被捕前，他在暮色森林的乌鸦岭墓地挖掘尸体，卖给死灵法师摩本特·费尔。夜色镇议会已决定将他处死。",h="暴风城监狱中，迪克斯特·瓦德仍身陷囹圄，四周正发生一场血腥暴动。被捕前，他在暮色森林的乌鸦岭墓地挖掘尸体，卖给死灵法师摩本特·费尔。夜色镇议会已决定将他处死。",kw={"议员米尔斯迪普","罪与罚","迪克斯特·瓦德","暮色森林","盗墓贼","摩本特·费尔","乌鸦岭墓地","暴风城","监狱"},ang={["class:Paladin"]="身为圣骑士，你可以将瓦德与死灵法师往来、提供新鲜尸体的行径视为对圣光和死者安息的冒犯。",["class:Priest"]="身为牧师，你可以认为瓦德亵渎乌鸦岭墓地的罪行，需要在道德与灵魂层面得到补偿。",["faction:Alliance"]="身为援助夜色镇的联盟勇士，终结瓦德的罪行，既能为暮色森林遭到亵渎的坟墓讨回公道，也有助于夺回暴动中的监狱。"},sec={{t="暮色森林的盗墓勾当",b="在被锁链囚禁于暴风城地下之前，迪克斯特·瓦德靠在暮色森林盗墓牟利。在悲伤与恐惧日益蔓延的乌鸦岭墓地，他挖出了刚刚下葬的死者。他将尸体卖给当地修习黑暗法术的人。"},{t="死灵法师的爪牙",b="死灵法师摩本特·费尔是瓦德的主要买家，他的仪式荼毒着暮色森林，也让亡灵的队伍不断壮大。瓦德为他提供尸体，助长了夜色镇的恐怖。暴风城当局最终逮捕了瓦德，将他押入监狱。他的罪行让暮色森林的居民要求伸张正义，议员米尔斯迪普则要求拿瓦德的手作为证明。"},{t="监狱中的混乱",b="一场叛乱席卷了监狱，瓦德在混乱中获释，走出了牢房。他手持武器，凶狠残暴，占据了监狱的一角，用恐惧阻止外人靠近。试图恢复秩序的联盟部队将他列为优先铲除的目标之一。"}},faq={{q="迪克斯特·瓦德是谁？",a="迪克斯特·瓦德是关押在暴风城监狱中的一名臭名昭著的罪犯。他曾在暮色森林盗墓，为黑暗仪式提供尸体。",al={"迪克斯特·瓦德是谁","迪克斯特·瓦德背景故事","监狱迪克斯特"}},{q="迪克斯特·瓦德为何被关进监狱？",a="暴风城当局因瓦德在暮色森林的乌鸦岭墓地盗墓而将他逮捕。他挖出刚刚下葬的尸体，卖给死灵法师摩本特·费尔。",al={"他为何被捕","迪克斯特·瓦德的罪行","迪克斯特做了什么"}},{q="谁想要迪克斯特·瓦德死？",a="夜色镇的议员米尔斯迪普想要瓦德死。他要求拿瓦德的手作为证明，为暮色森林遭到亵渎的坟墓讨回公道。",al={"谁想要迪克斯特死","迪克斯特·瓦德悬赏","罪与罚任务发布者"}},{q="瓦德与摩本特·费尔有什么关系？",a="瓦德曾为摩本特·费尔提供尸体。他在乌鸦岭墓地挖出刚刚下葬的死者，供这名死灵法师举行黑暗仪式。",al={"与摩本特·费尔的关系","迪克斯特·瓦德 摩本特·费尔","谁买走了尸体"}},{q="在哪里能找到迪克斯特·瓦德？",a="迪克斯特·瓦德就在暴风城监狱内，这座监狱位于暴风城的运河区。眼下叛乱仍在持续，他就在其中一处囚禁区内。",al={"迪克斯特·瓦德位置","迪克斯特·瓦德在哪里","哪里能找到迪克斯特"}},{q="任务为何要求带回迪克斯特的手？",a="议员米尔斯迪普要求带回瓦德死后的手，以此证明这个盗墓贼再也无法挖掘暮色森林的坟墓，也无法靠死灵法术牟利。",al={"为何砍下他的手","迪克斯特·瓦德的手","迪克斯特死亡证明"}}},fp="12,253,25.206.0,23.378.0,21.274.0,20.133.0,36.166.0,28.127.0,41.128.0,32.147.0,42.143.0"}
P.entries["npc:dirania-silvershine"] = {n="迪兰妮亚·月光",s="在幽影谷，迪兰妮亚·月光守望着林地，也为埃沃隆忧心。她忠诚而细心，总在同伴因鲁莽冒险而陷入险境时照看着他。",h="在幽影谷，迪兰妮亚·月光守望着林地，也为埃沃隆忧心。她忠诚而细心，总在同伴因鲁莽冒险而陷入险境时照看着他。",kw={"解毒剂","迪兰妮亚","埃沃隆","幽影谷","月光","泰达希尔","树林"},ang={["race:NightElf"]="作为一名初入幽影谷的年轻暗夜精灵，你可以从迪兰妮亚身上看到友谊的分量，也能看到危险如何侵入世界之树最新的庇护之地。"},sec={{t="幽影谷的守望者",b="迪兰妮亚守望着幽影谷，这片静谧的山谷坐落在泰达希尔的枝叶之下。年轻的暗夜精灵在这里开始为卡利姆多和联盟效力。其他人在兽穴和圣所中承担着更广泛的灵性职责，迪兰妮亚则将心思放在身边的人身上。即使在泰达希尔的腹地，危险也在悄然滋生。"},{t="好友遇险",b="迪兰妮亚最牵挂的是她的同伴埃沃隆。他性急莽撞，面对谷中出没的毒物也疏于防范，因此常常惹上麻烦。当一只树林蜘蛛的毒牙让他倒下时，迪兰妮亚寻求热心人的帮助，收集材料配制解药，以免毒液造成长久的伤害。"}},faq={{q="迪兰妮亚·月光是谁？",a="迪兰妮亚·月光是一名暗夜精灵，住在泰达希尔的幽影谷。埃沃隆因有毒的野生生物而陷入险境后，她请求他人帮忙营救并医治他。",al={"迪兰妮亚","迪兰妮亚是谁","迪兰妮亚·月光背景故事"}},{q="在哪里可以找到迪兰妮亚·月光？",a="你可以在泰达希尔的新手山谷幽影谷找到迪兰妮亚，她就在奥达希尔旁的中央道路附近。",al={"迪兰妮亚位置","迪兰妮亚在哪里","寻找迪兰妮亚·月光"}},{q="迪兰妮亚和埃沃隆是什么关系？",a="迪兰妮亚和埃沃隆是亲密的朋友。她照看着他，当他因粗心大意而被当地生物咬伤中毒时，她便设法为他准备解毒剂。",al={"迪兰妮亚与埃沃隆有关系吗","埃沃隆与迪兰妮亚","迪兰妮亚的朋友"}},{q="迪兰妮亚提供哪些任务？",a="迪兰妮亚请求旅人帮助她的同伴，其中包括收集材料，配制解药来清除埃沃隆体内的蜘蛛毒液。她的请求包括“需要帮助的朋友”和“埃沃隆的解药”。",al={"迪兰妮亚任务","迪兰妮亚·月光提供的任务","埃沃隆任务"}},{q="迪兰妮亚为什么担心幽影谷的蜘蛛？",a="幽影谷枝叶间的树林蜘蛛身带剧毒。像埃沃隆这样初出茅庐的精灵往往低估了被它们咬伤的危险，不过经验丰富的哨兵能够应付这些蜘蛛。",al={"幽影谷蜘蛛","泰达希尔为什么有蜘蛛","树林蜘蛛危险"}},{q="迪兰妮亚属于任何正式的组织或阵营吗？",a="迪兰妮亚是一名居住在泰达希尔的联盟暗夜精灵。她并未以艾露恩姐妹会或塞纳里奥议会活跃成员的身份出现，而是一位关心同胞的平民。",al={"迪兰妮亚阵营","迪兰妮亚是德鲁伊吗","迪兰妮亚是哨兵吗"}}},fx={f156932e={q="迪兰妮亚·月光想要什么？",a="迪兰妮亚急切地想为好友埃沃隆寻求帮助。他前往幽影谷后遭到当地的网木蜘蛛严重毒伤，已经无法行动。她需要有人尽快在林间空地各处收集所需材料，配制解毒剂，救他一命。",al={"迪兰妮亚·月光的目标","迪兰妮亚需要什么","迪兰妮亚·月光想要什么"}},e30a1bf8={q="迪兰妮亚·月光为什么在这里？",a="迪兰妮亚住在幽影谷，与其他暗夜精灵一同栖居在奥达希尔遮蔽的枝干间。好友埃沃隆在附近中了蜘蛛毒后，她便焦急地留守此地，等待有能力的旅人前来相助。",al={"迪兰妮亚为何在幽影谷","迪兰妮亚·月光在此的原因","迪兰妮亚为何在这里"}}},fp="19,184,23.330.0,16.314.0,27.154.0,37.108.0,42.154.0,31.184.0,51.184.0,51.183.0"}
P.entries["npc:dirge-quikcleave"] = {n="迪尔格·奎克里弗",s="在加基森的旅店里，迪尔格·奎克里弗以地精烹饪大师和商人的身份坐镇。他的创意菜肴闻名艾泽拉斯，经验丰富的厨师也来向他求教，掌握大师级烹饪技艺。",h="在加基森的旅店里，迪尔格·奎克里弗以地精烹饪大师和商人的身份坐镇。他的创意菜肴闻名艾泽拉斯，经验丰富的厨师也来向他求教，掌握大师级烹饪技艺。",kw={"大师级烹饪","蚌肉大餐","烹饪训练师","迪尔格·奎克里弗","加基森","地精厨师","塔纳利斯"},ang={["profession:Cooking"]="身为胸怀抱负的厨师，你可以向迪尔格·奎克里弗求教大师级烹饪技艺。他会用招牌蚌肉蛋饼食谱考验你的手艺，然后才授予你大师资格。",["race:Orc"]="身为立志品遍美食的部落成员，你会由奥格瑞玛的训练师直接派往塔纳利斯沙漠，向迪尔格求教烹饪技艺。"},sec={{t="锋利的切肉刀大师",b="在尘土飞扬的加基森，迪尔格·奎克里弗为穿越塔纳利斯沙漠、口干舌燥的旅人供应酒水和肉食。虽然他的厨房设在边陲酒馆里，他却自称是艾泽拉斯在世最伟大的烹饪艺术家。城里的烹饪训练师教完常规课程后，会将最有潜力的学生送到他这里。迪尔格的食谱要求严苛，用料也非同寻常，从制作蚌肉大餐菜肴所需的巨型蚌肉和蛋，到遥远海岸的珍奇野兽，不一而足。"},{t="异域风味与隐秘交易",b="迪尔格·奎克里弗既有美食家的豪气，也有地精的生意头脑。他与卡利姆多各地的奇人异士保持联系，寻觅危险的烹饪冒险。那些带来凶猛野兽肉块的人，例如菲拉斯恐怖之岛上庞大的奇美洛克的肉，可以获得丰盛菜肴的食谱，让勇士在险途中有充足的体力。他们可不能过多打听迪尔格的私下交易。"}},faq={{q="迪尔格·奎克里弗是谁？",a="迪尔格·奎克里弗是地精厨师兼补给商，待在塔纳利斯加基森的旅店里。他被誉为艾泽拉斯最出色的烹饪行家之一，教导有志于烹饪的人磨炼手艺，迈向大师级境界。",al={"迪尔格·奎克里弗背景故事","迪尔格是谁","加基森厨师"}},{q="在哪里能找到迪尔格·奎克里弗？",a="迪尔格·奎克里弗就在加基森的酒馆里，这座热砂港旗下的新兴城镇坐落于塔纳利斯北部的沙丘间。",al={"迪尔格位置","迪尔格·奎克里弗在哪里","迪尔格旅店"}},{q="烹饪训练师为什么会把冒险者送到他那里？",a="各大主城的烹饪训练师能传授给学徒的本领终究有限。当厨师达到专家级门槛时，他们便会通过“加基森之旅!”任务，将其送往加基森的迪尔格那里，证明自己的本领，解锁大师级烹饪。",al={"为什么拜访迪尔格","大师级烹饪任务","加基森之旅"}},{q="迪尔格以哪些菜肴闻名？",a="迪尔格·奎克里弗的拿手菜包括蚌肉大餐，一道用巨型蚌肉和蛋制成的咸香蛋饼，还有丰盛的狼肉排，以及滋味浓烈的迪尔格的超美味奇美拉肉片。",al={"迪尔格食谱","蚌肉大餐","迪尔格做什么菜"}}},fp="16,212,21.433.0,31.426.0,24.200.0,36.126.0,48.238.0,32.169.0"}
P.entries["npc:doan-karhan"] = {n="杜安·卡汉",s="在南贫瘠之地，杜安·卡汉研究着燃烧军团的恶魔神器。他是一名人类学者，也修习黑暗法术，为了潜心研究而独居于此，尤其醉心于神秘的索兰鲁克宝珠。",h="在南贫瘠之地，杜安·卡汉研究着燃烧军团的恶魔神器。他是一名人类学者，也修习黑暗法术，为了潜心研究而独居于此，尤其醉心于神秘的索兰鲁克宝珠。",kw={"贫瘠之地","杜安·卡汉","索兰鲁克宝珠","扎尔盖的宝珠","术士"},ang={["class:Warlock"]="身为经验丰富的术士，你可以向杜安·卡汉求取奥秘知识，探寻、修复并驾驭传说中的恶魔宝珠。",["faction:Alliance"]="杜安·卡汉虽然是人类，却远离暴风城和塞拉摩，宁愿在卡利姆多腹地孤独地自我放逐，也不愿受到Grand Alliance的约束。"},sec={{t="贫瘠之地的隐士",b="杜安·卡汉独自在南贫瘠之地扎营，远离联盟的文明堡垒。他隐居荒野，以便不受干扰地研究危险的恶魔遗物。他深谙强大邪能容器的奥秘，持有扎尔甘宝珠，并痴迷于传说中的索兰鲁克宝珠。寻求神器制作与黑暗仪式知识的术士常来拜访他。"}},faq={{q="杜安·卡汉在哪里？",a="杜安·卡汉在南贫瘠之地扎营，位于陶拉祖营地和主路以东。他独自住在一小片很容易被忽略的空地上。",al={"杜安·卡汉位置","杜安·卡汉在哪","杜安·卡汉南贫瘠之地"}},{q="为什么一个人类会独居在贫瘠之地？",a="杜安·卡汉选择自我放逐到危机四伏的荒野，研究燃烧军团的魔法遗物。在联盟的文明疆域，这类对恶魔宝珠的研究要么被禁止，要么受到严密审查。",al={"杜安为何在此","贫瘠之地为何有人类","杜安·卡汉背景故事"}},{q="索兰鲁克宝珠是什么？",a="索兰鲁克宝珠是一件古老而强大的燃烧军团遗物，其中蕴含着黑暗力量。杜安·卡汉深谙它与类似的扎尔盖恩宝珠的构造，并指引那些试图重铸它的术士。",al={"索兰鲁克宝珠","索兰鲁克宝珠是什么"}}},fp="11,215,25.406.0,29.148.0,43.171.0,29.208.0"}
P.entries["npc:doctor-gregory-victor"] = {n="格里高利·维克托医生",s="格里高利·维克托医生是一名被遗忘者外科医生，驻扎在阿拉希高地的部落前哨落锤镇。他被誉为部落首屈一指的创伤医师，负责考核那些希望掌握高级伤员分诊和战场急救的医者。在当地激烈的冲突中，他以冷静而高效的医术为前线战士缝合伤口。",h="格里高利·维克托医生是一名被遗忘者外科医生，驻扎在阿拉希高地的部落前哨落锤镇。他被誉为部落首屈一指的创伤医师，负责考核那些希望掌握高级伤员分诊和战场急救的医者。在当地激烈的冲突中，他以冷静而高效的医术为前线战士缝合伤口。",kw={"阿拉希高地","格里高利·维克托医生","急救","格里高利·维克托","落锤镇","部落创伤救治","外科医生","伤员分诊"},ang={["faction:Horde"]="Doctor Victor在部落处境最为险峻的前哨之一提供至关重要的战场医疗，确保阿拉希前线的战士恢复战斗能力。",["race:Undead"]="与皇家药剂师学会调制的有毒药剂不同，Doctor Victor展现了被遗忘者对常规凡人解剖学和修复外科医术的精通。"},sec={{t="落锤镇的外科医生",b="尽管许多人对被遗忘者药剂师心存疑虑，格里高利·维克托医生却以实用的战场外科医术为部落效力，而非散播瘟疫的炼金术。他驻扎在纷争不断的阿拉希高地深处的落锤镇，为遭受辛迪加强盗、石拳食人魔和联盟部队重创的士兵施行手术。他的医疗站也是部落战地医者的主要试炼场，要求他们在巨大压力下果断高效地救治伤员，并优先处理危重病患。"}},faq={{q="格里高利·维克托医生是谁？",a="格里高利·维克托医生是一名被遗忘者医师，驻扎在阿拉希高地的落锤镇。他是部落的创伤外科大师，负责监督伤员分诊工作，并指导高级战地医者。",al={"维克托医生","格里高利·维克托","格里高利·维克托是谁"}},{q="在哪里可以找到格里高利·维克托医生？",a="他位于阿拉希高地东北部的落锤镇要塞内。",al={"格里高利·维克托位置","维克托在哪","维克托医生在哪"}},{q="他在部落中担任何种职责？",a="维克托医生通过严格的考试，考核有潜力的战地医者在战场上分诊救治伤员的能力，教导他们如何稳定垂死伤员的状况，并制作供前线作战使用的高级布质绷带。",al={"格里高利·维克托做什么","格里高利·维克托急救","部落创伤医生"}},{q="联盟中与他职责相当的是谁？",a="古斯塔夫·范沃森医生驻扎在尘泥沼泽的塞拉摩岛，负责联盟的高级创伤救治和伤员分诊训练。",al={"联盟对应的维克托医生","联盟伤员分诊医生"}}},fx={d46fa605={q="格里高利·维克托医生站在哪一边？",a="格里高利·维克托医生忠于部落和被遗忘者。他驻扎在阿拉希高地的落锤镇，是一位经验丰富的外科医生，负责救治本阵营的伤员，并向愿意学习的人传授先进的战地急救知识。",al={"格里高利·维克托医生属于什么阵营","维克托医生是部落成员吗","维克托医生的效忠对象"}},["5e053b25"]={q="格里高利·维克托医生想要什么？",a="维克托医生致力于战地医疗和外科手术。他需要能够在高压环境下处理伤员分诊的战地医护人员，并通过考核有志成为治疗者的人，确保他们能合理安排治疗顺序，在战争混乱中挽救生命。",al={"维克托医生想要什么","格里高利·维克托医生的目标","维克托在做什么"}},["3e1305a9"]={q="格里高利·维克托医生为什么在这里？",a="维克托医生驻扎在落锤镇，支援部落在争夺激烈的阿拉希高地的前线。联盟的袭击和当地威胁不断涌现，因此需要一位经验丰富的创伤外科医生来保障士兵的性命。",al={"格里高利·维克托为何在这里","维克托医生为何在落锤镇","维克托在此的原因"}}},fp="21,220,21.420.0,29.178.0,39.87.0,37.159.0,32.139.0"}
P.entries["npc:doctor-gustaf-vanhowzen"] = {n="古斯塔夫·范沃森医生",s="古斯塔夫·范沃森医生在塞拉摩堡垒主持塞拉摩的医疗工作。他训练治疗者，并考核资深医护人员的战地分诊和绷带包扎技能。",h="古斯塔夫·范沃森医生在塞拉摩堡垒主持塞拉摩的医疗工作。他训练治疗者，并考核资深医护人员的战地分诊和绷带包扎技能。",kw={"联盟外科医疗队","大师级急救","急救","塞拉摩堡垒","古斯塔夫·范沃森","塞拉摩","分诊","范沃森"},ang={["faction:Alliance"]="身为联盟医护人员，前往塞拉摩，在范沃森医生的严密监督下证明你的分诊本领，掌握战地外科技能。"},sec={{t="塞拉摩的首席医师",b="古斯塔夫·范沃森医生在塞拉摩堡垒的一层救治吉安娜·普罗德摩尔的部队，并训练塞拉摩的前线治疗者。尘泥沼泽让他们的工作格外艰苦，因此范沃森要求他们在压力之下也能熟练施救。经验丰富的医护人员要接受他严格的分诊考核，判断哪些伤势需要优先处理。"}},faq={{q="在哪里可以找到古斯塔夫·范沃森医生？",a="范沃森医生在塞拉摩堡垒的一层工作，这座堡垒是尘泥沼泽的塞拉摩岛上的主要要塞。",al={"范沃森位置","古斯塔夫·范沃森在哪里","古斯塔夫·范沃森地点"}},{q="范沃森为联盟担任什么职务？",a="范沃森医生是联盟外科医疗队的首席医师，也是塞拉摩首屈一指的创伤外科医师。他管理驻军的医疗病房，并向经验丰富的联盟战地医护人员传授专家级 急救。",al={"范沃森做什么","范沃森职责","范沃森医生是谁"}},{q="范沃森医生会教玩家什么？",a="范沃森医生主持专家级急救的分诊考核，让技艺娴熟的医护人员得以提升技能上限。他还会教符合条件的医护人员制作厚魔纹绷带和符文布绷带。",al={"范沃森能教什么","范沃森训练","范沃森急救教学"}},{q="部落有与范沃森医生职责相当的人吗？",a="有。格里高利·维克托医生是部落的创伤救治专家。他在阿拉希高地的落锤镇训练战地医护人员，并主持分诊考核。",al={"部落分诊训练师","部落对应范沃森的人","部落急救大师是谁"}}},fx={["5f514c39"]={q="古斯塔夫·范沃森医生是谁？",a="古斯塔夫·范沃森医生是联盟外科医疗队的首席医师，也是一位驻扎在塞拉摩岛的创伤外科大师。他的战地医术在联盟中声名远扬，负责监督塞拉摩治疗者的训练，并向战地医师传授高阶伤员救治技术。",al={"范沃森是谁","古斯塔夫·范沃森","古斯塔夫·范沃森医生是谁"}},d768860b={q="古斯塔夫·范沃森医生效忠哪一方？",a="范沃森医生对联盟忠心耿耿。他领导着名为联盟外科医疗队的医疗部队，在吉安娜·普罗德摩尔的旗帜下效力，以严谨的战地医疗救治士兵和前线冒险者，保住他们的性命。",al={"范沃森的阵营","范沃森属于联盟吗","古斯塔夫·范沃森医生效忠谁"}},c346cbcd={q="古斯塔夫·范沃森医生想要什么？",a="范沃森医生希望联盟各支部队都能维持最高水准的创伤救治。在战场上，犹豫就会让人丧命，因此他要考验有能力的战地医师，并传授伤员救治方法，让他们能在极端压力下应对重伤的战士。",al={"范沃森想要什么","范沃森的动机","范沃森医生的目标"}},["12e0bbc2"]={q="古斯塔夫·范沃森医生为什么在这里？",a="范沃森医生驻扎在塞拉摩岛的塞拉摩堡垒，照料这座军事要塞的伤员，并训练当地驻军的治疗者。他在这里考验那些游历卡利姆多、精通急救并有志于创伤救治的医师。",al={"范沃森为什么在塞拉摩","范沃森医生为什么在这里","范沃森在哪里工作"}},["9903e76f"]={q="古斯塔夫·范沃森医生与谁有联系？",a="范沃森医生为塞拉摩岛的联盟驻军服务，隶属于吉安娜·普罗德摩尔在当地的部队。他直接与联盟军中的治疗者协作，并指挥联盟外科医疗队医疗部门。",al={"范沃森的所属组织","范沃森为谁效力","古斯塔夫·范沃森医生的关系"}}},fp="23,158,28.326.0,43.120.0,48.209.0,41.200.0,54.157.0"}
P.entries["npc:donova-snowden"] = {n="多诺瓦·雪山",s="多诺瓦·雪山是一位无畏的矮人研究员，在冬泉谷冰火温泉附近的温热泉水旁扎营。尽管严寒刺骨，野生动物凶猛，她仍在研究当地奇异的地热活动，并监视腐化日益加深的冬泉熊怪。",h="多诺瓦·雪山是一位无畏的矮人研究员，在冬泉谷冰火温泉附近的温热泉水旁扎营。尽管严寒刺骨，野生动物凶猛，她仍在研究当地奇异的地热活动，并监视腐化日益加深的冬泉熊怪。",kw={"多诺瓦·雪山","火酒","冰火温泉","熊怪","研究员","冬泉","冬泉谷"},ang={["faction:Horde"]="尽管出身矮人，多诺瓦仍愿意放下阵营之别，招募能干的斥候，对抗冬泉谷的野兽和被腐化的熊怪。",["race:Dwarf"]="遇见一位独自勇闯冰封群峰的矮人同胞，让人倍感亲切，也展现了矮人对实地考察与探索经久不衰的热情，即使远离卡兹莫丹也不例外。"},sec={{t="雪地中的孤独研究员",b="大多数旅人都选择留在安全的永望镇，多诺瓦·雪山却选择在冰火温泉附近的冰冷荒野中扎营。她每天都在调查从永久冻土中涌出的奇异地热现象，以及逐渐侵蚀冬泉谷本土野生动物的黑暗力量。她务实而坚定，招募路过的联盟和部落冒险者收集样本，协助遏制当地的威胁。"},{t="调查冬泉熊怪",b="多诺瓦将大部分精力放在冬泉熊怪身上，它们的行为已变得反复无常，充满攻击性。她调查冬泉火酒之类的烈性配制饮品，以及在各部族间流传的奇异有毒物质，试图找出它们突然陷入疯狂的根源。对于想要了解北方群山间蔓延的腐化的人来说，她的实地研究使她成为一位关键的知情者。"}},faq={{q="在哪里可以找到多诺瓦·雪山？",a="多诺瓦·雪山在冬泉谷冰火温泉西南方的一处小温泉旁扎营，隔着主路与冰火温泉相望。",al={"多诺瓦·雪山位置","多诺瓦在哪","多诺瓦·雪山地图"}},{q="多诺瓦为什么待在这片严寒的荒野中？",a="她正在对冬泉谷不同寻常的温泉开展环境研究，并调查侵染当地冬泉熊怪部族的腐化。",al={"多诺瓦为什么在冬泉谷","多诺瓦·雪山的目的"}},{q="多诺瓦会与部落玩家合作吗？",a="会。虽然多诺瓦是矮人，但她以独立研究员的身份行事，向联盟和部落的冒险者都提供任务。",al={"多诺瓦仅限联盟吗","部落能和多诺瓦交谈吗","多诺瓦·雪山阵营"}},{q="多诺瓦正在调查冬泉熊怪的什么问题？",a="她正在研究令冬泉部族陷入疯狂的神秘腐化，尤其关注冬泉火酒之类的奇异配制饮品，以及在它们的信使身上发现的污秽有毒物质。",al={"多诺瓦熊怪任务","冬泉火酒研究"}}},fp="14,202,29.367.0,28.370.1,32.121.0,44.137.0,36.119.0,63.195.0"}
P.entries["npc:donyal-tovald"] = {n="丹亚·托瓦尔德",s="在暴风要塞，丹亚·托瓦尔德负责照管皇家图书馆的历史典籍。年轻的安度因·乌瑞恩国王资助他保存和抄录书籍，供更多民众阅览。",h="在暴风要塞，丹亚·托瓦尔德负责照管皇家图书馆的历史典籍。年轻的安度因·乌瑞恩国王资助他保存和抄录书籍，供更多民众阅览。",kw={"安度因·乌瑞恩国王","书籍","丹亚·托瓦尔德","历史","图书管理员","皇家图书馆","暴风要塞"},ang={["class:Mage"]="作为一名造访暴风要塞的法师，你或许会重视托瓦尔德对文字知识的悉心保存。这些文献主要记载历史，而非奥术知识。",["race:Human"]="作为暴风城的人类，你将托瓦尔德的工作视为在第一次兽人战争与首都重建之后，保存并重建自身文化与历史记载的一部分。"},sec={{t="暴风城历史的守护者",b="丹亚·托瓦尔德负责照管暴风要塞内的皇家图书馆。馆内的历史记载、卷轴和学术典籍主要供贵族与王室宫廷使用。年轻的安度因·乌瑞恩国王资助了一项计划，要让普通市民也能分享这些知识。因此，托瓦尔德保存并抄录这些文献，在王国政局动荡之际，让联盟的教训与辉煌得以留存。"}},faq={{q="丹亚·托瓦尔德是谁？",a="丹亚·托瓦尔德负责照管暴风要塞内的皇家图书馆。他保管王国的档案，并负责安度因·乌瑞恩国王向公众提供历史书籍抄本的计划。",al={"托瓦尔德是谁","王室图书管理员","丹亚·托瓦尔德背景故事"}},{q="在哪里可以找到丹亚·托瓦尔德？",a="你可以在暴风要塞东侧的皇家图书馆翼区找到丹亚·托瓦尔德，他就在书架和历史卷轴之间。",al={"丹亚·托瓦尔德位置","托瓦尔德在哪里","如何找到托瓦尔德"}},{q="他为什么向市民分发书籍？",a="年轻的安度因·乌瑞恩国王资助了一项向公众传播知识的王室计划。丹亚·托瓦尔德负责王室手稿的抄录与分发。",al={"安度因图书计划","暴风城图书馆计划","他为什么分发书籍"}},{q="他隶属于贵族或神职人员吗？",a="托瓦尔德在暴风要塞担任王室档案保管员，直接为王室效力。他专注于历史与学术文献，而非宗教或政治教义。",al={"托瓦尔德属于圣光教会吗","托瓦尔德阵营"}}},fx={["18ed48d6"]={q="丹亚·托瓦尔德效忠哪一方？",a="托瓦尔德是暴风城王国和联盟的忠诚仆从。他就在暴风要塞内任职，听命于王室行政机构，并直接支持年轻的安度因·乌瑞恩国王所倡导的教育事业。",al={"丹亚·托瓦尔德效忠谁","丹亚·托瓦尔德的阵营","丹亚为谁效力"}},["6c9214b5"]={q="丹亚·托瓦尔德想要什么？",a="托瓦尔德希望保存王国的历史，并让民众学会读写。他照管皇家图书馆中的档案，并致力于将用于教育的抄本送到暴风城各处的普通民众手中。",al={"丹亚·托瓦尔德的目标","丹亚想做什么","丹亚·托瓦尔德的目的"}},["715728b5"]={q="丹亚·托瓦尔德为什么在皇家图书馆？",a="托瓦尔德在暴风要塞的皇家图书馆区域担任管理员之一。在这个岗位上，他守护着王国积累的知识，并管理经王室批准的书籍发放事宜。",al={"丹亚·托瓦尔德为什么在暴风要塞","丹亚·托瓦尔德的图书馆职责","丹亚为什么在这里"}}},fp="13,169,30.390.0,21.189.0,31.133.0,40.159.0,56.179.0"}
P.entries["npc:doomsayer-wiserunner"] = {n="先知奥萨迪·智慧行者",s="在血蹄村西北方的洞穴中，先知奥萨迪·智慧行者引导年轻的牛头人完成神圣的仪式。这位受人敬重的长者帮助他们在莫高雷寻求灵性的智慧。",h="在血蹄村西北方的洞穴中，先知奥萨迪·智慧行者引导年轻的牛头人完成神圣的仪式。这位受人敬重的长者帮助他们在莫高雷寻求灵性的智慧。",kw={"纳拉其营地","末日预言者 先知奥萨迪·智慧行者","莫高雷","幻象仪祭","智慧仪祭","先知奥萨迪·智慧行者","牛头人长者"},ang={["class:Shaman"]="身为萨满祭司，你能看出先知奥萨迪·智慧行者是一位古老传统的守护者，能够领会交织于大地与天空之间的讯息。",["race:Tauren"]="作为一名走出红云台地的年轻shu'halo，你可以向先知奥萨迪·智慧行者寻求指引，踏上遵循先祖足迹、走向灵性成熟的旅程。"},sec={{t="神圣之路的引路人",b="先知奥萨迪·智慧行者引导年轻的牛头人完成祖传的仪式。在经历最初的力量与幻象试炼后，他们会向他寻求指引。他解读来自大地母亲的幻象，并教导他们如何敬奉先祖。他的智慧帮助莫高雷各处分散的游牧部族凝聚为一个群体。"}},faq={{q="先知奥萨迪·智慧行者是谁？",a="先知奥萨迪·智慧行者是一位受人敬重的牛头人长者，负责引导年轻的入门者完成神圣的大地之母仪祭。",al={"先知奥萨迪·智慧行者是谁","先知奥萨迪·智慧行者","先知奥萨迪·智慧行者 牛头人长者"}},{q="他在莫高雷担任什么角色？",a="先知奥萨迪·智慧行者指导年轻的牛头人。在他们完成早期的幻象仪式后，他会接待前来进行智慧仪祭的勇士，考验他们是否已准备好为部族和大地母亲效力。",al={"先知奥萨迪·智慧行者做什么","先知奥萨迪·智慧行者的职责","先知奥萨迪·智慧行者的角色"}},{q="在哪里可以找到先知奥萨迪·智慧行者？",a="先知奥萨迪·智慧行者位于血蹄村西北方丘陵中的一处洞穴。幻象仪祭中的幻象会引导年轻的牛头人来到这里，而他会派他们前往雷霆崖以东的赤色石，拜访那里的先祖之灵。",al={"先知奥萨迪·智慧行者在哪里","先知奥萨迪·智慧行者的位置","先知奥萨迪·智慧行者的坐标"}}},fp="15,166,26.302.0,23.115.0,34.187.0,35.223.0"}
P.entries["npc:doras"] = {n="多拉斯",s="在奥格瑞玛上方，多拉斯指挥着部落的驭风者飞往卡利姆多各地。他照管着这座都城的双足飞龙，送信使、斥候和旅人踏上旅途。",h="在奥格瑞玛上方，多拉斯指挥着部落的驭风者飞往卡利姆多各地。他照管着这座都城的双足飞龙，送信使、斥候和旅人踏上旅途。",kw={"多拉斯","飞行管理员","奥格瑞玛","力量谷","驭风者管理员","双足飞龙"},ang={["faction:Horde"]="身为部落冒险者，你可以依靠多拉斯，从都城迅速飞往卡利姆多各地的盟友定居点。"},sec={{t="空中航路的掌管者",b="多拉斯在力量谷上方的木制平台上照料驭风者。部落在杜隆塔尔定居后，这些聪慧、长着皮翼的野兽便成了部落在卡利姆多各地通信和出行的主要依靠。多拉斯为骑手安排休息妥当的坐骑，确保重要消息和援军抵达遥远的哨站。它们的航线通往十字路口、雷霆崖，以及灰谷或尘泥沼泽深处的定居点。"}},faq={{q="在哪里可以找到多拉斯？",a="多拉斯在俯瞰奥格瑞玛力量谷的飞行塔顶等候。沿着城门附近中央木制建筑的蜿蜒坡道向上，就能到达他的飞龙栖息处。",al={"多拉斯位置","奥格瑞玛飞行管理员在哪","奥格瑞玛双足飞龙管理员"}},{q="多拉斯训练什么生物？",a="多拉斯管理着驭风者，也称双足飞龙。这些聪慧、带毒的有翼掠食者原本栖息在卡利姆多干旱的峭壁和草原上，后来与部落结为伙伴，载着骑手长途飞行。",al={"奥格瑞玛坐骑","多拉斯用什么飞行","驭风者是什么"}},{q="多拉斯能送旅人去哪里？",a="多拉斯将旅人从奥格瑞玛送往卡利姆多中部和北部的部落哨站。其中包括贫瘠之地的十字路口、莫高雷的雷霆崖，以及灰谷和更远地方的军营。",al={"多拉斯飞行路线","奥格瑞玛能飞到哪","奥格瑞玛飞行路线"}}},fp="5,152,20.432.0,23.178.0,32.197.0,31.208.0"}
P.entries["npc:doren"] = {n="Doren",s="多伦上尉统领着隐于荆棘谷北部的反抗军营地。多伦曾是库尔森上校麾下的军官，在上司和远征军同袍陷入疯狂后，他率众发动了兵变。如今，他指挥着一支游击抵抗军，决心查明这场疯病的根源，并除掉库尔森。",h="多伦上尉统领着隐于荆棘谷北部的反抗军营地。多伦曾是库尔森上校麾下的军官，在上司和远征军同袍陷入疯狂后，他率众发动了兵变。如今，他指挥着一支游击抵抗军，决心查明这场疯病的根源，并除掉库尔森。",kw={"书呆子 赫洛德","库尔森上校","多伦","库尔森","库尔森的营地","多伦上尉","反抗军营地","荆棘谷","索尔森"},ang={["faction:Alliance"]="对联盟士兵而言，多伦体现了暴风城丛林远征所酿成的悲剧，也为他们提供了纠正库尔森的恶行、让荒蛮边疆重归秩序的机会。",["race:Human"]="人类旅者会认出多伦身上的军人风范，这也提醒着他们，远离暴风城王国、孤立无援地执行任务，会给心智和士气带来怎样的损耗。"},sec={{t="丛林中的兵变",b="多伦上尉最初打着暴风城的旗号，在库尔森上校的指挥下远征荆棘谷。这次远征本是为了在荒蛮的南方丛林建立据点，但随着库尔森和他的亲信陷入反复无常、残暴嗜杀的疯狂，局势迅速恶化。多伦和一批忠诚的将士不愿舍弃理智与荣誉，脱离了队伍。他们逃往北方，在道路旁开辟了反抗军营地，宁可叛逃，也不愿侍奉一个疯子。"},{t="追寻真相",b="多伦在这处岌岌可危的前哨指挥针对库尔森的营地的行动。他与中立势力维持补给往来，其中包括南方藏宝海湾的克拉兹克等地精联络人，以便让日渐减员的部队有粮可食、有武器可用。除了维持生存，多伦还在寻找答案：他派遣列兵索尔森等密探深入敌后，查明究竟是什么诅咒了上校，并揪出书呆子赫洛德这样的叛徒和帮凶。多伦始终相信，要保住远征军仅存的荣誉，唯有亲手终结库尔森。"}},faq={{q="多伦上尉是谁？",a="多伦上尉是荆棘谷北部反抗军营地的领袖。多伦曾在暴风城派出的远征军中担任库尔森上校的副手，上校发疯后，他带领一批不愿继续追随上校的士兵脱离了队伍。",al={"多伦是谁","多伦的故事","反抗军营地领袖"}},{q="为什么多伦被视为反叛者？",a="多伦和他的部队发动兵变，反抗他们的指挥官库尔森上校。库尔森是正式任命的远征军统帅，因此，脱离队伍并举兵反抗他的行为，在名义上使多伦及其追随者成了反叛者，尽管他们叛逃是为了保全理智、反抗库尔森的暴政。",al={"为什么叫反抗军营地","多伦为何反叛","库尔森兵变"}},{q="是什么让库尔森上校陷入疯狂？",a="让库尔森及其亲信陷入疯狂的确切根源仍是个谜，多伦一直在努力查明真相。多伦通过侦察和潜入行动，调查究竟是什么在丛林深处腐化了他昔日的指挥官。",al={"库尔森为何发疯","库尔森的疯狂"}},{q="多伦如何为反抗军营地维持补给？",a="失去暴风城的官方支援后，多伦依靠秘密运输和与第三方的贸易安排获取补给。其中，他会与南方海盗港口藏宝海湾的克拉兹克等地精商人协调，为部队提供装备。",al={"反抗军营地补给","多伦的补给"}},{q="书呆子赫洛德是谁，他与多伦有什么关系？",a="书呆子赫洛德是库尔森部队中的一名同伙。多伦怀疑，列兵索尔森潜入营地期间，赫洛德曾参与揭穿这名卧底特工对多伦的忠诚。",al={"书呆子 赫洛德","赫洛德反抗军营地"}},{q="多伦听命于暴风城吗？",a="多伦仍然忠于联盟的理念，但由于他在战场上脱离队伍、反抗指挥官，如今他独立行动。他欢迎联盟冒险者前来，协助收拾这场灾难性远征留下的残局。",al={"多伦联盟","多伦对暴风城的效忠"}}},fp="5,161,22.398.0,20.383.1,24.192.0,32.278.0,30.173.0,44.175.0,56.153.0,31.188.0"}
P.entries["npc:dorn-plainstalker"] = {n="多恩·平原行者",s="多恩·平原行者是一位独居的牛头人长者，住在俯瞰千针石林峡谷的老屋。他主持传统的成年试炼，考验部落冒险者的品格与毅力。通过信仰、耐力、力量和学识的试炼，他检验旅人是否有资格为大地母亲和自己的族人效力。",h="多恩·平原行者是一位独居的牛头人长者，住在俯瞰千针石林峡谷的老屋。他主持传统的成年试炼，考验部落冒险者的品格与毅力。通过信仰、耐力、力量和学识的试炼，他检验旅人是否有资格为大地母亲和自己的族人效力。",kw={"多恩·平原行者","乱风岗","牛头人试炼","耐力的试炼","信仰的试炼","知识试炼","力量试炼","千针石林","老屋"},ang={["faction:Horde"]="多恩欢迎所有愿意勇敢接受试炼的部落勇士，让各个种族的战士、猎人和萨满祭司都能在卡利姆多崎岖的荒野中证明自己的勇毅。",["race:Tauren"]="对于游历千针石林的牛头人而言，多恩延续着祖先的游牧传统与精神仪式，考验一个人与Earth Mother之间的平衡。"},sec={{t="高崖隐士",b="多恩·平原行者隐居在老屋峡谷高处山脊的一处浅洞中，远离乱风岗的喧嚣。要抵达他的山中居所，必须沿北侧陡峭的悬崖蜿蜒而行，俯瞰下方高耸的台地。在这处清幽的高地，多恩守护着古老的习俗，并评判那些在严酷的南贫瘠之地寻求指引的人。"},{t="四项试炼",b="多恩·平原行者引导朝圣者完成一系列严苛的考验，衡量牛头人勇士的核心美德：信仰、耐力、力量和学识。这些试炼并非单纯考验蛮力，而是迫使试炼者直面恐惧，纵身跃入未知，与荒野中狡猾的掠食者比拼耐力，并思索卡利姆多的神圣历史，才能最终通过成年试炼。"}},faq={{q="多恩·平原行者是谁？",a="多恩·平原行者是一位牛头人隐士和长者，住在老屋，那是千针石林高处一处隐蔽的崖边居所。他为立志成为勇士的部落成员主持传统的成年试炼。",al={"多恩是谁","多恩的传说","多恩·平原行者"}},{q="在哪里可以找到多恩·平原行者？",a="他位于老屋的一处洞穴中。从乱风岗向北走，抵达峡谷边缘高耸的峭壁，再沿山脊向东，直到找到一条通往他山中隐居之所的坡道。",al={"多恩在哪里","如何前往多恩·平原行者处","老屋位置"}},{q="多恩主持哪些试炼？",a="多恩主持四项神圣的考验：信仰的试炼、耐力的试炼、力量试炼和知识试炼。完成这些考验，便能证明旅人的勇气、身体的韧性、战斗技巧，以及对传统的尊重。",al={"多恩·平原行者任务","信仰的试炼","千针石林成年试炼"}},{q="什么是信仰的试炼？",a="信仰的试炼要求朝圣者从令人目眩的悬崖木板上迈步而下，跃入下方的深渊，以此展现毫无保留的信任，并克服本能的恐惧。",al={"千针石林信仰之跃","信仰的试炼 多恩"}},{q="多恩为何独居洞穴？",a="多恩恪守牛头人的苦修精神传统。他独居在老屋的高处，远离乱风岗日常的贸易与防务，为求道者守护着一处不受打扰的冥思与试炼之地。",al={"多恩为何隐居","多恩·平原行者背景"}},{q="多恩与乱风岗有关联吗？",a="虽然多恩住在乱风岗之外，但他仍是部落和牛头人各部族的忠诚一员，帮助那些穿行于狂风呼啸的峡谷中的勇敢旅人。",al={"乱风岗长者","多恩属于部落吗"}}},fx={["4250a0db"]={q="多恩·平原行者效忠哪一方？",a="多恩·平原行者效忠部落和他的牛头人同胞。他欢迎部落旅者前往老屋，接受考验以证明自己的能力，并引导他们完成传统仪式，确保他们具备为部族和整个部落效力所需的力量、信仰与智慧。",al={"多恩是部落成员吗","多恩·平原行者的阵营","多恩效忠谁"}},a0eea52d={q="多恩·平原行者想做什么？",a="多恩·平原行者想考验那些穿越千针石林的勇士的品格、耐力与精神。通过主持信仰、耐力、力量和知识试炼，他希望让合格的冒险者为世界的严酷挑战做好准备，并确保他们尊崇大地的传统。",al={"多恩的目标","多恩想做什么","多恩·平原行者的职责"}}},fp="17,281,25.303.0,15.302.0,25.177.0,35.204.0,37.225.0,26.134.0,35.227.0,38.157.0"}
P.entries["npc:drum-fel"] = {n="杜拉姆法尔",s="在落锤镇，杜拉姆法尔指挥部落抵御巨魔、食人魔和人类残部，守住阿拉希。他与妻子科林一同努力，为部落在这片地区建立稳固的立足点。",h="在落锤镇，杜拉姆法尔指挥部落抵御巨魔、食人魔和人类残部，守住阿拉希。他与妻子科林一同努力，为部落在这片地区建立稳固的立足点。",kw={"阿拉希高地","石拳","杜拉姆法尔","落锤镇","科林法尔","奥卡拉尔","枯木"},ang={["faction:Horde"]="对于在东部王国推进的部落战士，杜拉姆法尔统筹军事行动，确保幽暗城与南方领地之间脆弱的生命线畅通。",["race:Orc"]="身为兽人，杜拉姆法尔展现出在东部王国重建兽人生活所需的坚定意志，坚守在这片曾经遍布收容所的土地上。"},sec={{t="落锤镇的守卫官",b="杜拉姆法尔统领落锤镇的防御，并指挥部落向阿拉希推进。在这座设防的庇护所中，他面对着四面八方的敌对势力。枯木森林巨魔和石拳食人魔占据着博德戈尔和石拳大厅。杜拉姆知道，落锤镇无法仅靠独善其身而兴盛；必须削弱周边敌人的力量。他派遣身经百战的勇士深入敌境，在这些威胁袭击部落营地之前将其瓦解。"},{t="激流堡的威胁",b="杜拉姆法尔将战事推进到激流堡，石拳食人魔已在这个覆灭的人类王国的废墟中据守。多年前，杜拉姆击败了食人魔蛮兵奥卡拉尔，而这个食人魔至今未忘。如今，奥卡拉尔在激流堡内部伺机复仇。杜拉姆的妻子科林暗中设法向丈夫隐瞒奥卡拉尔的行踪。她依靠外来的冒险者消除这一威胁，以免杜拉姆冲进埋伏。"}},faq={{q="杜拉姆法尔是谁？",a="杜拉姆法尔坐镇阿拉希高地的落锤镇，领导部落的军事行动，指挥针对当地敌对势力的战役。",al={"杜拉姆法尔","杜拉姆法尔是谁","落锤镇 杜拉姆"}},{q="在哪里可以找到杜拉姆法尔？",a="杜拉姆法尔位于阿拉希高地东北部的落锤镇内，就在向北通往辛特兰的大路东侧。",al={"杜拉姆法尔位置","杜拉姆法尔在哪","寻找杜拉姆法尔"}},{q="科林法尔是谁？",a="科林法尔是杜拉姆法尔的妻子，住在落锤镇。",al={"科林法尔","杜拉姆法尔的妻子"}},{q="食人魔奥卡拉尔为什么想杀死杜拉姆法尔？",a="多年前，杜拉姆法尔曾在战斗中击败奥卡拉尔。这个蒙受羞辱的食人魔如今在激流堡的废墟中等待，寻求向杜拉姆复仇。",al={"奥卡拉尔的仇怨","奥卡拉尔为什么憎恨杜拉姆法尔","奥卡拉尔 杜拉姆法尔"}},{q="杜拉姆法尔针对哪些威胁展开行动？",a="杜拉姆法尔指挥部队打击博德戈尔、石拳大厅和激流堡的石拳食人魔，以及附近的枯木巨魔部族。",al={"杜拉姆法尔任务","杜拉姆法尔的敌人","杜拉姆法尔与谁作战"}}},fp="8,187,20.438.0,24.424.1,16.144.0,28.129.0,17.60.0,46.143.0,34.160.0"}
P.entries["npc:drusilla-la-salle"] = {n="杜希拉·拉萨雷",s="杜希拉·拉萨雷在北郡修道院外的墓地里教授术士。这位人类训练师在神圣教团管辖之外，指导初学施法者掌握暗影与召唤之术。当禁忌知识流出修道院，她便动身将其据为己有。",h="杜希拉·拉萨雷在北郡修道院外的墓地里教授术士。这位人类训练师在神圣教团管辖之外，指导初学施法者掌握暗影与召唤之术。当禁忌知识流出修道院，她便动身将其据为己有。",kw={"修道院","杜希拉·拉萨雷","墓地","北郡","虚空灵能","被盗的典籍","术士训练师"},ang={["class:Priest"]="身为牧师，你看到杜希拉·拉萨雷在北郡的神圣殿堂之外，紧邻祝圣过的墓地，研习暗影之术与恶魔契约。",["class:Warlock"]="身为术士，你向第一位导师杜希拉·拉萨雷学习黑暗法术。她教授实用的诅咒与邪能召唤之术，并敦促你在众目睽睽之下掩藏自己的野心。"},sec={{t="圣地中的暗影",b="杜希拉·拉萨雷在北郡修道院外的墓碑之间教授术士学徒。院内，圣骑士和牧师在彩绘玻璃下研习。暴风城禁止恶魔学和邪能魔法，因此术士只能栖身于社会边缘。新学徒收到被污染的信件后，杜希拉·拉萨雷便教他们运用暗影，同时避免立刻激怒修道院的主事者。"},{t="虚空灵能",b="北郡修道院的图书馆侧厅收藏着禁书，其中就有《虚空灵能》。杜希拉·拉萨雷觊觎这份手稿已久，但术士若出现在守卫森严的藏书室，难免引人怀疑。一名背弃信仰的见习者带着这本书逃离修道院，加入了迪菲亚潜行者，她的机会就此到来。杜希拉·拉萨雷派学徒追赶叛徒，将魔典带给她，声称他们是在追回修道院的财物。"}},faq={{q="为什么术士能在北郡修道院附近活动？",a="圣光教会和暴风城的领袖对术士深怀戒心。杜希拉·拉萨雷在附近的墓地授课，远离北郡修道院内研习的牧师和教士。",al={"杜希拉·拉萨雷为何在修道院","神圣修道院中的术士","她为何在墓地"}},{q="杜希拉·拉萨雷想得到哪本书？",a="杜希拉·拉萨雷想得到《虚空灵能》，这本魔典曾被锁在北郡修道院图书馆侧翼内一处严加看守的地方。一名迪菲亚叛逃者偷走了它，将书带到了修道院势力所不及的地方。",al={"她想要哪本书","虚空灵能书籍","被盗典籍任务书籍"}},{q="谁从图书馆偷走了那本书？",a="北郡修道院的一名见习者违背誓言，加入迪菲亚潜行者后，偷走了这本典籍。他逃到了北郡山谷附近的一处营地。",al={"谁拿走了典籍","迪菲亚窃书贼","谁偷走了虚空灵能"}},{q="她对新入门的人类术士有何作用？",a="杜希拉·拉萨雷是人类术士的第一位训练师。她收下寄给新学徒的被污染的信件，教授基础诅咒和召唤仆从之术。",al={"北郡人类术士训练师","谁在北郡训练术士"}}},fx={fe9579dd={q="杜希拉·拉萨雷是谁？",a="杜希拉·拉萨雷是一名人类术士，驻留在北郡山谷的修道院墓地里。神圣的牧师和圣骑士在修道院高墙内受训，而她则悄悄指导那些对黑暗法术颇有天赋的人类新手，教他们以自身意志驾驭邪能与暗影之力。",al={"杜希拉是谁","杜希拉·拉萨雷 背景故事","杜希拉 身份"}},["89e305f6"]={q="杜希拉·拉萨雷效忠哪一方？",a="她效忠暴风城王国和联盟。尽管北郡修道院崇奉圣光的神职人员对术士心存疑虑，杜希拉仍在为王国效力，训练初出茅庐的术士，让他们用危险的天赋对付暴风城的敌人。",al={"杜希拉是否邪恶","杜希拉 联盟","杜希拉 阵营"}}},fp="17,244,22.378.0,18.414.1,47.190.0,39.190.0,36.154.0,47.147.0"}
P.entries["npc:duke-hydraxis"] = {n="海达克西斯公爵",s="海达克西斯公爵是一位水元素贵族，在艾萨拉近海一座偏远、饱受海浪冲刷的小岛上统领海达希亚水元素。他效忠于猎潮者耐普图隆，召集凡人冒险者打击宿敌，尤其是炎魔拉格纳罗斯。",h="海达克西斯公爵是一位水元素贵族，在艾萨拉近海一座偏远、饱受海浪冲刷的小岛上统领海达希亚水元素。他效忠于猎潮者耐普图隆，召集凡人冒险者打击宿敌，尤其是炎魔拉格纳罗斯。",kw={"艾萨拉","海达克西斯公爵","海达希亚水元素","海达克西斯","熔火之心","耐普图隆","拉格纳罗斯","水元素"},ang={["class:Shaman"]="对于直接与原初元素沟通的萨满祭司而言，遇见海达克西斯公爵这样地位的元素，便有难得的机会了解Neptulon古老的等级体系，以及元素位面之间永恒的争斗。"},sec={{t="水元素之主",b="海达克西斯公爵驻守在艾萨拉拉文凯斯雕像东北方的一块孤岩上，是海达希亚水元素的首席使者。大多数被束缚于艾泽拉斯的元素都充满敌意、混乱无序，海达克西斯却行事审慎，目标明确。作为猎潮者耐普图隆的忠诚封臣，他认为水是原初之力中最纯净、最不可或缺的力量。他冷眼审视着艾泽拉斯日益加剧的动荡，寻找能够改变元素战争力量平衡的勇士。"},{t="对抗烈焰之战",b="海达克西斯的主要战役针对火焰之王拉格纳罗斯麾下的烈焰大军。他视火元素的侵袭为世界的毒瘤，必须将其扑灭。在给予信任，或提供挑战拉格纳罗斯在熔火之心的烈焰要塞所需的工具之前，海达克西斯公爵要求凡人斩杀各大陆上的敌对元素，以证明自己的力量、韧性与忠诚。证明自身价值的人将获得大海的祝福，以及浇灭守护火焰之王领地的神圣火焰的手段。"}},faq={{q="在哪里可以找到海达克西斯公爵？",a="海达克西斯公爵位于艾萨拉东部近海的一座孤立小岛上，就在拉文凯斯雕像的东北方。",al={"海达克西斯在哪里","海达克西斯公爵位置","寻找海达克西斯公爵","海达克西斯地图位置"}},{q="海达克西斯公爵效忠于谁？",a="他领导海达希亚水元素，并侍奉水元素的统治者猎潮者耐普图隆。",al={"海达克西斯侍奉谁","海达克西斯阵营","耐普图隆的仆从"}},{q="海达克西斯公爵为何关注凡人勇士？",a="他寻找可靠的凡人盟友，向敌对的元素势力开战，尤其是潜伏在黑石山中的拉格纳罗斯的烈焰大军。",al={"海达克西斯为何需要我们","海达克西斯想要什么","海达克西斯的目的"}},{q="海达克西斯公爵与熔火之心有什么联系？",a="海达克西斯公爵指引勇士削弱炎魔拉格纳罗斯的力量，并提供必要的元素助力，以熄灭守卫熔火之心的符文与首领。",al={"海达克西斯熔火之心","海达克西斯 拉格纳罗斯","熔火之心 海达克西斯"}}},fp="13,216,22.377.0,20.504.0,33.131.0,34.114.0,52.139.0,54.152.0"}
P.entries["npc:durnan-furcutter"] = {n="德南·弗卡特",s="在寒脊山谷的安威玛尔，德南·弗卡特为年轻的矮人和侏儒提供抵御山间严寒的衣物。他在聚居地内出售轻便衣物和皮革制品。",h="在寒脊山谷的安威玛尔，德南·弗卡特为年轻的矮人和侏儒提供抵御山间严寒的衣物。他在聚居地内出售轻便衣物和皮革制品。",kw={"安威玛尔","布甲商人","寒脊山谷","丹莫罗","德南·弗卡特","皮甲商人","热酒"},ang={["profession:Tailoring"]="作为初学裁缝的你，可以从德南的基础衣物中学到东西。在换上大师制作的布甲之前，这些衣物帮助斥候和学徒在积雪的山口中活下来。",["race:Dwarf"]="作为寒脊山谷的矮人，你能看到德南实用的手艺，以及他对热酒的喜爱。他亲切的谈笑声在风雪中传开。"},sec={{t="寒风中的温暖针脚",b="在安威玛尔内，年轻的矮人和流亡的侏儒努力证明自己。有些人需要行动自如，沉重的铁甲难以满足他们的需要。德南·弗卡特出售轻便柔韧的衣物，供斥候、潜行者和施法者穿着，让他们在丹莫罗的刺骨寒风中保持灵活。他在炉火旁出售日常衣物和缝制的皮革制品。他声称自己的货物是山谷里最好的。"},{t="酒杯在手",b="德南既喜欢烈酒，也喜欢诚信的买卖。为了抵御冰冷的穿堂风，他向诺里斯·激流订购一杯杯热气腾腾的热酒，后者在寒脊山谷各处出售这种滚烫的酒。忙着在山谷中奔走办事的冒险者，经常趁酒还没凉就给德南送来一杯。随后，他们再把空杯送回诺里斯手中。"}},faq={{q="德南·弗卡特是谁？",a="德南·弗卡特向初入丹莫罗的冒险者出售基础布甲和皮甲装备。他是寒脊山谷安威玛尔的一名矮人服装和皮革商人。",al={"德南","弗卡特","德南·弗卡特是谁"}},{q="在哪里可以找到德南·弗卡特？",a="你可以在寒脊山谷的安威玛尔内找到德南·弗卡特，他就在训练师和当地工匠附近。",al={"德南位置","德南在哪","安威玛尔布甲商人"}},{q="德南出售什么？",a="德南出售入门级布甲和皮甲，供依靠敏捷身手或法术、而非厚重锁甲的冒险者使用。",al={"德南货物","德南卖什么"}},{q="他为什么会与运送热酒有关？",a="德南长时间在寒脊山谷的凛冽寒风中工作。他向在山谷各处卖酒的诺里斯·激流订购热腾腾的热酒，用来暖身提神。",al={"德南啤酒任务","热酒 德南","德南酒"}}},fx={d97cf4a2={q="德南·弗卡特效忠哪一方？",a="德南坚定地支持铁炉堡和联盟。他在安威玛尔为年轻的矮人和侏儒新兵提供装备，他们的旅程正是从寒脊山谷开始的。",al={"德南 阵营","德南·弗卡特 联盟","德南效忠谁"}},afaf309b={q="德南·弗卡特想要什么？",a="德南最看重的自然是做生意，还夸口说自己出售的布衣和皮装是山谷这一带最好的。生意之外，他从不拒绝一杯热气腾腾的热酒，好抵御寒脊山谷刺骨的严寒。",al={"德南想要什么","德南·弗卡特 目标","德南 目的"}},["9750ade9"]={q="德南·弗卡特为什么在安威玛尔？",a="安威玛尔是寒脊山谷新兵的训练大厅，也是他们的集会之所。德南留在这里，为初出茅庐的冒险者提供必需的衣物和基础护甲，让他们做好准备，再踏入冰雪覆盖的荒野。",al={"德南为何在这里","德南为何在寒脊山谷","德南 所在位置 原因"}}},fp="16,175,25.376.0,13.360.0,24.179.0,34.114.0,22.126.0,53.166.0"}
P.entries["npc:duthorian-rall"] = {n="达索瑞恩·拉尔",s="在暴风城的光明大教堂，达索瑞恩·拉尔指引初出茅庐的神圣勇士完成试炼。身为白银之手中备受尊敬的人类骑士，他是联盟最具影响力的圣骑士之一。他负责监督他们的训练与精神试炼，教导他们仁爱、勇气与奉献，让他们准备好保卫艾泽拉斯，抵御天灾军团以及王国内部的威胁。",h="在暴风城的光明大教堂，达索瑞恩·拉尔指引初出茅庐的神圣勇士完成试炼。身为白银之手中备受尊敬的人类骑士，他是联盟最具影响力的圣骑士之一。他负责监督他们的训练与精神试炼，教导他们仁爱、勇气与奉献，让他们准备好保卫艾泽拉斯，抵...",kw={"光明大教堂","达芙妮·斯迪威尔","达索瑞恩·拉尔","乔丹·斯迪威尔","圣骑士训练师","白银之手","暴风城","生命符记","圣洁之书","勇气之书"},ang={["class:Paladin"]="身为圣骑士，你在暴风城接受达索瑞恩·拉尔的指引。他的基础试炼考验你的怜悯与勇气，让你获得复活、神圣感知以及召唤战马的能力。",["faction:Alliance"]="身为联盟的守卫者，你仰赖达索瑞恩这位颇具影响力的白银之手领袖，确保联盟的守卫者品行端正，有能力保卫王国，抵御强盗与亡灵。",["race:Human"]="身为人类，你会在暴风城的光明大教堂见到常驻于此的达索瑞恩，他体现了人类信仰与社会所重视的虔诚和骑士纪律。"},sec={{t="白银之手的支柱",b="在光明大教堂，达索瑞恩·拉尔恪守白银之手骑士团的传统。王国因境内的纷争而动荡不安，瓦里安·乌瑞恩国王也下落不明。达索瑞恩肩负着教导新入门者严守纪律的职责。各地备受尊敬的圣骑士会将有潜力的新兵送到他这里：闪金镇的威尔海姆修士和铁炉堡的布兰度尔·铁锤。在那里，新兵们开始接受神圣的试炼。"},{t="怜悯与生命的试炼",b="达索瑞恩教导他们，缺乏道德根基的武力是空洞的。在圣洁之书试炼中，他让入门者在暴风城各处施行仁慈之举、无私助人，以此考验他们的同情心。只有完成这些考验，他才会向候选者传授更深奥的奥秘。\n\n在英雄哨岗附近，他用生命符记考验他们。随后，他派他们去救助受伤的盟友，学习引导圣光的力量，让死去的战友重获生命。"},{t="勇气的代价",b="达索瑞恩的勇气试炼要求他们在险境面前勇敢无畏。他告诫有志入门者，践行誓言可能让他们付出生命。为了考验他们的决心，他派入门者深入险境，其中就包括前往西部荒野，保护达芙妮·斯迪威尔免受迪菲亚叛徒的侵害。随后，他指引他们去寻找铁炉堡外的锻造大师乔丹·斯迪威尔，并赐予他们与身份相称的神圣战马。"}},faq={{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是白银之手的一位杰出骑士，常驻暴风城的光明大教堂。他教导新晋圣骑士，考验他们为圣光教会效力的虔诚与勇气。",al={"达索瑞恩·拉尔背景故事","达索瑞恩是谁","大教堂圣骑士达索瑞恩"}},{q="在哪里可以找到达索瑞恩·拉尔？",a="达索瑞恩·拉尔位于光明大教堂的东翼，这座教堂坐落在暴风城教堂广场的中心。",al={"达索瑞恩·拉尔在哪里","达索瑞恩·拉尔位置","如何找到达索瑞恩"}},{q="他与圣洁之书有什么关联？",a="达索瑞恩将圣洁之书交给圣骑士，指引他们完成谦卑、怜悯与救援的试炼。完成试炼，便证明入门者有资格运用圣光的力量复活死者。",al={"圣洁之书 达索瑞恩","救赎任务 达索瑞恩","生命符记任务"}},{q="达索瑞恩为什么派圣骑士前往西部荒野？",a="在勇气之书试炼中，达索瑞恩派圣骑士前往达芙妮·斯迪威尔位于西部荒野的农场，保护她免受迪菲亚强盗的侵害。这份危险考验着他们是否愿意牺牲自己，保护无辜者。",al={"达芙妮·斯迪威尔任务","勇气之书 西部荒野","西部荒野圣骑士任务"}},{q="达索瑞恩会给予通过试炼的圣骑士哪些奖励？",a="在达索瑞恩的指引下，通过考验的圣骑士会获得关键的神圣能力，包括复活死者的神圣恩赐、感知亡灵的能力，以及暴风壁垒这样的防护装备，最终还能召唤战马。",al={"达索瑞恩任务奖励","达索瑞恩给予什么奖励"}},{q="最初是谁将冒险者引荐给达索瑞恩的？",a="通常由圣骑士训练师指引有志入门者前去拜访达索瑞恩，其中包括闪金镇的威尔海姆修士和铁炉堡的布兰度尔·铁锤。",al={"谁引荐前往达索瑞恩处","达索瑞恩指引任务"}}},fx={adc9c2ec={q="达索瑞恩·拉尔效忠哪一方？",a="达索瑞恩·拉尔坚定地效忠大联盟、暴风城王国和白银之手骑士团。他在光明大教堂侍奉圣光，与王国的领袖和神职人员一道训练圣骑士，让他们投身于守护艾泽拉斯的事业，抵御天灾军团和迪菲亚潜行者等威胁。",al={"达索瑞恩·拉尔 阵营","达索瑞恩效忠谁","达索瑞恩·拉尔是否属于联盟"}},["5fa6dad6"]={q="达索瑞恩·拉尔想要什么？",a="达索瑞恩致力于考验、磨炼并引导有志成为圣骑士的人，让他们真正体现美德、怜悯与勇气。他通过施舍、忏悔和履行战斗职责的试炼，确保新晋的神圣战士已准备好运用复活之术等圣光最伟大的恩赐，保卫王国，抵御日益严峻的威胁。",al={"达索瑞恩·拉尔的目标","达索瑞恩想要什么","达索瑞恩·拉尔 动机"}},["091b91cc"]={q="达索瑞恩·拉尔为什么在这里？",a="达索瑞恩驻守在暴风城的光明大教堂，是白银之手在南方诸国的首席导师之一。王国各地的教官将前途光明的新兵引荐给他，由他督导他们的虔诚信仰，在实战中考验他们的决心，并正式授予他们更高的阶位。",al={"达索瑞恩为何在暴风城","达索瑞恩·拉尔 大教堂 职责","达索瑞恩·拉尔为何在这里"}},["6e7325c8"]={q="达索瑞恩·拉尔与谁有联系？",a="达索瑞恩与各地的导师密切合作，例如闪金镇的威尔海姆修士和铁炉堡的布兰度尔·铁锤，他们会向他引荐有潜力的圣骑士。他也与艾尔文各地需要帮助的朋友保持密切联系，例如贾森·坦诺姆，还会与西部荒野的斯迪威尔一家等盟友协同行动。",al={"达索瑞恩·拉尔 盟友","达索瑞恩·拉尔 人际关系","达索瑞恩认识谁"}},["46aa8798"]={q="达索瑞恩·拉尔为什么出名？",a="达索瑞恩以联盟最具影响力的圣骑士之一而闻名。在白银之手内部，他因坚定不移的虔诚、培养新一代神圣勇士的职责，以及向值得嘉奖的骑士授予崇高神圣荣誉的权力而备受尊敬。",al={"达索瑞恩·拉尔是否有名","达索瑞恩·拉尔 声望","达索瑞恩·拉尔有多出名"}}},fp="14,365,27.431.0,29.437.0,18.376.1,22.214.0,34.125.0,47.211.0,45.210.0,66.240.0,45.134.0"}
P.entries["npc:ebru"] = {n="厄布鲁",s="厄布鲁是一名暗夜精灵德鲁伊，栖身于哀嚎洞穴上方的峭壁间。她是纳拉雷克斯仅存的少数未受腐化的弟子之一，只能无助地看着导师复苏贫瘠之地的梦想扭曲成梦魇。她在高处招募勇于深入地下的旅人，请他们清剿 梦魇 催生的变异怪物。",h="厄布鲁是一名暗夜精灵德鲁伊，栖身于哀嚎洞穴上方的峭壁间。她是纳拉雷克斯仅存的少数未受腐化的弟子之一，只能无助地看着导师复苏贫瘠之地的梦想扭曲成梦魇。她在高处招募勇于深入地下的旅人，请他们清剿 梦魇 催生的变异怪物。",kw={"贫瘠之地","塞纳里奥议会","变异","德鲁伊","厄布鲁","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊而言，遇见厄布鲁便会深切地意识到，行走于翡翠梦境之中潜藏着何等可怕的危险，一旦失控，又会付出何等惨痛的代价。",["race:NightElf"]="厄布鲁代表着一小群孤立无援的暗夜精灵，他们在卡利姆多干旱腹地的深处活动，远离灰谷与泰达希尔的古老枝丫。"},sec={{t="洞口上方的守望",b="纳拉雷克斯的大多数追随者都屈服于洞穴中蔓延的翡翠腐化，厄布鲁却逃脱了梦魇的魔掌。她在俯瞰哀嚎洞穴入口的骷髅状岩体内扎营，守望着通往深处的道路。她知道，纳拉雷克斯引出地下泉水、将干旱的贫瘠之地化为葱郁林地的高尚计划已经酿成惨剧，于是急切地指引自愿前来的冒险者消灭日益增多的变异野兽，以免它们席卷周围的平原。"},{t="腐化的代价",b="梦魇不仅扭曲了洞穴的生态，也扭曲了厄布鲁的同门，将他们变成了狂热的尖牙德鲁伊。失去了同伴，又眼看着自己的德鲁伊团体走向毁灭，厄布鲁将精力集中在遏制腐化上。"}},faq={{q="厄布鲁是谁？",a="厄布鲁是一名暗夜精灵德鲁伊，也是纳拉雷克斯未受腐化的弟子。她住在哀嚎洞穴入口上方高处的一处洞穴中，监视着这里，并协调各方力量，阻止腐化蔓延到贫瘠之地。",al={"厄布鲁是谁","厄布鲁的故事","关于厄布鲁"}},{q="厄布鲁为什么在哀嚎洞穴上方？",a="纳拉雷克斯的仪式失控，陷入 翡翠梦魇，将她的同门变成了充满敌意的狂热者，她便向上逃去。洞口上方峭壁间的栖身之处让她既能监视洞穴，又能避开里面凶残的怪物。",al={"厄布鲁在哪里","厄布鲁为什么在上面","厄布鲁的洞穴位置"}},{q="纳拉雷克斯和他的其他弟子遭遇了什么？",a="纳拉雷克斯为了引出地下泉水而进入深度冥想，意识却被困在了 翡翠梦魇 之中。随之而来的腐化扭曲了洞穴中的动植物，也让他的大多数弟子陷入疯狂，变成了尖牙德鲁伊。",al={"弟子们遭遇了什么","纳拉雷克斯的命运","尖牙德鲁伊 的起源"}},{q="厄布鲁请旅人做什么？",a="厄布鲁敦促冒险者深入哀嚎洞穴，清剿变异野兽，反击那些从导师饱受折磨的梦境中诞生的变异怪物。",al={"厄布鲁的任务","清除变异生物","净化洞穴"}}},fx={["5ace5551"]={q="厄布鲁效忠于哪一方？",a="厄布鲁为塞纳里奥议会效力，并忠于她的导师——德鲁伊纳拉雷克斯。许多同伴都遭到侵入洞穴的梦魇侵蚀，而她没有变得敌对，也未屈服于腐化。她虽是暗夜精灵，却愿意接纳任何有能力深入洞穴净化绿洲、拯救师父的旅人，无论其属于联盟还是部落。",al={"厄布鲁所属阵营","厄布鲁属于联盟还是部落","厄布鲁为谁效力"}}},fp="4,229,25.497.0,23.219.1,12.213.0,46.244.0,49.247.0,35.191.0"}
P.entries["npc:edwin-vancleef"] = {n="艾德温·范克里夫",s="才华横溢的艾德温·范克里夫在死亡矿井中统领着迪菲亚潜行者。他曾领导 石匠公会，在第二次战争后重建暴风城。贵族拒绝支付承诺给工人们的报酬，如今范克里夫正向这个他曾帮助复兴的王国寻求复仇。",h="才华横溢的艾德温·范克里夫在死亡矿井中统领着迪菲亚潜行者。他曾领导 石匠公会，在第二次战争后重建暴风城。贵族拒绝支付承诺给工人们的报酬，如今范克里夫正向这个他曾帮助复兴的王国寻求复仇。",kw={"兄弟会","死亡矿井","迪菲亚","月溪镇","石匠","暴风城","范克里夫","西部荒野"},ang={["class:Rogue"]="SI:7 的首领马迪亚斯·肖尔亲自训练了范克里夫。范克里夫将公会领导才能与高超的暗杀技巧结合起来，成为艾泽拉斯最出色的盗贼之一。",["faction:Alliance"]="联盟指挥官将范克里夫视为南方人类领地内部安全的头号威胁。他的行动让西部荒野和艾尔文森林边境陷入瘫痪。",["race:Human"]="对暴风城的人类而言，范克里夫的故事展现了王国战后复兴的代价：一位忠诚的英雄被剥夺了生计，最终成为王国最致命的叛乱者。"},sec={{t="王国的建筑师",b="第一次战争后，艾德温·范克里夫领导石匠行会重建了暴风城。他是一位技艺无双的工匠，也是一位理想主义者，精通建筑，指挥修筑了首都宏伟的城墙和高耸的大教堂。他儿时的好友马迪亚斯·肖尔教会他潜行、诡计和刀剑技艺，让范克里夫既成为建筑大师，也成为了致命的秘密行动高手。"},{t="暴动与兄弟会",b="经过多年的劳作，石匠公会 完成了暴风城的重建。贵族因军事征战欠下巨额债务，拒绝向公会支付承诺的报酬。范克里夫要求偿付，贵族们却解散了公会。他率领工人发动暴动，随后离开了城市。混乱中，他的副手兼最信任的助手巴基尔·斯瑞德被捕，关进了监狱。在西部荒野，范克里夫将遭到放逐的工人和结盟的流亡者聚集在迪菲亚潜行者的旗帜下。"},{t="暗影中的复仇",b="王室疏于治理乡野之际，迪菲亚将西部荒野的农民赶出家园，霸占了当地丰富的金矿。在月溪镇的死亡矿井深处，范克里夫正指挥建造一艘巨型战舰，准备武力进攻暴风城。贵族将这些盗贼视为一群乌合之众，而范克里夫已经与河匪、豺狼人和海盗联手。他满怀怨恨的工会已成为一支蓄势待发、准备对抗王权的大军。"}},faq={{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫是迪菲亚潜行者的首领，曾任 石匠协会 的会长。第一次战争期间，部落摧毁了暴风城，而他正是重建这座城市的建筑大师。",al={"范克里夫是谁","艾德温·范克里夫的故事","范克里夫的身份"}},{q="石匠协会 为何反抗暴风城？",a="石匠协会 重建暴风城后，贵族因王国债台高筑而拒绝向公会支付约定的工钱。范克里夫和工人们提出抗议，贵族们却解散了公会，街头随即爆发了激烈的暴动。",al={"迪菲亚 为何反叛","石匠 为何暴动","迪菲亚 暴动的原因"}},{q="艾德温·范克里夫藏在哪里？",a="艾德温·范克里夫在西部荒野死亡矿井最深处的密室中指挥迪菲亚潜行者。传闻入口就在宁静的月溪镇中。",al={"范克里夫在哪里","范克里夫的位置","死亡矿井首领的位置"}},{q="他与马迪亚斯·肖尔有什么关系？",a="马迪亚斯·肖尔是艾德温·范克里夫儿时的好友。肖尔训练范克里夫潜行、偷窃和战斗的本领，希望他能加入王室情报机构 SI:7。",al={"范克里夫与 肖尔","范克里夫与 肖尔 有关系吗","马迪亚斯·肖尔 的朋友"}},{q="巴基尔·斯瑞德在暴动中遭遇了什么？",a="暴动期间，范克里夫的副手兼最信任的助手巴基尔·斯瑞德被捕入狱。范克里夫带领 石匠协会 离开城市时，斯瑞德却几乎被遗忘在监狱里，等待审判和讯问。",al={"巴基尔·斯瑞德是谁","范克里夫的副手","巴基尔·斯瑞德与暴动"}},{q="他在死亡矿井里建造什么？",a="迪菲亚征召了聪明的地精，协助他们在死亡矿井底部建造某种可怕的东西，但究竟是什么，仍不得而知。",al={"死亡矿井的船","死亡矿井里有什么","范克里夫的战舰"}}},fp="14,273,24.387.0,28.517.0,28.474.1,22.199.0,49.252.0,31.174.1,39.164.0,46.227.0,37.145.1"}
P.entries["npc:einar-stonegrip"] = {n="埃纳尔·石钳",s="埃纳尔·石钳守在湿地十字路口的路旁，托旅人将货物送进镇里。他避而不去米奈希尔港，因为与他失和的妻子就住在那里。",h="埃纳尔·石钳守在湿地十字路口的路旁，托旅人将货物送进镇里。他避而不去米奈希尔港，因为与他失和的妻子就住在那里。",kw={"鳄鱼","埃纳尔·石钳","詹姆斯·哈洛兰","米奈希尔港","塞达","皮革","捕猎者","湿地"},ang={["faction:Alliance"]="身为联盟的旅人，你在铁炉堡与米奈希尔港之间往来时，可能会经过埃纳尔的路边落脚处。他会雇人沿联盟的补给路线运送货物。",["race:Dwarf"]="身为矮人，你或许能理解埃纳尔那种坚韧自立的性情。他与妻子之间的纠葛，让他只能待在湿漉漉的沼泽里，无法置身温暖的旅店。"},sec={{t="十字路口的捕猎者",b="埃纳尔·石钳在湿地的道路交汇处猎捕鳄鱼。这里的十字路口连接着丹奥加兹、丹莫德和米奈希尔港。他将结实的鳄鱼皮卖给沿海的制皮匠和商人。埃纳尔虽然强悍得足以从泥潭里拖出爬行动物，却与妻子塞达闹得不可开交。他留在路旁，请旅人把成捆的皮革送给他的生意伙伴詹姆斯·哈洛兰，不愿亲自进入米奈希尔港。"}},faq={{q="埃纳尔·石钳是谁？",a="埃纳尔·石钳在湿地的十字路口猎捕鳄鱼，并将鳄鱼皮卖到米奈希尔港。",al={"埃纳尔是谁","埃纳尔·石钳的故事","湿地矮人十字路口"}},{q="埃纳尔为什么不亲自把货物送到米奈希尔港？",a="埃纳尔不去米奈希尔港，是因为他与住在那里的妻子塞达关系极其恶劣。他留在沼泽地里，付钱请过路的信使运送货物。",al={"埃纳尔为什么不进镇","埃纳尔·石钳的妻子","为什么雇用冒险者"}},{q="埃纳尔在米奈希尔港与谁做生意？",a="埃纳尔为詹姆斯·哈洛兰收集鳄鱼皮，后者是米奈希尔港一位经营皮革制品的商人。",al={"埃纳尔的生意伙伴","谁买埃纳尔的皮革","与詹姆斯·哈洛兰的关系"}}},fp="15,167,27.475.0,23.101.0,57.176.0,44.104.0"}
P.entries["npc:eitrigg"] = {n="伊崔格",s="在奥格瑞玛，伊崔格作为备受信赖的顾问，站在大酋长萨尔身旁。他曾参加第一次兽人战争和第二次兽人战争，在黑石氏族所属的部落战败后离去，过起了流亡生活。如今，他协助萨尔引领新部落重拾荣耀与萨满之道。",h="在奥格瑞玛，伊崔格作为备受信赖的顾问，站在大酋长萨尔身旁。他曾参加第一次兽人战争和第二次兽人战争，在黑石氏族所属的部落战败后离去，过起了流亡生活。如今，他协助萨尔引领新部落重拾荣耀与萨满之道。",kw={"黑石氏族","鲜血与荣耀","伊崔格","索尔的堡垒","壁炉谷","奥格瑞姆·毁灭之锤","奥格瑞玛","斯坦索姆","萨尔","提里奥·弗丁"},ang={["class:Paladin"]="身为圣骑士，你知道伊崔格与提里奥·弗丁的故事，那是一场关于职责与正义荣耀的著名考验。",["class:Warrior"]="身为战士，你能从伊崔格身上看到历经数十年悲剧仍未磨灭的战士荣耀。他凭借力量与始终严明的自律，从两场战争中生还。",["faction:Horde"]="身为部落的一员，你可以将伊崔格视为部落活着的记忆。他站在萨尔身旁，帮助部落避免重蹈昔日遭恶魔腐化时的覆辙。",["race:Orc"]="身为杜隆塔尔的兽人，你可以将伊崔格视为一位备受尊崇的长者。他出身黑石氏族，却证明了任何兽人都能拥抱荣耀，挽回族人传承的荣光。"},sec={{t="旧部落的老兵",b="伊崔格出生于德拉诺的黑石氏族，曾在第一次兽人战争和第二次兽人战争中为部落而战。连年的征战，以及部落在第二次兽人战争中的败北，迫使他正视族人在嗜血与恶魔腐化中陷得有多深。他厌恶部落如今的模样，于是离开四散的残部，前往洛丹伦的荒野寻求独处。"},{t="鲜血与荣耀",b="流亡期间，伊崔格栖身于壁炉谷附近一座废弃的哨塔。人类圣骑士提里奥·弗丁发现了他，两人的交锋使残破的哨塔轰然倒塌。伊崔格没有杀死昏迷的人类，而是将他拖到了安全的地方。提里奥·弗丁被这份战士的荣耀打动，誓与他结为挚友，并为这位隐士的藏身之处保守秘密。当地的联盟当局最终抓住了伊崔格，判处他在斯坦索姆受绞刑。提里奥·弗丁舍弃骑士身份、领地与自由，攻入城中营救他。两人的情谊让这两位战士明白，荣耀能够跨越两个民族之间的仇恨。"},{t="大酋长的顾问",b="在斯坦索姆，提里奥·弗丁试图解救伊崔格时，萨尔新近统一的部落突袭了这座城市，带走了这位年迈的战士。与萨尔相识后，伊崔格确信兽人正在摆脱恶魔的腐化，回归祖先的萨满传统。他随萨尔横渡无尽之海，来到卡利姆多，并在奥格瑞玛的智慧谷获得了备受尊崇的地位。如今，伊崔格在索尔的堡垒内为年轻的大酋长出谋划策。他协助考核新兵，分享自己积累的智慧，让新部落免于重蹈昔日悲剧。"}},faq={{q="伊崔格是谁？",a="伊崔格是一位年迈的黑石兽人战士，也是参加过第一次兽人战争和第二次兽人战争的老兵。他如今居住在奥格瑞玛的索尔的堡垒，为大酋长萨尔提供建议。",al={"伊崔格是谁","伊崔格的故事","站在萨尔身旁的兽人"}},{q="伊崔格为何视一名人类为兄弟？",a="在洛丹伦流亡时，伊崔格与圣骑士提里奥·弗丁决斗，导致一座石塔倒塌，他救下了这位圣骑士。提里奥·弗丁为伊崔格的藏身之处保守秘密，后来更在斯坦索姆与自己的同胞交战，阻止处决，并为此放弃了头衔与领地。共同秉持的荣耀让他们结为兄弟。",al={"伊崔格与提里奥·弗丁","伊崔格的人类朋友","鲜血与荣耀"}},{q="伊崔格属于哪个氏族？",a="伊崔格属于黑石氏族。他曾参加昔日的战争，后来目睹部落残部遭到恶魔腐化，便离开了他们。",al={"伊崔格的氏族","伊崔格是黑石氏族的吗"}},{q="伊崔格为何离开旧部落？",a="部落在第二次兽人战争中战败后，伊崔格看清了嗜血与恶魔腐化如何夺走了族人的荣耀。他满怀厌恶地离去，宁愿找一处清静之地等待死亡，也不愿为腐化的战争机器效力。",al={"伊崔格为何离开","伊崔格的流亡"}},{q="伊崔格是如何来到奥格瑞玛的？",a="联盟军队抓住伊崔格，准备在斯坦索姆处决他时，萨尔的军队突袭了城市，将他救出。伊崔格看到萨尔恪守荣耀，带领族人回归萨满之道，便选择追随他前往卡利姆多。",al={"伊崔格如何结识萨尔","伊崔格获救"}},{q="伊崔格如今在奥格瑞玛担任什么职责？",a="在索尔的堡垒，伊崔格为萨尔提供建议，并协助考验和评估那些宣誓效忠新部落的新兵。",al={"伊崔格任务","伊崔格做什么"}}},fp="7,199,26.324.0,15.633.0,25.568.0,15.158.0,46.286.0,33.135.0,36.221.0,36.239.0,51.113.0"}
P.entries["npc:elanaria"] = {n="艾兰娜瑞",s="在达纳苏斯的战士区，艾兰娜瑞训练战士，让他们准备好应对卡利姆多各地的危险。她让他们迎战沃鲁斯·邪蹄和艾鲁拉的阴影等敌人，考验他们的实力。",h="在达纳苏斯的战士区，艾兰娜瑞训练战士，让他们准备好应对卡利姆多各地的危险。她让他们迎战沃鲁斯·邪蹄和艾鲁拉的阴影等敌人，考验他们的实力。",kw={"达纳苏斯","艾兰娜瑞","艾鲁拉的阴影","铁匠玛希尔","泰达希尔","沃鲁斯·邪蹄","战士任务","战士区"},ang={["class:Warrior"]="身为战士，你可以在战士区寻求艾兰娜瑞的指引，并在战斗中证明自己的实力。",["faction:Alliance"]="身为联盟士兵，当你在卡利姆多北部各地捍卫联盟的利益时，可以向达纳苏斯的艾兰娜瑞寻求指引和武器装备。",["race:NightElf"]="身为暗夜精灵，你可以帮助艾兰娜瑞，将萨特和不得安息的幽影赶出祖先的土地。"},sec={{t="战士区的哨兵",b="艾兰娜瑞在达纳苏斯的战士区训练战士。自暗夜精灵加入大联盟以来，她一直指引着哨兵和其他种族的战士，应对威胁他们家园的危险。"},{t="钢铁与意志的试炼",b="艾兰娜瑞要求战士具备纪律、耐力，以及经战斗证明的实力。她派遣经验丰富的战士前去铲除泰达希尔和黑海岸的威胁，其中包括萨特沃鲁斯·邪蹄和艾鲁拉的阴影。她还与铁匠玛希尔合作，为通过考验的战士配备作战所需的武器装备。"}},faq={{q="艾兰娜瑞是谁？",a="艾兰娜瑞是达纳苏斯战士区的一位暗夜精灵战士导师。她派遣战士前往卡利姆多北部各地接受试炼。",al={"艾兰娜瑞 达纳苏斯","艾兰娜瑞是谁","艾兰娜瑞 非玩家角色"}},{q="在哪里可以找到艾兰娜瑞？",a="你可以在战士区找到艾兰娜瑞，那里是达纳苏斯北部用于军事训练和防御的区域。",al={"艾兰娜瑞位置","艾兰娜瑞在哪里","艾兰娜瑞所在地点"}},{q="艾兰娜瑞提供哪些任务？",a="艾兰娜瑞派遣战士追击沃鲁斯·邪蹄和艾鲁拉的阴影，并指引他们前往铁匠玛希尔处获取武器装备。",al={"艾兰娜瑞任务","艾兰娜瑞提供的任务","艾兰娜瑞战士任务"}},{q="艾兰娜瑞为什么派遣战士对付沃鲁斯·邪蹄？",a="沃鲁斯·邪蹄是一个危险的萨特，他的腐化力量威胁着北方的荒野。艾兰娜瑞派遣有能力的战士前去杀死他，既保护森林，也在战斗中考验他们的实力。",al={"艾兰娜瑞 沃鲁斯","沃鲁斯·邪蹄任务","为什么杀死沃鲁斯·邪蹄"}},{q="铁匠玛希尔是谁？",a="铁匠玛希尔是达纳苏斯的一位护甲匠。艾兰娜瑞指引战士前往玛希尔处，获取适合前线作战的装备。",al={"玛希尔的关联","铁匠玛希尔 战士","艾兰娜瑞与玛希尔"}},{q="艾兰娜瑞会与暗夜精灵以外的种族来往吗？",a="会。艾兰娜瑞会指引前来战士区接受训练的联盟战士。",al={"人类能与艾兰娜瑞交谈吗","联盟战士 艾兰娜瑞"}}},fx={de8f39db={q="艾兰娜瑞效忠于哪一方？",a="艾兰娜瑞坚定地支持达纳苏斯的暗夜精灵及更广泛的联盟。她居住在首都的战士区，指引并派遣有能力的战士保卫他们的土地，抵御迫近的威胁。",al={"艾兰娜瑞所属阵营","艾兰娜瑞为谁效力","艾兰娜瑞的效忠对象"}},d7c0e558={q="艾兰娜瑞想要什么？",a="艾兰娜瑞寻求愿意守护卡利姆多、肃清腐化邪恶的老练战士。她派遣勇士消灭危险敌人，包括萨特沃卢斯·邪蹄；她也会将有潜力的新兵引荐给铁匠马希尔等技艺精湛的工匠，确保他们做好战斗准备。",al={"艾兰娜瑞需要什么","艾兰娜瑞的职责","艾兰娜瑞的动机"}},["16a563e6"]={q="艾兰娜瑞为何在达纳苏斯？",a="艾兰娜瑞驻守达纳苏斯的战士区，担任暗夜精灵首都战士们的导师和协调者。从这个军事据点，她可以轻松评估来访冒险者的实力，并派遣他们前往最需要其刀剑之处。",al={"艾兰娜瑞为何在这里","艾兰娜瑞为何在战士区","艾兰娜瑞所在位置的原因"}}},fp="8,179,25.204.0,25.276.0,16.132.0,26.112.0,32.113.0,56.189.0,21.120.0,44.86.0"}
P.entries["npc:elder-bloodhoof"] = {n="血蹄长者",s="春节期间，血蹄长者安歇在莫高雷血蹄村的正北方。血蹄部族尊他为守护先祖的灵魂。",h="春节期间，血蹄长者安歇在莫高雷血蹄村的正北方。血蹄部族尊他为守护先祖的灵魂。",kw={"先祖","血蹄村","血蹄长者","春节","莫高雷","赤色石","牛头人之魂"},ang={["class:Shaman"]="作为萨满祭司，你可以向血蹄长者寻求指引，他是一位指引并庇护后裔的先祖之魂。",["race:Tauren"]="作为牛头人，你可以向血蹄长者致敬，以此尊崇自己的部族血脉。他是Bloodhoof tribe敬奉的一位先祖。"},sec={{t="先祖之魂",b="血蹄长者在血蹄村附近守望着他的族人。牛头人尊他为与自身血脉及莫高雷平原紧密相连的灵魂。春节期间，心怀敬意的旅人前来寻求他的智慧，接受他的祝福。他的存在让已故酋长与部族先辈的指引始终伴随着血蹄部族。"}},faq={{q="血蹄长者是谁？",a="血蹄长者是一位牛头人幽魂，安歇在莫高雷血蹄村的正北方。血蹄 部族尊他为先祖之一，并在春节期间寻求他的智慧。",al={"血蹄长者背景故事","血蹄村外的幽灵是谁","血蹄长者身份"}},{q="何时能见到血蹄长者？",a="每年春节期间，你都能见到血蹄长者，他会现身赐予祝福。",al={"血蹄长者在哪里","血蹄长者不见了","如何找到血蹄长者"}},{q="他与血蹄村有何联系？",a="血蹄长者安歇在血蹄村的正北方，守望着血蹄部族。在牛头人的传统中，先祖之魂始终与后裔生活和聚集的地方紧密相连。",al={"他为何在血蹄村附近","血蹄长者与凯恩的关系"}}},fp="15,162,23.342.0,23.197.0,33.76.0,44.193.0"}
P.entries["npc:elder-bronzebeard"] = {n="铜须长者",s="春节期间，铜须长者会出现在铁炉堡的秘法区。他的名字与统治这座城市的氏族同名，而他的土灵形态让人想起矮人那由岩石诞生的祖先。",h="春节期间，铜须长者会出现在铁炉堡的秘法区。他的名字与统治这座城市的氏族同名，而他的土灵形态让人想起矮人那由岩石诞生的祖先。",kw={"祖先","土灵","铜须长者","铁炉堡","春节","麦格尼","秘法区"},ang={["faction:Alliance"]="作为春节期间来到铁炉堡的联盟朝圣者，你可以拜访一位象征着矮人王国根基的长者。",["race:Dwarf"]="身为矮人，拜访铜须长者是一次难得的机会，让你得以窥见自己的土灵血脉。探险者协会正通过研究揭开更多秘密。"},sec={{t="秘法区的先祖",b="在铁炉堡秘法区的水池旁，铜须长者以土灵的形态现身。远古的土灵由泰坦用活体岩石铸造而成，后来才变成血肉之躯。矮人学者和探险家通过遍及卡兹莫丹及更远地区的考古发掘，才刚刚开始揭开自身起源的秘密。\n\n铜须长者与统治这座城市的氏族同名，他的形态表明，他可能是铜须部族的直系祖先。他的灵魂展现出，那些由岩石诞生的后裔如今已有多大的变化。"}},faq={{q="为什么铜须长者看起来像土灵，而不是普通的矮人？",a="矮人是土灵的后裔，而土灵是泰坦用岩石创造的古老生灵。随着时间流逝，土灵变成了血肉之躯。铜须长者生活在遥远的过去，那时这种变化尚未发生，因此他的灵魂仍保留着土灵时期的岩石形态。",al={"铜须长者为什么是石头","铜须长者是土灵吗","铜须长者种族"}},{q="他与国王麦格尼·铜须有亲缘关系吗？",a="从他的名字和他在铁炉堡现身这一点来看，他应当是铜须氏族一位备受尊崇的祖先，这一血脉在麦格尼国王的统领下统治着这座城市。古老家谱中确切的支系关系早已湮没在历史之中。",al={"他是麦格尼的祖先吗","麦格尼·铜须的亲属","铜须家谱"}},{q="铜须长者为什么会在铁炉堡？",a="春节期间，长者的灵魂会在艾泽拉斯各地现身，向旅人传授智慧、赐予祝福。铜须长者出现在铁炉堡秘法区宁静的水池旁，那里是矮人法师和学者聚集的地方。",al={"铜须长者在这里做什么","铜须长者在哪里","秘法区幽灵"}}},fx={f31842b8={q="铜须长者是谁？",a="铜须长者是一位古老的土灵之魂，徘徊在铁炉堡的秘法区。他显现的是先祖由泰坦铸造的岩石形体，而非血肉之躯，象征着矮人一族深远的先祖根源与绵延不绝的血脉。",al={"铜须长者是谁","铜须长者的身份","铜须长者是什么"}},["7b1c25c3"]={q="铜须长者站在哪一方？",a="作为一位备受尊崇的先祖，铜须长者站在铁炉堡腹地，静静守望着这座矮人都城。如同所有春节长者，他不介入凡人的战争，向前来拜访的旅人与朝圣者致意，无论他们隶属哪面旗帜。",al={"铜须长者的阵营","铜须长者站在哪一方","铜须长者属于联盟吗"}},a81f3e52={q="铜须长者想要什么？",a="铜须长者只愿与敬奉古老传统的人们交流，别无所求。作为一位游荡至今的古老灵魂，他迎接朝圣者，并在心怀敬意的访客面前显现。",al={"铜须长者想要什么","铜须长者的动机","铜须长者为什么想交谈"}}},fp="17,198,31.502.0,75.262.0,40.198.0,38.230.0"}
P.entries["npc:elder-darkcore"] = {n="暗灵长者",s="春节期间，暗灵长者守望在幽暗城上方的王座厅中。他缅怀世间的先祖，并为前来致敬的旅人赐福。",h="春节期间，暗灵长者守望在幽暗城上方的王座厅中。他缅怀世间的先祖，并为前来致敬的旅人赐福。",kw={"先祖","先祖硬币","达克考尔","暗灵长者","春节","洛丹伦废墟","王座厅","幽暗城"},ang={["faction:Alliance"]="身为联盟旅人，你必须避开首都废墟周围的高等级被遗忘者哨兵和皇家卫兵，才能抵达暗灵长者身边。因此，对你而言，他是节日期间最危险的拜访对象之一。",["race:Undead"]="身为Undead，你会发现暗灵长者距离幽暗城通往地表的升降梯仅有几步之遥，就站在洛丹伦王国覆灭之处的石板上。"},sec={{t="王座厅中的英灵",b="春节期间，古老的长者们会现身于艾泽拉斯各地，与旅人分享智慧。暗灵长者守望在洛丹伦废墟的王座厅中，就在幽暗城入口的正上方。泰瑞纳斯·米奈希尔二世国王就倒在那片染血的地板上。深入被遗忘者领地腹地致敬的人，会获得一枚先祖硬币和他的祝福。"}},faq={{q="暗灵长者是谁？",a="春节期间，暗灵长者会以受人敬仰的先祖之灵的身份现身。在幽暗城上方的王座厅中，他为来访者赐福，并赠予先祖硬币。",al={"暗灵长者","暗灵","暗灵是谁"}},{q="在哪里可以找到暗灵长者？",a="暗灵长者在首都残破的王座厅中等候，那里位于幽暗城入口上方的洛丹伦废墟中。",al={"暗灵在哪","暗灵位置","幽暗城长者"}},{q="暗灵长者对联盟有敌意吗？",a="暗灵长者保持中立，欢迎前来向他致敬的旅人。联盟访客必须避开在洛丹伦废墟的被遗忘者据点中巡逻的敌对卫兵。",al={"联盟能与暗灵交谈吗","暗灵属于部落吗","幽暗城春节联盟"}},{q="向暗灵长者致敬能获得什么？",a="向暗灵长者致敬可以获得一枚先祖硬币。",al={"暗灵奖励","暗灵任务"}}},fx={["3a0e846b"]={q="暗灵长者效忠于哪一方？",a="暗灵长者不参与当今部落与联盟的冲突。作为参与春节庆典、受人敬仰的先祖之魂，他超然于凡俗争斗，欢迎任何尊敬地前来拜访的旅人，不论他们追随哪一面旗帜。",al={"暗灵长者所属阵营","暗灵长者属于部落还是联盟","暗灵的效忠对象"}},["32c6e8a4"]={q="暗灵长者想要什么？",a="在春节期间，暗灵长者希望分享先祖的古老智慧与祝福。他等待旅人向往昔致敬，并向那些尊崇他悠久记忆的人赐予祝福和长者传承的信物。",al={"暗灵长者想要什么","暗灵长者的目的","为何拜访暗灵长者"}},e5445cfd={q="暗灵长者为何在洛丹伦废墟？",a="作为艾泽拉斯各地庆祝春节的一部分，暗灵长者现身于幽暗城上方已成废墟的王座大厅。古老先祖的灵魂会在艾泽拉斯那些历史深厚、饱经哀伤之地显现，让凡人即便身处覆灭的王国，也能与先祖的记忆交流。",al={"暗灵长者为何在幽暗城","洛丹伦废墟与暗灵长者","暗灵长者所在位置的背景"}}},fp="14,179,27.292.0,22.181.0,32.114.0,42.177.0,43.59.0"}
P.entries["npc:elder-goldwell"] = {n="金井长者",s="春节期间，金井长者会出现在卡拉诺斯附近。这位古老的土灵之魂追忆着现代矮人文明的起源。",h="春节期间，金井长者会出现在卡拉诺斯附近。这位古老的土灵之魂追忆着现代矮人文明的起源。",kw={"先祖","丹莫罗","土灵","金井长者","金井","卡拉诺斯","春节"},ang={["faction:Alliance"]="作为途经卡拉诺斯的联盟旅人，你可以寻找金井，向他致敬，并接受传统的好运祝福。",["race:Dwarf"]="作为矮人，与金井长者相见，让你有难得的机会了解自身源于岩石的传承，以及将现代铁炉堡与土灵相连的血脉。"},sec={{t="土灵之魂",b="在卡拉诺斯附近，金井长者以半透明的土灵之魂形态守望着积雪的山坡。他的石质身躯让人想起铜须氏族那些由泰坦铸造的先祖。在祭祖庆典期间，旅人可以来到他面前，向这份传承致敬。"}},faq={{q="金井长者是谁？",a="金井长者是一位土灵先祖之魂，会出现在丹莫罗的卡拉诺斯附近。在应季的祭祖活动期间，旅人可以向矮人的先辈表达敬意。",al={"金井长者身份","金井是谁","金井背景故事"}},{q="金井长者在哪里？",a="金井长者站在丹莫罗的卡拉诺斯外，通常就在当地旅店和人群聚集处附近。",al={"金井长者位置","哪里能找到金井长者","寻找金井"}},{q="为什么金井长者看起来像土灵，而不是矮人？",a="矮人的祖先可以追溯到泰坦创造的土灵，他们有着岩石般的皮肤。作为一位纪念先辈的古老灵魂，金井保留着土灵的形态，而非活着的矮人所拥有的血肉之躯。",al={"为什么金井是土灵","金井是土灵吗","金井岩石矮人"}}},fp="14,146,23.252.0,22.171.0,32.101.0,65.201.0"}
P.entries["npc:elder-graveborn"] = {n="灰石长者",s="春节期间，灰石长者在布瑞尔附近迎接旅人。这位先祖之魂向他们致意，并指引朝圣者前往洛丹伦北部的其他长者所在之处。",h="春节期间，灰石长者在布瑞尔附近迎接旅人。这位先祖之魂向他们致意，并指引朝圣者前往洛丹伦北部的其他长者所在之处。",kw={"先祖","布瑞尔","土灵","灰石长者","灰石","春节","提瑞斯法林地"},ang={["faction:Alliance"]="作为联盟朝圣者，你必须绕过布瑞尔，才能在不引起被遗忘者守卫和巡逻队注意的情况下抵达灰石身边。",["race:Undead"]="身为被遗忘者，你可以在布瑞尔与幽暗城之间的道路上找到灰石。他的存在令人忆起艾泽拉斯尚未遭受Scourge或瘟疫侵染的远古岁月。"},sec={{t="提瑞斯法的幽魂",b="春节期间，灰石长者在布瑞尔东南方不远处迎接旅人。这位幽灵长者伫立在提瑞斯法林地阴魂萦绕的林间，附近便是被遗忘者的城镇。尽管王国饱受动荡，灰石仍向朝圣者送上平和的问候与先祖的智慧。他还指引他们前往幽暗城、瑟伯切尔以及瘟疫之地各处的幽魂所在之地。"}},faq={{q="灰石长者是谁？",a="灰石长者是一位在春节期间现身的先祖幽魂。他在提瑞斯法林地、布瑞尔东南方不远处，为旅人送上节日的祝福。",al={"灰石长者传说","灰石是谁","布瑞尔幽魂长者"}},{q="他为什么在提瑞斯法林地？",a="春节期间，先祖之魂在艾泽拉斯各地聚集，向昔日的英雄和共同的传承致敬。灰石长者守望着布瑞尔外的土地。",al={"为什么在布瑞尔","灰石长者在哪里"}},{q="联盟冒险者能与他交谈吗？",a="可以。节日长者欢迎双方阵营的旅人。联盟旅人应小心接近：灰石就在被遗忘者的布瑞尔镇附近。",al={"联盟能与灰石交谈吗","联盟布瑞尔长者"}},{q="他向旅人提供什么消息？",a="灰石长者指引朝圣者前往当地其他幽魂所在之处。他提到了幽暗城、银松森林的瑟伯切尔、圣光之愿礼拜堂、哭泣之洞和通灵学院。",al={"灰石长者指路","灰石语录"}}},fp="15,168,20.374.0,23.156.0,29.161.0,38.166.0,41.168.0"}
P.entries["npc:elder-morningdew"] = {n="晨露长者",s="晨露长者是一位古老的暗夜精灵之魂，在春节期间现身于千针石林。她在闪光平原干旱的峡谷与干涸的盐滩间，为前来寻访她的旅人赐予智慧与先祖的祝福。",h="晨露长者是一位古老的暗夜精灵之魂，在春节期间现身于千针石林。她在闪光平原干旱的峡谷与干涸的盐滩间，为前来寻访她的旅人赐予智慧与先祖的祝福。",kw={"先祖","长者","晨露长者","幽灵","春节","晨露","暗夜精灵","千针石林"},ang={["race:NightElf"]="对kaldorei而言，寻访晨露这样的古老长者是一项表达崇敬的神圣职责，将如今的暗夜精灵与受人敬仰的先辈之魂联系起来。",["race:Tauren"]="Tauren对先祖之魂怀有深深的敬意，因此，与卡利姆多各地长者的相遇，自然延续了他们在文化中对先辈智慧的崇敬。"},sec={{t="节日中受敬仰的灵魂",b="春节期间，受人敬仰的先祖之魂在卡利姆多和东部王国各地显现，颂扬智慧、传承与和平。晨露长者便是其中之一，她来到千针石林，迎接前来致敬的朝圣者。她不受阵营或凡世纷争的束缚，任何怀着敬意前来聆听她的教诲、接受她的祝福的冒险者，都能获赠她的先祖硬币。"}},faq={{q="晨露长者是谁？",a="晨露长者是一位暗夜精灵先祖之魂，每年都会在春节期间显现。她在千针石林等候联盟与部落的旅人前来致敬。",al={"晨露长者背景故事","晨露是谁","晨露身份"}},{q="为什么要寻访她？",a="冒险者在春节期间寻访她，向先祖表达敬意，并因敬奉她的灵魂而获赠一枚先祖硬币和智慧的祝福。",al={"为什么寻找晨露长者","晨露的作用","春节长者"}},{q="她属于联盟还是部落？",a="与所有春节长者一样，晨露长者在凡世的政治纷争中保持中立。联盟与部落的冒险者都可以平和地走近她，向她致敬。",al={"晨露是否敌对","晨露长者阵营","部落能否与晨露交谈"}}},fp="16,147,33.371.0,24.116.0,39.141.0,41.128.0"}
P.entries["npc:elder-obsidian"] = {n="黑曜石长者",s="春节期间，黑曜石长者会现身于银松森林的瑟伯切尔。这位土灵先祖之魂在被遗忘者占据的墓地间迎接旅人，传授古老的智慧，赐予祝福。",h="春节期间，黑曜石长者会现身于银松森林的瑟伯切尔。这位土灵先祖之魂在被遗忘者占据的墓地间迎接旅人，传授古老的智慧，赐予祝福。",kw={"先祖","先祖硬币","土灵","黑曜石长者","春节","瑟伯切尔","银松森林"},ang={["faction:Alliance"]="身为联盟朝圣者，你必须谨慎前行，才能在被遗忘者的定居点瑟伯切尔见到黑曜石长者。",["race:Dwarf"]="身为矮人，与黑曜石长者这样的土灵之魂交谈，能让你窥见岩石先祖的远古岁月。"},sec={{t="瑟伯切尔的灵魂",b="春节期间，黑曜石长者在瑟伯切尔迎接旅人。他的土灵之魂将艾泽拉斯的古老传承带到了银松森林。周围的墓穴由被遗忘者占据，凶野的狼人也威胁着这片森林。然而，黑曜石仍平和地欢迎各方旅人，为前来求教的人送上先祖硬币与古老的祝福。"}},faq={{q="黑曜石长者是谁？",a="黑曜石长者是一位古老的土灵之魂，会在春节期间现身于银松森林。他迎接那些敬重艾泽拉斯先祖传承的旅人。",al={"黑曜石长者背景故事","黑曜石是谁","瑟伯切尔长者"}},{q="在哪里能找到黑曜石长者？",a="黑曜石长者位于瑟伯切尔的墓地中，那是银松森林中部道路旁的一座被遗忘者村落。",al={"黑曜石长者位置","黑曜石在哪里","寻找黑曜石长者"}},{q="为什么一位土灵长者会出现在银松森林？",a="春节期间，古老的长者之魂会在艾泽拉斯各地现身，分享先祖的智慧。黑曜石长者在古老的墓地间与旅人相会，超然于当地的领土纷争之外。",al={"黑曜石为什么在银松森林","银松森林的土灵"}},{q="联盟冒险者能与黑曜石长者交谈吗？",a="可以。节日期间的长者欢迎各个阵营的旅人。瑟伯切尔由被遗忘者占据，因此联盟冒险者必须穿过附近敌对守卫的防线，才能抵达黑曜石长者身边。",al={"联盟能否拜访黑曜石长者","黑曜石长者对联盟友善"}}},fp="14,190,25.359.0,22.163.0,34.125.0,54.186.0,51.180.0"}
P.entries["npc:elder-runetotem"] = {n="符文图腾长者",s="春节期间，符文图腾长者会出现在杜隆塔尔的剃刀岭外。这位牛头人之灵为前来寻访她的旅人赐予智慧与祝福。",h="春节期间，符文图腾长者会出现在杜隆塔尔的剃刀岭外。这位牛头人之灵为前来寻访她的旅人赐予智慧与祝福。",kw={"先祖硬币","杜隆塔尔","符文图腾长者","春节","剃刀岭","符文图腾","牛头人幽灵"},ang={["faction:Horde"]="身为部落的一员，你可以在剃刀岭外找到符文图腾长者。她的到来体现了杜隆塔尔的兽人与莫高雷的牛头人之间的精神同盟。",["race:Tauren"]="身为牛头人，在远离莫高雷的地方遇见符文图腾部族一位德高望重的先祖，会让你想起Shu'halo的灵魂在各地守护着他们的盟友。"},sec={{t="杜隆塔尔的灵魂",b="符文图腾长者出现在剃刀岭旁，远离莫高雷草木丰茂的平原与神圣的墓地。她的到来，将舒哈洛的古老传统带到了部落位于无尽之海沿岸的家园。"},{t="敬奉先祖",b="春节期间，伟大的领袖、萨满祭司与英雄的灵魂会出现在世界各地，与生者交流。符文图腾长者所承袭的家族之名，属于一个敬奉大地母亲、寻求灵魂交流的血脉。向她致敬的旅人会获得先祖信物与她的祝福。"}},faq={{q="符文图腾长者是谁？",a="符文图腾长者是一位牛头人先祖，在春节期间出现在杜隆塔尔的剃刀岭附近。她迎接旅人，并赐予先祖的祝福。",al={"符文图腾长者的故事","剃刀岭的牛头人幽灵是谁","符文图腾幽灵"}},{q="为什么杜隆塔尔会有一位牛头人之灵？",a="大多数牛头人先祖之灵都扎根于莫高雷，但春节的灵魂会游历卡利姆多和东部王国。她在剃刀岭现身，让途经杜隆塔尔的部落旅人得以向大地母亲子嗣的智慧致敬。",al={"符文图腾为什么在剃刀岭","杜隆塔尔牛头人幽灵"}},{q="她与符文图腾部族有什么联系？",a="符文图腾长者承袭了符文图腾氏族之名，这一显赫的牛头人血脉以萨满祭司、灵魂向导以及与自然世界的联系而闻名。",al={"符文图腾部族长者","符文图腾家族"}},{q="与她交谈能获得什么？",a="在春节期间与符文图腾长者交谈，既是对她的缅怀，也能获得一枚先祖硬币和来自灵魂的临时祝福。",al={"符文图腾长者给予什么","符文图腾奖励"}}},fp="15,139,19.202.0,16.297.0,23.155.0,42.252.0,53.152.0,34.146.0"}
P.entries["npc:elder-skyseer"] = {n="星灵长者",s="星灵长者是一位牛头人先祖的灵魂，居于千针石林乱风岗高耸的崖顶。作为从灵魂世界归来的受敬重的长者，他注视着部落仍在继续的旅程，也始终与族人的安息之地保持着深厚的联系。",h="星灵长者是一位牛头人先祖的灵魂，居于千针石林乱风岗高耸的崖顶。作为从灵魂世界归来的受敬重的长者，他注视着部落仍在继续的旅程，也始终与族人的安息之地保持着深厚的联系。",kw={"先祖","星灵长者","乱风岗","赤色石","牛头人幽灵","千针石林"},ang={["class:Shaman"]="萨满祭司是与元素和灵魂沟通的灵性使者，他们在星灵长者身上看到了先祖历久不衰的智慧，这些先祖仍在守望着生者。",["race:Tauren"]="对牛头人而言，与星灵长者相遇就是与先祖直接交流，体现了赤色石与莫高雷各处平原上传承的对灵魂的敬畏。"},sec={{t="乱风岗的灵魂",b="星灵长者徘徊在乱风岗这片饱受疾风吹拂的台地聚落，脚下便是千针石林的盐碱峡谷。乱风岗的牛头人在哨站险峻的桥梁和木制平台间忙碌，而星灵长者作为一位已越过生死帷幕的先祖，守望着这片天地。他如同先祖留下的明灯，为寻求先辈智慧的旅人指引方向，并为尊重古老传统的人们赐下祝福。"},{t="与先祖之地的羁绊",b="虽然星灵长者的灵魂常在风蚀的石柱间显现，但他也是牛头人历代先祖中的一员，他们的族人敬奉莫高雷的神圣土地，那里的赤色石先祖之灵守护着各个部族。星灵长者这样的灵魂表明，对牛头人而言，物质世界与先祖之灵之间的帷幕依然十分薄弱，先祖通过追思与仪式指引着后世子孙。"}},faq={{q="星灵长者是谁？",a="星灵长者是一位牛头人先祖之灵，在千针石林的乱风岗显现。他是备受尊崇的长者之一，这些长者的灵魂守望着如今的旅人，为前来寻访的人们提供先祖的指引。",al={"星灵长者的故事","星灵长者是谁","星灵长者非玩家角色"}},{q="星灵长者为什么是幽灵？",a="他是一位早已离开凡世的古老先祖。牛头人的文化与先辈保持着深厚的灵魂联系，一些德高望重的长者会以灵魂形态驻留或归来，指引生者。",al={"星灵长者为什么死了","星灵长者死了吗","乱风岗牛头人幽灵"}},{q="他与莫高雷有什么联系？",a="与所有牛头人先祖一样，星灵长者受到族人的敬奉，他们的故乡是莫高雷，那里的赤色石先祖之灵守护着各个部族。不过，他自己的灵魂显现在千针石林的乱风岗。",al={"星灵长者赤色石","星灵长者与莫高雷的联系"}},{q="在哪里可以找到星灵长者？",a="星灵长者位于千针石林的乱风岗，徘徊在远高于谷底、设有防御工事的台地聚落之上。",al={"星灵长者的位置","寻找星灵长者","星灵长者在哪里"}}},fx={e54499fb={q="星灵长者属于哪一方？",a="星灵长者不介入生者之间的战争。他作为一位徘徊于乱风岗风吹日晒的台地上方的牛头人先祖之魂，为任何尊崇他的旅人，无论其属于部落还是联盟，提供来自冥界的先祖指引与智慧。",al={"星灵长者的阵营","星灵长者属于部落吗","星灵长者的效忠对象"}}},fp="13,156,25.289.0,27.364.0,21.137.0,29.175.0,34.192.0,31.115.0"}
P.entries["npc:elder-starweave"] = {n="星纹长者",s="春节期间，星纹长者以暗夜精灵先祖之魂的形态安歇于奥伯丁。她在黑海岸沿岸向朝圣者传授古老的智慧。",h="春节期间，星纹长者以暗夜精灵先祖之魂的形态安歇于奥伯丁。她在黑海岸沿岸向朝圣者传授古老的智慧。",kw={"先祖","奥伯丁","先祖硬币","黑海岸","星纹长者","春节","星纹"},ang={["class:Druid"]="身为参与节庆的德鲁伊，你或许能从星纹对群星的感悟中，听出塞纳里奥教义中关于新生、记忆以及与自然和谐共处的思想。",["race:NightElf"]="身为一名在黑海岸冒险的暗夜精灵，你遇见星纹长者，与绵延久远的先祖血脉建立联系，那些先祖曾在远古的灾变中仰望Elune与群星。"},sec={{t="奥伯丁的明灯",b="在奥伯丁，星纹长者以缥缈幽魂的形态出现在沿海的民居之间。塞纳里奥议会与卡利姆多各族都将她奉为先祖。旅人途经这座港口，前往内陆或渡海远行，但驻足于她面前的人会得到先祖的祝福。她谈起群星，说它们如今的轨迹已与往昔不同，并将它们视为明灯，为后世带去希望与坚毅。"}},faq={{q="星纹长者是谁？",a="春节期间，星纹长者以暗夜精灵先祖之魂的形态出现在奥伯丁。她迎接旅人，传授古老的智慧，并赠予先祖硬币。",al={"星纹长者的传说","星纹是谁","长者星纹"}},{q="在哪里能找到星纹长者？",a="在奥伯丁附近的黑海岸海滨，可以找到星纹长者。",al={"星纹长者在哪里","星纹长者位置","星纹地点"}},{q="她为何以灵魂形态现身？",a="星纹长者是一位备受敬重的先祖，在春节期间以灵魂形态现身，让生者得以向那些塑造了暗夜精灵遥远过去的先人致敬。",al={"星纹为何是幽灵","星纹死了吗","为何是幽灵"}},{q="部落玩家能与她交谈吗？",a="可以。春节期间受到敬奉的先祖长者欢迎来自各方的旅人。部落冒险者穿行奥伯丁时务必小心，因为这是一座亲近联盟的港口。",al={"部落能拜访星纹吗","部落星纹长者"}}},fp="15,162,21.458.0,23.171.0,35.78.0,32.181.0,31.173.0"}
P.entries["npc:eleanor-shackleton"] = {n="Eleanor Shackleton",s="Eleanor Shackleton在布瑞尔西南方的提瑞斯法林地树林中扎营。这位热衷野外生活的被遗忘者女子不留在镇上或幽暗城，而是向旅人传授荒野生存与野外技艺。当地还有其他被遗忘者与她同姓，这或许是他们在瘟疫降临前的生活留下的联系。",h="Eleanor...",kw={"布瑞尔","露营入门","埃莉诺·沙克尔顿","沙克尔顿","棍棒与骨头","冒险者","广阔的野外","提瑞斯法林地"},ang={["profession:Cooking"]="身为厨师，你可以向Eleanor学习如何在野外生起营火，远离文明聚落的炉灶烹制食物。她的营地是旅途中厨师们的一处实用落脚点。",["race:Undead"]="身为被遗忘者的一员，学会在没有熟悉的舒适条件下于荒野生存至关重要。Eleanor帮助新近复生的同胞适应提瑞斯法艰苦的生活。"},sec={{t="林地向导",b="Eleanor Shackleton在布瑞尔西南方阴魂游荡的树林中扎营，远离幽暗城。新近苏醒的被遗忘者常常前往这些聚居地，她却教导旅人如何在提瑞斯法遭受枯萎侵蚀的土地上生存。她传授的技艺包括搭建营地、收集柴火，以及远离文明聚落的炉火与厨房时，如何继续从事专业活动。"},{t="前生的牵绊",b="Eleanor Shackleton与住在幽暗城魔法区的皮尔斯·沙克尔顿和萨曼塔·沙克尔顿同姓。在洛丹伦支离破碎的废墟中，姓氏可能是亡灵与生前生活仅存的纽带。无论Eleanor、Pierce和Samantha是近亲，还是仅有共同的祖先，他们都在这个遭受枯萎侵蚀的王国中，以各自的方式为被遗忘者效力。"}},faq={{q="在哪里能找到埃莉诺·沙克尔顿？",a="埃莉诺·沙克尔顿在提瑞斯法林地布瑞尔西南方的树林中扎营，营地远离铺石主路。",al={"埃莉诺·沙克尔顿位置","埃莉诺在哪","沙克尔顿地点"}},{q="埃莉诺·沙克尔顿向冒险者传授什么？",a="埃莉诺·沙克尔顿传授荒野生存技艺，包括露营、采集食物，以及在野外从事专业活动。",al={"埃莉诺任务","埃莉诺做什么","提瑞斯法露营任务"}},{q="埃莉诺与洛丹伦其他姓沙克尔顿的人有亲缘关系吗？",a="埃莉诺·沙克尔顿与幽暗城的皮尔斯·沙克尔顿和萨曼塔·沙克尔顿同姓，这表明他们可能在天灾军团吞噬王国之前就是亲人。",al={"皮尔斯·沙克尔顿亲属","萨曼塔·沙克尔顿","沙克尔顿家族背景"}},{q="她为什么在布瑞尔外扎营，而不住在镇上？",a="埃莉诺·沙克尔顿传授野外技艺和荒野生存之道。她在树林中扎营，便能在旅人需要这些本领的地方与他们相遇。",al={"为何在布瑞尔外扎营","埃莉诺·沙克尔顿营地"}}},fp="18,269,21.353.0,21.378.0,36.107.0,47.116.0,53.186.0,60.139.0"}
P.entries["npc:electrocutioner-6000"] = {n="电刑器6000型",s="在诺莫瑞根的Launch Bay，电刑器6000型守卫着上层平台。这台蜘蛛坦克为麦克尼尔·瑟玛普拉格及其麾下遭受辐射的麻风侏儒而战。",h="在诺莫瑞根的Launch Bay，电刑器6000型守卫着上层平台。这台蜘蛛坦克为麦克尼尔·瑟玛普拉格及其麾下遭受辐射的麻风侏儒而战。",kw={"电刑器","诺莫瑞根","发射间","蜘蛛坦克","瑟玛普拉格","车间钥匙"},ang={["faction:Alliance"]="身为盟友，你知道，要取得车间钥匙，突破Launch Bay并摧毁电刑器6000型至关重要。在设法解放诺莫瑞根时，这把钥匙能让你绕过危险的前部通道。",["profession:Engineering"]="身为工程师，即便电刑器6000型正用高压电流攻击你，你仍会惊叹于它的底盘所能驾驭的强大电力。",["race:Gnome"]="身为流亡铁炉堡的侏儒，你或许会将电刑器6000型视为对自身技艺的侮辱：在瑟玛普拉格的统治下，一台侏儒战争机器竟将矛头指向了自己的同胞。"},sec={{t="瑟玛普拉格的电击机器",b="诺莫瑞根沦陷后，麦克尼尔·瑟玛普拉格及其麾下遭受辐射的麻风侏儒控制了城中的战争机器。电刑器6000型守卫着Launch Bay的上层平台。它用高压电流攻击入侵者。"},{t="车间钥匙",b="电刑器6000型守卫着车间钥匙，这把钥匙能打开通往诺莫瑞根车间的后门。击倒这台机器，拿到钥匙，就能更快地深入城中。"}},faq={{q="在哪里能找到电刑器6000型？",a="电刑器6000型位于一处高架走道平台上，俯瞰着诺莫瑞根的发射台。",al={"电刑器6000型位置","电刑器在哪","寻找电刑器6000型"}},{q="谁在驾驶电刑器6000型？",a="关于诺莫瑞根沦陷的记载并未提及驾驶员的名字。电刑器6000型为麦克尼尔·瑟玛普拉格及其麾下的麻风侏儒而战。",al={"谁驾驶电刑器6000型","电刑器驾驶员"}},{q="这台机器为何如此不稳定？",a="它的装甲底盘传导着高压电流，并将电流释放到任何靠近者身上。这使电刑器6000型成为发射台危险的守卫。",al={"为何释放电击","电刑器原型","瑟玛普拉格的设计"}},{q="击败电刑器6000型为何对探险者如此重要？",a="电刑器6000型守卫着车间钥匙，这把钥匙能打开通往诺莫瑞根深层工程区域的后门。有了钥匙，就能更快地穿行于这些设施之间。",al={"车间钥匙","为何击杀电刑器","电刑器6000型掉落"}},{q="电刑器是自动机械还是载具？",a="电刑器6000型是一台机械坦克，也就是侏儒制造的、拥有蜘蛛般机械足的装甲战争机器。如今，它与那些试图解放诺莫瑞根的人为敌。",al={"电刑器是机器人吗","电刑器蜘蛛坦克类型"}}},fx={cad4dd7a={q="电刑器6000型是什么？",a="电刑器6000型是一台超强充能的机械蜘蛛坦克，守卫着诺莫瑞根的发射台。它周身迸射着高压电流，为麦克尼尔·瑟玛普拉格和追随他的麻风侏儒而战。",al={"电刑器6000型是谁","电刑器6000型是什么","电刑器6000型的背景故事"}},["48c81a6d"]={q="电刑器6000型站在哪一方？",a="这台战争机器完全效命于麦克尼尔·瑟玛普拉格及其麾下疯狂的麻风侏儒。它狂热地捍卫着瑟玛普拉格对诺莫瑞根的统治，消灭任何胆敢靠近发射台的石腭怪、联盟特工或部落闯入者。",al={"电刑器的阵营","电刑器为谁效力","电刑器效忠谁"}},["5513927c"]={q="电刑器6000型想要什么？",a="这台坦克服务于麦克尼尔·瑟玛普拉格的狂妄野心。它的职责是用电流击杀并清除一切胆敢进入诺莫瑞根深处的擅入者。",al={"电刑器6000型的目标","电刑器想要什么","电刑器的动机"}},e5de5943={q="电刑器6000型为什么在发射台？",a="这台坦克驻守在发射台上层的高架通道，守卫着空中走道，封锁通往设施深处的道路。它携带着车间钥匙，以重火力把守关口，阻挡任何试图深入瑟玛普拉格据点核心的人。",al={"电刑器为什么在这里","电刑器为什么在发射间","电刑器的用途"}},["06482735"]={q="电刑器6000型为何令人畏惧？",a="这台机器以致命的威力而臭名昭著。它的装甲机体传导着高压电流，向任何靠近者释放，使它成为阻挡入侵者深入瑟玛普拉格要塞核心的最危险守卫之一。",al={"电刑器为何令人畏惧","电刑器的名声","电刑器为何出名"}}},fp="20,172,30.241.0,16.186.0,44.96.0,36.146.0,31.164.0,66.174.0,49.142.0"}
P.entries["npc:elling-trias"] = {n="埃林·提亚斯",s="在暴风城的贸易区，埃林·提亚斯在自家的奶酪店里招呼顾客。轻松的闲谈背后，他的情报生意横跨各个大陆。",h="在暴风城的贸易区，埃林·提亚斯在自家的奶酪店里招呼顾客。轻松的闲谈背后，他的情报生意横跨各个大陆。",kw={"伊莱恩·提亚斯","埃林·提亚斯","马迪亚斯·肖尔","失踪的使节","si:7","暴风城","贸易区","提亚斯奶酪坊","泰里恩"},ang={["class:Rogue"]="身为潜行者，你知道奶酪店可以成为理想的情报交接点。埃林的店靠近旧城区，加上他与马迪亚斯·肖尔的密切关系，使这里成为暴风城地下世界的一个固定据点。",["faction:Alliance"]="身为联盟的一员，你可以信赖埃林，让他悄悄搜集从塞拉摩到壁炉谷的传闻，帮助王国抵御内部的威胁。"},sec={{t="奶酪大师",b="埃林·提亚斯与妻子Elaine、儿子阿班一起，在贸易区售卖上好的奶酪。他向顾客兜售整轮奶酪，与镇民愉快地攀谈。然而，熟悉这家店的人都明白，提亚斯奶酪坊也是暴风城最可靠的掩护据点之一。城中络绎不绝的商贸往来，让特工、廷臣和冒险者得以避开城市卫兵的耳目，低声交换消息。"},{t="密语之网",b="埃林·提亚斯的线人与盟友遍布远方，远超寻常店主所能企及的范围。他的人脉包括SI:7的马迪亚斯·肖尔、德拉维主教等教会人士，以及夜色镇、塞拉摩岛和遥远的瘟疫之地壁炉谷附近的特工。因此，每当拦路劫匪或乡间隐秘动向的传闻出现时，提亚斯往往能在王室察觉之前，将这些线索拼凑起来。"},{t="失踪的外交官",b="埃林·提亚斯帮助调查者寻找一位在前往塞拉摩的航程中失踪的高级外交官。他指引他们去找自己的联络人，其中包括一位已疏远的特工乔贞，以及他的老朋友泰里恩。他们追查的线索揭露了迪菲亚潜行者在绑架事件中的作用。在机敏的言辞与愤世嫉俗的调侃之下，埃林看出这场阴谋深深牵涉着暴风城的贵族阶层。"}},faq={{q="埃林·提亚斯是谁？",a="埃林·提亚斯在暴风城的贸易区经营着一家家族奶酪店。他也是一位经验丰富的情报掮客，与SI:7、教会以及艾泽拉斯各地的偏远前哨都有联系。",al={"埃林是谁","埃林·提亚斯身份","提亚斯奶酪商人"}},{q="他的奶酪店在哪里？",a="提亚斯奶酪坊位于暴风城的贸易区，沿运河外侧的河墙而建，靠近与旧城区的交界处。",al={"提亚斯的奶酪位置","埃林·提亚斯在哪里","提亚斯暴风城店铺"}},{q="他与迪菲亚潜行者有什么联系？",a="埃林·提亚斯并非迪菲亚潜行者的成员。他通过线人网络追踪他们的动向，并帮助联盟冒险者查明他们在各种阴谋中扮演的角色，其中包括绑架一位王室外交官的事件。",al={"提亚斯迪菲亚","提亚斯是迪菲亚成员吗"}},{q="他是怎么认识马迪亚斯·肖尔的？",a="马迪亚斯·肖尔与埃林·提亚斯相识多年，每当官方渠道行不通时，就会向他求助。肖尔很不情愿开口，而埃林在自己的工作帮到肖尔和SI:7时，也总会发些牢骚。这家店让他们能绕过王室渠道，暗中打探消息。",al={"提亚斯与肖尔","提亚斯 军情七处","提亚斯是军情七处成员吗"}},{q="谁和他一起经营这家店？",a="埃林与妻子伊莱恩·提亚斯、儿子本·提亚斯一起经营提亚斯奶酪坊。他们共同维持着店铺的表象，让它看起来只是一门普通的家族生意。",al={"提亚斯家人","埃林·提亚斯妻子"}},{q="他在失踪的使节调查中起到了什么作用？",a="德拉维主教派调查者去找埃林·提亚斯，他的联络人包括旧识乔贞和泰里恩。他们提供的线索追踪了迪菲亚的动向，并揭露了是谁劫走了那位前往塞拉摩的外交官。",al={"失踪的使节 提亚斯","为什么去提亚斯的奶酪店"}}},fx={f0ad15b5={q="埃林·提亚斯效忠哪一方？",a="埃林虽然在暗中行事，却坚定地效忠暴风城和联盟。他常以贸易区一名不起眼的奶酪商人的身份掩饰自己的行动，暗中的关系却直通马迪亚斯·肖尔和SI:7。他积极对抗迪菲亚潜行者这样的颠覆势力，维护王国的安全。",al={"埃林·提亚斯是否效忠暴风城","埃林·提亚斯为谁效力","埃林·提亚斯是否属于联盟"}},fc385e9b={q="埃林·提亚斯想要什么？",a="表面上，埃林只想和家人一起售卖上好的奶酪。实际上，他希望通过搜集情报、铲除威胁王权的势力来维护暴风城的安全。危机出现时，他会动用遍布各地的人脉，悄然瓦解阴谋，避免引起民众恐慌。",al={"埃林·提亚斯的动机","埃林·提亚斯的目标是什么","埃林·提亚斯为何提供帮助"}},e76b2a1d={q="埃林·提亚斯为何在暴风城？",a="埃林在暴风城繁华的贸易区开展活动，因为一家生意兴隆的奶酪店能为间谍活动提供绝佳掩护。在柜台后面，他可以不露痕迹地交换密报、接待信使，并与王国各地的情报人员协调行动，而在旁人眼中，他只是个与妻儿一起看店的普通商人。",al={"埃林·提亚斯为何在暴风城","埃林为何留在暴风城","埃林·提亚斯在城中的目的"}}},fp="12,172,23.387.0,17.401.0,20.394.1,20.182.0,33.114.0,49.215.1,30.240.0,27.142.0,62.199.1"}
P.entries["npc:elu"] = {n="艾鲁",s="艾鲁是驻守在千针石林乱风岗上的见习风骑士。他渴望开始正式训练，翱翔天际，因此委托部落旅者从附近的巢穴中取回野生双足飞龙的卵。",h="艾鲁是驻守在千针石林乱风岗上的见习风骑士。他渴望开始正式训练，翱翔天际，因此委托部落旅者从附近的巢穴中取回野生双足飞龙的卵。",kw={"艾鲁","乱风岗","风巢","千针石林","风骑士","双足飞龙","双足飞龙的卵"},ang={["faction:Horde"]="为艾鲁采集双足飞龙的卵，能直接壮大部落的信使与运输网络，让遍布卡利姆多的偏远哨站保持空中往来。",["race:Tauren"]="对牛头人冒险者而言，协助艾鲁就是支持一位同族，让他在祖辈世居的峡谷上空，努力掌握驯养双足飞龙这门古老而重要的技艺。"},sec={{t="心切的学徒",b="乱风岗高踞于盐碱平原与峡谷谷底之上，艾鲁每天在这里照料聚落的飞行坐骑，梦想着自己也能展翅飞翔。作为一名年轻的牛头人学徒，他渴望加入风骑士大师的行列，巡逻卡利姆多高耸的台地。然而，在开始真正的飞行训练之前，他必须为兽栏补充新的双足飞龙，以此证明自己的能力，于是他派遣能干的冒险者前往风巢，从在那里筑巢的凶猛野生双足飞龙身边采集完好无损的卵。"}},faq={{q="艾鲁是谁？",a="艾鲁是一名驻守在千针石林乱风岗的牛头人见习风骑士，负责协助获取和饲养新坐骑，为部落的空中交通网提供支持。",al={"艾鲁 乱风岗","艾鲁是谁","牛头人学徒艾鲁"}},{q="艾鲁为什么需要双足飞龙的卵？",a="艾鲁的任务是为风骑士大师们补充兽栏中的双足飞龙。从新采集的卵开始饲养这些野兽，才能妥善训练它们，与它们建立羁绊，使它们成为部落值得信赖的坐骑。",al={"为什么需要双足飞龙的卵","艾鲁双足飞龙任务","艾鲁任务目标"}},{q="艾鲁派冒险者去哪里寻找卵？",a="他指引冒险者前往风巢，那是千针石林西部一处危险的台地，成群的野生双足飞龙在那里凶猛地守卫着巢穴。",al={"双足飞龙的卵在哪里","风巢在哪里","艾鲁的卵位置"}}},fx={["74f15e75"]={q="艾鲁效忠哪一方？",a="艾鲁效忠部落和他的牛头人同胞。他驻守在乱风岗的高崖之上，与部落的驭风者大师并肩工作，训练并供给飞行坐骑，以满足在卡利姆多各地旅行的需要。",al={"艾鲁的阵营","艾鲁是部落成员吗","艾鲁效忠谁"}},["3d25520c"]={q="艾鲁为什么在乱风岗？",a="艾鲁在乱风岗担任驭风者学徒。他留在这里协助飞行管理员，并努力赢得翱翔天空的资格；他的任务是从千针石林的高处巢穴获取新的双足飞龙，以供训练后交给部落骑手。",al={"艾鲁为什么在千针石林","艾鲁与乱风岗","艾鲁的目的"}},c552be8c={q="艾鲁隶属于谁？",a="艾鲁是部落驭风者大师的学徒。他听从那些培育卡利姆多飞翼双足飞龙的训练师和驯兽师的安排，在他们的指导下工作，希望开始接受正式的驭风者训练。",al={"艾鲁的师父","艾鲁为谁效力","艾鲁与驭风者"}}},fp="3,170,19.350.0,11.146.0,30.137.0,45.115.0"}
P.entries["npc:eva-sarkhoff"] = {n="艾瓦·萨克霍夫",s="艾瓦·萨克霍夫是巴罗夫家族前女仆长留下的幽魂，与丈夫卢森一同徘徊在恐怖的通灵学院外。凯尔达隆陷落时，她遭到屠夫的折磨并被杀害，如今她的灵魂寻求勇敢的凡人，为他们的死复仇，并销毁他们受诅咒的遗骸。",h="艾瓦·萨克霍夫是巴罗夫家族前女仆长留下的幽魂，与丈夫卢森一同徘徊在恐怖的通灵学院外。凯尔达隆陷落时，她遭到屠夫的折磨并被杀害，如今她的灵魂寻求勇敢的凡人，为他们的死复仇，并销毁他们受诅咒的遗骸。",kw={"巴罗夫","凯尔达隆","诅咒神教","艾瓦·萨克霍夫","卡斯迪诺夫","卢森·萨克霍夫","通灵学院","屠夫"},ang={["class:Priest"]="目睹艾瓦和Lucien久久不散的痛苦，便会深切感受到Scourge的残忍，也迫使修习神圣之道的人为他们不得安息的灵魂带来平静，净化束缚他们的邪恶魔法。",["race:Human"]="艾瓦和她的丈夫代表了洛丹伦的普通仆从，当巴罗夫家族将凯尔达隆卖给克尔苏加德时，他们遭到了本国腐败贵族的背叛。"},sec={{t="巴罗夫家族的覆灭",b="艾瓦曾担任富裕的巴罗夫家族的女仆长数十年，与担任管家的丈夫卢森一同照料凯尔达隆的庞大城堡。巴罗夫家族日益惶恐，既担忧年华老去、终将一死，也担忧自己的巨额财富，于是与克尔苏加德订下了灾难性的契约。庄园逐渐被交给初具规模的诅咒教派，宏伟的宅邸也随之扭曲为通灵学院，一所秘密传授死灵法术的学院。艾瓦和卢森在城堡的走廊里躲藏了六个月，四处搜寻食物，眼看着教徒和怪物不断侵占他们的家园。"},{t="屠夫的手术刀",b="艾瓦和卢森终究还是被天灾军团发现，随后被交到了人称屠夫的瑟尔林·卡斯迪诺夫医生手中。卡斯迪诺夫对两人进行了数周痛苦不堪的实验，用黑暗魔法延续他们的生命，让他们承受远超凡人极限的折磨。即使死后，他们的尸体也被拿去喂食尸鬼，而不得安息的灵魂则被束缚在凯尔达隆，如今艾瓦在那里恳求过往的冒险者杀死卡斯迪诺夫，并焚毁他们的遗骸。"}},faq={{q="艾瓦·萨克霍夫生前是什么人？",a="艾瓦·萨克霍夫曾是贵族巴罗夫家族的女仆长，与担任管家的丈夫卢森一同在凯尔达隆的城堡里生活和工作了数十年。",al={"艾瓦·萨克霍夫的背景故事","艾瓦·萨克霍夫是谁","艾瓦的故事"}},{q="艾瓦是怎么死的？",a="艾瓦和卢森躲避诅咒神教数月后被发现，随后被交给了瑟尔林·卡斯迪诺夫医生。卡斯迪诺夫连续数周无情地折磨他们，用黑暗魔法维持他们的生命，直到他们最终死去，尸体也被拿去喂了食尸鬼。",al={"艾瓦·萨克霍夫是怎么死的","艾瓦·萨克霍夫之死","谁杀了艾瓦"}},{q="为什么艾瓦的幽灵仍留在凯尔达隆？",a="艾瓦遭受的折磨极其恐怖，违背自然，以至于她的灵魂仍被束缚在凡间。只有杀死卡斯迪诺夫医生，并烧毁她留在通灵学院内的遗骸，她才能步入永恒。",al={"艾瓦为什么变成幽灵","艾瓦的灵魂","艾瓦为什么徘徊不去"}}},fp="12,186,23.489.0,21.375.1,37.120.0,16.229.0,40.158.0"}
P.entries["npc:executor-arren"] = {n="执行官阿伦",s="在丧钟镇，执行官阿伦指挥着聚落的防御，而新的亡灵正从坟墓中爬起。他率领众人对抗天灾军团僵尸、野兽，以及威胁被遗忘者的敌人。",h="在丧钟镇，执行官阿伦指挥着聚落的防御，而新的亡灵正从坟墓中爬起。他率领众人对抗天灾军团僵尸、野兽，以及威胁被遗忘者的敌人。",kw={"丧钟镇","执行官阿伦","被遗忘者","夜行蜘蛛洞穴","血色十字军","希尔瓦娜斯","提瑞斯法林地"},ang={["faction:Horde"]="身为部落的一员，你见证阿伦在丧钟镇的指挥如何在敌人环伺之中，为部落稳固在洛丹伦北部的第一个据点。",["race:Undead"]="身为亡灵，执行官阿伦是你在提瑞斯法最早遇见的指挥官之一。他让你初次体会到在黑暗女王麾下履行职责的滋味。"},sec={{t="丧钟镇的指挥官",b="执行官阿伦在丧钟镇的礼拜堂外指挥当地的防御。墓穴中的看护者引导新近复生的亡灵走出迷茫，阿伦则让他们将注意力转向如何在坟墓之外生存。在希尔瓦娜斯·风行者女王的旗帜下，他组织人手清除村庄边界附近的无脑僵尸。在洛丹伦陷落的阴影下，被遗忘者在此巩固立足之地。"},{t="守卫边境",b="丧钟镇周围的危险，远不止那些迷茫的新生亡灵。在阿伦的命令下，斥候与新兵出击，对付夜行蜘蛛洞穴中的凶恶蜘蛛，并猎杀林地边缘的捕食者。他号召所有有能力的人行动起来，考验这些新来者能否守住重获新生的机会，并为黑暗女王效力。"},{t="血色威胁",b="血色十字军是阿伦最担忧的敌人。这些狂热者企图消灭所有亡灵，在他们眼中，天灾军团与拥有自由意志的被遗忘者毫无区别。阿伦下令打击驻扎在提瑞斯法荒野中的血色巡逻队。他的部队截击信使，研究夺来的公文，保护丧钟镇免遭圣火的净化。"}},faq={{q="执行官阿伦是谁？",a="执行官阿伦负责指挥提瑞斯法林地丧钟镇的防御。他组织新近复生的被遗忘者保卫村庄，确保周围乡野的安全。",al={"阿伦的职责","阿伦是谁","丧钟镇执行官"}},{q="执行官在被遗忘者中是什么军衔？",a="在被遗忘者中，执行官是备受信任的军事与行政指挥官。他们管理当地驻军，指挥野外行动，并贯彻希尔瓦娜斯·风行者女王的意志与律法。",al={"执行官头衔","执行官是什么","被遗忘者执行官军衔"}},{q="阿伦为什么派新兵对付僵尸？",a="瘟疫摧毁洛丹伦后，遗留下来的无脑天灾军团残部在丧钟镇附近游荡。阿伦下令清除它们，以免刚刚苏醒的亡灵在离开墓穴时被它们撕碎。",al={"为什么杀僵尸","被诅咒者任务","无脑天灾军团"}},{q="血色十字军为什么会在提瑞斯法林地？",a="血色十字军是一个激进的人类组织，致力于消灭所有亡灵。它在洛丹伦的废墟各处设有哨站，并企图净化被遗忘者，认为他们与天灾军团毫无区别。",al={"血色十字军提瑞斯法","十字军为何在此","丧钟镇的十字军"}},{q="夜行蜘蛛洞穴是什么地方？",a="夜行蜘蛛洞穴是丧钟镇西北方的一座金矿，已被蜘蛛占据。被遗忘者需要矿中的黄金，因此阿伦派新兵逐步清除这些蜘蛛。",al={"丧钟镇蜘蛛洞","夜行蜘蛛洞穴","阿伦蜘蛛任务"}},{q="新兵完成阿伦的任务后，他会派他们去哪里？",a="丧钟镇眼前的威胁得到解决后，阿伦会派有能力的新兵前往布瑞尔，向执行官塞加德报到，支援被遗忘者在提瑞斯法林地各处的行动。",al={"丧钟镇之后","阿伦之后去哪里","战场上的执行官"}}},fp="14,182,23.391.0,24.327.0,18.358.1,22.160.0,44.189.0,49.199.0,46.208.0,27.173.0,58.187.0"}
P.entries["npc:executor-zygand"] = {n="执行官塞加德",s="执行官塞加德在布瑞尔的城镇大厅中指挥提瑞斯法林地中部的被遗忘者防务。他向幽暗城最高指挥部汇报，并统筹对抗侵入被遗忘者领地的血色十字军。",h="执行官塞加德在布瑞尔的城镇大厅中指挥提瑞斯法林地中部的被遗忘者防务。他向幽暗城最高指挥部汇报，并统筹对抗侵入被遗忘者领地的血色十字军。",kw={"阿伦","布瑞尔","亡灵卫兵","执行官","蛆眼","血色十字军","提瑞斯法","塞加德"},ang={["faction:Horde"]="作为一名从卡利姆多来到提瑞斯法林地的旅人，你能从塞加德身上看到纪律严明的军事领导，带领被遗忘者为巩固对洛丹伦的控制而战。",["race:Undead"]="作为一名走出丧钟镇的被遗忘者，你遇到的执行官塞加德代表着幽暗城更广泛的军事权威，将新公民纳入现役，投入对抗他们最痛恨的敌人的战斗。"},sec={{t="布瑞尔的指挥官",b="被遗忘者在丧钟镇苏醒后，执行官塞加德便从布瑞尔指挥地区防务。执行官阿伦等军官，以及亡灵卫兵林奈等野外哨兵，都向他汇报。他汇集斥候的报告，派遣有能力的新兵守卫洛丹伦的边境，抵御外敌侵入。"},{t="对抗十字军",b="遍布提瑞斯法林地的血色十字军牵动着执行官塞加德的注意力。他派出人手打击十字军的斥候、营地和前沿基地，阻止这些狂热者集结足以威胁幽暗城外围通道的兵力。"}},faq={{q="执行官塞加德是谁？",a="执行官塞加德是驻扎在提瑞斯法林地布瑞尔的被遗忘者高级军官。他统领当地的亡灵卫兵驻军，听取下级军官的汇报，并指挥针对当地威胁的作战。",al={"塞加德","执行官塞加德是谁","塞加德职责"}},{q="在哪里能找到执行官塞加德？",a="执行官塞加德通常位于布瑞尔的主城镇大厅内或附近。布瑞尔是被遗忘者在提瑞斯法林地的中心聚居地，就在幽暗城北面。",al={"塞加德位置","塞加德在哪","执行官塞加德地图"}},{q="塞加德在提瑞斯法林地的主要目标是什么？",a="执行官塞加德的主要目标是指挥当地对抗血色十字军的战争。他追踪这些狂热者在提瑞斯法各处的动向，下令摧毁他们的营地、铲除他们的首领，阻止他们向幽暗城进军。",al={"塞加德任务目标","为何对抗十字军","塞加德目的"}},{q="谁向执行官塞加德汇报？",a="执行官阿伦和亡灵卫兵林奈等野外哨兵都向执行官塞加德汇报。阿伦在丧钟镇指挥初入伍的新兵，林奈则在提瑞斯法林地的主要道路交叉口巡逻。",al={"塞加德下属","谁为塞加德效力","阿伦的上级"}},{q="执行官塞加德会处理失控亡灵的威胁吗？",a="会。执行官塞加德也在当地发布悬赏，清剿危及林地通行安全的野生亡灵和危险的游荡食腐者，其中就包括盗取尸体的豺狼人蛆眼。",al={"蛆眼","塞加德悬赏","通缉任务"}},{q="“执行官”在被遗忘者中是什么级别？",a="在被遗忘者中，执行官拥有地区总督和军事指挥官的职权。执行官管理聚居地，统领当地的亡灵卫兵部队，并在洛丹伦各处争夺中的地区贯彻希尔瓦娜斯女王的统治。",al={"什么是执行官","执行官级别","被遗忘者执行官"}}},fp="15,217,16.301.0,22.258.0,23.208.0,33.157.0,46.202.0,31.187.0,49.194.0,53.228.0"}
P.entries["npc:falfindel-waywarder"] = {n="法芬德尔",s="法芬德尔是一名暗夜精灵德鲁伊，驻守在萨兰纳尔，这座哨站守卫着菲拉斯与千针石林的交界。从这座边境哨站出发，他致力于治愈遭到腐化的土地，守护卡利姆多南部的荒野。从石爪山或贫瘠之地一路南下的旅人，常会遇见正在寻求援手、恢复自然平衡的他。",h="法芬德尔是一名暗夜精灵德鲁伊，驻守在萨兰纳尔，这座哨站守卫着菲拉斯与千针石林的交界。从这座边境哨站出发，他致力于治愈遭到腐化的土地，守护卡利姆多南部的荒野。从石爪山或贫瘠之地一路南下的旅人，常会遇见正在寻求援手、恢复自然...",kw={"焦炭谷","法芬德尔","菲拉斯","石爪山","萨兰纳尔","千针石林","维沃德","小精灵"},ang={["class:Druid"]="他派遣森林之灵与小精灵去治愈石爪山的焦土，体现了德鲁伊修复自然的神圣使命。",["faction:Alliance"]="对于从贫瘠之地或石爪山长途跋涉南下的联盟旅人，法芬德尔与萨兰纳尔的守卫提供了一处温暖的庇护所。",["race:NightElf"]="法芬德尔代表着你的族人在卡利姆多边疆的警戒与守望，努力修复自然的伤痕，抵御荒野中步步逼近的危险。"},sec={{t="南部边境的守望",b="萨兰纳尔扼守着一处门户，菲拉斯的葱郁森林在这里逐渐降低，通向千针石林高耸的台地与干燥的盐碱平原。法芬德尔守望着这座偏远的哨站，迎接跋涉大陆远道而来的疲惫旅人。壮丽的自然景色与潜伏的危险环绕四周，他在此为暗夜精灵提供联络，协助他们监视当地的威胁，以及卡利姆多各地更大范围的生态灾难。"},{t="治愈焦炭谷",b="尽管驻守南方，法芬德尔仍深切关注着遥远北方石爪山脉遭受的破坏。焦炭谷毁于黑暗魔法与烈火，是卡利姆多荒野上一道令人痛心的伤疤。当冒险者将援助物资送到法芬德尔手中，帮助这片土地恢复生机时，他便会呼唤森林之灵。他召来成群的小精灵，指引它们迅速北上石爪山，开始修复焦土。"},{t="监视野猪人与荒原",b="除了协调修复工作，法芬德尔还密切监视着周边地区，包括剃刀沼泽的野猪人巢穴。法芬德尔查阅找回的日记，搜集野猪人首领的情报，确保联盟了解那些日益加剧、威胁着菲拉斯与中部沙漠之间通道的危险。"}},faq={{q="法芬德尔在哪里？",a="法芬德尔驻守在萨兰纳尔，这座暗夜精灵哨站位于菲拉斯与千针石林的交界。",al={"法芬德尔位置","法芬德尔在哪","法芬德尔地图"}},{q="法芬德尔在萨兰纳尔担任什么职责？",a="他在哨站担任德鲁伊与向导，监视剃刀沼泽野猪人等地区威胁，并协调修复焦炭谷等遭到破坏的土地。",al={"法芬德尔做什么","法芬德尔职责","法芬德尔任务"}},{q="法芬德尔如何帮助焦炭谷？",a="当冒险者协助收复焦炭谷时，法芬德尔便会吟诵咒语，召唤森林中的小精灵，派遣它们北上石爪山，治愈遭到侵蚀的土地。",al={"法芬德尔 石爪山","法芬德尔焦炭谷","收复焦炭谷法芬德尔"}},{q="法芬德尔为何关注剃刀沼泽？",a="他研究剃刀沼泽野猪人带来的威胁，并查阅亨里格·独眉的日记等物品，追踪卡尔加·刺肋等首领的影响。",al={"卡尔加·刺肋 法芬德尔","亨里格·独眉的日记法芬德尔","法芬德尔野猪人"}},{q="法芬德尔属于联盟，还是保持中立？",a="法芬德尔是一名效忠达纳苏斯与联盟的暗夜精灵德鲁伊。接近萨兰纳尔的部落旅人会受到哨站的敌视。",al={"法芬德尔是联盟吗","法芬德尔阵营"}},{q="法芬德尔会对旅人说些什么？",a="他会热情地问候友善的访客，体谅他们一路跋涉的辛劳，说道：“你看起来像是从很远的地方来的。”",al={"法芬德尔对话","法芬德尔台词"}}},fx={["444437e8"]={q="法芬德尔是谁？",a="法芬德尔是一名暗夜精灵，驻守在萨兰纳尔哨站，该地毗邻菲拉斯和千针石林。他关心土地的健康，也留意卡利姆多南部地区面临的危险；他守望过往旅人，并与其他暗夜精灵密切合作，应对荒野中出现的新威胁。",al={"法芬德尔是谁","法芬德尔的背景"}},e0cb4d91={q="法芬德尔想要什么？",a="法芬德尔希望保护脆弱的荒野，并帮助受创的土地恢复生机。他指挥盟友召唤森林之灵，让焦炭谷重焕生机；协调物资运送，保障当地哨站的补给；还设法除掉潜伏在剃刀沼泽中的堕落猪人老妪。",al={"法芬德尔想要什么","法芬德尔的目标","法芬德尔任务的目的"}},["2bf92e29"]={q="法芬德尔为什么在这里？",a="法芬德尔在萨兰纳尔担任德鲁伊和向导，守卫千针石林与菲拉斯之间的通道。在这座偏远的哨站，他监视着从贫瘠之地蔓延而来的猪人威胁，并协调行动，恢复卡利姆多中部和南部遭污染森林的平衡。",al={"法芬德尔为什么在这里","法芬德尔为什么在萨兰纳尔","法芬德尔的职责"}}},fp="19,285,28.299.0,24.322.0,35.292.0,37.120.0,38.161.0,41.151.0,46.175.0,50.125.0,37.135.0"}
P.entries["npc:falla-sagewind"] = {n="菲拉·古风",s="在贫瘠之地上方的一处峭壁上，菲拉·古风注视着这片土地，留意着异动的征兆。她的营地位于十字路口和甜水绿洲之间，她在那里研究自然与魔法的变化。",h="在贫瘠之地上方的一处峭壁上，菲拉·古风注视着这片土地，留意着异动的征兆。她的营地位于十字路口和甜水绿洲之间，她在那里研究自然与魔法的变化。",kw={"贫瘠之地","十字路口","法拉","发光的碎片","甜水绿洲","梦魇","旷野之风","牛头人","哀嚎洞穴"},ang={["class:Druid"]="身为德鲁伊，你可以在菲拉·古风的帮助下，追寻纳拉雷克斯和尖牙德鲁伊在哀嚎洞穴中悲剧般堕落的历程。",["faction:Horde"]="身为部落的一员，你可以请菲拉·古风解读斥候从贫瘠之地纷争不断的草原上带回的奇异征兆与腐化遗物。",["race:Tauren"]="身为牛头人，你或许会将菲拉·古风对大地的守望视为一种默默的守护。她在高处留意着灵魂腐化的迹象，而她的同胞则守卫着下方的道路。"},sec={{t="高崖上的守望者",b="菲拉·古风在十字路口西南方一处僻静的山顶扎营，远高于贫瘠之地的小径。她从那里观察草原，以及野生动物的变化。她还研究从哀嚎洞穴下方裂隙中涌出的腐化。守望让她远离了十字路口日常的贸易往来，但她始终关注着这片土地的灵魂与创伤。"},{t="醒来的梦魇",b="旅人从哀嚎洞穴的变异野兽身上取得奇异而不断脉动的碎片，并循着线索找到菲拉·古风。她研究扰乱绿洲的扭曲魔法，并从种种迹象中认出，地下的翡翠梦境已遭到腐化。为了进一步探明在这片地区扎根的梦魇，她指引旅人前去求教塞纳里奥议会中睿智的德鲁伊。"}},faq={{q="菲拉·古风是谁？",a="菲拉·古风在十字路口西南方高崖上的营地中守望着贫瘠之地。她帮助旅人了解正在这片地区蔓延的奇异魔法灾祸。",al={"菲拉·古风是谁","菲拉是谁","菲拉·古风背景故事"}},{q="在哪里可以找到菲拉·古风？",a="菲拉·古风在十字路口西南方、甜水绿洲北方的一座山峰顶端扎营。崎岖的山路从周围的草原蜿蜒而上，通往她的营地。",al={"菲拉·古风位置","菲拉·古风在哪里","如何前往菲拉·古风处"}},{q="菲拉·古风为何关注哀嚎洞穴？",a="菲拉·古风研究从哀嚎洞穴带回的一块发光的碎片中蕴含的奇异魔法。她指引旅人向经验丰富的德鲁伊寻求进一步的指点。",al={"菲拉·古风 哀嚎洞穴","菲拉·古风为何关注绿洲","菲拉·古风 发光的碎片"}},{q="菲拉·古风属于哪个氏族或家族吗？",a="菲拉·古风与其他一些牛头人同姓，但尚无确切证据表明他们之间存在亲属关系。",al={"古风家族","古风家族有哪些人","菲拉·古风与塔胡有亲属关系吗"}},{q="哪些任务与菲拉·古风有关？",a="菲拉·古风通过“发光的碎片”和“在噩梦中”这两个任务协助调查哀嚎洞穴，这些任务涉及正在腐化当地绿洲的黑暗梦境。",al={"菲拉·古风任务","菲拉·古风给予的任务","在噩梦中任务"}},{q="联盟玩家可以与菲拉·古风互动吗？",a="可以。菲拉·古风会帮助两个阵营的旅人处理发光的碎片。她让联盟冒险者前往达纳苏斯寻找玛斯雷·驭熊者，让部落冒险者前往雷霆崖寻找哈缪尔·符文图腾。",al={"菲拉·古风有敌意吗","菲拉·古风对联盟友好吗"}}},fp="14,182,24.362.0,20.360.1,22.190.0,32.153.0,56.156.0,53.91.0,35.153.0,50.205.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="部落英雄的灵魂",s="部落英雄的灵魂是一名兽人战士死后徘徊不去的幽魂，守望着从悲伤沼泽通往南方的道路。悔恨与耻辱将他束缚于此，他警告过往旅人，诅咒之地有恐怖之物在等待他们，也寻求愿意将他饱受折磨的士兵从恶魔奴役中解救出来的勇士。",h="部落英雄的灵魂是一名兽人战士死后徘徊不去的幽魂，守望着从悲伤沼泽通往南方的道路。悔恨与耻辱将他束缚于此，他警告过往旅人，诅咒之地有恐怖之物在等待他们，也寻求愿意将他饱受折磨的士兵从恶魔奴役中解救出来的勇士。",kw={"奥利斯塔","部落英雄的灵魂","毁灭者戈洛尔","副官 基利斯","污染者拉瑟莱克","瑟温妮","禁锢之石","沼泽空谈者"},ang={["class:Warrior"]="作为一位声名远扬的阵亡战士，他的幽魂与那些征战四方的冒险者有着深切的共鸣，因为他们懂得战友倒下而自己独活的痛楚。",["faction:Horde"]="这位英雄承受着战士被恶魔的残暴行径剥夺荣誉的痛苦，恳求部落冒险者为他失去的小队复仇，洗去败亡留在他们身后的污点。"},sec={{t="悲剧性的统率",b="这名战士生前是一位声名显赫的勇士，奉命率领一支精挑细选的部队前往诅咒之地，调查并回报燃烧军团在当地的动向。他的报告始终未能送达；奉命北上斯通纳德的信使遭到沼泽空谈者及其麾下鱼人的伏击，惨遭杀害。指挥官既得不到命令，也等不来援军，最终率领士兵向南挺进那片破碎的荒原，迎战日益壮大的黑暗势力。这是一次致命的误判。他的军队不敌恶魔大军，溃散后遭到俘虏，在恐惧魔王污染者拉瑟莱克手中饱受骇人的折磨。"},{t="失败的代价",b="指挥官与副官基利斯一同被俘，在盘蛇谷遭受残酷的拷打，而俘虏他们的恶魔则将幸存士兵的灵魂从躯体中撕扯出来。这位英雄虽然逃了出来，却在沼泽边境附近伤重而亡，他的灵魂从此被束缚在诅咒之地的入口。他的士兵遭遇了更加黑暗的命运：他们失去灵魂的躯壳被绑定在神秘的石头上，成为不死的奴仆，分别受制于拉瑟莱克及其副官——大法师奥利斯塔、瑟温妮女士和毁灭者戈洛尔。只要那些束缚灵魂的石头尚未被击碎，士兵的折磨尚未结束，他躁动不安的灵魂就无法安息。"}},faq={{q="这位部落英雄生前是什么人？",a="他是一名久经沙场的兽人战士，被选中率领一支侦察部队进入诅咒之地，评估恶魔的威胁。他从污染者拉瑟莱克的酷刑下逃脱后，因伤势过重而死，灵魂滞留在离开悲伤沼泽的道路旁。",al={"部落英雄身份","部落英雄名字","部落英雄是谁"}},{q="他为何在诅咒之地边境徘徊？",a="失去部队、未能完成使命的耻辱将他束缚于此。在勇敢的冒险者南下摧毁禁锢之石，将他的士兵从燃烧军团的永恒奴役中解救出来之前，他不肯离去。",al={"他为何成为幽灵","部落英雄幽灵","他为何在此"}},{q="他送往斯通纳德的命令出了什么事？",a="携带紧急报告返回斯通纳德哨站的斥候，在沼泽中遭到沼泽空谈者率领的鱼人伏击并杀害。报告遗失，援军始终没有到来，促使这位英雄孤军深入诅咒之地。",al={"失踪的命令","他的命令出了什么事","沼泽空谈者 信使"}},{q="他的副官基利斯遭遇了什么？",a="副官基利斯在盘蛇谷内遭受了恶魔的实验。他的灵魂被扭曲腐化，肉身化作一头骇人的地狱猎犬，潜伏在洞穴深处。",al={"副官 基利斯","基利斯 是谁","基利斯 遭遇了什么"}},{q="他的士兵为何无法被杀死？",a="拉瑟莱克及其副官将被俘士兵的灵魂与肉体分离。没有灵魂，他们的肉身便无法真正死去。只有将他们的躯体打得濒临崩解，附近束缚灵魂的石头才会短暂地变得可以摧毁，他们也才能获得解脱。",al={"无法被杀死的士兵","禁锢之石","拉瑟莱克 的仆从"}}},fp="24,237,16.554.0,20.622.1,32.275.0,51.235.0,47.205.0,40.165.1,34.269.1"}
P.entries["npc:fandral-staghelm"] = {n="范达尔·鹿盔",s="范达尔·鹿盔在达纳苏斯的塞纳里奥区领导着塞纳里奥议会的德鲁伊。玛法里奥·怒风进入翡翠梦境后，范达尔力主培育泰达希尔，推动卡多雷强势复兴，并时常与高阶女祭司泰兰德·语风发生冲突。",h="范达尔·鹿盔在达纳苏斯的塞纳里奥区领导着塞纳里奥议会的德鲁伊。玛法里奥·怒风进入翡翠梦境后，范达尔力主培育泰达希尔，推动卡多雷强势复兴，并时常与高阶女祭司泰兰德·语风发生冲突。",kw={"塞纳里奥议会","达纳苏斯","范达尔","玛法里奥","拉贾克斯","流沙","鹿盔","泰达希尔","瓦斯坦恩"},ang={["class:Druid"]="身为德鲁伊，你看到鹿盔统领着达纳苏斯的德鲁伊，并推动塞纳里奥议会直接掌握世俗权力。他的主张与沉睡中的玛法里奥·怒风的传统教诲相冲突。",["faction:Alliance"]="身为联盟的一员，你会发现泰达希尔是卡利姆多北部的一座堡垒。鹿盔对年轻种族的轻蔑几乎毫不掩饰，只有出于政治上的权宜之计，才容忍他们的存在。",["race:NightElf"]="身为暗夜精灵，你看到范达尔体现着Kaldorei的骄傲与怒火。他推动泰达希尔的定居建设，而普通民众则感受到了他所在的区域与月神殿之间的裂痕。"},sec={{t="泰达希尔的缔造者",b="第三次大战之后，随着海加尔山巅的诺达希尔被牺牲，暗夜精灵失去了永生与神圣的庇护之所。玛法里奥·怒风失踪后，范达尔接过了领导德鲁伊的重任。他说服了古树议会，认为族人必须重建家园，重获永生。\n\n得到议会的批准后，范达尔率领德鲁伊在卡利姆多海岸外培育出了泰达希尔。他希望用这棵巨树彰显卡多雷的坚韧，恢复他们失去的霸权。守护巨龙并未赐福于这一壮举。"},{t="流沙的悲剧",b="第一次兽人战争的一千年前，在希利苏斯的流沙之战期间，范达尔担任卡多雷的战地指挥官。其拉虫人称他为卡尔西斯，意为大地之手。他深爱的独子瓦斯坦恩与他并肩奋战在前线。\n\n其拉虫人将军拉贾克斯利用范达尔对儿子的深爱，佯攻南风村。瓦斯坦恩被俘，并在惊恐的大德鲁伊面前遭到处决。悲痛击垮了范达尔的意志，迫使他撤退，酿成惨重损失。他对虫群的刻骨仇恨至今未消。"},{t="纷争与傲慢",b="在达纳苏斯，范达尔以傲慢而强硬的手腕治理卡多雷的事务。高阶女祭司泰兰德·语风是一位精神领袖，主张守护传统与审慎外交。范达尔则认为，军事扩张与果断用兵才是族人生存的关键。"}},faq={{q="范达尔·鹿盔是谁？",a="范达尔是达纳苏斯塞纳里奥议会的代理大德鲁伊，在玛法里奥·怒风缺席期间领导卡多雷德鲁伊。他的火爆脾气与帝国野心，塑造了他对泰达希尔的愿景。",al={"范达尔的故事","大德鲁伊是谁","达纳苏斯的大德鲁伊"}},{q="范达尔为何与泰兰德不和？",a="范达尔主张重振卡多雷的军力，积极扩张，并重获失去的永生。泰兰德·语风则以对艾露恩的虔诚信仰和审慎的态度引领族人。海加尔山之战后，两人对暗夜精灵未来的相反愿景，在达纳苏斯引发了激烈的政治摩擦。",al={"范达尔与泰兰德","德鲁伊与女祭司为何不和","鹿盔与语风的对立"}},{q="为何种下泰达希尔？",a="海加尔山之战后，诺达希尔伤痕累累，暗夜精灵也失去了永生。玛法里奥失踪后，范达尔说服了古树议会，认为族人必须重建家园，重获永生。得到议会的批准后，范达尔与最强大的德鲁伊共同培育出了泰达希尔。",al={"谁创造了泰达希尔","范达尔为何种下泰达希尔","泰达希尔的起源"}},{q="范达尔的儿子遭遇了什么？",a="在希利苏斯的流沙之战期间，范达尔的儿子瓦斯坦恩被诱入南风村的伏击圈。其拉将军拉贾克斯俘虏了他，并在范达尔面前将他杀害。丧子之痛让这位大德鲁伊悲恸不已，满怀怨恨。",al={"范达尔的儿子","瓦斯坦恩是谁","瓦斯坦恩·鹿盔"}},{q="在哪里可以找到范达尔·鹿盔？",a="在达纳苏斯的塞纳里奥区顶层可以找到范达尔，他在忠诚的德鲁伊簇拥下，掌管着这座卡多雷都城。",al={"范达尔在哪里","范达尔的位置","塞纳里奥区的领袖"}}},fx={d5bab569={q="范达尔·鹿盔效忠哪一方？",a="范达尔是达纳苏斯的大德鲁伊，也是塞纳里奥议会的一位领袖，拥护卡多雷和联盟。然而，他的忠诚带有强烈的民族主义色彩。他不愿顺从塞纳里奥长老或月神祭司团一贯的谨慎作风，而是严格按照自己认定的暗夜精灵民族利益行事，追求强硬的军事路线。",al={"范达尔·鹿盔的阵营","范达尔效忠谁","范达尔的效忠对象"}},adee2909={q="范达尔·鹿盔想要什么？",a="范达尔渴望恢复暗夜精灵的力量、不朽之身和领土霸权。他厌倦了数百年来消极避世的生活，力主种下世界之树泰达希尔，以取代诺达希尔。他设想建立一个积极进取的卡多雷国度，随时准备征服边境，大胆扩张至卡利姆多各地，并重拾远古时代失去的荣光与活力。",al={"范达尔·鹿盔的目标是什么","范达尔的野心","大德鲁伊鹿盔想要什么"}},["6d220bca"]={q="范达尔·鹿盔为什么在达纳苏斯？",a="玛法里奥·怒风被困在翡翠梦境中，无法行动，范达尔便接过大德鲁伊之位。他在达纳苏斯的塞纳里奥区高处统领塞纳里奥议会的德鲁伊，与大祭司泰兰德·语风共同执政，并积极主导泰达希尔的政治与魔法未来。",al={"范达尔为什么在达纳苏斯","范达尔·鹿盔驻守此地的原因","范达尔为什么在这里"}},["53c16312"]={q="范达尔·鹿盔为何闻名？",a="在率领种下泰达希尔之前很久，范达尔曾在希利苏斯的流沙之战中担任杰出的卡多雷战地指挥官。他对其虫族大军发动的毁灭性战术打击，为他赢得了其拉虫人的称号“卡尔希斯”——大地之手。其拉虫人畏惧他在战场上的狂怒，直到他们策划了他儿子的悲惨处决。",al={"范达尔为何闻名","范达尔为何令人畏惧","范达尔的大地之手称号"}}},fp="16,273,23.554.0,29.517.0,18.281.0,24.202.0,43.295.0,27.292.0,31.240.0,36.128.0"}
P.entries["npc:farmer-furlbrow"] = {n="农夫法布隆",s="在贾森农场附近，农夫法布隆和妻子弗娜被困在损坏的马车旁。他们被迪菲亚潜行者赶出了西部荒野北部的农场，希望能前往艾尔文森林。",h="在贾森农场附近，农夫法布隆和妻子弗娜被困在损坏的马车旁。他们被迪菲亚潜行者赶出了西部荒野北部的农场，希望能前往艾尔文森林。",kw={"布兰契","迪菲亚","法布隆","传家宝","詹森","南瓜","西奥多","弗娜","马车","怀表"},ang={["faction:Alliance"]="身为联盟的公民，你能看到西部荒野的地方政权已经彻底失去了作用。忠诚的百姓得不到王国士兵的保护，只能背井离乡。"},sec={{t="装上马车的家当",b="法布隆夫妇收拾了能带走的东西，动身前往艾尔文森林。西奥多也劝农夫萨丁等邻居离开。如今，路上的匪徒和野兽威胁着他们的安全。\n\n弗娜照料着他们的马老马布兰契，西奥多则在一旁放哨。他希望找回弗娜的父亲在他们婚礼当天送给他的怀表。他还想向哨兵岭示警，告知匪徒正在逼近。"},{t="侵占土地的证据",b="在法布隆夫妇逃离之前，迪菲亚潜行者的暴徒向西奥多施压，夺走了他农田的地契，弗娜也在上面签了名。他们认为，这份地契能帮助他们伪造自己的地契。地契至今仍在匪徒手中。\n\n你可以找回地契，将它交还给西奥多。如果西部荒野有朝一日能再次让老实人安居，这份地契或许能帮助法布隆夫妇收回自己的土地。"}},faq={{q="农夫法布隆是谁？",a="西奥多·法布隆和妻子弗娜被迪菲亚潜行者赶出了西部荒野北部的南瓜农场，一同逃离了家园。他们被困在贾森农场附近，守着损坏的马车。",al={"农夫法布隆","西奥多·法布隆","法布隆是谁"}},{q="农夫法布隆为什么被困在路上？",a="西奥多和弗娜逃离西部荒野、前往艾尔文森林时，马车坏了。他们和自己的马老马布兰契一起被困在路旁。",al={"他的马车为什么坏了","法布隆为什么在路上","西部荒野坏掉的马车"}},{q="农夫法布隆丢失了什么传家宝？",a="逃离农场时，西奥多丢失了弗娜的父亲在他们婚礼当天送给他的怀表。他希望能找回它。",al={"遗忘的传家宝怀表","法布隆的怀表","怀表"}},{q="农夫法布隆在西部荒野以外还有家人吗？",a="没有记载表明他在西部荒野以外还有亲属。西奥多的家人是妻子弗娜，她和他一起被困在损坏的马车旁，身边还有他们的马老马布兰契。",al={"法布隆的家人","法布隆的兄弟"}}},fx={d2bcffbc={q="农夫法布隆效忠哪一方？",a="农夫法布隆是西部荒野的一名普通农民，忠于暴风城王国和联盟。迪菲亚潜行者夺走了他的土地，将他赶了出去，他对他们毫无好感。尽管因王国未能提供保护而心怀怨愤，他仍向同属联盟的旅人和人民军求助。",al={"农夫法布隆的阵营","法布隆支持谁","法布隆是否属于联盟"}},["81475819"]={q="农夫法布隆想要什么？",a="农夫法布隆只想修好损坏的货车，带着妻子弗娜和他们的老马布兰契逃离西部荒野。南瓜农场已被迪菲亚匪徒占据，他眼下最要紧的是收集补给、找回遗失的传家宝，并带着家人离开这片无法无天的边地。",al={"法布隆需要什么","农夫法布隆的目标","法布隆的意图"}}},fp="15,201,24.404.0,24.359.1,23.196.0,44.137.0,39.124.0,54.162.0"}
P.entries["npc:farmer-saldean"] = {n="农夫萨丁",s="在西部荒野中部的萨丁农场，农夫萨丁和妻子萨尔玛仍在饱受侵扰的田地里劳作。其他农夫纷纷逃离或放弃，他却仍在对抗失控的收割傀儡和日益猖獗的盗匪。",h="在西部荒野中部的萨丁农场，农夫萨丁和妻子萨尔玛仍在饱受侵扰的田地里劳作。其他农夫纷纷逃离或放弃，他却仍在对抗失控的收割傀儡和日益猖獗的盗匪。",kw={"鸡饲料","农夫萨丁","麦田看守","萨丁","萨丁农场","萨尔玛","清理荒野","西部荒野"},ang={["faction:Alliance"]="身为联盟的旅人，你能从萨丁身上看到西部荒野留守忠诚者的顽强决心。即使王国士兵不见踪影，他们仍死守着王国的土地。",["profession:Cooking"]="像萨丁这样的农夫，是暴风城粮食供应日渐衰弱的支柱。保住他的庄稼，才能让王国各地的餐桌上仍有果腹的面包。"},sec={{t="扶犁坚守",b="农夫萨丁还记得西部荒野昔日繁荣的模样。如今，杂草丛生的田地、横冲直撞的机械收割看守和四处劫掠的盗匪包围着他的农场。但他不肯放弃自己的土地。\n\n其他农户已经弃田而去，或是做起了盗贼。萨丁和妻子萨尔玛留了下来，尽力收获所剩无几的粮食。他请路过的冒险者摧毁自己和邻居田里失控的看守傀儡，好清理土地，重新播种。"},{t="西部荒野的镰刀",b="在哨兵岭与北边的桥梁之间，萨丁守卫着自己的家园，也让平民的生活得以延续。尽管日子艰难，他仍与人民军保持着联系。眼前的麻烦一旦解决，他就会指引身强力壮的旅人前去寻找格里安·斯托曼。\n\n清除失控的收割机械，只能让他的农场暂时喘息。扼住乡野咽喉的混乱局面仍有待解决。"}},faq={{q="农夫萨丁是谁？",a="农夫萨丁是一位经验丰富的人类农夫，与妻子萨尔玛住在西部荒野的萨丁农场。饥荒、失控的收割傀儡和日益猖獗的盗匪威胁着他的土地，但他不肯离去。",al={"萨丁","萨丁是谁","萨丁非玩家角色"}},{q="农夫萨丁的农场为何陷入困境？",a="西部荒野的自动收割傀儡出了故障，已经失控。它们在农田里游荡，攻击视野中的任何人，因此萨丁需要冒险者摧毁自己和邻居田里的机械看守，夺回土地。",al={"收割傀儡为何攻击","萨丁农场的问题"}},{q="在哪里可以找到农夫萨丁？",a="农夫萨丁就在萨丁农场的农舍外，那里位于西部荒野中部，紧邻大路，在哨兵岭以北。",al={"萨丁的位置","萨丁在哪里","萨丁农场的位置"}},{q="萨丁支持人民军吗？",a="是的。萨丁忙于保护庄稼和家园，但他会指引有能力的冒险者沿路前往哨兵岭，寻找格里安·斯托曼，帮助人民军保卫这片地区。",al={"萨丁 格里安·斯托曼","萨丁 民兵"}},{q="萨丁出售哪些独特的物品？",a="萨丁出售作为主食的面包和特殊的鸡饲料。后者是一种奇特的谷物，那些想与西部荒野四处游荡的本地家禽交朋友的旅人，正四处寻觅它。",al={"萨丁 商人","特殊的鸡饲料商人"}}},fx={b644bbfd={q="农夫萨丁想要什么？",a="萨丁只想守住农庄、收获庄稼，与妻子萨尔玛一起勉强维持生计。西部荒野陷入混乱，又遭暴风城漠视，他只能依靠过路的冒险者清除在田间肆虐的失控机械麦田傀儡，并协助当地的人民军恢复这一地区的安宁。",al={"萨丁想要什么","萨丁的目标","农夫萨丁想要什么"}},["340c71f6"]={q="农夫萨丁为何在这里？",a="萨丁不肯被赶出自己的土地。盗贼几乎赶走了西部荒野的其他所有农民，但他仍与妻子萨尔玛留在萨丁农场，耕作田地，在步步逼近的危险中守住家园。",al={"萨丁为何在西部荒野","萨丁为何留下","农夫萨丁的来历"}},["4625baa0"]={q="农夫萨丁与谁有关联？",a="农夫萨丁与妻子萨尔玛·萨丁一起经营农庄，妻子负责操持家务和烹饪。他还与哨兵岭的格里安·斯托曼及人民军合作，指引身强力壮的勇士前去支援他们，对抗威胁王国粮仓的匪徒。",al={"农夫萨丁的家人","萨丁的配偶是谁","萨尔玛·萨丁的关系"}}},fp="14,191,16.492.0,22.422.0,22.211.0,40.240.0,34.139.0,42.185.0,36.142.0"}
P.entries["npc:farthing"] = {n="Farthing",s="在暴风城的光明大教堂，法席恩引导信众，并统筹王国各地的援助。这位仁慈而睿智的人类神职人员照料着教区信众和需要帮助的人。",h="在暴风城的光明大教堂，法席恩引导信众，并统筹王国各地的援助。这位仁慈而睿智的人类神职人员照料着教区信众和需要帮助的人。",kw={"本尼迪塔斯","主教法席恩","光明大教堂","法席恩","摩本特·费尔","寻求智慧","暴风城"},ang={["class:Priest"]="作为造访光明大教堂的牧师，你可以向法席恩了解暴风城人类神职人员的圣职体系与学识智慧。",["faction:Alliance"]="作为在暮色森林等南方地区对抗腐化的联盟冒险者，你可以向法席恩及其神职同僚寻求神圣的启迪与精神上的坚定。"},sec={{t="暴风城的主教",b="主教法席恩在光明大教堂照料暴风城民众的精神需求。他与大主教本尼迪塔斯及聚集于此的神职人员一同侍奉。在那里，他为旅人答疑解惑，帮助研习神圣技艺的人，并履行圣光教会的公共事务与牧灵职责。"},{t="援助疫病之地",b="法席恩在首都指引热忱的旅人，前往王国境内需要神圣援助的地方。据报告，死灵法师摩本特·费尔正在活动，亡灵瘟疫也在暮色森林蔓延。法席恩为人们提供建议，帮助他们破除黑暗法术，净化遭到疫病侵蚀的边境。"}},faq={{q="在哪里可以找到主教法席恩？",a="主教法席恩住在光明大教堂内，那里位于暴风城教堂广场的中央。",al={"法席恩位置","法席恩在哪里","法席恩地图"}},{q="法席恩在大教堂担任何种职务？",a="法席恩是圣光教会正式授任的主教。他指引来访的信众、修习中的牧师，以及为远方定居点寻求神圣智慧的冒险者。",al={"法席恩做什么","法席恩是谁"}},{q="法席恩与暮色森林有何关联？",a="面对暮色森林的亡灵威胁，冒险者向法席恩求教，了解维系死灵法师摩本特·费尔力量的黑暗法术。他指引他们寻求净化之道。",al={"法席恩暮色森林","法席恩 摩本特·费尔"}},{q="法席恩与其他同姓居民有亲属关系吗？",a="人类领土上有好几个人都姓法席恩，其中包括库勒曼·法席恩和伊维特·法席恩。主教法席恩并未提及任何直系亲属关系。",al={"库勒曼·法席恩亲属","法席恩家族"}}},fx={["1783acb6"]={q="主教法席恩为什么在光明大教堂？",a="法席恩驻守在暴风城的光明大教堂，履行主教的圣职，为来访者提供指引，支持牧师们的工作，并代表高阶神职人员协助主持教会事务。",al={"法席恩为什么在这里","法席恩为什么在暴风城","法席恩在大教堂的职责"}},e622858b={q="主教法席恩是谁？",a="主教法席恩是圣光教会的一名人类牧师，在暴风城宏伟的光明大教堂中任职。他仁慈而睿智，处理大教堂的事务，并为信徒提供指引。",al={"法席恩是谁","主教法席恩","法席恩的故事"}},["6481fc58"]={q="主教法席恩效忠哪一方？",a="法席恩坚定地支持大联盟，以及大主教本尼迪塔斯领导的圣光教会。他在暴风城的神圣殿堂中代表牧师群体，指引求助者，并照管信仰事务。",al={"法席恩效忠哪一方","法席恩为谁效力","法席恩是否属于联盟"}},e4f9a584={q="主教法席恩想要什么？",a="法席恩希望帮助旅人，恪守圣光的美德。他格外关心受到黑暗威胁的土地，例如指点冒险者如何帮助暮色森林饱受困扰的人民对抗黑暗的通灵术。",al={"法席恩的动机","法席恩想要什么","法席恩的目标"}}},fp="8,175,21.292.0,24.281.0,35.107.0,46.174.0,39.160.0,60.158.0"}
P.entries["npc:feegly-the-exiled"] = {n="被流放的费格雷",s="在贫瘠之地南部的巴尔莫丹挖掘场附近，被流放的费格雷独自潜藏着。他曾被誉为远征队最出色的挖掘者之一，却因将一件出土遗物的力量据为己有，被塔文布莱德将军赶走。",h="在贫瘠之地南部的巴尔莫丹挖掘场附近，被流放的费格雷独自潜藏着。他曾被誉为远征队最出色的挖掘者之一，却因将一件出土遗物的力量据为己有，被塔文布莱德将军赶走。",kw={"巴尔莫丹","贫瘠之地","挖掘者","挖掘","被流放","费格雷","众月之泪","石腭怪"},ang={["faction:Horde"]="费格雷对巴尔莫丹挖掘者怀有深切的怨恨，这使他成了那些试图破坏贫瘠之地矮人远征队行动的部落旅人意想不到的盟友。",["race:Dwarf"]="对矮人而言，费格雷是一个悲惨而可怕的警示：一名出色的挖掘者，因痴迷于一件出土遗物，失去了在同族中的容身之地。"},sec={{t="挖掘者的毁灭",b="被流放的费格雷曾是巴尔莫丹最出色的挖掘者之一。众月之泪是挖掘场的首个重大发现，费格雷将它的力量据为己有。塔文布莱德将军称这颗宝石受到了诅咒，将它锁在巴尔丹城堡，并赶走了费格雷。如今，费格雷独自郁郁而居，迫切地想夺回那颗将给他带来厄运的宝石。当他终于再次握住宝石时，众月之泪碎裂了，费格雷也扭曲变形成了一只丑陋、佝偻的石腭怪。"}},faq={{q="被流放的费格雷是谁？",a="费格雷是巴尔莫丹挖掘场的一名矮人挖掘者，遭到流放后仍觊觎着那里的众月之泪。",al={"费格雷是谁","费格雷的故事","被流放的费格雷"}},{q="费格雷为何被逐出巴尔莫丹？",a="费格雷痴迷于众月之泪，那是巴尔莫丹的首个重大发现。塔文布莱德将军称这颗宝石受到了诅咒，将它锁在巴尔丹城堡，并赶走了费格雷。",al={"为何被流放","费格雷做了什么","费格雷被流放"}},{q="费格雷为何愿意与部落冒险者交谈？",a="费格雷遭到矮人同胞的背叛和驱逐，对联盟远征队已毫无忠诚可言。他迫切地想取回自己觊觎的遗物，于是向部落旅人寻求帮助。",al={"费格雷为何对部落友善","费格雷对部落友善"}},{q="众月之泪是什么？",a="众月之泪是巴尔莫丹的挖掘者出土的一颗宝石，也是他们在那里的首个重大发现。费格雷声称它赋予了自己力量，但塔文布莱德将军认定它受到了诅咒，将它锁在巴尔丹城堡。",al={"众月之泪","费格雷的宝石","费格雷的神器"}}},fp="17,219,15.436.1,25.93.0,38.181.0,51.172.0,30.217.0"}
P.entries["npc:feero-ironhand"] = {n="费罗·艾隆汉",s="在迈斯特拉岗哨，费罗·艾隆汉守卫着黑海岸与灰谷之间的道路。他与净化者德尔格伦携手对抗暗滩教派。",h="在迈斯特拉岗哨，费罗·艾隆汉守卫着黑海岸与灰谷之间的道路。他与净化者德尔格伦携手对抗暗滩教派。",kw={"灰谷","奥伯丁","暗滩教派","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨"},ang={["faction:Alliance"]="对于从黑海岸南下的联盟旅人来说，费罗在灰谷这片危险且战事不断的荒野中提供了一处立足之地。",["race:Human"]="身为人类，看到费罗在灰谷古老的精灵森林中站岗，便能欣慰地感受到联盟各族之间的协作。"},sec={{t="迈斯特拉岗哨的亡灵壁垒",b="迈斯特拉岗哨监视着从黑海岸向南通往灰谷的道路。费罗·艾隆汉在岗哨服役，维持着与奥伯丁之间的通信和贸易，同时警戒周围的树林。他与净化者德尔格伦共同对抗暗滩教派。邪教徒和林中的猛兽威胁着连接达纳苏斯补给线与灰谷前线的道路。"}},faq={{q="费罗·艾隆汉是谁？",a="费罗·艾隆汉是一名联盟人类圣骑士，驻守在灰谷西部的迈斯特拉岗哨。他帮助往来于黑海岸与灰谷之间的旅人，并与奥伯丁协调后勤事务。",al={"费罗·艾隆汉","费罗是谁","费罗非玩家角色"}},{q="费罗在迈斯特拉岗哨的职责是什么？",a="费罗协助迈斯特拉岗哨抵御当地的威胁。他支援净化者德尔格伦对抗暗滩教派，并协助维持通往黑海岸的信使与补给路线畅通。",al={"费罗为何在此","费罗的职责","迈斯特拉岗哨人类"}},{q="暗滩教派是什么？",a="暗滩教派在灰谷北部活动，施展黑暗魔法，举行邪恶仪式。迈斯特拉岗哨的联盟部队致力于干扰并瓦解其活动。",al={"暗滩教派"}},{q="费罗与银色黎明有联系吗？",a="没有记录表明费罗与银色黎明有联系。他是一名圣骑士，与净化者德尔格伦密切合作，后者同样是一名在森林中对抗黑暗势力的人类圣骑士。",al={"费罗银色黎明","费罗属于银色黎明吗"}}},fp="14,162,27.349.0,22.188.0,42.184.0,36.179.0,47.175.0"}
P.entries["npc:fel-zerul"] = {n="费泽鲁尔",s="费泽鲁尔是一名兽人术士，驻扎在悲伤沼泽幽暗深处的斯通纳德。他奉大酋长萨尔的直接命令，调查潜伏在沉入水下的阿塔哈卡神庙中的不祥存在。",h="费泽鲁尔是一名兽人术士，驻扎在悲伤沼泽幽暗深处的斯通纳德。他奉大酋长萨尔的直接命令，调查潜伏在沉入水下的阿塔哈卡神庙中的不祥存在。",kw={"阿塔哈卡","费泽鲁尔","斯通纳德","悲伤沼泽","萨尔","术士"},ang={["class:Warlock"]="费泽鲁尔受萨尔正式委派执行任务，这表明新部落有时也会依靠黑暗法术的研习者，来对抗隐秘而深奥的威胁。",["faction:Horde"]="费泽鲁尔驻扎在斯通纳德，担任预警斥候，确保沼泽中滋生的黑暗魔法不会让部落在当地的据点措手不及。"},sec={{t="监视沉没的神庙",b="虽然萨尔领导的部落普遍对黑暗法术心存疑虑，但大酋长明白，要了解邪恶的力量，就需要研究这些力量的人。费泽鲁尔被专门派往斯通纳德，查明泪水之池和沉入水下的阿塔哈卡神庙周围的腐化之谜。这名术士指引冒险者找回文物，并调查被流放的阿塔莱巨魔，力求在邪恶威胁部落的南方哨站之前，查明浑浊水下究竟有什么正在蠢动。"}},faq={{q="费泽鲁尔是谁？",a="费泽鲁尔是一名兽人术士，居住在部落位于悲伤沼泽的据点斯通纳德。他负责调查附近阿塔哈卡神庙中正在进行的黑暗仪式。",al={"费泽鲁尔","费泽鲁尔是谁","斯通纳德术士"}},{q="萨尔为什么派一名术士前往斯通纳德？",a="大酋长萨尔派出了费泽鲁尔，因为应对古老的诅咒和鲜血仪式，需要精通黑暗魔法的人。费泽鲁尔的任务是监视沉没的神庙周围令人不安的动向，保护部落在沼泽中的利益。",al={"萨尔 费泽鲁尔","费泽鲁尔为何在此","费泽鲁尔的使命"}},{q="费泽鲁尔在调查什么？",a="费泽鲁尔正在调查泪水之池的阿塔哈卡神庙中的阿塔莱巨魔及其亵渎仪式。他招募斥候和冒险者，打捞文物，追查可能掌握关键知识的流亡祭司。",al={"费泽鲁尔任务背景","费泽鲁尔想要什么","泪水之池调查"}}},fp="9,121,25.427.0,17.164.0,41.207.0,32.209.0"}
P.entries["npc:felgur-twocuts"] = {n="费古尔·双刃",s="费古尔·双刃是一名说话直率的兽人斥候，驻守在凄凉之地的幽灵岗哨。他负责协调部落对抗当地半人马氏族的行动。",h="费古尔·双刃是一名说话直率的兽人斥候，驻守在凄凉之地的幽灵岗哨。他负责协调部落对抗当地半人马氏族的行动。",kw={"半人马赏金","凄凉之地","费古尔·双刃","幽灵岗哨","部落","科卡尔","兽人"},ang={["faction:Horde"]="费古尔是幽灵岗哨至关重要的行动联络人，协助部落击退凄凉之地咄咄逼人的半人马部族。",["race:Orc"]="费古尔秉持着兽人在危险边境一贯的务实作风，比起闲聊，他更看重力量、速度和立竿见影的成效。"},sec={{t="粗声粗气的前哨斥候",b="费古尔·双刃驻守在凄凉之地中部的幽灵岗哨，四周尽是荒凉景象，他没有多少耐心听人客套。作为部落的前线斥候，他负责评估旅人和定居者穿越群山向西行进时面临的威胁，尤其是当地的科卡尔半人马。"},{t="对半人马的战争",b="费古尔指派部落勇士击杀当地的半人马酋长，并领取剿杀交战部族的赏金，这些部族正威胁着整个地区。任何想要巩固部落在凄凉之地立足点的人，都少不了与他接洽。"}},faq={{q="费古尔·双刃是谁？",a="费古尔·双刃是一名兽人斥候，也负责发布任务，驻守在部落位于凄凉之地的前线营地幽灵岗哨。",al={"费古尔·双刃是谁","费古尔是谁"}},{q="在哪里可以找到费古尔·双刃？",a="他位于幽灵岗哨，就在贯穿凄凉之地中部的道路北侧。",al={"费古尔·双刃位置","费古尔在哪","费古尔·双刃在哪"}},{q="费古尔·双刃会交付什么任务？",a="费古尔招募部落冒险者，打击当地的科卡尔半人马，追杀戴兹帕可汗，并领取剿杀敌对半人马的赏金。",al={"费古尔任务","费古尔想要什么"}},{q="费古尔为什么对访客如此冷淡？",a="凄凉之地是一片危险而严酷的荒原，周围盘踞着敌对的半人马氏族。费古尔驻守在孤立的岗哨里，无暇闲聊，只愿专心应对生存挑战，履行军人的职责。",al={"费古尔为何无礼","费古尔有话快说"}}},fx={f5a09a6e={q="费古尔·双刃支持哪一方？",a="费古尔是部落的骄傲成员，驻守在遥远的边境，致力于推进部落的利益，并保护他们的营地免受当地威胁。",al={"费古尔·双刃的阵营","费古尔是部落的吗","费古尔效忠谁"}},["8c623583"]={q="费古尔·双刃想要什么？",a="费古尔想要遏制威胁凄凉之地部落的敌对半人马氏族。他招募有能力的勇士领取悬赏，并与可汗德兹赫帕交锋。",al={"费古尔·双刃的目标","费古尔想做什么","费古尔需要什么"}},a5d710fc={q="费古尔·双刃为什么驻扎在这里？",a="费古尔驻扎在幽灵岗哨，负责监视当地半人马部族，并指挥行动，应对威胁部落在凄凉之地立足之地的敌人。",al={"费古尔·双刃为什么在幽灵岗哨","费古尔在这里的职责","费古尔为什么在这里"}}},fp="14,100,21.270.0,18.228.0,22.97.0,32.82.0,36.128.0,36.182.0"}
P.entries["npc:felix-whindlebolt"] = {n="菲利克斯",s="菲利克斯逃离诺莫瑞根的辐射后，在寒脊山谷的安威玛尔寻求庇护。霜鬃巨魔夺走了他的行李。",h="菲利克斯逃离诺莫瑞根的辐射后，在寒脊山谷的安威玛尔寻求庇护。霜鬃巨魔夺走了他的行李。",kw={"安威玛尔","寒脊山谷","菲利克斯","霜鬃","诺莫瑞根","难民","白须营地"},ang={["race:Dwarf"]="身为矮人，你能看到霜鬃巨魔在安威玛尔附近袭击侏儒难民。他们在寒脊山谷各处的袭击愈发猖獗。",["race:Gnome"]="身为侏儒，你与你的同胞有着相同的遭遇，诺莫瑞根沦陷后，你们被迫流落到丹莫罗的严寒之中。"},sec={{t="流离失所的旅人",b="辐射席卷诺莫瑞根时，菲利克斯逃离了这座城市。仓促之中，他落下了自己的行李和工具。\n\n霜鬃冰巨魔把他的大箱子、盒子和一桶螺栓带到了安威玛尔西南方的营地。没了这些装备，菲利克斯只能依靠旅人为他找回失物。"}},faq={{q="菲利克斯是谁？",a="菲利克斯是一名侏儒难民，在寒脊山谷的安威玛尔避难。他逃离诺莫瑞根时遗失了行李，随后被霜鬃巨魔拿走了。",al={"菲利克斯是谁","菲利克斯的故事","白须 营地的侏儒"}},{q="菲利克斯原本打算去哪里？",a="侏儒试图赶走穴居人的行动出了严重的差错，辐射随之席卷诺莫瑞根，菲利克斯因此逃离了家园。他抵达了寒脊山谷的矮人哨站安威玛尔，却发现这里并不适合侏儒居住。",al={"菲利克斯原本要去哪里","菲利克斯的目的地","菲利克斯为何在寒脊山谷"}},{q="他的财物遭遇了什么？",a="菲利克斯仓促逃离诺莫瑞根时，遗失了大箱子、盒子和一桶螺栓。霜鬃冰巨魔把这些东西带到了安威玛尔西南方的营地，让他失去了补给。",al={"谁偷走了菲利克斯的东西","菲利克斯被盗的装备","霜鬃巨魔与菲利克斯"}},{q="菲利克斯向冒险者出售什么？",a="菲利克斯不出售任何东西。他逃离诺莫瑞根时遗失了所有行李，如今身在安威玛尔，只能向那些为他找回大箱子、盒子和一桶螺栓的人致谢。",al={"菲利克斯出售的物品","菲利克斯提供什么","菲利克斯的物品"}}},fx={b1540142={q="菲利克斯效忠哪一方？",a="菲利克斯属于诺莫瑞根流亡者，效忠于大联盟。他和许多流离失所的侏儒一样，逃离了遭受辐射污染的诺莫瑞根废墟，如今栖身于寒脊山谷的安威玛尔，希望能与族人重聚。",al={"菲利克斯的阵营","菲利克斯是否属于联盟","菲利克斯为谁效力"}}},fp="17,146,20.284.0,25.160.0,29.218.0,33.183.0,36.163.0"}
P.entries["npc:fenrus-the-devourer"] = {n="吞噬者芬鲁斯",s="吞噬者芬鲁斯在影牙城堡上层的内殿中徘徊。大法师阿鲁高将这头巨大的座狼养作宠物和守卫，它的身躯因非自然的魔法而膨胀。想要进入大法师书房的闯入者，必须面对这头野兽和它的主人。",h="吞噬者芬鲁斯在影牙城堡上层的内殿中徘徊。大法师阿鲁高将这头巨大的座狼养作宠物和守卫，它的身躯因非自然的魔法而膨胀。想要进入大法师书房的闯入者，必须面对这头野兽和它的主人。",kw={"阿鲁高","芬鲁斯","吞噬者芬鲁斯","影牙城堡","银松森林","座狼"},ang={["class:Hunter"]="不要浪费时间试图魅惑Fenrus。暗影之牙的黑暗法术已将它的心智扭曲得无可挽回，荒野之力也无法约束它。",["class:Mage"]="Fenrus是大法师阿鲁高堕落的阴暗印记：他用奥术扭曲野兽，将它们变成形貌怪诞的看家守卫。",["class:Warlock"]="大法师阿鲁高召唤的虚空行者，表明这位昔日的达拉然法师在禁忌的暗影召唤术中已陷得多深。"},sec={{t="主人书房中的野兽",b="吞噬者芬鲁斯潜伏在影牙城堡深处，大法师阿鲁高的私人居室之外。与城墙上的狼人不同，芬鲁斯是一头座狼，身躯膨胀得异常巨大。这头野兽在阿鲁高私人书房的书架、卷轴和奥术器具之间徘徊。大法师将芬鲁斯养作宠物，也用它来防范那些前来取他性命的人。"},{t="腐化的力量",b="芬鲁斯异常庞大的身躯，表明自席瓦莱恩男爵败亡以来，黑暗魔法已浸透这座城堡。大法师阿鲁高或他放出的狼人通过奥术或暗影实验扭曲了这头生物，将一头本地的掠食者变成了贪食而势不可挡的巨兽。芬鲁斯如此狂野，又受到魔法束缚，没有猎人能够魅惑或驯服它。"},{t="阿鲁高的注视",b="惊扰芬鲁斯，可能会让粗心大意者丧命。座狼一旦发现闯入者，便会发出响彻堡垒的刺耳嚎叫，引起阿鲁高的注意。大法师将自己的黑暗意志投射到房间内，召唤虚空行者，帮助芬鲁斯压倒并吞噬进入此地的人。"}},faq={{q="芬鲁斯是什么生物？",a="芬鲁斯是一头异常巨大的座狼，是洛丹伦本土的一种形似狼的掠食者，而非用双腿行走的狼人。它异常庞大的身躯和凶残的性情，源于长期受到影牙城堡内黑暗魔法的侵蚀。",al={"芬鲁斯是狼人吗","芬鲁斯生物类型","芬鲁斯狼"}},{q="在哪里能找到芬鲁斯？",a="芬鲁斯在银松森林的影牙城堡高处的书房中徘徊。它的巢穴就位于通往大法师阿鲁高内部据点的必经之路上。",al={"芬鲁斯在哪里","芬鲁斯位置","芬鲁斯房间"}},{q="猎人能将芬鲁斯驯服为宠物吗？",a="不能。虽然芬鲁斯在分类上属于普通野兽，猎人却无法驯服它。它的心智已然破碎，只剩狂性，受大法师阿鲁高的黑暗意志束缚。",al={"能驯服芬鲁斯吗","芬鲁斯可以驯服吗","驯服芬鲁斯"}},{q="芬鲁斯遭到攻击时，阿鲁高为什么会召唤恶魔？",a="阿鲁高将芬鲁斯视为心爱的宠物，也是内殿前的最后一道守卫。战斗开始时，芬鲁斯发出咆哮，阿鲁高便会介入，在房间中召唤虚空行者，压倒那些威胁这头野兽的人。",al={"阿鲁高虚空行者","阿鲁高为什么帮助芬鲁斯","芬鲁斯虚空行者增援"}},{q="芬鲁斯为什么比普通座狼大得多？",a="人们认为，芬鲁斯庞大的体型源于大法师阿鲁高的黑暗实验，或是狼人侵占城堡时带来的魔法余波。",al={"芬鲁斯为什么巨大","芬鲁斯体型背景","巨型座狼"}},{q="与芬鲁斯交战时，整个地下城会发生什么？",a="芬鲁斯进入战斗时，会发出雷鸣般的咆哮，在影牙城堡内的任何地方都能听见。这声咆哮让所有人都知道，阿鲁高门外正在发生战斗。",al={"芬鲁斯咆哮","芬鲁斯嚎叫响彻地下城","影牙城堡响亮咆哮"}}},fp="19,206,29.328.0,15.312.0,21.291.1,32.209.0,26.160.0,33.147.0,54.215.0,47.154.0,55.166.0"}
P.entries["npc:field-marshal-snowfall"] = {n="大元帅斯诺·落雪",s="在铁炉堡的军事区，大元帅斯诺·落雪指挥联盟筹备应对希利苏斯的异种蝎威胁。这位矮人军官监管为即将到来的战争募集的物资，并奖赏为王国出力的人。",h="在铁炉堡的军事区，大元帅斯诺·落雪指挥联盟筹备应对希利苏斯的异种蝎威胁。这位矮人军官监管为即将到来的战争募集的物资，并奖赏为王国出力的人。",kw={"安其拉","大元帅斯诺·落雪","铁炉堡","军事区","徽记","希利苏斯","斯诺·落雪","战备"},ang={["faction:Alliance"]="身为联盟的一员，你看到斯诺·落雪号召从暴风城到达纳苏斯的各个种族，为即将到来的战斗倾尽库存。他代表着联盟在工业与军事上的共同意志。",["race:Dwarf"]="身为矮人，你会在Great Forge的军事区找到斯诺·落雪。他自豪地谈起守护Titans的造物，使其免遭一种古老而根深蒂固的邪恶侵害。"},sec={{t="安其拉战备军需官",b="大元帅斯诺·落雪在铁炉堡的军事区指挥联盟的备战工作。在他看来，即将到来的冲突远不止是一场边境小规模冲突。这是一场对抗远古敌人的战争，这个敌人仇视泰坦的一切造物。志愿者大量募集绷带、金属锭、皮革、草药和口粮。斯诺·落雪监管这些储备，确保联盟部队开始南下进军希利苏斯时，有武器可用，有护甲可穿，有口粮可吃。"},{t="通往希利苏斯之路",b="联盟各地的铁匠、采集者、厨师和士兵都在为备战出力。斯诺·落雪记录他们的贡献，接收表彰徽记，并向志愿者提供物资调配凭证。待双方阵营都集齐所需物资后，这些储备就会装箱，向南运往塞纳里奥要塞。从那里发起的大举进攻，将直指甲虫之墙背后的其拉虫群与上古之神。"}},faq={{q="大元帅斯诺·落雪是谁？",a="大元帅斯诺·落雪是驻守铁炉堡军事区的一位矮人高级军官。他负责监管和清点联盟的大批物资，为即将在希利苏斯展开的对抗其拉虫人的战争做准备。",al={"斯诺·落雪的职责","斯诺·落雪是谁","大元帅斯诺·落雪的故事"}},{q="联盟为什么要募集这么多物资？",a="一股远古力量从安其拉大门后威胁着卡利姆多。在大军穿越希利苏斯严酷的沙漠之前，联盟必须储备大量护甲、金属锭、医用绷带、食物和草药。",al={"为什么捐献布料","战备的目的","为什么募集战争物资"}},{q="募集完成后，物资会运往哪里？",a="当联盟和部落都集齐所需物资后，商队和补给船便会将储备运往希利苏斯的塞纳里奥要塞。双方联军会在那里建立前线集结地。",al={"物资运往哪里","物资如何处理"}},{q="荣誉徽章换取物资有什么用途？",a="捐献者捐出所需的武器和材料后，就会获得荣誉徽章换取物资。斯诺·落雪成批接收这些徽记，并以补给箱和装备奖赏尽责的联盟公民，酬谢他们的付出。",al={"上交徽记","徽记有什么用"}}},fx={ec7ab6f1={q="大元帅斯诺·落雪效忠哪一方？",a="大元帅斯诺·落雪是联盟一位坚定不移的指挥官。他驻守在铁炉堡的军事区，统筹整个阵营的后勤与资源征集，为在卡利姆多发动联合攻势做好准备。尽管这场战役要求联盟与部落在各自筹集物资的同时，维持一份勉强的合作，斯诺·落雪仍坚定效忠于大联盟的诸王国。",al={"大元帅斯诺·落雪属于联盟还是部落","大元帅斯诺·落雪的阵营","大元帅斯诺·落雪为谁效力"}},e1b72348={q="大元帅斯诺·落雪想要什么？",a="斯诺·落雪希望从联盟各地储备数量惊人的原材料、绷带、金属锭、草药和粮食。他要确保安其拉之门被攻破时，抵达希利苏斯严酷沙漠的常备军拥有所需的一切武器、药水和口粮，能够抵御克苏恩的大军，而不至于因消耗过度而崩溃。",al={"大元帅斯诺·落雪的目标","大元帅斯诺·落雪在征集什么"}},a597c3d5={q="大元帅斯诺·落雪为什么在铁炉堡？",a="斯诺·落雪将指挥部设在铁炉堡的军事区，因为这座矮人的山中城市是联盟工业与贸易的枢纽。在这里，他可以核查货运清单，协调公民士兵征集而来的物资，并将堆积如山的补给集中起来，再运往海另一边的希利苏斯集结地。",al={"大元帅斯诺·落雪为什么在铁炉堡","大元帅斯诺·落雪与军事区","大元帅斯诺·落雪为什么在这里"}}},fp="22,236,37.443.0,20.422.0,30.204.0,48.225.0,49.218.0,47.222.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="斯托布里奇元帅",s="在暴风城的城门前，斯托布里奇元帅协助马库斯·乔纳森将军守卫首都。她也接收大捷之后送来的报告和战利品。",h="在暴风城的城门前，斯托布里奇元帅协助马库斯·乔纳森将军守卫首都。她也接收大捷之后送来的报告和战利品。",kw={"元帅","城门","黑石之王","马库斯·乔纳森","奈法利安","石桥","暴风城","英雄谷"},ang={["class:Warrior"]="身为战士，你可以通过在联盟中争取崇高的军中地位，赢得前线士兵的尊重。斯托布里奇元帅是驻守暴风城城门的高级指挥官之一。",["faction:Alliance"]="身为联盟的一员，你与斯托布里奇元帅和马库斯·乔纳森将军等军官共同肩负着保卫暴风城的责任。"},sec={{t="城门前的亡灵壁垒",b="在暴风城的正门前，斯托布里奇元帅守望着通往英雄谷的东侧拱门。身为大联盟的高级军官，她与马库斯·乔纳森将军密切合作。守军、旅人和凯旋的勇士从她的岗哨下方经过。如果敌人突破外围防线，她随时准备组织驻军迎战。"},{t="战利品接收者",b="斯托布里奇元帅接收征讨王国重大威胁的战役报告和战利品。高级指挥官依靠她这样的军官核实重要情报，记录前线的胜利。其中就包括在黑石山的峭壁间击败军阀和怪物的战绩。"}},faq={{q="斯托布里奇元帅在哪里？",a="斯托布里奇元帅站在暴风城英雄谷东北部的一座拱门下，进入城门后，她就在马库斯·乔纳森将军的右侧。",al={"斯托布里奇元帅位置","斯托布里奇元帅在哪里","寻找斯托布里奇元帅"}},{q="斯托布里奇元帅在暴风城担任何种职责？",a="斯托布里奇元帅是一名联盟高级军官，协助马库斯·乔纳森将军守卫暴风城正门。她也接收凯旋的联盟勇士带回的重要军事报告和战利品。",al={"斯托布里奇元帅的职责","斯托布里奇元帅的作用","斯托布里奇元帅是谁"}},{q="元帅在联盟中是什么军衔？",a="元帅是大联盟最高的军官军衔之一，仅次于大元帅。这一级别的军官负责重要战术部署、城市防区和战略驻军。",al={"联盟元帅军衔","斯托布里奇元帅的军衔有多高"}},{q="哪些重要任务与斯托布里奇元帅有关？",a="斯托布里奇元帅接收任务“黑石之王”的报告和战利品。当联盟冒险者将巨龙的头颅带回暴风城城门时，这份报告便证实了奈法利安已被击败。",al={"斯托布里奇元帅任务","黑石之王任务交付者"}}},fx={["63c0e4ac"]={q="斯托布里奇元帅是谁？",a="斯托布里奇元帅是联盟军队中的一名人类高级指挥官，驻守在暴风城城门。她与城中的领导者一同驻守英雄谷，负责关键防务，也是王国的高级军事长官之一。",al={"斯托布里奇元帅是谁","斯托布里奇元帅的身份","斯托布里奇元帅的背景"}},["05caa28c"]={q="斯托布里奇元帅效忠哪一方？",a="斯托布里奇元帅对暴风城王国和大联盟忠心不二。她直接听命于王国的最高指挥官，协助保卫首都，抵御外来威胁。",al={"斯托布里奇元帅的阵营","斯托布里奇元帅的效忠对象","斯托布里奇元帅为谁效力"}},d0356b7c={q="斯托布里奇元帅为什么在这里？",a="她奉命驻守英雄谷，守卫首都的宏伟入口，协助马库斯·乔纳森将军协调暴风城的军队，并接收联盟勇士带回的紧急军情和战利品。",al={"斯托布里奇元帅为什么在暴风城","斯托布里奇元帅为什么在城门","斯托布里奇元帅与英雄谷"}},a46f624c={q="斯托布里奇元帅想要什么？",a="斯托布里奇力求全面守护暴风城，击败王国最强大的敌人，并热切地查验冒险者带来的重大胜利凭证，以确保王国的安全。",al={"斯托布里奇元帅的目标","斯托布里奇元帅想要什么","斯托布里奇元帅的动机"}},af024441={q="斯托布里奇元帅与谁有关联？",a="她与统领暴风城城防的马库斯·乔纳森将军密切合作，也是伯瓦尔·弗塔根公爵麾下庞大军事体系的一员，守护着少年安度因·乌瑞恩国王的国土。",al={"斯托布里奇元帅的关系","斯托布里奇元帅与谁合作","斯托布里奇元帅与马库斯·乔纳森"}}},fp="25,163,22.341.0,18.305.0,43.181.0,54.232.0,45.198.0,52.200.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="大副菲兹莫斯",s="在米奈希尔港的深水旅店外，大副菲兹莫斯终日饮酒。他曾是库尔提拉斯第三舰队中浪花女神号号的大副，也是舰队在第二次战争中覆灭后唯一已知仍然在世的幸存者。如今，他寻求愿意面对那些溺亡战友不息亡魂的旅人。",h="在米奈希尔港的深水旅店外，大副菲兹莫斯终日饮酒。他曾是库尔提拉斯第三舰队中浪花女神号号的大副，也是舰队在第二次战争中覆灭后唯一已知仍然在世的幸存者。如今，他寻求愿意面对那些溺亡战友不息亡魂的旅人。",kw={"深水旅店","帕雷斯之眼","大副菲兹莫斯","菲兹莫斯","库尔提拉斯","失落的舰队","米奈希尔港","第三舰队","浪花女神号"},ang={["faction:Alliance"]="菲兹莫斯回忆起联盟海军历史上悲惨的一页，以及对抗部落奴役的巨龙大军时蒙受的损失。",["race:Human"]="身为人类，你与库尔提拉斯老兵菲兹莫斯有着同族之谊。他的人民曾在Second War期间为保卫洛丹伦付出巨大的牺牲。"},sec={{t="潦倒的水手",b="在米奈希尔港的深水旅店外，大副菲兹莫斯独自饮酒。他不事洗漱，身上的恶臭让许多顾客避之不及，大多数人眼中只有一个借酒浇愁的潦倒老水手。那些坐下来倾听的人，才会听到一支骄傲的舰队如何毁于烈火与利爪。"},{t="第三舰队的覆灭",b="第二次战争期间，菲兹莫斯在浪花女神号号上担任大副。这艘船随库尔提拉斯的第三舰队出征，对抗部落。在湿地近海，龙喉氏族兽人驱使被奴役的红龙伏击舰队，焚毁了舰船。船只纷纷断裂沉没。只有菲兹莫斯成功活着游到了岸上。"},{t="挥之不去的诅咒",b="大副菲兹莫斯从龙焰中幸存下来，但他昔日的船员却未能安息。他们的船只如今被称为失落的舰队，受诅咒的亡灵水手仍被困在这些水下坟墓中。愧疚与恐惧始终纠缠着菲兹莫斯，他请求旅人消灭这些水手，并寻回或许能解除束缚其灵魂的邪恶力量的古老遗物。"}},faq={{q="大副菲兹莫斯是谁？",a="大副菲兹莫斯是一名年迈的库尔提拉斯人水手，曾担任浪花女神号号的大副。他在第二次战争中从库尔提拉斯第三舰队的覆灭中幸存，如今在米奈希尔港的深水旅店外饮酒度日。",al={"菲兹莫斯的故事","菲兹莫斯是谁","大副菲兹莫斯"}},{q="他的船遭遇了什么？",a="第二次战争期间，龙喉氏族兽人骑乘被奴役的红龙，伏击了浪花女神号号和第三舰队的其余舰船。船只燃起大火，在湿地近海的礁石上断裂。",al={"浪花女神号遭遇了什么","第三舰队的覆灭","他的船为何沉没"}},{q="失落的舰队在哪里？",a="失落的舰队那些破碎的船体沉在米奈希尔港以北、礁石遍布的湿地沿岸水中。鱼人和溺亡水手不息的亡魂守在那里。",al={"失落的舰队位置","沉船在哪里","菲兹莫斯的船的位置"}},{q="他为何希望冒险者对付昔日的船员？",a="第三舰队中溺亡的水手化作了受诅咒、备受折磨的亡灵。菲兹莫斯寻求旅人让他们安息，并寻回那些束缚着他们灵魂的神器。",al={"受诅咒的船员任务背景","为何杀死他的船员"}},{q="帕雷斯之眼是什么？",a="帕雷斯之眼是一件古老而强大的神器，曾由第三舰队运载。它的黑暗力量与折磨那些沉船水手的诅咒有关，寻回它是让溺亡舰队安息的关键。",al={"帕雷斯之眼","帕雷斯遗物"}},{q="菲兹莫斯为何如此难闻？",a="舰队沉没时，菲兹莫斯失去了一切，如今在深水旅店外醉生梦死，任由自己日渐潦倒。他穿着被海水浸透的破衣烂衫，鲜少洗漱。",al={"菲兹莫斯为何难闻","菲兹莫斯的恶臭"}}},fp="22,319,15.263.0,27.323.0,19.336.1,30.215.0,26.196.0,32.167.0,51.178.0,26.213.0,34.159.0"}
P.entries["npc:fizzle-brassbolts"] = {n="菲兹尔·铜栓",s="菲兹尔·铜栓是一位杰出的侏儒工程师，驻扎在千针石林沙漠赛道上烈日炙烤的盐滩。他与竞争对手、地精普兹克共同创办了这条赛道，让侏儒的精密工程与地精鲁莽的奇思妙想在高速火箭车竞赛中一较高下。他不断搜寻零件、燃料和稀奇古怪的沙漠材料，以维持车队运转。",h="菲兹尔·铜栓是一位杰出的侏儒工程师，驻扎在千针石林沙漠赛道上烈日炙烤的盐滩。他与竞争对手、地精普兹克共同创办了这条赛道，让侏儒的精密工程与地精鲁莽的奇思妙想在高速火箭车竞赛中一较高下。他不断搜寻零件、燃料和稀奇古怪的沙漠...",kw={"铜栓","菲兹尔","沙漠赛道","普兹克","火箭车","闪光平原","千针石林"},ang={["faction:Alliance"]="虽然身处中立的竞速地带，菲兹尔仍会友善地接待途经此地、南下塔纳利斯的联盟旅人，并为他们提供机械活计。",["profession:Engineering"]="工程师同行会欣赏菲兹尔的钻研精神：即使身处恶劣的沙漠环境，他依然致力于优化火箭推进技术，绘制尖端车辆设计图。",["race:Gnome"]="菲兹尔肩负着整个诺莫瑞根的荣誉来到沙漠，铁了心要证明侏儒的精密技术胜过地精的鲁莽。"},sec={{t="原则与活塞之争",b="在闪光平原蒸腾的热浪中，政治同盟与古老宿怨都让位于引擎的轰鸣。菲兹尔·铜栓来到这里，只为一个目标：彻底证明侏儒工艺远胜于地精粗糙的修修补补。他与地精同行普兹克一起协助规划了沙漠赛道，为这片原本荒凉的盆地带来了赛车、维修组和观众。"},{t="盐滩上的钻研",b="要以惊人的速度驰骋于干燥的盐滩，就得不断随机应变，菲兹尔也从不回避异乎寻常的实验。无论是测试用当地生物毒液调制的易爆混合物，还是雇用旅人取回替换用的机械零件，菲兹尔都决心让自己的车手跑得比任何会爆炸的地精机器更快。"}},faq={{q="菲兹尔·铜栓是谁？",a="菲兹尔·铜栓是一位侏儒工程学大师，也是驻扎在千针石林沙漠赛道的侏儒赛车队的主要组织者。",al={"菲兹尔是谁","菲兹尔·铜栓的故事","赛道上的侏儒"}},{q="菲兹尔为什么来到闪光平原？",a="他来到这里，是为了与地精工程师普兹克解决一场技术争论，看看究竟哪个种族的工程技术更胜一筹。他们共同建立了沙漠赛道，让各自的火箭车在平坦的盐盆地上正面较量。",al={"菲兹尔为何在此","赛道的用途","为何修建赛道"}},{q="铜栓兄弟是谁？",a="菲兹尔和他的兄弟维兹尔·铜栓在沙漠赛道经营着侏儒赛车队。他们的新型火箭车速度太快，驾驶员接连撞车，因此他们向铁炉堡的朋友飞行员比罗·长须求助，索要攻城坦克防撞头盔。",al={"铜栓兄弟","维兹尔·铜栓","菲兹尔的兄弟"}},{q="菲兹尔为什么需要用生物毒液制造赛车？",a="菲兹尔不断用当地材料做实验，配制强效的引擎油液、添加剂和助燃剂，好让自己的火箭车胜过普兹克的机器。",al={"盐滩毒液任务","毒液赛车燃料","他为何需要毒液"}},{q="菲兹尔会与地精交战吗？",a="不会动用武器。尽管彼此怀有强烈的同行嫉妒，菲兹尔和普兹克仍在赛道上维持着脆弱的中立休战关系，一心专注于高速竞赛。",al={"菲兹尔是否敌视地精","菲兹尔与普兹克的争斗"}},{q="飞行员比罗·长须是谁？",a="飞行员比罗·长须是铁炉堡攻城坦克旅的一名矮人攻城坦克驾驶员，也是铜栓兄弟的朋友，和他们一样喜爱危险的机械。",al={"与飞行员比罗·长须的关系","菲兹尔的飞行员朋友"}}},fx={["092966e5"]={q="菲兹尔·铜栓效忠哪一方？",a="菲兹尔·铜栓代表侏儒及其在沙漠赛道的车队。他对联盟和部落的旅人都保持中立，在闪光平原与普兹克等地精工程师维持着务实的合作关系。虽然他竭力证明侏儒工程学优于地精工程学，但双方的竞争局限于沙漠赛道，而非公开交战。",al={"菲兹尔属于联盟吗","菲兹尔·铜栓的阵营","菲兹尔为谁效力"}},["4ec804ad"]={q="菲兹尔·铜栓想要什么？",a="菲兹尔一心想证明侏儒工程学绝对胜过地精技术。为此，他与地精对手普兹克共同创立了沙漠赛道。他专注于研发速度更快的火箭赛车，寻找闪光平原蝎子咸腥的毒液等珍稀燃料原料，并在盐碱地赛道上击败地精车队。",al={"菲兹尔想要什么","菲兹尔·铜栓的目标","菲兹尔为什么参加赛车"}}},fp="17,250,33.232.0,22.236.0,25.123.0,44.258.0,32.242.0,50.141.0,38.155.0,23.174.0"}
P.entries["npc:fleet-master-seahorn"] = {n="舰队指挥官卡拉·海角",s="舰队指挥官卡拉·海角是一位经验丰富的牛头人航海家，担任藏宝海湾黑水海盗的海军指挥官。他与大财主里维加兹一同驻守在水手之家旅店的上层露台，负责这座地精港口的海上防务。他的首要职责是保护港湾，抵御死敌血帆海盗日益逼近的威胁。",h="舰队指挥官卡拉·海角是一位经验丰富的牛头人航海家，担任藏宝海湾黑水海盗的海军指挥官。他与大财主里维加兹一同驻守在水手之家旅店的上层露台，负责这座地精港口的海上防务。他的首要职责是保护港湾，抵御死敌血帆海盗日益逼近的威胁。",kw={"黑水海盗","血帆海盗","藏宝海湾","法迪尔海湾","菲尔拉伦","舰队指挥官卡拉·海角","大财主里维加兹","水手之家旅店","卡拉·海角","蛮荒海岸"},ang={["class:Rogue"]="在藏宝海湾活动的潜行者会发现，卡拉·海角是海岸谍报行动的核心，组织着针对血帆战舰的秘密突袭，并截获敌方命令。",["faction:Horde"]="虽然卡拉·海角是牛头人，但他只效忠热砂港和Blackwater Raiders，对部落与联盟的旅客一视同仁，保持中立。",["race:Tauren"]="卡拉·海角是极少数离开卡利姆多内陆平原、精通远洋航海的牛头人之一，担任着一座中立地精港口的舰队指挥官。"},sec={{t="远洋上的公牛",b="牛头人以栖居平原而闻名于卡利姆多，舰队指挥官卡拉·海角却选择了截然不同的海上生活。他身着海盗装束，统率黑水海盗的舰队，这是热砂港在荆棘谷经营的私人海上武装。卡拉·海角驻守在水手之家旅店顶层，与大财主里维加兹并肩共事，为藏宝海湾协调航线、船员调配和海岸防务。这座港口虽无法无天，管理却十分严密。"},{t="保卫海湾",b="卡拉·海角始终最为担忧的是血帆海盗，他们已在南部的蛮荒海岸沿线建立了设防营地，并将战舰停泊在近海。当情报揭示舰队指挥官菲尔拉伦及血帆海盗首领们打算直接进攻并洗劫藏宝海湾时，卡拉·海角果断采取行动。他派遣雇佣兵夺取敌方信件，并登上敌方旗舰除掉菲尔拉伦、基尔豪和斯蒂沃特，成功使港口免遭彻底毁灭。"},{t="放眼诸海",b="除了抵御海盗袭击，卡拉·海角还管理着遍布东部王国的各类贸易与打捞业务。他与打捞潜水员合作，在法迪尔海湾附近的阿拉希海岸外协调沉没宝藏的回收工作，找回精灵遗物。他还将途经镇上的有利可图的商机告知大财主里维加兹，例如钓鱼竞赛和当地贸易，确保黑水舰队资金充足，并领先于竞争对手。"}},faq={{q="舰队指挥官卡拉·海角在哪里？",a="他位于藏宝海湾水手之家旅店的顶层和露台，就站在大财主里维加兹身旁，俯瞰着码头。",al={"卡拉·海角在哪里","卡拉·海角位置","寻找卡拉·海角"}},{q="为什么一个牛头人会担任海盗舰队指挥官？",a="虽然大多数牛头人仍与莫高雷的平原和精神传统紧密相连，卡拉·海角却选择了航海与海上佣兵的生活。他的航海本领和统率威望，使他得以领导大财主里维加兹麾下的黑水海盗。",al={"牛头人海盗","卡拉·海角为什么是海盗","藏宝海湾的牛头人"}},{q="卡拉·海角与大财主里维加兹是什么关系？",a="卡拉·海角是大财主里维加兹的副手，也是其麾下黑水海盗的海军指挥官。大财主里维加兹负责政治、贸易和财务，卡拉·海角则掌管藏宝海湾的舰队、战术情报和防御军事行动。",al={"卡拉·海角与大财主里维加兹","卡拉·海角是大财主里维加兹的保镖吗","谁为大财主里维加兹效力"}},{q="黑水海盗是谁？",a="黑水海盗是一支效忠热砂港的私掠舰队，以藏宝海湾为基地。他们与肆意劫掠的不法海盗不同，是一支得到认可的海军，负责保护地精商人的利益，维持南部海域的秩序。",al={"黑水海盗","卡拉·海角属于哪个阵营","藏宝海湾海盗"}},{q="卡拉·海角为什么要阻止血帆海盗？",a="血帆海盗是黑水海盗的死敌。在舰队指挥官菲尔拉伦的率领下，血帆海盗已在蛮荒海岸沿线扎营，并打算攻占藏宝海湾。卡拉·海角始终致力于抢先挫败他们的入侵计划。",al={"卡拉·海角对抗血帆海盗","血帆海盗冲突","为什么对抗血帆海盗"}},{q="卡拉·海角在荆棘谷以外也有业务往来吗？",a="有。卡拉·海角与德拉克里格博士和沙克斯·奥布里等打捞人员合作，回收阿拉希高地近海、法迪尔海湾附近沉没的货物与精灵宝藏，并将珍贵的文物送回他在藏宝海湾的驻地。",al={"法迪尔海湾卡拉·海角","卡拉·海角沉没宝藏","阿拉希任务卡拉·海角"}}},fp="20,193,23.444.0,17.432.1,20.405.0,38.152.0,49.217.0,51.220.0,31.264.0,55.221.0,57.235.0"}
P.entries["npc:foggy-mackreel"] = {n="醉鬼马克里尔",s="在断裂的萨多尔大桥上，醉鬼马克里尔惦记着一批要送往南海镇的月光酒。这名矮人被困在大桥下层残破的石台上，脚下是令人目眩的深渊，心思却仍放在差事上。",h="在断裂的萨多尔大桥上，醉鬼马克里尔惦记着一批要送往南海镇的月光酒。这名矮人被困在大桥下层残破的石台上，脚下是令人目眩的深渊，心思却仍放在差事上。",kw={"阿拉希","醉鬼","马克里尔","月光酒","南海镇","萨多尔大桥","湿地"},ang={["faction:Alliance"]="身为往返于铁炉堡和南海镇之间的联盟信使，你或许会遇到醉鬼，替他运送滞留的货物，帮助这位同属联盟的臣民。",["race:Dwarf"]="身为矮人，你或许能理解马克里尔的顽强固执，以及他异于常人的轻重之分：比起被困在足以致命的深渊上方，他更看重按时送达烈酒。"},sec={{t="受困桥下",b="醉鬼马克里尔在萨多尔大桥下断裂的桥墩上等待，虽然处境危险，却依然镇定。黑铁的破坏和战火摧毁了这座连接湿地与阿拉希高地的大桥。马克里尔没怎么考虑获救的事；他只想把烈性月光酒送到希尔斯布莱德丘陵的南海镇，交给那里的酒客。他雇用身手足够敏捷、能抵达他所在石台的过路旅人，替他完成这趟送酒的差事。"}},faq={{q="醉鬼马克里尔是谁？",a="醉鬼马克里尔是一名矮人信使，被困在断裂的萨多尔大桥下残破的石柱上。脚下的深渊并不让他担忧；他一心只想把月光酒送到。",al={"醉鬼马克里尔","醉鬼是谁","马克里尔非玩家角色"}},{q="在哪里可以找到醉鬼马克里尔？",a="醉鬼马克里尔在萨多尔大桥中央断裂桥段下方半腰处的一座石台上等待。从阿拉希高地一侧的桥体小心跳下，就能到达他所在的地方。",al={"醉鬼马克里尔在哪","醉鬼马克里尔位置","怎么找到马克里尔"}},{q="醉鬼马克里尔为什么会在下面？",a="醉鬼马克里尔在旅途中被困在了萨多尔大桥的残骸里。他最关心的是找到一个人，把他的月光酒继续送往南海镇。",al={"醉鬼为什么受困","马克里尔怎么到那里的","他为什么在桥上"}},{q="醉鬼马克里尔提供什么任务？",a="醉鬼马克里尔提供“马克里尔的月光酒”任务，请旅人带上一壶他酿的烈酒，穿过阿拉希高地，送到南海镇的旅店。",al={"醉鬼任务","马克里尔的月光酒任务","醉鬼提供什么任务"}}},fp="14,136,20.402.0,22.173.0,32.186.0,33.171.0,37.153.0"}
P.entries["npc:foreman-oslow"] = {n="工头奥斯洛",s="在湖畔镇，工头奥斯洛正艰难地重建止水湖上的桥。黑石兽人摧毁了这座桥，而工具遗失、物资被盗又让工程停滞不前。他需要有人帮忙找回工具、收集材料，好让镇子恢复这条贸易通道。",h="在湖畔镇，工头奥斯洛正艰难地重建止水湖上的桥。黑石兽人摧毁了这座桥，而工具遗失、物资被盗又让工程停滞不前。他需要有人帮忙找回工具、收集材料，好让镇子恢复这条贸易通道。",kw={"黑石","止水湖上的桥","工头奥斯洛","闪金镇","湖畔镇","奥斯洛","赤脊山","工具箱"},ang={["faction:Alliance"]="身为联盟的一员，你知道湖畔镇的断桥让东部边境失去了屏障。修复这座桥对保障边境安全至关重要。",["profession:Mining"]="身为矿工，你知道奥斯洛需要原材料、金属制品和采石场运来的石料，才能重建损毁的石砌结构。"},sec={{t="一分为二的镇子",b="工头奥斯洛在断裂的止水湖上的桥旁忙碌，试图让湖畔镇重新连通。这座桥横跨止水湖，将西面通往艾尔文的道路与东岸连接起来。黑石兽人从石堡的峭壁上下来，袭击了这座桥，意图瘫痪湖畔镇的贸易和军事调动。桥梁断裂后，镇子被分隔开来，失去了屏障。"},{t="沉没的钢铁与被盗的石料",b="工头奥斯洛丢失了修桥所需的工具和材料。桥梁倒塌后，补充的工具从闪金镇经陆路运来，随后装上了湖上的渡船。黑石兽人的投石车击中了船只，让奥斯洛沉重的铁制工具箱沉入止水湖泥泞的湖底。赤脊山的豺狼人还劫走了一支从暴风城运送新材料的商队，夺走了架设桥拱所需的铁桩和铆钉。"}},faq={{q="工头奥斯洛是谁？",a="工头奥斯洛是湖畔镇的一名人类石匠和建筑工。他负责止水湖上的桥的维护与重建工作。",al={"工头奥斯洛","奥斯洛是谁","湖畔镇建筑工"}},{q="止水湖上的桥为什么断了？",a="黑石兽人摧毁了止水湖上的桥。这座桥被毁后，湖畔镇的主要通道被切断，镇子的防御被削弱，东西两岸之间也无法便捷往来了。",al={"桥为什么断了","谁摧毁了湖畔镇的桥","止水湖上的桥被毁"}},{q="奥斯洛遗失的工具在哪里？",a="奥斯洛沉重的工具箱就在止水湖底。黑石投石车的一轮轰击击沉了从闪金镇运送工具箱的船。",al={"工具在哪里","遗失工具的位置","奥斯洛的工具箱"}},{q="桥为什么还没修好？",a="奥斯洛无法恢复施工，因为黑石兽人的投石车把他的工具击沉在湖里，豺狼人又抢走了运来的建筑物资。他需要外人帮忙找回设备和材料。",al={"桥为什么还没修好","湖畔镇修桥延误"}},{q="奥斯洛的物资最初是从哪里运来的？",a="奥斯洛补充的工具由货车从艾尔文森林的闪金镇运来，随后转装到湖上的渡船，以绕过断桥。",al={"补给货车的来处","工具从哪里运来"}},{q="奥斯洛正面临哪些威胁？",a="奥斯洛面对着附近高地上的黑石兽人，他们的攻城器械不断轰击湖面，还有四处游荡、袭击补给车队的豺狼人。",al={"奥斯洛的敌人","谁在袭击桥梁"}}},fp="13,190,17.337.0,29.408.0,21.125.0,35.184.0,29.132.0,40.201.0,48.134.0,35.135.0"}
P.entries["npc:foreman-stonebrow"] = {n="工头乔尼·石眉",s="在古博拉采掘场，工头乔尼·石眉正面对穴居人的袭击，矿工们已被赶出了矿坑。他代表矿工联盟寻求援助，守卫这处采掘场。",h="在古博拉采掘场，工头乔尼·石眉正面对穴居人的袭击，矿工们已被赶出了矿坑。他代表矿工联盟寻求援助，守卫这处采掘场。",kw={"丹莫罗","工头乔尼·石眉","古博拉","古博拉采掘场","矿工联盟","石眉","穴居人"},ang={["profession:Mining"]="身为矿工，帮助石眉夺回采掘场的石料和矿藏也与你息息相关，这些资源对卡兹莫丹的行会运作至关重要。",["race:Dwarf"]="对矮人而言，穴居人袭击古博拉采掘场，既打击了铁炉堡的石材产业，也让人想起潜藏在矮人领地下方的古老威胁。"},sec={{t="古博拉的危机",b="工头乔尼·石眉在卡拉诺斯以东的古博拉采掘场主持矿工联盟的工作。向深处挖掘时，矿工们挖通了采掘场下方的穴居人洞穴。这些生物涌入矿坑，迫使矿工们丢下工具逃离。石眉仍守在采掘场边缘，寻找愿意击退穴居人的旅者。"}},faq={{q="工头乔尼·石眉是谁？",a="工头乔尼·石眉负责矿工联盟在丹莫罗古博拉采掘场的工作。他协调挖掘作业，并努力保障采掘场的安全。",al={"石眉","石眉是谁","工头乔尼·石眉的故事"}},{q="工头乔尼·石眉为何寻求帮助？",a="挖掘作业挖通了古博拉采掘场下方的穴居人洞穴。穴居人席卷了下层平台，杀害工人，将幸存的矿工逼回采掘场边缘的营地。",al={"古博拉穴居人问题","为何需要帮助","采掘场任务"}},{q="矿工联盟是什么组织？",a="矿工联盟是一个总部设在铁炉堡的矮人行会和贸易组织。它负责卡兹莫丹各地的采矿勘探、资源采集和采石作业。",al={"矿工联盟","矿工联盟是什么组织"}},{q="在哪里可以找到工头乔尼·石眉？",a="工头乔尼·石眉位于丹莫罗东部古博拉采掘场边缘的营地，就在通往洛克莫丹的道路旁。",al={"石眉的位置","工头乔尼·石眉在哪里"}}},fx={["2635f3c5"]={q="工头乔尼·石眉站在哪一边？",a="工头乔尼·石眉效忠矿工联盟和矮人王国铁炉堡，坚定地站在联盟一边。他监督丹莫罗的公共开掘工程，并寻求联盟冒险者的帮助，清除威胁铁炉堡采矿作业的敌人。",al={"石眉的阵营","石眉为谁效力","石眉与联盟"}},c868fd05={q="工头乔尼·石眉为什么在古博拉采掘场？",a="工头乔尼·石眉受派前往古博拉采掘场，代表矿工联盟监督挖掘和资源开采。穴居人突然涌入，工人们无力抵挡，他便留守在矿坑附近，召集援手，协调夺回采掘场的行动。",al={"石眉为何在这里","石眉与古博拉","石眉在这里做什么"}}},fp="17,171,23.302.0,25.149.0,41.180.0,27.171.0,37.120.0"}
P.entries["npc:foreman-thazz-ril"] = {n="工头塔兹利尔",s="在试炼谷，苦工们听从工头塔兹利尔的指挥。这位兽人劳工主管督促工人按时干活，为年轻的勇士备好物资，但偷懒的苦工和附近的邪教徒让他烦恼不已。",h="在试炼谷，苦工们听从工头塔兹利尔的指挥。这位兽人劳工主管督促工人按时干活，为年轻的勇士备好物资，但偷懒的苦工和附近的邪教徒让他烦恼不已。",kw={"木棒","火刃氏族","杜隆塔尔","工头","懒惰的苦工","塔兹利尔","试炼谷"},ang={["profession:Mining"]="身为矿工，你能看出塔兹利尔有多珍视自己的装备：他迫切地想从火刃集会所找回自己的附魔矿镐。",["race:Orc"]="身为即将成年的年轻兽人，你会看到，部落在战场上的力量离不开纪律严明的劳动。"},sec={{t="管好苦工",b="在试炼谷，工头塔兹利尔指挥苦工砍伐木材，为营地和年轻的勇士收集物资。在杜隆塔尔荒凉的红色岩地上建立家园，需要持续不断的劳作，苦工们却常常在沙漠的烈日下打盹。塔兹利尔派初来乍到的新兵带上他的木棒，叫醒那些熟睡的苦工，让建设继续进行。"},{t="落入险境的矿镐",b="塔兹利尔在火刃集会所勘探矿产资源时，仓皇逃离了里面的黑暗邪教徒，不慎遗落了自己珍爱的附魔矿镐。如今，术士和他们的恶魔爪牙聚集在洞中。塔兹利尔行事谨慎，不敢亲自取回工具，只能依靠年轻的部落预备勇士深入洞穴，将它带回来。"}},faq={{q="工头塔兹利尔是谁？",a="工头塔兹利尔是杜隆塔尔试炼谷的一名兽人劳工主管。他管理工人，监督伐木，并勘察这一带的资源，帮助部落建立定居点。",al={"塔兹利尔是谁","塔兹利尔 试炼谷","工头塔兹利尔的故事"}},{q="塔兹利尔为什么给玩家木棒？",a="塔兹利尔手下的苦工经常不去收集木材，反而倒头大睡。他给新兵一根附魔木棒，用来叫醒苦工，让他们回去干活。",al={"为什么要打懒惰的苦工","塔兹利尔的木棒","懒惰的苦工任务背景"}},{q="塔兹利尔的矿镐为什么在火刃氏族的洞穴里？",a="塔兹利尔在火刃集会所勘探矿脉时，把自己的附魔矿镐遗落在了那里。他遇到里面的邪教徒后便逃走了。",al={"塔兹利尔的矿镐","矿镐为什么在集会所","火刃氏族 矿镐"}},{q="他在部落中担任什么职务？",a="塔兹利尔是一名平民监工，并非前线士兵或萨满祭司。他监督体力劳动，维持建筑物资的供应，并督促苦工勤勉干活。",al={"塔兹利尔是士兵吗","塔兹利尔的职级"}}},fp="17,177,25.336.0,30.350.0,25.196.0,44.164.0,54.143.0,30.163.0"}
P.entries["npc:foreman-thistlenettle"] = {n="工头希斯耐特",s="在死亡矿井下方，工头希斯耐特的队伍被困在月溪镇地下。他曾同时为矿工联盟和探险者协会效力，并在隧道坍塌时与手下的矿工一同丧生。如今，他化作食尸鬼再次游荡，身上仍带着公会徽章。",h="在死亡矿井下方，工头希斯耐特的队伍被困在月溪镇地下。他曾同时为矿工联盟和探险者协会效力，并在隧道坍塌时与手下的矿工一同丧生。如今，他化作食尸鬼再次游荡，身上仍带着公会徽章。",kw={"徽章","坍塌","死亡矿井","工头","食尸鬼","矿工联盟","希斯耐特","维尔德"},ang={["profession:Mining"]="身为矿工，你知道隧道坍塌和地下深处的敌人会让每一次下矿都充满危险。",["race:Dwarf"]="身为矮人，你知道探险者协会的一名工头及其队伍的覆灭，揭示了人类王国地下潜藏的危险。"},sec={{t="兄弟的悲痛",b="维尔德·蓟草一直在暴风城等待失踪兄弟及其队伍的消息。隧道被占据，所有消息都无法传到他耳中。如今有传言说，那位死去的工头正在亡者之中游荡。死亡矿井附近的旅人受托终结他的痛苦，并将他的徽章交给悲痛的兄弟。"},{t="死亡矿井的悲剧",b="在迪菲亚潜行者完全控制死亡矿井之前，矿工们曾在这里开采富饶的矿脉。工头希斯耐特曾带领一支同时为矿工联盟和探险者协会效力的探险队。在月溪镇地下深处，一场猛烈的坍塌切断了他们通往地面的道路。矿工们死于黑暗之中，却未能得到安息。死亡之力的污染使希斯耐特和他的队伍化作饥渴的食尸鬼，在阴暗的通道中游荡。"}},faq={{q="工头希斯耐特生前是什么人？",a="工头希斯耐特是一名矮人，同时为矿工联盟和探险者协会效力。在亡命之徒将死亡矿井彻底设防之前，他曾带领矿工前往那里，开采并勘测地下矿脉。",al={"希斯耐特的故事","工头希斯耐特是谁","希斯耐特的背景"}},{q="工头希斯耐特为什么变成了亡灵食尸鬼？",a="一场坍塌掩埋了工头希斯耐特和他的采矿队伍，夺走了他们的生命。随后，矿井中的黑暗能量或残留的通灵术让他们的遗骸化作不得安息的食尸鬼。",al={"他为什么是食尸鬼","希斯耐特怎么死的","希斯耐特亡灵"}},{q="工头希斯耐特在哪里？",a="工头希斯耐特在死亡矿井外围迷宫中一条坍塌的死路里游荡，那里位于通往矿井深处的传送门之前。他昔日的矿工如今也已化作食尸鬼，围在他身边。",al={"哪里能找到希斯耐特","希斯耐特的位置","死亡矿井工头位置"}},{q="谁在寻找工头希斯耐特？",a="工头希斯耐特的兄弟维尔德·蓟草正在寻找能证实其遭遇的证据。维尔德住在暴风城的矮人区，请求旅人带回希斯耐特的徽章。",al={"谁想要希斯耐特死","维尔德的兄弟","希斯耐特任务发布者"}}},fx={["81248170"]={q="工头希斯耐特站在哪一边？",a="工头希斯耐特如今不再属于任何阵营，也不再为任何事业效力。他已化为一只毫无心智、饥渴难耐的食尸鬼，与复生的手下袭击所有愚蠢到闯入死亡矿井那片坍塌角落的人，无论来者是迪菲亚、联盟，还是四处寻宝的猎人。",al={"希斯耐特的阵营","工头希斯耐特是否敌对","希斯耐特为谁效力"}},a595eadc={q="工头希斯耐特想要什么？",a="这个矮人生前无论怀着怎样的抱负，都已葬送在塌方之中。化为亡灵后，工头希斯耐特再无宏图或阴谋，只有所有食尸鬼共有的盲目而躁动的饥饿，驱使他徘徊于黑暗的碎石间，搜寻任何靠近的活物。",al={"希斯耐特想要什么","工头希斯耐特的动机","希斯耐特的目标"}},["194368c4"]={q="工头希斯耐特为什么会在死亡矿井这里？",a="他最初深入死亡矿井，是代表矿工联盟和探险者协会监督一支远征队。灾难降临时，地下塌方将他的队员压在岩石之下，他们就此被困，再也无法离开，死后也不例外。",al={"希斯耐特为何在死亡矿井","希斯耐特如何来到这里","工头希斯耐特为何在这里"}}},fp="21,256,17.308.1,24.434.1,45.212.0,45.173.0,39.171.0,41.185.0"}
P.entries["npc:frahun-shadewhisper"] = {n="弗拉胡恩·影语者",s="弗拉胡恩·影语者在幽影谷的奥达希尔训练暗夜精灵潜行者。他教导初出茅庐的斥候和潜行者掌握潜行、敏捷身法与隐秘突袭。艾瑞安·影语是达纳苏斯的另一位潜行者训练师，与他有着相同的姓氏。",h="弗拉胡恩·影语者在幽影谷的奥达希尔训练暗夜精灵潜行者。他教导初出茅庐的斥候和潜行者掌握潜行、敏捷身法与隐秘突袭。艾瑞安·影语是达纳苏斯的另一位潜行者训练师，与他有着相同的姓氏。",kw={"奥达希尔","密文符记","埃里安","弗拉胡恩","潜行者训练师","影语者","幽影谷","泰达希尔"},ang={["class:Rogue"]="身为潜行者，弗拉胡恩·影语者会教你最初的潜行、伏击战术与武器运用技巧。",["race:NightElf"]="身为暗夜精灵，你会看到族人与生俱来的夜间活动天赋和隐匿本领，如何化为保护泰达希尔的实用战斗技巧。"},sec={{t="暗影中的导师",b="弗拉胡恩·影语者在泰达希尔的奥达希尔教导新晋潜行者掌握隐匿与刀刃技艺。暗夜精灵社会尊崇祭司、哨兵和德鲁伊，但斥候与渗透者也在守护世界之树的枝桠。新兵带着密文符记来见弗拉胡恩。他评估他们的潜力，引导他们迈出研习潜行者技艺的第一步。"}},faq={{q="弗拉胡恩·影语者是谁？",a="弗拉胡恩·影语者在泰达希尔的奥达希尔训练暗夜精灵潜行者。他教导新晋潜行者掌握潜行、精准战斗与隐秘战术。",al={"弗拉胡恩背景故事","弗拉胡恩是谁","弗拉胡恩·影语者的职责"}},{q="在哪里可以找到弗拉胡恩·影语者？",a="弗拉胡恩·影语者位于奥达希尔，那是泰达希尔上幽影谷的中心据点。",al={"弗拉胡恩位置","弗拉胡恩在哪里","寻找弗拉胡恩·影语者"}},{q="弗拉胡恩与艾瑞安·影语有亲属关系吗？",a="人们认为，弗拉胡恩·影语者与在达纳苏斯训练潜行者的艾瑞安·影语有亲属关系。两人姓氏相同，又都从事潜行者训练，这些都支持了这一看法。",al={"艾瑞安·影语兄弟","弗拉胡恩与艾瑞安·影语的亲属关系","影语者家族"}},{q="密文符记与他有什么关系？",a="新晋暗夜精灵潜行者将密文符记带给弗拉胡恩·影语者。这表明他们已经准备好正式学习潜行者的技艺。",al={"密文符记交付","弗拉胡恩符记","潜行者初始任务"}}},fp="19,201,23.329.0,27.132.0,39.93.0,40.163.0,49.137.0"}
P.entries["npc:furen-longbeard"] = {n="弗伦·长须",s="在暴风城的矮人区，战士们慕名而来，寻求弗伦·长须打造实战护甲的技艺。他师从格瑞曼德·艾尔默，以金属加工和打造重型护具的本领闻名。",h="在暴风城的矮人区，战士们慕名而来，寻求弗伦·长须打造实战护甲的技艺。他师从格瑞曼德·艾尔默，以金属加工和打造重型护具的本领闻名。",kw={"护甲匠","铁匠","矮人区","弗伦的铠甲","弗伦·长须","格瑞曼德·艾尔默","暴风城","战士"},ang={["class:Warrior"]="身为联盟战士，你可以找弗伦·长须，让他用收集来的材料和自己的锻造技艺，为你打造经过火焰淬炼的护甲。",["profession:Blacksmithing"]="身为铁匠，你可以在暴风城见识矮人锻造工艺的高超水准。格瑞曼德·艾尔默将自己的精湛技艺传授给了弗伦·长须。",["race:Dwarf"]="身为矮人，你可以看到弗伦·长须在人类都城的中心延续着矮人的金属加工传统。"},sec={{t="人类都城的矮人铁匠",b="弗伦·长须远离铁炉堡的宏伟熔炉，在暴风城的矮人区从事锻造。和许多矮人一样，他将古老的金属加工技艺带到南方，帮助重建和保卫这个王国。他的手艺让他与城内乃至更远地方的工匠建立了联系。"},{t="火焰淬炼锁甲的精湛技艺",b="格瑞曼德·艾尔默传授了弗伦·长须锻造技艺。弗伦不断精进处理重型锁甲和板甲的方法，使其能够承受战斗中的打击。年轻的战士向他寻求坚固耐用的护具。为了打造经过火焰淬炼的护甲，他需要来自世界偏远角落的稀有矿石、特殊部件和奇异材料。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是暴风城矮人区的一名矮人护甲匠。联盟战士向他寻求精工打造的锁甲和指点。",al={"弗伦是谁","弗伦·长须的故事","暴风城矮人护甲匠"}},{q="在哪里可以找到弗伦·长须？",a="你可以在暴风城的矮人区找到弗伦·长须，他就在熔炉和锻造作坊附近。",al={"弗伦·长须在哪里","弗伦·长须位置","弗伦暴风城"}},{q="谁传授了弗伦锻造技艺？",a="格瑞曼德·艾尔默传授了弗伦·长须护甲制作和冶金技艺。这位备受尊敬的资深工匠也住在矮人区。",al={"弗伦的老师","弗伦的导师","谁教导了弗伦"}},{q="弗伦以打造什么护甲闻名？",a="弗伦·长须以打造弗伦的铠甲闻名。他运用精细的金属加工技艺，配合从大陆各地收集的稀有部件，制成这种坚固的护甲。",al={"弗伦的铠甲","弗伦护甲任务","暴风城战士锁甲任务"}},{q="弗伦·长须与其他长须家族成员有亲缘关系吗？",a="弗伦·长须与东部王国各地其他知名矮人有着相同的氏族名，其中包括铁炉堡攻城坦克驾驶员飞行员比罗·长须。弗伦的专长则是锻造。",al={"弗伦的家族","长须氏族","飞行员比罗·长须的亲属"}},{q="战士们为什么要寻找弗伦·长须？",a="证明了自己具备基本战斗本领的战士，会被指引去找弗伦·长须，寻求厚重而耐用的护甲。这些护甲能够经受住前线战斗的考验，抵御更致命的威胁。",al={"战士为什么找弗伦","战士任务矮人区","弗伦战士训练师"}}},fx={["269e0799"]={q="弗伦·长须站在哪一边？",a="弗伦·长须是联盟的忠诚成员，在暴风城繁忙的矮人区从事锻造。他与铁炉堡同胞、其他铁匠及雷矛氏族密切合作，以自己的手艺为联盟守卫者打造装备。",al={"弗伦·长须的阵营","弗伦·长须与联盟","弗伦·长须为谁效力"}},d8add91c={q="弗伦·长须想要什么？",a="弗伦寻求稀有材料与能干的盟友，以打造出色的护甲，尤其为那些寻求烈火淬炼锁甲等坚固装备的有为战士效力。他也致力于完成重要的军需订单，其中包括为雷矛卫队专门打造装备的订单。",al={"弗伦想要什么","弗伦·长须的动机","弗伦·长须的目标"}},["316ead5d"]={q="弗伦·长须为什么在暴风城？",a="弗伦在暴风城的矮人区工作，是连接矮人锻造技艺与人类都城军备需求的重要纽带。在城中大熔炉附近，他可以与学徒、锻造大师及侏儒工程师合作，同时为前线守卫者提供重甲。",al={"弗伦·长须为何在这里","弗伦为何在暴风城","弗伦·长须所在地的背景"}}},fp="15,194,36.264.0,29.324.0,23.149.0,35.108.0,36.140.0,40.165.0,47.183.0,41.168.0"}
P.entries["npc:furl-scornbrow"] = {n="弗恩·凝眉",s="在剃刀岭西北方的一座哨塔上，弗恩·凝眉守望着杜隆塔尔。他年事已高，无法再上前线，便为年轻的旅人制作结实的背包。",h="在剃刀岭西北方的一座哨塔上，弗恩·凝眉守望着杜隆塔尔。他年事已高，无法再上前线，便为年轻的旅人制作结实的背包。",kw={"生活所需","杜隆塔尔","弗恩·凝眉","瞭望哨","兽人","剃刀岭","哨塔"},ang={["faction:Horde"]="弗恩在剃刀岭外的山脊上值守，体现了杜隆塔尔新建的定居点抵御残存威胁所需的警惕。",["race:Orc"]="弗恩体现了兽人的信念：年老并不意味着战士的效力之路就此终结。尽管他已失去战斗的力量，却仍光荣地为部落效力。"},sec={{t="山脊上的守望者",b="弗恩·凝眉在剃刀岭西北方的一座木制哨塔上，守望着中部平原。奥格瑞玛建立之初，局势紧张，像弗恩这样的哨兵会吹响号角，警示来犯的野猪人、半人马和库尔提拉斯入侵者。此后，杜隆塔尔逐渐安定，剃刀岭也巩固了边界。紧急情况日渐减少，弗恩便在岗位上度过了漫长而宁静的时光。"},{t="仍有用武之地的双手",b="弗恩说，自己筋骨衰老，力量衰退，已无力战斗。但兽人不会轻易放弃自己的使命。他用双手缝制帆布袋和背包，供新兵携带补给。初出茅庐的冒险者只需拿来粗线和实用的材料，他便会为他们备好行装，让他们踏上向部落证明自身价值的旅途。"}},faq={{q="弗恩·凝眉是谁？",a="弗恩·凝眉在剃刀岭西北方峭壁上的一座瞭望塔中值守。他年事已高，无法再上前线，便留意着危险的动向，为年轻的旅人制作背包。",al={"弗恩是谁","弗恩·凝眉的故事","剃刀岭的弗恩"}},{q="弗恩在杜隆塔尔担负什么职责？",a="弗恩驻守在设有警戒号角的哨塔上，监视着逼近剃刀岭的入侵者。随着部落治下的杜隆塔尔愈发安定，他吹响警报的次数也少了，便利用平静的时光帮助新兵整理装备。",al={"弗恩做什么","弗恩的使命"}},{q="弗恩为什么向旅人索要材料？",a="弗恩向旅人索要材料，是因为他相信部落的每一员都必须尽自己的一份力。他已无力战斗，便为初出茅庐的战士缝制实用的旅行背包，只索取粗线之类的基本材料。",al={"新的背包任务故事","弗恩为什么要粗线"}}},fp="14,137,21.398.0,22.344.0,22.175.0,31.218.0,42.223.0"}
P.entries["npc:gaerolas-talvethren"] = {n="盖洛拉斯·塔文斯伦",s="在饱受动荡的泰达希尔，盖洛拉斯·塔文斯伦在星风村守护着沉睡的德鲁伊。他寻求援助，以对抗凶暴的熊怪和在枝干间蔓延的腐化。",h="在饱受动荡的泰达希尔，盖洛拉斯·塔文斯伦在星风村守护着沉睡的德鲁伊。他寻求援助，以对抗凶暴的熊怪和在枝干间蔓延的腐化。",kw={"不安的风","盖洛拉斯·塔文斯伦","瘤背的腐化","星风村","泰达希尔","沉睡"},ang={["class:Druid"]="身为德鲁伊，盖洛拉斯守护沉睡德鲁伊的职责让帮助他成为与你切身相关的事：你保护的是同属塞纳里奥议会的修行者。",["race:NightElf"]="作为一名离开多兰纳尔的年轻暗夜精灵，帮助盖洛拉斯会让你看到，污秽已在泰达希尔神圣的枝干间蔓延得多么深。"},sec={{t="沉睡者的守护者",b="盖洛拉斯·塔文斯伦在星风村守护着沉睡的德鲁伊。他们在沉睡中与翡翠梦境交融，而异样的腐化正在森林中蔓延，扰乱泰达希尔，也让他的守望愈发不安。"},{t="瘤背的威胁",b="盖洛拉斯呼吁旅者击退瘤背熊怪，它们的心智已陷入疯狂与野蛮。他希望查明从它们的萨满祭司身上蔓延的污秽，以及它们陷入狂乱的根源，保住泰达希尔东部仅存的神圣。"}},faq={{q="盖洛拉斯·塔文斯伦是谁？",a="盖洛拉斯·塔文斯伦是星风村的一名暗夜精灵守卫，负责守护沉睡的德鲁伊，并调查侵扰当地的诡异腐化。",al={"盖洛拉斯","盖洛拉斯是谁","盖洛拉斯的职责"}},{q="在哪里可以找到盖洛拉斯·塔文斯伦？",a="你可以在泰达希尔东部、多兰纳尔以东的星风村找到盖洛拉斯·塔文斯伦。",al={"盖洛拉斯的位置","盖洛拉斯·塔文斯伦在哪里","寻找盖洛拉斯"}},{q="盖洛拉斯保护的“沉睡者”是谁？",a="沉睡者是暗夜精灵德鲁伊，他们在兽穴和圣所中进入漫长的沉睡，以游历翡翠梦境，而他们的肉身则容易受到伤害。",al={"沉睡者","沉睡者是谁","沉睡的德鲁伊"}},{q="盖洛拉斯担忧哪些威胁？",a="侵蚀当地野生生物的腐化，以及瘤背熊怪突如其来的疯狂敌意，都让盖洛拉斯深感不安。",al={"星风的威胁","盖洛拉斯的任务","瘤背的麻烦"}}},fp="19,163,24.234.0,20.263.0,27.129.0,37.96.0,46.165.0,41.116.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="黑暗缚灵者加科因",s="在暴风城的已宰的羔羊地下，黑暗缚灵者加科因考验着寻求术士之道的人。他教导有志成为术士的联盟成员召唤并束缚恶魔。",h="在暴风城的已宰的羔羊地下，黑暗缚灵者加科因考验着寻求术士之道的人。他教导有志成为术士的联盟成员召唤并束缚恶魔。",kw={"黑暗缚灵者","加科因","法师区","已宰的羔羊","魅魔","苏伦娜·凯尔东","虚空行者","术士"},ang={["class:Warlock"]="作为人类或侏儒术士，你可以在暴风城的墓穴中向加科因学习召唤并束缚虚空行者和魅魔。",["faction:Alliance"]="加科因藏身于首都地下的秘密团体，揭示了联盟核心地带所作出的妥协。"},sec={{t="秘密集会之所",b="已宰的羔羊酒馆大厅下方的地窖，是研习暗影与邪能之人的聚集之所。墓穴般的房间里布满了召唤法阵和阴森的典籍，避开了那些监视暴风城公开法师圣所的目光。在那里，加科因教导年轻术士严守纪律、懂得克制，然后才让他们召唤那些自己或许无法控制的力量。"},{t="恶魔之师",b="加科因传授恶魔学识与束缚恶魔的仪式。获得他关注的人会奔走于王国各地，寻找稀有之物，其中包括被盗的血石护符和黑暗森林中的腐化木材。材料集齐后，加科因便在墓穴的召唤法阵旁监督他们施法。在那里，学徒们要面对虚空行者和魅魔，在考验意志的试炼中冒着生命危险。"},{t="背叛与后患",b="苏伦娜·凯尔东曾是加科因的学徒，她带着一条珍贵的血石颈环逃入了荒野。她的背叛可能让这个术士团体暴露在暴风城卫兵面前。因此，加科因派遣忠诚的追随者找回遗失的器物，并在当局察觉之前灭口，以绝后患。"}},faq={{q="在哪里可以找到黑暗缚灵者加科因？",a="加科因就在暴风城法师区的已宰的羔羊地下。进入酒馆，沿后方的斜坡向下走。顺着石砌通道前行，就能到达最底层墓穴中的召唤法阵。",al={"加科因在哪里","加科因位置","已宰的羔羊地下室"}},{q="黑暗缚灵者加科因做些什么？",a="加科因指导联盟术士，并通过遍布艾泽拉斯的试炼考验学徒。他教他们召唤并束缚虚空行者和魅魔等恶魔。",al={"加科因做什么","加科因职责","加科因任务"}},{q="为什么术士能在已宰的羔羊地下活动？",a="暴风城禁止恶魔魔法，并对其深怀戒心。在已宰的羔羊地下，术士们避开卫兵和市民的耳目，秘密行事。暴风城容忍他们的存在，将他们视为一股危险的秘密力量。",al={"为什么容许术士活动","术士在暴风城是否合法","已宰的羔羊背景故事"}},{q="苏伦娜·凯尔东是谁？",a="苏伦娜·凯尔东曾是加科因的学生，她从他那里偷走了一条力量强大的血石颈环。她的背叛威胁着这个隐秘团体，因此加科因派遣术士追查她的下落。",al={"苏伦娜·凯尔东","加科因的学生","谁偷了加科因的东西"}},{q="加科因帮助召唤哪些恶魔？",a="加科因监督束缚虚空行者和魅魔的仪式。他指导术士将恶魔召唤到地下的法阵中，并将其制服。",al={"加科因恶魔","加科因虚空行者","加科因魅魔"}},{q="斯坦哈德是谁，加科因为什么会提到他？",a="斯坦哈德·法尔杉是一位经验丰富的术士，居住在卡利姆多棘齿城一带的山丘中。学生掌握加科因传授的基础束缚仪式后，加科因便会派他们远渡重洋，跟随斯坦哈德继续研习黑暗之道。",al={"斯坦哈德","寻找斯坦哈德","加科因接下来派往何处"}}},fx={["5c1d997e"]={q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一名强大的人类术士，藏身于暴风城法师区的已宰的羔羊下方的墓穴深处。他远离城市卫兵和肯瑞托的窥探，指引初学邪能法术的人，传授迫使异界恶魔服从自身意志所需的危险仪式。",al={"加科因是谁","加科因 身份","加科因 背景故事"}},a5302178={q="黑暗缚灵者加科因效忠哪一方？",a="加科因大体上为联盟效力，训练人类和侏儒施法者将恶魔力量化为武器，以求生存。然而，与大多数黑暗法术大师一样，他真正的忠诚仍深藏不露，隐于阴影与秘密之中，在暴风城统治者的审视之外追寻禁忌知识。",al={"加科因是联盟的吗","加科因 效忠对象","加科因为谁效力"}},["503bf85b"]={q="黑暗缚灵者加科因想要什么？",a="加科因希望进一步掌握邪能魔法，并确保有志成为术士的人具备束缚更强大恶魔的决心，而不会反被恶魔吞噬。他也在暗中设法追回被盗的强大法器，例如他那误入歧途的昔日学徒偷走的血石颈环。",al={"加科因想要什么","加科因 目标","加科因 动机"}}},fp="20,167,24.317.0,16.384.0,24.279.1,38.196.0,34.156.0,52.199.0,22.179.0,36.143.0,46.204.0"}
P.entries["npc:galgar"] = {n="戈加尔",s="在试炼谷的大兽穴附近，戈加尔为效力于部落的年轻新兵提供食物。他请初来乍到的人采集野生仙人掌果，用来制作他的清凉果。",h="在试炼谷的大兽穴附近，戈加尔为效力于部落的年轻新兵提供食物。他请初来乍到的人采集野生仙人掌果，用来制作他的清凉果。",kw={"清凉果","仙人掌果","厨师","杜隆塔尔","戈加尔","部落新兵","试炼谷"},ang={["profession:Cooking"]="戈加尔沿用部落务实质朴的烹饪方式，利用杜隆塔尔稀少的自然资源养活新兵，让他们随时准备投入战斗。",["race:Orc"]="身为试炼谷中的年轻兽人，你在面对更凶险的荒野威胁之前，会先替戈加尔跑一趟腿，完成这项熟悉的成人试炼。"},sec={{t="谷中的厨师",b="戈加尔在试炼谷大兽穴附近的火堆旁烹饪，为正在经历最初成人试炼的年轻兽人和巨魔提供食物。杜隆塔尔是一片干旱严酷的红色荒原，食物必须从这片土地上四处搜寻。戈加尔派新手战士去采集成熟的仙人掌果，既考验他们的细心与毅力，也为自己的厨房补充食材。"},{t="清凉果",b="戈加尔的拿手菜叫作清凉果。他说，采集带刺的沙漠果实是一项简单的任务，能让新兵逐渐适应冒险生活。这道菜依然为饥肠辘辘的受训者充饥。每个部落战士都有自己的起点，而戈加尔让他们从沙漠采食开始。"}},faq={{q="在哪里可以找到戈加尔？",a="戈加尔就在试炼谷的大兽穴外，靠近中央篝火和烹饪区的地方。这座峡谷位于杜隆塔尔西南部，是兽人和巨魔的起始之地。",al={"戈加尔位置","戈加尔在哪","戈加尔坐标"}},{q="戈加尔请冒险者做什么？",a="戈加尔请新来的冒险者从散布在试炼谷各处的野生仙人掌上采集成熟的仙人掌果，好让他制作清凉果。",al={"戈加尔任务","戈加尔要什么"}},{q="戈加尔为什么派新兵去采果子？",a="戈加尔说，这项任务很简单，能让初出茅庐的战士从一件小差事开始，熟悉山谷，并练习在杜隆塔尔严酷的荒野中自给自足。",al={"为什么要仙人掌果","戈加尔的考验"}},{q="清凉果是什么？",a="清凉果是戈加尔的招牌菜，用从杜隆塔尔本土沙漠植物上采来的新鲜仙人掌果制成，为新兵充饥。",al={"清凉果是什么","戈加尔的食物"}}},fp="6,150,20.327.0,21.269.0,24.170.0,39.162.0,48.155.0,30.158.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="甘鲁尔·血眼",s="在奥格瑞玛，甘鲁尔·血眼在城下训练术士。在暗影裂口，部落的新晋术士学习更黑暗的恶魔仪式，以及如何让虚空行者和魅魔服从自己的意志。",h="在奥格瑞玛，甘鲁尔·血眼在城下训练术士。在暗影裂口，部落的新晋术士学习更黑暗的恶魔仪式，以及如何让虚空行者和魅魔服从自己的意志。",kw={"血眼","暗影裂口","甘鲁尔","奥格瑞玛","魅魔","训练师","虚空行者","术士"},ang={["class:Warlock"]="作为一名寻求禁忌知识的术士，你可以在卡利姆多向甘鲁尔学习，并接受束缚虚空行者和魅魔所需的试炼。",["faction:Horde"]="作为部落的一员，你会看到邪能魔法如何被用于增强军事实力，而它的研习者依然被限制在主城地下的隐蔽角落。"},sec={{t="暗影中的大师",b="术士们在奥格瑞玛地下的暗影裂口中隐秘地研习。大酋长萨尔容许他们留在新部落中，但杜隆塔尔明亮的阳光下并不适合施展他们的黑暗法术。这片洞穴为暗影编织者、潜行者和邪能施法者提供了不受打扰的研习之所。甘鲁尔就在这里教导崭露头角的邪能研习者。"},{t="束缚虚空",b="野心勃勃的术士来到甘鲁尔这里，学习危险的召唤仪式。想要束缚更强大的恶魔，例如坚韧的虚空行者或妖娆的魅魔，就必须备齐仪式材料，并掌握准确的咒语。召唤者必须在被召唤的生物吞噬之前将其控制。"}},faq={{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼在奥格瑞玛训练兽人术士。他指导部落的初学和进阶术士，教他们召唤并束缚来自扭曲虚空的恶魔。",al={"甘鲁尔·血眼","甘鲁尔是谁","甘鲁尔·血眼的职责"}},{q="在哪里可以找到甘鲁尔·血眼？",a="甘鲁尔位于暗影裂口，那是奥格瑞玛地下的一片洞穴群。他与其他黑暗法术研习者待在一起，远离城中的主要街道。",al={"甘鲁尔的位置","甘鲁尔·血眼在哪里","暗影裂口的训练师在哪里"}},{q="为什么术士藏在暗影裂口？",a="术士在暗影裂口研习，是因为兽人曾遭奴役，大酋长萨尔和新部落信奉萨满之道的社会因此不信任邪能魔法与恶魔腐化。部落因术士的用处而容许他们存在，但将他们的法术活动限制在暗处，以免引发民众骚乱。",al={"为什么在洞穴里","为什么隐藏术士","暗影裂口的背景故事"}},{q="甘鲁尔帮助召唤哪些恶魔？",a="甘鲁尔指导术士举行仪式，召唤并降服虚空行者和魅魔。完成他的任务，就证明召唤者拥有控制这些恶魔的意志。",al={"甘鲁尔教授的恶魔","甘鲁尔的恶魔任务","虚空行者魅魔训练师"}},{q="甘鲁尔有已知的亲属吗？",a="甘鲁尔与哈尔加·血眼拥有相同的姓氏，但没有公开记载说明他们的确切关系。",al={"甘鲁尔的亲属","哈尔加·血眼的亲属"}},{q="甘鲁尔提到的斯坦哈德是谁？",a="斯坦哈德·法尔杉是一位造诣深厚的术士，住在贫瘠之地靠近棘齿城的丘陵一带。甘鲁尔将有潜力的学生送到他那里，接受更高深的指导和更严峻的挑战。",al={"寻找斯坦哈德","斯坦哈德是谁","斯坦哈德的任务"}}},fp="16,190,23.329.0,18.298.0,24.158.0,34.152.0,47.291.0,37.155.0,35.102.0,38.181.0"}
P.entries["npc:gann-stonespire"] = {n="加恩·石塔",s="在巴尔莫丹附近的南贫瘠之地道路旁，加恩·石塔正为族人被逐出家园一事寻求报复。这位牛头人游牧者的部族曾在这片土地上狩猎，如今这里却成了矮人的挖掘场。",h="在巴尔莫丹附近的南贫瘠之地道路旁，加恩·石塔正为族人被逐出家园一事寻求报复。这位牛头人游牧者的部族曾在这片土地上狩猎，如今这里却成了矮人的挖掘场。",kw={"巴尔莫丹","巴尔丹","加恩·石塔","勘察员卡兹戈姆","南贫瘠之地","石塔"},ang={["faction:Horde"]="身为部落的一员，你可以帮助加恩遏制联盟在南贫瘠之地根深蒂固的扩张势头。",["race:Tauren"]="身为牛头人，你与那些游牧者有着共同的遭遇，他们祖传的牧场和神圣的土地一再遭到外来的联盟远征队亵渎。"},sec={{t="被逐出巴尔莫丹",b="矮人远征队从铁炉堡来到这里，建起巴尔莫丹后，加恩·石塔便在南贫瘠之地的道路旁扎营。周围的土地曾是他部族世代相传的领地和猎场。矮人矿工用镐头、火枪和重型机械将牛头人赶出了家园，还拒绝了和平交涉。加恩不愿默默放弃祖先留下的一切。他号召过往的旅人反击这些挖掘者。"},{t="夺回故土与破坏行动",b="和平交涉失败后，加恩指引部落成员打破矮人对挖掘场的控制。他的报复目标是远征队的首领，其中包括勘察员卡兹戈姆。随后，他让人用矮人的爆破火药和军械制成炸药包。加恩打算在矮人的飞行器下方引爆炸药，削弱他们的技术优势，为流离失所的族人夺回荣誉。"}},faq={{q="加恩·石塔是谁？",a="加恩·石塔是一名牛头人战士，他的部族曾生活在如今被巴尔莫丹占据的土地上。矮人建立挖掘场时将他们赶走，如今加恩在南贫瘠之地的路旁等候，寻求复仇，并夺回族人的家园。",al={"加恩是谁","加恩·石塔的故事","巴尔莫丹外的牛头人"}},{q="加恩为何与巴尔莫丹的矮人作战？",a="巴尔丹矮人远征队来到南贫瘠之地，将当地的牛头人逐出祖传的猎场，以便修建一座挖掘堡垒。矮人拒绝外交交涉后，加恩选择用武力摧毁他们的挖掘行动。",al={"加恩为何憎恨矮人","为何进攻巴尔莫丹","加恩与巴尔莫丹的冲突"}},{q="加恩打算如何对付挖掘场？",a="加恩委托他人杀死包括勘察员卡兹戈姆在内的矮人监工，夺取挖掘记录。随后，他让人将偷来的矮人军械和爆破物资制成炸弹，准备炸毁远征队的飞行器，破坏他们的技术优势。",al={"加恩的复仇计划","加恩做什么","巴尔莫丹炸弹"}},{q="加恩·石塔在哪里扎营？",a="加恩·石塔在南贫瘠之地巴尔莫丹西侧不远处的道路上徘徊，那里位于挖掘场外围。",al={"加恩在哪里","加恩·石塔的位置"}}},fp="15,183,25.399.0,24.405.1,23.283.0,47.250.0,43.229.1,41.129.0"}
P.entries["npc:gar-thok"] = {n="加索克",s="在剃刀岭，加索克指挥离开试炼谷的新兵保卫杜隆塔尔。这位身经百战的兽人战士在库尔提拉斯军队登陆杜隆塔尔海岸时幸存下来，如今统筹防务，抵御人类入侵者和本土威胁。",h="在剃刀岭，加索克指挥离开试炼谷的新兵保卫杜隆塔尔。这位身经百战的兽人战士在库尔提拉斯军队登陆杜隆塔尔海岸时幸存下来，如今统筹防务，抵御人类入侵者和本土威胁。",kw={"戴林","杜隆塔尔","加索克","库尔提拉斯","剃刀岭","雷克萨","提拉加德"},ang={["class:Warrior"]="作为一名从残酷的海军突袭中幸存的前线指挥官，加索克要求其他战士拥有坚韧的战斗意志，并毫不犹豫地服从命令。",["faction:Horde"]="面对部落各族的新兵，加索克明确指出这片新领土的处境有多么危险，并指挥他们击退入侵的联盟残部。",["race:Orc"]="对于离开试炼谷的年轻兽人来说，加索克代表着老一辈严明而不容动摇的军纪，正是这些老兵流血奋战，才赢得了杜隆塔尔。"},sec={{t="赤色荒地的老兵",b="第三次战争后，加索克随大酋长萨尔进军杜隆塔尔，在建设新家园的最初岁月里，担任纳兹格雷尔的副官。半食人魔流浪者雷克萨来到杜隆塔尔时，加索克警告他，野猪人正在袭击定居点的外围。他请这位兽王出手，保护尚未站稳脚跟的新定居点。"},{t="从海军上将的入侵中幸存",b="海军上将戴林·普罗德摩尔率领库尔提拉斯舰队登陆杜隆塔尔东海岸时，加索克的意志经受了考验。在一处偏远哨所，加索克亲眼看着海军陆战队攻破防线，屠杀了他麾下的驻军。他的部队伤亡惨重，但他活了下来。这场突袭让他始终警惕着残存的海军陆战队，他们至今仍盘踞在提拉加德城堡和沿海的沉船中。"},{t="剃刀岭的防务",b="加索克在剃刀岭的兵营中统筹杜隆塔尔中部的防务。他迅速派遣初出茅庐的部落战士、萨满祭司和斥候，驱逐敌对的库尔提拉斯人残部，夺回打捞上来的物资，并找回遗留在沿海废墟中的军事命令。杜隆塔尔的安全远未得到保障，加索克持续向那些挑战部落对这片土地所有权的敌人施压。"}},faq={{q="加索克是谁？",a="加索克是驻扎在剃刀岭的兽人军官，负责组织杜隆塔尔的军事行动，抵御敌对势力。他是一名参加过第三次战争的老兵，在奥格瑞玛建立期间曾效力于纳兹格雷尔麾下。",al={"加索克背景故事","加索克是谁","剃刀岭指挥官"}},{q="来到剃刀岭之前，加索克曾在哪里作战？",a="加索克曾在杜隆塔尔的一处边境哨所担任纳兹格雷尔的副官，在那里与雷克萨合作，平息了早期的野猪人袭击。库尔提拉斯人水兵攻陷了哨所，杀死了他的部下。",al={"加索克的过去","加索克 海加尔山","加索克的历史"}},{q="加索克为何如此憎恨杜隆塔尔的人类？",a="海军上将戴林·普罗德摩尔入侵期间，库尔提拉斯水兵突袭了加索克的沿海哨所，屠杀了他的部下。加索克幸存下来，至今仍致力于铲除剩余的海军陆战队营地。",al={"加索克为何憎恨库尔提拉斯","加索克 人类","提拉加德城堡 加索克"}},{q="加索克派冒险者对抗哪些威胁？",a="加索克派新兵对付提拉加德城堡中敌对的库尔提拉斯人水兵，从沿海沉船中夺回物资，击退入侵的野猪人，并搜寻人类指挥官留下的命令。",al={"加索克任务","加索克想要什么","剃刀岭任务"}},{q="他与纳兹格雷尔和萨尔是什么关系？",a="在杜隆塔尔最初的殖民远征期间，加索克是纳兹格雷尔信任的副官，直接听命于大酋长萨尔，协助守卫新占领土的边界。",al={"加索克 纳兹格雷尔","加索克 萨尔","加索克军衔"}},{q="在哪里能找到加索克？",a="加索克就在剃刀岭的主哨塔和兵营外。剃刀岭是杜隆塔尔中部的定居点，位于奥格瑞玛以南。",al={"加索克位置","加索克在哪里","寻找加索克"}}},fp="8,248,27.360.0,32.371.0,21.372.0,16.188.0,53.207.0,53.216.0,53.195.0,49.195.0,28.136.0"}
P.entries["npc:gart-mistrunner"] = {n="加尔特·迷雾行者",s="在纳拉其营地，加尔特·迷雾行者指引着受到大地母亲召唤的牛头人新手。他在红云台地传授最初的自然魔法仪式。",h="在纳拉其营地，加尔特·迷雾行者指引着受到大地母亲召唤的牛头人新手。他在红云台地传授最初的自然魔法仪式。",kw={"纳拉其营地","德鲁伊训练师","加尔特·迷雾行者","迷雾","莫高雷","红云台地","牛头人德鲁伊"},ang={["class:Druid"]="身为牛头人德鲁伊，加尔特·迷雾行者是第一位引导你与荒野沟通、运用Earth Mother恩赐的导师。",["race:Tauren"]="身为牛头人，你见证加尔特·迷雾行者将Shu'halo古老的德鲁伊传统传授给纳拉其营地的年轻人。"},sec={{t="红云台地的导师",b="当舒哈鲁重拾古老的德鲁伊之道时，加尔特·迷雾行者守望着纳拉其营地。牛头人德鲁伊新手在红云台地迈出第一步时，便会被派到他身边，往往还带着一封推荐信，请他予以照料。加尔特教导他们与自然世界沟通。他们借助自然的恢复之力与艾露恩的月光，治疗盟友，击败威胁这片土地的敌人。"}},faq={{q="加尔特·迷雾行者是谁？",a="加尔特·迷雾行者在莫高雷红云台地的纳拉其营地训练德鲁伊。他向牛头人新手传授最初的法术与仪式。",al={"加尔特是谁","加尔特·迷雾行者的背景故事","加尔特·迷雾行者"}},{q="他向刚刚觉醒的德鲁伊传授哪些法术？",a="加尔特向初学者传授基本的自然能力，包括治疗法术治疗之触和攻击性的自然魔法月火。",al={"加尔特教什么","加尔特·迷雾行者的训练","纳拉其营地德鲁伊法术"}},{q="他与迷雾氏族有什么关系？",a="迷雾是加尔特的姓氏。没有任何背景故事描述过一个名为迷雾的部族，也没有进一步提及他的亲族；他以纳拉其营地的德鲁伊训练师这一身份为人所知。",al={"迷雾氏族","迷雾家族是谁"}}},fp="15,108,28.421.0,23.134.0,48.98.0,46.147.0"}
P.entries["npc:gath-ilzogg"] = {n="加塞尔佐格",s="赤脊山的石堡要塞仍在加塞尔佐格的掌控之下。这位黑石军阀的部队占据着要塞，不断袭击湖畔镇，所罗门镇长已悬赏捉拿他。",h="赤脊山的石堡要塞仍在加塞尔佐格的掌控之下。这位黑石军阀的部队占据着要塞，不断袭击湖畔镇，所罗门镇长已悬赏捉拿他。",kw={"黑石","加塞尔佐格","湖畔镇","辛格","所罗门镇长","石堡","石堡要塞"},ang={["faction:Alliance"]="对联盟而言，击败加塞尔佐格就能重创黑石威胁湖畔镇的攻势，回应所罗门镇长绝望的呼救。",["race:Orc"]="身为兽人，加塞尔佐格展现了Dark Horde麾下黑石氏族古老而好战的作风，与萨尔在卡利姆多建立的新部落毫无关系。"},sec={{t="石堡之祸",b="加塞尔佐格从燃烧平原北上，要为黑石氏族夺取赤脊山。在叛变的人类术士莫甘斯的邪恶法术协助下，他的战团重创石堡要塞的守军，夺取了俯瞰这片地区的高地。加塞尔佐格从要塞中指挥部队穿过山谷，向湖畔镇的桥梁发动袭击，不断加大对这座人类城镇的压力。黑石精锐卫兵和一只名叫辛格的凶恶黑龙雏龙始终守在他身旁。"},{t="脆弱的统治",b="加塞尔佐格对石堡的占领带来了新的危险。莫甘斯背叛了昔日的兽人盟友，集结了一支由范高雷中尉率领的暗皮豺狼人部队。黑石巡逻队和人类旅人都成了他们的猎物。所罗门镇长已公开悬赏捉拿加塞尔佐格，号召联盟佣兵或冒险者登上石堡要塞的城墙，在湖畔镇彻底沦陷之前终结他的恐怖统治。"}},faq={{q="加塞尔佐格是谁？",a="加塞尔佐格率领黑石先锋部队入侵赤脊山，从联盟手中夺取了石堡要塞。",al={"加塞尔佐格背景故事","加塞尔佐格是谁","赤脊山黑石首领"}},{q="在哪里能找到加塞尔佐格？",a="加塞尔佐格盘踞在石堡要塞的顶层，要塞位于赤脊山东部的峭壁之间。",al={"加塞尔佐格位置","加塞尔佐格在哪","寻找加塞尔佐格"}},{q="加塞尔佐格为什么有一只雏龙？",a="加塞尔佐格身边养着一只名叫辛格的黑龙雏龙。许多人相信，维克多·奈法里奥斯将辛格赐给了他，作为夺取石堡要塞的奖赏。",al={"加塞尔佐格旁边为什么有雏龙","辛格龙","黑龙雏龙加塞尔佐格"}},{q="为什么有人悬赏捉拿他？",a="加塞尔佐格的袭击和对石堡的占领让湖畔镇面临彻底毁灭的威胁，因此湖畔镇的所罗门镇长将捉拿他列为悬赏要务。",al={"悬赏加塞尔佐格","谁想要加塞尔佐格死","所罗门镇长悬赏"}},{q="加塞尔佐格和莫甘斯之间发生了什么？",a="人类术士莫甘斯起初用黑暗魔法帮助加塞尔佐格征服石堡。要塞陷落后，莫甘斯背叛了兽人，集结暗皮豺狼人，同时攻击人类和黑石氏族。",al={"莫甘斯加塞尔佐格同盟","豺狼人为什么攻击兽人","莫甘斯背叛"}}},fp="11,159,25.446.0,14.422.1,19.106.0,31.93.0,41.140.0,34.168.0,47.221.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="加克希姆·尘链",s="在蛛网小径的一处联盟小营地里，加克希姆·尘链正努力争取石爪山脉暗夜精灵的支持。这位雄心勃勃的侏儒学者兼工匠代表着奥术、炼金术和工程学启蒙协会，力图证明工程技艺与炼金术能够保护他们的林地家园。他也对荆棘谷地精的破坏行径怀有强烈的仇恨。",h="在蛛网小径的一处联盟小营地里，加克希姆·尘链正努力争取石爪山脉暗夜精灵的支持。这位雄心勃勃的侏儒学者兼工匠代表着奥术、炼金术和工程学启蒙协会，力图证明工程技艺与炼金术能够保护他们的林地家园。他也对荆棘谷地精的破坏行径怀有...",kw={"集会","加克希姆","侏儒","凯拉","尘链","石爪山脉","荆棘谷地精","蛛网小径","狂风峭壁"},ang={["faction:Alliance"]="在危机四伏的蛛网小径，加克希姆提供侦察、情报收集和破坏任务，遏制工业势力对石爪山脉的肆意侵占。",["profession:Engineering"]="加克希姆将工程学运用于实地，策划秘密行动并设计战术装置，专门用来破坏荆棘谷地精的粗陋机械。",["race:Gnome"]="加克希姆将侏儒学界的自豪带到了卡利姆多，向这里的古老文明证明，齿轮和试剂也能像自然魔法一样拯救森林。",["race:NightElf"]="加克希姆是一位坚定的盟友，积极保卫灰谷和石爪山脉的边境，抵御地精工业的侵袭。"},sec={{t="科学使者",b="在石爪山脉崎岖的山道间，加克希姆·尘链为暗夜精灵带来了另一种守护荒野的方法。他代表奥术、炼金术和工程学启蒙协会，相信精密设计的机械与化学制剂能像向艾露恩祈祷一样，守护并修复卡利姆多的荒野。他与哨兵凯拉·影矛一同驻扎在蛛网小径，努力说服这些身材高大、离群索居的盟友，让他们相信工程学也能为生机盎然的森林效力。"},{t="破坏伐木机械",b="荆棘谷地精的滥砍滥伐与工业贪欲让附近的狂风峭壁满目疮痍，加克希姆为此投入了大量精力。他认为那些粗陋的地精机械既不值得尊重，也不值得手下留情，于是组织秘密行动，用不稳定的化学制剂破坏他们的伐木作业。他组织行动，瘫痪伐木机并窃取其设计图，意在证明侏儒的智慧能够击败肆无忌惮的商业掠夺。"}},faq={{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位侏儒学者兼发明家，驻扎在石爪山脉蛛网小径的一处联盟哨所。他代表奥术、炼金术和工程学启蒙协会。",al={"加克希姆是谁","加克希姆·尘链背景故事","石爪山脉的侏儒"}},{q="奥术、炼金术和工程学启蒙协会是什么？",a="奥术、炼金术和工程学启蒙协会是一个融合奥术魔法、炼金合剂与机械工程的侏儒学术团体。加克希姆远赴卡利姆多，宣扬其理念。",al={"启蒙协会","加克希姆阵营","加克希姆所属团体"}},{q="加克希姆为何与暗夜精灵合作？",a="加克希姆想向暗夜精灵证明，侏儒的科学与炼金术能够保护并修复林地。在传统德鲁伊之道以外，他为森林保护提供了联盟的现代方案。",al={"加克希姆为何在此","加克希姆暗夜精灵","加克希姆的目的"}},{q="加克希姆为何憎恨荆棘谷地精？",a="加克希姆憎恨荆棘谷地精，因为他们用粗陋的机械无情地砍光狂风峭壁的林木，还造成了有毒污染。他鄙视他们肆无忌惮的掠夺，用不稳定的化学制剂和破坏行动对付他们的作业。",al={"加克希姆荆棘谷地精","加克希姆对抗荆棘谷地精","为何对抗荆棘谷地精"}},{q="谁与加克希姆一同驻扎在蛛网小径？",a="加克希姆与凯拉·影矛共同驻守蛛网小径的小哨站，她是一名暗夜精灵哨兵，负责监视通往狂风峭壁的小径。",al={"加克希姆的同伴","谁与加克希姆在一起","加克希姆与凯拉"}},{q="在哪里能找到加克希姆·尘链？",a="加克希姆位于石爪山脉蛛网小径的一处简陋联盟营地，就在狂风峭壁工业伐木场的西南方。",al={"加克希姆位置","加克希姆在哪里","加克希姆·尘链地图"}}},fp="16,364,21.497.0,19.462.0,24.217.0,81.233.0,42.187.0,40.212.0,43.137.0,36.157.0"}
P.entries["npc:gazin-tenorm"] = {n="贾森·坦诺姆",s="在暴风城的光明大教堂祭坛附近，贾森·坦诺姆刚从艾尔文森林的一次危险侦察任务中归来。",h="在暴风城的光明大教堂祭坛附近，贾森·坦诺姆刚从艾尔文森林的一次危险侦察任务中归来。",kw={"光明大教堂","迪菲亚","达索瑞恩·拉尔","贾森·坦诺姆","亨兹·法奥克","圣骑士","圣洁之书"},ang={["class:Paladin"]="作为一名学习怜悯与救赎的新兵，你会在光明大教堂遇见贾森，帮助他倒下的战友亨兹·法奥克。",["race:Dwarf"]="身为矮人，你能看到贾森与暴风城同心协力。他代表王国的顾问们，直面艾尔文的匪徒。"},sec={{t="教堂中的斥候",b="贾森·坦诺姆留在光明大教堂，心思却仍在艾尔文森林。他和挚友亨兹·法奥克曾深入林中，为王廷搜集迪菲亚潜行者动向的证据。迪菲亚的部队伏击了他们。贾森逃回了暴风城，亨兹却身陷险境，命悬一线。如今，贾森正在寻找一位圣光的勇士，帮助他的同伴。"}},faq={{q="在哪里可以找到贾森·坦诺姆？",a="贾森·坦诺姆站在暴风城光明大教堂内部后方的祭坛附近，周围是高阶神职人员和圣骑士导师。",al={"贾森位置","贾森·坦诺姆在哪里","贾森在哪里"}},{q="贾森·坦诺姆在艾尔文森林遭遇了什么？",a="贾森和同伴亨兹·法奥克在调查兄弟会时，遭到了迪菲亚部队的伏击。贾森逃回了暴风城，亨兹却被困在森林中。",al={"贾森的故事","贾森遭遇了什么","贾森为什么受伤"}},{q="贾森为什么要调查迪菲亚潜行者？",a="贾森和亨兹深入艾尔文森林，为暴风城的国王顾问们搜集迪菲亚潜行者从事非法活动的证据。",al={"为什么调查迪菲亚","贾森的任务","贾森 亨兹 迪菲亚"}},{q="贾森与圣骑士的试炼有什么关系？",a="达索瑞恩·拉尔会让那些追寻圣洁之书、立志成为圣骑士的人类去找贾森。贾森会指引他们去营救亨兹·法奥克，考验他们的勇气与仁慈。",al={"贾森 圣洁之书","圣骑士任务 贾森","亨兹·法奥克任务"}}},fx={d8d56684={q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是一名矮人调查员，目前栖身于暴风城的光明大教堂。他与搭档在王室联络人的协助下搜集证据，试图证实都城门外日益加剧的迪菲亚威胁。",al={"贾森是谁","贾森·坦诺姆是谁","贾森·坦诺姆的身份"}},e9ee1d11={q="贾森·坦诺姆效忠哪一方？",a="贾森对联盟和暴风城王国忠心耿耿。他与光明大教堂的祭司和圣骑士并肩工作，努力为国王的宫廷搜集有关艾尔文境内叛乱颠覆活动的确凿情报。",al={"贾森·坦诺姆的阵营","贾森属于联盟吗","贾森为谁效力"}},["22d0c57e"]={q="贾森·坦诺姆想要什么？",a="贾森在迪菲亚暴徒的伏击中勉强活了下来，如今迫切希望有人能从艾尔文森林救出他的同伴亨兹·法奥克。此外，他还想在叛乱进一步扩大之前，向国王的顾问揭露迪菲亚潜行者的阴谋。",al={"贾森想要什么","贾森·坦诺姆的目标","贾森在寻找什么"}},["6cef862e"]={q="贾森·坦诺姆为什么在光明大教堂？",a="与迪菲亚的一场激烈冲突让贾森惊魂未定，他为逃命而奔走，最终来到光明大教堂这处神圣的庇护所。在这里，他待在祭坛附近，在达索瑞恩·拉尔与白银之手的严密保护下休养。",al={"贾森为何在大教堂","贾森·坦诺姆为何在这里","贾森 光明大教堂"}},["2ec8b348"]={q="贾森·坦诺姆与谁有关联？",a="贾森与同为调查员的亨兹·法奥克紧密合作。他也与达索瑞恩·拉尔建立了深厚的信任，后者会指引前途可期的年轻圣骑士前来帮助贾森，共同履行保卫王国的职责。",al={"贾森·坦诺姆的盟友","贾森的关系","贾森与谁合作"}}},fp="12,127,24.372.0,30.135.0,47.170.0,51.140.0,45.162.0"}
P.entries["npc:gazrog"] = {n="加兹罗格",s="加兹罗格在十字路口守护着部落的道路和补给线。他召集途经此地的部落旅人，应对贫瘠之地的威胁，寻找失踪的巡逻队。",h="加兹罗格在十字路口守护着部落的道路和补给线。他召集途经此地的部落旅人，应对贫瘠之地的威胁，寻找失踪的巡逻队。",kw={"贫瘠之地","十字路口","多格兰","加兹罗格","部落哨所","迅猛龙窃贼","被偷走的银币"},ang={["faction:Horde"]="作为一名从杜隆塔尔或莫高雷出发的部落旅人，你可以到加兹罗格那里领取差事，保障卡利姆多各地道路的安全。",["race:Orc"]="身为兽人，你知道加兹罗格是一名坚守十字路口的老兵，要守护这片边疆的安宁，需要勇气和决心。"},sec={{t="十字路口的哨兵",b="加兹罗格守望着十字路口及周边的道路。劫掠者和野兽威胁着途经这处偏远聚落的补给，因此他与当地守军协作，保障货物、钱币和信使通行。荒野中的动静需要时刻留意，加兹罗格依靠过往的旅人，处理哨所栅栏之外的麻烦。"},{t="草原上的危机",b="加兹罗格的守望范围延伸至各条小径，迅猛龙在那里捕食旅人，野猪人氏族则伏击斥候。他协调人手应对拦路抢劫，包括追回部落被盗的货物。他也留意着失踪士兵的下落，其中就有负伤后被野猪人扣押的步兵多格兰。"}},faq={{q="在哪里可以找到加兹罗格？",a="加兹罗格就在十字路口，那里是贫瘠之地北部、南部和东部道路的交汇处。",al={"加兹罗格位置","加兹罗格在哪里","加兹罗格十字路口"}},{q="加兹罗格为部落担任何种职责？",a="加兹罗格负责协调行动，守卫十字路口。他指派部落旅人保护补给线、追回被盗的货物，并寻找失踪人员。",al={"加兹罗格职责","加兹罗格是谁","加兹罗格做什么"}},{q="加兹罗格问起的被偷走的银币是怎么回事？",a="贫瘠之地道路上的迅猛龙和趁火打劫之徒，经常盯上部落运送钱币的车队。加兹罗格派勇士追击那些野兽，追回被盗的货物。",al={"被偷走的银币任务","谁偷走了银币","贫瘠之地被盗的货物"}},{q="多格兰是谁？",a="多格兰是一名被派驻十字路口、与加兹罗格共事的部落步兵。加兹罗格听说多格兰还活着，只是负了伤，被野猪人扣押，但他宁愿瞒着多格兰的伴侣赞卡沙。",al={"多格兰的消息","多格兰在哪里","加兹罗格多格兰"}},{q="加兹罗格与棘齿城或地精有关系吗？",a="加兹罗格驻守十字路口，为部落效力。他在贫瘠之地中部维护安全，保障兽人、牛头人和巨魔的利益。",al={"加兹罗格属于棘齿城吗","加兹罗格阵营","加兹罗格地精"}},{q="迅猛龙为什么要偷窃贫瘠之地的补给？",a="没人知道迅猛龙为什么要偷窃补给。它们把银币藏在棘齿城南方迅猛龙巢穴的窝里，加兹罗格也想知道，那些关于它们智慧的传闻是否属实。",al={"迅猛龙为什么偷东西","迅猛龙会偷东西吗","迅猛龙闪亮物品"}}},fp="6,165,28.336.0,16.289.0,26.104.0,41.168.0,53.148.0,14.205.0,49.131.0,49.175.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Gelbin Mekkatorque",s="在侏儒区，Gelbin Mekkatorque领导着流亡铁炉堡的侏儒。他的发明包括机械陆行鸟和矿道地铁，他也指引着夺回诺莫瑞根的行动。",h="在侏儒区，Gelbin Mekkatorque领导着流亡铁炉堡的侏儒。他的发明包括机械陆行鸟和矿道地铁，他也指引着夺回诺莫瑞根的行动。",kw={"矿道地铁","格尔宾","侏儒","诺莫瑞根","大工匠","铁炉堡","机械陆行鸟","梅卡托克","瑟玛普拉格","侏儒区"},ang={["profession:Engineering"]="站在你面前的是大工匠，他发明了机械陆行鸟，也是推动矿道地铁建成的关键人物。他在侏儒区的工坊继续推动着侏儒工程学的发展。",["race:Gnome"]="身为侏儒，你将梅卡托克视为流亡族人的领袖。诺莫瑞根遭受毒害一事令他深感愧疚，而他的才智与夺回你们祖传家园的决心，则赢得了侏儒区侏儒们的忠诚。"},sec={{t="大工匠与发明大师",b="Gelbin Mekkatorque凭借发明才华赢得了大工匠的头衔。在侏儒之中，领袖的地位取决于才智和功绩，而非血统。他造出了第一台能够正常运转的机械陆行鸟，改变了侏儒的出行方式。他还帮助铜须矮人研制攻城坦克，并在修建连接铁炉堡与暴风城的矿道地铁时发挥了关键作用。"},{t="背叛与流亡铁炉堡",b="石腭怪从地下深处涌出，入侵了诺莫瑞根。在挚友兼首席顾问麦克尼尔·瑟玛普拉格的劝说下，格尔宾·梅卡托克下令将放射性废料排入下层通道，以杀死入侵者。然而，毒气却夺去了数千名无辜侏儒的性命，并使幸存者发生变异。瑟玛普拉格占据了这座沦为废墟的城市。\n\n梅卡托克带领幸存的难民穿越丹莫罗，来到铁炉堡，心中满是愧疚，决意弥补过错。麦格尼国王在侏儒区接纳了他们。在那里，梅卡托克统筹侏儒的军事与科研行动，力图夺回诺莫瑞根。"}},faq={{q="格尔宾·梅卡托克是谁？",a="格尔宾·梅卡托克是侏儒选出的大工匠，领导着侏儒一族。身为工程学大师，他设计了许多重要发明，包括机械陆行鸟和矿道地铁。",al={"大工匠","侏儒领袖","侏儒国王是谁"}},{q="梅卡托克为何身在铁炉堡，而非诺莫瑞根？",a="石腭怪攻陷了诺莫瑞根，放射性尘埃也摧毁了这座城市。梅卡托克带领族人穿越丹莫罗，来到铁炉堡，国王麦格尼·铜须让他们在侏儒区避难，他们也在此筹划夺回家园。",al={"梅卡托克为何在铁炉堡","侏儒为何在铁炉堡","诺莫瑞根陷落"}},{q="是什么导致了诺莫瑞根的灾难？",a="梅卡托克信任的顾问说服他将有毒的放射性冷却液排入诺莫瑞根的下层区域，以阻止石腭怪。毒气未能阻止它们，反而使整座城市遭到辐射污染，夺去了数千名侏儒的性命。",al={"诺莫瑞根发生了什么","诺莫瑞根为何遭到辐射污染","瑟玛普拉格的背叛"}},{q="梅卡托克在成为大工匠之前发明了什么？",a="在成为大工匠之前，梅卡托克发明了机械陆行鸟。他还协助研制了矮人的攻城坦克，并在建造连接铁炉堡与暴风城的矿道地铁时发挥了关键作用。",al={"梅卡托克的发明","格尔宾建造了什么"}},{q="梅卡托克真的是国王吗？",a="侏儒没有世袭的君主。他们依据功绩和才智选出大工匠，梅卡托克的权威便来自这场选举。",al={"梅卡托克是国王吗","侏儒国王"}}},fx={db25d752={q="格尔宾·梅卡托克效忠哪一方？",a="格尔宾·梅卡托克坚定地站在联盟一方。作为侏儒的领袖，他与国王麦格尼·铜须及铁炉堡的矮人保持着牢不可破的情谊；正是他们敞开城门，收留了流离失所的侏儒同胞。梅卡托克承诺以侏儒的工程技术、智慧和军事资源，援助艾泽拉斯各地的联盟盟友。",al={"梅卡托克的阵营","格尔宾是否效忠联盟","梅卡托克效忠谁"}},["0e3721be"]={q="格尔宾·梅卡托克想要什么？",a="梅卡托克唯一的目标就是收复诺莫瑞根。家园沦陷、无数侏儒惨遭杀害，这些沉重的悲痛驱使他寻找办法，清除穴居人和污染大厅的辐射。从侏儒区出发，他安排侦察行动并组织突击队，为夺回城市做好准备。",al={"梅卡托克的目标","格尔宾想做什么","格尔宾的计划"}},["39ae11c6"]={q="格尔宾·梅卡托克与谁有联系？",a="梅卡托克与他在铁炉堡的热情东道主国王麦格尼·铜须密切合作，也与暴风城的联盟领袖协调行动。在个人层面上，诺莫瑞根的沦陷，以及他听从一位受信任顾问的建议、下令释放辐射后死去的数千名侏儒，一直令他难以释怀。",al={"梅卡托克的盟友","格尔宾的人际关系","梅卡托克与谁合作"}},["5cf35b41"]={q="格尔宾·梅卡托克为何出名？",a="梅卡托克在艾泽拉斯享有盛名，被誉为历史上最伟大的工程天才之一。他发明了第一台能够正常运作的机械陆行鸟，协助设计了矮人的攻城器械，还对连接铁炉堡与暴风城的矿道地铁的建造起到了关键作用。",al={"梅卡托克为何出名","格尔宾以什么闻名","梅卡托克的发明"}}},fp="18,195,35.366.0,31.615.1,26.169.0,54.227.0,42.227.0,56.201.0,30.146.0"}
P.entries["npc:gelihast"] = {n="格里哈斯特",s="在黑暗深渊，格里哈斯特守卫着被水淹没的阿斯卡之池中的一座奇异祭坛。他麾下的盲光鱼人聚集在他周围，盘踞于沉没的神庙中。",h="在黑暗深渊，格里哈斯特守卫着被水淹没的阿斯卡之池中的一座奇异祭坛。他麾下的盲光鱼人聚集在他周围，盘踞于沉没的神庙中。",kw={"黑暗深渊","盲光","格里哈斯特","鱼人","阿斯卡之池","暮光之锤"},ang={["class:Warrior"]="格里哈斯特的剑击快得令人眼花缭乱。身为战士，你可以稳住阵脚，利用他狂乱的双刃攻势反制他。",["faction:Alliance"]="身为一名致力于清除渗入灰谷的腐化的联盟冒险者，你必须除掉格里哈斯特，确保被水淹没的神庙北部通道安全。",["faction:Horde"]="身为一名奉命清剿黑暗深渊的部落冒险者，你必须消灭格里哈斯特，打通深入佐拉姆海岸下方那座沉没的神庙的道路。"},sec={{t="致命的召唤",b="在佐拉姆海岸的地下深处，格里哈斯特占据了黑暗深渊中的一处巢穴。大多数鱼人都栖身于沿海浅水区，他却手持双剑袭击入侵者，动作之快让许多人来不及反应。进入他攻击范围的施法者很少能活下来。"},{t="盲光之主",b="格里哈斯特与他麾下的盲光鱼人统治着阿斯卡之池，稍有动静，这些鱼人就会蜂拥到他身边。他的巢穴后方矗立着一座祭坛。击败他并触碰祭坛的人会获得黑暗深渊的祝福。"}},faq={{q="格里哈斯特是谁？",a="格里哈斯特在黑暗深渊深处的阿斯卡之池统率着盲光部族。他挥舞双刃作战，速度快得令人眼花缭乱。",al={"格里哈斯特是谁","格里哈斯特故事","格里哈斯特背景"}},{q="格里哈斯特为什么会在黑暗深渊里？",a="没有人知道最初是什么将格里哈斯特吸引到了黑暗深渊。他和麾下的盲光鱼人占据了被水淹没的废墟中的阿斯卡之池，凶狠地抵御着入侵者。",al={"黑暗深渊为什么有鱼人","格里哈斯特为什么在神庙里"}},{q="暮光之锤对他有何反应？",a="没有任何记载提及格里哈斯特与神庙深处的暮光之锤教徒有过什么往来。他与麾下的盲光鱼人统治着自己的水池。",al={"格里哈斯特与暮光之锤","教徒喜欢格里哈斯特吗"}},{q="格里哈斯特身后的祭坛是什么？",a="格里哈斯特盘踞的水池后方矗立着一座祭坛。旅行者击败他后，可以触碰祭坛，获得黑暗深渊的祝福。",al={"深渊祭坛","格里哈斯特祭坛","黑暗深渊祝福祭坛"}},{q="他领导着哪个鱼人部族？",a="格里哈斯特领导着盲光鱼人，这个凶暴的部族盘踞在洞穴中的阿斯卡之池。",al={"格里哈斯特部族","黑暗深渊有哪些鱼人"}},{q="如果放任格里哈斯特不管，会发生什么？",a="格里哈斯特和麾下的盲光鱼人封锁着阿斯卡之池，阻挡任何试图深入沉没的神庙的人。",al={"格里哈斯特命运","谁杀死格里哈斯特"}}},fp="8,144,16.259.0,24.218.0,16.138.0,41.189.0,43.151.0,34.118.0,35.110.0,49.126.0"}
P.entries["npc:gelkak-gyromast"] = {n="基尔卡克·旋杆",s="基尔卡克·旋杆的船被蛇颈龙击沉后，他便流落在黑海岸北部的薄雾海沿岸。这个侏儒说起话来像个海盗船长，想让他的机械大副机械打手4100重新运转起来。",h="基尔卡克·旋杆的船被蛇颈龙击沉后，他便流落在黑海岸北部的薄雾海沿岸。这个侏儒说起话来像个海盗船长，想让他的机械大副机械打手4100重新运转起来。",kw={"黑海岸","基尔卡克·旋杆","侏儒发明家","玛塞斯特拉","薄雾海","机械打手 4100"},ang={["profession:Engineering"]="身为工程师，你看得出基尔卡克将复仇的希望寄托在他那台令人赞叹的装置Threshwackonator 4100上。",["race:Gnome"]="身为侏儒，看到同族流落在卡利姆多的边缘，你便能体会到冒险会让你离家多远。"},sec={{t="流落薄雾海",b="基尔卡克·旋杆流落在玛塞斯特拉废墟以西、黑海岸北部的海岸上。这个侏儒说起话来像个老海员，还自称船长。蛇颈龙在离岸不远处击沉了他的船，他被冲上了雾气弥漫的海岸。他的机械大副机械打手4100型的钥匙在岩石上撞碎了。螃蟹、森林陆行鸟和鱼人在残骸中翻找，带走了钥匙的碎片。"},{t="机械打手故障",b="旅行者找回钥匙后，基尔卡克便让他们启动机械打手4100型，把它带回自己身边。他希望用它对付沿岸的鱼人和野兽。机器起初顺从地跟着走，却在抵达船长身边时出了故障，开始发起攻击。旅行者必须摧毁它。"}},faq={{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆流落在薄雾海沿岸，那里是黑海岸北部的海滩，就在玛塞斯特拉废墟以西。这个侏儒说起话来像个海盗船长。",al={"基尔卡克","基尔卡克是谁","旋杆"}},{q="基尔卡克为什么会流落在黑海岸？",a="蛇颈龙在离岸不远处击沉了基尔卡克的船，他带着机械大副的破碎钥匙，被冲上了黑海岸北部的海岸。",al={"基尔卡克为什么在这里","基尔卡克 黑海岸"}},{q="机械打手 4100是什么？",a="机械打手 4100是基尔卡克制造的机械造物，也是自封的大副。他想让它重新运转起来，好向沿岸的鱼人和野兽复仇。",al={"机械打手","基尔卡克的机器","机器人"}},{q="基尔卡克需要旅行者帮什么忙？",a="基尔卡克请旅行者从沿岸的螃蟹、森林陆行鸟和鱼人那里找回他那把钥匙的三块碎片。然后，他们就能启动机械打手4100型，把它带回他身边。",al={"基尔卡克的任务","旋杆的任务"}}},fp="15,169,23.409.0,32.325.1,23.151.0,36.138.0,34.181.0,42.193.0"}
P.entries["npc:general-marcus-jonathan"] = {n="马库斯·乔纳森将军",s="马库斯·乔纳森将军在暴风城城门守卫首都，权衡王国边境定居点的求援。作为第二次大战的老兵，他统领暴风城防御部队，并负责管理驻军。",h="马库斯·乔纳森将军在暴风城城门守卫首都，权衡王国边境定居点的求援。作为第二次大战的老兵，他统领暴风城防御部队，并负责管理驻军。",kw={"乔纳森将军","湖畔镇","所罗门镇长","马库斯·乔纳森","雷吉纳德·温德索尔","暴风城军队","暴风城防御","英雄谷"},ang={["class:Warrior"]="作为一名战士，你可以将马库斯·乔纳森将军视为王国步兵履行军人职责的典范，他既是暴风城城门的指挥官，也是一位Second War老兵。",["faction:Alliance"]="作为一名联盟战士，你可以从驻守首都城门的马库斯·乔纳森身上，看到暴风城引以为傲的军人风范。"},sec={{t="城门指挥官",b="马库斯·乔纳森将军骑马驻守英雄谷，指挥暴风城的防务。他是城门处军衔最高的军官，也是这座城市的第一道防线。在第二次大战期间，他曾在图拉扬将军麾下，与雷吉纳德·温德索尔等士兵并肩作战。如今，他必须保卫首都，而包括湖畔镇在内的边境城镇，求援的呼声却日益迫切。"},{t="重压下的指挥",b="马库斯·乔纳森将军向地方行政官保证，他会尽力帮助湖畔镇等城镇击退黑石兽人和豺狼人。私下里，他坦言王廷已变得疏远，年幼国王的摄政当局也举止反常。"}},faq={{q="在哪里能找到马库斯·乔纳森将军？",a="马库斯·乔纳森将军骑马驻守在暴风城正门内侧，俯瞰英雄谷的入城桥梁。",al={"马库斯·乔纳森位置","乔纳森将军在哪里","暴风城城门指挥官"}},{q="马库斯·乔纳森有怎样的从军经历？",a="马库斯·乔纳森将军在第二次战争期间效力于图拉扬将军麾下，与雷吉纳德·温德索尔等战友并肩作战。他最终晋升为暴风城防御部队的最高指挥官。",al={"马库斯·乔纳森往事","马库斯·乔纳森背景故事","马库斯是否参加过第二次战争"}}},fp="23,206,22.396.0,18.241.1,41.127.0,43.198.0"}
P.entries["npc:gerard-tiller"] = {n="葛拉德·提勒",s="葛拉德·提勒在马科伦农场打理场地，盼着喝上一口泉水。给他带去一皮囊泉水，他就会拿新鲜的红苹果来交换。",h="葛拉德·提勒在马科伦农场打理场地，盼着喝上一口泉水。给他带去一皮囊泉水，他就会拿新鲜的红苹果来交换。",kw={"艾尔文森林","葛拉德·提勒","给葛拉德水喝","马科伦农场","清凉的泉水","新鲜的红苹果"},ang={["profession:Cooking"]="葛拉德用新鲜苹果换取普通泉水，让想要简单食材的旅人有了获取水果的地方。"},sec={{t="口渴的农场雇工",b="葛拉德·提勒在闪金镇以南的马科伦农场谷仓外干活。这座农场以葡萄闻名，要让收成不断，就得辛勤劳作。农活让他口干舌燥，所以他很欢迎带着一皮囊新鲜泉水前来的旅人。作为回报，他会给他们一些从当地果园采来的新鲜的红苹果。"}},faq={{q="葛拉德·提勒是谁？",a="葛拉德·提勒是一名人类农场雇工，在艾尔文森林南部的马科伦农场谷仓外干活。",al={"葛拉德·提勒身份","葛拉德是谁","提勒艾尔文森林"}},{q="在哪里可以找到葛拉德·提勒？",a="去马科伦农场的大木谷仓外找找，那里位于闪金镇以南、斯通菲尔德农场以东。",al={"葛拉德·提勒位置","葛拉德在哪里","艾尔文森林寻找葛拉德"}},{q="葛拉德·提勒用什么交换？",a="葛拉德用一个新鲜的红苹果换取一皮囊清凉的泉水。",al={"葛拉德苹果交换","葛拉德·提勒泉水","葛拉德想要什么"}},{q="葛拉德会卷入马科伦和斯通菲尔德两家的争斗吗？",a="不会。葛拉德在马科伦农场干活，只顾着做农活和解渴，不参与马科伦家族和斯通菲尔德两家的争斗。",al={"葛拉德·提勒争斗","马科伦争斗葛拉德"}}},fx={["467277ed"]={q="葛拉德·提勒想要什么？",a="在烈日下的马科伦农场劳作让人口干舌燥，葛拉德只想要一皮囊清凉的泉水来解渴。如果你给他带来水喝，他会很乐意拿果园里一颗爽脆的新鲜的红苹果作为交换。",al={"葛拉德·提勒需要什么","葛拉德·提勒的交易","葛拉德想要什么"}},["9aadf23d"]={q="葛拉德·提勒为何在这里？",a="葛拉德·提勒靠在马科伦农场的谷仓外打理场地为生。尽管周边的艾尔文地区动荡不安，葛拉德仍专注于日常农活，照料庄稼。",al={"葛拉德·提勒为何在葡萄园","葛拉德·提勒在此的原因","葛拉德·提勒做什么"}},["9f9d4e60"]={q="葛拉德·提勒与谁有联系？",a="葛拉德与马科伦家族有联系，在他们位于暴风城以南的葡萄园里干活。虽然他就在这个家族的土地上、谷仓旁劳作，但他只管自己的事，避开马科伦家族与邻近的对头斯通菲尔德家族之间激烈的争斗。",al={"葛拉德·提勒的关系","葛拉德·提勒为谁工作","葛拉德·提勒的盟友"}}},fp="13,141,18.335.0,21.112.0,31.112.0,30.70.0,60.138.0"}
P.entries["npc:gerrig-bonegrip"] = {n="葛利·硬骨",s="在铁炉堡的荒弃的洞穴，葛利·硬骨买卖奇异典籍，以及记述黑暗仪式与远古力量的文献。",h="在铁炉堡的荒弃的洞穴，葛利·硬骨买卖奇异典籍，以及记述黑暗仪式与远古力量的文献。",kw={"黑暗深渊","硬骨","荒弃的洞穴","葛利","铁炉堡","洛迦里斯手稿","符文与厄运"},ang={["class:Warlock"]="身为术士，你可以在荒弃的洞穴的硬骨所收藏的冷僻仪式文献与黑暗典籍中，找到危险的知识。",["race:Dwarf"]="身为矮人，你或许会觉得，硬骨买卖禁忌知识的行径，为铁炉堡的学术生活蒙上了一层令人不安的阴影。"},sec={{t="硬骨符文与厄运",b="葛利·硬骨在荒弃的洞穴经营着葛利·硬骨的符文和厄运。在大多数市民眼中，他是个性情古怪的商人，买卖奇异遗物与禁忌知识。在这门生意的掩护下，葛利为信奉虚无的暮光之锤教派效力。他搜集危险的手稿与记述上古之神的冷僻文献，而铁炉堡参议院和王座厅对此仍一无所知。"},{t="搜集禁忌知识",b="葛利招募不知情的联盟冒险者，让他们找回古代文物，其中就包括藏在黑暗深渊深处的洛迦里斯手稿。他将这些遗物中的知识抄录下来，与遍布艾泽拉斯的教派同僚分享。他的关系网包括斯奎尔图，以及与密斯莱尔等远古原初存在有牵连的人物。葛利致力于推进教派毁灭世界的图谋。"}},faq={{q="葛利·硬骨是谁？",a="葛利·硬骨在铁炉堡的荒弃的洞穴经营着葛利·硬骨的符文和厄运。他买卖奇异的珍玩，以及记述古老仪式的冷僻典籍。",al={"硬骨是谁","葛利·硬骨背景故事","硬骨 铁炉堡"}},{q="他用洛迦里斯手稿做什么？",a="葛利想要取得黑暗深渊中的洛迦里斯手稿，将其纳入自己的珍稀典籍收藏。进一步调查，便能揭示他如何使用这份手稿。",al={"硬骨为什么想要洛迦里斯手稿","深渊中的知识 交任务","洛迦里斯手稿用途"}},{q="葛利如何在铁炉堡活动？",a="葛利以古怪学者和商人的身份，在荒弃的洞穴低调行事，买卖冷僻典籍。",al={"铁炉堡知道硬骨是邪教徒吗","为什么允许硬骨留在铁炉堡"}},{q="他与密斯莱尔有什么联系？",a="葛利与矮人斯奎尔图是旧识，后者正在阿拉希高地调查被封印的土元素密斯莱尔。通过这些关系，葛利协助安排与古老束缚仪式和原初力量有关的事务。",al={"葛利·硬骨与密斯莱尔","斯奎尔图与葛利"}}},fx={ec528c98={q="葛利·硬骨站在哪一边？",a="葛利是铁炉堡的矮人，在荒弃的洞穴经营着葛利·硬骨的符文和厄运。他买卖有关仪式与远古力量的晦涩知识，并告诫来访者，他掌握的某些知识并非未经入门之人所能接触。",al={"葛利·硬骨的阵营","葛利为谁工作","葛利·硬骨是邪恶的吗"}},f2a99842={q="葛利·硬骨为何在铁炉堡？",a="葛利在铁炉堡幽暗的荒弃的洞穴开了一家店，收集并买卖稀有手稿、符文，以及有关仪式的古老知识。他付钱请冒险者从黑暗深渊寻回洛迦里斯手稿之类的文献。",al={"葛利为何在铁炉堡","葛利·硬骨在这里做什么","葛利·硬骨为何在荒弃的洞穴"}}},fp="15,119,26.363.1,30.398.1,23.152.2,45.142.1,37.120.2,34.231.0"}
P.entries["npc:gershala-nightwhisper"] = {n="戈沙拉·夜语",s="在奥伯丁，戈沙拉·夜语研究魔法腐化对精灵的影响。奎尔萨拉斯的高等精灵所走的道路令他忧心，他检视受到诅咒的水生生物与恶魔生物，寻找腐化改变身心的迹象。",h="在奥伯丁，戈沙拉·夜语研究魔法腐化对精灵的影响。奎尔萨拉斯的高等精灵所走的道路令他忧心，他检视受到诅咒的水生生物与恶魔生物，寻找腐化改变身心的迹象。",kw={"奥伯丁","黑暗深渊","腐化","黑海岸","戈沙拉","娜迦","夜语","萨特"},ang={["faction:Alliance"]="对联盟而言，戈沙拉是一位资助者，他派遣探险队深入危机四伏的黑暗深渊，从中获取宝贵的奥术知识。",["race:NightElf"]="对暗夜精灵而言，戈沙拉令人不安的探究让他们想起远古的Sundering，以及魔法成瘾的惨痛代价，他们的同胞曾因此化为可怕的怪物。"},sec={{t="蜕变研究",b="身在奥伯丁的戈沙拉·夜语，目光越过黑海岸沿岸的困境，投向了奎尔萨拉斯高等精灵身上潜藏的危险。他痛心地看着他们拥抱危险的奥术技艺，并自称血精灵。戈沙拉想要弄清，不受约束的魔法会给肉体与灵魂带来怎样的变化。为此，他派遣经验丰富的联盟冒险者深入黑暗深渊被水淹没的殿堂，收集栖居其中的娜迦和萨特的腐化脑干。"},{t="毁灭的解药",b="戈沙拉对娜迦和萨特脑干的兴趣，源于这两个种族共同的过去。在屈从于艾萨拉女王、与恶魔订立契约之前，他们都曾是暗夜精灵。戈沙拉检视着数千年来恶魔与深渊能量在他们神经系统上留下的痕迹。他希望找到警示或防护之法，让其他精灵同胞免遭类似的可怕畸变。"}},faq={{q="在哪里可以找到戈沙拉·夜语？",a="戈沙拉·夜语位于奥伯丁，那是黑海岸沿岸联盟的主要港口城镇。",al={"戈沙拉位置","戈沙拉在哪里","寻找戈沙拉·夜语"}},{q="戈沙拉为什么需要娜迦和萨特的脑干？",a="戈沙拉研究腐化的脑干，以探究魔法与恶魔之力引发的蜕变如何改变昔日暗夜精灵的身体构造。娜迦和萨特都曾是精灵，他想弄清他们遭受腐化后身体发生的变化。",al={"为什么需要脑干","腐化研究背景故事","戈沙拉研究什么"}},{q="戈沙拉希望通过研究达成什么目的？",a="戈沙拉希望自己的研究能帮助血精灵，防止他们因危险地依赖邪能和不受约束的奥术之力而堕入邪恶，变得畸形可怖。",al={"戈沙拉的目标","为什么帮助血精灵","戈沙拉的研究目的"}},{q="戈沙拉需要的样本在哪里？",a="戈沙拉指引冒险者前往黑暗深渊，那是灰谷沿岸一处被水淹没的古老神殿废墟，娜迦和萨特栖居其中。",al={"脑干在哪里","黑暗深渊脑干","戈沙拉的物品在哪里找"}}},fp="21,249,23.452.0,19.381.0,37.94.0,50.208.0,56.158.0,47.137.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="加摩拉",s="在黑暗深渊，加摩拉守卫着Pool of Ask'ar中的一座小岛。这只古老的巨龟会践踏任何靠近的人。",h="在黑暗深渊，加摩拉守卫着Pool of Ask'ar中的一座小岛。这只古老的巨龟会践踏任何靠近的人。",kw={"黑暗深渊","艾露恩","加摩拉","阿斯卡之池","驯服","海龟","暮光之锤"},ang={["class:Druid"]="身为德鲁伊，你眼中的加摩拉是一只古老的深渊生物，在遭到亵渎的神庙废墟中变得凶暴。",["class:Hunter"]="身为踏入黑暗深渊的猎人，你或许会怜悯加摩拉这只高贵而古老的深渊野兽。只要有耐心，你仍有机会驯服他。",["race:NightElf"]="身为暗夜精灵，看到凶暴的加摩拉盘踞在Elune被淹没的神庙中，你或许会痛心地意识到，这处圣地在邪恶的暮光之锤手中已沦落到何种地步。"},sec={{t="沉没神庙中的野兽",b="黑暗深渊曾是暗夜精灵供奉艾露恩的神庙。如今，遗迹已被洪水淹没，被纳迦、萨特和信奉虚无的暮光之锤教派占据。加摩拉栖居其间，巨大的厚重龟壳能挡下几乎所有打击，唯有最坚决的猛击才能奏效。"},{t="深渊的守护者",b="在Pool of Ask'ar的一座小岛上，体型较小的海龟围在加摩拉身边，它们不会打扰旅人。只有加摩拉会发起攻击，用庞大的身躯践踏、碾碎任何靠近的人。"}},faq={{q="加摩拉是谁？",a="加摩拉守卫着黑暗深渊内阿斯卡之池中的一座小岛，这座被淹没的艾露恩神庙已被暮光之锤占据。他会攻击任何靠近的人。",al={"加摩拉背景故事","黑暗深渊巨龟","加摩拉是谁"}},{q="加摩拉为何敌视外来者？",a="没有记载说明加摩拉为何变得如此凶暴。他会攻击任何闯入阿斯卡之池中他所栖居小岛的人，践踏所有靠近者。",al={"海龟为何愤怒","海龟为何攻击","加摩拉的疯狂"}},{q="猎人能驯服加摩拉吗？",a="能。尽管加摩拉体型庞大，又饱受多年折磨，技艺娴熟的猎人依然可以驯服他。",al={"驯服加摩拉","猎人能否驯服黑暗深渊海龟"}},{q="阿斯卡之池是什么地方？",a="阿斯卡之池是黑暗深渊中一处被水淹没的地下洞穴。加摩拉在其中一座小岛的中央游荡，周围是温顺的本地海龟。",al={"阿斯卡之池","加摩拉在哪里"}},{q="他与上古之神有什么联系？",a="没有相关记载。加摩拉是深渊中的野兽，而崇拜上古之神的暮光之锤教徒已经占据了他周围那座沉没的神庙。",al={"加摩拉与上古之神","海龟是否被腐化"}}},fp="9,133,29.244.0,21.198.0,17.187.0,38.149.0,28.95.0,27.146.0,45.152.0"}
P.entries["npc:gilnid"] = {n="基尔尼格",s="在死亡矿井深处，基尔尼格为迪菲亚潜行者管理着地精熔炉。他被称为熔炼师，负责监督将原矿炼成精炼金属和军火的工作，供艾德温·范克里夫的秘密铁甲巨舰使用。他的铸造厂制造着兄弟会进攻暴风城所需的重型火炮。",h="在死亡矿井深处，基尔尼格为迪菲亚潜行者管理着地精熔炉。他被称为熔炼师，负责监督将原矿炼成精炼金属和军火的工作，供艾德温·范克里夫的秘密铁甲巨舰使用。他的铸造厂制造着兄弟会进攻暴风城所需的重型火炮。",kw={"火炮","死亡矿井","迪菲亚","熔炉","铸造厂","基尔尼格","地精","巨舰","冶炼师","范克里夫"},ang={["faction:Alliance"]="阻止基尔尼格，就能切断迪菲亚的武器生产线，使范克里夫的战舰无法配齐武器，威胁暴风城港口。",["profession:Engineering"]="基尔尼格的铸造厂展现了地精重工业的运作：在恶劣的条件下，生产舰炮、弹药和船体结构用的金属板。",["profession:Mining"]="基尔尼格的高炉和熔炼锅展示了迪菲亚潜行者如何将西部荒野的原矿炼成精铁，制成武器。"},sec={{t="铸造厂之主",b="在死亡矿井深处，迪菲亚潜行者依靠技艺娴熟的工匠锻造战争兵器。基尔尼格是范克里夫的首席冶炼师，在中央铸造厂指挥着地精劳工、技师和铁匠。他比大多数同族都高大，驱使他们在浓烟与炉渣间劳作，大声发号施令，不许片刻休息。他们将铁矿石加工成厚重的装甲板和致命的军火。"},{t="武装巨舰",b="基尔尼格的铸造厂支撑着兄弟会的宏大野心。他负责督造重型火炮和弹药，供停泊在工坊后方地下海湾中的庞大铁甲战舰使用。只有他的手下造好每一门炮、每一根炮管和每一颗炮弹，迪菲亚的战舰才能按计划进攻暴风城。"}},faq={{q="基尔尼格是谁？",a="基尔尼格是一名地精工程师，也是艾德温·范克里夫在死亡矿井的首席冶炼师。他管理着兄弟会的熔炉，指挥工人为其战争机器铸造火炮和弹药。",al={"基尔尼格 死亡矿井","基尔尼格是谁","熔炼师"}},{q="基尔尼格为什么在死亡矿井？",a="迪菲亚潜行者雇用了地精工程师，为其秘密战舰进行建造和补给。基尔尼格主持冶炼工作，将开采出的铁矿石加工成精制零件、装甲和火炮。",al={"地精为什么在死亡矿井","基尔尼格 迪菲亚 背景故事","基尔尼格在做什么"}},{q="基尔尼格在忙什么？",a="矿井更深处的码头藏着一艘巨舰，基尔尼格负责督造武装这艘巨舰所需的火炮、船用零件和炮弹。",al={"基尔尼格 火炮","基尔尼格在建造什么","死亡矿井 熔炉用途"}},{q="为什么必须击败基尔尼格？",a="基尔尼格控制着挡在通往海湾道路上的铸造厂。只有控制了熔炼室，矿井深处厚重的防爆门才会开启。",al={"为什么要杀基尔尼格","基尔尼格后面的门"}},{q="基尔尼格直接为艾德温·范克里夫效力吗？",a="是的。基尔尼格是一名受雇的地精专家，直接听命于范克里夫，负责重型金属加工和武器生产。他并非最初的石匠兄弟会成员。",al={"范克里夫和基尔尼格","基尔尼格是迪菲亚首领吗"}},{q="为什么他身边有这么多地精？",a="基尔尼格在铸造厂里领导着一支地精工程队。他们在他的严密监督下操作高炉、浇铸铁水、组装军火。",al={"基尔尼格 地精","死亡矿井 熔炉工人"}}},fp="6,303,21.350.0,21.292.1,14.188.0,31.183.0,26.123.0,28.149.0,45.173.0,41.157.0"}
P.entries["npc:gilshalan-windwalker"] = {n="基尔沙兰·风行者",s="在幽影谷的奥达希尔树根旁，基尔沙兰·风行者研究着蔓延于泰达希尔的腐化。他的研究从树林蜘蛛及其日益增强的攻击性开始。",h="在幽影谷的奥达希尔树根旁，基尔沙兰·风行者研究着蔓延于泰达希尔的腐化。他的研究从树林蜘蛛及其日益增强的攻击性开始。",kw={"奥达希尔","基尔沙兰","幽影谷","蜘蛛","特纳隆","毒液","树林","风行者"},ang={["class:Druid"]="身为德鲁伊，你看得出基尔沙兰的研究有助于塞纳里奥议会查明幽影谷枝间生态失衡的原因。",["race:NightElf"]="身为暗夜精灵，你看到了基尔沙兰最初的探索，他试图弄清这棵年轻的世界之树为何已经栖息着狂暴而饱受侵害的野生动物。"},sec={{t="树根旁的学者",b="基尔沙兰·风行者在奥达希尔入口的石阶上观察着幽影谷。种下泰达希尔，是为了重建暗夜精灵失去的庇护之所，恢复他们与自然的和谐，然而精神衰败的迹象几乎随即出现。基尔沙兰研究着腐化对当地野兽的影响，首先关注的是在附近结网的毒蜘蛛。"},{t="树林蜘蛛的威胁",b="基尔沙兰研究着幽影谷北部黑丝洞中的树林蜘蛛。这些蜘蛛曾是森林平衡的一部分，如今却变得充满敌意，遭到了腐化。他派年轻的新手去收集毒囊和完好的卵。他希望通过研究这些样本，了解毒液发生了怎样的变化，以及腐化究竟会代代相传，还是从泰达希尔的土壤中蔓延而来。"},{t="传话给大德鲁伊",b="基尔沙兰认为，蜘蛛的毒液或许带有这棵新世界之树近期生长的迹象。他安排将毒液和一枚卵送往达纳苏斯，自己将在那里继续研究。他还告诉那些前途可期的守护者，特纳隆·雷拳正在奥达希尔最高处的房间里找他们，德鲁伊的领袖们在那里守望着这棵年轻的世界之树。"}},faq={{q="基尔沙兰·风行者是谁？",a="基尔沙兰·风行者在幽影谷的奥达希尔研究野生动物。这位暗夜精灵学者调查着影响泰达希尔生物的腐化。",al={"基尔沙兰","基尔沙兰是谁","风行者 暗夜精灵"}},{q="基尔沙兰为什么需要树林蜘蛛的毒液？",a="基尔沙兰需要树林蜘蛛的毒液，以研究毒液发生了怎样的变化，以及蜘蛛为何变得如此好斗，腐化如此严重。",al={"为何需要树林蜘蛛毒液","树林蜘蛛毒液任务","蜘蛛毒液 基尔沙兰"}},{q="他如何处理树林蜘蛛的卵？",a="基尔沙兰将树林蜘蛛的卵与毒液一同送往达纳苏斯，以便在那里研究这些样本。尚未孵化的卵比成年的巨型蜘蛛更容易运输，捕捉后者实在太过危险。",al={"树林蜘蛛的卵任务","为何需要蜘蛛卵","树林蜘蛛的卵"}},{q="基尔沙兰接下来会派冒险者去哪里？",a="基尔沙兰告诉冒险者，特纳隆·雷拳正在奥达希尔最高处的房间里找他们，并派他们前往那里。",al={"特纳隆的召唤","见过基尔沙兰后找谁","树林蜘蛛的卵后续"}},{q="基尔沙兰·风行者在哪里？",a="基尔沙兰坐在奥达希尔北侧底部的石径上，就在幽影谷中央大树的中空入口外。",al={"基尔沙兰位置","风行者在哪里","寻找基尔沙兰"}},{q="泰达希尔的野生动物为什么充满攻击性？",a="泰达希尔的野生动物充满攻击性的原因尚不明确。一股疫病正沿着树根和土壤渗透，腐蚀着这些生物的心智与天性，引起了基尔沙兰等居民的担忧。",al={"蜘蛛为何发狂","泰达希尔腐化","幽影谷腐化野兽"}}},fp="20,174,22.360.0,18.361.0,21.349.1,28.154.0,38.115.0,37.199.0,43.92.0,38.139.0,45.185.0"}
P.entries["npc:gilthares-firebough"] = {n="基尔萨瑞斯·火枝",s="基尔萨瑞斯·火枝被塞拉摩俘虏，关押在北方城堡的一座高塔中。他曾在一艘往返棘齿城与藏宝海湾、运送私酿酒的船上担任水手，如今正寻找逃脱的机会。",h="基尔萨瑞斯·火枝被塞拉摩俘虏，关押在北方城堡的一座高塔中。他曾在一艘往返棘齿城与藏宝海湾、运送私酿酒的船上担任水手，如今正寻找逃脱的机会。",kw={"藏宝海湾","逃离城堡","基尔萨瑞斯·火枝","北方城堡","棘齿城","萨罗丹船队"},ang={["faction:Alliance"]="基尔萨瑞斯起初对过路者漠不关心，但对那些摧毁他的船只、将他关进牢房的联盟水手怀有强烈的敌意。",["faction:Horde"]="帮助基尔萨瑞斯逃离北方城堡，便能打击塞拉摩在贫瘠之地沿海的侵略行动。"},sec={{t="铁窗后的走私者",b="基尔萨瑞斯·火枝被关押在北方城堡的一座高塔中。他的船在棘齿城与藏宝海湾之间运送违禁货物时，被塞拉摩海军轰成了碎片。作为唯一的幸存者，基尔萨瑞斯被戴上镣铐，拖上岸关了起来。他身穿鲜红的衣服，对那些屠杀他船员的联盟狂热分子毫无好感。不过，他并不在乎是谁帮他脱身，只要对方能带他从城墙上一路杀出去。"}},faq={{q="基尔萨瑞斯·火枝是谁？",a="基尔萨瑞斯是一名隶属于萨罗丹船队的精灵水手。北方城堡的部队在贫瘠之地沿海拦截并击沉了他的商船，随后将他俘虏。",al={"基尔萨瑞斯 是谁","基尔萨瑞斯 的故事","这个精灵是谁"}},{q="他为什么被关押在北方城堡？",a="基尔萨瑞斯曾在一艘往返棘齿城与藏宝海湾、运送私酿酒的运输船上服役。塞拉摩士兵击沉了船只，杀死了其他船员，并将他作为战俘，连同违禁货物一起押往北方城堡。",al={"他为什么坐牢","为什么被关在笼子里","北方城堡 的囚犯"}},{q="基尔萨瑞斯是高等精灵还是血精灵？",a="基尔萨瑞斯是一名独立航海的精灵，既不为联盟效力，也不为银月的统治者效力。他的红色衣着常让人联想到 辛多雷，但他效力的是私掠者，而非某个国家阵营。",al={"基尔萨瑞斯 是哪种精灵","高等精灵还是血精灵","基尔萨瑞斯 的种族"}},{q="萨罗丹船队是什么组织？",a="萨罗丹船队是一个独立的海上组织，在无尽之海从事走私活动。他们的生意包括在棘齿城与藏宝海湾之间运送私酿酒，这条航线利润丰厚。",al={"萨罗丹船队","他为谁效力","基尔萨瑞斯 的船员"}}},fp="19,179,22.439.0,27.149.0,40.228.0,39.212.0,33.184.0"}
P.entries["npc:glorin-steelbrow"] = {n="戈罗林·钢眉",s="在米奈希尔港的深水旅店，戈罗林·钢眉从远方协助主教法席恩的工作。他帮助旅者在湿地海岸寻找随第三舰队一同沉没的圣物与材料，将暮色森林的困境与北方的沉船联系起来。",h="在米奈希尔港的深水旅店，戈罗林·钢眉从远方协助主教法席恩的工作。他帮助旅者在湿地海岸寻找随第三舰队一同沉没的圣物与材料，将暮色森林的困境与北方的沉船联系起来。",kw={"主教法席恩","深水旅店","被诅咒的舰队","暮色森林","帕雷斯之眼","戈罗林·钢眉","光铸铁","米奈希尔港","湿地"},ang={["class:Paladin"]="作为遵从法席恩命令的圣骑士，你可以依靠戈罗林的帮助找回Lightforge iron，这种神圣金属可用于打造受圣光祝福的武器。",["faction:Alliance"]="作为联盟的一员，你可以帮助找回在湿地近海的海难中遗失的军事遗物与祝圣材料。",["race:Dwarf"]="作为矮人，你可以看到戈罗林在米奈希尔港展现的干劲与团结精神，支援卡兹莫丹和南方人类王国各地的盟友。"},sec={{t="港口的联络",b="主教法席恩在暴风城的光明大教堂，帮助暮色森林的居民抵御步步逼近的恐怖威胁。在遥远的北方，他通过在深水旅店工作的戈罗林·钢眉，与米奈希尔港保持联系。戈罗林为受命北上寻找神圣金属与遗忘圣物的旅者提供帮助，指引方向。他的工作将南方饱受困扰的森林与湿地近海的沉船残骸联系起来。"},{t="舰队的厄运与遗失的圣物",b="戈罗林·钢眉了解第三舰队的悲剧，那些船只在湿地沿岸遭受重创，被拖入海底。他指引旅者穿过鬼魂出没的残骸，寻找遗失的光铸铁锭，以及名为帕雷斯之眼的强大诅咒神器。戈罗林知道，这些神圣军备至关重要，可以用来锻造武器，抵御威胁联盟的黑暗势力。"}},faq={{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一名在米奈希尔港深水旅店工作的矮人。他与暴风城的主教法席恩协调联络，帮助旅者在湿地近海寻找沉没的货物与圣物。",al={"戈罗林是谁","戈罗林·钢眉的故事","戈罗林做什么"}},{q="在哪里可以找到戈罗林·钢眉？",a="你可以在湿地西海岸的米奈希尔港，深水旅店一楼找到戈罗林。",al={"戈罗林的位置","戈罗林·钢眉在哪里","戈罗林 深水旅店"}},{q="米奈希尔港的矮人为什么会参与暮色森林的事务？",a="暴风城光明大教堂的主教法席恩正在寻找强大的神圣遗物与经过祝圣的金属，以对抗侵蚀暮色森林的黑暗。他派遣信任的使者前往戈罗林·钢眉那里，戈罗林熟悉湿地海岸，能够指引打捞者找到第三舰队沉没的残骸。",al={"暮色森林任务为何在湿地","与法席恩的联系","为何派往湿地"}},{q="戈罗林提到的第三舰队是什么？",a="第三舰队是一支联盟海军远征舰队，在湿地近海遭遇了灾难。破碎的船体散落在海床上，溺亡水手的鬼魂在其中徘徊，残骸中还藏着珍贵的货物，包括光铸铁和古代神器。",al={"被诅咒的舰队是什么","第三舰队 湿地","被诅咒的舰队任务"}},{q="帕雷斯之眼是什么？",a="帕雷斯之眼是一件古老的宗教圣物，曾由那支沉没的舰队运载。在戈罗林的指引下，你从海底找回它之后，祭司们必须净化沾染其上的黑暗腐化，那股力量始终萦绕在沉船周围。",al={"帕雷斯之眼","帕雷斯圣物","帕雷斯之眼是什么"}},{q="光铸铁有什么用途？",a="光铸铁是一种经过祝圣的稀有金属，可以用来打造受祝福的武器，击败强大的亡灵与恶魔势力。戈罗林帮助找回沉船中遗失的金属锭，供暮色森林的守卫者使用。",al={"光铸铁","遗失的金属锭","受祝福的武器"}}},fp="16,236,19.415.0,32.395.1,24.214.0,34.121.0,57.290.0,48.239.0,26.232.1,33.209.0"}
P.entries["npc:gnoarn"] = {n="诺恩",s="在铁炉堡，诺恩帮助流散的族人寻求援助。诺莫瑞根沦陷后，这位流亡的侏儒在侏儒区安了家，开始指引旅者去寻找其他工程师和幸存者。",h="在铁炉堡，诺恩帮助流散的族人寻求援助。诺莫瑞根沦陷后，这位流亡的侏儒在侏儒区安了家，开始指引旅者去寻找其他工程师和幸存者。",kw={"宾格斯","诺恩","侏儒爆炸头","诺莫瑞根","铁炉堡","沉默的舒尼","侏儒区"},ang={["faction:Alliance"]="身为途经铁炉堡的联盟英雄，你可以与诺恩交谈，了解侏儒在丹莫罗、洛克莫丹和暴风城开展工程活动的线索。",["race:Gnome"]="身为侏儒，你可以从诺恩维系东部王国各地流亡工程师之间联系的举动中，看到他的决心。"},sec={{t="流离失所的诺莫瑞根居民",b="穴居人入侵了诺莫瑞根，灾难性的辐射迫使居民逃离这座宏伟的地下城市。铜须矮人在侏儒区收留了诺恩。他从那里指引旅者前往联盟各地，帮助需要援助的侏儒，其中包括困在洛克莫丹的飞行员宾格斯·雷管，以及暴风城雄心勃勃的工程师沉默的舒尼。"}},faq={{q="诺恩是谁？",a="诺恩是一名侏儒幸存者，住在铁炉堡侏儒区侏儒区的难民之中。他指引旅者去帮助流亡在联盟各地的侏儒。",al={"这个侏儒是谁","诺恩背景故事","诺恩非玩家角色"}},{q="在哪里可以找到诺恩？",a="诺恩住在铁炉堡东北部的侏儒区，身边是流亡族人的机械和工作台。",al={"诺恩位置","诺恩在哪里","寻找诺恩"}},{q="诺恩会交付什么任务？",a="诺恩指引旅者去帮助四散的侏儒。他派他们前往洛克莫丹，查探失踪飞行员宾格斯·雷管的情况，或前往暴风城，与发明家沉默的舒尼谈谈她的自动旋钻挖掘机。",al={"诺恩任务","诺恩想要什么"}},{q="诺恩的头发怎么了？",a="诺莫瑞根沦陷之前，诺恩以古怪的“侏儒爆炸头”发型闻名。灾难性的放射性尘埃和泄出的辐射摧毁了这座城市，也夺走了他的头发。",al={"诺恩侏儒爆炸头","诺恩头发"}}},fx={["38923b37"]={q="诺恩效忠哪一方？",a="诺恩忠于诺莫瑞根的侏儒同胞和大联盟。他与流离失所的侏儒们一同住在侏儒区，努力维持社群的秩序，并保持与铁炉堡盟友的联系。",al={"诺恩 阵营","诺恩 是否属于联盟","诺恩 为谁效力"}},ce7102b3={q="诺恩为什么会在铁炉堡？",a="和成千上万的侏儒一样，诺恩在诺莫瑞根陷落后被迫离开家园。当穴居人占领这座地下科技奇迹、有毒辐射污染其通道时，幸存者逃向地面，在铁炉堡的矮人近亲中寻求庇护，并在侏儒区安下了家。",al={"诺恩 为何在这里","诺恩 为何来到铁炉堡","诺恩 来到铁炉堡的原因"}},["82a3a1ba"]={q="诺恩想要什么？",a="诺恩牵挂着流离失所的同胞的安危与下落。诺莫瑞根撤离后的混乱中，他寻找宾格斯等失踪的伙伴，并指引能干的冒险者去帮助沉默的舒尼等杰出的发明家和专家。",al={"诺恩 想做什么","诺恩 目标","诺恩 需要什么"}},efead32c={q="诺恩与谁有联系？",a="诺恩与铁炉堡的其他诺莫瑞根幸存者保持着密切联系，尤其负责联络著名发明家沉默的舒尼，并协调寻找宾格斯·雷管等同为难民的伙伴。",al={"诺恩 盟友","诺恩 认识谁","诺恩 关系"}}},fp="6,191,33.358.0,14.165.0,26.110.0,32.234.0,31.172.0"}
P.entries["npc:godrick-farsan"] = {n="高德瑞克·法杉",s="在幽暗城的魔法区，高德瑞克·法杉在凯伦丁·哈加尔身旁协助被遗忘者术士。他双目失明，却说自己能以另一种方式看见。",h="在幽暗城的魔法区，高德瑞克·法杉在凯伦丁·哈加尔身旁协助被遗忘者术士。他双目失明，却说自己能以另一种方式看见。",kw={"凯伦丁·哈加尔","高德瑞克·法杉","纯洁者之心","斯坦哈德·法尔杉","魅魔","幽暗城","术士"},ang={["class:Warlock"]="身为术士，你可以向高德瑞克请教，准备召唤魅魔所需的诱饵，并了解恶魔仆从吞噬成性的本性。",["race:Undead"]="身为亡灵，你可以看到高德瑞克坦然接受残破的身躯与失明的双眼，同时磨炼黑暗魔法感知，以弥补凡俗肉身的脆弱。"},sec={{t="黑暗中的双眼",b="在魔法区的召唤法阵之间，高德瑞克·法杉协助凯伦丁·哈加尔大师，指引有志修习术士之道的被遗忘者。高德瑞克双目失明，却说自己能以另一种方式看见，但并未解释其中的缘由。他考验那些寻求束缚更强大恶魔的人，派他们收集纯洁的心和精华，用于繁复的召唤仪式。"}},faq={{q="高德瑞克·法杉是谁？",a="高德瑞克·法杉是幽暗城魔法区的一名被遗忘者术士。他协助凯伦丁·哈加尔大师教导初出茅庐的术士，并指导他们进行仪式。",al={"高德瑞克·法杉","高德瑞克是谁"}},{q="高德瑞克双目失明，如何看见？",a="高德瑞克·法杉说，尽管双目失明，他仍能以另一种方式看见。他并未解释其中的缘由。",al={"高德瑞克是否失明","高德瑞克如何看见"}},{q="高德瑞克与斯坦哈德·法尔杉有亲属关系吗？",a="高德瑞克·法杉与斯坦哈德·法尔杉有着相同的姓氏，但两人之间并无已获证实的亲属关系。",al={"斯坦哈德·法尔杉的亲属关系","斯坦哈德·法尔杉的兄弟","高德瑞克与斯坦哈德是否有亲属关系"}},{q="他在术士训练中承担什么职责？",a="高德瑞克·法杉指导术士进行束缚仪式，包括获取纯洁的心，以引诱并束缚魅魔。",al={"高德瑞克术士任务","纯洁者之心任务"}}},fp="14,147,16.321.0,22.154.0,35.94.0,37.89.0,43.118.0"}
P.entries["npc:golnir-bouldertoe"] = {n="高尼尔·石趾",s="在铁炉堡的Great Forge，高尼尔·石趾为矿工和勘探者供应物资，也接收来自哨站的公文。",h="在铁炉堡的Great Forge，高尼尔·石趾为矿工和勘探者供应物资，也接收来自哨站的公文。",kw={"石趾","煤","助熔剂","高尼尔","大锻炉","铁炉堡","采矿供应商"},ang={["profession:Mining"]="Great Forge的矿工依靠高尼尔供应采矿所需的工具和材料，包括备用矿工锄，以及将矿脉中开采的原矿熔炼成金属锭所需的助熔剂。",["race:Dwarf"]="对于初次前往寒脊或卡拉诺斯冒险归来的矮人来说，高尼尔是他们在都城最早接触的人之一。他在山腹炽热的核心旁迎接旅人。"},sec={{t="Great Forge的商人",b="高尼尔·石趾在铁炉堡的Great Forge为勘探者和工匠供应装备。他出售矿工锄、助熔剂和煤，供这座矮人都城的熔炉和铁匠铺使用。高尼尔是吉尔弗拉姆·石趾的亲属，也是进城工人信赖的接洽人。他指引新手，也接收附近哨站的物资消息。"}},faq={{q="在哪里能找到高尼尔·石趾？",a="高尼尔·石趾在铁炉堡的大锻炉工作，与其他贸易商人一起，位于中央熔炼区和锻造区附近。",al={"高尼尔位置","高尼尔在哪里","高尼尔·石趾 铁炉堡"}},{q="高尼尔出售哪些货物？",a="高尼尔向开采和提炼原矿的勘探者出售矿工锄、煤和助熔剂。",al={"高尼尔出售的货物","高尼尔卖什么","高尼尔商品"}},{q="高尼尔·石趾与什么任务有关吗？",a="有。信使将附近矮人定居点的消息送往都城。旅人会将塞尔萨玛等哨站的公文直接交给高尼尔，其中包括与格莱斯·瑟登及抵达航班有关的消息。",al={"高尼尔任务","飞往铁炉堡 高尼尔"}},{q="高尼尔在丹莫罗还有其他亲属吗？",a="高尼尔与吉尔弗拉姆·石趾同属一个氏族，后者是一名采矿训练师，就在他身旁的铁炉堡大锻炉工作。",al={"石趾家族","吉尔弗拉姆·石趾亲属"}}},fx={["5f6dd933"]={q="高尼尔·石趾是谁？",a="高尼尔·石趾是一名矮人商人，在铁炉堡的大锻炉经营采矿用品。他为在这座城市熔火之心劳作的勘探者和铁匠提供必需的补给、矿镐及熔炼用品。",al={"高尼尔 是谁","高尼尔·石趾 背景故事","高尼尔 身份"}},b602f757={q="高尼尔·石趾效忠哪一方？",a="高尼尔是铁炉堡和铜须氏族的忠诚臣民，坚定地支持大联盟。他在王国繁忙的中心经营生意，为矮人同胞和来访的联盟旅人提供服务。",al={"高尼尔 阵营","高尼尔 效忠对象","高尼尔 属于哪一方"}},["7131f874"]={q="高尼尔·石趾为什么会在这里？",a="高尼尔守在大锻炉附近，那里炉火不熄，矿石日夜熔炼。来自丹莫罗及更远地方的矿工和铁匠会将收获直接带到铁炉堡的中央熔炉，因此高尼尔将店铺设在附近，为他们配备必要的工具。",al={"高尼尔 为何在铁炉堡","高尼尔 在大锻炉的职责","高尼尔 为何在这里"}}},fp="17,116,27.339.0,35.129.0,28.84.0,44.221.0,47.118.0"}
P.entries["npc:gorbold-steelhand"] = {n="高尔博德·钢手",s="在奥伯丁，高尔博德·钢手维系着黑海岸沿岸的贸易往来。这位矮人商人从遥远的无尽之海彼岸运来货物，供旅人、工匠和暗夜精灵选购。",h="在奥伯丁，高尔博德·钢手维系着黑海岸沿岸的贸易往来。这位矮人商人从遥远的无尽之海彼岸运来货物，供旅人、工匠和暗夜精灵选购。",kw={"奥伯丁","黑海岸","深不可测的海洋","高尔博德","铁炉堡","商人","钢手","商贩"},ang={["faction:Alliance"]="身为联盟的一员，你能看到高尔博德·钢手帮助来自东方的联盟种族和暗夜精灵维持跨越无尽之海的贸易往来。",["race:Dwarf"]="身为矮人，在黑海岸雾气弥漫、夜色笼罩的环境中看到高尔博德·钢手，或许会让你想起铁炉堡的家。"},sec={{t="卡利姆多的矮人商人",b="高尔博德·钢手将铁炉堡的贸易带到了奥伯丁。暗夜精灵遍布卡利姆多北部的大部分地区，因此联盟哨站依赖跨越无尽之海的商人。高尔博德与卡多雷一起工作，出售商用品、施法材料、制造材料和工具。旅人在准备探索黑海岸危机四伏的海滨与森林时，会来他这里采购。"},{t="海上生意",b="高尔博德·钢手关注奥伯丁外海的险恶水域，就像关注自己的存货一样。黑海岸沿岸的暗礁吞没过联盟船只，那些遗失的货物引起了这位商人的兴趣。潜入深海的旅人或许会发现，他很想听听沉船中可打捞的货物和遗失航海日志的消息。"}},faq={{q="高尔博德·钢手是谁？",a="高尔博德·钢手是奥伯丁的一名矮人商人，奥伯丁是黑海岸的沿海港口。",al={"高尔博德","高尔博德·钢手是谁","奥伯丁的矮人"}},{q="高尔博德·钢手出售什么？",a="高尔博德·钢手为途经奥伯丁的手艺人出售一般商用品、制造材料、采集工具，以及瓶子和线等材料。",al={"高尔博德出售什么","高尔博德商用品","高尔博德商品列表"}},{q="为什么一名铁炉堡矮人会住在黑海岸？",a="奥伯丁是连接卡利姆多与东部王国的联盟交通枢纽。矮人前往那里经商、探索，并支援暗夜精灵盟友的行动。",al={"为什么这里有矮人","高尔博德为什么在黑海岸","奥伯丁的铁炉堡商贸"}},{q="高尔博德提供任务吗？",a="是的。高尔博德·钢手会在“深不可测的海洋, 深不可测的海洋”任务中指引冒险者，从黑海岸外海的沉船残骸中找回遗失的船货。",al={"高尔博德任务","深不可测的海洋任务发布者"}}},fp="17,174,28.351.0,17.299.0,25.81.0,33.157.0,46.168.0,30.122.0"}
P.entries["npc:gordon-wendham"] = {n="高顿·温德哈姆",s="在幽暗城的贸易区，高顿·温德哈姆出售武器，也为来自地表的信使指路。",h="在幽暗城的贸易区，高顿·温德哈姆出售武器，也为来自地表的信使指路。",kw={"被遗忘者","高顿·温德哈姆","迈克尔·加勒特","贸易区","幽暗城","武器商人"},ang={["class:Warrior"]="身为战士，你可以从高顿·温德哈姆那里购买可靠的基础刀剑和钝器，在主城中练习武器技能。",["race:Undead"]="身为刚从丧钟镇获得自由的被遗忘者，你可以在贸易区找到高顿·温德哈姆这样的商人，为这个年轻国度的战事提供补给。"},sec={{t="贸易区的军备",b="高顿·温德哈姆向为被遗忘者而战的人出售武器。他的货品从匕首、手斧到阔剑、钉锤，一应俱全。初出茅庐的战士在踏入洛丹伦那些争夺不休的地区之前，可以在这里找到可靠的兵器。"},{t="信使的目的地",b="飞行管理员和信使派出的旅人，往往会被指引到高顿·温德哈姆的摊位。有些人从废墟顶上的蝙蝠管理员那里前来。他的摊位位于贸易区，旅人需要补给，或要携带公文穿过这座地下城市时，很容易找到他。"}},faq={{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆在幽暗城的贸易区出售武器，也帮助从地表前来的信使。",al={"高顿·温德哈姆背景故事","温德哈姆是谁","幽暗城高顿"}},{q="高顿·温德哈姆在哪里？",a="你可以在幽暗城地下大厅的贸易区找到高顿·温德哈姆，他就在自己的武器摊位旁。",al={"高顿·温德哈姆位置","幽暗城高顿在哪","贸易区武器商人"}},{q="他出售什么？",a="他出售基础武器，包括剑、匕首、钉锤、法杖、斧和投掷武器。",al={"温德哈姆货品","高顿卖什么","高顿·温德哈姆武器"}},{q="哪些任务与他有关？",a="高顿·温德哈姆接收来自地表蝙蝠栖息地的货物，其中也有蝙蝠管理员迈克尔·加勒特送来的货物。",al={"高顿·温德哈姆任务","乘坐飞行坐骑前往幽暗城","迈克尔·加勒特任务"}}},fp="14,100,30.235.0,23.273.0,22.107.0,32.111.0,18.91.0,24.118.0"}
P.entries["npc:gornek"] = {n="高内克",s="在杜隆塔尔的试炼谷，高内克负责接待兽人和黑暗之矛巨魔新兵。他接待那些准备向新部落证明自身价值的人。",h="在杜隆塔尔的试炼谷，高内克负责接待兽人和黑暗之矛巨魔新兵。他接待那些准备向新部落证明自身价值的人。",kw={"大兽穴","杜隆塔尔","高内克","羊皮纸","新部落","试炼谷"},ang={["race:Orc"]="对年轻的兽人而言，向高内克报到，是告别童年、在杜隆塔尔赢得光荣地位的第一步。",["race:Troll"]="作为受萨尔庇护的盟友，黑暗之矛巨魔向高内克呈交凭证，证明自己有能力与兽人兄弟平等并肩。"},sec={{t="迎接未经考验者",b="在试炼谷，高内克让部落的新兵接受首次纪律考验。大酋长萨尔的命令很明确：每个年轻人和新来者都必须凭借勇气与毅力赢得一席之地。高内克评估进入山谷的人，阅读他们的引荐指令，并指引他们去寻找营地各处的训练师。无论新兵带来的是加密的便笺、刻有雕文的羊皮纸，还是普通石板，高内克都会收下这些凭证，让他们踏上严酷的求生之路。"},{t="为杜隆塔尔效力的一生",b="谷中干旱的峡谷既考验战斗技巧，也教导新兵如何在新部落中共同生活。高内克不让初来者漫无目的地逗留，指引他们前往附近的蝎子洞穴、野猪巢穴，以及经验丰富的教官那里。那些在训练场上活下来，并消灭红岩沟壑中威胁的人，会得到高内克最后的认可，随后被派往杜隆塔尔更广阔、更危险的土地。"}},faq={{q="高内克是谁？",a="高内克是一名兽人，负责在试炼谷接待和督导部落新兵。他阅读新兵的入伍文书，并指引他们前往各自的职业训练师那里。",al={"高内克","这个兽人是谁","高内克是谁"}},{q="在哪里可以找到高内克？",a="高内克位于杜隆塔尔西南部的试炼谷，站在山谷中央附近的大兽穴内，年轻的兽人和黑暗之矛巨魔正是从这里踏上旅程。",al={"高内克位置","高内克在哪里","高内克地图"}},{q="新兵为什么要向他报到？",a="新来者带来的训练卷轴和石板上，写明了他们选择的修习之道。高内克审阅这些介绍信，确认他们的资格，再将他们派往谷中相应的导师那里。",al={"为什么拜访高内克","羊皮纸任务","石板任务"}},{q="他在新部落中担任什么职责？",a="高内克负责协调加入萨尔的新部落的事宜。他确保新兵在踏入杜隆塔尔更广阔的土地之前，学会有关荣誉、生存和战备的基本准则。",al={"高内克在部落中的职责","高内克做什么"}}},fp="6,126,22.459.0,28.387.0,14.172.0,24.153.0,34.207.0,34.157.0"}
P.entries["npc:gramma-stonefield"] = {n="米莱德·斯通菲尔德",s="在艾尔文的斯通菲尔德农场，米莱德·斯通菲尔德正默默设法缓和家族间的争端。",h="在艾尔文的斯通菲尔德农场，米莱德·斯通菲尔德正默默设法缓和家族间的争端。",kw={"艾尔文","米莱德·斯通菲尔德","马科伦","梅贝尔","米尔德里德","斯通菲尔德农场","汤米·乔","威廉·匹斯特"},ang={["faction:Alliance"]="作为一名联盟旅人，你能看到，腹地的地方纷争也需要不动声色的斡旋与体谅。"},sec={{t="暗中的调解者",b="几十年来，斯通菲尔德和马科伦家族两家隔着道路争吵不休。米莱德·斯通菲尔德是家族中最年长的在世成员，她认为两家的对立既无意义，又有害处。因此，当她的孙子托米·乔·斯通菲尔德爱上梅贝尔·马科伦时，她选择了体谅，而非对家族的忠诚。她向闪金镇的老朋友威廉·匹斯特求助，悄悄筹划，让这对恋人能在两家农场的敌意中秘密相会。"}},faq={{q="米莱德·斯通菲尔德是谁？",a="米莱德·斯通菲尔德的名字是米莱德，是艾尔文森林农场里斯通菲尔德家族年迈的女家长。她是托米·乔·斯通菲尔德的祖母。",al={"奶奶是谁","米莱德·斯通菲尔德","斯通菲尔德祖母"}},{q="她如何看待与马科伦家族家族的争端？",a="米莱德不愿卷入与马科伦家族家族的争端。她认为这种积怨既愚蠢又有害，宁愿两家和睦相处，也不愿他们继续争吵。",al={"斯通菲尔德与马科伦的争端","她恨马科伦家族吗"}},{q="她为什么帮助托米·乔和梅贝尔？",a="米莱德疼爱她的孙子托米·乔，希望他能幸福。她不认同家族间的争端，请老朋友威廉·匹斯特为托米·乔与梅贝尔·马科伦的恋情想个办法。",al={"为何帮助托米·乔","奶奶的爱情药水","帮助恋人"}},{q="威廉·匹斯特与她是什么关系？",a="威廉·匹斯特是米莱德·斯通菲尔德信任的老朋友。他住在闪金镇的狮王之傲旅店，是一名炼金师。她派可信的信使去找他，为托米·乔寻求药剂和其他帮助。",al={"威廉·匹斯特的关系","威廉·匹斯特与奶奶"}}},fx={d471da09={q="米莱德·斯通菲尔德为什么会在这里？",a="这间小屋是她一生的家。作为斯通菲尔德家族的女家长和在世最年长的成员，米尔德丽德就住在艾尔文森林的家族农庄里，默默照看着亲人，努力防止他们之间的小小争斗毁掉年轻人的生命。",al={"米莱德·斯通菲尔德 为何在农场","斯通菲尔德农场 米莱德·斯通菲尔德 位置","米莱德·斯通菲尔德 为何在这里"}}},fp="17,88,19.454.0,25.172.0,51.165.0,41.197.0,29.222.0"}
P.entries["npc:grand-mason-marblesten"] = {n="大石匠玛布勒斯坦",s="在铁炉堡的平民区，玛布勒斯坦正筹备一座纪念碑，向苏利·巴鲁致敬。国王麦格尼·铜须委托他建造这座纪念碑，纪念这位在萨多尔大桥惨剧中丧生的矮人士兵。玛布勒斯坦正在寻找配得上这项工程的石材。",h="在铁炉堡的平民区，玛布勒斯坦正筹备一座纪念碑，向苏利·巴鲁致敬。国王麦格尼·铜须委托他建造这座纪念碑，纪念这位在萨多尔大桥惨剧中丧生的矮人士兵。玛布勒斯坦正在寻找配得上这项工程的石材。",kw={"国王的礼物","铜须","平民区","大石匠","铁炉堡","麦格尼","玛布勒斯坦","石匠","苏利·巴鲁"},ang={["faction:Alliance"]="对联盟而言，苏利·巴鲁的牺牲让人想起那些在联盟历次战争中阵亡的士兵。",["profession:Mining"]="在丹莫罗及更远地区开采矿石的矿工，都知道玛布勒斯坦对原石品质有多么用心。",["race:Dwarf"]="对矮人而言，石工技艺是祖先留下的传承。帮助玛布勒斯坦，便是向卡兹莫丹的工艺与苏利·巴鲁的英灵致敬。"},sec={{t="石雕大师",b="大石匠玛布勒斯坦负责铁炉堡平民区的公共工程与纪念碑建造。矮人石匠在山体中凿出大厅、石柱和宏伟的雕像，传承着延续数百年的古老技艺。玛布勒斯坦是城中最杰出的雕刻大师之一。他以自己的作品保存着铜须一族的历史。"},{t="国王的敬意",b="麦格尼国王委托玛布勒斯坦建造一座纪念碑，纪念在萨多尔大桥惨剧中丧生的士兵苏利·巴鲁。这座纪念碑向巴鲁和他悲痛的遗孀致以敬意。为了让这份敬意长存，玛布勒斯坦正在寻找品质最上乘的石材之一，奥特兰克花岗岩。他请旅人从希尔斯布莱德的达隆山带回这种石材。"}},faq={{q="大石匠玛布勒斯坦是谁？",a="大石匠玛布勒斯坦是铁炉堡平民区的一位资深矮人石匠。他负责公共与王室的雕刻工程，其中包括国王麦格尼·铜须委托建造的苏利·巴鲁纪念碑。",al={"玛布勒斯坦是谁","玛布勒斯坦的职责","大石匠非玩家角色"}},{q="在哪里可以找到大石匠玛布勒斯坦？",a="你可以在铁炉堡的平民区找到大石匠玛布勒斯坦。他就在城中商店和银行附近的石料与建筑工程之间。",al={"玛布勒斯坦的位置","玛布勒斯坦在哪里","铁炉堡玛布勒斯坦"}},{q="玛布勒斯坦正在建造什么纪念碑？",a="玛布勒斯坦正在为苏利·巴鲁建造纪念碑，这位矮人士兵在萨多尔大桥惨剧中丧生。国王麦格尼·铜须委托建造这座纪念碑，向巴鲁和他悲痛的遗孀致以敬意。",al={"他在建造什么","国王的礼物任务","玛布勒斯坦雕像"}},{q="玛布勒斯坦为什么需要冒险者收集材料？",a="玛布勒斯坦正在寻找品质最上乘的石材之一，用来建造一座长存的纪念碑。他派旅人前往希尔斯布莱德的达隆山，采集奥特兰克花岗岩。",al={"玛布勒斯坦的任务","为什么需要石材","纪念碑材料"}},{q="在矮人社会中，“大石匠”这个头衔意味着什么？",a="在矮人之中，大石匠是精通石工技艺的大师，受托承担重大王国工程、王室建筑设计和礼仪性纪念碑的建造。石工技艺与锻造同样受到尊崇。",al={"什么是大石匠","矮人石匠等级"}},{q="玛布勒斯坦是联盟官员，还是私人承包商？",a="玛布勒斯坦在铁炉堡为王国和联盟效力。他与国王麦格尼·铜须的宫廷协调，承办王室委托的工程。",al={"玛布勒斯坦为谁效力","玛布勒斯坦的阵营"}}},fx={a77cb24b={q="大石匠玛布勒斯坦效忠哪一方？",a="玛布勒斯坦对铁炉堡和联盟忠心耿耿。他驻守在城中平民区的中心，为国王麦格尼·铜须和矮人王国效力，以自己的技艺和石工作品致敬矮人的传承与王座。",al={"玛布勒斯坦阵营","玛布勒斯坦为谁效力","玛布勒斯坦联盟"}},["1dc5a337"]={q="大石匠玛布勒斯坦想要什么？",a="玛布勒斯坦正在督造一座皇家纪念碑，需要上好的材料才能将其完工。在“国王的礼物”任务中，他希望能干的冒险者帮忙收集必要的物资，用来建造麦格尼国王下令修建的纪念碑，悼念阵亡士兵苏利·巴鲁。",al={"玛布勒斯坦想要什么","玛布勒斯坦目标","玛布勒斯坦为何需要帮助"}},["98aae54f"]={q="大石匠玛布勒斯坦为什么在平民区？",a="玛布勒斯坦将工坊设在铁炉堡繁忙的平民区，以便监督这座宏伟山中要塞的石工工程，并为王室组织施工。开阔的广场便于他协调工程，也方便他招募途经城中的旅人。",al={"玛布勒斯坦为何在铁炉堡","玛布勒斯坦为何在这里","玛布勒斯坦 平民区 铁炉堡"}}},fp="22,225,19.334.0,16.330.0,30.203.0,40.135.0,39.185.0,57.139.0,58.193.0,59.140.0"}
P.entries["npc:granis-swiftaxe"] = {n="格兰尼斯·快斧",s="在卡拉诺斯的雷酒酿制厂，格兰尼斯·快斧训练着从寒脊山小径而来的年轻联盟战士。他为他们穿越丹莫罗的旅程做好准备，再将经验丰富的战士送往铁炉堡。",h="在卡拉诺斯的雷酒酿制厂，格兰尼斯·快斧训练着从寒脊山小径而来的年轻联盟战士。他为他们穿越丹莫罗的旅程做好准备，再将经验丰富的战士送往铁炉堡。",kw={"丹莫罗","格兰尼斯·快斧","卡拉诺斯","穆伦·雷矛","雷酒酿制厂","战士训练师"},ang={["class:Warrior"]="作为一名刚离开寒脊山谷的矮人或侏儒战士，你可以在雷酒酿制厂向格兰尼斯学习基础战斗技巧。",["race:Dwarf"]="作为一名矮人，你会在当地麦酒带来的惬意之中，感受到格兰尼斯那份固执的骄傲和习武的严谨。"},sec={{t="卡拉诺斯的严厉导师",b="格兰尼斯·快斧在雷酒酿制厂训练穿行于丹莫罗、寻求指导的年轻战士。他以战士之道为荣，其他职业的人试图引起他的注意时，他总觉得好笑。学生在战斗中证明自己的本领后，格兰尼斯便让他们沿山路前往铁炉堡的军事区，向训练大师穆伦·雷矛求教。"}},faq={{q="格兰尼斯·快斧是谁？",a="格兰尼斯·快斧在卡拉诺斯的雷酒酿制厂一楼训练年轻的矮人和侏儒战士。他教给他们穿越丹莫罗所需的基本战斗技巧。",al={"格兰尼斯·快斧","格兰尼斯是谁","卡拉诺斯战士训练师"}},{q="格兰尼斯为什么嘲笑我的角色？",a="格兰尼斯对不走战士之道的人没什么耐心。其他职业的人与他交谈时，他会嗤笑道，他们在他的训练下连一天都撑不过去。",al={"格兰尼斯无礼台词","格兰尼斯为什么嘲笑我","格兰尼斯对非战士的台词"}},{q="格兰尼斯会让有所长进的战士去哪里？",a="当战士在丹莫罗积累了足够的经验后，格兰尼斯便会让他们去找穆伦·雷矛，一位在铁炉堡军事区任教的资深战士训练师。",al={"穆伦 雷矛任务","格兰尼斯任务线","格兰尼斯让人去找谁"}},{q="格兰尼斯与卡兹莫丹其他姓快斧的人有亲属关系吗？",a="格兰尼斯与其他一些矮人同姓快斧，但他们之间的亲属关系尚未得到证实。",al={"快斧家族","格兰尼斯·快斧的亲属"}}},fx={b8e95117={q="格兰尼斯·快斧效忠哪一方？",a="格兰尼斯坚定地支持铁炉堡的矮人以及整个联盟。他驻守卡拉诺斯，凭借自己的战斗经验训练新一代守卫，抵御丹莫罗周围的穴居人、冰霜巨魔和其他威胁。",al={"格兰尼斯·快斧阵营","格兰尼斯为谁而战","格兰尼斯联盟"}},["760b1803"]={q="格兰尼斯·快斧为什么在卡拉诺斯？",a="格兰尼斯驻守在卡拉诺斯的雷酒酿制厂内，训练从寒脊山小径出发的联盟战士新兵。丹莫罗面临当地穴居人和雪怪日益加剧的威胁，因此他严格的战斗训练对当地防务至关重要。",al={"格兰尼斯为何在这里","格兰尼斯·快斧所在地原因","格兰尼斯为何来到卡拉诺斯"}},cf3183bb={q="格兰尼斯·快斧想要什么？",a="格兰尼斯要的是身经百战、纪律严明，能够为卡兹莫丹坚守阵线的战士。他对弱者或缺乏训练的人没什么耐心，要求新兵坚持不懈地投入训练，之后才会指引有潜力的老兵去铁炉堡，向穆伦·雷矛这样的师傅求教。",al={"格兰尼斯·快斧目标","格兰尼斯想要什么","格兰尼斯目的"}}},fp="15,202,26.373.0,23.201.0,34.185.0,42.153.0,51.95.0"}
P.entries["npc:great-father-winter"] = {n="冬天爷爷",s="冬幕节期间，冬天爷爷在奥格瑞玛倾听孩子们的心愿。他受雇于烟林牧场，在力量谷的索尔的堡垒附近带来节日的欢乐，不过这份工作也让他疲惫不堪。",h="冬幕节期间，冬天爷爷在奥格瑞玛倾听孩子们的心愿。他受雇于烟林牧场，在力量谷的索尔的堡垒附近带来节日的欢乐，不过这份工作也让他疲惫不堪。",kw={"姜饼","冬天爷爷","奥格瑞玛","冬幕节","力量谷"},ang={["faction:Horde"]="对部落而言，他是奥格瑞玛的节日代表，为烟林牧场发放节日礼物和任务。",["profession:Cooking"]="厨师可以用节日食谱烤制姜饼，再带上牛奶一起送给冬天爷爷，让他重新振作。",["race:Orc"]="身为兽人，看到自己的同胞沦为穿着戏服、兜售商家折扣的吉祥物，难免会让恪守传统者失去耐心，尽管兽人敬重四季更迭与元素。"},sec={{t="受雇扮演的传说",b="力量谷的冬天爷爷是一名兽人演员，受雇于烟林牧场商贸公司。古老的传说讲述了一位威严的元素之灵，他游历大地，带来白雪与四季更迭，但奥格瑞玛的这位冬天爷爷却在推销公司的商品，逗部落的孩子们开心。一些批评者认为，这个商业吉祥物贬低了真正的时令传统。不过，几乎没人否认他为城市街头带来的节日热闹。"},{t="力量谷的轮班工作",b="冬天爷爷在索尔的堡垒外装饰一新的常青树下工作。孩子们爬上他的膝头，告诉他自己想要什么礼物，而他则宣传烟林牧场的折扣，送上节日问候。漫长的轮班让他精疲力竭。他承认，自己在背包里备了节日美酒，好在收工后借酒消解喧嚣，而前来的冒险者会带些零食，帮他撑下去。"}},faq={{q="这是真正的冬天爷爷吗？",a="不是。他是一名受雇于烟林牧场的普通兽人，装扮成传说中的冬幕节人物，在奥格瑞玛派发节日促销信息。",al={"他是真的吗","冬天爷爷是谁","他是演员吗"}},{q="在奥格瑞玛哪里能找到冬天爷爷？",a="冬天爷爷就在力量谷的索尔的堡垒外，冬幕节的树和节日摊位旁。",al={"冬天爷爷位置","冬天爷爷在哪里","冬天兽人在哪里"}},{q="他在冬幕节期间做些什么？",a="他招待欢度节日的人们，倾听孩子们想要什么礼物，发放烟林牧场的促销任务，并在节日最热闹的时候于树下派发节日礼物。",al={"他做什么","冬天爷爷的作用","冬幕节任务"}},{q="他为什么想要姜饼和牛奶？",a="喧闹的人群和轮流坐上他膝头的孩子们让他疲惫不堪。他索要姜饼和牛奶，好补充体力，撑到收工。",al={"给冬天爷爷的点心","为什么要牛奶和饼干","姜饼任务"}},{q="他怎么看待自己的工作？",a="在他看来，这场表演既乏味又累人。他抱怨那些满怀期待的孩子，匆匆念完公司的宣传口号，一分一秒地盼着收工，好喝上包里那瓶助兴的酒。",al={"他喜欢自己的工作吗","冬天爷爷台词","他喝醉了吗"}},{q="联盟也有类似的人物吗？",a="有。联盟的冬天爷爷是一位受雇于烟林牧场的年迈矮人，就在铁炉堡 平民区 的节日树旁。",al={"联盟冬天爷爷","铁炉堡 圣诞老人","联盟对应人物"}}},fp="19,189,12.411.0,36.399.0,36.138.0,50.132.0,48.188.0,46.153.0,30.193.0,44.150.0"}
P.entries["npc:greatfather-winter"] = {n="冬天爷爷",s="冬日流转，冬天爷爷的身影既在古老的传说中，也在城中的庆典里。有人说，他为艾泽拉斯铺上白雪，让大地得以休憩，重焕生机。在城里，烟林牧场的地精塑造了人们熟悉的冬天爷爷形象。",h="冬日流转，冬天爷爷的身影既在古老的传说中，也在城中的庆典里。有人说，他为艾泽拉斯铺上白雪，让大地得以休憩，重焕生机。在城里，烟林牧场的地精塑造了人们熟悉的冬天爷爷形象。",kw={"丹莫罗","姜饼","冬天爷爷","铁炉堡","奥格瑞玛","冬幕节"},ang={["profession:Cooking"]="身为厨师，你可以为烟林牧场和冬天爷爷本人制作姜饼及其他节日美食。",["race:Dwarf"]="身为矮人，你可以将冬天爷爷视为塑造世界的泰坦的化身。丹莫罗白雪皑皑的山峰，见证着他留下的痕迹。"},sec={{t="神话与新生",b="古老的传说讲述，冬天爷爷会在岁末漫游世界。他展开白雪织成的斗篷，自然便沉入梦乡，静待新生。矮人称他为泰坦的化身或使者。他们认为，丹莫罗覆满冰霜的峭壁就是他眷顾此地的证明。牛头人尊重他在冬日流转中的地位，但认为是太阳与月亮带来了严寒和风暴，让Earth Mother得以休憩。\n\n各地的人们聚在一起，以盛宴抵御严寒。他们坚信，生命终将归来。"},{t="烟林牧场与城中庆典",b="在铁炉堡和奥格瑞玛，烟林牧场的地精为城中的庆典重塑了这位古老精灵的形象。这家贸易公司让冬天爷爷的形象广为人知：一位身穿红衣、蓄着白胡子的欢乐长者，驾着飞行雪橇，带来节日美食和玩具。\n\n烟林牧场在铁炉堡雇用一名矮人，在奥格瑞玛雇用一名兽人，听孩子们诉说心愿，并收下牛奶和姜饼。在装饰华丽的树下，这家公司也推销着应季商品。"}},faq={{q="铁炉堡的冬天爷爷是真正的精灵吗？",a="铁炉堡节日树旁的冬天爷爷，是烟林牧场雇来的演员。这家地精公司安排这些亮相，让孩子们开心，也借此售卖节日糖点。古老的传说则讲述着一位在冬日行走于世间的缥缈存在。",al={"冬天爷爷是真的吗","铁炉堡那个人是谁","他是演员吗"}},{q="矮人为何敬重冬天爷爷？",a="矮人将冬天爷爷与创造了他们的泰坦联系在一起。他们视他铺下的白雪为祝福，并认为丹莫罗终年严寒的山峰就是他眷顾此地的证明。",al={"矮人冬幕节","矮人的冬天爷爷","铁炉堡冬天爷爷"}},{q="冬天爷爷会如何享用人们送来的饼干和牛奶？",a="在烟林牧场的节日故事里，冬天爷爷一边吃着姜饼、喝着冰镇牛奶，一边阅读心愿清单，传递节日的欢乐。",al={"给冬天爷爷的美食","为什么要牛奶和饼干","姜饼任务"}},{q="部落如何看待冬天爷爷？",a="在奥格瑞玛，烟林牧场让一名兽人扮演冬天爷爷，为庆典招徕人气。牛头人敬重冬季，视其为大地母亲休憩并重焕生机的时节。他们尊重他在季节轮回中所起的作用，但并不崇拜泰坦。",al={"部落冬天爷爷","奥格瑞玛冬天爷爷","牛头人冬幕节"}}},fx={["66677a0e"]={q="冬天爷爷效忠哪一方？",a="他不属于任何一方阵营。传说中，冬天爷爷是一股古老而超自然的自然之力，为整个世界带来季节的新生与丰饶，不受凡人效忠对象的影响。你在铁炉堡看到的那位冬天爷爷，由地精贸易公司烟林牧场赞助，这家公司严格保持中立，以盈利为目的经营。事实上，烟林牧场还雇了一位兽人扮演者，让他同时坐镇奥格瑞玛，向部落传播节日欢乐。",al={"冬天爷爷属于联盟还是部落","冬天爷爷属于联盟吗","冬天爷爷阵营"}},a8f1de98={q="冬天爷爷想要什么？",a="神话中的古老精灵只希望让寒冬笼罩世界，给予大地休养、生息并最终焕然一新所需的时间，同时为欢迎他的人赐下丰饶。然而，你在铁炉堡遇到的凡人扮演者受雇于烟林牧场。他们的目标完全围绕节日庆典与商业经营：传播欢乐，给乖孩子分发美食，并让节日商品和玩具热销。",al={"冬天爷爷动机","冬天爷爷想要什么","冬天爷爷为何送礼物"}},daa32740={q="冬天爷爷为什么在铁炉堡？",a="烟林牧场将他安排在冬幕节树旁，主持他们的节日庆典。在节日到来前的几周里，这位快活的老人会与市民和孩子们见面，倾听他们的节日心愿，收取信件，并与地精助手们一同传递善意，同时帮助烟林牧场推销应季商品。",al={"冬天爷爷为何在铁炉堡","冬天爷爷为何在这里","冬天爷爷位置 铁炉堡"}},["8b922b4d"]={q="冬天爷爷与谁有关联？",a="矮人的传统将这位古老精灵与泰坦紧密相连，认为他体现了泰坦塑造艾泽拉斯四季的力量。而在日常庆典中，城里那位冬天爷爷则与烟林牧场合作，身边围着他们个头小巧的小助手和节日雪人。",al={"冬天爷爷与谁有关联","冬天爷爷的关联","谁与冬天爷爷共事"}}},fp="18,220,16.501.0,39.484.0,55.259.0,41.184.0,73.157.0,43.246.0"}
P.entries["npc:greatmother-hawkwind"] = {n="鹰风酋长的母亲",s="在红云台地的水井旁，鹰风酋长的母亲指引着年轻的牛头人。她是纳拉其营地领袖鹰风酋长的母亲，虽已年迈，仍坚守着部族共同承担的责任。",h="在红云台地的水井旁，鹰风酋长的母亲指引着年轻的牛头人。她是纳拉其营地领袖鹰风酋长的母亲，虽已年迈，仍坚守着部族共同承担的责任。",kw={"一件琐事","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷","红云台地","牛头人长者"},ang={["race:Tauren"]="作为一名在红云台地踏上旅途的年轻牛头人，你能从鹰风酋长的母亲身上看到Earth Mother的信念：尊敬长者，与群体团结一心，谦逊地为他人效劳。"},sec={{t="台地的长者",b="鹰风酋长的母亲每天都在纳拉其营地的清水井旁，指引刚开始接受成年仪式考验的年轻牛头人。岁月让她步履迟缓，但她依然参与村中的事务。她相信，无论老幼，每个部族成员都必须为维系群体的生活出力。她常请年轻的牛头人打水，帮忙做些简单的杂务。"},{t="母亲的指引",b="鹰风酋长的母亲是纳拉其营地领袖鹰风酋长的母亲。红云台地面临威胁时，她会提出忠告。她的儿子组织猎人和战士，对抗刺背野猪人和当地的掠食野兽。她守护着聚落的精神支柱，提醒初醒者，力量始于谦逊和为族人效劳。"}},faq={{q="鹰风酋长的母亲是谁？",a="鹰风酋长的母亲是红云台地纳拉其营地的一位年迈的牛头人女族长。她是鹰风酋长的母亲，也指引着年轻的牛头人。",al={"鹰风酋长的母亲的故事","鹰风酋长的母亲是谁","纳拉其营地长者"}},{q="在哪里能找到她？",a="她坐在纳拉其营地东南方的水井旁，那里位于莫高雷西南部的红云台地。",al={"鹰风酋长的母亲的位置","鹰风酋长的母亲在哪里"}},{q="她会请年轻的牛头人做些什么？",a="鹰风酋长的母亲会请年轻的牛头人从村中的水井打水，送给营地里的其他人。这项杂务教导他们，真正为部族效劳的人不会轻视任何工作。",al={"鹰风酋长的母亲的任务","一件小事"}},{q="她与鹰风酋长是什么关系？",a="鹰风酋长的母亲是鹰风酋长的母亲，他负责纳拉其营地的防御事务和年轻勇士的训练。",al={"鹰风酋长的母亲","她与鹰风酋长有亲属关系吗"}}},fp="20,160,17.375.0,19.339.0,28.147.0,23.100.0,40.185.0,39.124.0"}
P.entries["npc:grelin-whitebeard"] = {n="格瑞林·白须",s="在寒脊山谷，格瑞林·白须奉国王之命监视霜鬃的威胁。铁炉堡正忙于对抗穴居人，因此，他那孤立的营地只能依靠当地新兵。",h="在寒脊山谷，格瑞林·白须奉国王之命监视霜鬃的威胁。铁炉堡正忙于对抗穴居人，因此，他那孤立的营地只能依靠当地新兵。",kw={"寒脊山谷","丹莫罗","霜鬃","格瑞林·白须","格瑞克尼尔","铁炉堡参议院","森内尔·白须","被盗的日志"},ang={["faction:Alliance"]="身为联盟的一员，你能看出联盟和铁炉堡的部队在丹莫罗各地已捉襟见肘。像格瑞林这样的斥候面对巨魔时，几乎得不到支援。",["race:Dwarf"]="身为矮人，你看到格瑞林为国王麦格尼效力，抵御铁炉堡势力所及之处的威胁，守卫丹莫罗的边境。",["race:Gnome"]="身为刚从诺莫瑞根的灾难中逃来的侏儒，你或许会发现，只要有人能帮忙对付霜鬃，格瑞林都会欣然接受。"},sec={{t="国王的命令",b="格瑞林·白须和他的兄弟森内尔奉铁炉堡的参议院与国王麦格尼·铜须之命，来到寒脊山谷。他们的任务是评估并消除当地霜鬃巨魔的威胁。铁炉堡的士兵正忙于应对丹莫罗各地的穴居人之乱，兄弟俩因此缺乏补给。于是，格瑞林在积雪的山丘间扎营，依靠当地新兵和路过的初学者完成任务。"},{t="南方的麻烦",b="格瑞林在营地里监视着霜鬃部族从寒脊山谷向南推进。巨魔越来越猖狂，开始离开山中的洞穴，四处袭掠。在一次袭击中，一个满身涂绘的巨魔冷酷的格瑞克尼尔潜入无人看守的营地，偷走了格瑞林记录观察结果的野外日志。\n\n格瑞林绝不会辜负国王。他派旅人进入霜鬃的洞穴，找回他的记录，并将最终报告送到卡拉诺斯的森内尔手中。"}},faq={{q="格瑞林·白须为什么待在这片雪地里？",a="铁炉堡的参议院与国王麦格尼·铜须派格瑞林前来评估并消除寒脊山谷的霜鬃威胁。铁炉堡的士兵正忙于在别处对抗穴居人，他只能依靠当地新兵。",al={"格瑞林为何在这里","格瑞林·白须的任务","格瑞林·白须是谁"}},{q="谁偷走了格瑞林的日志？",a="一个名叫冷酷的格瑞克尼尔的霜鬃巨魔袭击了格瑞林无人看守的营地，偷走了他的日志。格瑞林看见这个浑身涂满印记的蛮徒带着他的野外笔记，逃向南方的巨魔洞穴。",al={"谁偷走了日志","偷日志的窃贼","格瑞林的日志"}},{q="格瑞林的兄弟是谁？",a="格瑞林的兄弟是森内尔·白须，驻守在山下更远处的卡拉诺斯。格瑞林派可靠的信使前往那里，送去有关巨魔动向的报告。",al={"格瑞林的兄弟","森内尔·白须","森内尔是谁"}},{q="格瑞林的营地里还有谁？",a="没有记录表明格瑞林的营地里有其他同伴。格瑞林和森内尔被派去对付巨魔，却几乎得不到支援，而巨魔袭击时，营地也无人看守。",al={"白须营地的非玩家角色","谁和格瑞林在一起","格瑞林的同伴"}},{q="铁炉堡为什么不派正规军来帮助他？",a="铁炉堡的守军和参议院的部队正忙于应对丹莫罗各地的穴居人之患。像格瑞林这样的斥候只能依靠当地新兵，应对各地的威胁。",al={"为何没有矮人军队","铁炉堡守卫在哪里","为何没有士兵"}}},fx={bc052fbe={q="格瑞林·白须是谁？",a="格瑞林·白须是代表铁炉堡参议院和国王麦格尼·铜须派往寒脊山谷的调查员。他奉命评估霜鬃巨魔的进攻动向，在白雪覆盖的山谷中设立了一处偏远营地，依靠新入伍的巡山人击退巨魔，而矮人主力部队正忙于应付别处的战事。",al={"格瑞林是谁","格瑞林·白须背景故事","白须是谁"}},d217c46a={q="格瑞林·白须效忠哪一方？",a="格瑞林对铁炉堡王国和大联盟忠心耿耿。他直接听命于铁炉堡参议院，携带着麦格尼国王亲手盖印的公文，不知疲倦地守护矮人的领土，抵御外来的威胁。",al={"格瑞林·白须阵营","格瑞林为谁工作","格瑞林属于联盟吗"}},["6d2fc414"]={q="格瑞林·白须想要什么？",a="格瑞林希望尽快解决寒脊山谷南部的霜鬃巨魔问题。由于矮人卫兵忙于抵御穴居人的入侵，他需要身强力壮的冒险者削减这些凶悍巨魔的数量，从巨魔首领格里克尼尔手中夺回被偷走的日记，并将他完成的侦察报告交给卡拉诺斯的兄弟。",al={"格瑞林想做什么","格瑞林·白须目标","格瑞林需要什么"}}},fp="17,176,15.436.0,20.440.0,46.211.0,27.197.0,24.154.0,31.163.0,56.159.0"}
P.entries["npc:greta-mosshoof"] = {n="格雷塔·苔蹄",s="格雷塔·苔蹄是一位牛头人德鲁伊，在费伍德森林南部的翡翠圣地与翡翠之环并肩作战。她与暗夜精灵及其他自然守护者一起，调查在这片古老森林中蔓延的邪恶污染，并派遣斥候深入暗影议会的要塞加德纳尔。",h="格雷塔·苔蹄是一位牛头人德鲁伊，在费伍德森林南部的翡翠圣地与翡翠之环并肩作战。她与暗夜精灵及其他自然守护者一起，调查在这片古老森林中蔓延的邪恶污染，并派遣斥候深入暗影议会的要塞加德纳尔。",kw={"被污染的水","翡翠之环","翡翠圣地","费伍德森林","格雷塔·苔蹄","水之先知伊斯伦","加德纳尔"},ang={["class:Druid"]="对于那些致力于清除燃烧军团所留创伤的德鲁伊而言，格雷塔·苔蹄体现了塞纳里奥议会的合作精神，放下阵营归属，共同恢复卡利姆多的荒野。",["race:Tauren"]="即使远在北方，身处曾经仅由暗夜精灵守护的土地，格雷塔依然展现了牛头人治愈Earth Mother创伤的坚定决心。"},sec={{t="森林的守护者",b="格雷塔·苔蹄驻守在费伍德森林南部边界的翡翠圣地，与翡翠之环携手对抗吞噬这片古老林地的污染。她不愿将饱受摧残的土地拱手让给第三次大战遗留的恶魔污染，而是协调各方力量，查明并遏制不断蔓延的腐化。她的调查集中在费伍德森林遭到污染的水源，以及盘踞在加德纳尔的邪恶教徒身上。"},{t="打击暗影议会",b="格雷塔·苔蹄在揭露暗影议会于加德纳尔深处策划的阴谋时发挥了关键作用。她意识到，峡谷中遭到污染的泉水和邪恶结界正在直接助长侵蚀这片土地的病害，于是招募旅人采集被污染的水样，向远方海岸上的水之先知伊斯伦等萨满祭司寻求帮助，并摧毁那些保护恶魔集团免遭外人侵入的仪式火盆。"}},faq={{q="格雷塔·苔蹄是谁？",a="格雷塔·苔蹄是翡翠之环的一名牛头人成员，驻守在费伍德森林的翡翠圣地。她帮助旅人和德鲁伊调查并清除毒害森林的恶魔污染。",al={"格雷塔·苔蹄背景故事","格雷塔·苔蹄是谁","格雷塔 费伍德森林"}},{q="格雷塔·苔蹄属于哪个阵营？",a="格雷塔·苔蹄是翡翠之环的成员，这是一个致力于治愈自然的中立组织。因此，她会为联盟和部落的冒险者提供指引与任务。",al={"格雷塔·苔蹄是部落还是联盟","格雷塔·苔蹄声望","格雷塔 阵营"}},{q="格雷塔为什么派冒险者进入加德纳尔？",a="加德纳尔是暗影议会在费伍德森林的要塞，他们将恶魔胆汁注入这片土地的水道，并维持着庇护恶魔的结界。格雷塔指引冒险者打击加德纳尔，破坏他们的仪式，净化遭到污染的泉水。",al={"加德纳尔任务缘由","格雷塔·苔蹄 加德纳尔","加德纳尔势力的缘由"}},{q="格雷塔·苔蹄与水之先知伊斯伦有什么关系？",a="格雷塔与水之先知伊斯伦是朋友，后者是一位居住在贫瘠之地沿海的睿智萨满祭司。格雷塔发现费伍德森林的水样遭到污染后，便指引冒险者寻求伊斯伦的灵性力量来净化水样，使其能够洁净被污染的泉水。",al={"格雷塔 与 伊斯伦","水之先知伊斯伦的关联"}}},fp="14,215,22.321.0,30.337.1,22.178.0,43.143.0,47.224.0,55.277.0"}
P.entries["npc:grif-wildheart"] = {n="格瑞夫",s="在卡拉诺斯的雷酒酿制厂外，格瑞夫引导年轻猎人踏上与野兽伙伴相伴的道路。他向从寒脊山谷前来的猎人传授追踪、射击和驯服野兽的技艺。",h="在卡拉诺斯的雷酒酿制厂外，格瑞夫引导年轻猎人踏上与野兽伙伴相伴的道路。他向从寒脊山谷前来的猎人传授追踪、射击和驯服野兽的技艺。",kw={"驯服野兽","丹莫罗","格瑞夫","猎人训练师","卡拉诺斯","巡山人","雷酒酿制厂"},ang={["class:Hunter"]="身为猎人，你向格瑞夫学习驯服野兽，并能与丹莫罗各处的野生掠食者结下羁绊。",["faction:Alliance"]="身为联盟斥候或神射手，你可以在卡拉诺斯向格瑞夫学习，为踏入铁炉堡周围的荒野做好准备。",["race:Dwarf"]="身为矮人，你可以追随格瑞夫的巡山人传统，与山中的野兽一同生活。"},sec={{t="荒野生涯",b="格瑞夫一生都在丹莫罗冰封的荒野中度过。许多铁炉堡矮人选择在锻炉或矿井中劳作，当地的巡山人却说，他花在四足野兽身上的时间太多了。即便如此，也没有人质疑他对荒野的了解。多年来，他与经验丰富的狩猎伙伴一起，在积雪的山脊间追踪猎物，熟知峭壁间掠食者的习性。"},{t="野兽之道",b="年轻的矮人猎人在寒脊山谷完成最初的试炼后，便前往卡拉诺斯，接受格瑞夫的指导。他磨炼他们的射术，教他们在荒野中生存。不过，他最精深的本领，是让猎人与野兽结下羁绊。他让学生带着驯兽棒，深入丹莫罗冰冷的荒原，面对大型峭壁野猪、雪豹和冰爪熊。"},{t="前往武器大厅",b="猎人安抚过三种野兽后，格瑞夫在卡拉诺斯的训练便告完成。猎人还必须学会喂养、管教和训练新伙伴。因此，格瑞夫让完成训练的学生沿着山坡前往铁炉堡。在这座都城的穹顶之下，他们向驯兽大师报到，学习照料将与自己相伴一生的伙伴。"}},faq={{q="格瑞夫是谁？",a="格瑞夫在丹莫罗的卡拉诺斯训练猎人。他指导那些已在寒脊山谷完成最初试炼的联盟新手猎人。",al={"格瑞夫是谁","格瑞夫身份","关于格瑞夫"}},{q="在哪里可以找到格瑞夫？",a="你可以在卡拉诺斯的雷酒酿制厂外找到格瑞夫，就在从寒脊山小径通往铁炉堡的积雪道路旁。",al={"格瑞夫位置","格瑞夫在哪里","卡拉诺斯的格瑞夫"}},{q="格瑞夫教新手猎人什么？",a="格瑞夫教年轻猎人磨炼射术、在荒野中生存，以及驯服野兽。他的课程涉及野猪、豹和熊。",al={"格瑞夫教什么","格瑞夫猎人训练","格瑞夫技能"}},{q="格瑞夫让猎人驯服哪些野兽？",a="格瑞夫让猎人深入丹莫罗，驯服一头大型峭壁野猪、一只雪豹和一头冰爪熊。",al={"格瑞夫驯兽任务","丹莫罗驯服哪些动物","驯服野兽目标"}},{q="猎人完成驯兽试炼后，格瑞夫会让他们去哪里？",a="完成驯兽试炼后，猎人会前往铁炉堡。在那里，高阶驯兽师会教他们喂养和指挥自己的伙伴。",al={"格瑞夫之后去哪里","训练野兽下一步","格瑞夫后续任务"}},{q="铁炉堡的巡山人如何看待格瑞夫？",a="铁炉堡当地的巡山人说，格瑞夫花在动物身上的时间太多了。不过，他们也坦然承认，他对猎人技艺的了解几乎无人能及。",al={"巡山人对格瑞夫的看法","格瑞夫受尊敬吗","格瑞夫的名望"}}},fx={["5a030de6"]={q="格瑞夫效忠哪一方？",a="格瑞夫坚定地效忠于铁炉堡和大联盟。他在卡拉诺斯指导年轻的矮人猎人，以此为族人效力，确保他们具备保卫山中王国及其领土所需的纪律和生存技能。",al={"格瑞夫阵营","格瑞夫是联盟吗","格瑞夫效忠对象"}},a3b5e7f5={q="格瑞夫想要什么？",a="格瑞夫致力于传授荒野技艺。他希望有志成为猎人的人掌握驯服野兽和野外生存的本领，因此派新学徒深入丹莫罗的雪地，学习尊重、耐心，以及如何与峭壁间的生灵结下一生的羁绊。",al={"格瑞夫目标","格瑞夫想要什么","格瑞夫动机"}},["20183458"]={q="格瑞夫为什么在卡拉诺斯？",a="格瑞夫驻留在卡拉诺斯，训练从寒脊山谷走来的新兵。卡拉诺斯地处丹莫罗的交通要道，是年轻猎人的理想试炼场，他们已准备好与山中的野猪、豹子和熊较量智慧。",al={"格瑞夫为什么在这里","格瑞夫为什么在丹莫罗","格瑞夫为什么在卡拉诺斯"}}},fp="14,220,19.374.0,20.367.0,27.374.0,22.146.0,32.120.0,36.139.0,43.99.0,66.131.0,49.152.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="葛瑞姆·雷酒",s="在西部荒野的匕首岭，葛瑞姆·雷酒守着自己的酒桶，酿造烈酒。这个古怪的矮人说话总是押韵，是雷酒氏族的一员。",h="在西部荒野的匕首岭，葛瑞姆·雷酒守着自己的酒桶，酿造烈酒。这个古怪的矮人说话总是押韵，是雷酒氏族的一员。",kw={"麦酒","酿酒师","匕首岭","酿酒厂","葛瑞姆","卡拉诺斯","雷酒","西部荒野"},ang={["profession:Cooking"]="身为厨师，你可以从葛瑞姆的酿酒技艺中学到东西，那也是雷酒传承的一部分。",["race:Dwarf"]="身为矮人，你熟知雷酒这个姓氏。在西部荒野的丘陵间，遇见雷酒兄弟中的一人用奇特配方酿酒，让你品到了丹莫罗的风味。"},sec={{t="流落异乡的酿酒师",b="葛瑞姆·雷酒在匕首岭扎营，照料着自己的私藏酒桶。他离开了丹莫罗白雪覆盖的群峰，来到西部荒野饱受风吹的丘陵，而雷酒酿酒世家的家乡就在丹莫罗的卡拉诺斯。他性情开朗，醉心于烈酒，开口总是押韵。旅人必须先完成一项简单的任务，他才会回答问题，而他也随时准备考验渴酒之人的品酒本领。"}},faq={{q="在哪里能找到葛瑞姆·雷酒？",a="葛瑞姆·雷酒就在西部荒野南部的匕首岭。他带着酿酒设备，在那里扎营。",al={"葛瑞姆位置","葛瑞姆在哪里","在哪里找到葛瑞姆·雷酒"}},{q="葛瑞姆为什么说话总是押韵？",a="没人能确切说清葛瑞姆为什么说话总是押韵。他喜爱诗句，谁想向他提问，都得先完成一项简单的任务。",al={"葛瑞姆为什么押韵","葛瑞姆说话押韵","他为什么用诗句说话"}},{q="他与雷酒酿制厂有什么关系？",a="葛瑞姆属于丹莫罗卡拉诺斯的雷酒氏族。包括拉格纳·雷酒在内，他的亲族都在家乡照料家族的酿酒厂，而葛瑞姆则独自在西部荒野的丘陵间酿酒。",al={"葛瑞姆酿酒厂","葛瑞姆和拉格纳是亲戚吗","雷酒家族"}}},fx={["21ebedd0"]={q="葛瑞姆·雷酒是谁？",a="葛瑞姆是一位古怪而开朗的矮人酿酒师，来自丹莫罗著名的雷酒氏族。他嗜好麦酒的名声远扬，还喜欢用谜语和诗句说话；他离开了卡拉诺斯的家，独自在西部荒野的丘陵间酿酒。",al={"葛瑞姆是谁","葛瑞姆·雷酒","关于葛瑞姆"}},["182004c2"]={q="葛瑞姆·雷酒效忠哪一方？",a="葛瑞姆和雷酒氏族的其他成员一样，效忠于铁炉堡和联盟。不过，他真正热衷的是酿酒和美酒，而非政治或阵营间的战争，因此任何懂得欣赏上好黑啤酒的人都能得到他的友善相待。",al={"葛瑞姆阵营","葛瑞姆是联盟吗","葛瑞姆立场"}},["9bf66a40"]={q="葛瑞姆·雷酒想要什么？",a="葛瑞姆总想着酿造自己的招牌佳酿，并与旅人分享。只要你提供原料或帮上一点忙，他就十分乐意让你品尝劲道十足的雷酒贮藏啤酒，让你精神振奋。",al={"葛瑞姆想要什么","葛瑞姆目标","葛瑞姆为什么需要啤酒花"}},d50f3d5e={q="葛瑞姆·雷酒为什么在西部荒野？",a="葛瑞姆离开丹莫罗寒冷的山峰，来到匕首岭，如今每天在这里酿酒，以诗句抒发思绪，远离卡拉诺斯的家族酒坊。",al={"葛瑞姆为什么在西部荒野","葛瑞姆在西部荒野的原因","葛瑞姆在西部荒野做什么"}}},fp="21,164,17.384.0,39.116.0,36.144.0,53.199.0"}
P.entries["npc:grish-longrunner"] = {n="瑞什·远行者",s="在升降梯旁，瑞什·远行者注视着南贫瘠之地与千针石林之间的边界。这位牛头人斥候为部落传递消息，并监视这处通道上的动向。",h="在升降梯旁，瑞什·远行者注视着南贫瘠之地与千针石林之间的边界。这位牛头人斥候为部落传递消息，并监视这处通道上的动向。",kw={"贫瘠之地","召回卫兵","升降梯","瑞什","远行者","牛头人","千针石林"},ang={["faction:Horde"]="身为部落的信使或战士，你可以在南下千针石林或北上贫瘠之地的路上，找到守望升降梯的瑞什。",["race:Tauren"]="身为牛头人，你与瑞什同享远行者之名，也同样警惕地守护着穿过祖居之地的道路。"},sec={{t="升降梯旁的守望者",b="瑞什·远行者在南贫瘠之地的升降梯旁守望。升降梯的平台连接着干燥的南贫瘠之地与千针石林的峡谷。成群的野猪人在附近游荡，敌对势力也威胁着这处通道。瑞什监视过往的旅人，并向部落通报情况，以便在需要的地方召来援军。"}},faq={{q="瑞什·远行者是谁？",a="瑞什·远行者是部落的一名牛头人斥候，驻守在升降梯边缘。升降梯的平台从贫瘠之地降入千针石林。",al={"瑞什是谁","瑞什·远行者身份","瑞什做什么"}},{q="在哪里可以找到瑞什·远行者？",a="在南贫瘠之地，通往下方千针石林的升降梯机械入口旁，可以找到瑞什·远行者。",al={"瑞什·远行者位置","瑞什在哪里","寻找瑞什"}},{q="他在这一带承担什么职责？",a="瑞什接待部落的信使和旅人，并通过召回卫兵等请求，协助召集和指挥当地的援军。",al={"瑞什职责","瑞什任务","召回卫兵 瑞什"}}},fp="16,184,19.332.0,24.147.0,34.141.0,35.143.0"}
P.entries["npc:grub"] = {n="格拉布",s="在十字路口东边的一间小屋里，格拉布和一位厨师、一位面包师经营着一家路边小餐馆。他以教旅人用贫瘠之地当地的害兽烹饪而闻名。",h="在十字路口东边的一间小屋里，格拉布和一位厨师、一位面包师经营着一家路边小餐馆。他以教旅人用贫瘠之地当地的害兽烹饪而闻名。",kw={"贫瘠之地","十字路口","掘地鼠炖肉","杜恩格","格拉布","塔班·熟麦"},ang={["faction:Horde"]="身为部落的一员，你可以在十字路口外找到格拉布的路边厨房。他在那里为旅人提供食物，并教他们如何利用平原上的物产。",["profession:Cooking"]="身为厨师，你可以通过收集食材，学会格拉布的掘地鼠炖肉食谱。"},sec={{t="边地的胃口",b="在十字路口东边，格拉布与他的厨师杜恩格和面包师塔班·熟麦同住一间小屋。格拉布利用贫瘠之地的掘地鼠做菜，不让它们白白浪费。他向旅人提供一道食谱，将这些啮齿动物慢炖成汤。"}},faq={{q="格拉布是谁？",a="格拉布是一名兽人，住在贫瘠之地十字路口东边的一间小屋里。他与他的厨师杜恩格和面包师塔班·熟麦经营着一家小餐馆，招待过往的旅人。",al={"格拉布","格拉布是谁","十字路口东边的兽人"}},{q="在哪里能找到格拉布？",a="格拉布就在贫瘠之地十字路口东边不远处，离开大路后，山脚下的一间小屋里。",al={"格拉布位置","格拉布在哪里","格拉布的小屋"}},{q="格拉布需要什么帮助？",a="格拉布需要旅人从贫瘠之地收集掘地鼠，用来制作掘地鼠炖肉。他会将食谱传授给制作这道菜的厨师。",al={"格拉布任务","掘地鼠炖肉任务"}}},fp="4,144,19.238.0,12.191.0,22.120.0,30.126.0"}
P.entries["npc:grull-hawkwind"] = {n="格鲁尔·鹰风",s="在红云台地的纳拉其营地，格鲁尔·鹰风引导年轻的牛头人完成最初的试炼。身为鹰风酋长之子，他帮助猎人和战士做好准备，考验他们的决心，并向祖先致敬。",h="在红云台地的纳拉其营地，格鲁尔·鹰风引导年轻的牛头人完成最初的试炼。身为鹰风酋长之子，他帮助猎人和战士做好准备，考验他们的决心，并向祖先致敬。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","莫高雷","红云台地","力量仪祭","牛头人"},ang={["class:Hunter"]="身为莫高雷的猎人，你要面对格鲁尔·鹰风安排的最初试炼，在与当地野兽的较量中接受耐心与技巧的考验。",["race:Tauren"]="身为红云台地的年轻牛头人，你可能会遇见格鲁尔·鹰风，他是最早考验你并向你介绍Shu'halo传统的勇士之一。"},sec={{t="酋长之子",b="在纳拉其营地，格鲁尔·鹰风帮助部族的年轻人做好准备。身为鹰风酋长之子，他引导初来红云台地的年轻人，判断他们是否已准备好为舒哈鲁效力。他安排耐力、追踪和生存试炼，让他们应对平原陆行鸟和山狮。通过这些试炼，年轻的牛头人逐渐明白，平衡与尊重自然是莫高雷生活的根基。"}},faq={{q="格鲁尔·鹰风是谁？",a="格鲁尔·鹰风在红云台地的纳拉其营地引导年轻的牛头人。他是鹰风酋长的儿子，指导那些刚刚踏上旅途的人。",al={"格鲁尔·鹰风的职责","格鲁尔是谁","格鲁尔·鹰风的故事"}},{q="格鲁尔·鹰风对年轻冒险者有何作用？",a="格鲁尔·鹰风评估牛头人新手的基础训练，并安排他们在周围的平原上完成最初的狩猎与生存试炼。",al={"格鲁尔的任务","格鲁尔做什么","格鲁尔·鹰风的作用"}},{q="格鲁尔与营地的首领有亲属关系吗？",a="是的。格鲁尔·鹰风是纳拉其营地的酋长——鹰风酋长的儿子。他秉承父亲的传统，帮助营地的守卫者做好准备。",al={"鹰风酋长之子","格鲁尔·鹰风的家人","格鲁尔与酋长有亲属关系吗"}}},fp="14,206,17.383.0,22.141.0,57.139.0,42.159.0"}
P.entries["npc:grunt-dogran"] = {n="步兵多格兰",s="步兵多格兰被囚禁在南贫瘠之地深处。他曾先后被派驻十字路口和陶拉祖营地，后来在深入阿迦玛戈巡逻时被俘。",h="步兵多格兰被囚禁在南贫瘠之地深处。他曾先后被派驻十字路口和陶拉祖营地，后来在深入阿迦玛戈巡逻时被俘。",kw={"阿迦玛戈","贫瘠之地","陶拉祖营地","十字路口","多格兰","步兵多格兰","野猪人"},ang={["faction:Horde"]="多格兰被俘一事，展现了部落驻军为抵御好战的野猪人部族、守护贫瘠之地各处商路与边界而付出的代价。",["race:Orc"]="身为兽人，多格兰体现了这样的信念：战死沙场，比沦为无力自理的废人苟活于世更有荣耀。"},sec={{t="步兵的职责",b="步兵多格兰在部落军中晋升后，从十字路口被派往陶拉祖营地增援。他率领一队步兵进入阿迦玛戈，与刺背野猪人展开激战。多格兰身受重伤，落下残疾。他的战友撤退时留下了他，野猪人将他拖走，囚禁起来。"},{t="荣耀的归宿",b="步兵多格兰因伤致残，仍被困在敌后。他不愿拖着残躯回家，让伴侣照顾一个废人。他宁愿与野猪人进行最后一战，并托人将象征自己忠贞爱意的信物送到爱人手中。"}},faq={{q="步兵多格兰在哪里？",a="多格兰被囚禁在阿迦玛戈，那里位于南贫瘠之地，是一处野猪人密集的营地，就在陶拉祖营地北面。",al={"多格兰位置","多格兰在哪","贫瘠之地寻找多格兰"}},{q="多格兰为什么会被野猪人俘虏？",a="多格兰率领巡逻队从陶拉祖营地出发，前去打击野猪人，却在交战中受伤致残，随后被俘。他的战友来不及将他带走，只能让他落入敌人手中。",al={"多格兰为何被俘","多格兰如何被抓"}},{q="多格兰为什么拒绝获救？",a="多格兰在战斗中落下了终身残疾，不愿回家成为伴侣的负担。他宁愿在与野猪人的战斗中死去，也不愿作为废人活着。",al={"多格兰为何不肯离开","营救多格兰"}},{q="谁在寻找多格兰？",a="多格兰的伴侣赞卡沙住在奥格瑞玛，自他出发服役后便音讯全无，于是开始寻找他。她的忧虑让旅人先找到十字路口的加兹罗格，再前往陶拉祖营地寻找步兵劳格玛，那里的士兵逐渐拼凑出了失踪巡逻队的遭遇。",al={"谁派人寻找多格兰","多格兰任务给予者"}}},fp="12,158,14.331.0,17.255.1,30.117.0,40.183.0,37.160.1,26.254.0"}
P.entries["npc:grunt-logmar"] = {n="步兵劳格玛",s="在陶拉祖营地，步兵劳格玛为部落守望着贫瘠之地南部的边境。他追踪营地附近的威胁，并为失踪的斥候寻求援助。",h="在陶拉祖营地，步兵劳格玛为部落守望着贫瘠之地南部的边境。他追踪营地附近的威胁，并为失踪的斥候寻求援助。",kw={"陶拉祖营地","多格兰","步兵劳格玛","肯兹格拉的伤药","兽人步兵","陶拉祖","贫瘠之地"},ang={["faction:Horde"]="劳格玛是一名在贫瘠之地支援牛头人的部落前线士兵。他依靠部落勇士援助倒下和被俘的斥候。",["race:Orc"]="身为一名远离奥格瑞玛驻守的兽人步兵，你与部落的牛头人盟友并肩而立。"},sec={{t="陶拉祖营地的职责",b="在陶拉祖营地，步兵劳格玛守卫着部落在贫瘠之地南部的边境。营地坐落在牛头人的聚居地之间，附近有敌对野猪人的领地，以及通往石爪山和莫高雷的山口。劳格玛警惕着这些危险，并统筹侦察报告。当战友遭到当地敌人的伏击或俘虏时，他便召集有能力的部落旅者，帮助寻找并援助他们。"}},faq={{q="步兵劳格玛是谁？",a="步兵劳格玛是驻扎在贫瘠之地南部陶拉祖营地的一名兽人士兵。他为部落守卫这处聚居地，并负责救援和侦察行动。",al={"步兵劳格玛","劳格玛是谁","劳格玛 贫瘠之地"}},{q="在哪里可以找到步兵劳格玛？",a="你可以在贫瘠之地南部的陶拉祖营地找到步兵劳格玛，营地位于通往升降梯和千针石林的道路旁。",al={"劳格玛在哪里","劳格玛位置","寻找步兵劳格玛"}},{q="劳格玛负责哪些事务？",a="劳格玛关注失踪部落斥候的安危。他派遣旅者调查同为步兵的多格兰失踪和被俘的情况，并找回肯兹格拉的伤药等重要补给。",al={"劳格玛任务","劳格玛需要什么","营救多格兰"}}},fp="12,149,20.365.0,20.135.0,32.125.0,33.190.0"}
P.entries["npc:grunth"] = {n="Grunth",s="在奥格瑞玛，葛兰斯渴望与部落的勇士们相伴。这个年幼的兽人住在 暗巷区 的孤儿院里，每逢儿童周，他便踏上穿越卡利姆多和东部王国的旅程，了解成为英雄意味着什么。",h="在奥格瑞玛，葛兰斯渴望与部落的勇士们相伴。这个年幼的兽人住在 暗巷区 的孤儿院里，每逢儿童周，他便踏上穿越卡利姆多和东部王国的旅程，了解成为英雄意味着什么。",kw={"儿童周","葛兰斯","兽人孤儿","奥格瑞玛","孤儿监护员巴特维尔","孤儿哨","暗巷区"},ang={["faction:Horde"]="作为部落的勇士，在儿童周期间带领葛兰斯出游，能让你看到在自由中出生、无需受恶魔奴役的一代，以及你的阵营竭力守护的一切。",["race:Orc"]="作为兽人，葛兰斯展现了杜隆塔尔年轻一代的面貌，他们在部族荣誉与生存需求中成长，而非困于收容所里那种阴暗的消沉之中。"},sec={{t="好奇的部落孩童",b="葛兰斯是住在奥格瑞玛 暗巷区 的一名兽人孤儿，由孤儿监护员巴特维尔照料。他在杜隆塔尔荒凉的红色土地上长大，总是满怀敬畏地望着身披铠甲的冒险者，问个不停。身披铠甲的战士真的很可怕吗？为什么闪电劈在水面上，却不会把所有的鱼都电死？他有机会亲眼看见有人与真正的巨龙战斗吗？"},{t="儿童周之旅",b="在儿童周期间，吹响兽人孤儿哨便能召来葛兰斯，让他随冒险者周游世界。他想去莫高雷拜见大酋长凯恩·血蹄，看看洛丹伦残破的王座厅，还想走访那些艰苦的边疆，他的同胞正在那里为自己的未来而战。"}},faq={{q="葛兰斯是谁？",a="葛兰斯是奥格瑞玛 暗巷区 孤儿院里的一名兽人孩童。孤儿监护员巴特维尔照料着他，而他梦想着成为部落的传奇英雄。",al={"葛兰斯 非玩家角色","兽人孤儿","奥格瑞玛孤儿"}},{q="在哪里能找到葛兰斯？",a="葛兰斯和其他孤儿一起住在奥格瑞玛的 暗巷区。在儿童周期间，使用孤儿监护员巴特维尔交给你的兽人孤儿哨，就能在任何地方召来他。",al={"葛兰斯 位置","葛兰斯 在哪里","寻找 葛兰斯"}},{q="葛兰斯想去哪些地方？",a="葛兰斯想见识部落的伟大地标与人物。他请求去雷霆崖拜见大酋长凯恩·血蹄，看看棘齿城的码头，再前往洛丹伦残破的王座厅。",al={"葛兰斯 任务","孤儿想要什么","葛兰斯 游历"}},{q="葛兰斯的性格如何？",a="葛兰斯嗓门大，好奇心强，想象力丰富。他会问冒险者一些奇怪的问题，比如“祖格祖格”是什么意思，没有翅膀的苍蝇是不是该叫“步行虫”，甚至还提到把石头塞进自己的鼻子里。",al={"葛兰斯 语录","葛兰斯 对话","葛兰斯 说什么"}}},fp="6,203,28.338.0,24.291.0,14.169.0,26.160.0,38.180.0,42.208.0"}
P.entries["npc:gryan-stoutmantle"] = {n="格里安·斯托曼",s="在西部荒野的哨兵岭，格里安·斯托曼率领着人民军。身为白银之手的圣骑士，他从洛丹伦返回故乡，守护这片被暴风城王室弃之不顾、匪患横行的土地。",h="在西部荒野的哨兵岭，格里安·斯托曼率领着人民军。身为白银之手的圣骑士，他从洛丹伦返回故乡，守护这片被暴风城王室弃之不顾、匪患横行的土地。",kw={"死亡矿井","格里安","人民军","哨兵岭","白银之手","斯托曼","范克里夫","西部荒野","威利"},ang={["class:Paladin"]="身为圣骑士，当教会和王室对穷人不闻不问时，格里安将 Light 的庇护带给西部荒野的农民，履行着白银之手的职责。",["faction:Alliance"]="身为联盟的一员，你能看到暴风城在政治上的无所作为，如何迫使忠诚的民众自行武装，保卫腹地。",["race:Human"]="身为人类，你与格里安同样扎根于西部荒野，也同样拥有暴风城乡民的坚韧，面对匪徒的侵扰和都城的漠视。"},sec={{t="骑士归乡",b="格里安·斯托曼最初在远离西部荒野的地方服役。年轻时，他北上洛丹伦，立誓成为白银之手的骑士。他在那里经历了第三次大战的恐怖。后来，他得知故乡正陷入无法无天的境地，成群结伙的匪徒四处横行，而王室却弃之不顾。格里安离开北方前线，回来保护本分的农民，决心不让西部荒野像北方那样沦陷。"},{t="人民军",b="格里安归来时，西部荒野几乎无人守卫。王室的漠视与贵族的政治僵局，让暴风城迟迟无法派兵驻守。于是，格里安在哨兵岭组建了人民军，将当地农民、哨兵和过路的佣兵召集起来，组成一支志愿卫队。\n\n这支民兵艰难地维持着防线，抵御迪菲亚潜行者、河爪 豺狼人和敌对机械的袭击。即使邻近的湖畔镇恳求援助，格里安也抽不出兵力增援。"},{t="揭开匪首的真面目",b="格里安·斯托曼试图查明，究竟是谁在幕后将西部荒野推向毁灭。他找到赤脊山的盗贼黑衣威利，要求对方偿还旧日的恩情，又与 SI:7 的马迪亚斯·肖尔交谈。他们提供的情报揭示，匪徒的首领是艾德温·范克里夫。范克里夫曾是石匠公会备受怠慢的建筑大师。\n\n民兵抓住了一名企图劫掠当地货车的匪徒后，格里安利用这名俘虏，找到了迪菲亚潜行者位于月溪镇地下、死亡矿井中的总部。他派出身经百战的勇士，直取范克里夫。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼在位于哨兵岭的总部指挥人民军。他是白银之手的圣骑士。",al={"格里安是谁","斯托曼的故事","西部荒野领袖"}},{q="既然西部荒野属于暴风城，为什么还需要人民军？",a="暴风城的贵族拒绝派遣王室士兵，也不愿拨出国库资金保护西部荒野。当地农民只能独自面对劫掠者和豺狼人，于是在格里安的领导下组建了自己的卫队。",al={"为何需要民兵","暴风城军队在哪","暴风城为何抛弃西部荒野"}},{q="格里安与白银之手有怎样的渊源？",a="年轻时，格里安前往洛丹伦，成为白银之手的圣骑士。第三次大战期间，他在北方的战场上服役，随后离开那里，回去保卫危在旦夕的故乡。",al={"格里安是圣骑士吗","格里安与 白银之手","格里安在 洛丹伦"}},{q="格里安为什么拒绝援助湖畔镇？",a="所罗门镇长请求增援，以对抗赤脊山的豺狼人和兽人，格里安却不得不拒绝。人民军守卫哨兵岭已是捉襟见肘，格里安担心，即使只派出一小队人马，也会让西部荒野落入迪菲亚手中。",al={"所罗门镇长的请求","援助 赤脊山","为何不派兵援助湖畔镇"}},{q="格里安是如何发现迪菲亚藏身之处的？",a="格里安向黑衣威利和马迪亚斯·肖尔打探情报，随后派冒险者调查迪菲亚潜行者。他们的发现，记述在一段隐藏的文字中。",al={"寻找死亡矿井","谁找到了范克里夫","迪菲亚 叛徒的故事"}},{q="黑衣威利与格里安是什么关系？",a="黑衣威利住在湖畔镇的旅店里，欠格里安一条命。格里安并不喜欢这个盗贼的卑劣品性，却利用这份恩情，换取了有关迪菲亚行动的情报。",al={"威利与格里安","黑衣威利欠下的恩情"}}},fx={["7558c158"]={q="格里安·斯托曼效忠哪一方？",a="格里安效忠联盟和暴风城王国，而他最忠于的，是西部荒野的平民百姓。暴风城王庭对这片土地的苦难视而不见，格里安便亲自率领人民军，着手应对危局。他依然是一名忠诚的骑士，为将这片疆土夺回、交还给理应拥有它的民众而战。",al={"格里安·斯托曼的阵营","格里安为谁效力","格里安属于什么阵营"}},c0a0d15a={q="格里安·斯托曼想要什么？",a="格里安力求铲除迪菲亚潜行者，让西部荒野重归和平，恢复法纪与秩序。他想夺回当地被侵占的农场，清剿那些恐吓本分定居者的匪徒和盗贼，并保障遭王室遗弃的农民的安全。",al={"格里安·斯托曼的目标","格里安想要什么","格里安的动机"}},d2149791={q="格里安·斯托曼为什么在西部荒野？",a="西部荒野是格里安的故乡。第三次大战期间，他身在洛丹伦，得知匪徒正在蹂躏故土、将农民赶出田地，便返回南方，保卫这片土地。他驻守在哨兵岭，从这片争夺之地的腹地领导人民军。",al={"格里安为何在西部荒野","格里安为何来到西部荒野","格里安为何在哨兵岭"}},["9073fb6b"]={q="格里安·斯托曼与谁有关联？",a="格里安与暴风城情报机构SI:7的首领马迪亚斯·肖尔保持联系，后者为他提供有关迪菲亚潜行者的重要侦察情报。他还与赤脊山的黑衣威利有往来，这位旧识曾被他救过一命，他也与邻近各地的守卫者协调行动。",al={"格里安·斯托曼的盟友","格里安与谁合作","格里安的人脉"}}},fp="17,203,22.437.0,20.496.0,21.532.1,25.120.0,68.209.0,45.185.0,47.243.0,52.167.1,32.195.0"}
P.entries["npc:guard-berton"] = {n="卫兵伯尔顿",s="在湖畔镇旅店外，卫兵伯尔顿希望尽快将可怕的塔格尔绳之以法。赤脊山正遭受黑石兽人的入侵，这名人类卫兵已厌倦了暴风城的拖延。",h="在湖畔镇旅店外，卫兵伯尔顿希望尽快将可怕的塔格尔绳之以法。赤脊山正遭受黑石兽人的入侵，这名人类卫兵已厌倦了暴风城的拖延。",kw={"伯尔顿","卫兵伯尔顿","湖畔镇","赤脊山","塔格尔","可怕的塔格尔","监狱","罪有应得"},ang={["faction:Alliance"]="身为联盟的守护者，你能理解边境城镇为何日渐不满：他们正为生存而战，暴风城的官僚机构却迟迟不肯伸张正义。"},sec={{t="寻求正义的卫兵",b="赤脊山正遭受黑石兽人的入侵，卫兵伯尔顿在湖畔镇旅店外守望。他牵挂的是可怕的塔格尔，这名被俘的敌人被关押在暴风城监狱深处。塔格尔因危害王国的罪行被判处死刑，却因暴风城无限期推迟行刑而一直被关在牢里。湖畔镇正在流血，伯尔顿绝不会让这个残暴的劫掠者继续待在牢房里。他雇用自愿前往的冒险者，绕过拖延，杀死这个兽人。"}},faq={{q="卫兵伯尔顿是谁？",a="卫兵伯尔顿是一名联盟卫兵，驻守在赤脊山的湖畔镇旅店外。他雇用冒险者，惩处一名臭名昭著的兽人囚犯。",al={"伯尔顿 湖畔镇","伯尔顿是谁"}},{q="卫兵伯尔顿为什么要杀死可怕的塔格尔？",a="尽管可怕的塔格尔因危害王国的罪行被判处死刑，暴风城仍暂缓了行刑。赤脊山遭到围攻，伯尔顿便安排人手，在监狱内杀死塔格尔。",al={"为什么杀塔格尔","塔格尔处决","伸张正义任务背景"}},{q="可怕的塔格尔被关押在哪里？",a="可怕的塔格尔被关押在监狱，那是暴风城运河区一座戒备森严的地下牢狱。",al={"塔格尔位置","塔格尔在哪里"}},{q="在哪里可以找到卫兵伯尔顿？",a="卫兵伯尔顿就在湖畔镇旅店外守望，俯瞰着赤脊山的湖畔镇中心。",al={"伯尔顿在哪里","伯尔顿位置"}}},fp="12,174,23.450.0,20.169.0,52.199.0,32.102.0,32.105.0"}
P.entries["npc:guard-howe"] = {n="卫兵豪维",s="在湖畔镇的桥边，卫兵豪维守望着道路，招募战士对抗黑石兽人。出于私仇，他悬赏征集击败这些兽人的凭证。",h="在湖畔镇的桥边，卫兵豪维守望着道路，招募战士对抗黑石兽人。出于私仇，他悬赏征集击败这些兽人的凭证。",kw={"黑石悬赏","黑石兽人","卫兵豪维","豪维","湖畔镇","赤脊山"},ang={["faction:Alliance"]="暴风城给湖畔镇的直接援助很少，因此豪维这样的前线卫兵依靠途经此地的联盟勇士，阻止黑石兽人攻陷镇子。"},sec={{t="桥上的宿怨",b="卫兵豪维在止水湖石桥南端守望，这里靠近湖畔镇中心。黑石兽人不断深入赤脊山，豪维视他们为山谷的威胁。他对这个氏族怀有深仇，招募过往的战士前往东部山丘猎杀兽人。作为回报，他会向带回击败兽人凭证的人支付赏金。"}},faq={{q="卫兵豪维是谁？",a="卫兵豪维是一名人类城镇卫兵，驻守在赤脊山湖畔镇的桥南端。他协助保护镇子，并派遣战士对抗入侵的黑石兽人。",al={"卫兵豪维","豪维 湖畔镇","豪维是谁"}},{q="卫兵豪维为什么要杀死黑石兽人？",a="豪维一心向黑石氏族复仇，这个氏族的军队已深入赤脊山，不断向湖畔镇施压。他向那些削减兽人兵力的人提供赏金。",al={"为何悬赏黑石","豪维 兽人","豪维为何憎恨兽人"}},{q="卫兵豪维与当地其他人有亲属关系吗？",a="卫兵豪维与所罗门·豪维同姓，因此他们可能有亲属关系。豪维专注于守卫湖畔镇和对抗兽人。",al={"豪维的亲属","所罗门 豪维 亲属关系"}}},fp="10,184,22.361.0,18.174.0,47.194.0,51.136.0"}
P.entries["npc:guard-thomas"] = {n="卫兵托马斯",s="在东谷伐木场以西的桥上，卫兵托马斯守望着艾尔文的东部边境。他为暴风城军队效力，保护当地工人免受野兽和鱼人的侵害。",h="在东谷伐木场以西的桥上，卫兵托马斯守望着艾尔文的东部边境。他为暴风城军队效力，保护当地工人免受野兽和鱼人的侵害。",kw={"东谷","东谷伐木场","艾尔文森林","卫兵托马斯","失踪的卫兵","鱼人","暴风城军队","托马斯"},ang={["class:Warrior"]="身为一名年轻的联盟战士，你可以从托马斯身上看到前线军人的纪律，以及守卫一方边境的艰辛。",["faction:Alliance"]="身为联盟的一员，你能看到Stormwind Army的兵力有多么紧张。卫兵托马斯几乎得不到王室的支援，却仍坚守着至关重要的边境哨岗。"},sec={{t="东部边境",b="卫兵托马斯驻守在通往东谷伐木场的跨河石桥上，这处哨岗虽安静，却缺乏掩护。附近的树林里潜伏着凶猛的生物，伐木工人依靠暴风城的卫兵保护。军队兵力捉襟见肘，托马斯只能依靠旅人协助维持秩序，并向指挥部传递消息。"},{t="边境的麻烦",b="熊和潜伏的野兽威胁着艾尔文东部林缘的伐木工与旅人。鱼人部族已在水道旁扎营，卫兵托马斯因此追踪它们的动向，并悬赏削减它们的数量。沿河派出的巡逻队有时会失踪。随着这一带的麻烦日益增多，托马斯必须查明卫兵同伴们的下落。"}},faq={{q="在哪里能找到卫兵托马斯？",a="卫兵托马斯站在艾尔文森林东部道路的跨河石桥上，就在东谷伐木场以西。",al={"卫兵托马斯位置","托马斯在哪里","卫兵托马斯桥梁"}},{q="卫兵托马斯在艾尔文森林负责什么？",a="卫兵托马斯为暴风城军队守卫艾尔文的东部边境。他守卫着商路上的桥梁，保护附近的工人免受野兽侵害，并留意河岸边的鱼人。",al={"托马斯做什么","卫兵托马斯职责","托马斯 东谷"}},{q="卫兵托马斯为什么请求协助寻找失踪的卫兵？",a="派往河流流域的巡逻队迟迟未归。没有足够的卫兵接替，托马斯无法离开岗位，只能请旅人沿水道寻找失踪的同伴。",al={"艾尔文失踪的卫兵","卫兵托马斯失踪的斥候","卫兵出了什么事"}},{q="鱼人为什么会给卫兵托马斯带来麻烦？",a="鱼人部族正沿着艾尔文东部的河流向更上游推进。它们威胁着伐木作业和补给路线，因此托马斯发布悬赏，以保持水道畅通。",al={"东谷鱼人","为什么要杀鱼人","卫兵托马斯鱼人悬赏"}},{q="卫兵托马斯向谁汇报？",a="卫兵托马斯在暴风城军队服役，按指挥层级向闪金镇和首都的地区指挥部汇报。随着边境的麻烦日益增多，他也通过公文与西部荒野的格里安·斯托曼协调行动。",al={"托马斯的上级","暴风城军队指挥层级","托马斯为谁效力"}},{q="冒险者完成在艾尔文的任务后，卫兵托马斯会派他们去哪里？",a="东谷附近和东部河流沿岸的威胁得到处理后，托马斯会指引经验丰富的旅人前往西部荒野，帮助格里安·斯托曼和处境艰难的人民军。",al={"卫兵托马斯之后","东谷之后去哪里","西部荒野报到"}}},fx={["2ef4fdb3"]={q="卫兵托马斯是谁？",a="卫兵托马斯是暴风城军队的一名军官，驻守在艾尔文森林的东部边境。暴风城的兵力分散在王国各地，捉襟见肘，托马斯则坚守东谷伐木场附近的岗哨，保护桥边的旅人与工人，抵御豺狼人和步步进逼的鱼人。",al={"托马斯是谁","卫兵托马斯的身份","卫兵托马斯是谁"}},["26bccfb6"]={q="卫兵托马斯效忠哪一方？",a="托马斯为暴风城王国和联盟效力。身为暴风城军队的忠诚士兵，他奉王命行事，亲自为王国的民众和劳工守卫边境。",al={"卫兵托马斯的阵营","卫兵托马斯为谁效力","卫兵托马斯联盟"}},["8313e011"]={q="卫兵托马斯想要什么？",a="托马斯需要有能力的人手，保护艾尔文森林的东部边缘。河中凶猛的鱼人和敌对的豺狼人威胁着东谷的伐木工，他希望肃清周围荒野的威胁，查明失踪巡逻兵的下落，并定期向暴风城和西部荒野的最高指挥部传回情报。",al={"托马斯想要什么","卫兵托马斯的目标","卫兵托马斯需要什么"}},c7700b23={q="卫兵托马斯为什么在这里？",a="托马斯奉命驻守东边的桥梁，守卫通往东谷伐木场及更远边境地区的主要通道。东谷是暴风城重要的木材供应地，而当地野兽正从河流与山丘一带逼近，因此必须有军队驻守，确保道路畅通。",al={"卫兵托马斯为何在桥边","托马斯为何在这里","卫兵托马斯驻守原因"}}},fp="12,174,21.343.0,17.343.1,30.125.0,45.186.0,53.195.0,43.165.0,32.228.0,75.178.0"}
P.entries["npc:gubber-blump"] = {n="古博·布拉普",s="在奥伯丁岸边，古博·布拉普一边钓鱼、传授钓鱼技艺，一边寻找新鲜的蟹肉。",h="在奥伯丁岸边，古博·布拉普一边钓鱼、传授钓鱼技艺，一边寻找新鲜的蟹肉。",kw={"奥伯丁","布拉普","黑海岸","钓鱼","格劳恩·布拉普","古博","暗礁蟹","闪光的小珠"},ang={["profession:Cooking"]="古博·布拉普偏爱海滨食物，尤其是新鲜的reef crawler肉，这是从黑海岸水域采集食材的厨师们眼中的上等原料。",["race:Dwarf"]="身为矮人，古博·布拉普却定居在雾气笼罩的卡利姆多海岸，而非卡兹莫丹，这并不多见。他坦率地谈论亲族时，仍流露出铁炉堡的乡土气息。"},sec={{t="奥伯丁的垂钓者",b="古博·布拉普在黑海岸沿岸钓鱼，就在奥伯丁的飞行管理员与渡船码头之间。大多数矮人偏爱石砌厅堂或熔炉，他却选择了海岸。他向旅人传授钓鱼技艺，也出售简单的钓鱼用具。蟹肉是他最喜爱的食物之一，他常常依靠旅人从危险的海岸带回渔获，或找回家传的渔具。"},{t="家族情谊与海边人情",b="古博·布拉普谈起家人时毫不拘束，尤其是他的堂亲格劳恩·布拉普，此人留着胡子，身上还有一股异味。帮助他处理海边事务的旅人，比如收集蟹腿或寻找家传鱼竿，可能会收到一封亲笔感谢信，以及一个闪亮的鱼饵，供下次垂钓时使用。"}},faq={{q="古博·布拉普是谁？",a="古博·布拉普在奥伯丁的海滩上钓鱼并传授钓鱼技艺，位置就在村庄码头与角鹰兽管理员之间。",al={"古博·布拉普是谁","古博·布拉普非玩家角色","古博·布拉普在哪"}},{q="古博·布拉普教授什么，又出售什么？",a="古博·布拉普传授钓鱼技艺，也出售基本的钓鱼用具，包括鱼竿和闪光的小珠。",al={"古博卖什么","古博·布拉普训练师","黑海岸钓鱼训练师"}},{q="古博·布拉普会交付哪些任务？",a="古博·布拉普请旅人寻找他家传的鱼竿，并从海岸收集上好的蟹肉。",al={"古博·布拉普任务","海中的水果","家族和鱼竿"}},{q="格劳恩·布拉普是谁？",a="格劳恩·布拉普是古博·布拉普的矮人堂亲。古博说，格劳恩留着胡子，身上还有一股异味。",al={"格劳恩·布拉普","古博·布拉普的堂亲"}}},fp="12,91,23.367.0,28.326.0,20.116.0,37.101.0,38.101.0,19.99.0"}
P.entries["npc:gunther-arcanus"] = {n="冈瑟尔·阿坎努斯",s="在澈水湖的一座小岛上，冈瑟尔·阿坎努斯摆脱了巫妖王的控制，过着与世隔绝的生活。他相信，其他所有亡灵仍是天灾军团的奴仆。",h="在澈水湖的一座小岛上，冈瑟尔·阿坎努斯摆脱了巫妖王的控制，过着与世隔绝的生活。他相信，其他所有亡灵仍是天灾军团的奴仆。",kw={"阿坎努斯","比索","澈水湖","达拉然","冈瑟尔","埃斯沙德","肯瑞托","巫妖","通灵师","图勒","提瑞斯法林地"},ang={["class:Mage"]="作为一名在达拉然受训的法师，冈瑟尔反映了那些在Scourge入侵洛丹伦之前秘密研习禁忌通灵术的肯瑞托法师。",["class:Warlock"]="作为一名术士，冈瑟尔展现了在达拉然领袖的监管之外，对黑暗法术和亡者复生的禁忌研究能达到何种程度。",["race:Undead"]="作为一名亡灵，冈瑟尔是被遗忘者中的异例。他获得自由的经历表明，有时仅凭奥术修养与钢铁般的意志，就能挣脱巫妖王的精神控制。"},sec={{t="挣脱枷锁",b="第三次大战期间，天灾军团席卷北方，亡灵瘟疫夺去了冈瑟尔的生命，又将他复活为奴仆。凭借精湛的奥术造诣与意志，他独自挣脱了巫妖王的精神控制，无须像其他亡灵那样依靠巫妖王力量的衰退或希尔瓦娜斯的帮助。冈瑟尔相信，其他所有行尸走肉仍是天灾军团没有心智的奴仆，于是隐居在提瑞斯法林地的一座小岛上。步履蹒跚的守卫环绕着他，而他断绝了与生者和死者的一切往来。"},{t="回归的巫妖",b="被遗忘者寻求强大的盟友来对抗天灾军团，于是派出使者去取冈瑟尔的法术书。在幽暗城，比索·埃斯沙德认出了书中的笔迹，那属于他失散已久的同窗。比索为取回的法术书施加了魔法，而冈瑟尔要求消灭当地的天灾军团指挥官。通过此事，他得知还有其他亡灵挣脱了控制。确信希尔瓦娜斯的阵营确实在反抗天灾军团后，冈瑟尔与昔日的同窗立下约定，援助被遗忘者。"},{t="达拉然的学徒",b="洛丹伦沦陷之前，冈瑟尔曾是肯瑞托一名颇具潜力的学徒，在达拉然研习奥术。他与挚友比索·埃斯沙德和图勒·鸦爪不顾肯瑞托对黑暗魔法的严令禁止，秘密钻研通灵术。为了纪念彼此的兄弟情谊，三人将各自的学徒魔杖绑在一起，制成了一件传世之物。"}},faq={{q="冈瑟尔·阿坎努斯是谁？",a="冈瑟尔·阿坎努斯曾是达拉然的一名肯瑞托法师，在第三次大战期间丧生。他被复活为亡灵后，独自挣脱了巫妖王的支配，隐居在提瑞斯法林地澈水湖的一座小岛上。",al={"冈瑟尔是谁","冈瑟尔背景","冈瑟尔·阿坎努斯的故事"}},{q="为什么冈瑟尔看起来像普通的被遗忘者，而不是骸骨形态的巫妖？",a="传统的巫妖将灵魂存放在命匣中，以悬浮的可怖骸骨形态现身。冈瑟尔获得了堪比巫妖的通灵力量，却保留了自己复活后的尸身，因此仍有生前的外貌。",al={"冈瑟尔为什么像人类","冈瑟尔不是骷髅","冈瑟尔为什么是巫妖"}},{q="冈瑟尔为什么独自住在岛上？",a="摆脱巫妖王的控制后，冈瑟尔以为自己是唯一拥有自由意志的亡灵。他认定其他所有行尸走肉都是天灾军团没有心智的奴隶，于是隐居起来，并命令仆从杀死任何靠近的人。",al={"冈瑟尔为什么独居","冈瑟尔孤岛隐居","冈瑟尔为什么躲藏"}},{q="冈瑟尔是怎么认识比索·埃斯沙德的？",a="冈瑟尔和比索·埃斯沙德曾是挚友，也是达拉然肯瑞托的同窗，与图勒·鸦爪一同求学。三人将各自的学徒魔杖绑在一起，以纪念彼此的友谊。",al={"比索与冈瑟尔","冈瑟尔怎么认识比索","比索·埃斯沙德的过往"}},{q="冈瑟尔会加入被遗忘者吗？",a="会。冒险者归还了施过魔法的法术书，并杀死当地的天灾军团特工莉莉丝·奈法拉，证明自己反抗巫妖王之后，冈瑟尔便宣誓效忠比索与被遗忘者的事业。",al={"冈瑟尔会加入部落吗","冈瑟尔所属阵营","冈瑟尔是被遗忘者吗"}},{q="莉莉丝·奈法拉是谁？",a="莉莉丝·奈法拉是驻扎在提瑞斯法林地的一名天灾军团特工。冈瑟尔要求冒险者杀死她，以此证明自己效力于巫妖王的敌人，而非天灾军团。",al={"莉莉丝·奈法拉","奈法拉","冈瑟尔的目标"}}},fp="15,170,21.514.0,17.497.1,20.335.1,23.212.0,73.223.0,42.244.0,38.206.1,31.204.1,22.176.1"}
P.entries["npc:gurda-ragescar"] = {n="古尔达·怒痕",s="古尔达·怒痕在灰谷碎木岗哨西南方的一处部落营地阵亡。她与弗兰·强风在保卫营地、抵御幽暗森林中的威胁时牺牲。",h="古尔达·怒痕在灰谷碎木岗哨西南方的一处部落营地阵亡。她与弗兰·强风在保卫营地、抵御幽暗森林中的威胁时牺牲。",kw={"灰谷","弗兰·强风","古尔达","兽人","怒痕","碎木","丢失的书页"},ang={["faction:Horde"]="对部落而言，古尔达营地的陷落，见证了在灰谷森林中站稳脚跟所付出的代价。"},sec={{t="陷落的哨站",b="古尔达·怒痕和她的卫兵在碎木岗哨西南方的一处部落小营地阵亡。这座哨站位于灰谷浓密的树冠之下，深入暗夜精灵守军与野兽争夺的地带。营地被攻陷时，古尔达和弗兰·强风遭到杀害。他们最后一战留下的残迹，仍待路过的盟友发现。"},{t="阵亡的斥候",b="小径附近的旅人可能会发现古尔达遇难的现场。营地中的物品和未完成的工作，反映出部落在林间的行动，其中包括遗失的文件和因伏击而未能执行的命令。"}},faq={{q="古尔达·怒痕是谁？",a="古尔达·怒痕是一名兽人斥候，驻扎在灰谷碎木岗哨西南方的一处部落小营地。哨站被攻陷时，她与同伴一同阵亡。",al={"古尔达是谁","古尔达·怒痕的故事"}},{q="在哪里能找到古尔达·怒痕？",a="她的遗体位于碎木岗哨西南方一处被攻陷的营地，营地就在穿过灰谷中部的道路旁。",al={"古尔达的位置","古尔达·怒痕在哪里"}},{q="谁与她一同遇害？",a="他们的小营地遭到袭击时，弗兰·强风和他们的卫兵都在她身旁阵亡。",al={"谁与古尔达一同阵亡","弗兰·强风"}},{q="哪个任务与古尔达·怒痕有关？",a="古尔达与丢失的书页任务有关，这项任务需要找回散落在灰谷荒野中的文件。",al={"古尔达的任务","丢失的书页"}}},fp="14,162,15.345.0,17.221.0,22.157.0,34.104.0,29.87.0,35.107.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="温尼斯·布莱葛",s="在黑海岸沿岸，温尼斯·布莱葛注视着潮汐和冲上岸的遗骸。这位暗夜精灵住在奥伯丁，派旅者去查看北部海滩上死去的奇异海洋生物和巨大海龟。",h="在黑海岸沿岸，温尼斯·布莱葛注视着潮汐和冲上岸的遗骸。这位暗夜精灵住在奥伯丁，派旅者去查看北部海滩上死去的奇异海洋生物和巨大海龟。",kw={"奥伯丁","搁浅的海洋生物","搁浅的海龟","布莱雷贡德","黑海岸","温尼斯","卡多雷","迷雾之海","冲上岸"},ang={["class:Druid"]="身为德鲁伊，你或许会将温尼斯关于海洋生物搁浅的报告视为警讯，预示着卡利姆多的自然和谐受到了扰乱。",["faction:Alliance"]="身为联盟旅者，你依赖奥伯丁这座卡利姆多北部的主要海港。安全的航道和海滩，对所有途经此地的盟友种族都很重要。",["race:NightElf"]="对于 kaldorei 而言，黑海岸近海巨型海兽的非正常死亡，是祖地失去平衡的令人不安的征兆。温尼斯对海滩的守望，对他们意义重大。"},sec={{t="流沙的守望者",b="温尼斯·布莱葛以奥伯丁的家为据点，守望着海岸。镇上的其他人照料森林，或忙于横渡迷雾之海的航运，她则沿着海岸巡视。近来，潮水将巨大海洋生物的遗骸带上了沙滩。她请旅者搜寻海滩，带回骨骼样本，查明近海水域究竟发生了什么。"},{t="搁浅的巨兽",b="在奥伯丁南北两侧，越来越多的海洋生物和古老海龟被冲上岸来。温尼斯请旅者检查这些尸体和骸骨。她希望查明是什么将这些生物逼上海滩，或夺去了它们的生命，并了解卡利姆多北部近海水域中的危险。"}},faq={{q="温尼斯·布莱葛是谁？",a="温尼斯·布莱葛是一位住在黑海岸奥伯丁的暗夜精灵，研究着海岸沿线的异常变化。她派旅者勘察海滩，调查大海冲上岸来的东西。",al={"温尼斯是谁","温尼斯 奥伯丁","温尼斯的故事"}},{q="在哪里可以找到温尼斯·布莱葛？",a="温尼斯·布莱葛就在奥伯丁，位于黑海岸雾气笼罩的海滨，靠近海滩和码头。",al={"温尼斯在哪里","温尼斯的位置","寻找温尼斯"}},{q="她为什么关注搁浅的生物？",a="死去的海龟和其他奇异海洋生物，可能意味着黑海岸近海水域的平衡遭到了破坏，或有尚未现身的捕食者潜伏其中。温尼斯检查海岸上的遗骸，试图找出原因。",al={"海龟为何搁浅","她为何需要骨骼","冲上岸任务"}},{q="温尼斯提供哪些任务？",a="温尼斯派旅者调查黑海岸沿岸被冲上岸的海洋生物和海龟，并接收他们带回的发现。",al={"温尼斯的任务","她会给予什么"}},{q="她属于塞纳里奥议会或 哨兵 吗？",a="温尼斯是一位月亮的夜精灵女祭司，在奥伯丁为 艾露恩姐妹会 效力。她既不是塞纳里奥德鲁伊，也不是哨兵指挥官，但她和同族一样，关心着黑海岸的自然平衡。",al={"温尼斯的阵营","温尼斯是德鲁伊吗"}},{q="她的名字有什么含义？",a="温尼斯的姓氏布莱葛是由“长腿金发女郎”的字母重新排列而成的，是这个世界的创造者留下的一点诙谐趣味。",al={"布莱葛 的含义","温尼斯名字彩蛋"}}},fp="21,227,29.406.0,19.292.0,29.190.0,39.109.0,43.177.0,32.142.0,52.208.0,24.109.0"}
P.entries["npc:hagar-lightninghoof"] = {n="哈加尔·雷蹄",s="哈加尔·雷蹄是一名牛头人斥候，驻守在千针石林高处的乱风岗。传闻峡谷深处藏着一窝奇异的卵，他因此展开调查，追寻一枚受到当地风蛇拼死守护的异型卵。",h="哈加尔·雷蹄是一名牛头人斥候，驻守在千针石林高处的乱风岗。传闻峡谷深处藏着一窝奇异的卵，他因此展开调查，追寻一枚受到当地风蛇拼死守护的异型卵。",kw={"异型卵","阿利卡拉","乱风岗","哈加尔","雷蹄","莫特加·火鬃","千针石林","风蛇"},ang={["faction:Horde"]="哈加尔驻守在远高于谷底的乱风岗，依靠能干的部落勇士闯入那些普通斥候无法安全进入的险恶巢穴。",["race:Tauren"]="对牛头人旅者而言，帮助哈加尔会带来令人心潮澎湃的发现：古老传说中的阿利卡拉，那有翼的复仇化身，就活生生地存在于下方的峡谷之中。"},sec={{t="奇异的卵",b="驻守在乱风岗高耸的崖顶期间，哈加尔·雷蹄听到了一个传闻：下方洞穴深处藏着一枚不同寻常的卵。当地风蛇守护巢穴时异常凶猛，让好奇的斥候无法靠近。哈加尔正在寻找一位敢于闯入风蛇巢穴的冒险者，希望能亲自研究这枚卵，弄清究竟是什么样的生物，能让峡谷中天生的掠食者表现出如此强烈的守护本能。"},{t="破壳而出的传说",b="当一位冒险者终于取回这枚卵，将它带到乱风岗时，卵就在哈加尔面前孵化了，里面是一条幼小的风蛇，模样酷似传说中的阿利卡拉——牛头人民间传说中备受敬畏的灵体，被视为复仇的化身。意识到这种生物的归来在文化与信仰上意义重大，哈加尔立刻派这位旅者去请教长者莫特加·火鬃。"}},faq={{q="哈加尔·雷蹄是谁？",a="哈加尔·雷蹄是一名住在千针石林乱风岗的牛头人任务给予者。他调查峡谷中的异常野生生物，尤其是一枚据说藏在附近洞穴深处的奇异风蛇卵。",al={"哈加尔是谁","哈加尔·雷蹄的职责","哈加尔的故事"}},{q="在哪里可以找到哈加尔·雷蹄？",a="他位于乱风岗顶端，这处部落的中心哨站坐落在千针石林中部巨大的石柱之上。",al={"哈加尔在哪","哈加尔·雷蹄的位置","乱风岗的哈加尔"}},{q="哈加尔寻找的“异型卵”是什么？",a="异型卵是一枚不同寻常的卵，由地下巢穴中的风蛇守护。哈加尔请冒险者将它取回，以便研究它究竟是什么。",al={"异型卵","这枚卵是什么","风蛇卵"}},{q="哈加尔向谁请教这枚卵的事？",a="哈加尔派冒险者去找莫特加·火鬃交谈，这位乱风岗的长者对牛头人传统有着更深的了解。",al={"狂暴的风蛇 找谁交任务","哈加尔的后续任务","哈加尔之后去哪"}}},fx={d173f224={q="哈加尔·雷蹄效忠哪一方？",a="哈加尔·雷蹄效忠部落和他的牛头人同胞。他驻扎在高耸的乱风岗尖塔之上，只把任务交给那些证明自己有能力冒险深入下方危险峡谷的部落勇士。",al={"哈加尔·雷蹄的阵营","哈加尔是部落成员吗"}},c809f2c7={q="哈加尔·雷蹄为什么会在乱风岗？",a="哈加尔听说风蛇巢穴中发现了一枚奇特的异型卵后，便前往千针石林。这个奇异的发现令他十分好奇，于是他在乱风岗扎营，希望找到一位胆识过人的人，能越过风蛇守卫将它取回。",al={"哈加尔为什么在这里","哈加尔为什么来到千针石林"}},a74332ba={q="哈加尔·雷蹄与谁关系密切？",a="哈加尔与乱风岗的牛头人守卫并肩行事，并与莫特加·火鬃密切商议。当他的调查牵涉到古老的牛头人传说和神圣的征兆时，他便向莫特加请教。",al={"哈加尔的关系","哈加尔与谁共事"}}},fp="19,175,18.377.0,14.315.1,27.162.0,39.143.0,45.135.1,37.127.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Halaan Hawk-Eye",s="Halaan Hawk-Eye是一名Skyborne哨兵，驻守在泽风岛森达尔村的瞭望塔顶。他既没有魔法感知力，也不具备同伴们神秘的skysight，只能凭借敏锐的肉眼观察岛上的周边地区。他在高处监视远方的锚定塔，并提醒来访者，这些塔中的奥术能量正变得不稳定。",h="Halaan...",kw={"锚定塔","哈兰","鹰眼","天行者","天眼","森达尔村","泽风岛"},ang={["race:Skyborne"]="Halaan代表着那些缺乏操纵魔网或使用skysight天赋的Skyborne，他们凭借坚定的警戒和履行武职为自己的族群效力。"},sec={{t="没有魔法的守望者",b="Halaan Hawk-Eye驻守在森达尔村上方的高处，尽管没有许多Skyborne与生俱来的天赋，他仍为族人效力。他无法汲取泽风岛地下魔网中流淌的奥术能量，也无法通过神秘的skysight窥视世界之间的景象。因此，Halaan完全依靠自己敏锐的感官。他从瞭望塔上的高处扫视天际，观察岛上的锚定塔，提醒人们留意其中愈发狂乱、起伏不定的奥术能量。"}},faq={{q="哈兰·鹰眼是谁？",a="哈兰·鹰眼是一名天裔哨兵，驻守在泽风岛俯瞰森达尔村的瞭望塔顶。他观察周围的土地，并提醒冒险者，岛上的锚定塔正受到紊乱魔法的影响。",al={"哈兰·鹰眼","哈兰是谁","桑达尔瞭望塔非玩家角色"}},{q="哈兰与其他天裔有何不同？",a="与许多同族不同，哈兰既没有能够穿透世界之间帷幕的神秘天空视界，也没有驾驭泽风岛地下魔网的天赋。他依靠的是敏锐的肉眼和天生的观察力。",al={"哈兰的能力","哈兰能否使用魔法","哈兰的天空视界"}},{q="哈兰为何担忧锚定塔？",a="哈兰监视着远方的锚定塔，发现它们释放的魔法能量变得紊乱、起伏不定，给泽风岛的稳定带来了未知的风险。",al={"锚定塔出了什么问题","泽弗拉斯的锚定装置问题"}},{q="在哪里可以找到哈兰·鹰眼？",a="他站在泽风岛森达尔村的木制瞭望塔顶，眺望着远方的天际。",al={"哈兰在哪里","哈兰的位置"}}},fx={d6a0f6c4={q="哈兰·鹰眼属于哪一方？",a="哈兰是天裔的一员，与泽风岛上的同族站在一起。虽然他不像同伴那样天生能够施展魔网魔法，也没有超凡的天空视界，他仍忠心地为族人效力，守望森达尔村，并提醒旅人注意威胁家园的动荡正在逐渐加剧。",al={"哈兰的阵营","哈兰·鹰眼属于哪一方","哈兰为谁效力"}},e8313a77={q="哈兰·鹰眼为什么驻守在瞭望塔？",a="哈兰驻守在森达尔村的塔顶，因为他无法像其他天裔那样汲取当地的魔网能量或施展魔法天空视界。因此，他凭借敏锐的天生视力巡视泽风岛，监视远处的锚定塔柱，留意它们的魔法稳定性开始减弱。",al={"哈兰·鹰眼为什么在这里","哈兰为什么在瞭望塔","哈兰在此的原因"}}},fp="15,194,24.375.0,23.191.0,48.176.0,46.151.0,33.122.0"}
P.entries["npc:hamhock"] = {n="哈姆霍克",s="在暴风城监狱里，哈姆霍克仍被关在暴动的囚犯之中。这个体型庞大的双头食人魔是监狱里最残暴的囚犯之一。",h="在暴风城监狱里，哈姆霍克仍被关在暴动的囚犯之中。这个体型庞大的双头食人魔是监狱里最残暴的囚犯之一。",kw={"暮色森林","哈姆霍克","食人魔","监狱","碎拳","暴风城","双头"},ang={["class:Warrior"]="要制服哈姆霍克，战士就必须在监狱狭窄的走廊里，正面迎击他那庞大身躯的蛮力。",["faction:Alliance"]="一个双头食人魔在首都街道下肆意横行，足以说明城里的卫兵已经彻底失去了对监狱的控制。"},sec={{t="铁窗后的蛮横巨怪",b="哈姆霍克是暴风城监狱里一个身形高大的双头食人魔。这座监狱原本用来关押小偷、杀人犯和政见异议者，因此，他庞大的身躯在牢房间显得格外慑人。囚犯们发动暴乱并控制监狱后，哈姆霍克仍留在混乱之中，碾碎任何踏入他所在监区的人。"},{t="来历不明",b="没有记载说明哈姆霍克是如何被捕的，也没有记载说明他为何会与暴风城的盗贼和异议者关在一起。无论他因何被送进监狱，如今他都是这里最危险的囚犯之一。"}},faq={{q="哈姆霍克是谁？",a="哈姆霍克是被关押在暴风城监狱里的一个体型庞大的双头食人魔。在迪菲亚囚犯领导的暴乱中，他是潜藏在监狱走廊深处的威胁。",al={"哈姆霍克","监狱里的食人魔是谁","监狱食人魔首领"}},{q="一个食人魔怎么会被关进暴风城监狱？",a="没有记载说明哈姆霍克是如何被捕或被带到暴风城的。",al={"哈姆霍克为何入狱","哈姆霍克如何被捕","监狱里为何有食人魔"}},{q="哈姆霍克与迪菲亚暴徒是盟友吗？",a="迪菲亚头目领导着监狱里的叛乱，但没人知道哈姆霍克是在与他们合作，还是仅仅沉醉于破败牢房间的混乱。",al={"哈姆霍克是迪菲亚成员吗","哈姆霍克迪菲亚潜行者","哈姆霍克为巴基尔效力吗"}},{q="哈姆霍克与暮色森林的食人魔有关吗？",a="没有任何线索表明哈姆霍克与暮色森林的食人魔有关。暮色森林沃古尔食人魔山的碎拳食人魔，是距离暴风城最近的食人魔氏族，但没有记载说明哈姆霍克来自何处。",al={"哈姆霍克属于碎拳吗","哈姆霍克沃古尔","沃古尔食人魔监狱"}},{q="哈姆霍克与某项特定的悬赏或任务有关吗？",a="没有悬赏或城内通缉令提到哈姆霍克的名字。他是冒险者清剿这座暴乱据点时会遇到的威胁。",al={"哈姆霍克任务","有哈姆霍克相关任务吗","哈姆霍克悬赏"}},{q="双头食人魔有什么特别之处？",a="双头食人魔的两个头各有独立的性格，而且往往比独头同族更狡猾，或更擅长魔法。因此，对普通狱卒而言，哈姆霍克格外危险。",al={"双头食人魔背景故事","为何有两个头"}}},fp="7,145,19.317.0,13.188.0,15.157.0,49.65.0,42.152.0,44.190.0,48.115.0,37.203.0"}
P.entries["npc:hana-zua"] = {n="哈纳祖",s="在试炼谷，哈纳祖在峡谷山脊上遭遇萨科斯后，负伤倒地。这位黑暗之矛斥候正等待年轻的部落新兵前来救援。",h="在试炼谷，哈纳祖在峡谷山脊上遭遇萨科斯后，负伤倒地。这位黑暗之矛斥候正等待年轻的部落新兵前来救援。",kw={"黑暗之矛","杜隆塔尔","哈纳祖","萨科斯","毒蝎","试炼谷"},ang={["faction:Horde"]="对部落而言，帮助哈纳祖活下来，并为他报仇，是对你是否忠诚、是否做好战斗准备的初步考验。",["race:Troll"]="作为一名在杜隆塔尔踏上旅途的黑暗之矛新兵，你可能会在当地野兽出没的险境中发现一位受伤的同胞。保护你的新盟友至关重要。"},sec={{t="倒在剧毒之下的斥候",b="哈纳祖负伤倒在试炼谷上方的山脊上。这位黑暗之矛斥候遭遇了萨科斯，一只在峭壁间出没的凶猛毒蝎，它的毒刺险些要了他的命。他无法动弹，也无法返回营地，只能躺在尘土中，等待路过的新兵。他需要他们杀死萨科斯，并将他的困境告知大兽穴的人。"}},faq={{q="哈纳祖是谁？",a="哈纳祖是一名受伤的黑暗之矛巨魔斥候，身处杜隆塔尔的试炼谷。山脊上的野兽伏击了他，使他身中剧毒。",al={"哈纳祖","哈纳祖是谁","试炼谷受伤的巨魔"}},{q="哈纳祖遭遇了什么？",a="萨科斯是一只潜伏在训练场上方峭壁间的巨大毒蝎，它击倒了哈纳祖。它的毒液使他无法动弹，也无法返回安全的地方。",al={"哈纳祖为何受伤","谁使哈纳祖中毒","哈纳祖的伤势"}},{q="他请求旅人做什么？",a="哈纳祖请求旅人杀死萨科斯，带回这头野兽的螯作为凭证，并将他的状况告知大兽穴的教官。",al={"哈纳祖任务","哈纳祖想要什么"}}},fp="8,105,23.325.0,16.128.0,26.140.0,33.161.0"}
P.entries["npc:hands-springsprocket"] = {n="汉兹·跳链",s="在寒脊山小径，汉兹·跳链艰难地维持着山谷与卡拉诺斯之间的物资运输。石腭穴居人已经封锁了这条路线。",h="在寒脊山小径，汉兹·跳链艰难地维持着山谷与卡拉诺斯之间的物资运输。石腭穴居人已经封锁了这条路线。",kw={"寒脊山小径","寒脊山谷","丹莫罗","汉兹·跳链","卡拉诺斯","跳链","送给塔诺克的补给"},ang={["faction:Alliance"]="汉兹维持着寒脊山谷的矮人新兵与丹莫罗腹地各处定居点之间的物资运输。",["race:Gnome"]="汉兹展现了侏儒与矮人盟友一道在丹莫罗建立贸易联系的决心。"},sec={{t="山径受阻",b="在寒脊山小径入口，汉兹·跳链的物资运输被石腭穴居人阻断了。他平日里负责向雷酒酿制厂和卡拉诺斯的旅店运送补给。穴居人占据了通往寒脊山谷外的地下隧道，商贸往来和行人通行都已中断。如今，汉兹只能依靠有能力的旅人，将装有必需物资的箱子运过这条危险的山间通道。"}},faq={{q="汉兹·跳链是谁？",a="汉兹·跳链是一名驻留在寒脊山谷的侏儒，就在寒脊山小径入口外。他负责向丹莫罗地势较低的地区运送补给。",al={"汉兹·跳链是谁","汉兹·跳链的故事","这个侏儒是谁"}},{q="他为什么需要人帮忙运送补给？",a="穴居人石腭盘踞在寒脊山谷通往丹莫罗其他地区的山径中。没有武装护卫或能干的旅人相助，日常运输也变得十分危险。",al={"汉兹为何需要帮助","寒脊山小径的补给","补给为何受阻"}},{q="他的补给要送往哪里？",a="汉兹安排将物资运往卡拉诺斯，其中包括塔诺克·霜锤和当地旅店老板所需的货物，他们都依赖从雪峰另一侧运来的补给。",al={"补给运往哪里","汉兹的补给路线","箱子交给谁"}}},fx={d7333ab8={q="汉兹·跳链效忠哪一方？",a="汉兹是联盟的忠诚一员，也是丹莫罗矮人们的朋友。和许多因诺莫瑞根的灾难而流离失所的侏儒一样，他与铁炉堡的盟友紧密合作，负责后勤与货物运送，为卡拉诺斯等当地聚落提供支援。",al={"汉兹·跳链阵营","汉兹·跳链是联盟吗"}},["8576a218"]={q="汉兹·跳链想要什么？",a="汉兹希望有人将他的货物安全送过寒脊山小径，交给卡拉诺斯雷酒酿制厂的塔诺克·霜锤。最近，隧道内充斥着大量敌对的石腭穴居人，他的货运因此完全停滞，急需一位冒险者带着货箱穿过险境。",al={"汉兹想要什么","汉兹·跳链目标"}},d21580a2={q="汉兹·跳链与谁有来往？",a="汉兹经常与塔诺克·霜锤做生意，后者是卡拉诺斯雷酒酿制厂的旅店老板。每当低地需要补给，汉兹就会安排货物经由山道运送，道路变得危险时，他便依靠旅人帮忙接续运输。",al={"汉兹与谁合作","汉兹·跳链关系"}}},fp="20,145,24.392.0,28.147.0,38.169.0,32.155.0"}
P.entries["npc:hansel-heavyhands"] = {n="汉瑟尔·重拳",s="汉瑟尔·重拳是一名体格异常庞大的黑铁矮人，随瑟银兄弟会驻守在灼热峡谷的瑟银哨塔高处。哨站的监工们派他执行危险的野外任务，他却总以各种五花八门的小病小痛为由，把危险的差事转交给过路的冒险者。他魁梧的身躯在同族中格外显眼，只是他对野外工作的热情远不及他的块头。",h="汉瑟尔·重拳是一名体格异常庞大的黑铁矮人，随瑟银兄弟会驻守在灼热峡谷的瑟银哨塔高处。哨站的监工们派他执行危险的野外任务，他却总以各种五花八门的小病小痛为由，把危险的差事转交给过路的冒险者。他魁梧的身躯在同族中格外显眼，只...",kw={"大熔炉","黑铁","汉瑟尔·重拳","熏火龙","熔岩蜘蛛","灼热峡谷","瑟银兄弟会","瑟银哨塔"},ang={["faction:Alliance"]="尽管联盟通常与黑铁的效忠者交战，瑟银兄弟会却欢迎任何有力气干活的人，因此想在当地接些悬赏差事，找汉瑟尔就很方便。",["faction:Horde"]="部落旅人会觉得汉瑟尔庞大的体格让人联想到兽人或牛头人，不过，他不愿投身光荣战斗的态度肯定会让人皱眉。",["race:Dwarf"]="铜须和蛮锤矮人或许会惊叹于汉瑟尔的巨大身躯，也可能嗤之以鼻，纳闷一个整天逃避实际劳作的黑铁矮人怎么能长得如此高大。"},sec={{t="矮人中的巨人",b="即便以黑铁氏族普遍宽肩壮硕的标准来看，汉瑟尔·重拳也堪称异类。他身躯庞大，比同族高出许多，身高和肩宽几乎能与兽人相比，光是站在那里，就像一名为前线厮杀而生的战士。然而，尽管体格威猛，名号响亮，汉瑟尔似乎对任何不必要的体力消耗都毫无兴趣，更愿意待在火山灰上方高处那片相对安全的瑟银兄弟会营地里。"},{t="借口大师",b="监工斯克兰格和大铁匠博恩奈特经常给汉瑟尔派下苦差事，要他去清剿潜伏在下方熔渣坑中的炽热野兽。每当被要求清除大熔炉里四处爬行、捕食猎物的熏火龙时，汉瑟尔就以脚痛为由推脱。每当被命令消灭遍布灼热荒地的巨型熔岩蜘蛛时，他又声称那片该死的火山山脊“气候严寒”，害他得了重感冒。因此，只要有佣兵愿意冒险穿越岩浆流，汉瑟尔随时都有委托可交给他们。"}},faq={{q="汉瑟尔·重拳是谁？",a="汉瑟尔·重拳是一名效力于瑟银兄弟会的黑铁矮人。他驻守在灼热峡谷的瑟银哨塔，以惊人的庞大体格和逃避危险野外差事的过人本领而闻名。",al={"汉瑟尔是谁","汉瑟尔·重拳背景故事","汉瑟尔矮人"}},{q="为什么汉瑟尔比其他矮人大那么多？",a="他的庞大体格没有明确的解释。汉瑟尔就是一名体型异常巨大的黑铁矮人，肩膀宽阔，四肢粗壮，整体身形接近兽人。",al={"汉瑟尔为什么这么大","灼热峡谷巨型矮人","兽人大小的矮人"}},{q="汉瑟尔会给冒险者什么任务？",a="汉瑟尔招募过路旅人，替他完成上级交办的任务。具体来说，他会付钱雇佣佣兵，消灭灼热峡谷各处的巨型熔岩蜘蛛，并深入大熔炉猎杀熏火龙。",al={"汉瑟尔·重拳任务","汉瑟尔提供什么任务"}},{q="为什么汉瑟尔不自己干活？",a="每当危险的差事找上门，汉瑟尔总能想出借口。他声称脚痛，无法进入大熔炉对付熏火龙；而当他被命令去猎杀熔岩蜘蛛时，他又抱怨酷热的灼热峡谷冷得让他感冒了。",al={"汉瑟尔为什么不战斗","汉瑟尔的借口"}},{q="汉瑟尔效忠于黑铁皇帝吗？",a="汉瑟尔属于瑟银兄弟会，这是一个脱离了达格兰·索瑞森皇帝和拉格纳罗斯的黑铁矮人反叛派系。他对造访瑟银哨塔的联盟和部落旅人都保持中立。",al={"汉瑟尔效忠暗炉吗","汉瑟尔是敌人吗"}},{q="在哪里可以找到汉瑟尔·重拳？",a="他位于瑟银哨塔，这座岩石哨站坐落在北部山脊上，俯瞰着灼热峡谷。",al={"汉瑟尔位置","汉瑟尔在哪里"}}},fp="17,169,21.272.0,17.378.0,25.159.0,48.160.0,43.155.0,37.186.0,41.211.0,37.119.0"}
P.entries["npc:harb-clawhoof"] = {n="哈布·爪蹄",s="哈布·爪蹄在血蹄村附近照料牛头人的科多兽。他将它们交给有资格的牛头人骑手，以及深受雷霆崖信任的勇士。",h="哈布·爪蹄在血蹄村附近照料牛头人的科多兽。他将它们交给有资格的牛头人骑手，以及深受雷霆崖信任的勇士。",kw={"血蹄村","哈布·爪蹄","科多兽训练师","科多兽商人","坐骑商人","莫高雷科多兽","雷霆崖坐骑"},ang={["faction:Horde"]="身为兽人、巨魔或被遗忘者，能从哈布那里获得一头科多兽，象征着你的荣耀与友谊得到了雷霆崖长者的认可。",["race:Tauren"]="身为牛头人，哈布·爪蹄为你提供的坐骑承载着你的传承，既能助你穿行莫高雷，也与你的游牧传统紧密相连。"},sec={{t="大型科多兽饲养者",b="哈布·爪蹄在血蹄村附近照料科多兽。这些庞大的野兽能驮着重物长途跋涉，对牛头人在平原上的出行和劳作至关重要。哈布照料并训练每一头科多兽，再为它配上受牛头人敬重的骑手。"},{t="平原上的坐骑",b="牛头人赢得信任后，便能骑乘哈布的科多兽，而外来者则要接受更严格的审视。科多兽体形庞大，脾性独特，不熟悉它们的人很难驾驭。其他种族的盟友必须证明自己的忠诚，并在雷霆崖达到崇拜声望，才能骑乘哈布的坐骑。"}},faq={{q="在哪里可以找到哈布·爪蹄？",a="哈布·爪蹄照看着血蹄村外围的科多兽围栏，那里位于莫高雷中部，就在雷霆崖以南。",al={"哈布·爪蹄位置","哈布·爪蹄在哪里","科多兽商人位置"}},{q="哈布·爪蹄出售什么？",a="哈布出售数种科多兽坐骑，包括棕色和灰色科多兽，以及供老练骑手骑乘的重甲大型科多兽。",al={"哈布卖什么","哈布的坐骑","科多兽商人货物"}},{q="其他种族能从哈布那里购买科多兽吗？",a="可以。牛头人可以直接购买科多兽，其他部落种族则必须在雷霆崖达到崇拜声望，并向部族证明自己，哈布才会将科多兽托付给他们。",al={"兽人能买科多兽吗","巨魔能骑科多兽吗","科多兽声望要求"}},{q="为什么科多兽对牛头人如此重要？",a="科多兽适应牛头人的游牧生活，也适应卡利姆多中部的开阔平原。它们驮运重物，充当作战坐骑，还能在崎岖的土地上运送贸易货物。",al={"牛头人与科多兽的背景故事","为什么选择科多兽"}}},fp="13,175,25.264.0,20.291.0,31.129.0,29.124.0,35.169.0,41.160.0"}
P.entries["npc:harken-windtotem"] = {n="哈肯·风之图腾",s="在血蹄村，哈肯·风之图腾指引年轻的猎人穿行于莫高雷的平原。他传授族人的传统，并要求猎人和旅者证明自己的追踪与采集本领。",h="在血蹄村，哈肯·风之图腾指引年轻的猎人穿行于莫高雷的平原。他传授族人的传统，并要求猎人和旅者证明自己的追踪与采集本领。",kw={"血蹄村","哈肯·风之图腾","莫高雷","猛鹫狩猎","牛头人","风之图腾"},ang={["class:Hunter"]="作为途经血蹄村的猎人，你可以击落空中的猛鹫，检验自己的射术与采集本领。",["race:Tauren"]="作为牛头人，你能看出哈肯·风之图腾对祖传狩猎之道的敬重：在平原上严守纪律、自给自足，并尊重 Earth Mother 的野兽。"},sec={{t="血蹄村的猎手",b="在血蹄村中心附近，哈肯·风之图腾指引着学习牛头人狩猎之道的人们。在莫高雷的平原上生活，既要敬重自然，也要掌握维系部族生计的本领。哈肯派年轻的猎人去猎捕在台地上空盘旋的猛鹫，以此考验他们。他们收集这些鸟的羽毛，展现自己的耐心、准头，以及只取所需的谨慎。"}},faq={{q="哈肯·风之图腾是谁？",a="哈肯·风之图腾是血蹄村的一名牛头人猎手，在那里向旅者和年轻的猎人传授牛头人追踪与狩猎的传统。",al={"哈肯·风之图腾背景故事","哈肯 是谁"}},{q="在哪里可以找到哈肯·风之图腾？",a="哈肯·风之图腾就在血蹄村，位于莫高雷中部、雷霆崖以南。",al={"哈肯 位置","哈肯·风之图腾在哪里"}},{q="哈肯会交给冒险者什么任务？",a="哈肯·风之图腾派猎人前往莫高雷的草原，猎杀野生猛鹫，收集它们坚韧的飞羽。",al={"哈肯·风之图腾任务","猛鹫狩猎任务"}},{q="哈肯与 博万·风之图腾 有亲缘关系吗？",a="哈肯·风之图腾与 博万·风之图腾 拥有相同的氏族名，暗示着部族亲缘或家族联系。哈肯专注于莫高雷当地的狩猎。",al={"哈肯 与 博万 有亲缘关系吗","与 博万·风之图腾 的关系"}}},fp="16,199,21.359.0,24.124.0,36.94.0,43.117.0,37.147.0"}
P.entries["npc:harlan-bagley"] = {n="哈兰·巴格雷",s="在暴风城的贸易区，哈兰·巴格雷为狮心武器库备足货物，供顾客选购。他的店铺位于该区北侧，为市民和到访的冒险者提供服务。",h="在暴风城的贸易区，哈兰·巴格雷为狮心武器库备足货物，供顾客选购。他的店铺位于该区北侧，为市民和到访的冒险者提供服务。",kw={"护甲商","哈兰·巴格雷","狮心武器库","商人","暴风城","贸易区"},ang={["faction:Alliance"]="作为联盟商人，哈兰·巴格雷协助为王国首都供应装备和货物。周边地区的威胁让常规补给线路面临风险。"},sec={{t="狮王之傲军械库",b="哈兰·巴格雷经营着狮心武器库，店铺位于暴风城贸易区的北侧。他管理库存，在柜台后出售防具。商贸往来和各地信使为店铺带来补给。王国首都面临着远方的边境冲突和物资短缺。"}},faq={{q="哈兰·巴格雷是谁？",a="哈兰·巴格雷经营着狮心武器库，这是一家位于暴风城贸易区的装备店。他是一名人类店主，也是一名商人。",al={"哈兰是谁","哈兰·巴格雷的故事","狮心武器库商人"}},{q="在哪里可以找到哈兰·巴格雷？",a="你可以在狮心武器库内找到哈兰·巴格雷，店铺位于暴风城贸易区中央广场的北面。",al={"哈兰·巴格雷的位置","哈兰在哪里","狮心武器库的位置"}},{q="他在暴风城的商业活动中扮演什么角色？",a="哈兰·巴格雷在王国首都供应护甲和装备。他有时会雇用冒险者运送货物，并保障运往店里的补给安全抵达。",al={"哈兰卖什么","哈兰·巴格雷的生意"}}},fx={["13bd1b18"]={q="哈兰·巴格雷效忠哪一方？",a="哈兰·巴格雷是联盟的一名普通公民和商人，效忠暴风城王国。他在贸易区公开经营生意，为途经首都的冒险者、卫兵和守卫者提供服务。",al={"哈兰·巴格雷阵营","哈兰·巴格雷是联盟吗"}},d342d373={q="哈兰·巴格雷想要什么？",a="经营狮心武器库需要稳定的原材料供应和精湛的工艺。哈兰一心要让自己的军械店货源充足，随时为顾客服务，因此经常请旅人帮忙获取货物，补充库存。",al={"哈兰想要什么","哈兰·巴格雷动机","哈兰为什么需要补货"}},["0eb71712"]={q="哈兰·巴格雷为什么在这里？",a="哈兰经营着狮心武器库，店铺位于暴风城繁华的贸易区北侧。他留在这里，为络绎不绝的顾客、铁匠和士兵提供服务，这些人正在置办装备，准备踏上穿越艾泽拉斯的旅途。",al={"哈兰·巴格雷为什么在暴风城","哈兰为什么在贸易区"}}},fp="13,186,20.275.0,21.134.0,31.119.0,47.158.0"}
P.entries["npc:harlo-barnaby"] = {n="哈尔罗·巴纳比",s="在米奈希尔港，哈尔罗·巴纳比身上仍留着丹莫德陷落时的伤痕。这位矮人难民逃过了黑铁的突袭，向旅人讲述北方沼泽中的惨剧，提醒他们小心。",h="在米奈希尔港，哈尔罗·巴纳比身上仍留着丹莫德陷落时的伤痕。这位矮人难民逃过了黑铁的突袭，向旅人讲述北方沼泽中的惨剧，提醒他们小心。",kw={"黑铁","丹莫德","哈尔罗·巴纳比","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你知道丹莫德的陷落威胁着连接沼泽地与阿拉希的重要陆桥。Harlo的警告对联盟部队至关重要。",["race:Dwarf"]="身为矮人，你从Harlo身上看到了那场血腥氏族战争留下的活生生的伤痕，对手正是企图切断卡兹莫丹与北方联系的背信弃义的黑铁矮人。"},sec={{t="逃离丹莫德",b="黑铁矮人毫无预兆地袭击了北方要塞丹莫德，哈尔罗·巴纳比被迫逃离。混乱中，一柄飞来的斧头正中他的后背。这一击让他失去了知觉，但他仍活着穿过了沼泽地。哈尔罗在米奈希尔港醒来时，身上已包扎好绷带，虽然保住了性命，却留下了伤痕与屠杀的记忆。他无法返回丹莫德，只能敦促联盟冒险者前往他昔日家园仍在冒烟的废墟调查。"}},faq={{q="哈尔罗·巴纳比是谁？",a="哈尔罗·巴纳比在黑铁对丹莫德的突袭中幸存，如今住在米奈希尔港。他是一名铁炉堡矮人。",al={"哈尔罗·巴纳比","哈尔罗是谁","米奈希尔港矮人"}},{q="哈尔罗·巴纳比是怎么来到米奈希尔港的？",a="哈尔罗·巴纳比逃离丹莫德时，被一柄掷来的斧头击中了后背。他在撤退途中失去了知觉，醒来时已身在米奈希尔港，受到当地治疗师的照料。",al={"哈尔罗怎么来到这里的","哈尔罗·巴纳比背伤"}},{q="丹莫德发生了什么？",a="黑铁矮人从萨多尔大桥向南推进，攻陷并摧毁了丹莫德。这次袭击消灭了当地的矮人守军，迫使幸存者逃入湿地。",al={"丹莫德陷落","丹莫德发生了什么"}}},fp="13,180,20.449.0,21.116.0,48.176.0,26.174.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="海格纳·重枪",s="在寒脊山小径通往卡拉诺斯的雪路上，海格纳·重枪为猎人和巡山人供应枪械与弹药。",h="在寒脊山小径通往卡拉诺斯的雪路上，海格纳·重枪为猎人和巡山人供应枪械与弹药。",kw={"弹药","寒脊山小径","丹莫罗","枪械师","海格纳·重枪","卡拉诺斯","靶场"},ang={["class:Hunter"]="作为一名从寒脊山谷前往丹莫罗皑皑雪峰的猎人，你可以从海格纳那里获得弹丸、弹药袋和备用枪械。",["race:Dwarf"]="作为一名矮人，你可以在海格纳的路边靶场与旅人一同练习枪法。"},sec={{t="路边的枪械师",b="在寒脊山小径与卡拉诺斯之间，海格纳的小营地为矮人射手、旅人和当地民兵提供服务。山中的居民常到这处颇受欢迎的靶场练习射击，以应对丹莫罗的野兽。前来练习的射手络绎不绝，海格纳因此需要依靠矮人工程师罗斯洛·鲁治不断送来弹药。"}},faq={{q="海格纳·重枪是谁？",a="海格纳·重枪在寒脊山小径与卡拉诺斯之间的路边经营着一处枪械师营地和露天靶场。",al={"海格纳是谁","海格纳·重枪 非玩家角色","丹莫罗的枪械师"}},{q="海格纳的弹药从哪里来？",a="海格纳的弹药来自罗斯洛·鲁治，这位矮人工程师身在丹莫罗的另一处地方，为靶场供应弹药。",al={"海格纳的供应商","谁为重枪供货","重枪的弹药任务"}},{q="海格纳为当地矮人提供什么服务？",a="海格纳为当地猎人和民兵供应枪械与弹丸。他还为途经丹莫罗的射手提供练习用的靶场。",al={"海格纳为何在这里","海格纳的靶场","重枪的职责"}}},fx={f158c8ab={q="海格纳·重枪效忠哪一方？",a="海格纳坚定地效忠铁炉堡与联盟。他驻在山路沿线，为丹莫罗当地的民兵、守卫者和猎人提供可靠的火器，保护王国白雪覆盖的山道，抵御步步逼近的威胁。",al={"海格纳·重枪阵营","海格纳是联盟吗","海格纳为谁效力"}},["932ff4bf"]={q="海格纳·重枪想要什么？",a="海格纳需要稳定的弹药供应，才能维持工坊和练习靶场的运转。当地射手和民兵不断在他的营地训练并补充弹药，使他的库存消耗得很快，需要他的工程师伙伴罗斯洛·鲁治定期送货。",al={"海格纳需要什么","海格纳·重枪目标","海格纳任务"}},["3c40a283"]={q="海格纳·重枪为什么会在这条路边？",a="他在寒脊山小径与卡拉诺斯之间那条人来人往的道路旁，设立了营地和射击场。这里位置理想，既能为刚走出山谷的新兵提供装备，也能为保卫丹莫罗中部雪地的巡逻兵提供补给。",al={"海格纳为何在此","海格纳营地位置","海格纳为何扎营"}}},fp="17,132,22.305.0,25.117.0,37.106.0,42.148.0"}
P.entries["npc:henze-faulk"] = {n="亨兹·法奥克",s="在艾尔文森林的英雄哨岗附近，亨兹·法奥克身负重伤，倒在地上。他为贾森·坦诺姆挡下了迪菲亚潜行者的袭击，如今正等待圣骑士的援助。",h="在艾尔文森林的英雄哨岗附近，亨兹·法奥克身负重伤，倒在地上。他为贾森·坦诺姆挡下了迪菲亚潜行者的袭击，如今正等待圣骑士的援助。",kw={"迪菲亚","艾尔文森林","贾森·坦诺姆","亨兹·法奥克","英雄哨岗","复活","生命符记","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，当你用生命符记将亨兹·法奥克从死亡边缘救回时，你便接受了一场仁慈的考验。圣光既能在战斗中助你一臂之力，也能抗衡死亡。",["race:Dwarf"]="身为矮人，看到亨兹·法奥克倒在人类的土地上，你便会想起，迪菲亚匪徒威胁着各族旅人，而不仅是暴风城的人民。"},sec={{t="英雄哨岗的牺牲",b="在暴风城以东的英雄哨岗，亨兹·法奥克倒在石环附近。迪菲亚劫掠者在那里伏击了他和他的朋友贾森·坦诺姆。亨兹为让贾森活下来，挺身挡下袭击，随后倒在了强盗的刀刃下。贾森赶到光明大教堂求援。亨兹仍在生死之间徘徊，等待一位携带生命符记的圣骑士。"}},faq={{q="亨兹·法奥克是谁？",a="亨兹·法奥克是一名铁炉堡矮人，如今身负重伤，倒在艾尔文森林英雄哨岗的石环附近。他在保护朋友贾森·坦诺姆时，被迪菲亚强盗击倒。",al={"亨兹·法奥克","英雄哨岗的矮人","艾尔文濒死的矮人"}},{q="亨兹·法奥克为什么倒在地上？",a="迪菲亚潜行者在亨兹·法奥克和贾森·坦诺姆旅途中伏击了他们。亨兹承受了大部分攻击，让贾森得以逃脱，如今正等待一位圣光的初学者前来救助。",al={"亨兹为什么濒死","亨兹死了吗","亨兹·法奥克死了"}},{q="亨兹与圣骑士有什么关系？",a="亨兹·法奥克是年轻圣骑士接受圣洁之书试炼时，一项入门仪式的救助对象。圣骑士新兵携带生命符记前往艾尔文，用它救治亨兹，证明自己已经掌握圣光的救赎祝福。",al={"亨兹圣骑士任务","圣洁之书矮人"}},{q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是亨兹·法奥克的同伴。迪菲亚匪徒将他们逼入绝境时，亨兹保护了贾森，后者幸存下来，并向圣光教会求援。",al={"贾森是谁","贾森·坦诺姆的朋友"}}},fx={["162be787"]={q="亨兹·法奥克效忠哪一方？",a="亨兹·法奥克坚定地效忠于联盟与圣光。他是贾森·坦诺姆忠诚的朋友，同样也是一名矮人；在艾尔文森林，他为保护朋友，英勇抵抗迪菲亚潜行者的残忍匪徒，最终倒下。",al={"亨兹·法奥克阵营","亨兹是否属于联盟","亨兹·法奥克效忠对象"}},["47ed07eb"]={q="亨兹·法奥克想要什么？",a="亨兹·法奥克遭到迪菲亚潜行者的凶狠伏击而丧命，眼下最需要的是圣光降下奇迹，让他重获生命。除了活下去，他无私的心愿只是保护同伴贾森·坦诺姆免受伤害。",al={"亨兹想要什么","亨兹·法奥克目标","亨兹·法奥克目的"}}},fp="11,158,28.354.0,19.185.0,39.197.0,39.255.0,20.162.0"}
P.entries["npc:heralath-fallowbrook"] = {n="赫尔拉斯·静水",s="在剃刀沼泽深处，赫尔拉斯·静水落入野猪人之手，已奄奄一息。他奉命调查远古之神阿迦玛甘遗骸周围的荆棘，却遭到俘虏和虐待。如今，他只盼有人能将他的遭遇和他珍爱的坠饰带给远在达纳苏斯的妻子。",h="在剃刀沼泽深处，赫尔拉斯·静水落入野猪人之手，已奄奄一息。他奉命调查远古之神阿迦玛甘遗骸周围的荆棘，却遭到俘虏和虐待。如今，他只盼有人能将他的遭遇和他珍爱的坠饰带给远在达纳苏斯的妻子。",kw={"阿迦玛甘","静水","亨里格·独眉","赫尔拉斯","临终遗言","野猪人","剃刀沼泽","塔莎拉"},ang={["class:Druid"]="身为德鲁伊，看到赫尔拉斯在剃刀沼泽的荆棘中备受摧残，便能明白失去遏制的腐化如何在南贫瘠之地蔓延。",["race:NightElf"]="身为暗夜精灵，将赫尔拉斯的坠饰带到达纳苏斯，是向一位逝去的同胞致敬。他为探明并治愈卡利姆多大地的创伤，献出了生命。"},sec={{t="悲惨的使命",b="赫尔拉斯·静水来到南贫瘠之地，调查远古之神阿迦玛甘及其遗骸周围蔓延的荆棘。这位暗夜精灵德鲁伊受族人派遣，寻找剃刀沼泽腐化的根源。然而，野猪人俘虏了他，将他关进围栏，殴打与高烧让他伤重垂危。意识消散前，赫尔拉斯将自己的发现告诉了同为俘虏的矮人亨里格·独眉。他敦促亨里格向萨兰纳尔的哨兵前哨示警，告知他们野猪人老妪卡尔加·刺肋煽动的侵袭。"},{t="临终的心愿",b="即使亨里格·独眉已经逃脱，赫尔拉斯·静水仍虚弱得无法逃离剃刀沼泽。在荆棘盘绕的围栏中，这位濒死的德鲁伊勉强支撑着，向过往的旅人说出心愿。他请旅人从俘虏他的人手中夺回妻子塔莎拉的坠饰，并将它送到达纳苏斯交给她。这枚坠饰会将他的遭遇传达给塔莎拉，也让她知道，赫尔拉斯直到最后一刻仍惦念着她。"}},faq={{q="赫尔拉斯·静水是谁？",a="赫尔拉斯·静水是一位被囚禁在剃刀沼泽的暗夜精灵德鲁伊。他来到贫瘠之地，研究荆棘的腐化以及陨落的野猪远古之神阿迦玛甘留下的遗产，却被野猪人俘虏，遭受了致命的折磨。",al={"赫尔拉斯是谁","赫尔拉斯·静水","剃刀沼泽的暗夜精灵"}},{q="赫尔拉斯在剃刀沼泽里遭遇了什么？",a="剃刀沼泽的野猪人俘虏了赫尔拉斯，殴打他，并将他关进一间小屋。等到救援者能够赶到他身边时，虐待和疾病已让他濒临死亡。",al={"赫尔拉斯为何濒死","赫尔拉斯·静水遭遇了什么"}},{q="赫尔拉斯请求旅人做什么？",a="赫尔拉斯请求旅人从野猪人手中夺回妻子的坠饰，将它送到达纳苏斯交给她，并告知她自己的遭遇。",al={"赫尔拉斯任务","不朽的生命任务"}},{q="亨里格·独眉与赫尔拉斯是什么关系？",a="亨里格·独眉是一名矮人俘虏，与赫尔拉斯关在同一个围栏中。亨里格逃脱前，赫尔拉斯将自己对阿迦玛甘的了解告诉了他，并敦促他向萨兰纳尔前哨报告卡尔加·刺肋的动向。",al={"亨里格·独眉 赫尔拉斯","剃刀沼泽矮人俘虏"}}},fp="20,292,16.540.0,12.361.1,28.260.0,48.151.0,39.128.0,36.221.0"}
P.entries["npc:herod"] = {n="赫洛德",s="赫洛德是血色十字军著名的勇士与狂战士，统领着血色修道院内的武器库。他以凶悍的武艺和坚定的狂热闻名，训练新兵掌握发动圣战所需的残酷近战技巧。联盟中的异议者和幽暗城的部落统治者都想取他性命，以削弱血色十字军的军事核心。",h="赫洛德是血色十字军著名的勇士与狂战士，统领着血色修道院内的武器库。他以凶悍的武艺和坚定的狂热闻名，训练新兵掌握发动圣战所需的残酷近战技巧。联盟中的异议者和幽暗城的部落统治者都想取他性命，以削弱血色十字军的军事核心。",kw={"军械库","狂战士","赫洛德","虔诚的莱雷恩","破坏者","血色十字军","血色修道院","瓦里玛萨斯"},ang={["class:Warrior"]="赫洛德是暴怒战士的典型，他狂猛的旋风斩与不顾一切的攻势，让他成为血色十字军新兵心中令人畏惧的武力典范。",["faction:Alliance"]="响应虔诚的莱雷恩请求的联盟英雄，可以亲眼见证那些曾经高尚的洛丹伦守护者，如何在赫洛德这样的首领带领下，陷入疯狂而狂热的嗜血欲望。",["faction:Horde"]="对部落，尤其是被遗忘者而言，消灭赫洛德便是直接执行瓦里玛萨斯的命令，摧毁威胁提瑞斯法林地边境的领导层。"},sec={{t="武器库的勇士",b="在血色修道院武器库戒备森严的厅堂中，赫洛德便是血色十字军好战本性的化身。与大教堂中运用神圣魔法的施法者和圣骑士不同，赫洛德依靠的是原始而嗜血的蛮力。他身披锁甲，手持巨大的双手斧，亲自训练一批批血色预备兵，向他们灌输狂热的信念，要消灭所有不支持其狂热事业的人。"},{t="首要目标",b="赫洛德掌管着血色十字军前线战士的武器装备与战斗训练，因此，任何想要瓦解这一组织的人都必须将他击倒。虔诚的莱雷恩曾是血色十字军的一员，因看清组织的疯狂而心灰意冷，如今住在南海镇，他要求除掉赫洛德，以摧毁他们的军事领导层。在洛丹伦的另一边，幽暗城的恐惧魔王瓦里玛萨斯同样想要取他性命，清除这座紧邻被遗忘者领土的危险人类据点。"}},faq={{q="赫洛德是谁？",a="赫洛德是一名精锐人类战士，也是血色修道院武器库的指挥官。他是修道院的四位主要首领之一，负责为血色十字军狂热的近战战士配备装备并进行操练。",al={"赫洛德背景故事","赫洛德是谁","赫洛德 血色修道院"}},{q="赫洛德在哪里？",a="赫洛德位于血色修道院武器库区的深处，修道院坐落在提瑞斯法林地东北部。他在四周环绕着看台的中央训练场中等待挑战者。",al={"赫洛德在哪","赫洛德位置","寻找赫洛德"}},{q="部落为什么想杀死赫洛德？",a="恐惧魔王瓦里玛萨斯代表幽暗城的被遗忘者，要求消灭修道院的关键指挥官，其中就包括赫洛德，以根除血色十字军在被遗忘者首都门前留下的威胁。",al={"瓦里玛萨斯 赫洛德任务","部落为何杀赫洛德","深入血色修道院"}},{q="联盟为什么想杀死赫洛德？",a="虔诚的莱雷恩曾是血色十字军的一员，如今驻留在希尔斯布莱德丘陵，他看出这个组织已经陷入狂热。他请求联盟勇士除掉赫洛德，让血色十字军失去这位残暴的战士首领。",al={"以圣光之名","虔诚的莱雷恩 赫洛德","联盟为何杀赫洛德"}},{q="击败赫洛德后会发生什么？",a="赫洛德被击败后，一群年轻的血色预备兵会从周围的营房涌入训练场，为他们的导师复仇，足见他在学生心中培植的忠诚有多么深厚。",al={"血色预备兵","赫洛德 学徒涌入","赫洛德死亡事件"}},{q="赫洛德是哪一类战士？",a="赫洛德是一名狂战士，而非传统的神圣圣骑士。他以凶猛的冲锋和横扫四周的旋风斩粉碎敌人，依靠的是肉体的狂暴力量，而非圣光的法术。",al={"赫洛德战斗风格","赫洛德是圣骑士吗"}}},fx={["3c3e6bcb"]={q="赫洛德效忠于哪一方？",a="赫洛德是血色十字军的高级指挥官，是驻守在血色修道院内的四位关键领袖之一。他狂热地忠于血色十字军的激进使命，负责指挥他们的军事训练和军械库，对付一切被血色十字军视为不洁或敌对的人。",al={"赫洛德所属阵营","赫洛德为谁效力","赫洛德属于哪一方"}},["78320a40"]={q="赫洛德想要什么？",a="赫洛德一心训练血色十字军的新一代战士，消灭他们的敌人。他负责军械库，训练新兵，使他们拥有和自己一样永不熄灭的战斗热忱，并力图击溃任何胆敢擅闯修道院圣地的人。",al={"赫洛德的目标","赫洛德的目的","赫洛德想做什么"}},["60fea3ae"]={q="赫洛德为什么在这里？",a="赫洛德统领血色修道院的军械库区域。作为血色新兵的勇士和教官，他监管血色十字军的军械库，并亲自考验任何胆敢挑战血色十字军核心地带的人。",al={"赫洛德为什么在军械库","赫洛德为什么在血色修道院","赫洛德在军械库的职责"}},f73350c1={q="赫洛德与哪些人有联系？",a="赫洛德与血色修道院的核心领袖并肩共事，其中包括大检察官怀特迈恩、血色十字军指挥官莫格莱尼和驯犬者洛克希。他们共同统治着提瑞斯法林地的血色十字军堡垒。",al={"谁领导赫洛德","赫洛德的盟友","赫洛德与谁共事"}},["9c060a47"]={q="赫洛德为何声名远扬或令人畏惧？",a="赫洛德被称为血色勇士，以凶猛的狂战士战斗风格闻名。他挥舞着巨大的战斧，尤其以旋转挥砍、化作势不可挡的钢铁旋风而臭名昭著，能将附近的敌人撕成碎片。",al={"赫洛德为何令人畏惧","赫洛德的名声","赫洛德为何如此危险"}}},fp="5,274,26.314.0,22.402.0,13.207.0,23.148.0,35.182.0,38.206.0,36.165.1,30.185.0"}
P.entries["npc:high-executor-darthalia"] = {n="高级执行官达萨利亚",s="高级执行官达萨利亚在塔伦米尔指挥被遗忘者在希尔斯布莱德的战事。她听命于希尔瓦娜斯·风行者女士和瓦里玛萨斯，将南海镇和辛迪加作为打击目标。",h="高级执行官达萨利亚在塔伦米尔指挥被遗忘者在希尔斯布莱德的战事。她听命于希尔瓦娜斯·风行者女士和瓦里玛萨斯，将南海镇和辛迪加作为打击目标。",kw={"达萨利亚","高级执行官","希尔斯布莱德","希尔斯布莱德丘陵","南海镇","希尔瓦娜斯","辛迪加","塔伦米尔","瓦里玛萨斯"},ang={["faction:Alliance"]="在南海镇的人类及其盟友眼中，达萨利亚率领的攻势威胁着他们在洛丹伦的立足之地。",["faction:Horde"]="身为部落冒险者，你向达萨利亚报到，对抗联盟，守住希尔斯布莱德这片争夺不休的边疆。",["race:Undead"]="身为被遗忘者，你能看出达萨利亚让洛丹伦继续掌握在亡灵手中的决心。"},sec={{t="塔伦米尔的指挥官",b="高级执行官达萨利亚在塔伦米尔统领被遗忘者部队。她致力于牵制南海镇的人类军队，并在希尔斯布莱德丘陵各地追剿辛迪加强盗。被遗忘者在希尔斯布莱德南部的每一次攻势都由她指挥。"},{t="希尔斯布莱德之战",b="高级执行官达萨利亚听命于幽暗城的领袖希尔瓦娜斯·风行者女士和瓦里玛萨斯。她指挥希尔斯布莱德各地的战事，包括侦察、袭击人类领袖，以及悬赏缉拿威胁被遗忘者对洛丹伦北部控制的亡命之徒。"}},faq={{q="高级执行官达萨利亚是谁？",a="高级执行官达萨利亚统领希尔斯布莱德丘陵的被遗忘者部队。她指挥这些部队对抗南海镇和辛迪加。",al={"达萨利亚是谁","达萨利亚身份","执行官达萨利亚"}},{q="在哪里可以找到达萨利亚？",a="达萨利亚在塔伦米尔统领被遗忘者部队，协调洛丹伦中部各地的兵力部署与突袭行动。",al={"达萨利亚位置","达萨利亚在哪里","执行官达萨利亚地图"}},{q="达萨利亚听命于谁？",a="达萨利亚听命于幽暗城的领袖希尔瓦娜斯·风行者女士和瓦里玛萨斯。",al={"达萨利亚首领","达萨利亚阵营","谁指挥达萨利亚"}},{q="达萨利亚会向冒险者指派什么任务？",a="达萨利亚派遣部落勇士攻击人类定居点和危险的亡命之徒，其中包括遍布希尔斯布莱德丘陵的辛迪加成员。",al={"达萨利亚任务","达萨利亚给予的任务","达萨利亚想要什么"}},{q="达萨利亚为何与南海镇的人类交战？",a="达萨利亚作战是为了牵制南海镇的联盟部队，保护塔伦米尔，并阻止他们向北推进至幽暗城。",al={"为何攻击南海镇","南海镇战事","希尔斯布莱德冲突"}},{q="达萨利亚在被遗忘者军中担任何种军职？",a="身为高级执行官，达萨利亚在被遗忘者军中位居高层，统辖希尔斯布莱德的地区部队与前哨，并制定当地的作战战略。",al={"高级执行官军衔","达萨利亚头衔"}}},fp="23,168,24.254.0,21.276.0,31.137.0,29.125.0,29.87.0,46.149.0,51.145.0,50.142.0"}
P.entries["npc:high-executor-derrington"] = {n="高级执行官德灵顿",s="在亡灵壁垒，高级执行官德灵顿指挥被遗忘者先锋部队，抵御来自西瘟疫之地的威胁。这位军官行事干练，派遣身经百战的勇士前往安多哈尔和通灵学院等战火纷飞的废墟。",h="在亡灵壁垒，高级执行官德灵顿指挥被遗忘者先锋部队，抵御来自西瘟疫之地的威胁。这位军官行事干练，派遣身经百战的勇士前往安多哈尔和通灵学院等战火纷飞的废墟。",kw={"安多哈尔","亡灵壁垒","德灵顿","被遗忘者","高级执行官德灵顿","天灾军团","提瑞斯法林地","西瘟疫之地"},ang={["class:Warrior"]="德灵顿体现了一名前线士兵冷峻、务实的坚韧，比起宫廷阴谋，他更看重作战本领和战场上的实绩。",["faction:Horde"]="对于行经提瑞斯法的部落旅人而言，德灵顿指挥部队投身于西瘟疫之地的凶险战事。",["race:Undead"]="德灵顿是被遗忘者军队的中坚力量，守护着他们收复的土地，抵御Scourge的再次侵占和血色十字军的狂热攻势。"},sec={{t="边关指挥官",b="在亡灵壁垒的路障前，高级执行官德灵顿向那些从提瑞斯法林地进入西瘟疫之地的人下达命令。他对幽暗城的政治角力毫无耐心，视前线为一处只为生存而战的熔炉。部落士兵和雇佣兵接到的命令直截了当：侦察瘟疫肆虐的土地，在来犯之敌抵达提瑞斯法之前遏制其攻势。"},{t="两线作战",b="亡灵壁垒面临着安多哈尔的天灾军团和更北方血色十字军的威胁。天灾军团部队通过散布在乡野间的大锅传播腐化，而血色十字军的狂热分子则争夺北方的防御工事，与被遗忘者巡逻队交战不休。德灵顿统筹精准反击、针对血色十字军战线的破坏行动，以及对天灾军团瘟疫大锅分布区域的系统性打击，以保卫东部边境。"}},faq={{q="高级执行官德灵顿是谁？",a="高级执行官德灵顿是驻守亡灵壁垒的被遗忘者高级指挥官，这座军事哨站位于提瑞斯法林地与西瘟疫之地之间。他统筹部落向东推进的攻势，对抗天灾军团和血色十字军。",al={"德灵顿","德灵顿是谁","高级执行官德灵顿背景故事"}},{q="德灵顿在哪里？",a="德灵顿驻守在亡灵壁垒。这里是提瑞斯法林地东缘一处设有防御工事的隘口，扼守着通往西瘟疫之地的道路。",al={"德灵顿在哪里","德灵顿位置","寻找高级执行官德灵顿"}},{q="德灵顿在亡灵壁垒的目标是什么？",a="德灵顿力求通过坚固的防御抵御天灾军团，并向西瘟疫之地发起进攻，确保被遗忘者的生存。他派遣冒险者侦察安多哈尔、使瘟疫大锅失效，并挫败血色十字军的行动。",al={"德灵顿的目标","亡灵壁垒的用途","德灵顿的使命"}},{q="德灵顿关心幽暗城的政治吗？",a="不关心。德灵顿鄙视宫廷中的阴谋家和政客；在前线，每一天都必须为生存而战。",al={"德灵顿的性格","德灵顿是否关心政治"}},{q="德灵顿派遣士兵对抗哪些主要威胁？",a="德灵顿派遣士兵对抗盘踞安多哈尔的天灾军团、通灵学院内的黑暗通灵师，以及威胁部落东部补给线的附近血色十字军驻军。",al={"德灵顿的任务","德灵顿对抗什么"}},{q="亡灵壁垒为何戒备如此森严？",a="亡灵壁垒是提瑞斯法林地与瘟疫之地交战区域之间的主要隘口。驻军坚守关口，阻止天灾军团大军或血色十字军部队向幽暗城席卷而来。",al={"亡灵壁垒为何设在此处","亡灵壁垒背景故事"}}},fp="24,201,26.379.0,19.430.0,32.224.0,28.143.0,46.237.0,46.133.0,57.186.0,40.208.0"}
P.entries["npc:high-executor-hadrec"] = {n="高级执行官哈德瑞克",s="高级执行官哈德瑞克在瑟伯切尔指挥被遗忘者驻扎在银松森林的部队。他以这座墓穴为据点，统筹防御腐皮豺狼人等威胁，并调查这片地区各处斥候失踪的事件。",h="高级执行官哈德瑞克在瑟伯切尔指挥被遗忘者驻扎在银松森林的部队。他以这座墓穴为据点，统筹防御腐皮豺狼人等威胁，并调查这片地区各处斥候失踪的事件。",kw={"亡灵哨兵","芬里斯岛","哈德瑞克","高级执行官","腐皮","瑟伯切尔","暗影之牙","银松森林"},ang={["class:Rogue"]="身为潜行者，你可能会与哈德瑞克麾下的亡灵哨兵合作，找回失踪的同伴，并收集敌人的脓液和文件。",["faction:Horde"]="身为从卡利姆多远道而来的部落盟友，你可以向哈德瑞克报到，帮助稳定银松森林的局势，部落在洛丹伦北部的控制仍然薄弱。",["race:Undead"]="身为从丧钟镇南下的被遗忘者，你会发现哈德瑞克代表着幽暗城最高指挥部的意志，组织新近复生的亡灵保卫洛丹伦。"},sec={{t="瑟伯切尔的指挥官",b="高级执行官哈德瑞克从银松森林的瑟伯切尔指挥被遗忘者的军事行动。提瑞斯法林地在黑暗女王的部队控制下安然无虞，但银松森林仍面临敌对的达拉然法师、凶野的狼人和不断进犯的豺狼人。哈德瑞克必须巩固被遗忘者的控制，并镇压首都以南威胁幽暗城权威的势力。"},{t="腐皮之患",b="腐皮豺狼人和芬里斯岛占据了哈德瑞克的大部分精力。这些野兽受到亡灵之力的污染，已经占据亡者农场和洛丹米尔湖沿岸，威胁着被遗忘者的巡逻队。哈德瑞克派遣特工前往破败的渡口和农庄寻找线索，查明赋予豺狼人力量的源头，并准备进攻它们在岛上的据点。"},{t="密切关注暗影之牙",b="哈德瑞克也关注着亡灵哨兵送来的报告，这是被遗忘者的秘密情报机构。当秘密行动人员在影牙城堡附近失踪时，哈德瑞克便派遣特工查明他们的下落，并随时向黑暗女王汇报大法师阿鲁高及其受诅咒狼人的动向。"}},faq={{q="高级执行官哈德瑞克是谁？",a="哈德瑞克是一名被遗忘者军官，军衔为高级执行官。他统领瑟伯切尔的驻军，并指挥被遗忘者在银松森林各地的行动。",al={"哈德瑞克背景故事","哈德瑞克是谁","瑟伯切尔指挥官"}},{q="在哪里可以找到高级执行官哈德瑞克？",a="你可以在瑟伯切尔内找到哈德瑞克，这处被遗忘者聚居地位于银松森林中部，坐落在南北主干道旁。",al={"哈德瑞克位置","哈德瑞克在哪里","寻找哈德瑞克"}},{q="哈德瑞克指挥玩家对抗哪些威胁？",a="哈德瑞克指挥士兵和冒险者对抗亡者农场及芬里斯岛上的腐皮豺狼人。他还负责组织搜寻失踪的亡灵哨兵密探，并查明影牙城堡内部的情况。",al={"哈德瑞克任务","哈德瑞克做什么","银松森林任务"}},{q="高级执行官在被遗忘者的军事体系中负责什么？",a="高级执行官是被遗忘者的高级战地指挥官，效命于希尔瓦娜斯·风行者女士，负责统筹一处地区哨站或战线的战略。",al={"被遗忘者高级执行官","高级执行官军衔","哈德瑞克军衔"}},{q="哈德瑞克为什么关注芬里斯岛？",a="哈德瑞克关注芬里斯岛，是因为那里已经成为腐皮豺狼人的主要巢穴。他协调侦察行动并筹划进攻，以瓦解它们的领导层，确保洛丹米尔湖及附近水道的安全，保障被遗忘者的补给线。",al={"芬里斯岛哈德瑞克","为什么进攻芬里斯岛","腐皮芬里斯岛"}},{q="哈德瑞克与影牙城堡有什么关联？",a="哈德瑞克与被遗忘者的谍报组织亡灵哨兵合作。当派往影牙城堡方向的斥候未能回报时，他便派遣信任的特工前去调查，查明他们的遭遇。",al={"影牙城堡哈德瑞克","哈德瑞克阿鲁高","暗影之牙中的亡灵哨兵"}}},fp="20,207,26.333.0,20.353.0,17.264.1,28.139.0,40.125.0,48.224.0,60.153.0,40.242.0,47.199.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {n="大检察官法尔班克斯",s="大检察官法尔班克斯曾是白银之手骑士团中备受敬重的牧师，也是大领主亚历山德罗斯·莫格莱尼信赖的顾问。他曾是洛丹伦幸存守军中举足轻重的精神领袖，后来，他的命运与血色十字军走向黑暗的堕落紧紧相连。",h="大检察官法尔班克斯曾是白银之手骑士团中备受敬重的牧师，也是大领主亚历山德罗斯·莫格莱尼信赖的顾问。他曾是洛丹伦幸存守军中举足轻重的精神领袖，后来，他的命运与血色十字军走向黑暗的堕落紧紧相连。",kw={"灰烬使者","大教堂","法尔班克斯","检察官","莫格莱尼","雷诺","血色修道院","白银之手","斯坦索姆"},ang={["class:Paladin"]="法尔班克斯目睹了白银之手最黑暗的时刻：一名备受尊敬的圣骑士将传奇圣刃刺向了自己的父亲。",["class:Priest"]="在陨落之前，法尔班克斯是一名Light的牧师，也是被称为灰烬使者的大领主莫格莱尼最亲近的顾问。",["faction:Alliance"]="法尔班克斯的悲剧可以追溯到已经覆灭的洛丹伦王国，Grand Alliance的残部在那里分裂成了狂热者与被放逐者。",["race:Undead"]="法尔班克斯揭示了血色十字军最深重的虚伪：他们将自己人的尸体藏在祭坛后，却焚烧无辜的被遗忘者。"},sec={{t="灰烬使者的顾问",b="洛丹伦陷落之前，法尔班克斯是白银之手骑士团中德高望重的神职人员，也是大领主亚历山德罗斯·莫格莱尼最信赖的顾问，而这位大领主正是传奇武器灰烬使者的持有者。当莫格莱尼与上将阿比迪斯、大检察官伊森利恩共同创立血色十字军时，他就站在大领主身旁。起初，这是一个誓要消灭天灾军团的高尚组织。"},{t="斯坦索姆的背叛",b="大领主亚历山德罗斯·莫格莱尼的长子雷诺将父亲引入斯坦索姆城外一场可怕的天灾军团伏击时，法尔班克斯也随行在侧。战斗刚开始，法尔班克斯便在亡灵利爪的围攻下倒地，被成堆腐烂的尸体掩埋。他身陷这骇人的境地，默默目睹雷诺拾起落地的灰烬使者，将它刺入亲生父亲的心脏，以弑父之罪玷污了这柄圣刃。法尔班克斯从这场屠杀中幸存下来，从死人堆里挣扎着爬出，返回血色修道院，揭露雷诺的背叛。"},{t="处决与放逐",b="法尔班克斯声嘶力竭的警告令洛丹伦残存的守军分崩离析。相信他那骇人叙述的人离开了这个狂热的组织，建立了银色黎明。仍然效忠雷诺和赛丹·达索汉的人则将法尔班克斯斥为亵渎者和疯子。血色十字军秘密处决了法尔班克斯。十字军没有为他举行神圣的葬礼，而是将他的尸体丢弃在大教堂祭坛后的一间密室里，他最终在那里复起，成了他们发誓要净化的怪物。"}},faq={{q="在哪里可以找到大检察官法尔班克斯？",a="法尔班克斯藏在血色修道院的大教堂区内。要找到他，需进入主祭坛右侧的小礼拜堂，拉动墙上隐藏的火把，打开通往僻静墓室的秘密石门。",al={"法尔班克斯在哪里","如何找到法尔班克斯","法尔班克斯密室","修道院暗门"}},{q="法尔班克斯为什么会变成亡灵？",a="没有人确切解释过他是如何复起的。在斯坦索姆的伏击中，法尔班克斯曾被埋在成堆的天灾军团尸体之下，后来血色十字军因他指控其领袖而将他处决，他被丢弃的尸体藏在一间密室里，最终在那里复起，成了亡灵的一员。",al={"法尔班克斯为什么是僵尸","法尔班克斯属于天灾军团吗","法尔班克斯为什么是亡灵"}},{q="法尔班克斯被处决前是什么人？",a="法尔班克斯是白银之手骑士团的一名虔诚牧师，也是被称为灰烬使者的大领主亚历山德罗斯·莫格莱尼的首席顾问。他是洛丹伦幸存守军最初的精神领袖之一。",al={"法尔班克斯背景故事","大检察官法尔班克斯是谁","法尔班克斯传说"}},{q="是什么导致了血色十字军与银色黎明的分裂？",a="法尔班克斯从斯坦索姆归来，讲述了自己在那里的所见之后，这个组织便分裂了。相信法尔班克斯、反对雷诺狂热行径的人离开并建立了银色黎明，而雷诺的狂热追随者则留在了血色十字军。",al={"银色黎明起源","银色黎明为何分裂","法尔班克斯与银色黎明"}},{q="血色十字军为什么要杀死法尔班克斯？",a="血色十字军的领袖将他对斯坦索姆事件的证词斥为恶意的亵渎。十字军将他处决，以此掩盖真相。",al={"血色十字军为何杀死法尔班克斯","谁杀了法尔班克斯","法尔班克斯被处决"}},{q="谁接替法尔班克斯成为了大检察官？",a="法尔班克斯被处决并遭到秘密囚禁后，怀特迈恩接任了大检察官一职，与指挥官雷诺莫格莱尼一同主持血色修道院的审讯。",al={"现在的大检察官是谁","法尔班克斯的接替者","谁接替了法尔班克斯"}}},fx={["14cc9219"]={q="大检察官法尔班克斯如今站在哪一边？",a="法尔班克斯如今不再属于任何阵营。他曾是白银之手备受尊崇的牧师，也是高阶领主亚历山德罗斯·莫格莱尼最亲密的知己；然而，他遭到谋杀并死而复生后，失去了理智，也不再效忠旧日阵营。亡灵瘟疫将他吞噬，他又被昔日由他引导的狂热者囚禁起来。任何活物踏入他隐秘墓室，都会遭到他猛烈攻击；他在无尽的痛苦与疯狂中肆意出手。",al={"法尔班克斯的阵营","法尔班克斯有敌意吗","法尔班克斯站在哪边"}},d7d74c1e={q="法尔班克斯为何藏身于血色修道院？",a="在斯坦索姆的伏击中幸存后，法尔班克斯回到血色修道院，公开反对十字军的领袖雷诺·莫格莱尼和赛丹·达索汉。他被指为异端和骗子，随后遭处决，以免他继续发声。十字军接着将他的尸体丢弃在大教堂祭坛后方的一间密室里，把复活的尸身秘密封存起来。",al={"法尔班克斯为何在修道院","法尔班克斯为何藏在密室","法尔班克斯的密室"}},edd0ed20={q="大检察官法尔班克斯曾与谁关系密切？",a="法尔班克斯曾是高阶领主亚历山德罗斯·莫格莱尼——传奇武器灰烬使者的主人——最亲密的顾问与同伴；莫格莱尼与高阶将领阿比迪斯、以及大检察官伊森利恩创立血色十字军时，他也在场。他随亚历山德罗斯前往斯坦索姆，目睹的一切促使他警告其他骑士。这一警告引发了分裂，并促成银色黎明的建立。",al={"法尔班克斯的关系","法尔班克斯与莫格莱尼","法尔班克斯曾效忠谁"}}},fp="25,201,25.342.0,22.488.1,19.466.2,43.212.0,36.254.2,41.246.0,70.226.2,43.140.2,42.189.0"}
P.entries["npc:high-priest-rohan"] = {n="高阶牧师洛汉",s="在铁炉堡，高阶牧师洛汉于秘法大厅中引领着圣光教会。他教导年轻的牧师，帮助他们加深对圣光的掌握，并维系着铁炉堡、暴风城与远方盟友之间的精神纽带。",h="在铁炉堡，高阶牧师洛汉于秘法大厅中引领着圣光教会。他教导年轻的牧师，帮助他们加深对圣光的掌握，并维系着铁炉堡、暴风城与远方盟友之间的精神纽带。",kw={"圣光教会","驱魔香炉","格雷森·沙东布瑞克","秘法大厅","高阶牧师洛汉","铁炉堡","秘法区","牧师训练师","洛汗"},ang={["class:Paladin"]="作为格雷森·沙东布瑞克公爵派来的圣骑士，你拜访洛汗，借用他的驱魔香炉。作为回报，你为铁炉堡的贫困者带来援助。",["class:Priest"]="作为牧师，洛汗的指引和初期训练对你至关重要。之后，他会指引你前往暴风城或达纳苏斯，向著名的导师学习各族特有的信仰法术。",["faction:Alliance"]="作为联盟的信徒，你可以看到洛汗如何维系铁炉堡神职人员与光明大教堂、月神殿及塞纳里奥议会之间的联系。",["race:Dwarf"]="作为矮人，你可以看到洛汗对圣光的虔诚。卡兹莫丹的人民既传承着泰坦的遗产，也怀有深厚的精神信仰。"},sec={{t="Hall of Mysteries的牧者",b="在铁炉堡的秘法区，高阶牧师洛汉踱步于秘法大厅之中，是圣光教会在城中地位最高的代表。矮人曾经尊崇泰坦，而他们的牧师如今已接受圣光的智慧、仁慈与正义。洛汗耐心地教导年轻的侍僧施展神圣魔法，磨炼意志，以抵御绝望。"},{t="联盟之间的桥梁",b="当他教导的牧师掌握基础之后，洛汗便派他们远赴他乡，学习其他传统。人类和矮人学徒前往暴风城，向高阶牧师劳瑞娜求教。暗夜精灵弟子则前往达纳苏斯的月神殿，拜访女祭司阿兰希雅，研习艾露恩的赐福等奥秘。洛汗也派遣治疗者前往遥远的艾萨拉，援助塞纳里奥议会的德鲁伊，奔赴苦难召唤之处。"},{t="驱魔香炉",b="洛汗为联盟的牧师与圣骑士兄弟会保管着神圣的遗物。其中有一只受过祝福的驱魔香炉，多年来一直用于净除邪灵。当白银之手骑士团和格雷森·沙东布瑞克公爵需要它来助骑士们践行神圣使命时，洛汗便慷慨借出。他只请求一些慈善捐助，为铁炉堡日渐匮乏的济贫粮食储备补充物资。"}},faq={{q="在哪里可以找到高阶牧师洛汉？",a="高阶牧师洛汉在铁炉堡北侧秘法区的秘法大厅内踱步。他往返于神圣的藏书室与祭坛之间。",al={"洛汗位置","铁炉堡牧师训练师在哪","洛汗地图","秘法区牧师训练师"}},{q="洛汗在铁炉堡担任什么职责？",a="洛汗训练新晋牧师，提供精神上的指引，并引导他们前往艾泽拉斯各地深造。他是铁炉堡的资深牧师训练师，也是圣光教会在卡兹莫丹最重要的矮人代表。",al={"洛汗是谁","洛汗做什么","洛汗背景故事"}},{q="洛汗为什么派牧师前往达纳苏斯或暴风城？",a="洛汗派人类和矮人见习牧师前往暴风城的光明大教堂，学习绝望祷言等祷言。暗夜精灵牧师则返回达纳苏斯的月神殿，研习艾露恩的赐福等奥秘。他相信精神上的成长需要汲取不同传统的养分。",al={"洛汗职业任务","绝望祷言 洛汗","月神殿任务"}},{q="圣骑士为什么要寻找洛汗？",a="格雷森·沙东布瑞克公爵派来的圣骑士会向洛汗求借受过祝福的驱魔香炉。他将这件圣物借给白银之手骑士团举行仪式，只请求捐赠少量物资，为铁炉堡的穷人提供食物。",al={"圣骑士任务洛汗","驱魔香炉","强调牺牲"}},{q="洛汗为什么派牧师前往艾萨拉？",a="洛汗派遣治疗者，援助在艾萨拉荒野中工作的塞纳里奥议会暗夜精灵德鲁伊。他遵循圣光的召唤，施行仁爱，服务他人。",al={"塞纳里奥援助洛汗","洛汗塞纳里奥议会"}},{q="洛汗只训练矮人吗？",a="洛汗指引着联盟许多种族的信徒，包括矮人、人类和暗夜精灵。他的初步教导让他们做好准备，向熟知各自传统的导师继续学习。",al={"人类能跟洛汗学习吗","洛汗训练谁"}}},fx={["077c3151"]={q="高阶牧师洛汉是谁？",a="高阶牧师洛汉是居住在铁炉堡的圣光教会成员中地位最高的一位。这位德高望重、信仰虔诚的矮人，是山中王国牧师们的首席精神导师，指引初学者领悟虔诚、治疗与神圣之怒的真谛。",al={"洛汉是谁","高阶牧师洛汉","洛汉背景故事"}},["940e11c6"]={q="高阶牧师洛汉效忠哪一方？",a="洛汉坚定地效忠于铁炉堡王国、大联盟与圣光教会。他与暴风城的人类神职人员、达纳苏斯的暗夜精灵密切合作，甚至会在有人亟待救治时，向塞纳里奥议会这样的中立团体提供援助。",al={"洛汉阵营","洛汉是否属于联盟","洛汉效忠对象"}},["90c6beb0"]={q="高阶牧师洛汉想要什么？",a="洛汉致力于传播圣光的美德，照料需要帮助的人。他希望培养年轻牧师的智慧与坚韧，照顾铁炉堡的贫困居民，并在苦难威胁无辜生命时，将援助送往艾泽拉斯各处。",al={"洛汉想要什么","洛汉目标","洛汉动机"}},["88d280c0"]={q="高阶牧师洛汉为什么会在神秘大厅？",a="神秘大厅是铁炉堡研习神圣之道与参悟奥术的圣所。洛汉在这座神圣殿堂中踱步，照看城中居民的精神福祉，为前来祈求的人提供宗教指引，并亲自教导年轻牧师，再将他们派往更广阔的世界。",al={"洛汉为何在铁炉堡","洛汉为何在此","洛汉 秘法区"}}},fp="17,242,33.365.0,27.429.0,19.389.0,35.168.0,40.230.0,54.281.0,31.216.0,39.156.0,30.174.0"}
P.entries["npc:high-priestess-laurena"] = {n="高阶牧师劳瑞娜",s="在暴风城的光明大教堂，高阶牧师劳瑞娜教导人类牧师虔诚信奉之道与奥术防护法术。",h="在暴风城的光明大教堂，高阶牧师劳瑞娜教导人类牧师虔诚信奉之道与奥术防护法术。",kw={"奥术回馈者","本尼迪塔斯","光明大教堂","绝望祷言","高阶牧师","圣光","劳瑞娜","牧师训练师","暴风城"},ang={["class:Priest"]="身为牧师，你可以在暴风城向高阶牧师劳瑞娜学习。她指导人类侍僧，传授绝望祷言，并教导他们如何干扰敌方施法者。",["faction:Alliance"]="身为联盟勇士，你可以在光明大教堂找到高阶牧师劳瑞娜，她在那里巩固联盟的信仰。她传授抵御黑暗魔法与恐怖亡灵的防御法术。",["race:Human"]="身为暴风城的人类，你可以在动荡时期前往光明大教堂，向高阶牧师劳瑞娜寻求精神指引。"},sec={{t="教堂的高阶牧师",b="高阶牧师劳瑞娜在圣光教会中身居高位。她在暴风城的光明大教堂任职，那里是信仰的中心。大主教本尼迪塔斯领导着教会。"},{t="照拂信众",b="在教堂圣所的中央祭坛后方，高阶牧师劳瑞娜指导着有志成为牧师的人。那些专注而虔诚的侍僧会来到她身边，寻求更深入的研习。她传授绝望祷言这样的神圣恩赐，也教授能让敌方施法者反受自身奥术魔法伤害的防御法术。当学生学完她所能传授的一切，她便会指引他们前往联盟各地，向其他牧师大师求教。"}},faq={{q="在哪里可以找到高阶牧师劳瑞娜？",a="高阶牧师劳瑞娜位于暴风城教堂广场的光明大教堂内，站在主祭坛后方。",al={"劳瑞娜位置","牧师劳瑞娜在哪里","寻找劳瑞娜"}},{q="高阶牧师劳瑞娜教授什么？",a="高阶牧师劳瑞娜向人类牧师传授基础祷言，包括绝望祷言，以及奥术回馈者等对抗敌方施法者的防护法术。",al={"劳瑞娜法术","牧师训练师劳瑞娜","劳瑞娜教什么"}},{q="劳瑞娜来到暴风城之前住在哪里？",a="关于高阶牧师劳瑞娜在暴风城光明大教堂任职之前的生活，没有任何记载。",al={"劳瑞娜身世","劳瑞娜来自暴风城吗","劳瑞娜 洛丹伦"}},{q="她听命于大主教本尼迪塔斯吗？",a="是的。大主教本尼迪塔斯领导圣光教会，并主持光明大教堂的事务，高阶牧师劳瑞娜在其中身居高位。",al={"劳瑞娜与本尼迪塔斯","劳瑞娜的上级是谁","本尼迪塔斯 劳瑞娜"}},{q="她为什么指引我去找其他牧师训练师？",a="在传授圣光的基础祷言之后，高阶牧师劳瑞娜会让学生向研习其他教派的牧师大师求教。其中包括铁炉堡的矮人大师和达纳苏斯的暗夜精灵女祭司，他们能拓展学生在信仰上的学识。",al={"劳瑞娜让我离开","毫无畏惧任务","艾露恩的赐福任务"}},{q="劳瑞娜的家人被亡灵杀害了吗？",a="关于高阶牧师劳瑞娜的家人，没有任何记载。",al={"劳瑞娜家人死亡","劳瑞娜的家人遭遇了什么"}}},fx={["7a5d626d"]={q="高阶牧师劳瑞娜是谁？",a="高阶牧师劳瑞娜是圣光教会中一位地位显赫的资深女牧师。她在暴风城的光明大教堂主祭坛后方履行职责，指引有潜力的侍僧承担神圣使命。",al={"劳瑞娜是谁","高阶牧师劳瑞娜身份","高阶牧师劳瑞娜是谁"}},f0ff80a5={q="高阶牧师劳瑞娜效忠哪一方？",a="她全心奉献于圣光教会与联盟。她常驻暴风城的光明大教堂，为王国的信众提供宗教指引，培养新晋牧师，并援助那些逃离艾泽拉斯各地灾难、前来寻求庇护的幸存者。",al={"劳瑞娜效忠对象","劳瑞娜属于什么阵营","劳瑞娜为谁效力"}},["15a925ad"]={q="高阶牧师劳瑞娜想要什么？",a="劳瑞娜致力于引导信众，教导新近献身信仰的牧师，让他们能够抵御黑暗魔法和困扰艾泽拉斯的威胁。",al={"劳瑞娜的目标","劳瑞娜想做什么","劳瑞娜的动机"}},["8a1c100b"]={q="高阶牧师劳瑞娜为什么在光明大教堂？",a="作为圣光教会的一位高阶牧师，劳瑞娜在暴风城的信仰中心光明大教堂任职，在那里教导有潜力的新成员，并协助教会保护王国。",al={"劳瑞娜为什么在这里","劳瑞娜为什么在暴风城","劳瑞娜为什么在光明大教堂"}}},fp="22,108,33.188.0,20.402.0,40.118.0,39.160.0,45.120.0,43.151.0,48.257.0,42.55.0"}
P.entries["npc:highlord-demitrian"] = {n="德米提恩",s="德米提恩是一名独居的人类隐士，栖身于希利苏斯西北部的奇异水晶之间。他自称是桑德兰王子的忠仆，掌握着唤醒这位沉睡元素领主所需的秘法知识。携带古老元素桎梏的冒险者前来寻找他，试图释放逐风者的力量。",h="德米提恩是一名独居的人类隐士，栖身于希利苏斯西北部的奇异水晶之间。他自称是桑德兰王子的忠仆，掌握着唤醒这位沉睡元素领主所需的秘法知识。携带古老元素桎梏的冒险者前来寻找他，试图释放逐风者的力量。",kw={"水晶谷","德米提恩","希利苏斯","雷霆之怒","复生之瓶","逐风者"},ang={["class:Rogue"]="追寻逐风者传说之刃的潜行者，必须在希利苏斯与德米提恩交涉，让支离破碎的王子重获完整形体。",["class:Warrior"]="寻求传说之刃雷霆之怒的战士，必须找到德米提恩，开启解除逐风者束缚并将其唤醒的试炼。",["profession:Blacksmithing"]="为满足德米提恩让桑德兰复生的要求，需要精湛的锻造技艺，将原矿和烈焰精华锻造成Enchanted Elementium Bars。"},sec={{t="水晶谷的隐士",b="德米提恩徘徊在水晶谷一处废弃的营地中，在希利苏斯的荒凉旷野里显得格格不入。虽然德米提恩与暮光之锤有关，并盘桓在他们遭到毁坏的营地里，但他首要的身份仍是逐风者——桑德兰王子的使者。他对来访者冷漠疏离，除非他们带来了能证明逐风者精华破碎的信物。"},{t="复生之瓶",b="德米提恩所做的一切都与桑德兰的复生息息相关。如果冒险者向他出示逐风者的桎梏——从熔火之心的火元素身上夺来的遗物——德米提恩就会交出复生之瓶。他要求收集稀有的元素材料，包括大量附魔源质和火焰之王的精华，以重塑他所效忠的王子的躯体。"},{t="对逐风者的背叛",b="德米提恩的仪式将桑德兰王子召至水晶谷，冒险者必须在那里与重获形体的逐风者交战。击败这位元素领主后，他们拾取风吻之刃，将其交给惊恐的德米提恩，由他唤醒雷霆之怒作为交换。"}},faq={{q="在哪里可以找到德米提恩？",a="他位于希利苏斯最西北的角落，站在水晶谷内的暮光营地废墟附近。",al={"德米提恩位置","德米提恩在哪","德米提恩希利苏斯位置"}},{q="为什么德米提恩只会给出普通的回应？",a="只有携带至少半副逐风者的桎梏，德米提恩才会提供他的传说任务线；这些稀有宝物由熔火之心的迦顿男爵和加尔持有。",al={"德米提恩不交谈","如何接取德米提恩任务","德米提恩对话"}},{q="德米提恩与桑德兰王子是什么关系？",a="德米提恩是宣誓效忠桑德兰王子的凡人仆从。他一心寻找王子被分开的桎梏，让这位元素领主重返物质位面。",al={"德米提恩效忠谁","德米提恩与桑德兰的关系","德米提恩是否属于暮光之锤"}},{q="把复生之瓶所需的全部材料交给他后，会发生什么？",a="德米提恩会举行仪式，将桑德兰王子召至水晶谷，让逐风者重返物质位面。",al={"召唤桑德兰","德米提恩如何使用复生之瓶","水晶谷召唤"}},{q="德米提恩与暮光之锤教派有关联吗？",a="他与暮光之锤有关，住在他们遭到毁坏的营地中，言谈间也对上古之神充满敬意。不过，他立誓效忠的是自己的主人桑德兰王子。",al={"德米提恩是教徒吗","德米提恩暮光营地","德米提恩阵营"}},{q="如何从他那里获得雷霆之怒？",a="将从熔火之心的迦顿男爵和加尔身上取得的两半逐风者的桎梏交给他，再收集他为复生之瓶索要的稀有材料。他的仪式会释放出什么，以及这把剑最终如何被唤醒，将在剧透章节中讲述。",al={"如何获得雷霆之怒","雷霆之怒任务完成","德米提恩之刃"}}},fp="18,265,26.368.0,21.375.1,26.279.1,36.103.0,48.177.0,54.151.0,65.129.1,56.166.0,36.264.1"}
P.entries["npc:hogger"] = {n="霍格",s="在艾尔文森林西南部，霍格率领河爪豺狼人袭击农场和旅人。暴风城的治安官们已悬赏捉拿他，追究他发动暴力袭击的罪行。",h="在艾尔文森林西南部，霍格率领河爪豺狼人袭击农场和旅人。暴风城的治安官们已悬赏捉拿他，追究他发动暴力袭击的罪行。",kw={"悬赏","迪菲亚","杜汉","艾尔文","豺狼人","闪金镇","霍格","河爪"},ang={["faction:Alliance"]="身为联盟的一员，你能看到霍格的袭击如何让暴风城的军队疲于应付。治安官们依靠四处游历的冒险者来维持首都附近的秩序。",["race:Human"]="身为人类，迎战霍格是暴风城年轻守卫者早期的一场试炼。这场战斗回应了艾尔文腹地的威胁。"},sec={{t="河爪的恐怖首领",b="霍格在艾尔文森林西南部的霍格山统领河爪族群。自第三次战争以来，豺狼人袭击附近农庄时愈发大胆，行动也更有组织。如今，他们与迪菲亚潜行者并肩作战，以凶猛的战力换取武器、战术指引和魔法支援。为了守护艾尔文的边境和商路，避免更多流血，治安官杜汉悬赏捉拿霍格。"}},faq={{q="霍格是谁？",a="霍格在艾尔文森林西南部率领河爪族群。这个体型庞大的豺狼人劫掠附近的农庄，并因袭击人类定居点而遭到暴风城当局通缉。",al={"霍格背景故事","霍格是谁","河爪首领"}},{q="为什么有人悬赏捉拿霍格？",a="霍格袭击乡间农场和旅人，治安官杜汉与暴风城卫兵因此发布了悬赏。把他的巨爪带回闪金镇，作为凭证。",al={"通缉霍格","为什么要杀霍格","霍格悬赏"}},{q="河爪豺狼人正在与迪菲亚潜行者合作吗？",a="是的。河爪族群已经与迪菲亚潜行者联手。兄弟会提供精良武器、战术指引和魔法支援，以削弱暴风城对这一地区的控制。",al={"霍格迪菲亚","豺狼人与迪菲亚的联系","河爪与迪菲亚"}},{q="霍格在哪里扎营？",a="霍格与河爪同伙在艾尔文森林西南部的霍格山丘顶上扎营，那里靠近西部荒野边境。",al={"霍格位置","霍格在哪里","霍格山"}}},fx={cd1f1084={q="霍格站在哪一边？",a="霍格率领着艾尔文南部的河爪豺狼人，但他的族群并非单独行动。他们与迪菲亚潜行者勾结，以在林间制造混乱为交换，获取武器、战术指挥和奥术援助。虽然豺狼人主要为了掠夺和领地而战，但霍格与迪菲亚潜行者的结盟，让他的族群直接站到了暴风城王国及其人民的对立面。",al={"霍格的立场","霍格为谁效力","霍格与谁结盟"}},["3ddc17ac"]={q="霍格为什么在艾尔文森林？",a="霍格在艾尔文森林西南部的一座山丘上建立了据点，以便指挥族群大举扩张。河爪豺狼人从这座营地出发，袭击附近的人类农场和定居点，趁王国防务捉襟见肘之机，在迪菲亚潜行者的影响和支持下协同行动。",al={"霍格为什么在这里","霍格在艾尔文森林的原因","霍格为什么来到这里"}},d88533c5={q="霍格为什么如此令人畏惧？",a="霍格以凶残的力量和狡诈的统率手段，让整个艾尔文森林的人闻风丧胆。他不同于普通的游荡豺狼人，是一位异常强悍的酋长，能轻易击败独行的旅人和缺乏经验的冒险者。他对当地农庄的袭击造成了极其严重的破坏，暴风城的治安官们因此将他列为王国需要优先应对的威胁。",al={"霍格为什么出名","霍格为什么令人畏惧","霍格为什么臭名昭著"}}},fp="6,169,22.420.0,14.175.0,32.156.0,60.192.0,32.120.0"}
P.entries["npc:holt-thunderhorn"] = {n="浩特·雷角",s="在雷霆崖的猎人高地，浩特·雷角为部落训练牛头人猎人。他传授追踪与生存之道，并指引猎人前往莫高雷各地及更远的地方，接受专门的试炼。",h="在雷霆崖的猎人高地，浩特·雷角为部落训练牛头人猎人。他传授追踪与生存之道，并指引猎人前往莫高雷各地及更远的地方，接受专门的试炼。",kw={"浩特·雷角","猎人高地","猎人训练师","莫高雷","雷霆崖"},ang={["class:Hunter"]="身为猎人，你可以将浩特·雷角视为你在雷霆崖的重要导师。他传授武器技巧和追踪之道，并指引猎人学习驯服野兽。",["race:Tauren"]="身为牛头人，你继承了一种狩猎文化。早在各个游牧部族于崖顶建立永久家园之前，这种文化就已为他们提供食物与庇护。浩特·雷角在猎人高地延续着这一传统。"},sec={{t="高地上的大师",b="浩特·雷角在莫高雷平原上方的猎人高地，为部落训练猎人。他传授远程作战、追踪与生存之道。和其他深谙狩猎之道的长者一样，他引导年轻的牛头人从四处游猎的猎手，成长为守卫新首都、纪律严明的卫士。"}},faq={{q="在哪里可以找到浩特·雷角？",a="浩特·雷角位于猎人高地，那是雷霆崖东南部的台地。雷霆崖是牛头人的首都，坐落于莫高雷。",al={"浩特·雷角位置","浩特在哪里","雷霆崖猎人训练师"}},{q="浩特·雷角传授什么？",a="浩特·雷角是一位猎人训练师，传授射击、野外生存和驯服野兽的技艺。他还指引新手猎人参加专门的野兽掌握试炼。",al={"浩特教什么","浩特·雷角训练师","浩特传授哪些技能"}},{q="猎人在雷霆崖承担什么职责？",a="猎人历来是牛头人社会的支柱。他们提供食物，巡守边境以抵御半人马劫掠队，并在追踪猎物时恪守平衡、心怀敬畏，以此尊崇大地母亲。",al={"猎人高地的用途","牛头人猎人背景故事"}}},fp="16,189,18.277.0,36.119.0,33.169.0,43.190.0"}
P.entries["npc:houndmaster-loksey"] = {n="驯犬者洛克希",s="在血色修道院的图书馆区，驯犬者洛克希让十字军的战犬随时待命。他繁育并训练这些战犬，用来追猎亡灵、入侵者，以及被十字军判为异端的人。他严酷的训导让修道院的猛兽在提瑞斯法林地令人闻风丧胆。",h="在血色修道院的图书馆区，驯犬者洛克希让十字军的战犬随时待命。他繁育并训练这些战犬，用来追猎亡灵、入侵者，以及被十字军判为异端的人。他严酷的训导让修道院的猛兽在提瑞斯法林地令人闻风丧胆。",kw={"图书馆","驯犬者洛克希","猎犬","猎手雷奥普德","犬舍","洛克希","血色十字军","血色修道院"},ang={["class:Hunter"]="洛克希以残暴的武力驯服野兽。他凶猛的猎犬服从的是狂热，而非彼此的尊重。",["race:Undead"]="身为被遗忘者，你要当心洛克希的猎犬。它们受过训练，能嗅出死去血肉的气味，向十字军的驻军示警。"},sec={{t="犬舍之主",b="驯犬者洛克希训练凶猛的犬只追踪并攻击目标。血色十字军派它们嗅出染有瘟疫的尸体，找出藏匿的潜入者，并追捕那些逃离狂热者怒火的幸存者。洛克希指挥着守卫图书馆区的猎犬。它们随时准备将入侵者撕成碎片。"},{t="兄弟相争",b="洛克希的兄弟猎手雷奥普德是血色十字军派驻圣光之愿礼拜堂的使者，负责与银色黎明交涉。私下里，雷奥普德认为洛克希连自己的猎犬都管不好，更别说处理事关重大的外交事务。然而，洛克希依然是修道院内部指挥体系中的重要军官。"}},faq={{q="在哪里可以找到驯犬者洛克希？",a="驯犬者洛克希位于提瑞斯法林地东北部的血色修道院图书馆区，身边围着他的攻击犬。",al={"洛克希位置","洛克希在哪里","驯犬者洛克希位置"}},{q="洛克希在血色十字军中担任什么职务？",a="洛克希是血色十字军在修道院的首席驯兽师兼驯犬者。他繁育、训练并指挥战犬，让它们嗅出亡灵，追猎入侵者。",al={"洛克希做什么","洛克希职务","驯犬者职责"}},{q="猎手雷奥普德与洛克希是什么关系？",a="猎手雷奥普德是洛克希的兄弟。他在圣光之愿礼拜堂代表血色十字军，并看不起洛克希，认为他既管不好猎犬，也处理不了外交事务。",al={"雷奥普德洛克希兄弟","雷奥普德是谁","洛克希兄弟"}},{q="血色十字军为什么使用猎犬？",a="血色十字军训练凶猛的猎犬，让它们凭气味追踪天灾军团和被遗忘者，守卫修道院，并将逃跑的敌人撕成碎片。",al={"为什么用狗","血色猎犬用途","十字军犬只"}},{q="洛克希算是血色修道院的领袖吗？",a="是的。洛克希是血色修道院军事体系中的重要指挥官。他负责管理图书馆区内十字军的战犬。",al={"洛克希是首领吗","洛克希军衔","洛克希有多重要"}},{q="这些猎犬单独行动时也很危险吗？",a="是的。修道院的战犬经过专门选育，生性凶猛，又受过洛克希的训练，片刻间就能将身披护甲的入侵者撕成碎片。",al={"犬只强大吗","血色猎犬危险","洛克希宠物"}}},fx={["92e01b8b"]={q="驯犬者洛克希是谁？",a="驯犬者洛克希是一名人类队长，也是驻守在血色修道院的四位指挥官之一。他以严酷的纪律闻名，担任犬舍主管，负责繁育、训练并放出十字军凶猛的猎犬，袭击入侵者和疑似感染亡灵污秽之人。",al={"洛克希是谁","驯犬者洛克希的身份","驯犬者洛克希是谁"}},["6cbd929d"]={q="驯犬者洛克希站在哪一边？",a="洛克希坚定效忠血色十字军，是其修道院据点中的一线指挥官。他怀有与十字军相同的狂热，对亡灵以及其狂热教团之外的所有人都充满仇恨；在他看来，任何擅闯他们殿堂的人都只是喂给犬舍的猎物。",al={"洛克希的阵营","驯犬者洛克希与联盟","洛克希效忠谁"}},["1361b0af"]={q="驯犬者洛克希想做什么？",a="洛克希致力于守卫血色修道院，他训练凶残的猎犬群，令它们能够将敌人撕成碎片。他想彻底清除亡灵的踪迹，保护十字军领地免受外人侵扰，并让他的野兽毫不犹豫、毫无怜悯地追捕入侵者。",al={"洛克希的目标","洛克希想做什么","驯犬者洛克希的动机"}},["58572016"]={q="驯犬者洛克希为何在此？",a="洛克希驻扎在修道院的图书馆区，负责看管十字军的犬舍。作为驯犬者，他必须确保猎犬保持警觉、训练有素且凶猛，随时可以放出去巡逻并屠杀入侵者。",al={"洛克希为何在修道院","驯犬者洛克希为何在此","洛克希的目的"}},["264719ea"]={q="驯犬者洛克希为何声名远扬，或令人畏惧？",a="洛克希因他训练有素的猎犬群而令人畏惧。这些野兽能在几分钟内制服受害者，并将其撕成碎片。任何踏入修道院的人都害怕遇上他的犬舍，因为他们知道，在洛克希凶狠的指挥下，这些动物会变成无情的杀戮机器。",al={"洛克希为何令人畏惧","洛克希的声望","驯犬者洛克希为何危险"}}},fp="18,271,21.312.0,14.291.0,38.140.0,51.168.0,34.179.0,40.152.0,55.143.0,38.129.0"}
P.entries["npc:huldar"] = {n="胡达尔",s="胡达尔运送爆破火药的途中受阻，被困在洛克莫丹南部的道路上。这名矮人车夫需要有人帮忙，把货物送到南部的挖掘场，那里的考古学家和勘探员正需要补给。",h="胡达尔运送爆破火药的途中受阻，被困在洛克莫丹南部的道路上。这名矮人车夫需要有人帮忙，把货物送到南部的挖掘场，那里的考古学家和勘探员正需要补给。",kw={"爆破火药","商队","黑铁","挖掘","胡达尔","洛克莫丹","货车"},ang={["profession:Engineering"]="身为工程师，你知道未经加工的爆破火药既珍贵又不稳定，尤其是装在暴露在外的木桶里时。",["race:Dwarf"]="身为矮人，帮助胡达尔就是支援探险者协会的挖掘场，为你的同胞提供火药，以发掘远古泰坦的秘密。"},sec={{t="危机四伏的火药运输",b="胡达尔的货车损坏了，他被困在湖泊南端的转弯处附近。当地的野兽和穴居人威胁着道路，黑铁潜入者也潜伏在附近。他需要过路的旅人帮忙看守剩余的火药桶，并把这批货物送到挖掘场。"}},faq={{q="胡达尔是谁？",a="胡达尔是一名矮人车夫，被困在洛克莫丹南岸的货车旁。他向附近挖掘场运送爆破火药的途中受阻。",al={"胡达尔是谁","胡达尔 洛克莫丹","货车 矮人"}},{q="胡达尔的货车里装着什么？",a="胡达尔的货车里装着一桶桶爆破火药。南部挖掘场的矮人勘探员和考古学家需要这些炸药。",al={"胡达尔在运送什么","胡达尔 货车 货物","桶里是什么"}},{q="胡达尔为什么被困在路上？",a="凶猛的野兽、穴居人和黑铁矮人破坏者威胁着洛克莫丹南部的道路。一场伏击阻断了胡达尔的运输，因此他寻求帮助，守护并运送剩余的补给。",al={"胡达尔为什么被困","胡达尔 伏击"}},{q="黑铁矮人为什么盯上他的货物？",a="黑铁氏族企图削弱铁炉堡在洛克莫丹各地的势力，并破坏其历史研究。他们可以通过切断爆破火药的供应，让挖掘工作停滞，使矮人的各项行动失去防御和工业所需的物资。",al={"黑铁 爆破火药","黑铁为什么袭击胡达尔"}}},fx={ff7033f4={q="胡达尔站在哪一边？",a="胡达尔忠于铁炉堡和联盟。他直接为在洛克莫丹作业的矮人勘探员和矿工效力，将必需的军需物资运往各地，同时坚决抵抗渗入这一地区的敌对黑铁氏族。",al={"胡达尔属于联盟吗","胡达尔为谁效力","胡达尔的阵营"}},["9f03f8e3"]={q="胡达尔想要什么？",a="胡达尔想将他运送的这批爆破火药安全送到矮人的挖掘场。黑铁矮人在洛克湖的南部道路上伏击了他的车队，他因此需要坚定勇敢的旅人保护货物，击退那些破坏者。",al={"胡达尔想做什么","胡达尔的目标","胡达尔需要什么"}},["577cb64e"]={q="胡达尔与谁有关联？",a="胡达尔与驻扎在洛克莫丹的矮人挖掘者有联系。他的小队负责将重要补给和爆破火药直接运往他们的挖掘场，确保即使黑铁入侵的威胁日益加剧，挖掘工作仍能继续。",al={"胡达尔为谁工作","胡达尔的关系","胡达尔为谁运送补给"}}},fp="6,229,21.259.0,14.156.0,26.141.0,32.205.0,50.230.0"}
P.entries["npc:illiyana"] = {n="伊莉亚娜",s="在艾森娜神殿附近，伊莉亚娜守望着灰谷西南部的森林。这位古老的树妖保护林地免遭腐化，并召唤联盟勇士击退萨特。",h="在艾森娜神殿附近，伊莉亚娜守望着灰谷西南部的森林。这位古老的树妖保护林地免遭腐化，并召唤联盟勇士击退萨特。",kw={"灰谷","塞纳留斯的树枝","塞纳留斯","树妖","伊莉亚娜","萨特","艾森娜神殿"},ang={["class:Druid"]="德鲁伊尊树妖为荒野的化身。帮助伊莉亚娜守护神圣的林间空地，也是在履行塞纳里奥治愈大地的职责。",["faction:Alliance"]="伊莉亚娜是灰谷西南部的一位林地盟友。她为抵御邪恶侵袭、保护荒野的联盟部队提供庇护与指引。",["race:NightElf"]="对 Kaldorei 而言，伊莉亚娜这样的树妖是塞纳留斯的神圣血亲，也是荒野的守护者。她们发出对抗恶魔萨特的战斗号召时，总能得到毫不犹豫的回应。"},sec={{t="森林之女",b="伊莉亚娜是塞纳留斯的女儿之一，在灰谷西南部的森林中巡逻。树妖生活平和，却也会奋力保卫荒野。随着腐化在林地中蔓延，伊莉亚娜守护着圣物与林地，捍卫大自然原初的神圣。"},{t="萨特的威胁",b="萨特始终威胁着林间空地和伊莉亚娜的树妖姐妹。这些扭曲的恶魔生物企图腐化森林。伊莉亚娜召唤旅人消灭它们，找回包括塞纳留斯的树枝在内的失落圣物，让林地免遭恶魔玷污。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是一名树妖，在灰谷西南部的艾森娜神殿附近巡逻。身为塞纳留斯的女儿，她守望着荒野，保护姐妹们免遭恶魔势力侵害。",al={"这个树妖是谁","伊莉亚娜 灰谷","伊莉亚娜是什么"}},{q="为什么伊莉亚娜在我和她交谈时还一直走动？",a="伊莉亚娜沿着固定路线在林地中持续巡逻。与旅人交谈时，她仍会在林间来回走动。",al={"伊莉亚娜走动","她为什么走开","伊莉亚娜 任务 走动"}},{q="伊莉亚娜提供什么任务？",a="伊莉亚娜召唤旅人猎杀威胁这一带的萨特，并找回塞纳留斯的树枝等圣物，以保护她的树妖同胞。",al={"伊莉亚娜任务","林歌神殿任务"}},{q="伊莉亚娜在哪里？",a="伊莉亚娜在灰谷西南部的艾森娜神殿附近巡逻，守望着小径和附近的林地。",al={"伊莉亚娜位置","哪里能找到伊莉亚娜","林歌神殿树妖位置"}},{q="为什么萨特会威胁树妖？",a="萨特是遭恶魔腐化而扭曲的古代暗夜精灵。他们以玷污自然、奴役塞纳留斯的子嗣为乐，因此树妖成了他们恶意侵害的目标。",al={"萨特为什么憎恨树妖","树妖与萨特背景故事"}},{q="伊莉亚娜会帮助部落吗？",a="不会。伊莉亚娜与 暗夜精灵 和联盟结盟。进入她所在林地的部落成员会遭到她和盟友的敌视。",al={"伊莉亚娜是否敌视部落","部落能否与伊莉亚娜交谈"}}},fp="8,197,22.265.0,23.278.0,16.168.0,51.121.0,31.162.0,26.111.0,41.172.0,29.133.0"}
P.entries["npc:illiyana-moonblaze"] = {n="艾蒂尔·月火",s="在银翼树林，艾蒂尔·月火为对抗战歌氏族的联盟勇士提供补给。她在灰谷与银翼要塞并肩工作。",h="在银翼树林，艾蒂尔·月火为对抗战歌氏族的联盟勇士提供补给。她在灰谷与银翼要塞并肩工作。",kw={"灰谷","补给包","艾蒂尔·月火","哨兵","银翼树林","战歌峡谷"},ang={["faction:Alliance"]="作为向南行军、前往战歌峡谷争议边境的联盟战士，你可以向艾蒂尔·月火获取武器、护甲和口粮。",["race:NightElf"]="作为暗夜精灵，你可以看到，当kaldorei集结起来保卫灰谷时，艾蒂尔·月火一直为银翼要塞提供补给。"},sec={{t="银翼补给官",b="艾蒂尔·月火在银翼树林为银翼要塞保管补给。她的岗位靠近通往战歌峡谷的道路，为抵御战歌氏族、守卫灰谷南部林地的防御者配备物资。"},{t="前线补给",b="伊莉亚娜为准备在战歌峡谷对抗战歌氏族的联盟志愿者配备物资。随着勇士们赢得银翼要塞的青睐，她会提供特制口粮、专用药剂，以及适合林地小规模战斗的精良武器。她还为从前线归来的疲惫战士修理武器和护甲，保障哨兵的作战补给。"}},faq={{q="在哪里可以找到艾蒂尔·月火？",a="艾蒂尔·月火位于灰谷东南部的银翼树林，靠近集结地和通往战歌峡谷的传送门。",al={"艾蒂尔·月火位置","伊莉亚娜在哪","银翼军需官位置"}},{q="艾蒂尔·月火是哨兵的一员吗？",a="艾蒂尔·月火作为银翼要塞的补给官与他们并肩工作，为同他们一起作战的联盟勇士配备物资。",al={"伊莉亚娜是哨兵吗","伊莉亚娜军衔","伊莉亚娜阵营"}},{q="伊莉亚娜为联盟勇士提供什么？",a="艾蒂尔·月火向赢得银翼要塞青睐的勇士提供补给包、战场武器、护甲、戒指、战袍和消耗品。",al={"伊莉亚娜出售什么","战歌峡谷奖励 灰谷","伊莉亚娜商人"}},{q="她提供装备修理服务吗？",a="是的。艾蒂尔·月火为在树林中休整的联盟防御者修理武器和护甲，也提供专用军需装备。",al={"伊莉亚娜能修理吗","银翼修理商人","银翼树林修理"}},{q="她发放哪些补给包？",a="艾蒂尔·月火通过补给工作向联盟战士发放哨兵基础、标准和高级护理包，为前线防御者提供必需的战场物资。",al={"哨兵补给包","伊莉亚娜任务","战歌峡谷补给包"}}},fp="18,174,25.223.0,28.351.0,36.149.0,48.137.0,47.159.0,35.139.0,37.176.0"}
P.entries["npc:ilthalaine"] = {n="Ilthalaine",s="在幽影谷，伊尔萨莱恩守望着这片神圣的林地，指引年轻的暗夜精灵开启他们在泰达希尔的生活。他教导他们保卫家园，维系这里的平衡。",h="在幽影谷，伊尔萨莱恩守望着这片神圣的林地，指引年轻的暗夜精灵开启他们在泰达希尔的生活。他教导他们保卫家园，维系这里的平衡。",kw={"奥达希尔","自然的平衡","伊尔萨莱恩","卡多雷","任务给予者","幽影谷","魔符","泰达希尔"},ang={["class:Druid"]="作为初出茅庐的德鲁伊，你从伊尔萨莱恩关于削减野兽数量和自然平衡的教导中，学到践行塞纳里奥理念的第一课。",["faction:Alliance"]="作为联盟的勇士，当伊尔萨莱恩欢迎新的勇士为达纳苏斯和联盟效力时，你感受到了他身上 Kaldorei 沉静而警觉的守望精神。",["race:NightElf"]="作为年轻的暗夜精灵，你最先遇到的就是伊尔萨莱恩。他教导你照料泰达希尔上的家园，维护这里神圣的平衡。"},sec={{t="林谷守护者",b="伊尔萨莱恩守望着幽影谷中心外围的林间小径。他能察觉森林中常人难以发现的变化。当年轻的暗夜精灵开始意识到自己的职责时，他会欢迎他们，并教导他们 卡多雷 的传统。他的指引让他们做好准备，照料泰达希尔，肩负起守护者的责任。"},{t="自然的平衡",b="丰沛的春雨使幽影谷的夜刃豹和蓟背野猪数量激增，超出了这片林地所能供养的范围。伊尔萨莱恩请年轻的守护者削减它们的数量，为林中的其他生灵留下繁衍生息的空间，恢复自然的平衡。"},{t="修行的指引",b="伊尔萨莱恩让年轻的精灵通过与当地野兽交战接受考验，并指引他们走上各自选择的职业道路。他给每位旅者一枚职业魔符，让他们前往奥达希尔的庇护所寻找自己的导师。战士、德鲁伊、潜行者、牧师和猎人都能在那里找到为 卡多雷 效力的起点。"}},faq={{q="伊尔萨莱恩是谁？",a="伊尔萨莱恩守护着幽影谷，那是泰达希尔中一片幽静的林地。他向初来乍到的暗夜精灵介绍他们的职责和森林的状况。",al={"伊尔萨莱恩 背景故事","这个暗夜精灵是谁","幽影谷任务给予者"}},{q="伊尔萨莱恩在幽影谷承担什么职责？",a="伊尔萨莱恩留意着幽影谷的野生动物，教导年轻的暗夜精灵维护自然的平衡。他派他们前去狩猎，并指引他们寻找奥达希尔内的职业导师。",al={"伊尔萨莱恩 做什么","他为什么在这里","伊尔萨莱恩 的职责"}},{q="伊尔萨莱恩为什么要削减幼年夜刃豹和野猪的数量？",a="丰沛的春雨使夜刃豹和蓟背野猪的数量增长，超出了幽影谷所能承受的范围。伊尔萨莱恩请求削减它们的数量，以维护自然的平衡。",al={"自然的平衡 任务","为什么要杀夜刃豹","为什么要杀野猪"}},{q="他分发的魔符是什么？",a="伊尔萨莱恩给新手们分发职业魔符，指引他们去寻找奥达希尔内的导师，其中包括女祭司、德鲁伊、战士和潜行者。",al={"风化符记","简易符记","绿色符记","密文符记","神圣符记"}},{q="在哪里能找到伊尔萨莱恩？",a="伊尔萨莱恩站在泰达希尔的幽影谷中央小径上，就在奥达希尔巨大中空枝干的南侧。",al={"伊尔萨莱恩 位置","伊尔萨莱恩 在哪里","伊尔萨莱恩 坐标"}},{q="伊尔萨莱恩属于德鲁伊还是哨兵？",a="伊尔萨莱恩在幽影谷指引各个职业的新手。他感知着自然的和谐，并在此代表 卡多雷。",al={"他是德鲁伊吗","伊尔萨莱恩 属于什么阵营"}}},fp="10,181,20.314.0,21.261.0,21.292.0,18.155.0,40.179.0,64.198.0,33.142.0,30.107.0,58.123.0"}
P.entries["npc:innkeeper-allison"] = {n="旅店老板奥里森",s="旅店老板奥里森在暴风城贸易区的镶金玫瑰迎接旅人与商人。旅店位于银行与拍卖行之间，提供炉石绑定、饮品和住宿。",h="旅店老板奥里森在暴风城贸易区的镶金玫瑰迎接旅人与商人。旅店位于银行与拍卖行之间，提供炉石绑定、饮品和住宿。",kw={"奥里森","镶金玫瑰","炉石","旅店老板奥里森","暴风城","贸易区"},ang={["faction:Alliance"]="身为联盟的勇士，你可以在从前线归来后到镶金玫瑰休息，并在那里存放战利品。"},sec={{t="贸易区的待客之道",b="旅店老板奥里森在暴风城的镶金玫瑰迎接旅人。旅店位于贸易区的拍卖行与城中的主要金库之间，一楼吸引着小贩、佣兵和来访的外交使节。她在柜台后维持秩序，提供住宿和炉石服务。\n\n奥里森也参加当地的节日庆典。有时，她会为前来都城歇脚的游历英雄安排一些小差事。"}},faq={{q="在哪里能找到旅店老板奥里森？",a="旅店老板奥里森就在镶金玫瑰一楼的柜台后。旅店位于暴风城的贸易区，在中央银行与拍卖行之间。",al={"奥里森位置","旅店老板奥里森在哪里","镶金玫瑰旅店老板"}},{q="旅店老板奥里森提供哪些服务？",a="旅店老板奥里森可以让旅人将炉石绑定到镶金玫瑰，也提供食物和饮品。她还参与季节性活动和节日庆典。",al={"奥里森做什么","奥里森服务","这里能绑定炉石吗"}},{q="旅店老板奥里森提供任务吗？",a="是的。旅店老板奥里森参与季节性庆典，有时也能为四处寻求援助的旅人提供城中的差事。",al={"奥里森任务","旅店老板奥里森任务"}}},fx={["681a398f"]={q="旅店老板奥里森是谁？",a="奥里森是镶金玫瑰的店主兼旅店老板，这里是暴风城最著名的歇脚处之一。她在繁忙的贸易区中心经营旅店，迎接疲惫的冒险者、商人和旅客，让他们在拥挤的都城中找到炉火与慰藉。",al={"奥里森是谁","旅店老板奥里森背景故事","旅店老板奥里森是谁"}},["4fce5435"]={q="旅店老板奥里森效忠哪一方？",a="奥里森是暴风城王国的忠诚子民，一心效忠联盟。她的旅店为途经这座城市的联盟勇士和居民提供安全的庇护所与落脚点。",al={"旅店老板奥里森阵营","奥里森属于联盟吗","旅店老板奥里森效忠谁"}},["3063ebee"]={q="旅店老板奥里森为什么在这里？",a="奥里森经营着镶金玫瑰，旅店就坐落在暴风城繁忙的银行与拍卖行之间。她守在一楼的岗位上，为客人提供住宿、绑定炉石，并照料在这个城区经商办事、络绎不绝的旅客。",al={"旅店老板奥里森为什么在贸易区","旅店老板奥里森在这里的目的","奥里森为什么在这里"}},["735a1673"]={q="旅店老板奥里森想要什么？",a="奥里森只想把旅店经营得生意兴隆、宾至如归，让镶金玫瑰顺利运转。除了照料每天光顾的客人，她也乐于参加都城各处的市民庆典和时令节庆。",al={"旅店老板奥里森动机","奥里森想要什么","旅店老板奥里森的目标是什么"}}},fp="17,204,33.426.0,35.171.0,43.155.0,40.135.0"}
P.entries["npc:innkeeper-farley"] = {n="旅店老板法雷",s="在闪金镇的狮王之傲旅店，旅店老板法雷为旅人提供餐食、床铺和炉石。他深受喜爱，又时刻留心周遭，保管着被遗落的信件，倾听旅途中的烦恼。",h="在闪金镇的狮王之傲旅店，旅店老板法雷为旅人提供餐食、床铺和炉石。他深受喜爱，又时刻留心周遭，保管着被遗落的信件，倾听旅途中的烦恼。",kw={"艾尔文森林","弗雷德里克·法雷","闪金镇","旅店老板法雷","狮王之傲旅店","斯塔文"},ang={["faction:Alliance"]="作为刚离开北郡山谷的新兵，你可以在狮王之傲旅店的法雷柜台处绑定炉石并购买补给。"},sec={{t="闪金镇的老面孔",b="前往暴风城、西部荒野和暮色森林的旅人，都能在闪金镇狮王之傲旅店的柜台后找到旅店老板法雷。他提供餐食、麦酒、奶酪和床铺，也为有需要的人绑定炉石。法雷欢迎所有途经这处繁忙驿站的人，并维持旅店的秩序。"},{t="信使遗下的箱子",b="在通往暴风城、西部荒野和暮色森林的道路交汇处，旅店老板法雷听闻各种传言，也遇见形形色色的奇怪旅人。有一次，一名信使惊恐地逃入夜色，遗下了自己的挎包。法雷将留下的信件妥善存放在楼上的箱子里。其中有一封未寄出的信，收件人是曾任教师的斯塔文·密斯特曼托，为追查这位堕落教师行踪的调查者提供了线索。"}},faq={{q="旅店老板法雷是谁？",a="旅店老板法雷在闪金镇的狮王之傲旅店招待旅人，为穿行艾尔文森林的人提供休憩之所和补给。",al={"旅店老板法雷","弗雷德里克·法雷","闪金镇的旅店老板是谁"}},{q="法雷知道哪些有关斯塔文·密斯特曼托的事？",a="法雷记得，一名惊恐的信使曾在夜间逃离狮王之傲旅店，遗下了几份待送的邮件。他将遗弃的信件妥善存放在楼上的箱子里，其中包括一封寄给斯塔文·密斯特曼托却未送达的信，调查者可以前去取回。",al={"法雷 斯塔文","斯塔文 信件 闪金镇","斯塔文的传说 法雷"}},{q="法雷在旅店提供哪些服务？",a="法雷提供炉石绑定和客房出租服务，还出售来自联盟各地的饮料、果汁和奶酪。奶酪包括奥特兰克冷酪、达拉然奶酪，以及本地的暴风城奶酪。",al={"狮王之傲 服务","法雷 食物和饮料","闪金镇 炉石"}}},fx={bf81c39e={q="旅店老板法雷效忠哪一方？",a="旅店老板法雷是暴风城王国的忠诚子民，也是自豪的联盟成员。他在狮王之傲旅店为穿行于艾尔文森林腹地的联盟同胞、旅客和士兵提供食宿，热情款待他们。",al={"旅店老板法雷阵营","法雷效忠谁","法雷联盟"}},f8150ed8={q="旅店老板法雷想要什么？",a="法雷最关心的是让狮王之傲旅店顺利运转。在劝阻酒馆斗殴和斟倒麦酒的忙碌间隙，他希望能为疲惫的旅客提供一处温暖的避风港。",al={"法雷想要什么","法雷目标","旅店老板法雷动机"}},["5df540c8"]={q="旅店老板法雷为什么在这里？",a="法雷在闪金镇经营狮王之傲旅店。闪金镇坐落在艾尔文森林的道路交汇处，法雷便留在这里照看炉火，打理王国最繁忙的酒馆之一。",al={"法雷为什么在旅店","旅店老板法雷为什么在这里"}},a88a382c={q="旅店老板法雷与谁有联系？",a="法雷是闪金镇的老面孔，途经艾尔文森林的旅客都很熟悉他。游吟诗人法尔坎·伊森斯泰德会指引年轻的冒险者去找他，在狮王之傲旅店歇脚。",al={"法雷家人","旅店老板法雷与谁有亲属关系","法雷人际关系"}}},fp="16,192,19.294.0,29.406.1,24.131.0,47.265.0,45.178.0"}
P.entries["npc:innkeeper-firebrew"] = {n="旅店老板洛雷·火酒",s="在铁炉堡平民区的石火旅店，旅店老板洛雷·火酒为旅人提供食物与休憩之所。他用丰盛的矮人餐食，款待来到山腹之中的登山者和来访的贵宾。",h="在铁炉堡平民区的石火旅店，旅店老板洛雷·火酒为旅人提供食物与休憩之所。他用丰盛的矮人餐食，款待来到山腹之中的登山者和来访的贵宾。",kw={"平民区","矮人","火酒","炉石","旅店老板","铁炉堡","石火旅店"},ang={["faction:Alliance"]="作为远道而来的联盟旅人，你可以在火酒经营的这处中心避风港歇脚。这里靠近铁炉堡的正门，地处国王麦格尼·铜须的都城。火酒是那里的主要旅店老板。",["race:Dwarf"]="作为一名结束卡兹莫丹各地巡逻归来的矮人，你可以在火酒的酒馆里感受家一般的温暖，喝上一杯品质可靠的矮人烈性啤酒。"},sec={{t="石火的掌柜",b="旅店老板洛雷·火酒在平民区的石火旅店迎接旅人。酒馆坐落在平民区的中央环道，许多穿过大门的人首先就会找到这里。柜台上摆着麦酒、烈性啤酒和烤肉，火酒在这里招待前往丹莫罗雪道或深入山中王国的旅人。\n\n矿工、火枪手和使节聚集于此，暂别冷风穿行的隧道，围着炉火交流见闻。石火始终是铁炉堡中心一处热闹的交汇之地。"}},faq={{q="在哪里可以找到旅店老板洛雷·火酒？",a="旅店老板洛雷·火酒就在石火旅店内，酒馆位于铁炉堡平民区的南缘。",al={"火酒位置","旅店老板洛雷·火酒在哪里","铁炉堡酒馆老板"}},{q="火酒出售哪些货物？",a="火酒出售旅店常备的补给品，其中包括扎实管饱的矮人口粮。旅人可以买到矮人烈酒和蜂蜜酒、进口葡萄酒、肉类，以及适合长途旅行的丰盛餐食。",al={"火酒卖什么","火酒饮品","石火 旅店食物"}},{q="火酒属于某个矮人酿酒家族吗？",a="火酒以火酒为姓，但他的家族关系尚未得到确认。",al={"火酒家族","火酒与谁有亲属关系"}},{q="他为旅人提供哪些服务？",a="火酒可以让联盟旅人将炉石绑定在石火旅店。他还提供温暖的床铺，让旅人在山腹之中休息，恢复体力。",al={"这里能绑定炉石吗","铁炉堡炉石旅店"}}},fx={["9fc434fc"]={q="旅店老板洛雷·火酒是谁？",a="旅店老板洛雷·火酒是一位矮人，经营着位于铁炉堡繁华的平民区的石火旅店。他是这座山中城市里热情好客的主人，照看炉火、供应麦酒，并为当地居民和疲惫的旅客提供食宿。",al={"洛雷·火酒是谁","旅店老板洛雷·火酒","石火 旅店旅店老板"}},["3dd110f9"]={q="旅店老板洛雷·火酒效忠哪一方？",a="洛雷·火酒效忠铁炉堡王国，坚定地站在联盟一边。他的酒馆向所有盟友冒险者敞开大门，无论他们是来躲避丹莫罗的寒风，还是在穿越艾泽拉斯的漫长旅途后歇脚。",al={"洛雷·火酒阵营","洛雷·火酒联盟","洛雷·火酒属于联盟吗"}},e30bdb86={q="旅店老板洛雷·火酒想要什么？",a="洛雷·火酒专心经营一家热闹而好客的酒馆。他希望石火旅店的炉火始终熊熊燃烧，客人的酒杯盛满矮人烈酒，并确保来到这座熔炉之城的访客有个温暖的地方休息和绑定炉石。",al={"洛雷·火酒想要什么","洛雷·火酒动机","洛雷·火酒目标"}},b21a7171={q="旅店老板洛雷·火酒为什么在这里？",a="洛雷·火酒在平民区经营石火旅店，是进入铁炉堡中心地带的旅客最主要的接待者。他守在炉火旁，提供住宿，出售口粮与酒水，为抵达都城的冒险者提供温馨的落脚处。",al={"洛雷·火酒为什么在铁炉堡","洛雷·火酒为什么在石火旅店"}}},fp="18,192,23.517.0,36.110.0,38.180.0,47.84.0,43.168.0"}
P.entries["npc:innkeeper-grosk"] = {n="旅店老板格罗斯克",s="在剃刀岭，旅店老板格罗斯克迎接着往来于试炼谷与奥格瑞玛之间的旅人。他的旅店位于杜隆塔尔中部，提供食物、饮料和休息之所。",h="在剃刀岭，旅店老板格罗斯克迎接着往来于试炼谷与奥格瑞玛之间的旅人。他的旅店位于杜隆塔尔中部，提供食物、饮料和休息之所。",kw={"杜隆塔尔","格罗斯克","旅店老板","旅店老板格罗斯克","奥格瑞玛","苦工的重担","剃刀岭"},ang={["faction:Horde"]="对于初经战阵的兽人、巨魔以及前来造访的牛头人来说，从试炼谷或森金村向北前往奥格瑞玛时，格罗斯克的旅店就是沿途第一个真正的城镇落脚处和炉石绑定点。"},sec={{t="赤色荒原上的待客之道",b="剃刀岭连接着杜隆塔尔南部的训练场与奥格瑞玛的高墙。旅店老板格罗斯克在旅店里为战士、斥候和苦工提供栖身之所。旅人能在坚固的木梁下找到基本补给、丰盛的肉食和清凉的饮水。"},{t="苦工的片刻休憩",b="格罗斯克也帮助那些维持杜隆塔尔运转的劳工。胆小的苦工乌克尔把食物运到试炼谷，却得知那里并不需要这些食物。他请旅人把这批食物送回剃刀岭的格罗斯克的旅店。"}},faq={{q="旅店老板格罗斯克在哪里？",a="旅店老板格罗斯克就在杜隆塔尔中部剃刀岭的旅店内，旅店位于向北通往奥格瑞玛的大路旁。",al={"旅店老板格罗斯克位置","格罗斯克在哪里","剃刀岭旅店老板"}},{q="旅店老板格罗斯克提供哪些服务？",a="格罗斯克为部落旅人提供在剃刀岭绑定炉石的地点。他还出售基本的食物、饮水和肉食，供旅人在旅途间隙恢复生命值和法力值。",al={"格罗斯克做什么","格罗斯克商人","剃刀岭能否绑定炉石"}},{q="旅店老板格罗斯克提供任务吗？",a="格罗斯克接收乌克尔托旅人送回剃刀岭的食物。乌克尔太过害怕杜隆塔尔的野兽，不敢亲自送回。",al={"旅店老板格罗斯克任务","苦工的重担交任务"}}},fp="15,173,29.248.0,16.229.0,33.104.0,43.165.0,38.133.0"}
P.entries["npc:innkeeper-gryshka"] = {n="旅店老板格雷什卡",s="在奥格瑞玛的Broken Tusk，旅店老板格雷什卡为旅人提供食物、饮料和炉石绑定服务。她从杜隆塔尔和贫瘠之地各处的猎人那里采购肉类，供应旅店。",h="在奥格瑞玛的Broken Tusk，旅店老板格雷什卡为旅人提供食物、饮料和炉石绑定服务。她从杜隆塔尔和贫瘠之地各处的猎人那里采购肉类，供应旅店。",kw={"断牙","多拉斯","格雷什卡","炉石","旅店老板","奥格瑞玛","力量谷","扎尔夫"},ang={["faction:Horde"]="作为抵达杜隆塔尔的部落旅人，你可以先在力量谷的格雷什卡旅店绑定炉石、补充物资，再深入卡利姆多。",["profession:Cooking"]="作为厨师，你会欣赏格雷什卡采购上好肉品时的用心，她甚至会向远在贫瘠之地的猎人进货。"},sec={{t="力量谷的炉火",b="旅店老板格雷什卡在奥格瑞玛力量谷的Broken Tusk迎接旅人。旅店就在城市大门内不远处，战士、信使和新加入萨尔麾下部落的成员都能在此找到栖身之所。"},{t="偏爱鲜肉",b="格雷什卡为Broken Tusk的厨房备足鲜肉。部落领地各处值得信赖的猎人都会给她送来猎物，其中包括十字路口的扎尔夫和杜隆塔尔的格瑞姆塔克，他们将最好的肉送到旅店。"}},faq={{q="旅店老板格雷什卡是谁？",a="旅店老板格雷什卡在奥格瑞玛力量谷的断牙旅店迎接部落旅人。她提供炉石绑定服务，并出售食物和饮料。",al={"格雷什卡是谁","格雷什卡 奥格瑞玛","旅店老板 断牙"}},{q="在哪里可以找到旅店老板格雷什卡？",a="你可以在力量谷的断牙旅店内找到旅店老板格雷什卡，这里是穿过奥格瑞玛南面正门后的第一个主要城区。",al={"格雷什卡在哪","断牙旅店位置","力量谷旅店老板"}},{q="格雷什卡的肉类供应来自哪里？",a="格雷什卡从部落领地各处的猎人那里采购肉类，包括贫瘠之地十字路口的扎尔夫和杜隆塔尔的格瑞姆塔克，他们会将切好的猎物肉送给她。",al={"格雷什卡食物来源","谁为断牙供货","扎尔夫送肉"}},{q="格雷什卡提供哪些服务？",a="格雷什卡可以将你的炉石绑定到断牙旅店，让你直接返回奥格瑞玛。她还出售食物、面包和饮料，用来恢复生命值和法力值。",al={"这里能否绑定炉石","断牙炉石","格雷什卡出售物品"}},{q="格雷什卡与双足飞龙栖所是否有联系？",a="从贫瘠之地奉命跑飞行差事的旅人，往往会先给格雷什卡捎来包裹，再上去找多拉斯。他是双足飞龙管理员，位于城中高处的台地上。",al={"多拉斯任务","双足飞龙管理员 断牙","飞往奥格瑞玛旅店"}},{q="格雷什卡的性格如何？",a="格雷什卡是一位务实而爽朗的店主，喜欢好肉和直来直去的交谈，也喜欢让酒馆货品充足、井然有序，招待途经首都的部落战士。",al={"格雷什卡是否友善","格雷什卡性格"}}},fp="17,182,32.219.0,22.213.0,25.145.0,37.145.0,41.132.0,35.161.0,57.159.0,43.156.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="旅店老板凯达米尔",s="在多兰纳尔，旅店老板凯达米尔提供食物、饮品和休憩之所。离开幽影谷的年轻暗夜精灵，可以在世界之树枝叶下的这间旅店里找到栖身之处。",h="在多兰纳尔，旅店老板凯达米尔提供食物、饮品和休憩之所。离开幽影谷的年轻暗夜精灵，可以在世界之树枝叶下的这间旅店里找到栖身之处。",kw={"多兰纳尔","炉石","旅店","旅店老板","凯达米尔","暗夜精灵","泰达希尔"},ang={["race:NightElf"]="作为一名离开幽影谷训练场的暗夜精灵，你可以将凯达米尔的旅店当作离家后的第一个落脚点，并在那里绑定Hearthstone。"},sec={{t="多兰纳尔的炉火",b="许多初来乍到的人离开奥达希尔那片幽静的林地后，最先抵达的村庄就是多兰纳尔。在村庄中央的旅店里，旅店老板凯达米尔在泰达希尔的树冠下为来客提供面包、泉水和柔软的床铺。旅人、哨兵和前往达纳苏斯的年轻学徒会在他的柜台前稍作停留，歇歇脚，绑定炉石，并备好穿行于枝桠间所需的口粮。"},{t="镇上的货物",b="开在高高枝桠间的旅店，离不开附近聚落和商贩源源不断的补给。运送货物的信使常被派到凯达米尔的柜台前，让他的旅店也成为维系多兰纳尔日常运转的贸易往来中的一环。"}},faq={{q="在哪里可以找到旅店老板凯达米尔？",a="你可以在多兰纳尔中心的主旅店里找到凯达米尔。多兰纳尔坐落在泰达希尔的枝桠上，是幽影谷以南的第一个主要聚落。",al={"凯达米尔位置","凯达米尔在哪里","多兰纳尔旅店老板位置"}},{q="旅店老板凯达米尔提供哪些服务？",a="凯达米尔提供食物、饮品和休憩之所。你可以在他的炉边绑定炉石，购买水、牛奶、果汁和面包，也可以在他的旅店里退出游戏，积累休息奖励。",al={"凯达米尔的商品","凯达米尔出售什么","多兰纳尔旅店食物"}},{q="哪些任务与旅店老板凯达米尔有关？",a="凯达米尔通过当地名为“多兰纳尔的货物”的送货任务，接收送往旅店的包裹。",al={"凯达米尔的任务","多兰纳尔的货物交任务"}}},fp="18,175,18.371.0,15.215.0,36.133.0,44.165.0,39.96.0"}
P.entries["npc:innkeeper-norman"] = {n="旅店老板诺曼",s="旅店老板诺曼在幽暗城的贸易区经营酒馆，随时迎接旅人。这位安静勤勉的被遗忘者为部落旅人提供休憩之所、炉石绑定服务，以及供生者和死者享用的食物。",h="旅店老板诺曼在幽暗城的贸易区经营酒馆，随时迎接旅人。这位安静勤勉的被遗忘者为部落旅人提供休憩之所、炉石绑定服务，以及供生者和死者享用的食物。",kw={"贝茨","万圣节","炉石","旅店老板","诺曼","贸易区","幽暗城"},ang={["faction:Horde"]="对于仍然活着的部落盟友，旅店老板诺曼的酒馆提供了一处可以安心休息、恢复精力的地方，而幽暗城下的这座要塞，其他地方并不怎么欢迎生者。",["race:Undead"]="身为被遗忘者，你可以在为黑暗女王执行任务的间隙，到贸易区中心旅店老板诺曼的聚会之所休息。"},sec={{t="下水道中的款待",b="在洛丹伦都城的废墟之下，旅店老板诺曼照料着幽暗城贸易区的主要酒馆。途经这座被遗忘者要塞的使者、雇佣兵和冒险者都能在此投宿。旅人们来到这里绑定炉石，交流艾泽拉斯各地的消息，或为前往瘟疫之地的旅程做准备。"},{t="节日里的古怪趣事",b="一年中的大部分时间，旅店老板诺曼都在出售补给、打理客房。到了万圣节，他也会加入节日狂欢，请敢于尝试的客人做些古怪的表演，比如学鸡叫。照做的人可以获得幽暗城薄荷糖之类的节日零食。"}},faq={{q="在哪里可以找到旅店老板诺曼？",a="旅店老板诺曼经营着幽暗城内环南侧弧段上的主要酒馆，位于贸易区。",al={"诺曼位置","幽暗城旅店老板位置","诺曼在哪"}},{q="旅店老板诺曼提供哪些服务？",a="旅店老板诺曼提供客房、炉石绑定服务，以及适合生者和亡灵享用的食物与饮料。旅人也可以在此休息，并在离线期间积累休息加成。",al={"诺曼服务","幽暗城炉石"}},{q="诺曼为什么要客人学鸡叫？",a="在万圣节期间，旅店老板诺曼会请客人学鸡叫，作为节日恶作剧的一部分。愿意放下面子的冒险者可以获得特别的节日薄荷糖。",al={"学鸡叫薄荷糖","诺曼学鸡叫任务"}},{q="诺曼和旅店老板拜特斯有亲属关系吗？",a="旅店老板诺曼与旅店老板拜特斯之间没有已知的亲属关系，两人无论生前还是成为亡灵后，都未曾提及对方。他们的名字合在一起，是对电影《惊魂记》中诺曼·贝茨的诙谐致意。",al={"诺曼 拜特斯关联","旅店老板拜特斯 诺曼"}}},fp="16,205,25.322.0,22.267.0,34.116.0,44.159.0,52.175.0,37.189.0"}
P.entries["npc:innkeeper-pala"] = {n="旅店老板帕拉",s="在雷霆崖的下层台地，旅人们能找到照看着猫与萨满旅店的旅店老板帕拉。她为旅人提供歇脚之处、清凉的饮品和炉石绑定服务，方便他们踏上穿越莫高雷、前往更远之地的旅程。",h="在雷霆崖的下层台地，旅人们能找到照看着猫与萨满旅店的旅店老板帕拉。她为旅人提供歇脚之处、清凉的饮品和炉石绑定服务，方便他们踏上穿越莫高雷、前往更远之地的旅程。",kw={"猫和萨满祭司","炉石","旅店老板","旅店老板帕拉","莫高雷","帕拉","雷霆崖"},ang={["faction:Horde"]="作为来到莫高雷的兽人、巨魔或被遗忘者，你可以在升降梯旁帕拉的旅店里休息。",["race:Tauren"]="作为从卡利姆多边疆归来的牛头人，你能在雷霆崖中央台地高耸的图腾柱下，见到一张熟悉而亲切的面孔。"},sec={{t="下层台地的款待",b="旅店老板帕拉在雷霆崖下层台地的猫与萨满照看炉火。旅人们从中央升降梯或莫高雷的平原来到这里。在公共休息室里，疲惫的战士、四处游历的德鲁伊，以及来访的部落盟友，都能找到遮风避雨的屋檐、一杯热饮和熟悉的歇脚之处。"}},faq={{q="在哪里可以找到旅店老板帕拉？",a="帕拉就在雷霆崖下层台地的猫与萨满里，靠近城中的主要升降梯。",al={"帕拉位置","帕拉在哪里","旅店老板帕拉地图"}},{q="她为旅人提供哪些服务？",a="帕拉可以将你的炉石绑定到猫与萨满，让你瞬间返回这里。她也出售简单的食物和饮品，用于恢复生命值和法力值。",al={"帕拉服务","雷霆崖能绑定炉石吗","帕拉卖什么"}},{q="她的酒馆叫什么名字？",a="帕拉的酒馆名叫猫与萨满。途经这座城市下层的部落旅人会在这里相聚。",al={"猫与萨满","雷霆崖下层旅店名称","帕拉旅店名称"}}},fp="14,200,29.301.0,32.102.0,44.156.0,31.119.0"}
P.entries["npc:interrogator-vishas"] = {n="审讯员韦沙斯",s="审讯员詹姆斯韦沙斯是血色十字军的酷刑大师，驻守在血色修道院的墓地区深处。他以尖厉的嗓音和极度的残忍而臭名昭著，从摧垮俘虏、试探血肉之躯的极限中获得扭曲的快感。走进他刑讯室的人，鲜有能在离开时保全身心。",h="审讯员詹姆斯韦沙斯是血色十字军的酷刑大师，驻守在血色修道院的墓地区深处。他以尖厉的嗓音和极度的残忍而臭名昭著，从摧垮俘虏、试探血肉之躯的极限中获得扭曲的快感。走进他刑讯室的人，鲜有能在离开时保全身心。",kw={"墓地","审讯员韦沙斯","詹姆斯·韦沙斯","洛丹米尔湖","南希·韦沙斯","血色修道院","酷刑","沃瑞尔·森加斯"},ang={["class:Priest"]="看着韦沙斯借狂热信仰将可怕的肢体摧残奉为神圣之举，便能令人不寒而栗地明白，神圣的宗旨如何会蜕变为扭曲的疯狂。",["faction:Alliance"]="联盟英雄发现韦沙斯的所作所为后，很快就会意识到，血色十字军已不再区分Scourge怪物与无辜的活人旅者。",["race:Undead"]="对被遗忘者而言，韦沙斯体现了活人狂热者虚伪的恶意，他纯粹出于怨毒折磨被俘的亡灵，却声称自己在侍奉圣光。"},sec={{t="大审判官的手术刀",b="在血色修道院阴暗的墓穴与墓地中，审讯员韦沙斯看管着十字军俘获的敌人。外面的狂热者身披亮甲，在象征纯洁的旗帜下行军，而韦沙斯展现了这场圣战背后的阴暗真相：以宗教义愤为掩饰的肆意施虐。他将审讯视为一门引以为傲的技艺，而不仅仅是获取情报的职责，沉醉于被遗忘者俘虏、被擒的天灾军团，以及任何不幸被打成异端的活人旅者所承受的痛苦。"},{t="平静的居家生活",b="在染血的围裙和刑讯室的惨叫背后，韦沙斯还过着一种居家度日的双重生活，显得格外怪异。修道院围墙之外，他的家人，包括妻子南希·韦沙斯和年长的亲属韦沙斯老爷爷，平静地住在奥特兰克山脉洛丹米尔湖东岸一间偏僻的小屋里。韦沙斯甚至将从受害者身上夺来的骇人物件带回私生活中，他曾夺走一名叫沃瑞尔·森加斯的被遗忘者俘虏珍爱的婚戒，拿去送给南希。"}},faq={{q="在哪里可以找到审讯员韦沙斯？",a="审讯员韦沙斯位于提瑞斯法林地血色修道院的墓地区深处。他掌管着一间阴森的刑讯室，里面排列着铁笼和染血的刑架。",al={"韦沙斯位置","审讯员韦沙斯在哪里","韦沙斯房间"}},{q="韦沙斯为什么折磨囚犯？",a="血色十字军以铲除天灾军团的腐化、获取情报为由折磨俘虏，而韦沙斯本人却以施加痛苦为乐。他对自己的残忍深感自豪，将酷刑视为自己的艺术。",al={"韦沙斯为什么折磨人","韦沙斯动机"}},{q="沃瑞尔·森加斯是谁？",a="沃瑞尔·森加斯是一名被关押在修道院墓地区的俘虏，遭受着韦沙斯的残酷折磨。韦沙斯折磨了沃瑞尔数周，还偷走了他的婚戒，打算送给自己的妻子。",al={"囚犯沃瑞尔·森加斯","笼子里的囚犯是谁"}},{q="韦沙斯的家人住在哪里？",a="他的家人住在远离修道院的一间不起眼的小屋里，那里位于奥特兰克山脉的洛丹米尔湖东岸。他的妻子南茜和韦沙斯老爷爷在那里安静度日，似乎与他的暴行毫无瓜葛。",al={"南希·韦沙斯位置","韦沙斯老爷爷","韦沙斯家的房子"}},{q="韦沙斯关押着谁？",a="血色十字军将亡灵视为敌人。韦沙斯的囚犯中有一名被遗忘者，名叫沃瑞尔·森加斯，已经被他折磨了数周。",al={"韦沙斯的囚犯","韦沙斯折磨谁","韦沙斯的俘虏沃瑞尔"}},{q="韦沙斯的嗓音和举止是什么样的？",a="在那些直面过韦沙斯的人之中，他以刺耳尖厉的嗓音、咯咯的怪笑，以及每逢有机会从不肯屈服的受害者口中逼出秘密时流露出的骇人兴奋而臭名昭著。",al={"韦沙斯嗓音","韦沙斯性格"}}},fx={["518fe48c"]={q="审讯员韦沙斯是谁？",a="詹姆斯·韦沙斯是血色十字军的首席审讯官，驻扎在血色修道院墓地深处。他狂热而残忍出了名，尤其以折磨在他面前受审的囚犯为荣。他手持刑具，怀着近乎疯狂的狂热，对落入他手中的人严刑拷打，逼取口供。",al={"韦沙斯是谁","审讯员韦沙斯背景","詹姆斯·韦沙斯是谁"}},cadee917={q="审讯员韦沙斯效忠于哪一方？",a="韦沙斯完全效忠于血色十字军。他通过折磨被怀疑为天灾军团代理人的人、被遗忘者囚犯，以及任何被视为玷污或敌视血色十字军狂热纯洁信条的人，来服务于他们的狂热圣战。",al={"韦沙斯的阵营","韦沙斯为谁效力","韦沙斯 血色十字军"}},e1510cf6={q="审讯员韦沙斯为什么在这里？",a="韦沙斯驻扎在血色修道院墓地的刑讯室，负责审讯在提瑞斯法林地各处抓获的囚犯。他日夜逼取情报、发泄虐待欲，并代表十字军摧毁俘虏的意志，例如沃瑞尔·森加斯。",al={"韦沙斯为什么在墓地","韦沙斯在修道院的职责","韦沙斯在这里做什么"}}},fp="19,182,30.435.0,27.367.1,39.166.0,38.188.0,22.215.0,31.220.0,30.145.0,40.201.0"}
P.entries["npc:islen-waterseer"] = {n="水之先知伊斯伦",s="在提度斯阶梯旁，备受尊敬的牛头人萨满祭司水之先知伊斯伦指引部落的新学徒完成水的试炼。她住在一间幽静的渔舍旁，教导寻求水之图腾的萨满祭司与水之灵相契合。",h="在提度斯阶梯旁，备受尊敬的牛头人萨满祭司水之先知伊斯伦指引部落的新学徒完成水的试炼。她住在一间幽静的渔舍旁，教导寻求水之图腾的萨满祭司与水之灵相契合。",kw={"贫瘠之地","水之召唤","格雷塔·苔蹄","伊斯伦","萨满祭司","提度斯阶梯","水之灵契","水先知"},ang={["class:Shaman"]="身为萨满祭司，你在寻求水之图腾的过程中，向伊斯伦学习元素仪式，与水之灵建立联系，并学会与它们沟通。",["faction:Horde"]="身为部落的一员，你能在贫瘠之地海岸的伊斯伦身边找到宁静的精神寄托。她欢迎来自奥格瑞玛和雷霆崖的旅行者。",["race:Tauren"]="身为牛头人，你能从伊斯伦在海边独居的生活中，看出她对Earth Mother恩赐的敬意。在那里，她始终感知着荒野间细微的流动。"},sec={{t="提度斯阶梯的隐士",b="在贫瘠之地的海岸，水之先知伊斯伦隐居于岩石嶙峋的提度斯阶梯，干旱的平原在这里与无尽之海相接。这片海岸的水之灵原始而纯粹，近在咫尺。伊斯伦选择了这处宁静的偏僻居所，远离喧嚣的大厅与繁忙的城市，终日聆听潮汐。寻求与水沟通的萨满祭司会来到这里，向她请教。"},{t="水之灵契的女导师",b="萨满祭司要了解水，除了研习，还需要内心的和谐与灵视。伊斯伦指引求道者调制水之灵契，这种神圣的药剂能穿透凡人感官与元素显形之间的帷幕。她教导他们，水既能坚韧深沉，也能流动自如、滋养万物。任何寻求水之助力的人，都必须对它怀有深深的敬意。"},{t="跨越荒野的情谊",b="尽管伊斯伦在海岸过着宁静的生活，她的灵性联系却遍及卡利姆多。她与格雷塔·苔蹄有着亲密而长久的友谊，后者也是一位精通疗愈之术的睿智牛头人。伊斯伦对水之净化本性的了解远播于贫瘠之地以外，为遭受深重腐化的土地带来灵性的援助。"}},faq={{q="水之先知伊斯伦是谁？",a="在贫瘠之地的海岸，水之先知伊斯伦指引着寻求水之图腾的萨满祭司。这位备受尊敬的牛头人萨满祭司与水元素之灵有着罕见而深厚的联系，并教导那些远道而来的求学者。",al={"水之先知伊斯伦的故事","伊斯伦是谁","提度斯阶梯牛头人"}},{q="萨满祭司为何远道而来拜访她？",a="在水之召唤的试炼中，杜隆塔尔、奥格瑞玛和雷霆崖的萨满祭司训练师会指引学生前去寻找伊斯伦。她考验他们对水的理解，并教导他们调制水之灵契，让他们能够直接感知水元素。",al={"为何拜访伊斯伦","水之召唤任务人物","萨满祭司任务贫瘠之地海岸"}},{q="水之先知伊斯伦在哪里？",a="伊斯伦坐在提度斯阶梯的一间小渔舍外，那里位于贫瘠之地东海岸、商旅海岸以南。",al={"伊斯伦的位置","水之先知伊斯伦在哪里","寻找伊斯伦"}},{q="她所说的水之灵契是什么？",a="水之灵契是一种用元素材料调制的灵性药剂。饮下它，萨满祭司的视线便能穿透物质位面，看见栖居于神圣泉水与潮汐中的水之灵。",al={"水之灵契含义","灵契有什么作用"}},{q="伊斯伦的朋友格雷塔·苔蹄是谁？",a="格雷塔·苔蹄是伊斯伦的牛头人老友，也是修习灵性技艺的同道。她们的友谊长久不衰，常就灵性净化与水的疗愈本性相互请教。",al={"与格雷塔·苔蹄的联系","伊斯伦的朋友"}},{q="伊斯伦属于某个特定阵营或氏族吗？",a="没有资料提及伊斯伦所属的氏族。她独居海岸，欢迎来自部落和联盟的旅行者。她帮助净化费伍德森林遭到腐化的水源，而部落的萨满祭司训练师则将兽人、巨魔和牛头人学生送到她这里。",al={"伊斯伦的阵营","伊斯伦属于部落吗"}}},fp="15,223,25.336.0,27.330.0,22.332.0,23.203.0,33.255.0,33.117.0,38.195.0,37.207.0,49.243.0"}
P.entries["npc:iverron"] = {n="埃沃隆",s="在幽影谷，埃沃隆身中蜘蛛毒液，倒地不起。他的困境警示着泰达希尔内部日益蔓延的腐化。",h="在幽影谷，埃沃隆身中蜘蛛毒液，倒地不起。他的困境警示着泰达希尔内部日益蔓延的腐化。",kw={"解毒剂","丹塔利亚","埃沃隆","卡多雷","幽影谷","蜘蛛","泰达希尔","毒液"},ang={["class:Druid"]="作为一名在幽影谷学习的德鲁伊，你可以从埃沃隆中毒一事看出，自然正遭受更深的病痛。解药的材料就取自这片林地的动植物。",["profession:Herbalism"]="作为一名草药师，你可以迅速采集幽影谷的植物，帮助挽救生命；埃沃隆能否活下来，就取决于此。",["race:NightElf"]="作为一名刚刚走出奥达希尔的暗夜精灵，你可以从埃沃隆的不幸遭遇中看出，泰达希尔的荒野正在多么迅速地失去平衡。"},sec={{t="痛苦的毒咬",b="埃沃隆在幽影谷静谧的树冠下漫步时，遭到了树林蜘蛛的叮咬。毒液让这位年轻的暗夜精灵无法独自返回安全的地方。这些蜘蛛曾与林中生灵和平共处，如今却变得越来越有攻击性。"},{t="急寻解药",b="埃沃隆的同伴和当地的治疗者正设法用紫蓝色蘑菇、月瓣百合和树林蜘蛛的脓液配制解药。这些林间材料混合在一起，便能制成解毒剂。他能否活下来，取决于他们的行动是否及时。"}},faq={{q="埃沃隆是谁？",a="埃沃隆是一位年轻的暗夜精灵，身处泰达希尔的幽影谷。他在林间漫步时被有毒的生物咬伤，急需救助才能活命。",al={"埃沃隆故事","埃沃隆是谁","埃沃隆 暗夜精灵"}},{q="埃沃隆中了什么毒？",a="幽影谷中充满攻击性的树林蜘蛛咬伤了埃沃隆，使他中了令人虚弱的毒液。",al={"埃沃隆为何生病","什么咬伤了埃沃隆","埃沃隆中毒"}},{q="如何治愈埃沃隆？",a="用紫蓝色蘑菇、月亮花和从蜘蛛身上取得的树林蜘蛛的脓液制成解毒剂，就能治愈埃沃隆。",al={"治愈埃沃隆","埃沃隆解毒剂","拯救埃沃隆"}},{q="在哪里能找到埃沃隆？",a="你可以在幽影谷找到埃沃隆，那是泰达希尔一处幽静的林间空地，年轻的暗夜精灵在这里开始接受训练。",al={"埃沃隆位置","埃沃隆在哪里","寻找埃沃隆"}},{q="谁在帮助埃沃隆？",a="埃沃隆的朋友迪兰妮亚·月光请求他人帮忙收集解毒剂的材料，随后又请人趁解毒剂尚未失效，将它送回埃沃隆手中。",al={"谁救了埃沃隆","埃沃隆的朋友","丹塔莉亚·银林 埃沃隆"}},{q="幽影谷的蜘蛛为何如此充满敌意？",a="一种反常的病症正在泰达希尔蔓延，幽影谷的蜘蛛也因此变得充满敌意。它将平日深居林中的野兽扭曲成了凶暴的掠食者。",al={"蜘蛛为何攻击","泰达希尔 蜘蛛腐化"}}},fp="7,114,13.209.0,18.224.1,15.151.0,22.94.0,21.109.0,27.112.0,23.168.0,45.148.0"}
P.entries["npc:jahan-hawkwing"] = {n="加翰·鹰翼",s="在十字路口，加翰·鹰翼为部落旅人供应护甲。这位牛头人护甲商在贫瘠之地的这座哨站经营生意，周围的平原上有猛兽游荡。",h="在十字路口，加翰·鹰翼为部落旅人供应护甲。这位牛头人护甲商在贫瘠之地的这座哨站经营生意，周围的平原上有猛兽游荡。",kw={"护甲商","一捆兽皮","锁甲","十字路口","加翰·鹰翼","皮甲","牛头人","贫瘠之地"},ang={["faction:Horde"]="十字路口是卡利姆多几条主要道路的交汇处，加翰在这里为部落战士和斥候供应护甲，帮助他们抵御半人马的袭击和当地的野兽。",["race:Tauren"]="加翰体现了shu'halo务实、自立的处世之道。他运用制皮技艺和坚固的材料，保护在牛头人祖地贫瘠之地行走的旅人。"},sec={{t="十字路口的护甲商",b="加翰·鹰翼在十字路口为部落旅人和守卫供应所需的护甲。在贫瘠之地，耐用的装备能让人在面对半人马、野猪人和野兽时保住性命。加翰与当地的制皮匠合作，托人运送处理好的兽皮，让店里始终备有结实的熟皮护甲和坚固的锁甲。"}},faq={{q="加翰·鹰翼是谁？",a="加翰·鹰翼是一位牛头人商人兼护甲商，在贫瘠之地的十字路口经营生意。他为过往的冒险者和部落卫兵供应防身用的皮甲和锁甲装备。",al={"加翰·鹰翼的故事","加翰是谁","十字路口护甲商"}},{q="他出售哪些货物？",a="加翰出售基础的熟皮护甲和锁甲套装，包括外衣、靴子、腰带、护腕和手套。这些装备适合初出茅庐的战士、猎人和斥候。",al={"加翰卖什么","加翰·鹰翼的货物","加翰的护甲"}},{q="他会给旅人什么任务？",a="加翰依靠附近的工匠供应货物。他请旅人将未经加工或处理过的材料送到当地的制革匠手中，然后等待成品送回。",al={"加翰的任务","一捆兽皮任务","十字路口兽皮运送"}}},fp="14,166,25.315.0,22.164.0,24.160.0,38.168.0"}
P.entries["npc:jaina-proudmoore"] = {n="Jaina Proudmoore",s="吉安娜·普罗德摩尔是塞拉摩岛的统治者，也是当世最强大的人类女巫。她曾是达拉然肯瑞托的高材生，带领洛丹伦的幸存者渡过无尽之海，如今正努力维系联盟与新部落之间脆弱的和平。",h="吉安娜·普罗德摩尔是塞拉摩岛的统治者，也是当世最强大的人类女巫。她曾是达拉然肯瑞托的高材生，带领洛丹伦的幸存者渡过无尽之海，如今正努力维系联盟与新部落之间脆弱的和平。",kw={"安东尼达斯","阿尔萨斯","尘泥","吉安娜","肯瑞托","普罗德摩尔","塞拉摩","萨尔"},ang={["class:Mage"]="Jaina女士由大法师安东尼达斯亲自教导，被广泛认为是当世最强大的人类女巫，展现了达拉然奥术造诣的巅峰。",["faction:Alliance"]="Jaina为联盟守住了卡利姆多南部至关重要的据点，在效忠暴风城摄政大领主伯瓦尔与避免同邻近部落开战的愿望之间寻求平衡。"},sec={{t="远赴卡利姆多",b="吉安娜是库尔提拉斯海军上将戴林·普罗德摩尔的女儿，自幼便展现出非凡的奥术天赋，并在达拉然师从大法师安东尼达斯。第三次大战期间，她与阿尔萨斯·米奈希尔王子一同调查神秘的亡灵瘟疫，亲眼目睹了洛丹伦的悲惨覆灭。在先知麦迪文的警示下，她集结了一支由人类幸存者组成的远征队，扬帆西行，前往被遗忘的卡利姆多大陆。在那里，她的部队与萨尔的部落及暗夜精灵结成了前所未有的同盟，并肩屹立于海加尔山之巅，击败阿克蒙德，粉碎了燃烧军团的入侵。"},{t="塞拉摩的女领主",b="燃烧军团战败后，吉安娜在尘泥沼泽近海建立了海岛要塞塞拉摩，使其成为联盟在卡利姆多南部的主要堡垒。父亲为向兽人复仇而来时，她对外交的坚持经受了最严峻的考验；吉安娜拒绝支持他的战争，并在萨尔的部队杀死这位海军上将时选择退让，以免卡利姆多再次陷入毁灭性的冲突。如今，她统治着塞拉摩，坚定地主张共存，与大酋长萨尔密切合作，同时在日益紧张的局势中巩固联盟在当地的地位。"}},faq={{q="吉安娜·普罗德摩尔是谁？",a="吉安娜是塞拉摩岛的统治者，也可以说是当世最具天赋的人类法师。她是已故的库尔提拉斯海军上将戴林·普罗德摩尔的女儿，曾在达拉然师从大法师安东尼达斯。",al={"吉安娜是谁","吉安娜·普罗德摩尔的故事","塞拉摩领袖"}},{q="吉安娜为何身在卡利姆多，而非东部王国？",a="第三次大战期间，在洛丹伦陷落之前，先知麦迪文告诫吉安娜，要带领尽可能多的人渡海前往卡利姆多。她的远征队平安渡海，参加了海加尔山之战，随后在尘泥沼泽的港口要塞塞拉摩定居。",al={"吉安娜为何离开洛丹伦","吉安娜与卡利姆多","塞拉摩为何建在这里"}},{q="吉安娜与部落有何关系？",a="吉安娜与大酋长萨尔保持着一份不同寻常而又谨慎的友谊。在海加尔山并肩对抗燃烧军团之后，两位领袖一直努力维系双方人民之间的和平，尽管双方的强硬派都对此激烈反对。",al={"吉安娜与萨尔是否友好","吉安娜与部落","吉安娜是否憎恨兽人"}},{q="吉安娜与阿尔萨斯·米奈希尔王子之间发生了什么？",a="吉安娜与阿尔萨斯曾是亲密的伙伴，也曾相爱。他们一同调查在洛丹伦蔓延的瘟疫，但阿尔萨斯变得日益冷酷无情，令吉安娜深感惊骇——这一切最终演变为斯坦索姆的清洗，她拒绝参与屠杀受感染的市民。",al={"吉安娜与阿尔萨斯","吉安娜是否爱过阿尔萨斯"}}},fp="16,263,18.567.0,21.582.0,29.196.0,57.257.0,44.227.0,55.249.0"}
P.entries["npc:james-halloran"] = {n="詹姆斯·哈洛兰",s="在米奈希尔港，詹姆斯·哈洛兰靠鞣制鳄鱼皮谋生。过往的旅人和附近的商路帮他收集生皮，并将制好的皮革运往东部各大陆的买家手中。",h="在米奈希尔港，詹姆斯·哈洛兰靠鞣制鳄鱼皮谋生。过往的旅人和附近的商路帮他收集生皮，并将制好的皮革运往东部各大陆的买家手中。",kw={"鳄鱼","哈洛兰","詹姆斯·哈洛兰","制皮","米奈希尔港","制革匠","湿地"},ang={["class:Hunter"]="身为猎人，你或许能与哈洛兰找到共同之处。他靠追踪和猎取湿地中凶猛的爬行掠食者谋生。",["faction:Alliance"]="哈洛兰的生意维系着联盟在湿地这片险地的商业活动，为王国各地的城镇供应珍贵的精制皮革。"},sec={{t="沼泽中的制革匠",b="詹姆斯·哈洛兰在米奈希尔港生活和工作，靠镇外的沼泽谋生。危险的泥沼为他提供鳄鱼皮，他凭借精湛的手艺，将这些兽皮制成上好的皮革。附近的商路将他的成品运往艾泽拉斯各地的买家手中。"},{t="兽皮、学徒与日常买卖",b="哈洛兰在沼泽附近照看鞣皮槽，打理生意，那一带时刻都有危险。他雇用强健的旅人剥取沼泽幼兽的皮，并在他的作坊与附近的聚落之间运送日常货物。他们的帮助让他在打理鞣皮和贸易事务的同时，也能获得充足的制革原料。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是米奈希尔港的一名人类制革匠，他猎杀当地的鳄鱼并剥取兽皮，再将坚韧的兽皮鞣制成皮革，卖给世界各地的买家。",al={"詹姆斯·哈洛兰","哈洛兰","哈洛兰是谁","湿地制革匠"}},{q="詹姆斯·哈洛兰把皮革卖到哪里？",a="哈洛兰将上好的皮革运往艾泽拉斯各地。他依靠途经米奈希尔港的海上贸易，将货物运过大海。",al={"哈洛兰皮革贸易","鳄鱼皮运往哪里","哈洛兰的生意"}},{q="哈洛兰为什么需要冒险者收集小鳄鱼皮？",a="哈洛兰忙于在作坊里处理和鞣制兽皮，因此雇用路过的冒险者猎杀当地沼泽中的鳄鱼，剥取它们的皮。他们的工作让他无需离开作坊，就能获得稳定的原料供应。",al={"为什么猎杀小鳄鱼","小鳄鱼皮任务","鳄鱼皮哈洛兰"}},{q="哈洛兰与米奈希尔港有什么联系？",a="米奈希尔港是哈洛兰的贸易和补给中心。他依靠港口及其航线，将鞣制好的兽皮运往远方的市场，维持自己的制革生意。",al={"哈洛兰米奈希尔港","哈洛兰与港口的联系","哈洛兰住在米奈希尔港吗"}},{q="在哪里能找到詹姆斯·哈洛兰？",a="詹姆斯·哈洛兰在湿地西海岸的米奈希尔港生活和工作，镇外就是鳄鱼出没的沼泽。",al={"哈洛兰的位置","詹姆斯·哈洛兰在哪里","寻找哈洛兰"}},{q="哈洛兰有学徒吗？",a="有。哈洛兰把学徒视如己出，曾派他前往沼泽剥取巨型鳄鱼的皮。这个年轻人遭到撕咬，失去了一条腿。在他养伤期间，哈洛兰依靠强健的旅人收集生意所需的兽皮。",al={"哈洛兰的学徒","哈洛兰学徒的职责","谁为哈洛兰工作"}}},fp="14,189,23.235.0,35.293.0,22.169.0,43.125.0,68.211.0,49.162.0,34.129.0,33.239.0"}
P.entries["npc:jannok-breezesong"] = {n="詹诺克·柔歌",s="在多兰纳尔，詹诺克·柔歌训练年轻的暗夜精灵盗贼。他向在世界之树枝叶下踏上旅途的卡多雷传授潜行、诡计与刀剑技艺。",h="在多兰纳尔，詹诺克·柔歌训练年轻的暗夜精灵盗贼。他向在世界之树枝叶下踏上旅途的卡多雷传授潜行、诡计与刀剑技艺。",kw={"柔歌","多兰纳尔","艾瑞安·影语","詹诺克","暗夜精灵","盗贼训练师","泰达希尔"},ang={["class:Rogue"]="作为一名在泰达希尔初出茅庐的年轻暗夜精灵盗贼，你可以先在多兰纳尔向詹诺克学习，再前往首都。",["race:NightElf"]="作为一名kaldorei，除了哨兵和德鲁伊的传统，你也可以踏上潜行、毒药与匕首之路。"},sec={{t="暗影中的引路人",b="在多兰纳尔的枝叶下，詹诺克·柔歌教导初出茅庐的暗夜精灵盗贼。他训练的这些人不属于泰达希尔的哨兵和德鲁伊行列，而是默默行事。他教他们如何在暗影中潜行，从背后发动袭击，以及如何在枝叶间隐匿求生。盗贼在多兰纳尔完成最初的课程后，詹诺克便会指引他们前往达纳苏斯，向更有经验的训练师学习。"}},faq={{q="詹诺克·柔歌是谁？",a="詹诺克·柔歌在泰达希尔的多兰纳尔训练年轻的暗夜精灵盗贼。他向他们传授盗贼的基础技能与技巧。",al={"詹诺克是谁","詹诺克·柔歌的职责","多兰纳尔盗贼训练师"}},{q="詹诺克会让准备进修的盗贼前往何处？",a="在多兰纳尔完成初期训练后，盗贼可以前往达纳苏斯，向城中塞纳里奥区的资深盗贼训练师艾瑞安·影语进一步学习。",al={"詹诺克任务","艾瑞安·影语任务","多兰纳尔盗贼下一步"}},{q="在多兰纳尔哪里能找到詹诺克？",a="詹诺克就在多兰纳尔的训练师亭阁之间，这处聚居地位于泰达希尔中部、幽影谷之外。",al={"詹诺克位置","詹诺克在哪里","寻找詹诺克·柔歌"}}},fp="17,175,22.355.0,25.123.0,40.176.0,36.104.0"}
P.entries["npc:jasper-fel"] = {n="贾斯伯·菲尔",s="在旧城区的SI:7总部，贾斯伯·菲尔留意着来访者，告诫他们谨言慎行。",h="在旧城区的SI:7总部，贾斯伯·菲尔留意着来访者，告诫他们谨言慎行。",kw={"匕首","贾斯伯·菲尔","摩本特·费尔","旧城区","潜行者补给","si:7","暴风城","瓶子"},ang={["class:Rogue"]="身为潜行者，你可以从贾斯伯·菲尔那里买到瓶子和备用刀刃，用于在暴风城执行秘密任务。",["faction:Alliance"]="身为联盟的一员，你可以指望SI:7总部为那些在暗影中保卫王国的特工提供补给。"},sec={{t="暗影中的补给",b="贾斯伯·菲尔为旧城区的SI:7总部内的特工提供补给。他出售的货物包括普通匕首，以及用于调制和涂抹毒药的空瓶。他效力于马迪亚斯·肖尔的情报部门，并告诫来访者谨言慎行。在这里，口无遮拦会让人陷入危险。"}},faq={{q="在哪里可以找到贾斯伯·菲尔？",a="贾斯伯·菲尔就在暴风城旧城区东部的SI:7总部内。",al={"贾斯伯·菲尔位置","贾斯伯·菲尔在哪里","贾斯伯·菲尔暴风城"}},{q="贾斯伯·菲尔出售什么？",a="贾斯伯·菲尔为特工提供普通匕首和各种品质的空瓶。",al={"贾斯伯·菲尔商人","菲尔卖什么","贾斯伯·菲尔货物"}},{q="贾斯伯·菲尔与摩本特·费尔有亲属关系吗？",a="贾斯伯·菲尔与摩本特·费尔同姓，但贾斯伯对自己的私事缄口不言。",al={"贾斯伯·菲尔 摩本特·费尔","贾斯伯·菲尔与摩本特有亲属关系吗","费尔家族暮色森林"}},{q="贾斯伯·菲尔为什么告诫人们小声说话？",a="贾斯伯·菲尔告诫来访者谨言慎行，因为他在暴风城的谍报总部SI:7内工作，在那里，口无遮拦十分危险。",al={"为什么小声说话","贾斯伯·菲尔警告","说错话被割喉"}}},fx={["4d6e97a5"]={q="贾斯伯·菲尔是谁？",a="贾斯伯·菲尔是一名行事低调的人类商人，在暴风城经营生意。他置身于旧城区的隐秘角落，与SI:7特工往来密切，为游走于城中阴暗地下世界的盗贼和秘密特工提供隐秘行动所需的补给、药瓶和简易武器。",al={"贾斯伯·菲尔的背景故事","贾斯伯·菲尔是谁","贾斯伯·菲尔的身份"}},["0dbc34cf"]={q="贾斯伯·菲尔效忠哪一方？",a="贾斯伯·菲尔效忠暴风城与联盟，与SI:7的秘密情报网络紧密协作。他神秘的作风和充满危险意味的警告或许让人觉得他是个不受约束的人物，但他在旧城区经营的生意直接支援着为王国利益效力的特工。",al={"贾斯伯·菲尔与联盟","贾斯伯·菲尔为谁效力","贾斯伯·菲尔的阵营"}},["50a88541"]={q="贾斯伯·菲尔为什么在这里？",a="贾斯伯·菲尔驻留在旧城区的SI:7地盘内，默默为需要行动工具的特工提供物资。无论是调配毒药所需的空瓶，还是用于无声行动的普通刀刃，他都随时备好，让秘密行动得以避开窥探的目光。",al={"贾斯伯·菲尔为什么在旧城区","贾斯伯·菲尔的职责","贾斯伯·菲尔为什么在这里"}}},fp="10,105,24.286.0,28.75.0,26.84.0,37.95.0,49.143.0"}
P.entries["npc:je-neu-sancrea"] = {n="耶努萨克雷",s="耶努萨克雷在佐拉姆加前哨站监视着灰谷海岸的黑暗异动。这位黑暗之矛巨魔也是大地之环的萨满祭司，他派遣部落冒险者前往沉入水下的黑暗深渊神殿，调查其中的腐化。",h="耶努萨克雷在佐拉姆加前哨站监视着灰谷海岸的黑暗异动。这位黑暗之矛巨魔也是大地之环的萨满祭司，他派遣部落冒险者前往沉入水下的黑暗深渊神殿，调查其中的腐化。",kw={"阿库麦尔","黑暗深渊","大地之环","耶努萨克雷","杰尼","暮光之锤","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="身为萨满祭司，你追随大地之环的脚步，致力于让被腐化的元素恢复平衡，并重建卡利姆多水域的平衡。",["faction:Horde"]="身为部落的一员，当你从灰谷进入黑暗深渊时，可以向耶努寻求指引。",["race:Troll"]="身为巨魔，你与牛头人和兽人盟友并肩，沿着黑暗之矛的道路加入大地之环。"},sec={{t="海岸上的萨满祭司",b="耶努萨克雷从佐拉姆加前哨站监视着危机四伏的佐拉姆海岸。大地之环的大多数成员都在卡利姆多各地维系元素的和谐，而他则守望着这片海岸。黑暗深渊的神殿废墟附近，涌动着黑暗的震颤与反常的潮汐。萨满祭司的职责将他与大地之环紧紧相连，但他对黑暗之矛部族和萨尔所领导的部落的忠诚，使他只与部落勇士合作。"},{t="深渊之影",b="耶努萨克雷正在寻找沿海岸蔓延的腐化的根源。他收集被污染的蓝宝石核心，并调查水元素的邪恶残骸，其中也包括阿奎尼斯男爵的残骸。他的调查揭示了暮光之锤教派的影响。这个教派在波涛之下举行的仪式威胁着当地的元素平衡，也预示着效忠于上古之神的势力即将归来。"}},faq={{q="耶努萨克雷是谁？",a="耶努萨克雷是大地之环的一名黑暗之矛巨魔萨满祭司。他驻守在灰谷海岸的佐拉姆加前哨站，监视着从黑暗深渊蔓延而来的腐化。",al={"耶努是谁","耶努萨克雷背景故事","耶努是什么"}},{q="耶努既然属于大地之环，为什么只与部落冒险者打交道？",a="耶努与黑暗之矛部族和部落的联系决定了他与谁合作。大地之环致力于维系元素平衡，但耶努驻守在灰谷前线的一处部落前哨站，并不欢迎联盟旅者。",al={"为什么仅限部落","联盟能与耶努交谈吗","耶努是中立的吗"}},{q="耶努在调查黑暗深渊中的什么事情？",a="耶努正在调查源自黑暗深渊的元素动荡与黑暗魔法。他派遣勇士取回被腐化的水之核心，消灭暮光之锤教徒，并查证有关远古多头蛇阿库麦尔侍奉海底邪恶主人的传闻。",al={"耶努任务目标","耶努想要什么","为什么派玩家去黑暗深渊"}},{q="耶努萨克雷在哪里？",a="耶努萨克雷位于佐拉姆加前哨站，那是灰谷最西北端海岸上一处设有防御工事的部落聚落。前哨站坐落在佐拉姆海岸沿线，就在黑暗深渊以南。",al={"耶努在哪里","耶努萨克雷位置","寻找耶努"}},{q="大地之环是什么？",a="大地之环是一个古老的萨满祭司组织，致力于理解并安抚世界上的元素之灵。当黑暗势力或混乱的存在打破元素的自然和谐时，其成员便会出面干预。",al={"大地之环背景故事","大地之环是什么","萨满祭司组织"}},{q="暮光之锤在黑暗深渊中构成了什么威胁？",a="暮光之锤潜入黑暗深渊，崇拜阿库麦尔，并为上古之神举行仪式。耶努派遣部落冒险者对付这个教派的首领，以阻止他们的活动。",al={"暮光之锤 黑暗深渊","暮光教派 灰谷","黑暗深渊里的教徒是谁"}}},fp="14,195,22.405.0,19.367.1,22.180.0,71.233.0,50.264.0,32.198.0,25.204.0,57.190.0"}
P.entries["npc:jen-shan"] = {n="基沙",s="在试炼谷，基沙向年轻的猎人传授荒野之道。这位黑暗之矛丛林巨魔教导兽人和巨魔射手追踪、远程作战与生存的本领。",h="在试炼谷，基沙向年轻的猎人传授荒野之道。这位黑暗之矛丛林巨魔教导兽人和巨魔射手追踪、远程作战与生存的本领。",kw={"黑暗之矛","杜隆塔尔","风蚀羊皮纸","风蚀石板","猎人训练师","基沙","巨魔","试炼谷"},ang={["class:Hunter"]="身为年轻的兽人或巨魔猎人，你最先遇到的就是基沙。在你离开大兽穴的红色峡谷之前，她会教你远程作战技巧。",["race:Troll"]="身为巨魔，你会看到基沙延续黑暗之矛追踪与侦察的传统，在这片大陆上的新家园向年轻巨魔传授祖辈的狩猎之道。"},sec={{t="红沙之上的导师",b="基沙在试炼谷训练初出茅庐的猎人。年轻的兽人和黑暗之矛巨魔带着刻有文字的石板和羊皮纸，按照上面的指引前来找她。她教导他们射箭、射击和野外生存的本领，让他们做好准备，应对峡谷底部的蝎子和野猪。"}},faq={{q="基沙是谁？",a="基沙是一位黑暗之矛丛林巨魔，在杜隆塔尔的试炼谷训练猎人。她向年轻的部落猎人传授追踪、荒野知识和远程作战的本领。",al={"基沙背景故事","基沙是谁","试炼谷猎人训练师"}},{q="哪些任务与基沙有关？",a="年轻的猎人会被派去找基沙，接受入门训练。兽人带给她的是风蚀石板，巨魔则带着风蚀羊皮纸前来找她。",al={"基沙任务","风蚀石板 基沙","风蚀羊皮纸 基沙"}},{q="为什么一位巨魔会在兽人的试炼场训练猎人？",a="试炼谷是兽人新兵和同住在杜隆塔尔的黑暗之矛巨魔的试炼场。像基沙这样的巨魔斥候训练这两个种族的猎人和战士，让他们为部落效力。",al={"为什么试炼谷有巨魔","杜隆塔尔巨魔训练师"}}},fp="8,167,23.262.0,16.180.0,29.135.0,57.180.0"}
P.entries["npc:jennea-cannon"] = {n="詹妮亚·坎农",s="在暴风城的法师区，詹妮亚·坎农在巫师圣殿教导初学法师。她告诫他们谨慎自律，调查当地奥术能量的异动，并派有潜力的学徒前往城外，检验所学。",h="在暴风城的法师区，詹妮亚·坎农在巫师圣殿教导初学法师。她告诫他们谨慎自律，调查当地奥术能量的异动，并派有潜力的学徒前往城外，检验所学。",kw={"安多玛斯","蓝色隐士","詹妮亚·坎农","法师区","法师训练师","明镜湖","暴风城","巫师圣殿"},ang={["class:Mage"]="身为法师，你可以向詹妮亚寻求最初的实地调查任务，以及制作正式巫师长袍和法杖的指引。",["faction:Alliance"]="身为联盟的一员，你可以在暴风城的法师区找到詹妮亚。她在那里训练新的巫师，让他们能够安全地为联盟效力。"},sec={{t="密室中的引路人",b="在巫师圣殿螺旋步道的顶端，詹妮亚·坎农教导那些来到暴风城研习奥术的人。她传授的不只是法术。谨慎与自律同样重要。即使不研习魔法的人，也会听到她的告诫：未经训练，魔法会灼伤施法者。"},{t="实地研习与基础",b="詹妮亚派有潜力的学徒走出城墙，检验所学。在艾尔文森林的明镜湖，他们研究天然水源如何与奥术产生共鸣。随着学业深入，她会派他们调查蓝色隐士的异动，或收集性质不稳定的施法材料，制作他们第一套真正的巫师用具。"},{t="通往更高深的学识",b="当学徒的造诣超出詹妮亚所能传授的范围时，她会指引他们向更高明的大师求教。展现出真正潜力的人，可以在密室中继续进修，师从高阶巫师安多玛斯。其他人则可能远赴王国之外，向隐居尘泥沼泽深处的塔贝萨这样的施法者求学。"}},faq={{q="詹妮亚·坎农是谁？",a="詹妮亚·坎农在暴风城法师区的巫师圣殿指导初学法师，并安排入门阶段的魔法研究。",al={"詹妮亚·坎农","詹妮亚是谁","暴风城法师训练师"}},{q="在哪里可以找到詹妮亚·坎农？",a="你可以在巫师圣殿内找到詹妮亚·坎农，那是暴风城法师区中央的螺旋高塔。",al={"詹妮亚·坎农位置","詹妮亚在哪里","寻找詹妮亚"}},{q="詹妮亚·坎农提供哪些任务？",a="詹妮亚为联盟法师安排入门研习：考察艾尔文森林的明镜湖，调查蓝色隐士的怪事，以及收集制作新手法师装备的材料。",al={"詹妮亚任务","詹妮亚·坎农任务线"}},{q="她为什么派法师去明镜湖？",a="詹妮亚派学徒到明镜湖的瀑布底部取回水样，以便检验其中是否有魔法污染。她担心暴风城和艾尔文周围发生变化的魔法可能正在渗入水中。",al={"为什么去明镜湖","明镜湖任务詹妮亚"}},{q="詹妮亚·坎农会与法师以外的职业交流吗？",a="法师以外的人也可以与詹妮亚交谈。她告诫他们接触魔法时务必谨慎，因为魔法会灼伤未经适当训练的人。",al={"非法师能否与詹妮亚交谈","其他职业与詹妮亚"}},{q="詹妮亚·坎农的上级是谁？",a="詹妮亚在巫师圣殿内指导学生，直到他们准备好向高阶巫师安多玛斯这样的资深人物求学。",al={"詹妮亚的上级","巫师圣殿领导者"}}},fx={b57d5dda={q="詹妮亚·坎农效忠哪一方？",a="詹妮亚为暴风王国和联盟效力。她驻留在巫师圣殿，与暴风城的法师们共同加强城市的魔法防御，并训练忠于王国的法师新手。",al={"詹妮亚·坎农的阵营","詹妮亚·坎农为谁效力","詹妮亚·坎农的效忠对象"}},d154dff8={q="詹妮亚·坎农想要什么？",a="詹妮亚致力于引导和培养初出茅庐的施法者。她希望确保新手理解奥术危险而不稳定的本质，告诫旅人未经训练便会遭到原始魔法的灼烧，同时指引有潜力的学生前往王国各地开展重要的研习。",al={"詹妮亚·坎农的目标","詹妮亚想要什么","詹妮亚·坎农的职责"}},d5352518={q="詹妮亚·坎农为什么在这里？",a="她居住在暴风城法师区的巫师圣殿，担任联盟法师的导师。在这座高塔中，她负责奥术入门教学，调查附近的异常动静，并指引施法者向高阶巫师安多玛斯这样的权威人士或远方的导师求教。",al={"詹妮亚·坎农为什么在暴风城","詹妮亚·坎农与巫师圣殿","詹妮亚为什么在法师区"}}},fp="13,246,22.297.0,24.340.0,23.289.0,21.120.0,31.120.0,37.183.0,39.205.0,50.120.0,33.133.0"}
P.entries["npc:jergosh-the-invoker"] = {n="祈求者耶戈什",s="在奥格瑞玛地下深处，祈求者耶戈什正密谋对抗部落。他在怒焰裂谷领导着灼热之刃教徒，研习恶魔法术，而萨尔则引领兽人走向荣耀与萨满之道。",h="在奥格瑞玛地下深处，祈求者耶戈什正密谋对抗部落。他在怒焰裂谷领导着灼热之刃教徒，研习恶魔法术，而萨尔则引领兽人走向荣耀与萨满之道。",kw={"祈求者","耶戈什","奥格瑞玛","怒焰裂谷","灼热之刃","暗影议会","术士"},ang={["class:Warlock"]="身为术士，你面对的是一位强大的恶魔法术修习者，他的阴谋威胁着部落。",["faction:Horde"]="一个Shadow Council分支就藏在酋长的王座厅下方，这是部落无法忽视的安全威胁。",["race:Orc"]="身为兽人，你能从耶戈什身上看到，恶魔之血与巫术对旧部落的诱惑仍未消散，而萨尔正试图将其从兽人文化中根除。"},sec={{t="城下的邪教",b="耶戈什在奥格瑞玛地下召集灼热之刃。萨尔引领兽人走向荣耀与萨满之道，耶戈什却转而寻求恶魔的力量。他藏身怒焰裂谷，将追随者招入一个与暗影议会残党结盟的教派。这个邪教盘踞在部落都城地下，暗中对抗新部落所选择的道路。"},{t="恶魔之力的野心",b="耶戈什在怒焰裂谷的活动引来了萨尔的直接关注。黑暗仪式与危险的阴谋日益猖獗，已经引起了大酋长的注意。在杜隆塔尔境内，耶戈什仍维系着部落曾奋力摆脱的黑暗契约。"}},faq={{q="祈求者耶戈什是谁？",a="祈求者耶戈什领导着怒焰裂谷中的灼热之刃教徒。他背弃萨尔的荣耀之路，投身恶魔巫术。",al={"耶戈什是谁","耶戈什的故事","耶戈什 怒焰裂谷"}},{q="耶戈什为何藏身怒焰裂谷？",a="耶戈什藏身于奥格瑞玛地下的怒焰裂谷，灼热之刃可以在那里施展黑暗魔法，密谋对抗部落。",al={"耶戈什为何在奥格瑞玛地下","耶戈什所在地的故事"}},{q="耶戈什属于哪个阵营？",a="耶戈什领导着灼热之刃，这个邪教与暗影议会有关联，并为燃烧军团等恶魔势力效力。",al={"耶戈什的阵营","耶戈什是否属于暗影议会","灼热之刃首领"}},{q="萨尔知道耶戈什就在奥格瑞玛地下吗？",a="知道。耶戈什的阴谋已危险到惊动萨尔的地步，萨尔派遣了信任的冒险者进入怒焰裂谷，阻止这些教徒。",al={"萨尔 耶戈什","萨尔是否知道怒焰裂谷"}},{q="耶戈什为何修习邪能魔法，而非萨满之道？",a="耶戈什摒弃萨满之道所追求的和谐，转而投身恶魔巫术，寻求燃烧军团与黑暗法术的力量。",al={"为何成为术士","耶戈什 邪能魔法"}}},fp="19,171,23.327.0,17.259.1,27.136.0,40.131.0,36.130.0,46.139.0,57.125.0"}
P.entries["npc:jern-hornhelm"] = {n="吉恩·角盔",s="在塞尔萨玛，吉恩·角盔负责保障探险者协会的物资供应与消息传递。他协调镇上、铁炉堡和洛克莫丹腹地挖掘场之间的运送事务，而旅人们则在这片地区往来运送补给和进度报告。",h="在塞尔萨玛，吉恩·角盔负责保障探险者协会的物资供应与消息传递。他协调镇上、铁炉堡和洛克莫丹腹地挖掘场之间的运送事务，而旅人们则在这片地区往来运送补给和进度报告。",kw={"爆破火药","挖掘","探险者协会","铁环","吉恩·角盔","洛克莫丹","矿工","塞尔萨玛"},ang={["faction:Alliance"]="作为在洛克莫丹旅行的联盟旅人，你可以找吉恩寻求帮助，保障这片地区的安全，维护矮人的基础设施。",["profession:Mining"]="作为矿工，你能体会吉恩的从业经历，以及他在地下运输、爆破和资源搬运方面的实用知识。",["race:Dwarf"]="作为矮人，你帮助发掘族人深埋于群山之中的古老Titan传承。"},sec={{t="塞尔萨玛的后勤",b="吉恩·角盔从塞尔萨玛向洛克莫丹的各处挖掘场运送补给。矮人学者和野外队伍在荒野中探寻祖先的过往，他们的工作有赖于资源和工具的持续供应。吉恩也确保消息能送到正在作业的挖掘场。"},{t="为探险者协会效力",b="吉恩·角盔将野外的考古人员与铁炉堡探险者大厅内的探险者协会领导层联系起来。铁环挖掘场需要爆破火药、设备和定期送达的公文，才能让工作继续推进。吉恩请值得信赖的旅人沿着穴居人出没的道路运送补给和报告，让挖掘工作得以继续。"}},faq={{q="吉恩·角盔是谁？",a="吉恩·角盔是塞尔萨玛的一名矮人矿工，负责协调探险者协会的后勤事务。他保障当地挖掘工作的物资供应，让工作持续推进。",al={"吉恩是谁","吉恩·角盔身份","塞尔萨玛矮人吉恩"}},{q="在哪里可以找到吉恩·角盔？",a="吉恩·角盔站在塞尔萨玛的室外，就在洛克莫丹中部附近的大路旁。",al={"吉恩·角盔位置","吉恩在哪","吉恩·角盔地图"}},{q="吉恩·角盔属于哪个阵营？",a="吉恩·角盔效忠联盟，代表矮人的探险者协会。他负责安排人员调动和采矿物资的运输。",al={"吉恩·角盔阵营","吉恩为谁效力","吉恩是否属于探险者协会"}},{q="吉恩为什么需要将爆破火药送往挖掘场？",a="山中的挖掘场需要爆破火药来炸开坚硬的岩壁。吉恩负责协调将火药送往湖东侧勘察员基恩萨·铁环的挖掘场，那里的队伍正努力发掘古代遗迹。",al={"送火药给铁环的故事","挖掘场为何需要火药","洛克莫丹爆破火药"}},{q="吉恩·角盔与铁炉堡有什么联系？",a="吉恩·角盔将洛克莫丹偏远的挖掘场与铁炉堡探险者大厅内的探险者协会领导层联系起来。他经常将野外工作的进度报告送回铁炉堡。",al={"吉恩·角盔铁炉堡","吉恩向铁炉堡汇报"}},{q="洛克莫丹的挖掘场面临哪些问题？",a="穴居人不断侵扰铁环挖掘场，拖慢了挖掘进度。补给运输也面临危险：黑铁矮人伏击了一批运往挖掘场的爆破火药，因此吉恩得依靠武装旅人将物资送达。",al={"铁环挖掘场的问题","洛克莫丹挖掘场的危险","吉恩为何需要帮助"}}},fx={["1cf890d8"]={q="吉恩·角盔为什么在塞尔萨玛？",a="吉恩·角盔驻守在塞尔萨玛，负责洛克莫丹各处考古挖掘的后勤事务。他为探险者协会提供支持，协调铁炉堡与铁环挖掘场等偏远挖掘场之间的重要补给、报告和爆破物资，确保协会的行动有充足的资金和装备。",al={"吉恩·角盔为什么在这里","吉恩·角盔在洛克莫丹的职责","吉恩为什么在塞尔萨玛"}}},fp="13,249,22.273.0,29.330.0,21.150.0,31.94.0,42.146.0,58.209.0,48.177.0,53.221.0"}
P.entries["npc:jitters"] = {n="基特斯",s="基特斯独自住在乌鸦岭的废墟中，畏惧着周围的危险。他靠暮色森林西部旅人的接济度日，始终警惕着阴影中的动静。",h="基特斯独自住在乌鸦岭的废墟中，畏惧着周围的危险。他靠暮色森林西部旅人的接济度日，始终警惕着阴影中的动静。",kw={"书记员达尔塔","黑暗强盗","暮色森林","基特斯","乌鸦岭","罗兰之墓","月神镰刀","斯温·约根","狼人"},ang={["class:Rogue"]="身为潜行者，你能看出基特斯躲避危险的敏捷本能。但这份本能并未让他摆脱在暮色森林中的恐惧与孤独。",["faction:Alliance"]="基特斯终日生活在恐惧中，体现了暮色森林的灾祸给人们带来的苦难，而守夜人仍在竭力保护这里的居民。"},sec={{t="惊魂未定的隐士",b="基特斯在乌鸦岭的残垣断壁间瑟瑟发抖，惧怕着暮色森林西部小径沿途的捕食者。他依靠旅人提供食物，时刻提防危险。很久以前，他就习惯遇事退缩，遇到突如其来的威胁便跳开躲避，因此得了这个名字。他的恐惧源自亲身经历的种种惨事。"},{t="罗兰之墓的觉醒",b="基特斯曾是进入暮色森林的迪菲亚潜行者的一员。在罗兰之墓挖掘时，他发现了从岩石中伸出的月神镰刀。这件神器将凶猛嗜血的狼人带进了森林。基特斯眼看着同伴死在狼人的利爪之下，自己也险些丧命，才逃了出来。"},{t="逃亡与农场",b="逃出矿洞后，基特斯去了夜色镇。他从书记员达尔塔那里买了一本空白书册，躲在血鸦旅店里写下了那场噩梦。惊慌之中，他躲进了约根农场的一间谷仓。在那里，他看见身披黑色斗篷的黑暗强盗在搜寻镰刀时，杀害了斯温·约根的家人。基特斯害怕受到责难，也怕被人发现，便将几页日记埋进土里，随后逃往乌鸦岭，内疚与恐惧始终如影随形。"}},faq={{q="基特斯是谁？",a="基特斯是一个惊恐不安的人类，住在乌鸦岭的废墟中。他饥肠辘辘，孤身一人，在暮色森林的经历始终萦绕心头。",al={"这人是谁","基特斯的故事","基特斯的背景"}},{q="他为什么叫基特斯？",a="基特斯因小心戒备的习惯而得名，他总是畏缩着躲避攻击，遇到突如其来的陷坑便跳开。在暮色森林的孤独与恐惧让他变得更加紧张。",al={"为什么叫基特斯","他的名字从何而来","基特斯名字的由来"}},{q="狼人给暮色森林带来了什么危险？",a="狼人在暮色森林的林间和道路上潜行，威胁着旅人和孤立的聚居地。",al={"暮色森林的狼人威胁","基特斯附近的野兽","暮色森林的狼人危险"}},{q="斯温·约根的家人遭遇了什么？",a="斯温·约根的家人在自家的农场遭到杀害。他决心查出凶手是谁。",al={"斯温农场惨案","谁杀了斯温的家人","约根农场谋杀案"}},{q="基特斯能如何帮助斯温·约根调查？",a="基特斯的日记记录了他在暮色森林的经历，或许能帮助斯温调查家人的遭遇。",al={"基特斯与斯温的调查","基特斯如何帮助斯温","基特斯对暮色森林的记述"}},{q="基特斯的日记是什么？",a="基特斯的日记记录了他在暮色森林的经历，也是调查乌鸦岭和斯温·约根一家遭遇的线索之一。",al={"基特斯的日记","基特斯的完整日记","达尔塔的书"}}},fp="7,138,16.272.0,30.300.1,24.456.1,15.138.1,25.163.0,43.90.1,38.103.1,49.111.1,25.127.1"}
P.entries["npc:jocaste"] = {n="祖卡斯特",s="在达纳苏斯，祖卡斯特训练着从泰达希尔荒野前来的暗夜精灵猎人。",h="在达纳苏斯，祖卡斯特训练着从泰达希尔荒野前来的暗夜精灵猎人。",kw={"塞纳里奥区","达纳苏斯","猎人训练师","祖卡斯特","暗夜精灵猎人","泰达希尔"},ang={["class:Hunter"]="如果你是一名初到达纳苏斯的暗夜精灵猎人，祖卡斯特可以磨炼你的战斗技巧，帮助你加深与动物伙伴之间的纽带。",["race:NightElf"]="身为暗夜精灵，你可以从祖卡斯特身上看到你的族人、泰达希尔的野兽与塞纳里奥议会的教诲之间的和谐。"},sec={{t="塞纳里奥区的导师",b="祖卡斯特在达纳苏斯的塞纳里奥区训练暗夜精灵猎人。年轻的追踪者在幽影谷接受初步训练后，便来到她身边，准备在首都踏上狩猎之路。她传授射击技巧和野外生存之道，也教导猎人如何与卡利姆多的野兽建立纽带。"}},faq={{q="祖卡斯特是谁？",a="祖卡斯特在达纳苏斯的塞纳里奥区训练暗夜精灵猎人。",al={"祖卡斯特背景故事","祖卡斯特是谁","祖卡斯特 达纳苏斯"}},{q="在哪里可以找到祖卡斯特？",a="祖卡斯特位于塞纳里奥区，就在泰达希尔枝桠上的达纳苏斯西北部。",al={"祖卡斯特位置","祖卡斯特在哪里","祖卡斯特地点"}},{q="她对年轻猎人有何帮助？",a="年轻猎人来到达纳苏斯，向祖卡斯特求教，通过猎人之道精进技艺，并学习训练和驾驭野兽。",al={"祖卡斯特任务","猎人之道 祖卡斯特","训练野兽"}},{q="祖卡斯特隶属于塞纳里奥议会吗？",a="是的。祖卡斯特在塞纳里奥区训练猎人，并接引来访的猎人拜见塞纳里奥议会。",al={"祖卡斯特是否属于塞纳里奥议会","祖卡斯特阵营"}}},fp="7,79,23.272.0,15.65.0,25.84.0,42.147.0,47.123.0"}
P.entries["npc:john-j-keeshan"] = {n="John J. Keeshan",s="在赤脊山的战斗中，John J. 基沙恩下士被黑石兽人俘虏。石堡周围的战斗结束后，他们将他拖进了撕裂者之石深处。",h="在赤脊山的战斗中，John J.",kw={"约翰·杰·基沙恩","基沙恩","战斗中失踪","撕裂者之石","石堡"},ang={["class:Warrior"]="身为一名战士，基沙恩的遭遇展现了赤脊山前线的凶险，那里即便是身经百战的士兵，也可能被黑石氏族击败并掳走。",["faction:Alliance"]="身为一名联盟士兵，基沙恩在赤脊山为暴风城坚守防线、抵御黑石兽人时被俘。"},sec={{t="赤脊山的士兵",b="John J. 基沙恩下士在赤脊山为暴风城效力。黑石兽人向湖畔镇及其守军步步进逼时，他被派驻到那里。石堡要塞周围战火燃起时，基沙恩与其他士兵并肩作战，为王国坚守防线。"},{t="囚于撕裂者之石",b="黑石氏族从燃烧平原向北推进，进入了赤脊山。基沙恩加入了石堡要塞的守军，但兽人的攻势击溃了他们。兽人将他生擒，拖进撕裂者之石深处，他就此被囚禁在敌后。联盟救援队必须一路杀进去，才能将他救出。"}},faq={{q="约翰·杰·基沙恩是谁？",a="约翰·杰·基沙恩下士在暴风城军中服役，曾在赤脊山与黑石兽人作战。他在石堡要塞周围的战斗中被俘，随后被带往撕裂者之石。",al={"基沙恩的故事","基沙恩是谁","基沙恩下士"}},{q="基沙恩为何被囚禁在撕裂者之石？",a="在石堡要塞周围的战斗中，黑石兽人击败了基沙恩，并将他生擒。他们把他拖到了撕裂者之石洞穴内的营地。",al={"基沙恩为何被俘","撕裂者之石的囚犯","基沙恩如何被俘"}}},fp="15,170,21.262.0,26.356.1,23.193.0,43.170.0"}
P.entries["npc:jonathan-carevin"] = {n="乔纳森·卡尔文",s="在夜色镇，乔纳森·卡尔文猎杀着聚集在暮色森林中的危险生物。他和家人深入守夜人巡逻范围之外，在林冠之下追猎亡灵、狼人、恶魔和异端。",h="在夜色镇，乔纳森·卡尔文猎杀着聚集在暮色森林中的危险生物。他和家人深入守夜人巡逻范围之外，在林冠之下追猎亡灵、狼人、恶魔和异端。",kw={"卡洛尔","卡尔文的家人","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","亡灵","狼人"},ang={["class:Hunter"]="身为猎人，你与Carevin一样，追踪并猎杀暮色森林中夜间出没的掠食者。",["class:Paladin"]="身为圣骑士，你或许能理解Carevin的热忱，以及他借助圣光对抗恶魔和亡灵腐化的呼声。",["faction:Alliance"]="如果你为联盟而战，致力于稳定暮色森林的局势，乔纳森·卡尔文就在打击那些暴风城未能遏制的超自然威胁。"},sec={{t="卡尔文十字军",b="守夜人守卫夜色镇，并沿道路巡逻，但乔纳森·卡尔文认为，仅靠防守无法保护镇子。他与家人以及卡洛尔等盟友一起，猎杀游荡在暮色森林中的邪恶生物。他以圣光之名展开征战，目标是遍布这片地区的恶魔、亡灵和异端。"},{t="狼人的阴影",b="乔纳森·卡尔文密切关注着森林中那些形似野狼的凶残狼人，就像关注骷髅和食尸鬼一样。它们的存在威胁着这个已被围困的镇子。他组织调查，试图查明狼人的来历，并阻止它们每夜四处游荡。"}},faq={{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文以夜色镇的家为据点，在暮色森林中猎杀怪物。他带领家人，直接对抗那些出没于森林中的生物。",al={"卡尔文是谁","乔纳森·卡尔文的故事","卡尔文 夜色镇"}},{q="他与守夜人有何不同？",a="守夜人守卫夜色镇，并看守镇上的道路。乔纳森和他的盟友则在暮色森林中追猎亡灵和其他怪物，力求从源头上将它们消灭。",al={"他是守夜人成员吗","卡尔文与守夜人的区别"}},{q="他对抗哪些威胁？",a="乔纳森猎杀亡灵、狼人、恶魔，以及任何庇护或帮助这些生物的人。",al={"卡尔文猎杀什么","卡尔文的目标"}},{q="乔纳森隶属于血色十字军吗？",a="乔纳森激烈的言辞、对圣光的虔诚，以及对腐化的零容忍，与血色的信条颇为相似。他与家人在夜色镇独立行动。",al={"卡尔文 血色十字军","卡尔文属于血色吗"}},{q="谁协助乔纳森执行使命？",a="乔纳森的家人以及卡洛尔等盟友，帮助他猎杀在林间出没的怪物。",al={"卡尔文的盟友","谁帮助卡尔文"}},{q="他与狼人有什么关联？",a="乔纳森认为，狼人是威胁暮色森林居民的非自然生物。他请旅行者调查这些荒野中的狼人从何而来。",al={"卡尔文 狼人","卡尔文为何憎恨狼人"}}},fp="16,171,19.304.0,24.258.1,24.152.0,40.175.0,27.87.0,48.155.0,36.95.0,37.142.0"}
P.entries["npc:jorah-annison"] = {n="约拉·安尼森",s="在魔法区，约拉·安尼森帮助施法者寻找散落在艾泽拉斯各地的知识。这位被遗忘者制图师既熟悉地理，也了解术士寻求的古籍。",h="在魔法区，约拉·安尼森帮助施法者寻找散落在艾泽拉斯各地的知识。这位被遗忘者制图师既熟悉地理，也了解术士寻求的古籍。",kw={"安尼森","制图师","约拉","魔法区","地图","阴谋之书","幽暗城","术士"},ang={["class:Warlock"]="身为部落术士，你可以向约拉询问阴谋之书遗失书页的下落。",["faction:Horde"]="身为部落的一员，你可以借助约拉的制图知识，穿行于陌生的土地，寻回珍贵的遗物。",["race:Undead"]="身为亡灵，你与约拉同住在幽暗城，他的制图工作有助于被遗忘者的生存。"},sec={{t="晦暗之地的学者",b="约拉·安尼森在幽暗城的魔法区绘制地图，但这份工作提不起他的兴趣。他宁愿用店里所有的地图换一本好书。约拉对古籍的了解几乎无人能及，术士们也和他一样，欣赏学者的著述。"},{t="密谋集团的踪迹",b="寻找神秘古籍阴谋之书的术士，常常会被指引去找约拉·安尼森。他的见识远不止于洛丹伦废墟，还能指出哪些地方可能藏有古籍和黑暗教派的遗迹。他将古老传说的研究与遥远土地的地理知识结合起来。"}},faq={{q="约拉·安尼森是谁？",a="约拉·安尼森是幽暗城魔法区的一名亡灵制图师，在那里为部落旅人提供地理和历史遗址方面的知识。",al={"约拉·安尼森是谁","约拉是谁","幽暗城制图师"}},{q="在哪里可以找到约拉·安尼森？",a="你可以在洛丹伦废墟下方、幽暗城的魔法区找到约拉·安尼森。",al={"约拉·安尼森位置","约拉·安尼森在哪里","寻找约拉"}},{q="术士为什么需要与他交谈？",a="斯坦哈德·法尔杉会让寻找古籍阴谋之书的术士去找约拉，因为在他认识的人中，约拉对古籍最为了解。约拉会指引他们寻找这部古籍遗失的上下两部分，据说一部分在千针石林的半人马手中，另一部分在运送途中遗失于南海镇以西的海岸。",al={"约拉术士任务","阴谋之书 约拉","为什么与约拉交谈"}},{q="约拉·安尼森属于哪个阵营？",a="约拉·安尼森属于被遗忘者，效忠部落，并在族人的首都为他们效力。",al={"约拉是部落吗","约拉·安尼森阵营"}},{q="约拉·安尼森会直接向玩家出售地图吗？",a="约拉·安尼森主要为旅人提供有关被遗忘地标的指引，而非直接出售货物。",al={"约拉出售地图吗","约拉商人"}},{q="约拉·安尼森会出现在幽暗城以外的地方吗？",a="约拉·安尼森一直待在幽暗城的魔法区，不过他绘制的地图和提供的指引涉及贫瘠之地等遥远地区。",al={"贫瘠之地的约拉","幽暗城外的约拉"}}},fp="13,165,27.250.0,17.295.0,21.149.0,31.92.0,39.301.0,42.110.0,49.100.0,50.126.0"}
P.entries["npc:jordan-stilwell"] = {n="乔丹·斯迪威尔",s="在丹莫罗的铁炉堡大门外，乔丹·斯迪威尔照看着自己的熔炉。他原本被寄望加入圣光教会，却追随父亲走上了锻造之路，并向白洛尔·石手学习技艺。如今，他打造的武器装备着联盟各地的圣骑士。",h="在丹莫罗的铁炉堡大门外，乔丹·斯迪威尔照看着自己的熔炉。他原本被寄望加入圣光教会，却追随父亲走上了锻造之路，并向白洛尔·石手学习技艺。如今，他打造的武器装备着联盟各地的圣骑士。",kw={"白洛尔·石手","伯施·维里甘","达芙妮·斯迪威尔","丹莫罗","铁炉堡","乔丹·斯迪威尔","影牙城堡","勇气之书","维里甘之拳"},ang={["class:Paladin"]="身为圣骑士，你可能会受乔丹·斯迪威尔之托，前往艾泽拉斯各地寻找稀有材料，打造你的标志性战锤维里甘之拳。",["faction:Alliance"]="逃离银松森林中阿鲁高麾下的狼人后，乔丹在丹莫罗的矮人中找到了庇护。如今，他以自己的锻造技艺为联盟勇士效力。",["profession:Blacksmithing"]="乔丹曾向白洛尔·石手学习，使用着从父亲那里继承的附魔铁锤。他的作品跻身凡人神圣锻造技艺的巅峰之列。"},sec={{t="铁砧旁的召唤",b="乔丹·斯迪威尔原本被寄望立下神圣誓言，成为圣光教会的一名圣骑士。他却追随父亲走上了锻造之路，接过了父亲的附魔铁锤。矮人铁匠白洛尔·石手帮助他磨炼了技艺。乔丹依然虔诚地信奉圣光，并用自己的手艺为以圣光之名而战的勇士效力。"},{t="逃离银松森林",b="乔丹曾在银松森林中席瓦莱恩男爵的城堡里担任铁匠。后来，大法师阿鲁高向要塞释放了凶残的狼人，将它变成了影牙城堡。乔丹逃离了这场血腥屠戮，留下了自己的熔炉和昔日的家园。此后，他在丹莫罗的矮人中找到了庇护。"},{t="锻造维里甘之拳",b="乔丹在铁炉堡大门附近的露天熔炉旁工作。比起山腹内大锻炉的酷热，他更喜欢高山上的空气。圣光教会将合格的圣骑士派到他这里，而他会让他们前往世界各地，收集打造一柄传奇双手战锤所需的稀有材料。为纪念老友伯施·维里甘，乔丹将这件武器命名为维里甘之拳。它的钢铁凝聚着信仰与精湛的技艺。"}},faq={{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一名人类铁匠，在丹莫罗的铁炉堡大门外工作。他为圣光教会的圣骑士打造神圣武器，其中就包括维里甘之拳。",al={"乔丹·斯迪威尔是谁","乔丹·斯迪威尔的故事","铁炉堡外的铁匠是谁"}},{q="乔丹·斯迪威尔为什么在外面的雪地里工作，而不在铁炉堡内？",a="暴风城的达索瑞恩·拉尔说，比起铁炉堡内大锻炉令人窒息的闷热，乔丹更喜欢丹莫罗清冽的山间空气。",al={"乔丹为什么在铁炉堡外","为什么在丹莫罗工作","他为什么在雪地里"}},{q="乔丹·斯迪威尔与影牙城堡有什么渊源？",a="乔丹曾在银松森林中席瓦莱恩男爵的庄园里担任铸甲师和铁匠。他在那场叛乱之前或期间逃了出来，当时大法师阿鲁高和他麾下凶残的狼人屠杀了驻军，夺取了要塞。",al={"乔丹·斯迪威尔 影牙城堡","乔丹·斯迪威尔 银松森林","他住过焚木村吗"}},{q="维里甘之拳是什么？",a="维里甘之拳是乔丹·斯迪威尔为联盟圣骑士锻造的一柄强大的神圣双手战锤。他以老友伯施·维里甘的名字为它命名。",al={"维里甘之拳","维里甘的战锤","维里甘是谁"}},{q="谁传授了乔丹·斯迪威尔锻造技艺？",a="乔丹从父亲那里继承了锻造技艺和一把附魔铁锤。他在矮人铁匠白洛尔·石手的指导下精进了手艺。",al={"谁教过乔丹·斯迪威尔","乔丹·斯迪威尔的老师","他在哪里学的锻造"}},{q="乔丹·斯迪威尔的妻子是谁？",a="乔丹的妻子是达芙妮·斯迪威尔。多年来，他们共同为圣光教会提供了许多帮助，两人都因无比虔诚地侍奉信仰而备受敬重。",al={"乔丹·斯迪威尔的妻子","达芙妮·斯迪威尔的丈夫","达芙妮·斯迪威尔"}}},fx={["49deb919"]={q="乔丹·斯迪威尔效忠哪一方？",a="乔丹坚定地效忠于联盟与圣光教会。虽然他住在丹莫罗的矮人之间，在铁炉堡外从事锻造，却始终与暴风城的圣骑士保持着紧密联系，用自己的手艺武装虔诚信徒，抵御威胁王国的黑暗。",al={"乔丹·斯迪威尔的阵营","乔丹·斯迪威尔是否属于联盟","乔丹·斯迪威尔效忠谁"}},dd0bfe26={q="乔丹·斯迪威尔想要什么？",a="乔丹希望为值得托付的圣骑士锻造一件非凡的武器，以此纪念他的老友伯施·维里甘。为了打造神圣战锤维里甘之拳，他需要从艾泽拉斯各地收集稀有材料：他的恩师白洛尔·石手提供的精炼矿石、白石橡木、净化过的科尔宝石，以及他父亲遗失的锻造之锤。",al={"乔丹·斯迪威尔需要什么","乔丹·斯迪威尔的目标","乔丹·斯迪威尔的目的"}},["3def62e7"]={q="乔丹·斯迪威尔为什么出名？",a="乔丹是一位闻名遐迩的杰出武器锻造师，他对圣光的虔诚与他的锻造技艺同样深厚。他原本打算成为圣骑士，后来却选择继承父亲的手艺，并与妻子达芙妮一道，为圣光教会提供了莫大的帮助，教会至今仍将他视为最虔诚的信徒之一。",al={"乔丹·斯迪威尔是否出名","乔丹·斯迪威尔的声望","乔丹·斯迪威尔为何闻名"}}},fp="15,248,22.368.0,22.302.0,22.427.1,23.185.0,78.127.0,56.233.0,23.146.0,45.143.0,30.177.0"}
P.entries["npc:jorgen"] = {n="乔贞",s="在暴风城的英雄谷入口，乔贞守在水边，留意着来往的动静。他所在的僻静角落，吸引着那些有事不便公开谈论的人。",h="在暴风城的英雄谷入口，乔贞守在水边，留意着来往的动静。他所在的僻静角落，吸引着那些有事不便公开谈论的人。",kw={"德拉维主教","埃林·提亚斯","线人","乔贞","失踪的外交官","暴风城","英雄谷"},ang={["class:Rogue"]="身为盗贼，你能看出消息如何在暴风城的大理石街道之下暗中流传。乔贞与经由Trias’ Cheese开展的秘密活动关系密切。",["faction:Alliance"]="身为联盟的一员，你知道在暴风城通过官方渠道办事，可能会遇上官僚作风的阻碍。乔贞这样的街头线人，能帮助追查威胁王国的隐患。"},sec={{t="水边的耳目",b="乔贞常待在暴风城宏伟入口右侧的水边。他头顶的英雄雕像俯瞰着桥梁，而他则注视着下方的过客。想打听消息又不愿留下记录的人，可以在那里找到一位低调的接头人。"},{t="错综复杂的过往",b="乔贞的过往牵涉到兼事情报搜集的奶酪商大师埃林·提亚斯，以及光明大教堂的德拉维主教。一名外交官奉命前往塞拉摩后失踪，调查者追查此事时，乔贞能为他们指明方向。当地很少有接头人知道该如何查探这类敏感的事情。只有谨慎地与乔贞接洽，他才会提供帮助。"}},faq={{q="在哪里可以找到乔贞？",a="乔贞在暴风城英雄谷的水边等候。从艾尔文森林穿过城门进入城内，然后往主桥右侧的水边走去。",al={"乔贞位置","乔贞在哪","寻找乔贞"}},{q="乔贞在暴风城与谁有联系？",a="乔贞与埃林·提亚斯及光明大教堂的德拉维主教有旧交，前者是贸易区一位颇有名望、暗中另有人脉的奶酪商。",al={"乔贞的人脉","乔贞的关系","乔贞认识谁"}},{q="乔贞在失踪外交官的调查中起什么作用？",a="在寻找失踪使节的过程中，德拉维主教让调查者带着一封信，去找他的老朋友乔贞。乔贞勉强答应帮忙，要求他们发誓保密，然后让他们带着一封密封的便笺，去提亚斯奶酪店找埃林·提亚斯。",al={"乔贞失踪的外交官","乔贞任务"}},{q="乔贞隶属于暴风城卫兵吗？",a="不。乔贞独立行事，避开暴风城卫兵沿运河两岸巡逻的路线。在那里，人们可以交谈而不被旁人听见。",al={"乔贞是卫兵吗","乔贞阵营"}}},fx={["536f8488"]={q="乔贞是谁？",a="乔贞是个神秘人物，穿过暴风城宏伟的正门，就能在英雄谷的水边看到他静静逗留。他没有担任任何正式的市政职务，而是在首都事务的边缘活动，拥有深厚的人脉，以及一段与埃林·提亚斯大师和德拉维主教密切相关、尚未揭晓的过往。",al={"乔贞是谁","乔贞 暴风城","乔贞的身份"}},["846a3fb1"]={q="乔贞为什么在这里？",a="乔贞留在英雄谷边缘，充当暴风城内一处隐秘的联络点。他就在城门附近，避开窥探的目光，随时准备协助埃林·提亚斯这样的可信联系人，悄悄处理需要谨慎行事的秘密调查。",al={"乔贞为什么在这里","乔贞在此的原因","乔贞为什么在暴风城"}}},fp="6,150,17.244.0,17.376.1,24.174.0,40.157.0,72.248.0,51.141.0"}
P.entries["npc:josef-gregorian"] = {n="乔瑟夫·格里高利",s="在幽暗城的魔法区，乔瑟夫·格里高利为部落培养裁缝。他凭借精湛的技艺，指引他们学习制作附魔织物和专门的衣装。",h="在幽暗城的魔法区，乔瑟夫·格里高利为部落培养裁缝。他凭借精湛的技艺，指引他们学习制作附魔织物和专门的衣装。",kw={"收集材料","乔瑟夫·格里高利","魔法区","魔焰长袍","裁缝训练师","幽暗城"},ang={["profession:Tailoring"]="对部落的制衣匠而言，乔瑟夫·格里高利是洛丹伦的一位裁缝训练师，也会为带来材料的年轻法师缝制长袍。",["race:Undead"]="身为一名亡灵裁缝，乔瑟夫·格里高利延续着人类精细的裁缝技艺，这门手艺历经洛丹伦的陷落而留存，如今为被遗忘者社会服务。"},sec={{t="魔法区的织布者",b="乔瑟夫·格里高利在幽暗城的魔法区教授裁缝，被遗忘者及其部落盟友在这里研习这门手艺。对于通过织物纤维引导原始能量的术士、法师和牧师而言，裁缝依然至关重要。格里高利传授基础图样，也为带来所需材料的年轻法师缝制他们的第一件长袍。"}},faq={{q="在哪里可以找到乔瑟夫·格里高利？",a="乔瑟夫·格里高利在幽暗城的魔法区工作并授艺，与城中的施法者和学者为邻。",al={"乔瑟夫·格里高利位置","格里高利在哪里","幽暗城裁缝训练师"}},{q="乔瑟夫·格里高利在幽暗城担任什么职务？",a="乔瑟夫·格里高利向部落工匠传授缝纫图样和技法。他也为安娜斯塔西娅·哈特威尔派来的年轻法师缝制他们的第一件长袍。",al={"乔瑟夫·格里高利做什么","乔瑟夫·格里高利训练师","幽暗城裁缝"}},{q="乔瑟夫·格里高利提供哪些任务？",a="安娜斯塔西娅·哈特威尔派年轻法师带着亚麻布和在银松森林取得的达拉然法力宝石，前去找乔瑟夫·格里高利。他用这些材料为他们缝制魔焰长袍。",al={"乔瑟夫·格里高利任务","幽暗城长袍任务"}}},fp="15,153,27.328.0,33.114.0,54.149.0,39.185.0"}
P.entries["npc:kaal-soulreaper"] = {n="卡尔·噬灵",s="在幽暗城，兽人术士卡尔·噬灵训练学徒，并与部落各地的黑暗法术研习者保持密切联系。在被遗忘者之中，他指引学生前往远方，向那里的导师求教。",h="在幽暗城，兽人术士卡尔·噬灵训练学徒，并与部落各地的黑暗法术研习者保持密切联系。在被遗忘者之中，他指引学生前往远方，向那里的导师求教。",kw={"恶魔学","地狱战马","卡尔·噬灵","魔法区","梅纳拉·沃伦德","幽暗城","术士训练师"},ang={["class:Warlock"]="身为术士，你可以向卡尔·噬灵学习恶魔法术，他传授的基础技艺能让胸怀抱负的术士踏上制作奥拉赫宝珠与束缚Felsteed的道路。",["race:Orc"]="身为兽人，你可以在被遗忘者的首都找到公开传授技艺的卡尔·噬灵，远离奥格瑞玛萨满领袖的严密监视，也远离暗影裂口中隐秘的术士集会。"},sec={{t="暗影中的研习者",b="卡尔·噬灵在幽暗城的魔法区传授技艺，部落术士来到这里，学习他驾驭恶魔与施展诅咒的本领。萨尔领导的部落严格管制并监视奥格瑞玛境内的邪能魔法，而洛丹伦的地下密所则为卡尔这样的研习者提供了充足的容身之地。除了授课，卡尔还为追求更强大力量的人引荐海对岸的导师，其中就包括贫瘠之地的梅纳拉·沃伦德。"}},faq={{q="卡尔·噬灵是谁？",a="卡尔·噬灵在幽暗城的魔法区训练术士。他传授术士法术，并为寻求特殊黑暗神器与仪式的研习者提供指引。",al={"卡尔是谁","卡尔·噬灵的故事","卡尔 幽暗城"}},{q="为什么一个兽人术士会住在幽暗城？",a="在大酋长萨尔统领的兽人社会中，术士面临着深重的猜疑与严密的审视。幽暗城的环境更为宽容，让他们能够与被遗忘者一同研究暗影魔法和恶魔学。",al={"为什么兽人在幽暗城","为什么卡尔在幽暗城"}},{q="卡尔·噬灵会派学徒去哪里？",a="当学生的技艺足够娴熟时，卡尔会派他们渡过无尽之海，前往贫瘠之地向梅纳拉·沃伦德求学，或将他们引荐给部落其他杰出的术士。",al={"卡尔的任务","卡尔派人去找谁"}}},fp="15,178,29.383.0,23.157.0,46.175.0,48.183.0"}
P.entries["npc:kadrak"] = {n="卡德拉克",s="卡德拉克驻守莫尔杉壁垒，守卫贫瘠之地与灰谷之间的北部边境。他向这片争夺中的森林传递军情、调派援军，部落正在那里与暗夜精灵交战。",h="卡德拉克驻守莫尔杉壁垒，守卫贫瘠之地与灰谷之间的北部边境。他向这片争夺中的森林传递军情、调派援军，部落正在那里与暗夜精灵交战。",kw={"灰谷","贫瘠之地","卡德拉克","莫尔杉壁垒","兽人","壁垒","碎木岗哨","战歌"},ang={["class:Warrior"]="身为战士，你知道，要在林地战士的进攻和游击袭扰下守住一处设防的隘口，需要怎样的纪律。",["faction:Alliance"]="如果你为联盟而战，试图从灰谷进入贫瘠之地，卡德拉克驻守的壁垒就会挡住通往部落腹地的道路。",["faction:Horde"]="身为部落的一员，你可以指望卡德拉克指引战士北上，保卫伐木作业，并为部落夺取灰谷的领地。",["race:Orc"]="身为兽人，你可以将卡德拉克对灰谷边境的防守视为战歌氏族争夺领地的一部分。"},sec={{t="壁垒的守卫",b="卡德拉克驻守莫尔杉壁垒，把守贫瘠之地与灰谷之间的主要通道。这道路障划出了一条森严的边界：南面是部落控制的平原，北面则是暗夜精灵守卫的森林。卡德拉克警戒着哨兵和充满敌意的林地生物，守住防线，抵御入侵。"},{t="前线军务",b="卡德拉克也负责处理贫瘠之地与灰谷深处伐木营地之间的军事报告。信使为他带来战歌氏族的战报，他则向碎木岗哨等前哨调配补给和援军。前来向卡德拉克报到的人，会被继续派往争夺森林的战场。"}},faq={{q="卡德拉克是谁？",a="卡德拉克是驻守莫尔杉壁垒的兽人军官。他监管边境，指挥往来于贫瘠之地与灰谷战场之间的部落军队。",al={"卡德拉克身份","城墙边的兽人是谁","莫尔杉壁垒指挥官"}},{q="在哪里可以找到卡德拉克？",a="卡德拉克位于莫尔杉壁垒，那是贫瘠之地北部边缘一道加固的木制路障，道路从这里通往灰谷。",al={"卡德拉克位置","寻找卡德拉克","卡德拉克在哪里"}},{q="卡德拉克在部落中担任什么职责？",a="卡德拉克指挥边境防御，并收集侦察信使送来的军事报告。他向北上增援碎木岗哨等前哨的部落旅人交代军情。",al={"卡德拉克职责","卡德拉克做什么","卡德拉克的作用"}},{q="莫尔杉壁垒为何戒备森严？",a="莫尔杉壁垒守卫着通往贫瘠之地和杜隆塔尔的北部通道，抵御暗夜精灵为回应部落在灰谷的伐木行动而发动的入侵。",al={"莫尔杉壁垒为何设防","壁垒的用途","为何守卫灰谷边境"}},{q="卡德拉克提供哪些任务，又接受哪些任务的交付？",a="卡德拉克接收从贫瘠之地送来的报告，并派遣冒险者执行任务，处理战歌的侦察报告，巩固部落在森林边境的势力。",al={"卡德拉克任务","向卡德拉克报告","战歌报告"}},{q="卡德拉克与其他部落要人有联系吗？",a="卡德拉克与灰谷的战歌氏族保持定期联系，并在壁垒接收他们的侦察报告。",al={"卡德拉克的联系"}}},fp="6,167,23.293.0,19.296.0,14.157.0,26.131.0,35.173.0,45.163.0,44.176.0,53.123.0"}
P.entries["npc:kaela-shadowspear"] = {n="凯拉·影矛",s="在石爪山脉，凯拉·影矛守望着狂风峭壁西南方的荒野。局势日益紧张，大地又遭侵扰，她与其他哨兵协同行动。旅人们协助侦察险地，查明古老的守护者遭到腐化的原因。",h="在石爪山脉，凯拉·影矛守望着狂风峭壁西南方的荒野。局势日益紧张，大地又遭侵扰，她与其他哨兵协同行动。旅人们协助侦察险地，查明古老的守护者遭到腐化的原因。",kw={"古树","凯拉","尘链","哨兵","影矛","精魂","石爪山脉","塞恩希尔","狂风峭壁"},ang={["class:Druid"]="身为德鲁伊，你可以协助凯拉查明焦炭谷的古树遭到腐化的原因，并缓解那些受到侵扰的自然之灵的痛苦。",["faction:Alliance"]="身为联盟冒险者，你可以从石爪山脉的争夺地区为凯拉带回情报，并协助相距遥远的哨站互通消息。",["race:NightElf"]="身为暗夜精灵，你深知守护圣地的必要。凯拉努力安抚愤怒的精魂，保护卡利姆多备受尊崇的古树。"},sec={{t="边境斥候",b="凯拉·影矛守望着狂风峭壁西南方的山口。部落向石爪山脉推进，地精则在此开采这片土地丰富的自然资源。凯拉与侏儒加克希姆·尘链并肩行动，追踪那些不断深入暗夜精灵祖地的威胁。"},{t="治愈大地",b="对自然的暴行激怒了元素，也伤害了森林中古老的守护者。凯拉派遣旅人对抗狂暴的精魂，并追查那些曾守护焦炭谷的受伤树人遭到腐化的原因。她努力恢复安宁，以免大地遭受无法弥合的创伤。"}},faq={{q="凯拉·影矛是谁？",a="凯拉·影矛是一名暗夜精灵哨兵，驻守在石爪山脉狂风峭壁西南方的一处边境营地。她负责侦察事务，并协助保护当地的野生生物与精魂。",al={"凯拉是谁","凯拉·影矛身份","凯拉非玩家角色"}},{q="在哪里可以找到凯拉·影矛？",a="凯拉位于狂风峭壁西南方的一处联盟小营地，就在穿越石爪山脉的道路旁。侏儒工程师加克希姆·尘链也驻扎在这里。",al={"凯拉·影矛位置","凯拉在哪","凯拉石爪山脉营地"}},{q="凯拉向谁汇报？",a="凯拉与哨兵塞恩希尔协同行动，互通石爪山脉各地的敌军动向与当地威胁的情报。",al={"凯拉向谁汇报","凯拉塞恩希尔","凯拉的指挥官"}},{q="凯拉为何担忧元素生物？",a="风险投资公司.放火焚烧焦炭谷，又用机器撕裂大地，释放了火焰、岩石与愤怒的精魂。凯拉希望削减它们的数量，让大地得以恢复。",al={"怒灵任务","精魂为何愤怒","凯拉元素之灵"}},{q="狂风峭壁附近的古树怎么了？",a="守护焦炭谷的树人曾协助击退风险投资公司.，但此后它们却遭到了腐化。加克希姆怀疑是地精的武器所致，因此凯拉请旅人从受伤的树人身上取来一块被腐蚀的弹片，交给他研究。",al={"受伤的古树任务","凯拉古树","石爪山脉受伤的古树"}},{q="为什么有一名侏儒与凯拉一同驻守？",a="凯拉与联盟侏儒加克希姆·尘链共用一处营地。她照看荒野中的精魂，维持当地的战术平衡，而加克希姆则对抗附近敌对地精的机械与作业活动。",al={"加克希姆·尘链凯拉","加克希姆为何与凯拉同行","侏儒与暗夜精灵营地"}}},fp="17,170,23.279.0,16.289.0,25.157.0,37.164.0,25.124.0,44.198.0,54.260.0,36.203.0"}
P.entries["npc:kali-remik"] = {n="卡利·雷米克",s="在森金村，卡利·雷米克指引年轻猎人前往下一处训练地点。她是一名黑暗之矛巨魔猎人，熟悉在杜隆塔尔追踪和生存的技巧。",h="在森金村，卡利·雷米克指引年轻猎人前往下一处训练地点。她是一名黑暗之矛巨魔猎人，熟悉在杜隆塔尔追踪和生存的技巧。",kw={"黑暗之矛","杜隆塔尔","卡利·雷米克","森金村","猎人之道","追踪者","精神谷"},ang={["class:Hunter"]="作为一名年轻的兽人或巨魔猎人，当村里的操练已不足以提升你的本领时，你可以向卡利·雷米克寻求指引。她会让你前往剃刀岭，向索塔尔求教。",["race:Troll"]="作为一名黑暗之矛巨魔，你与卡利·雷米克同属一个氏族。当族人们沿着杜隆塔尔的海岸重建生活，并在奥格瑞玛的精神谷定居时，她守护着他们。"},sec={{t="狩猎的引路人",b="卡利·雷米克在森金村指引年轻的斥候，他们在这里开始试炼谷之外的生活。身为黑暗之矛巨魔追踪者，她熟悉杜隆塔尔的旱地和部落的定居点。当新手准备好离开当地的训练场时，卡利·雷米克便会将有潜力的猎人送往剃刀岭，向索塔尔求教。他们在那里开始学习驯服野兽，为部落的边疆队伍增添力量。"}},faq={{q="卡利·雷米克是谁？",a="卡利·雷米克是一名黑暗之矛巨魔猎人兼斥候，为准备好继续深造的年轻猎人指引方向。",al={"卡利·雷米克背景故事","卡利·雷米克是谁","卡利·雷米克非玩家角色"}},{q="在哪里可以找到卡利·雷米克？",a="在杜隆塔尔可以找到卡利·雷米克，尤其是在森金村一带，她在那里帮助自己的族人。",al={"卡利·雷米克在哪里","卡利·雷米克位置","寻找卡利·雷米克"}},{q="她为猎人提供什么指引？",a="卡利·雷米克指引那些已证明自己掌握基本技能的年轻兽人和巨魔猎人前往剃刀岭。在那里，索塔尔引导他们踏上驯服野兽伙伴的道路。",al={"猎人之道任务","卡利·雷米克猎人任务","卡利教什么"}}},fp="10,158,20.375.0,18.113.0,30.89.0,40.159.0"}
P.entries["npc:kaltunk"] = {n="卡尔图克",s="在杜隆塔尔的试炼谷腹地，卡尔图克迎接年轻的兽人，指引他们履行为部落效力的第一份职责。",h="在杜隆塔尔的试炼谷腹地，卡尔图克迎接年轻的兽人，指引他们履行为部落效力的第一份职责。",kw={"杜隆塔尔","高内克","卡尔图克","兽人新手","试炼谷","在世界中的位置"},ang={["faction:Horde"]="身为部落的一员，你能看到卡尔图克如何帮助杜隆塔尔这片严酷的试炼之地维持秩序。",["race:Orc"]="作为一名即将踏入卡利姆多的兽人，当你开始赢取属于自己的荣耀时，最先听到的便是卡尔图克粗声粗气的指示。"},sec={{t="第一步",b="卡尔图克照看初到试炼谷的兽人，指引他们前去寻找高内克，踏上磨炼纪律之路。训练师和长者安排试炼与狩猎仪式，而这位兽人监工则向新兵下达明确的命令，让他们知道该去哪里。"},{t="谷地的看守者",b="试炼谷被选作试炼之地，用来考验那些行走在谷底的年轻人的力量与韧性。卡尔图克也以同样坚韧务实的态度履行职责。他既不高谈阔论，也不娇惯新兵，而是期望每个兽人都能在世上找到自己的位置，为大酋长效力。"}},faq={{q="卡尔图克是谁？",a="卡尔图克是试炼谷的一名兽人监工。刚刚醒来的兽人冒险者最先遇到的就是他，他会指引他们寻找导师，开始训练。",al={"卡尔图克职责","这个兽人是谁","卡尔图克非玩家角色"}},{q="卡尔图克为新冒险者做些什么？",a="卡尔图克交给新兵的第一项任务，是去与谷中另一处的高内克交谈，以便开始训练。",al={"卡尔图克任务","卡尔图克想要什么","试炼谷第一个任务"}},{q="在哪里可以找到卡尔图克？",a="卡尔图克站在杜隆塔尔南部幽静的试炼谷中，就在中央训练帐篷和营火附近。",al={"卡尔图克位置","寻找卡尔图克","卡尔图克在哪里"}},{q="他为什么驻守在试炼谷？",a="卡尔图克迎接前来报到的兽人新兵，维持他们的秩序，并引导他们踏上为萨尔的部落效力的道路。",al={"卡尔图克为什么在这里","卡尔图克的作用"}}},fp="7,115,14.230.0,20.266.0,15.171.0,41.117.0,25.113.0,44.115.0"}
P.entries["npc:kam-deepfury"] = {n="卡姆·深怒",s="在暴风城的监狱里，卡姆·深怒与迪菲亚叛军分开关押。这个黑铁矮人因策划炸毁遥远北方的萨多尔大桥而被捕。",h="在暴风城的监狱里，卡姆·深怒与迪菲亚叛军分开关押。这个黑铁矮人因策划炸毁遥远北方的萨多尔大桥而被捕。",kw={"黑铁","卡姆·深怒","丹莫德","莫特雷·加玛森","监狱","暴风城","萨多尔大桥"},ang={["faction:Alliance"]="暴风城忙于应对迪菲亚起义时，卡姆·深怒提醒着联盟，黑铁仍在威胁其北部边疆。",["race:Dwarf"]="身为铁炉堡的矮人，你知道卡姆·深怒就是炸毁萨多尔大桥、杀害布莱德·长须亲族的破坏者。以荣誉之名，为逝者复仇。"},sec={{t="远离故土的破坏者",b="卡姆·深怒是一名黑铁矮人，被关押在暴风城监狱深处。那里的囚犯大多是心怀不满的石匠或迪菲亚叛军，但他两者都不是。在一次破坏北方重要基础设施的行动后，他被捕并押送至暴风城，与黑石山下的同族隔绝。与那些同囚一处的叛军一样，他也敌视联盟。"},{t="萨多尔大桥的破坏行动",b="湿地北部边境附近的丹莫德传来联盟情报，指出卡姆·深怒是炸毁萨多尔大桥的主谋。爆炸炸断了连接湿地与阿拉希高地的巨型石桥之一。这重创了铁炉堡和联盟的一条重要商贸与军事通道，还夺走了矮人指挥官布莱德·长须一位亲族的性命。"},{t="待偿的血债",b="莫特雷·加玛森与悲痛的布莱德·长须正在湿地招募雇佣兵，要他们前往暴乱中的暴风城监狱，找到卡姆·深怒。这名黑铁叛乱者暂时躲在监狱里，避开受害者的亲属。追寻他的人要取下他的首级，清算那桩始于数百英里外北方的血仇。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是一名被关押在暴风城监狱的黑铁矮人囚犯。他因策划破坏萨多尔大桥而闻名，与同囚一处的迪菲亚叛军并无隶属关系。",al={"卡姆·深怒是谁","卡姆·深怒的故事","监狱里的矮人是谁"}},{q="为什么一个黑铁矮人会被关进暴风城监狱？",a="卡姆·深怒因组织炸毁萨多尔大桥的一座桥梁而被捕。爆炸杀死了布莱德·长须的一位矮人亲族，并切断了湿地与阿拉希高地之间的一条重要通道。",al={"他为何被关进监狱","卡姆·深怒做了什么","他为何被囚禁"}},{q="卡姆·深怒是迪菲亚潜行者的一员吗？",a="不是。卡姆·深怒是一名黑铁矮人，并非迪菲亚潜行者的成员。他与叛军关押在一起，也和他们一样敌视联盟。",al={"他是迪菲亚成员吗","卡姆·深怒与迪菲亚","卡姆·深怒是否与范克里夫合作"}},{q="谁想要卡姆·深怒的命？",a="莫特雷·加玛森和布莱德·长须想要卡姆·深怒的命。萨多尔大桥的爆炸夺走了布莱德·长须一位亲族的性命，两人因此招募雇佣兵，前往暴风城的监狱找到卡姆·深怒。",al={"谁给了卡姆·深怒的任务","谁想杀死卡姆·深怒"}},{q="卡姆·深怒在哪里犯下了罪行？",a="卡姆·深怒在萨多尔大桥组织了破坏行动，那里的桥梁连接着湿地与阿拉希高地。",al={"桥在哪里被炸毁","卡姆·深怒炸桥","萨多尔大桥袭击"}},{q="在监狱的什么地方能找到卡姆·深怒？",a="卡姆·深怒被关押在暴风城运河区下方的暴风城监狱牢区深处。",al={"卡姆·深怒在监狱哪里","卡姆·深怒的位置"}}},fp="12,204,24.354.0,25.402.0,17.347.1,20.176.0,58.231.0,47.164.0,28.198.0,40.115.0,52.111.0"}
P.entries["npc:kanati-greycloud"] = {n="卡纳提·灰云",s="卡纳提·灰云是一名牛头人猎人，驻守在千针石林的白沙岗哨。他与狩猎同伴竭力组织防御，抵御当地加拉克半人马持续不断的侵扰。",h="卡纳提·灰云是一名牛头人猎人，驻守在千针石林的白沙岗哨。他与狩猎同伴竭力组织防御，抵御当地加拉克半人马持续不断的侵扰。",kw={"刺杀阴谋","半人马","加拉克","灰云","卡纳提","千针石林","白沙岗哨"},ang={["faction:Horde"]="白沙岗哨是俯瞰千针峡谷的重要制高点；保住卡纳提的性命，就能确保部落斥候继续监视半人马部队的动向。",["race:Tauren"]="对穿行于千针石林的牛头人来说，在白沙岗哨援助卡纳提，是保护同族、抵御世代宿敌半人马的重要防卫行动。"},sec={{t="险境中的岗哨",b="卡纳提·灰云在白沙岗哨扎营，这座岗哨高踞于千针石林西部的砂岩石柱之上。峡谷中猎物充足，视野开阔，却被加拉克半人马团团围住，他们的战团争夺着下方干旱平地上的每一寸土地。卡纳提与其他牛头人猎人一同监视谷底，竭力守住岗哨，抵御周围劫掠者的残暴侵袭。"},{t="半人马的伏击",b="加拉克半人马不仅想孤立白沙岗哨，还打算彻底消灭这里的守卫。往来于半人马营地之间的信使携带着明确命令，要刺杀卡纳提和他的同伴。前来此地的旅人必须截获这些作战命令，并在加拉克劫掠队登上台地、屠戮岗哨猎人时，与卡纳提并肩作战。"}},faq={{q="卡纳提·灰云是谁？",a="卡纳提·灰云是一名牛头人猎人，驻扎在千针石林西部的白沙岗哨，在那里扎营，抵御当地四处袭掠的威胁。",al={"卡纳提是谁","卡纳提·灰云的故事","白沙岗哨牛头人"}},{q="在哪里可以找到卡纳提·灰云？",a="卡纳提位于白沙岗哨，那是一处地势高耸的牛头人营地，坐落在千针石林西部的北侧峭壁上。",al={"卡纳提的位置","卡纳提在哪里","灰云在哪里"}},{q="加拉克半人马为什么要杀他？",a="加拉克半人马企图彻底控制千针石林的峡谷，并不断袭击部落的岗哨。截获的命令揭露了半人马的一场协同阴谋，意图刺杀卡纳提，瓦解岗哨的防御。",al={"半人马为何袭击卡纳提","加拉克刺杀阴谋","为何保护卡纳提"}}},fx={["35c73e38"]={q="卡纳提·灰云站在哪一边？",a="卡纳提·灰云是一名效忠部落的牛头人猎人。他欢迎到访白沙岗哨的部落旅人，并依靠他们帮助营地抵御敌对势力的威胁。",al={"卡纳提的阵营","卡纳提是部落成员吗","卡纳提属于联盟还是部落"}},cf857b32={q="卡纳提·灰云想要什么？",a="卡纳提只希望自己的狩猎营地能安宁无事，并确保同伴们平安。当地的加拉克半人马企图赶走或屠杀所有闯入者，因此他最关心的是抵御他们的暗杀行动。",al={"卡纳提需要什么","卡纳提·灰云的目标","为什么要帮助卡纳提"}},["10a1bee5"]={q="卡纳提·灰云为什么在这里？",a="卡纳提和同伴们在白沙岗哨建立了一个狩猎营地，打算猎取千针石林的猎物。不幸的是，他们在峡谷中扎营，正好进入了敌对的加拉克半人马争夺的领地。",al={"卡纳提为什么在白沙岗哨","卡纳提在这里做什么","卡纳提·灰云的目的"}}},fp="16,171,18.320.0,14.310.1,24.141.0,34.103.0,45.183.0"}
P.entries["npc:kaplak"] = {n="卡普拉克",s="在剃刀岭，卡普拉克为部落训练年轻的兽人和巨魔潜行者。他教授潜行、诡诈与刀刃技艺，然后将他们送往奥格瑞玛。",h="在剃刀岭，卡普拉克为部落训练年轻的兽人和巨魔潜行者。他教授潜行、诡诈与刀刃技艺，然后将他们送往奥格瑞玛。",kw={"杜隆塔尔","卡普拉克","兽人","奥格瑞玛","剃刀岭","潜行者训练师","潜行","瑟祖克"},ang={["class:Rogue"]="作为一名刚离开试炼谷的年轻兽人或巨魔潜行者，你可以先向卡普拉克学习入门技艺，然后由他指引你接触奥格瑞玛的秘密组织。",["faction:Horde"]="作为部落的一员，你可以信赖卡普拉克，由他训练斥候、间谍和刺客，守卫杜隆塔尔，并在常规战线之外执行任务。"},sec={{t="暗影中的导师",b="卡普拉克在剃刀岭训练部落的新晋潜行者。兽人的传统崇尚正面交锋和咆哮冲锋，但他传授的是生存所需的隐秘技巧：悄然跟踪、开锁，以及从背后发动攻击。当学生们在杜隆塔尔尘土飞扬的红色峡谷中学成后，他便让他们北上奥格瑞玛，在那里向公会的资深成员精进技艺。"}},faq={{q="卡普拉克是谁？",a="卡普拉克是杜隆塔尔剃刀岭的一名兽人潜行者训练师。他向来自试炼谷的年轻兽人和巨魔潜行者传授基础技巧，然后将他们送往奥格瑞玛，向更高阶的训练师学习。",al={"卡普拉克是谁","卡普拉克背景故事","卡普拉克剃刀岭"}},{q="在哪里可以找到卡普拉克？",a="卡普拉克位于杜隆塔尔中部的聚居地剃刀岭。他通常与其他职业训练师一起，在当地兵营内或附近休息。",al={"卡普拉克在哪","卡普拉克位置","寻找卡普拉克"}},{q="卡普拉克提供哪些任务？",a="卡普拉克指引潜行者冒险者寻找高阶训练师，并接受进一步的任务。他可能会派他们前往奥格瑞玛寻找瑟祖克。",al={"卡普拉克任务","卡普拉克提供的任务"}}},fp="6,147,23.370.0,14.190.0,26.140.0,30.120.0"}
P.entries["npc:karang-amakkar"] = {n="卡拉恩·阿玛卡",s="在佐拉姆加前哨站，卡拉恩·阿玛卡监视着灰谷岩石嶙峋的海岸，以及四面逼近部落的威胁。",h="在佐拉姆加前哨站，卡拉恩·阿玛卡监视着灰谷岩石嶙峋的海岸，以及四面逼近部落的威胁。",kw={"灰谷","污林","熊怪","卡拉恩·阿玛卡","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="卡拉恩·阿玛卡帮助灰谷西部的部落旅人，派遣他们对付佐拉姆加前哨站周围的敌对生物。",["race:Orc"]="远离杜隆塔尔，卡拉恩·阿玛卡坚守着一座偏远的前哨站，展现出守卫危险边境的兽人哨兵的坚韧。"},sec={{t="灰谷海岸",b="在佐拉姆海岸的佐拉姆加前哨站，卡拉恩·阿玛卡守卫着部落最易受袭的边境之一。营地面临来自海上、暗夜精灵和内陆野兽的压力。卡拉恩监视着向东道路沿线的敌对族群，保护部落信使和斥候，防止他们遭到那些保卫领地的部族伏击。"},{t="应对熊怪",b="卡拉恩·阿玛卡将大量精力放在古老森林中的熊怪身上，尤其是污林部族。腐化与原始的敌意使这些熊人陷入狂乱。卡拉恩派遣能干的战士击败它们的首领，清剿它们的巢穴，以免这些部族集结起来，有组织地进攻佐拉姆加。"}},faq={{q="卡拉恩·阿玛卡是谁？",a="卡拉恩·阿玛卡是驻守在灰谷海岸佐拉姆加前哨站的一名兽人斥候。他为部落监视当地的威胁，尤其是敌对的熊怪氏族。",al={"卡拉恩","卡拉恩是谁","卡拉恩·阿玛卡背景故事"}},{q="在哪里可以找到卡拉恩·阿玛卡？",a="卡拉恩·阿玛卡位于灰谷西北海岸、佐拉姆海岸沿线的佐拉姆加前哨站。",al={"卡拉恩位置","卡拉恩·阿玛卡在哪里","卡拉恩·阿玛卡地点"}},{q="卡拉恩·阿玛卡提供哪些任务？",a="卡拉恩派遣部落冒险者对付附近的熊怪部族，并指引他们向污林的国王发起攻击。",al={"卡拉恩任务","卡拉恩差事","卡拉恩想要什么"}},{q="卡拉恩为什么担忧熊怪？",a="灰谷的熊怪变得野蛮而腐化。它们袭击旅人，还威胁着佐拉姆加前哨站与部落在当地其他据点之间的联系。",al={"为什么杀熊怪","灰谷熊怪威胁","污林威胁"}},{q="卡拉恩·阿玛卡与新兵阿玛卡尔有亲属关系吗？",a="卡拉恩·阿玛卡与新兵阿玛卡尔拥有相同的氏族名或姓氏，但两人的确切亲属关系尚未得到证实。",al={"阿玛卡家族","新兵阿玛卡尔亲属","卡拉恩家族"}},{q="卡拉恩会直接与暗夜精灵交战吗？",a="卡拉恩·阿玛卡在佐拉姆加的职责主要是保卫领地，应对污林熊怪等荒野中的威胁。针对暗夜精灵的直接军事行动由其他部落指挥官负责。",al={"卡拉恩对抗暗夜精灵","卡拉恩联盟"}}},fp="14,98,25.319.0,25.330.0,22.150.0,32.107.0,37.116.0,41.165.0,46.124.0,43.208.0"}
P.entries["npc:kargal-battlescar"] = {n="卡加尔·战痕",s="卡加尔·战痕在前沿哨所守卫着贫瘠之地的东部边境。他监视着从杜隆塔尔通往这里的渡口，考察前来的新兵，并派遣有能力的战士向西进发，加强部落的防御。",h="卡加尔·战痕在前沿哨所守卫着贫瘠之地的东部边境。他监视着从杜隆塔尔通往这里的渡口，考察前来的新兵，并派遣有能力的战士向西进发，加强部落的防御。",kw={"贫瘠之地","战痕","征召","十字路口","杜隆塔尔","前沿哨所","卡加尔"},ang={["class:Warrior"]="身为战士，你能从卡加尔身上的战斗伤痕看出他身经百战的阅历。他展现出部落边境前线战士应有的坚韧。",["faction:Horde"]="作为刚离开杜隆塔尔的部落冒险者，你在卡利姆多更广泛的纷争边缘遇见了卡加尔·战痕。他为贫瘠之地的战事招募新兵。"},sec={{t="边境哨兵",b="卡加尔·战痕在前沿哨所监视着通往贫瘠之地的道路。旅人和初出茅庐的冒险者告别试炼谷，跨过怒水河上的桥梁。贫瘠之地是一片危险、争端不断的土地，凶猛的野兽、半人马劫掠者和野猪人部族都威胁着边境。卡加尔检查过往行人，为部落招募志愿参战的新兵。他派他们继续前往十字路口，协助当地指挥官稳固边境。"}},faq={{q="卡加尔·战痕是谁？",a="卡加尔·战痕统领前沿哨所，守卫着从杜隆塔尔进入贫瘠之地的东部道路。",al={"卡加尔·战痕","卡加尔","卡加尔是谁"}},{q="前沿哨所有什么作用？",a="前沿哨所负责对杜隆塔尔边境附近和怒水河沿岸的威胁发出警报，并协助保卫贫瘠之地。",al={"前沿哨所的作用","为何设立前沿哨所","这个哨所是什么"}},{q="卡加尔派新兵去哪里？",a="卡加尔指引新兵沿大路向西前往十字路口，那里是贫瘠之地的军事枢纽。",al={"卡加尔任务目的地","见过卡加尔后去哪里","卡加尔派人去哪里"}}},fp="17,206,22.484.0,25.104.0,42.119.0,36.100.0"}
P.entries["npc:karos-razok"] = {n="卡洛斯·拉佐克",s="在银松森林的瑟伯切尔，卡洛斯·拉佐克让被遗忘者的蝙蝠栖所时刻准备就绪。",h="在银松森林的瑟伯切尔，卡洛斯·拉佐克让被遗忘者的蝙蝠栖所时刻准备就绪。",kw={"蝙蝠饲养员","飞行管理员","卡洛斯·拉佐克","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="作为一名向南前往希尔斯布莱德丘陵的部落旅人，你可以将卡洛斯·拉佐克的蝙蝠栖所作为洛丹伦西部边缘的一处中转站。",["race:Undead"]="作为一名Undead，你可以利用卡洛斯·拉佐克的蝙蝠栖所，从银松森林前线返回希尔瓦娜斯的都城幽暗城。"},sec={{t="瑟伯切尔的双翼看守者",b="卡洛斯·拉佐克在瑟伯切尔墓穴上方的木制平台上照料着骸骨蝙蝠。月怒狼人、叛离的达拉然法师和安伯米尔的人类残部，让穿过银松森林的北方道路危机四伏。拉佐克让信使、新兵和重要补给得以从闹鬼的林冠上方通行，将这座边境哨站与提瑞斯法林地的都城连接起来。"}},faq={{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克在银松森林的瑟伯切尔照料被遗忘者的蝙蝠栖所。部落旅人和信使乘坐训练有素的吸血蝙蝠，穿行于洛丹伦。",al={"卡洛斯·拉佐克的职责","瑟伯切尔的飞行管理员是谁","瑟伯切尔蝙蝠饲养员"}},{q="卡洛斯·拉佐克能将旅人送往何处？",a="卡洛斯·拉佐克将旅人从瑟伯切尔送往提瑞斯法林地的幽暗城，以及希尔斯布莱德丘陵的塔伦米尔。他的航线将这座哨站与洛丹伦北部连接起来。",al={"瑟伯切尔飞行路线","瑟伯切尔的蝙蝠飞往哪里","从瑟伯切尔出发的航线"}},{q="卡洛斯照料什么生物？",a="卡洛斯·拉佐克照料着体形庞大的骸骨飞行蝙蝠。这些亡灵飞兽强健而不知疲倦，被遗忘者青睐它们，是因为它们能在洛丹伦遭受瘟疫侵蚀的天空中安静而持久地飞行。",al={"拉佐克有哪些坐骑","被遗忘者飞行兽","瑟伯切尔的飞行坐骑是什么"}},{q="飞行管理员为何对瑟伯切尔如此重要？",a="从焚木村的狼人诅咒到安伯米尔的人类巫师，敌对势力让银松森林的道路危机四伏。卡洛斯·拉佐克为被遗忘者提供了一条空中航线，让他们能够向前线基地运送补给，无需冒着在大路上遭到伏击的风险。",al={"瑟伯切尔为何需要蝙蝠管理员","瑟伯切尔的交通重要性"}}},fp="11,86,31.385.0,19.159.0,37.185.0,33.172.0,50.229.0"}
P.entries["npc:katie-hunter"] = {n="凯蒂·亨特",s="在东谷伐木场的马厩里，凯蒂·亨特为暴风城和深受信赖的联盟勇士照料马匹。她与兰达尔·亨特一起，为行走在王国道路上的旅人和士兵提供坐骑。",h="在东谷伐木场的马厩里，凯蒂·亨特为暴风城和深受信赖的联盟勇士照料马匹。她与兰达尔·亨特一起，为行走在王国道路上的旅人和士兵提供坐骑。",kw={"东谷","艾尔文森林","马匹商人","凯蒂·亨特","伐木场","坐骑","马厩","暴风城"},ang={["faction:Alliance"]="身为同盟种族的一员，你可以通过赢得暴风城宫廷的崇高声望与尊重，获得骑着凯蒂珍视的骏马奔赴战场的资格。",["race:Human"]="身为人类，只要掌握了基础骑术，你就可以向凯蒂购买一匹经典的暴风城战马。"},sec={{t="东谷的马厩",b="在艾尔文森林东部，凯蒂·亨特照料着东谷伐木场的马匹。伐木工为暴风城的重建砍伐木材时，她则为骑手培育可靠的杂色马、母马和迅捷的骏马。她的马匹载着人们，穿行于王国的道路和艾泽拉斯南部的险途。"}},faq={{q="凯蒂·亨特是谁？",a="凯蒂·亨特在艾尔文森林的东谷伐木场马厩，为暴风城王国繁育并出售马匹。",al={"凯蒂·亨特 艾尔文","凯蒂·亨特是谁","凯蒂·亨特 马匹商人"}},{q="在哪里能找到凯蒂·亨特？",a="凯蒂·亨特照看着东谷伐木场北部的围栏和马厩。她在艾尔文森林东部工作，附近就是骑术训练师兰达尔·亨特。",al={"凯蒂·亨特位置","凯蒂·亨特在哪里","寻找凯蒂·亨特"}},{q="非人类也能向她购买马匹吗？",a="可以。非人类买家需要在暴风城王国达到崇拜声望。人类冒险者无需特殊声望即可购买她的马匹。",al={"矮人购买马匹","暗夜精灵 马匹坐骑","暴风城声望坐骑"}},{q="她出售哪些马匹？",a="凯蒂·亨特出售普通骑乘马匹，包括杂色马、棕马和栗色马。她也出售披甲的迅捷骏马，例如迅捷褐色马、迅捷棕马和迅捷白马。",al={"凯蒂出售哪些坐骑","凯蒂·亨特 马匹种类"}}},fx={d7735dfa={q="凯蒂·亨特效忠哪一方？",a="凯蒂·亨特是暴风城王国的忠诚子民，也是联盟的一员。她在东谷伐木场经营马厩，直接为暴风城的居民服务，为那些已向王室证明忠诚的旅人和勇士提供可靠的坐骑。",al={"凯蒂·亨特 阵营","凯蒂·亨特是否属于联盟","凯蒂·亨特为谁效力"}},d5257f59={q="凯蒂·亨特想要什么？",a="凯蒂·亨特专心照料和出售东谷闻名遐迩的马匹。她希望为可靠的冒险者提供出色的坐骑，确保只有暴风城信赖的盟友才能买到她珍视的良马，帮助他们在王国各地旅行。",al={"凯蒂·亨特想要什么","凯蒂·亨特 职责","凯蒂·亨特 目标"}},["5cab52df"]={q="凯蒂·亨特为什么在东谷伐木场？",a="凯蒂·亨特定居在艾尔文森林东部的东谷伐木场，经营营地的马厩。她与兰达尔·亨特一起，利用营地远离暴风城喧嚣的开阔牧场，负责骑乘马匹的繁育和照料。",al={"凯蒂·亨特为什么在东谷","凯蒂·亨特为什么在这里","凯蒂·亨特在艾尔文做什么"}},["85933b18"]={q="凯蒂·亨特与谁有关联？",a="凯蒂·亨特与兰达尔·亨特密切合作，后者也负责管理东谷伐木场的马厩。他们共同经营营地的马匹生意，是暴风城盟友获取马匹的主要来源。",al={"凯蒂·亨特 关联","凯蒂·亨特与谁有关","凯蒂·亨特 兰达尔·亨特"}}},fp="12,196,19.309.0,20.120.0,30.166.0,35.137.0,26.197.0"}
P.entries["npc:katrana-prestor"] = {n="女伯爵卡特拉娜·普瑞斯托",s="女伯爵卡特拉娜·普瑞斯托是暴风城的一位贵族，也是宫廷中最有影响力的人物之一。瓦里安国王失踪后，她以受信任的顾问身份，在暴风要塞辅佐年幼的国王安度因与伯瓦尔·弗塔根公爵。",h="女伯爵卡特拉娜·普瑞斯托是暴风城的一位贵族，也是宫廷中最有影响力的人物之一。瓦里安国王失踪后，她以受信任的顾问身份，在暴风要塞辅佐年幼的国王安度因与伯瓦尔·弗塔根公爵。",kw={"卡特拉娜","普瑞斯托","卡特拉娜·普瑞斯托","普瑞斯托女士","顾问","暴风要塞","宫廷"},sec={{t="宫廷之声",b="普瑞斯托女士几年前来到宫廷，很快便成为最受信任的人物之一。暴风城的贵族争相博取她的青睐，而在伯瓦尔·弗塔根公爵摄政期间，许多以年幼国王之名作出的决策都受到她的建议左右。前来暴风要塞请求派兵或援助的人，往往发现她的意见与摄政者的意见同样举足轻重。"}},faq={{q="女伯爵卡特拉娜·普瑞斯托是谁？",a="女伯爵卡特拉娜·普瑞斯托是暴风城的一位贵族，也是宫廷中备受信任的顾问。瓦里安国王失踪后，她在暴风要塞辅佐年幼的国王安度因与伯瓦尔·弗塔根公爵，在贵族之中有着举足轻重的话语权。",al={"卡特拉娜·普瑞斯托是谁","普瑞斯托女士是谁","卡特拉娜·普瑞斯托背景故事"}},{q="她为何担任国王的顾问？",a="瓦里安国王失踪后，他年幼的儿子安度因登上王位，由伯瓦尔·弗塔根公爵摄政。普瑞斯托女士在他们身旁担任顾问。宫廷的许多决策都会征询她的意见，包括暴风城如何回应偏远领地的求援。",al={"普瑞斯托为何在宫廷","卡特拉娜做什么"}},{q="在哪里可以找到普瑞斯托女士？",a="她通常在暴风要塞的王座厅里，站在伯瓦尔·弗塔根公爵与年幼的安度因国王附近。",al={"卡特拉娜·普瑞斯托在哪里","卡特拉娜·普瑞斯托位置"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="凯玛德·考伯宾奇",s="凯玛德·考伯宾奇在奥格瑞玛出售烟林牧场的冬幕节商品。他在力量谷做生意，旅人可以在那里找到节庆商品，也可以帮忙解决节日期间的麻烦。",h="凯玛德·考伯宾奇在奥格瑞玛出售烟林牧场的冬幕节商品。他在力量谷做生意，旅人可以在那里找到节庆商品，也可以帮忙解决节日期间的麻烦。",kw={"考伯宾奇","地精","凯玛德","梅森","奥格瑞玛","烟林牧场","力量谷","冬幕节"},ang={["faction:Horde"]="凯玛德为部落将冬幕节贸易带到奥格瑞玛，让地精的商业活动融入传统的冬季庆典。",["profession:Cooking"]="身为厨师，你可以通过凯玛德及其烟林牧场的同事，找到制作传统节日点心所需的时令食谱和特色食材。"},sec={{t="地精的冬幕节",b="每逢冬幕节，凯玛德·考伯宾奇都会将烟林牧场带到力量谷。冬天爷爷在附近接待访客，凯玛德则出售精美的点心、节日包装纸和其他节庆商品。对地精来说，盛大的节庆少了热闹的金钱交易，就算不上圆满。"},{t="节日的麻烦",b="凯玛德也负责处理节日期间威胁烟林牧场的麻烦。节日糖果不翼而飞，驯鹿梅森也失踪了。凯玛德召集部落冒险者解决这些问题，让冬幕节顺利进行。"}},faq={{q="凯玛德·考伯宾奇是谁？",a="凯玛德·考伯宾奇是烟林牧场的一名地精商人。冬幕节期间，他在奥格瑞玛的力量谷做生意，出售精美的时令商品，并请过路人帮忙解决节日的麻烦。",al={"凯玛德是谁","凯玛德·考伯宾奇的故事","凯玛德做什么"}},{q="烟林牧场是什么？",a="烟林牧场是一个商贩联合组织，为艾泽拉斯各地的冬幕节供应食品、点心和时令商品。它同时为部落和联盟供货，从中赚取可观的利润。",al={"烟林牧场是什么","他为谁工作","烟林牧场的故事"}},{q="在哪里可以找到凯玛德·考伯宾奇？",a="凯玛德·考伯宾奇位于奥格瑞玛的力量谷，就在中央的节日布景附近，冬天爷爷在冬幕节期间便坐在那里。",al={"凯玛德的位置","凯玛德·考伯宾奇在哪里","他在奥格瑞玛哪里"}},{q="他为什么在节日期间向冒险者求助？",a="烟林牧场在冬幕节期间遇到了麻烦，包括节日糖果被盗，以及它珍视的驯鹿梅森遭到绑架。凯玛德雇用自愿相助的冒险者，找回失窃的货物和梅森，保住节日期间的利润。",al={"凯玛德的任务","冬幕节点心任务","梅森部落任务"}}},fp="19,176,22.305.0,21.250.0,27.196.0,27.202.0,37.159.0,57.247.0"}
P.entries["npc:keeper-albagorm"] = {n="守护者奥巴格姆",s="在石爪峰，守护者奥巴格姆注视着燃烧的焦炭谷，寻求援手，治愈荒野。",h="在石爪峰，守护者奥巴格姆注视着燃烧的焦炭谷，寻求援手，治愈荒野。",kw={"塞纳留斯","焦炭谷","守护者奥巴格姆","丛林守护者","石爪山","石爪峰"},ang={["class:Druid"]="身为德鲁伊，你与奥巴格姆同属塞纳里奥一脉，而他净化焦炭谷的努力也牵动着这份纽带。",["faction:Alliance"]="身为联盟的一员，当你途经石爪峰的暗夜精灵庇护所时，可以从奥巴格姆那里获得庇护与指引。"},sec={{t="峰顶的守护者",b="守护者奥巴格姆守卫着石爪峰上的暗夜精灵庇护所。如同其他塞纳留斯之子，他能感受到自然世界的痛楚。山峰以南，焦炭谷遭到一群贪婪的实业家麾下的机械化大军焚毁。如今，血怒鹰身人盘踞在废墟中，阻碍草木重新生长。奥巴格姆在庇护所中致力于阻止腐化，让受创的森林恢复平衡。"}},faq={{q="守护者奥巴格姆是谁？",a="守护者奥巴格姆是一位丛林守护者，也是塞纳留斯的半神子嗣之一，驻守在石爪山脉的石爪峰。他与暗夜精灵以及卡利姆多的自然守护者结盟。",al={"守护者奥巴格姆","奥巴格姆 是谁","奥巴格姆 石爪山"}},{q="在哪里可以找到守护者奥巴格姆？",a="你可以在石爪峰找到守护者奥巴格姆，那是位于石爪山脉西北部高处、隶属联盟的德鲁伊庇护所。",al={"守护者奥巴格姆位置","奥巴格姆 在哪里","奥巴格姆 坐标"}},{q="守护者奥巴格姆需要什么帮助？",a="奥巴格姆希望有人帮助他治愈焦炭谷。他派遣旅者进入那片灰烬弥漫的盆地，净化枯萎的大地，驱逐阻碍自然复苏的血怒鹰身人。",al={"守护者奥巴格姆任务","奥巴格姆 想要什么","收复焦炭谷"}}},fp="15,93,22.386.0,23.210.0,33.130.0,41.186.0"}
P.entries["npc:keeper-bel-dugur"] = {n="看守者贝尔杜加",s="在幽暗城，看守者贝尔杜加委派探险者为他的族人寻回黑暗典籍与魔法器物。这位博学的被遗忘者在炼金房深处工作。",h="在幽暗城，看守者贝尔杜加委派探险者为他的族人寻回黑暗典籍与魔法器物。这位博学的被遗忘者在炼金房深处工作。",kw={"炼金房","贝尔杜加","看守者贝尔杜加","暗影之牙","乌尔之书","幽暗城"},ang={["class:Warlock"]="身为术士，你时常会接触到贝尔杜加的委托。他的兴趣涉及危险的魔典、异位面召唤与黑暗秘术。",["race:Undead"]="身为亡灵，你或许会将贝尔杜加视为又一位博学的被遗忘者，寻求禁忌知识以巩固你们的王国。他真正的野心所效力的事业，超出了女妖之王为求生存而奋斗的目标。"},sec={{t="黑暗遗物收藏者",b="在炼金房的大缸与研究人员之间，看守者贝尔杜加派遣冒险者前往艾泽拉斯各地，寻回危险的奥术与秘术遗物。乌尔之书是一部论述异次元生物的传奇著作，被锁藏在影牙城堡内，令他深感兴趣。幽暗城中有许多人寻求魔法知识，试图治愈亡灵状态，或将其化作武器，而贝尔杜加精心挑选的藏品似乎旨在揭开古老的禁忌力量。"},{t="隐秘的效忠",b="看守者贝尔杜加身为幽暗城研究者，举止平静，却掩藏着他对末日邪教暮光之锤的效忠。他交付的任务暗中推进着这个邪教的隐秘目标，在皇家药剂师学会和希尔瓦娜斯毫无察觉的目光下，搜寻有关召唤与虚空魔法的奠基魔典。"}},faq={{q="在哪里可以找到看守者贝尔杜加？",a="看守者贝尔杜加在炼金房工作，那里是幽暗城下层环区南部的炼金区域。",al={"看守者贝尔杜加位置","贝尔杜加 在哪里","贝尔杜加 地图"}},{q="贝尔杜加为什么想要乌尔之书？",a="乌尔之书收录了达拉然法师 Ur 对其他次元与野性狼人的奠基性研究。贝尔杜加寻求其中禁忌的召唤原理，为他真正主人的黑暗阴谋效力。",al={"为什么要乌尔之书","贝尔杜加 用乌尔之书做什么"}},{q="看守者贝尔杜加效忠于希尔瓦娜斯吗？",a="看守者贝尔杜加表面上以档案管理员和研究者的身份为被遗忘者效力，但他调查中的一些线索暗示，他效忠的或许另有其人。",al={"贝尔杜加 邪恶吗","贝尔杜加 阵营","贝尔杜加 为谁效力"}},{q="他还会交给冒险者哪些任务？",a="除了影牙城堡中的乌尔之书，贝尔杜加还派遣旅者搜寻被遗忘的学识与禁忌典籍，其中包括与古老仪式和禁忌知识有关的黑暗论著。",al={"贝尔杜加 任务","看守者贝尔杜加任务"}}},fp="16,177,26.458.0,16.322.2,34.107.0,39.189.1,43.147.2,42.187.0"}
P.entries["npc:keeper-bel-varil"] = {n="看守者贝瓦里尔",s="在塔伦米尔，看守者贝瓦里尔为被遗忘者研究魔法与炼金术。他与沃丁·伍德的研究吸引了部落冒险者，前往希尔斯布莱德丘陵各处寻找遗物和束缚材料。",h="在塔伦米尔，看守者贝瓦里尔为被遗忘者研究魔法与炼金术。他与沃丁·伍德的研究吸引了部落冒险者，前往希尔斯布莱德丘陵各处寻找遗物和束缚材料。",kw={"贝瓦里尔","禁锢护腕","希尔斯布莱德丘陵","看守者贝瓦里尔","石头印记","塔伦米尔","沃丹·虚空之眼"},ang={["faction:Horde"]="作为身在希尔斯布莱德丘陵的部落勇士，你可以制服元素威胁，寻回束缚符咒，协助贝瓦里尔。他会为这些工作提供实用的奖励。",["race:Undead"]="作为被遗忘者的一员，你与贝瓦里尔一样，追求对奥术的掌控，也懂得善用资源。他仔细研究当地的遗物，力求为你的族人在洛丹伦赢得优势。"},sec={{t="塔伦米尔的研究",b="看守者贝瓦里尔在饱受围攻的塔伦米尔支持被遗忘者的魔法与炼金术研究。皇家药剂师和士兵们将注意力集中在沿路而下的南海镇联盟驻军身上。贝瓦里尔则着手研究实用的法术，派遣旅者从附近的元素生物和魔法威胁手中夺取石头护符和束缚护腕。"}},faq={{q="看守者贝瓦里尔是谁？",a="看守者贝瓦里尔在希尔斯布莱德丘陵的塔伦米尔研究魔法。他与研究同僚沃迪恩·伍德合作，检视在这片争夺中的土地各处发现的魔法器物与材料。",al={"看守者贝瓦里尔","贝瓦里尔是谁","贝瓦里尔 塔伦米尔"}},{q="在哪里可以找到看守者贝瓦里尔？",a="看守者贝瓦里尔就在塔伦米尔，这座被遗忘者的定居点位于希尔斯布莱德丘陵北部。",al={"贝瓦里尔位置","看守者贝瓦里尔在哪里","寻找看守者贝瓦里尔"}},{q="看守者贝瓦里尔提供哪些任务？",a="看守者贝瓦里尔派遣部落冒险者收集魔法残留物，包括石雕和禁锢护腕。他研究这些物品，以理解并操纵元素之力。",al={"贝瓦里尔任务","看守者贝瓦里尔任务"}}},fp="16,166,20.342.0,24.196.0,34.92.0,39.179.0"}
P.entries["npc:keldran"] = {n="科尔丹",s="在奥格瑞玛的精神谷北面，科尔丹正努力为与联盟缔结和平扫清道路。他指挥着针对恶魔残余势力的秘密突袭，希望借此表明如今的部落已经摒弃了燃烧军团。",h="在奥格瑞玛的精神谷北面，科尔丹正努力为与联盟缔结和平扫清道路。他指挥着针对恶魔残余势力的秘密突袭，希望借此表明如今的部落已经摒弃了燃烧军团。",kw={"与联盟的关系","火刃氏族","凄凉之地","科尔丹","玛乌林·碎骨","奥格瑞玛","塔卡塔·钢刃","精神谷"},ang={["class:Warlock"]="科尔丹针对火刃氏族展开的秘密战争，表明部落的领导者多么渴望摆脱失控的恶魔腐化。",["faction:Horde"]="科尔丹代表了部落中目光长远的一部分人，他们明白，要在卡利姆多实现持久和平，就必须洗去与恶魔为伍的恶名。"},sec={{t="外交征途",b="科尔丹在奥格瑞玛的红岩台地上开展工作，而萨尔则在智慧谷处理政务。联盟依然认为所有兽人都是恶魔主人的嗜血傀儡，这种恶名源于最初的几场战争。科尔丹相信萨尔已厌倦无休止的冲突，但只要崇拜恶魔的邪教仍在卡利姆多活动，和谈就无从开始。没有大酋长的正式批准，他便自行采取了行动。他派遣信任的密探前去应对远方的威胁，希望洗去恶魔留下的污点，为外交铺平道路。"},{t="凄凉之地的战事",b="科尔丹已派塔卡塔·钢刃和玛乌林·碎骨前往凄凉之地，领导清剿恶魔的行动。他们的主要目标是火刃氏族邪教。科尔丹希望根除这些邪教徒，并将证据带回奥格瑞玛，向联盟表明，新的部落正与人类和暗夜精灵并肩对抗燃烧军团。"}},faq={{q="科尔丹是谁？",a="科尔丹在奥格瑞玛的精神谷北面开展工作，组织力量对抗恶魔的影响，为与联盟展开外交铺平道路。",al={"科尔丹是谁","科尔丹背景故事","科尔丹非玩家角色"}},{q="科尔丹为何关心与联盟的关系？",a="科尔丹相信萨尔正逐渐厌倦与联盟之间持续不断的战争。只要联盟仍认为部落与燃烧军团结盟，和谈就无从开始。",al={"为何重视与联盟的关系","科尔丹的动机","他为何渴望和平"}},{q="科尔丹是在执行萨尔的正式命令吗？",a="不是。科尔丹并未得到大酋长萨尔的正式授权，他自行采取行动，希望洗清部落的恶名，为和平铺平道路。",al={"萨尔派遣了科尔丹吗","萨尔命令科尔丹","科尔丹获得授权了吗"}},{q="科尔丹在凄凉之地做什么？",a="科尔丹派塔卡塔·钢刃和玛乌林·碎骨前往凄凉之地对抗恶魔势力，尤其着重于剿灭火刃氏族邪教徒。",al={"凄凉之地行动","为何选择凄凉之地","科尔丹火刃氏族"}}},fp="7,226,20.541.0,19.355.1,15.147.0,56.176.0,49.135.0,34.141.0"}
P.entries["npc:kelm-hargunth"] = {n="凯尔姆·哈古斯",s="在莫尔杉营地，凯尔姆·哈古斯负责保障战歌氏族的补给。他为在战歌峡谷与暗夜精灵作战的部落勇士提供补给包和物资。",h="在莫尔杉营地，凯尔姆·哈古斯负责保障战歌氏族的补给。他为在战歌峡谷与暗夜精灵作战的部落勇士提供补给包和物资。",kw={"贫瘠之地","补给包","凯尔姆·哈古斯","莫尔杉营地","玩家对战 商人","军需官","战歌峡谷","战歌氏族"},ang={["class:Warrior"]="身为战士，你依靠哈古斯提供的坚固板甲护腿、沉重刀剑和战斗口粮，守住对抗联盟的防线。",["faction:Horde"]="身为部落士兵，你可以在战歌峡谷拿起武器对抗暗夜精灵，而凯尔姆·哈古斯会为你提供作战所需的装备。",["race:Orc"]="身为兽人，你看到哈古斯为战歌氏族供应武器和口粮，让葛罗·地狱吼在灰谷留下的事业得以延续。"},sec={{t="莫尔杉的军需官",b="在莫尔杉营地，凯尔姆·哈古斯为战歌氏族管理补给。营地位于贫瘠之地的北部边缘，紧邻灰谷边界。斥候和掠袭者在营地围栅外展开小规模交战，而 凯尔姆 则确保武器、护甲和口粮送到战士手中。战歌氏族与银翼要塞交锋，源源不断的物资补给与战场上的怒火同样重要。"},{t="补给前线",b="凯尔姆 为在战歌峡谷证明过自己的勇士提供专用补给。他的库存中有装着战地绷带和耐储口粮的补给包，还有带着战歌氏族鲜红徽记的武器装备。这些补给发往北方森林，供参与部落战事的战士使用。"}},faq={{q="凯尔姆·哈古斯是谁？",a="凯尔姆·哈古斯是战歌氏族的一名兽人补给官。他在贫瘠之地北部的莫尔杉营地，为在战歌峡谷作战的部落士兵分发武器、护甲和物资。",al={"凯尔姆·哈古斯","凯尔姆 是谁","莫尔杉 商人","战歌 商人"}},{q="凯尔姆·哈古斯在哪里？",a="凯尔姆·哈古斯驻守在莫尔杉营地，位于贫瘠之地最北端，紧邻通往灰谷的壁垒分界处。",al={"凯尔姆 位置","凯尔姆·哈古斯在哪里","莫尔杉 补给官位置"}},{q="凯尔姆·哈古斯为哪个阵营效力？",a="凯尔姆·哈古斯为战歌氏族效力。这支部落先锋军在灰谷南部与暗夜精灵交战，争夺木材和领土。",al={"凯尔姆 阵营","战歌氏族军需官","凯尔姆 为谁效力"}},{q="凯尔姆 提供什么补给包？",a="凯尔姆·哈古斯为前线战士提供 初级、标准 和 高级补给包。其中装有战场杂物、绷带和口粮，供峡谷中的部落战士使用。",al={"侦查骑兵 补给包","凯尔姆 补给包","战歌 补给包"}},{q="莫尔杉营地为何对战歌如此重要？",a="莫尔杉营地是贫瘠之地与灰谷之间一处设有防御工事的集结地和关卡。战歌氏族借此将补给、援军和采伐的木材安全地送入部落领地。",al={"为何设立莫尔杉营地","莫尔杉 用途","营地背景故事"}},{q="凯尔姆·哈古斯提供哪些装备？",a="凯尔姆·哈古斯为久经考验的战士提供战歌战袍、斥候之刃和军团士兵之剑等专用武器、量身配备的护甲套装、戒指，以及用于近身交战的战场药剂。",al={"凯尔姆 玩家对战 装备","战歌 奖励","凯尔姆 出售什么"}}},fp="13,170,25.362.0,19.315.0,21.198.0,31.153.0,38.138.0,39.176.0,54.205.0,45.219.0"}
P.entries["npc:kerlonian-evershade"] = {n="克罗尼亚·恒影",s="在黑海岸的古树之林，克罗尼亚·恒影从翡翠梦境中的漫长沉睡中醒来。这位暗夜精灵利爪德鲁伊需要帮助，才能穿过危机四伏的荒野，抵达迈斯特拉岗哨。",h="在黑海岸的古树之林，克罗尼亚·恒影从翡翠梦境中的漫长沉睡中醒来。这位暗夜精灵利爪德鲁伊需要帮助，才能穿过危机四伏的荒野，抵达迈斯特拉岗哨。",kw={"黑海岸","利爪德鲁伊","翡翠梦境","恒影","古树之林","克罗尼亚","昏昏欲睡"},ang={["class:Druid"]="身为德鲁伊，你知道与翡翠梦境深入交流会给塞纳里奥议会的门徒带来怎样的负担。",["race:NightElf"]="身为暗夜精灵，你帮助保护着族中的一位古老守护者。他刚刚归来，而这个世界自第三次大战以来已发生了变化。"},sec={{t="在黑海岸苏醒",b="克罗尼亚·恒影是利爪德鲁伊的一员，追随巨熊图腾。数百年来，这些德鲁伊沉睡在兽穴中，与翡翠梦境交流。他们在第三次大战期间被唤醒。如今，克罗尼亚在古树之林的古树下休憩，仍未摆脱漫长沉睡带来的超自然困倦。他必须穿过黑海岸危机四伏的森林，抵达灰谷边境的迈斯特拉岗哨。"},{t="危机四伏的旅途",b="从古树之林出发的道路危机重重。黑木熊怪在暮光谷游荡，暗滩教派教徒则潜伏在通往灰谷的道路沿线。沉睡让克罗尼亚变得虚弱，突如其来的疲惫仍困扰着他。他一路南下，与暗夜精灵同胞会合，途中需要好心的联盟旅人保护。"}},faq={{q="克罗尼亚·恒影是谁？",a="克罗尼亚·恒影是黑海岸古树之林附近的一位暗夜精灵利爪德鲁伊。他刚从翡翠梦境中醒来，需要帮助才能安全穿过森林。",al={"克罗尼亚是谁","克罗尼亚·恒影的故事","古树之林的德鲁伊"}},{q="克罗尼亚为什么会在行走时睡着？",a="和许多在兽穴中沉睡了数百年的猛禽德鲁伊一样，克罗尼亚仍受翡翠梦境残留的昏沉状态困扰。他的身心尚未完全适应苏醒后的状态，突如其来的睡意常常令他无法抵挡。",al={"克罗尼亚为什么沉睡","昏昏欲睡任务德鲁伊","克罗尼亚困倦"}},{q="他要去哪里？",a="克罗尼亚希望安全南下，前往迈斯特拉岗哨。那是位于黑海岸与灰谷交界处的一座暗夜精灵岗哨，他可以在那里安心休养。",al={"克罗尼亚的目的地","克罗尼亚去哪里","古树之林护送目的地"}},{q="什么是利爪德鲁伊？",a="猛禽德鲁伊是能够化身巨熊的暗夜精灵德鲁伊。他们运用力量、坚韧与野性之力，历来守护着兽穴和暗夜精灵的领地，也会在翡翠梦境中度过漫长的沉睡岁月。",al={"什么是利爪德鲁伊","利爪德鲁伊的故事"}}},fp="19,220,22.388.0,21.356.0,27.179.0,45.237.0,25.152.0,28.232.0"}
P.entries["npc:kernobee"] = {n="克努比",s="在诺莫瑞根，克努比被困在废墟之中。这位地精工程师发现黑铁矮人正在操作巨型超级钻探机，随后便被抓住、打昏，丢在宿舍区的穴居人群中。",h="在诺莫瑞根，克努比被困在废墟之中。这位地精工程师发现黑铁矮人正在操作巨型超级钻探机，随后便被抓住、打昏，丢在宿舍区的穴居人群中。",kw={"黑铁","宿舍","诺莫瑞根","克努比","棘齿城","超级钻探机","廷克维斯"},ang={["profession:Engineering"]="身为工程师，你知道，在争夺竞争对手设计图的情况下，探索黑铁钻探机这类实验性地下机械有多危险。",["race:Gnome"]="对于那些为夺回家园而战的侏儒来说，克努比的发现表明，黑铁矮人曾在暗中助长了这场灾难。"},sec={{t="致命的发现",b="克努比在诺莫瑞根做生意或搜寻废品时，得知黑铁矮人曾协助建造并操作那台在城下挖掘的巨型超级钻探机。他知道这一发现会招来危险，于是试图逃往棘齿城。他打算在那里警告自己的同伴廷克维斯。黑铁矮人在他逃脱之前抓住了他。"},{t="丢给穴居人",b="抓住克努比的人把他打得不省人事，却留下了他的性命。他们把他扔进宿舍走廊旁的一间小屋，就在Clean Zone对面。他的周围到处都是凶残的穴居人和辐射。他需要有人帮他苏醒，抵达安全地带，逃出废墟。"}},faq={{q="克努比是谁？",a="克努比是一名地精特工，被人发现时昏迷在诺莫瑞根的宿舍区。他与棘齿城的廷克维斯关系密切，在进入废墟后被袭击者抓住。",al={"这个地精是谁","克努比的故事","关于克努比"}},{q="克努比为什么被囚禁在诺莫瑞根？",a="克努比发现，黑铁氏族正在协助建造诺莫瑞根内部的地下超级钻探机。黑铁矮人把他打昏，扔进宿舍等死，以掩盖他们的存在和破坏行动。",al={"他为什么在这里","黑铁矮人为什么抓他","为什么在宿舍"}},{q="克努比向谁汇报？",a="克努比向地精工程师廷克维斯汇报，后者身在棘齿城，那是远在海对岸、位于贫瘠之地的中立港口城镇。",al={"廷克维斯是谁","他要去哪里","与棘齿城的联系"}},{q="克努比在诺莫瑞根的什么位置？",a="克努比昏迷在宿舍下层西侧的一间小侧室里，正对着清洁区。",al={"克努比的位置","克努比在哪里","寻找克努比"}}},fx={["3c758521"]={q="克努比站在哪一边？",a="克努比隶属于热砂港，听命于中立港口棘齿城的廷克维斯。他为地精的生意奔走，并不效力于联盟或部落，而在揭露潜伏于诺莫瑞根的黑铁矮人的阴谋后，他便与他们彻底站到了对立面。",al={"克努比是联盟还是部落","克努比阵营","克努比为谁效力"}},b63dca8d={q="克努比想要什么？",a="克努比只想活着逃出诺莫瑞根。他发现黑铁矮人参与建造了那台庞大的超级钻探机后，急需逃出宿舍，离开这座遭受辐射的城市，好向棘齿城的廷克维斯报告自己的发现。",al={"克努比想做什么","克努比目标","为什么帮助克努比"}}},fp="8,221,18.332.0,19.247.0,16.180.0,42.235.0,28.113.0,40.135.0"}
P.entries["npc:keryn-sylvius"] = {n="科瑞恩·塞尔留斯",s="在闪金镇的Lion’s Pride Inn二楼，科瑞恩·塞尔留斯训练年轻的潜行者。在Reading Room里，她传授潜行与刀刃技艺，并悄悄引导有潜力的特工加入暴风城的情报机构。",h="在闪金镇的Lion’s Pride Inn二楼，科瑞恩·塞尔留斯训练年轻的潜行者。在Reading Room里，她传授潜行与刀刃技艺，并悄悄引导有潜力的特工加入暴风城的情报机构。",kw={"艾尔文森林","闪金镇","科瑞恩·塞尔留斯","狮王之傲旅店","潜行者训练师","si:7"},ang={["class:Rogue"]="身为潜行者，你可以在艾尔文森林向塞尔留斯学习。等你准备就绪，她便能指引你前往暴风城的SI:7总部。",["faction:Alliance"]="身为联盟的一员，你可以信赖塞尔留斯，她在闪金镇交叉路口上方的岗位上监视着艾尔文的主要道路。"},sec={{t="闪金镇的低调身影",b="科瑞恩·塞尔留斯常驻Lion’s Pride Inn楼上的Reading Room。楼下的公共休息室里挤满了旅人和镇上的卫兵。楼上，她倾听着道路上传来的源源不断的传闻。她指导在艾尔文森林学习技艺的潜行者。\n\n当有潜力的特工不再满足于小偷小摸和路边的勾当时，塞尔留斯便悄悄派他们前往暴风城。在那里，他们可以寻找SI:7。"}},faq={{q="在哪里可以找到科瑞恩·塞尔留斯？",a="科瑞恩·塞尔留斯就在闪金镇狮王之傲旅店二楼的小阅览室里。",al={"科瑞恩·塞尔留斯位置","科瑞恩在哪","闪金镇潜行者训练师位置"}},{q="她提供哪些服务？",a="科瑞恩·塞尔留斯训练潜行者，传授新技能，并重置天赋专精。她也会指引他们的成长。",al={"科瑞恩做什么","她能提供训练吗","科瑞恩·塞尔留斯职责"}},{q="她与SI:7有什么联系？",a="当特工证明了自己的能力，塞尔留斯便指引他们前往旧城区，寻找马迪亚斯·肖尔和SI:7。暴风城的秘密情报网络就设在那里。",al={"科瑞恩 si7","她是si:7成员吗","她为暴风城效力吗"}}},fx={["74741391"]={q="科瑞恩·塞尔留斯是谁？",a="科瑞恩·塞尔留斯是一位潜行者训练师，住在闪金镇狮王之傲旅店的楼上。她隐居在安静的阅览室中，一边观察艾尔文森林里来来往往的人，一边向联盟旗下有潜力的潜行者传授潜行、开锁和诡计的精妙技艺。",al={"科瑞恩是谁","科瑞恩·塞尔留斯背景故事","塞尔留斯是谁"}},["017a68dc"]={q="科瑞恩·塞尔留斯站在哪一边？",a="科瑞恩坚定地效忠于暴风城王国和联盟。她以自己的技艺为王国效力，悄然将有才能的密探引向暴风城的秘密情报网络，让他们协助王国应对内乱与外敌。",al={"科瑞恩·塞尔留斯联盟还是部落","科瑞恩·塞尔留斯效忠对象","科瑞恩·塞尔留斯为谁效力"}},["90e34396"]={q="科瑞恩·塞尔留斯想要什么？",a="科瑞恩希望在艾尔文的宁静腹地发掘并教导尚未受训的人才，赶在他们触犯法律或滥用致命技艺之前。一旦学徒证明了自己的能力，她便会指引他们前往旧城区的SI:7总部，让他们的才能用于有组织的效力。",al={"科瑞恩想要什么","科瑞恩·塞尔留斯目标","为什么训练潜行者"}},f8e496c4={q="科瑞恩·塞尔留斯为什么在闪金镇？",a="狮王之傲旅店是艾尔文森林中人来人往的交通枢纽，非常适合悄然物色那些离开北郡山谷后刚刚起步的潜行者。她驻留楼上，便能在隐蔽之处指导初学者，而不会引来楼下当地卫兵或镇民的过多注意。",al={"科瑞恩为什么在狮王之傲旅店","科瑞恩·塞尔留斯为什么在闪金镇","科瑞恩为什么在闪金镇"}}},fp="13,230,29.398.0,31.104.0,29.121.0,38.162.0"}
P.entries["npc:khelden-bremen"] = {n="凯尔登·布雷门",s="在北郡修道院的楼上，凯尔登·布雷门教导人类法师最初的法术。他为初学者打下基础，让他们能以奥术为暴风城效力。",h="在北郡修道院的楼上，凯尔登·布雷门教导人类法师最初的法术。他为初学者打下基础，让他们能以奥术为暴风城效力。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师训练师","北郡修道院"},ang={["class:Mage"]="作为人类法师，你会先从凯尔登·布雷门那里接受最初的正规奥术教导，再前往暴风城的高塔继续研习。"},sec={{t="奥术导师",b="在书房里，凯尔登·布雷门教导初学者严守法度、专注心神，以安全地塑造原始的魔法能量。楼下，神职人员和守卫们继续履行职责。他的学生们正准备穿过艾尔文森林，前往暴风城的法师区继续研习。"}},faq={{q="凯尔登·布雷门是谁？",a="凯尔登·布雷门在艾尔文森林的北郡修道院训练新晋法师。他教导他们最初的法术，以及奥术研习的基础知识。",al={"凯尔登是谁","布雷门","北郡法师训练师"}},{q="在哪里能找到凯尔登·布雷门？",a="凯尔登·布雷门位于北郡修道院的二楼。进入修道院，从左侧第二个房间的楼梯上楼。",al={"凯尔登在哪","凯尔登·布雷门位置","北郡法师训练师位置"}},{q="他对初出茅庐的冒险者有何帮助？",a="来到北郡的人类法师会被指引去拜访凯尔登·布雷门，通常还会带上一封作为介绍信的雕文信件。他教导他们最初的法术，并帮助他们掌控自己的魔法天赋。",al={"凯尔登做什么","布雷门任务","雕文信件收件人"}}},fx={["7cfd66d2"]={q="凯尔登·布雷门站在哪一边？",a="凯尔登·布雷门坚定地效忠于暴风城王国和联盟。他驻守在北郡修道院，为王国培养新一代施法者，让他们做好准备，保卫人类的土地，抵御日益增长的危险。",al={"凯尔登·布雷门阵营","凯尔登为谁效力","凯尔登·布雷门是联盟吗"}},["032606f2"]={q="凯尔登·布雷门想要什么？",a="凯尔登的目标是向法师新手传授奥术技艺。他寻找潜心求学的学徒，让他们学习基础咒语，掌握日渐增长的才智，并负责任地运用力量，守护艾尔文森林和暴风城的安全。",al={"凯尔登·布雷门目标","凯尔登想要什么"}},["8660ec47"]={q="凯尔登·布雷门为什么在北郡修道院？",a="北郡修道院为响应暴风城号召的年轻守卫者提供招募与训练的安身之所。布雷门住在修道院楼上，专门接待初涉法术的人类学徒，在他们深入王国各地之前，引导他们迈出学习魔法的第一步。",al={"凯尔登为什么在北郡","凯尔登·布雷门为什么在这里"}}},fp="14,153,19.261.0,22.136.0,32.129.0,43.188.0"}
P.entries["npc:kil-hala"] = {n="基尔哈拉",s="在贫瘠之地的十字路口，基尔哈拉教部落裁缝加工布料。他还为年轻的部落法师编织虚灵长袍，只要他们带来灰谷欢笑姐妹的几缕头发。",h="在贫瘠之地的十字路口，基尔哈拉教部落裁缝加工布料。他还为年轻的部落法师编织虚灵长袍，只要他们带来灰谷欢笑姐妹的几缕头发。",kw={"贫瘠之地","十字路口","基尔哈拉","欢笑姐妹","虚空花边","裁缝","训练师"},ang={["faction:Horde"]="在十字路口，基尔哈拉传授纺织技艺，并为在贫瘠之地立足的部落战团和旅人提供货物。",["profession:Tailoring"]="身为部落裁缝，你可以在十字路口向基尔哈拉学习这门手艺。他还提供了一种编织奇异魔法长袍的方法。"},sec={{t="贫瘠之地的裁缝",b="基尔哈拉在十字路口训练裁缝，部落新兵和旅人都能在那里学习他的手艺。他传授如何加工普通布卷，以及制作适合在干燥平原上生活的衣物。应迪诺的请求，他还为年轻法师制作虚灵长袍，只要他们带来欢笑姐妹的头发，她们是灰谷森林中的树妖。"}},faq={{q="基尔哈拉是谁？",a="基尔哈拉是一名黑暗之矛巨魔，在贫瘠之地的十字路口训练裁缝。他向部落工匠传授编织布料和制作衣物的基础技艺。",al={"基尔哈拉身份","基尔哈拉是谁","十字路口裁缝"}},{q="在哪里可以找到基尔哈拉？",a="在十字路口可以找到基尔哈拉，那里是部落在贫瘠之地的中心聚居地。他就在其他部落专业训练师身旁。",al={"基尔哈拉位置","基尔哈拉在哪里","基尔哈拉地点"}},{q="基尔哈拉会给裁缝什么任务？",a="基尔哈拉本人不会派裁缝外出办事。迪诺派来的年轻部落法师会给他带来欢笑姐妹的几缕头发，她们是灰谷林中树居附近的树妖，他则将这些头发织成虚空花边服装交给他们。",al={"基尔哈拉任务","欢笑姐妹任务","虚空 蕾丝服装"}}},fp="8,208,21.328.0,16.144.0,26.129.0,41.220.0"}
P.entries["npc:kin-weelay"] = {n="肯维雷",s="肯维雷是一位声名远扬的黑暗之矛巫医，驻守在荆棘谷的格罗姆高营地。他直接受命于奥格瑞玛，为丛林中的部落先遣军提供秘术援助与指引。他精通灵魂之术，在破解黑暗魔精、协助营救年幼的耶尼库时发挥着关键作用。",h="肯维雷是一位声名远扬的黑暗之矛巫医，驻守在荆棘谷的格罗姆高营地。他直接受命于奥格瑞玛，为丛林中的部落先遣军提供秘术援助与指引。他精通灵魂之术，在破解黑暗魔精、协助营救年幼的耶尼库时发挥着关键作用。",kw={"黑暗之矛","格罗姆高","肯维雷","心灵之眼","巫医","耶尼库"},ang={["faction:Horde"]="肯维雷为部落应对单凭力量无法化解的威胁提供魔法对策，展现了巨魔通灵之术对部落战事的价值。",["race:Troll"]="对暗矛巨魔而言，肯维雷是族中最受尊敬的灵魂权威之一，致力于解除丛林同族施下的残酷诅咒。"},sec={{t="黑暗之矛魔精大师",b="肯维雷被黑暗之矛视为族中最强大的传统巫术施术者之一，对灵魂、妖术和灵魂魔法有着深厚的造诣。每当遇到涉及先祖之灵或敌对巨魔咒术的事情，荆棘谷的部落斥候都会求助于他，揭开魔法的帷幕。"},{t="前往格罗姆高的使命",b="肯维雷从奥格瑞玛尘土飞扬的街道一路南下，专程前往格罗姆高营地支援尼姆布亚。他的使命并不止于军事支援；他专注于解除施加在耶尼库身上的邪恶束缚，这个被掳走的孩子出身于酋长沃金所信赖的血脉。为了破解这种黑暗巫术，肯维雷正在寻找强大的施法材料，其中最重要的便是心灵之眼，用来制作能够释放被囚灵魂的灵魂宝石。"}},faq={{q="肯维雷是谁？",a="肯维雷是一位备受敬重的黑暗之矛巨魔巫医，驻守在荆棘谷北部的格罗姆高营地。他以精通通灵之术和灵魂魔法闻名，由部落领袖从奥格瑞玛派遣而来。",al={"肯维雷故事","肯维雷是谁","格罗姆高巫医"}},{q="肯维雷为什么来到荆棘谷？",a="他被派往格罗姆高营地，以秘术协助尼姆布亚和当地的黑暗之矛远征队，尤其是寻找年幼的耶尼库，将他从敌对丛林巨魔的控制中解救出来，并使他恢复正常。",al={"肯维雷为何在格罗姆高","肯维雷的目的"}},{q="肯维雷想要制造什么？",a="肯维雷正在寻找一件名为心灵之眼的圣物。他打算用巫术将其炼制成一颗灵魂宝石，捕获并妥善保存耶尼库的灵魂，切断施加在这个男孩身上的黑暗控制。",al={"肯维雷心灵之眼","肯维雷制造什么"}},{q="肯维雷来自哪里？",a="他来自奥格瑞玛，黑暗之矛部族自加入部落并定居回音群岛以来，便一直与这座城市保持着紧密联系，并有族人常驻于此。",al={"肯维雷背景","肯维雷来自哪里"}},{q="他如何看待荆棘谷的其他巨魔部族？",a="他将血顶和裂颅者等敌对丛林部族视为危险的对手，认为他们深陷暴力而腐化的仪式。他积极运用巫术对抗他们的咒术，救回被掳走的黑暗之矛年轻族人。",al={"肯维雷其他巨魔","肯维雷与血顶"}},{q="肯维雷研究哪些物品？",a="肯维雷调查当地带有自然或妖术共鸣的奇物，包括神秘的歌唱水晶，以及敌对丛林巨魔佩戴的骨质项链，通过研究其中的魔精来制定对策。",al={"肯维雷物品","歌唱水晶肯维雷"}}},fp="10,170,26.216.0,23.333.1,18.182.0,40.199.0,36.156.0,32.140.0,57.221.0,41.200.0"}
P.entries["npc:kindal-moonweaver"] = {n="辛达尔·月纹",s="辛达尔·月纹是一位暗夜精灵，隐居在菲拉斯崎岖山间的一处隐秘角落，就在恐怖图腾营地以北。荒野中的野生动物遭受虐待，令她深感忧虑。她监视着下方好勇斗狠的牛头人部族，同时寻求援手，解救被捕的野兽。她与耶尔卡·月纹是亲族，两人肩负着同样的使命，保护森林中无辜的生灵。",h="辛达尔·月纹是一位暗夜精灵，隐居在菲拉斯崎岖山间的一处隐秘角落，就在恐怖图腾营地以北。荒野中的野生动物遭受虐待，令她深感忧虑。她监视着下方好勇斗狠的牛头人部族，同时寻求援手，解救被捕的野兽。她与耶尔卡·月纹是亲族，两人肩...",kw={"厄运之槌","菲拉斯","所有生灵的自由","恐怖图腾营地","秘道","耶尔卡·月纹","辛达尔·月纹"},ang={["class:Druid"]="辛达尔一心保护森林生命，将受困的自然之灵从残酷的铁笼中解救出来，德鲁伊会与她志同道合。",["class:Hunter"]="与卡利姆多的野兽心意相通的猎人，会敬重辛达尔的努力：保护荒野中的幼兽，惩罚那些为了取乐或出于恶意而捕捉野兽的人。",["race:NightElf"]="辛达尔体现了kaldorei对自然世界一贯的虔诚，她独自守护着受到外来入侵者威胁的野兽。"},sec={{t="峭壁上的守望者",b="厄运之槌以东，一条狭窄蜿蜒的山路被树木部分遮蔽，辛达尔·月纹就在这里秘密监视着下方的山谷。菲拉斯的大部分地区陷于部落、羽月的暗夜精灵以及埃雷萨拉斯古老废墟之间的争夺，而辛达尔关注的是近在眼前、发生在一隅的暴行。下方的谷地里，恐怖图腾部族经营着一座设防营地，捕捉并圈禁当地的动物，其用意绝非善举。在隐蔽的瞭望处，辛达尔留意着是否有人愿意冒险闯入敌营，终结其中的苦难。"},{t="怜悯荒野生灵",b="辛达尔最关心的是菲拉斯神圣的平衡，以及那些无力抵抗野蛮捕猎者的温顺生灵。她与亲族耶尔卡·月纹一道，寻求解救笼中的野兽，也照看那些因残暴偷猎而流离失所的幼兽。她无意投身大规模的领土战争，而是将心力倾注于怜悯之举：释放笼中的精灵，并为一只失去双亲的小精龙寻找归宿。"}},faq={{q="辛达尔·月纹在哪里？",a="辛达尔藏身于菲拉斯北部的峭壁间，就在厄运之槌以东、恐怖图腾营地上方。找到一片树林后方那条隐蔽狭窄、蜿蜒上山的小径，就能抵达她所在之处。",al={"辛达尔·月纹位置","如何找到辛达尔","辛达尔在哪"}},{q="辛达尔·月纹是谁？",a="她是一位独居的暗夜精灵，致力于保护菲拉斯的动物与自然环境。她监视着恐怖图腾营地，阻止他们捕捉当地的野生动物。",al={"辛达尔背景故事","辛达尔是谁"}},{q="辛达尔在菲拉斯的目标是什么？",a="辛达尔希望解救附近恐怖图腾营地中被关在笼里的生灵，并确保荒野中失去双亲的野兽得到救助和安全的庇护。",al={"辛达尔任务目的","辛达尔为何在此"}},{q="辛达尔·月纹与耶尔卡·月纹有亲缘关系吗？",a="是的，辛达尔与耶尔卡·月纹是亲族。两人都姓月纹，并携手救助菲拉斯林地中遭受虐待、流离失所的生灵。",al={"耶尔卡·月纹的关联","辛达尔与耶尔卡"}},{q="辛达尔为何反对恐怖图腾？",a="恐怖图腾氏族占据着她栖身的山崖下方的营地，捕捉菲拉斯的野兽，并将它们关进笼中。辛达尔希望让这些生灵重获自由，并惩罚捕捉它们的人。",al={"辛达尔与恐怖图腾","恐怖图腾营地辛达尔"}},{q="辛达尔·月纹向双方阵营都提供任务吗？",a="不。辛达尔只向联盟提供任务，她招募联盟冒险者，从恐怖图腾手中解救笼中的生灵。",al={"辛达尔对部落友好吗","部落能与辛达尔交谈吗"}}},fp="17,266,26.536.0,23.337.0,35.169.0,25.156.0,33.138.0,51.121.0,37.158.0,53.125.0"}
P.entries["npc:kirge-sternhorn"] = {n="基尔格·锐角",s="在贫瘠之地，基尔格·锐角为穿越卡利姆多中部的旅人指引道路。这位牛头人守望着南部的小径，并指引初出茅庐的部落冒险者北上，前往十字路口。",h="在贫瘠之地，基尔格·锐角为穿越卡利姆多中部的旅人指引道路。这位牛头人守望着南部的小径，并指引初出茅庐的部落冒险者北上，前往十字路口。",kw={"贫瘠之地","十字路口","基尔格","南贫瘠之地","锐角","陶拉祖","牛头人"},ang={["faction:Horde"]="身为部落的一员，从南部地区出发时，你可以将基尔格视为旅途早期的一处路标，他会指引你前往十字路口，融入更大的部落群体。",["race:Tauren"]="身为牛头人，你能从基尔格引领部族同胞与盟友穿越新家园严酷边疆的方式中，感受到他踏实而热忱的品性。"},sec={{t="贫瘠之地的行者",b="初来乍到的流浪者常常对烈日炙烤下的贫瘠之地心生畏惧。基尔格·锐角照看着中央道路以南的旅人，那里位于南部营地与卡利姆多腹地之间。四处劫掠的野猪人和凶猛的掠食者在草原上游荡，基尔格帮助年轻的冒险者站稳脚跟。他确保他们前去寻找集结在北方、规模更大的部落力量。"}},faq={{q="基尔格·锐角是谁？",a="基尔格·锐角是贫瘠之地南部的一位牛头人行者兼向导。他帮助部落旅人穿越尘土飞扬的平原。",al={"基尔格·锐角背景故事","基尔格是谁","基尔格非玩家角色"}},{q="基尔格让旅人前往何处？",a="基尔格指引旅人北上，前往贫瘠之地的交通枢纽十字路口。部落军队在那里协调整个地区的防御与探索行动。",al={"基尔格任务","十字路口之旅 基尔格","基尔格指引前往何处"}},{q="基尔格·锐角效忠哪个阵营？",a="基尔格忠于部落和他的牛头人同胞。他为所有途经这片领地的部落成员提供指引与帮助。",al={"基尔格是否属于部落","基尔格效忠对象"}}},fp="15,161,25.354.0,23.119.0,32.159.0,40.123.0"}
P.entries["npc:klannoc-macleod"] = {n="克兰诺克·马克雷德",s="在勇士岛上，克兰诺克·马克雷德考验着前来的战士。这位人类战士欢迎联盟和部落的斗士前来精进战斗姿态。赢得他尊重的人，会被派往内陆，接受更严峻的力量试炼。",h="在勇士岛上，克兰诺克·马克雷德考验着前来的战士。这位人类战士欢迎联盟和部落的斗士前来精进战斗姿态。赢得他尊重的人，会被派往内陆，接受更严峻的力量试炼。",kw={"贫瘠之地","狂暴战士","勇士岛","岛民","克兰诺克","马克雷德","格斗考验","战士"},ang={["class:Warrior"]="身为战士，你要先在The Affray中接受克兰诺克·马克雷德对耐力与凶猛斗志的考验，之后他才会引导你掌握Berserker Stance。",["faction:Alliance"]="身为联盟战士，你必须远赴贫瘠之地海岸外的海域，找到克兰诺克·马克雷德，在勇士岛上证明自己已做好战斗准备。",["faction:Horde"]="身为部落斗士，你可以向克兰诺克·马克雷德寻求试炼与荣誉，他在自己的岛上将阵营间的争斗置于一旁。"},sec={{t="勇士岛的大师",b="克兰诺克·马克雷德在勇士岛上考验身经百战的斗士，这座岛位于贫瘠之地的商旅海岸外海。他虽是人类，却将联盟与部落的纷争置于一旁。他以每位挑战者的勇气、武艺和临阵时的意志来评判他们。"},{t="混战试炼",b="克兰诺克·马克雷德在勇士岛上设下的试炼名为格斗考验。挑战者登上架高的铁栅平台，在他的注视下，迎战一波又一波跃跃欲试的斗士。撑过猛攻并击败他选定的勇士，便能得到他的认可，证明自己具备接受狂暴战士训练所需的心性。"}},faq={{q="克兰诺克·马克雷德是谁？",a="克兰诺克·马克雷德在贫瘠之地海岸外的勇士岛上训练战士，考验他们的极限。斗士们前来找他，证明自己，学习新的技艺。",al={"克兰诺克是谁","克兰诺克·马克雷德背景故事","勇士岛上的人"}},{q="在哪里能找到克兰诺克·马克雷德？",a="你可以在勇士岛上找到克兰诺克·马克雷德，这座岩石小岛位于贫瘠之地东部外海、商旅海岸和棘齿城的东南方。游过开阔的海面，就能到达他的营地。",al={"克兰诺克位置","勇士岛在哪里","如何前往克兰诺克处"}},{q="为什么勇士岛上的人类会与部落玩家交谈？",a="克兰诺克·马克雷德不参与联盟与部落的冲突。他以挑战者的武学修养和战士意志来评判他们，并考验那些持有合适引荐而来的人。",al={"克兰诺克是否敌视部落","克兰诺克为何保持中立","部落克兰诺克"}},{q="什么是格斗考验？",a="格斗考验是勇士岛上的一项耐力试炼。你站在克兰诺克的战斗平台上，击败一波又一波的挑战者，最后迎战比格维尔，以证明自己具备掌握高阶战士技艺所需的凶猛斗志。",al={"格斗考验任务","勇士岛试炼","克兰诺克试炼"}},{q="为什么要把战士派往克兰诺克·马克雷德那里？",a="遍布艾泽拉斯的战士训练师会将最有潜力的学徒派往克兰诺克·马克雷德那里，接受武勇与毅力的考验。这项试炼让你为狂暴姿态所需的炽烈专注做好准备。",al={"勇士岛战士任务","为何拜访克兰诺克","狂暴姿态任务"}},{q="完成格斗考验后，克兰诺克会派你去找谁？",a="在格斗考验中证明自己后，克兰诺克·马克雷德会派你北上，前往塔伦米尔附近的奥特兰克山脉，寻求捕风者巴斯拉的指引。",al={"克兰诺克之后","捕风者任务","捕风者是谁"}}},fp="15,210,25.230.0,10.290.0,23.152.0,33.175.0,54.206.0,19.222.0,37.181.0,46.163.1"}
P.entries["npc:kor-ghan"] = {n="考格汉",s="在奥格瑞玛的暗影裂口，考格汉照看着药剂与毒药。这位黑暗之矛巨魔站在雷库尔的毒药店外，寻求帮助，配制解毒剂以应对杜隆塔尔的有毒掠食者。",h="在奥格瑞玛的暗影裂口，考格汉照看着药剂与毒药。这位黑暗之矛巨魔站在雷库尔的毒药店外，寻求帮助，配制解毒剂以应对杜隆塔尔的有毒掠食者。",kw={"解毒剂","暗影裂口","考格汉","奥格瑞玛","蝎子毒液","森金村"},ang={["class:Rogue"]="身为潜行者，当你前往奥格瑞玛的地下区域购买施法材料与毒液时，可能会在暗影裂口的Rekkul's Poisons外见到考格汉。",["race:Troll"]="身为巨魔，你与许多离开森金村的黑暗之矛巨魔同属一族。考格汉在部落戒备森严的都城中，运用着他对杜隆塔尔荒野险情的了解。"},sec={{t="暗影中的巨魔",b="考格汉在奥格瑞玛的暗影裂口，照看着雷库尔的毒药店外的药剂与毒药。他从这座都城派遣旅人前往杜隆塔尔的红色峡谷，从蝎子身上收集有毒材料。他需要这些材料来配制解毒剂，应对荒野中的危险。"}},faq={{q="考格汉是谁？",a="考格汉是一位黑暗之矛巨魔，站在奥格瑞玛暗影裂口的雷库尔毒药店外。",al={"考格汉","考格汉是谁","考格汉 非玩家角色"}},{q="在哪里可以找到考格汉？",a="考格汉就在奥格瑞玛中央地下的暗影裂口，雷库尔毒药店的正前方。",al={"考格汉位置","考格汉在哪里","寻找考格汉"}},{q="考格汉需要什么帮助？",a="考格汉需要旅人从奥格瑞玛入口附近的毒尾蝎身上收集毒囊，以便配制解毒剂。",al={"考格汉任务","寻找解毒剂任务","考格汉毒液"}},{q="考格汉曾经在杜隆塔尔出现过吗？",a="考格汉待在奥格瑞玛的毒药商附近。他派遣旅人前往杜隆塔尔，从城门附近的毒尾蝎身上收集毒囊。",al={"考格汉 森金","考格汉旧位置"}}},fp="8,196,22.287.0,16.103.0,26.110.0,34.127.0,35.160.0"}
P.entries["npc:korran"] = {n="科兰",s="科兰在十字路口监视贫瘠之地，留意威胁部落的动向。这位黑暗之矛巨人魔听命于奥格瑞玛的贝尔戈洛姆·石槌，研究在各处灌木荒野中出现的异种蝎。",h="科兰在十字路口监视贫瘠之地，留意威胁部落的动向。这位黑暗之矛巨人魔听命于奥格瑞玛的贝尔戈洛姆·石槌，研究在各处灌木荒野中出现的异种蝎。",kw={"贫瘠之地","贝尔戈洛姆·石槌","十字路口","寻卵","巨人旷野","科兰","异种虫"},ang={["faction:Horde"]="身为部落的一员，科兰关注着卡利姆多不断变化的生态，留意silithid这类新威胁，而奥格瑞玛则在巩固边防。",["race:Troll"]="身为黑暗之矛巨魔，你将侦察与生存的本能带到干旱的贫瘠之地，科兰正在这里凭借务实的机敏研究奇异的异域野兽。"},sec={{t="十字路口的斥候",b="科兰在十字路口留意着野猪人和半人马氏族之外的威胁。奥格瑞玛的贝尔戈洛姆·石槌派这位巨魔斥候驻守此地，观察这片土地的变化。科兰负责协调情报收集工作，为部落领袖提供情报。"},{t="异种蝎的入侵",b="科兰如今将注意力集中在贫瘠之地南部的巨人旷野。一种名为异种蝎的奇异虫形生物开始钻入地下，它们极具攻击性。为了查明虫群从何而来，以及它们对新生的部落有何威胁，科兰请过往的冒险者用他的爪形工具挖出完整的虫卵。"}},faq={{q="科兰是谁？",a="科兰是一名黑暗之矛巨魔，在十字路口观察并研究贫瘠之地。他向奥格瑞玛的贝尔戈洛姆·石槌汇报。",al={"科兰是谁","科兰 巨魔","十字路口 巨魔"}},{q="科兰在贫瘠之地调查什么？",a="科兰正在调查贫瘠之地南部巨人旷野上一种名为异种蝎的奇异虫形生物，它们极具攻击性。据报告，更南方的千针石林也出现了类似的虫群。",al={"科兰研究什么","科兰 研究","巨人旷野 昆虫"}},{q="科兰为谁效力？",a="科兰听命于贝尔戈洛姆·石槌，一位身处奥格瑞玛荣誉谷的老练战士。贝尔戈洛姆·石槌为部落监视卡利姆多各地新出现的威胁。",al={"谁派来了科兰","科兰 上级","贝尔戈洛姆·石槌"}},{q="科兰为什么需要异种蝎卵？",a="科兰需要完整的异种蝎卵，以研究虫群的生命周期和起源。他希望弄清这些生物究竟是什么，以及它们对部落领土构成多大的威胁。",al={"为什么需要异种蝎卵","寻卵任务","科兰 爪形工具"}}},fp="6,186,25.243.0,22.313.0,14.129.0,44.197.0,25.151.0,35.172.0"}
P.entries["npc:kravel-koalbeard"] = {n="克拉维尔·浓须",s="克拉维尔·浓须是个诡计多端的矮人商人兼骗子，驻扎在闪光平原的沙漠赛道。他为比赛喝彩并非纯粹出于热爱，而是把侏儒与地精之间激烈的赛车竞争视为大发横财的良机。从搜捡散落的机械零件，到利用勒索和酒精操纵比赛结果，克拉维尔总在寻找下一个有利可图的骗局。",h="克拉维尔·浓须是个诡计多端的矮人商人兼骗子，驻扎在闪光平原的沙漠赛道。他为比赛喝彩并非纯粹出于热爱，而是把侏儒与地精之间激烈的赛车竞争视为大发横财的良机。从搜捡散落的机械零件，到利用勒索和酒精操纵比赛结果，克拉维尔总在寻...",kw={"勒索","浓须","克拉维尔","沙漠赛道","火箭车","破坏","闪光平原","千针石林"},ang={["class:Rogue"]="潜行者会对克拉维尔的营生感到熟悉：盗窃、破坏、勒索，以及在暗处操纵贪婪的目标。",["race:Dwarf"]="与铁炉堡那些诚实的矿工、勘探员和巡山人不同，克拉维尔是个毫不知耻的无赖和骗子，让矮人的传统价值观蒙羞。",["race:Gnome"]="侏儒在克拉维尔身边时，应该看紧自己的饮料和蓝图，因为他既热衷于破坏侏儒的机器，也同样热衷于给侏儒车手下药。"},sec={{t="平原上的骗子",b="沙漠赛道的大多数观众和车队成员都沉浸在机械竞赛与火箭引擎的轰鸣声中，克拉维尔·浓须却只盯着所有人的钱袋。他是个投机者，在赛道营地尘土飞扬的角落里活动，动不动就提出委托或提供帮助，背后的动机却鲜有干净的。在克拉维尔眼中，侏儒与地精工程师之间赌注高昂的较量并非鼓舞人心的竞技，而是滋生勒索、破坏和盗窃的沃土。"},{t="操纵赛局",b="克拉维尔的勾当远不止在盐滩上捡拾废弃零件。为了操纵赔率，让比赛结果对自己有利，克拉维尔时常派遣愿意效劳的冒险者去干些非法勾当——散布谣言、实施勒索，甚至在决赛前夕灌醉维修人员。无论是用烈酒招待地精技师，还是偷偷给侏儒车手递上烈性饮品，只要能在比赛日赚个盆满钵满，克拉维尔什么卑劣手段都使得出来。"}},faq={{q="克拉维尔·浓须是谁？",a="克拉维尔·浓须是个善于耍弄阴谋的矮人投机者，驻扎在闪光平原的沙漠赛道。他利用侏儒与地精之间的竞争，通过搜捡废料、操纵比赛和敲诈勒索来中饱私囊。",al={"克拉维尔是谁","克拉维尔·浓须的身份","沙漠赛道的矮人"}},{q="克拉维尔·浓须在沙漠赛道做些什么？",a="克拉维尔雇用旅人在赛道周围替他干些见不得光的勾当。他的阴谋包括收集捡来的火箭车零件、挖掘可供勒索的把柄，以及灌醉技师和车手，借此破坏车队的表现，左右比赛结果。",al={"克拉维尔的目的","克拉维尔想要什么","克拉维尔的阴谋"}},{q="克拉维尔为什么要灌醉车队成员？",a="克拉维尔在火箭车比赛的结果上押下重注。他在赛前灌醉侏儒或地精，借此操纵比赛，让结果朝着最能为自己牟利的方向发展。",al={"灌醉侏儒任务","灌醉地精","克拉维尔的破坏活动"}},{q="在哪里能找到克拉维尔·浓须？",a="他位于千针石林的闪光平原，就在沙漠赛道热闹的维修营地一带徘徊。",al={"克拉维尔的位置","克拉维尔在哪里","克拉维尔 千针石林"}},{q="克拉维尔在千针石林之外也有人脉吗？",a="有。他的黑心买卖牵涉到地精港口棘齿城和藏宝海湾的联系人，其中包括与棘齿城的码头管理员迪兹维格、谣言贩子以及荆棘谷异域佳酿有关的交易。",al={"克拉维尔 藏宝海湾","克拉维尔的人脉"}},{q="克拉维尔会同时与联盟和部落合作吗？",a="和许多在沙漠赛道这类中立场所活动的人一样，克拉维尔在意的是金币，而非阵营忠诚。他很乐意雇用联盟和部落的冒险者来执行自己的阴谋。",al={"克拉维尔是否仅限联盟","部落能否与克拉维尔交谈"}}},fx={["33aea695"]={q="克拉维尔·浓须想要什么？",a="克拉维尔一心只想着利润和私利。在闪光平原，他想通过各种手段填满自己的腰包，从运送零件、兜售人情到策划敲诈勒索，无所不用其极。他最大胆的野心是操纵沙漠赛道的比赛结果，计划通过让维修团队和车手酩酊大醉来破坏并操控比赛。",al={"克拉维尔想要什么","克拉维尔·浓须的目标","克拉维尔的动机"}},["97572808"]={q="克拉维尔·浓须为什么会在千针石林？",a="闪光平原的沙漠赛道是个无法无天的地方，充斥着高额赌博、激烈竞争和鲁莽工程，因此成了骗子觅食的绝佳场所。克拉维尔在互相较劲的侏儒和地精旁边扎营，因为他们对击败彼此的执念让他们对投机者视而不见，也很容易落入他的圈套。",al={"克拉维尔为什么在这里","克拉维尔为什么在沙漠赛道","克拉维尔与闪光平原"}}},fp="16,215,25.289.0,17.326.1,24.185.0,52.181.0,45.157.0,36.117.0,47.193.0,46.111.0"}
P.entries["npc:kreldig-ungor"] = {n="克雷迪格·安戈尔",s="克雷迪格·安戈尔是一名富有进取心的矮人干员，代表寻物公司.驻扎在凄凉之地尼耶尔前哨站的高耸山崖间。他负责管理这片贫瘠荒原上的野外事务，雇用联盟冒险者找回遗失的货物，并收集当地珍贵的材料。他承接的打捞和回收合约，使他成为穿行于这片险地的旅人不可或缺的联络人。",h="克雷迪格·安戈尔是一名富有进取心的矮人干员，代表寻物公司.驻扎在凄凉之地尼耶尔前哨站的高耸山崖间。他负责管理这片贫瘠荒原上的野外事务，雇用联盟冒险者找回遗失的货物，并收集当地珍贵的材料。他承接的打捞和回收合约，使他成为穿...",kw={"联盟","凄凉之地","矮人","卡尼托的沉船","克雷迪格·安戈尔","尼耶尔前哨站","寻物公司","打捞"},ang={["faction:Alliance"]="克雷迪格驻扎在尼耶尔前哨站，完全依靠联盟旅人，才能在这片四面皆敌的土地上继续履行打捞合约。",["race:Dwarf"]="克雷迪格远离山中的厅堂，在边疆开张做生意，展现了矮人对探索险峻边地的热忱和经商的雄心。"},sec={{t="荒原上的外勤干员",b="在凄凉之地满目疮痍的峡谷间，尼耶尔前哨站为联盟提供了一处难得的庇护所，也成为克雷迪格·安戈尔这类逐利者开展生意的理想据点。克雷迪格代表寻物公司.，远离卡兹莫丹的安稳生活，深入半人马氏族、恶魔和部落争夺的荒凉旷野。旁人眼中只有废墟与灰烬，克雷迪格却看到了尚未发掘的利润，以及亟待找回的遗失财物。"},{t="卡尼托的合约",b="吸引克雷迪格来到凄凉之地的一项主要生意，与卡尼托失踪的船只有关，那艘船在凶险的西海岸失事。卡尼托的船上载着珍贵货物，克雷迪格正组织人手寻找残骸，抢在拾荒者或沿岸的海巨人将其尽数占有之前，找回散落的货物。"},{t="采集当地材料",b="除了海上打捞，克雷迪格还负责为寻物公司.采集凄凉之地奇异而珍贵的生物和矿物材料。严酷的环境孕育了独特的动植物，它们的各个部位在东部王国的炼金师和工程师那里都能卖出高价。愿意冒险面对荒原掠食者的冒险者，都能在克雷迪格的账簿上找到一份稳定的报酬。"}},faq={{q="克雷迪格·安戈尔是谁？",a="克雷迪格·安戈尔是一名隶属于寻物公司.的矮人干员，以凄凉之地的联盟据点尼耶尔前哨站为基地。他协调这片区域内的打捞任务和标本采集工作。",al={"克雷迪格·安戈尔背景故事","克雷迪格是谁","克雷迪格·安戈尔"}},{q="寻物公司.是什么？",a="寻物公司.是一家以营利为目的的企业，专门在危险的边疆地区打捞遗失货物、回收残骸并采集稀有材料。",al={"寻物公司","寻物公司是什么","寻物公司的业务"}},{q="在哪里能找到克雷迪格·安戈尔？",a="他位于联盟聚居地尼耶尔前哨站，那里高踞于凄凉之地东北部的嶙峋山岭间。",al={"克雷迪格·安戈尔位置","克雷迪格在哪里","寻找克雷迪格·安戈尔"}},{q="克雷迪格想从卡尼托的沉船中得到什么？",a="一艘载有卡尼托珍贵货物的船在凄凉之地沿岸失事。克雷迪格雇用冒险者寻找沉船，在遗失货物被拾荒者取走或遭到毁坏之前将其找回。",al={"卡尼托的沉船","克雷迪格 卡尼托","凄凉之地沉船"}},{q="克雷迪格为什么在凄凉之地收集材料？",a="凄凉之地的严酷环境孕育了稀有生物和独特的天然化合物。克雷迪格收集这些标本，供应给联盟各大城市的炼金师、工匠和买家。",al={"寻物公司的材料","凄凉之地材料","为什么收集材料"}},{q="克雷迪格为铁炉堡效力，还是受雇于私人企业？",a="虽然克雷迪格在联盟据点开展工作，而且只雇用联盟旅人，但他代表的是寻物公司.，一家以打捞和贸易为业的商业企业，并不执行王室的正式军事任务。",al={"克雷迪格隶属联盟还是私人企业","寻物公司 铁炉堡"}}},fx={ad7684ca={q="克雷迪格·安戈尔为什么驻扎在尼耶尔前哨站？",a="克雷迪格·安戈尔在尼耶尔前哨站的高处开设据点，以便在凄凉之地崎岖广袤的土地上为“回收者公司”开展业务。在这座设防的联盟避难所中，他相对安全地管理着废品回收和物资采购，还以此为基地，雇用强悍的冒险者深入险恶的荒地执行任务。",al={"克雷迪格·安戈尔为什么在这里","克雷迪格·安戈尔与尼耶尔前哨站","克雷迪格为什么在凄凉之地"}}},fp="13,164,25.306.0,21.237.0,25.336.0,21.156.0,24.126.0,33.85.0,51.190.0,47.171.0,56.210.0"}
P.entries["npc:krolg"] = {n="克罗格",s="克罗格住在密斯特拉湖南面、灰谷一间偏僻的小屋里，未受腐化。他被污林部族放逐，在同胞陷入恶魔般的疯狂时仍保持着理智。他只与看起来像熊怪的人交谈。",h="克罗格住在密斯特拉湖南面、灰谷一间偏僻的小屋里，未受腐化。他被污林部族放逐，在同胞陷入恶魔般的疯狂时仍保持着理智。他只与看起来像熊怪的人交谈。",kw={"灰谷熊怪","穆戈特酋长","达图尔的魔棒","污林","克罗格","克罗格的小屋","密斯特拉湖","莱恩的净化"},ang={["class:Druid"]="作为一名寻求恢复灰谷平衡的德鲁伊，你可以向克罗格求助。在遭到腐化的野生生灵之中，他仍保有清醒的声音。",["faction:Alliance"]="作为一名协助莱恩·狼行者的联盟斥候，你要依靠克罗格，瓦解敌对的Foulweald熊怪的领导层。",["race:NightElf"]="对阿斯特兰纳的暗夜精灵而言，克罗格让他们想起了古老的熊怪盟友，那时恶魔腐化尚未使各个部族分崩离析。"},sec={{t="未失的理智",b="在密斯特拉湖南面，克罗格依然神志清醒，未受疯狂侵蚀。灰谷的大多数污林熊怪都已屈服于燃烧军团留下的恶魔污染。克罗格在隐蔽的住处谨慎地守望着森林。他亲眼看着同胞陷入毫无理智的暴行，如今只与看起来像同族的生灵交谈。"},{t="达图尔的遗产",b="达图尔的变形魔棒能让联盟旅者化身为熊怪。克罗格见到看似友善的同族，便会分享净化这片土地的方法。他派英雄们对付兰恩·血牙及其守卫，他们的腐化与仇恨正威胁着森林。"}},faq={{q="克罗格为什么不和我说话？",a="克罗格不信任外来者，也畏惧着席卷森林的暴力与混乱。除非你在莱恩的净化期间用达图尔的变形魔棒变成熊怪的模样，否则他不会理睬你。",al={"克罗格不说话","无法与克罗格交谈","克罗格为何沉默"}},{q="在哪里能找到克罗格？",a="克罗格住在灰谷中南部的克罗格的小屋，就在密斯特拉湖南面。",al={"克罗格位置","克罗格在哪里","克罗格小屋"}},{q="克罗格属于哪个部族？",a="克罗格曾是污林部族的一员。他的同胞陷入了腐化与恶魔般的狂乱，他却保持着理智，并因此被放逐。",al={"克罗格部族","克罗格是污林吗"}},{q="克罗格会敌视玩家吗？",a="克罗格会攻击那些靠近他、却没有熊怪外形的外来者。接近他之前，先使用达图尔的变形魔棒。",al={"克罗格会攻击吗","克罗格是敌人吗"}},{q="克罗格为什么想杀死兰恩·血牙？",a="在克罗格看来，兰恩·血牙渴求力量，并因腐化而变得更强。尽管他将同胞的苦难归咎于暗夜精灵，他也不会让兰恩威胁他们的孩子或森林中的其他生灵。",al={"克罗格 兰恩·血牙","为何杀死兰恩·血牙"}},{q="让冒险者能与克罗格交谈的魔棒，出自怎样一位名叫达图尔的人之手？",a="达图尔是一名邪恶的巫师，在死前创造了附有魔法的变形魔棒。在莱恩的净化期间，冒险者找回魔棒遗失的部件，并请人将其重铸，以便化身熊怪接近克罗格。",al={"达图尔是谁","达图尔的魔棒背景"}}},fp="5,171,15.296.0,15.268.1,27.182.0,25.82.0,32.131.0,28.129.0,40.208.1,60.216.0"}
P.entries["npc:krom-stoutarm"] = {n="克罗姆·粗臂",s="在铁炉堡，克罗姆·粗臂于探险者大厅钻研黑暗法术。他既是矮人学者，也是一名术士，在图书馆中研究奥术典籍与恶魔仪式。他指引着在卡利姆多和东部王国各地寻求秘传知识的联盟术士。",h="在铁炉堡，克罗姆·粗臂于探险者大厅钻研黑暗法术。他既是矮人学者，也是一名术士，在图书馆中研究奥术典籍与恶魔仪式。他指引着在卡利姆多和东部王国各地寻求秘传知识的联盟术士。",kw={"探险者大厅","铁炉堡","克罗姆·粗臂","图书馆","粗臂","阴谋之书","术士"},ang={["class:Warlock"]="身为联盟术士，你会在探求黑暗束缚之术时向克罗姆请教，其中包括集齐阴谋之书这项危险的工作。",["faction:Alliance"]="身为联盟的施法者，你可以在铁炉堡这座山中要塞里，与克罗姆一同找到潜心求知的避所。",["race:Dwarf"]="身为矮人，你会觉得克罗姆能在探险者大厅备受敬重的书架间占有一席之地，是个罕见的例外，因为矮人通常排斥邪恶法术。"},sec={{t="大厅中的黑暗角落",b="克罗姆·粗臂在探险者大厅探求神秘学识。那里的矮人考古学家用镐铲研究泰坦遗物，克罗姆却埋首于厚重的典籍和束缚恶魔的仪式。他的研究让术士技艺在铁炉堡的山中殿堂有了一席之地，尽管许多人仍不信任这些法术。"},{t="卡巴尔之书",b="寻求束缚地狱猎犬等强大恶魔的联盟术士会向克罗姆·粗臂求助。他知晓散落在遥远土地上的神秘典籍。他派遣召唤者找回臭名昭著的阴谋之书的残页和碎片，其中一些就在千针石林的半人马手中。"}},faq={{q="在哪里可以找到克罗姆·粗臂？",a="你可以在铁炉堡探险者大厅的图书馆区找到克罗姆·粗臂。",al={"克罗姆·粗臂位置","克罗姆·粗臂在哪里","克罗姆·粗臂铁炉堡"}},{q="克罗姆·粗臂对玩家有何作用？",a="克罗姆指引联盟术士完成恶魔仪式，其中包括找回阴谋之书。",al={"克罗姆做什么","克罗姆·粗臂作用","克罗姆·粗臂任务"}},{q="克罗姆·粗臂与其他粗臂家族成员有亲属关系吗？",a="有几位矮人都姓粗臂，但克罗姆与其他人之间的亲属关系尚未得到证实。",al={"克罗姆亲属","斯登·粗臂亲属关系"}},{q="为什么术士能获准进入探险者大厅？",a="克罗姆是铁炉堡的矮人，曾在奥达曼挖掘场担任挖掘工。如今，他是一名四处游历的术士，在图书馆中搜集古代典籍，据说从未有人将他拒之门外。",al={"克罗姆为什么在探险者大厅","铁炉堡允许术士"}},{q="克罗姆为什么与贫瘠之地有关？",a="克罗姆寻找阴谋之书的旅程终点在贫瘠之地。术士们从千针石林的半人马手中，以及南海镇以西近海的一批遗失货物中，找回这本书被撕开的两半。随后，克罗姆将复原的典籍送往棘齿城，交给斯坦哈德·法尔杉。",al={"克罗姆·粗臂贫瘠之地","克罗姆任务为什么去贫瘠之地"}},{q="克罗姆·粗臂会传授法术吗？",a="克罗姆是一位提供学识指引的联系人，而非职业训练师。他引导术士完成特定的成长仪式，而不是传授日常使用的魔典知识。",al={"克罗姆能传授法术吗","克罗姆术士训练师"}}},fx={["6ca19015"]={q="克罗姆·粗臂是谁？",a="克罗姆·粗臂是一名矮人术士，在铁炉堡探险者大厅的图书馆中研究黑暗知识。许多研习邪能法术的人藏身于阴暗的地下室和隐秘的巫师集会，克罗姆却公开活动于探险者协会的学者和发掘者之间，钻研古代遗物、晦涩的奥术知识和神秘典籍。",al={"克罗姆是谁","克罗姆·粗臂 背景故事","克罗姆·粗臂是谁"}},["23fb54c2"]={q="克罗姆·粗臂效忠哪一方？",a="克罗姆·粗臂效忠铁炉堡和联盟。尽管他研习的术士法术令许多同胞心生猜疑与不安，他仍是探险者大厅中受人尊敬的学者，只将自己的秘学专长和奥术知识用于帮助联盟勇士完成使命。",al={"克罗姆·粗臂 阵营","克罗姆·粗臂 联盟还是部落","克罗姆为谁效力"}}},fp="13,264,27.311.0,21.291.0,31.85.0,46.101.0,44.112.0,56.195.0,37.254.0,32.151.0"}
P.entries["npc:krusk"] = {n="克鲁斯克",s="在塔伦米尔，克鲁斯克统筹搜寻被俘斥候与辛迪加遗物的行动。他奉大酋长萨尔之命调查敦霍尔德城堡，遭遇伏击后幸存，但小队就此失散。",h="在塔伦米尔，克鲁斯克统筹搜寻被俘斥候与辛迪加遗物的行动。他奉大酋长萨尔之命调查敦霍尔德城堡，遭遇伏击后幸存，但小队就此失散。",kw={"德鲁尔","敦霍尔德城堡","高迪尔","希尔斯布莱德","克鲁斯克","辛迪加","塔伦米尔","萨尔","托格萨"},ang={["faction:Horde"]="作为部落的一员，你可以看到克鲁斯克在洛丹伦为大酋长萨尔的利益奔走。他努力守护敦霍尔德的历史，并让被俘的兽人脱离辛迪加之手。",["race:Orc"]="身为兽人，帮助克鲁斯克营救斥候同伴，牵动着族人的荣誉与收容所的痛苦往事。敦霍尔德正是萨尔为族人打破枷锁的堡垒。"},sec={{t="受挫的任务",b="突袭敦霍尔德城堡失败后，克鲁斯克在塔伦米尔主持后续行动。大酋长萨尔派他带领一支小队侦察辛迪加的活动，并找回与这座堡垒黑暗往事有关的遗物。这些人类歹徒的防守之严密、配合之默契都超出了预料，兽人斥候在残破的城墙内遭到伏击，不敌对手。克鲁斯克奋力杀出重围。德鲁尔和托格萨被俘，囚禁在废墟之中，而远征队的领队高迪尔则被转移到辛迪加的另一处据点。如今，克鲁斯克正指挥部落部队攻入敦霍尔德，找回失落的物品，并解救受困的同伴。"},{t="监视辛迪加",b="克鲁斯克在塔伦米尔追踪辛迪加在希尔斯布莱德的动向。奥特兰克的落魄贵族以敦霍尔德城堡为据点，密谋对付部落的前哨站和昔日的联盟同胞。克鲁斯克密切监视着奥里登·匹瑞诺德领主等首领，希望在他们威胁部落于洛丹伦尚未稳固的立足之地前，瓦解其指挥体系。"}},faq={{q="克鲁斯克是谁？",a="克鲁斯克是塔伦米尔的一名兽人斥候，为大酋长萨尔效力。他奉命调查敦霍尔德城堡周边辛迪加的活动，并找回历史遗物。",al={"克鲁斯克","克鲁斯克是谁","克鲁斯克 塔伦米尔"}},{q="克鲁斯克的小队遭遇了什么？",a="辛迪加在敦霍尔德城堡内伏击了克鲁斯克和他的小队。克鲁斯克成功脱身，德鲁尔和托格萨则被囚禁在废墟中，远征队的领队高迪尔被带到了辛迪加的另一处据点。",al={"克鲁斯克的小队","克鲁斯克遭遇了什么","敦霍尔德伏击"}},{q="部落为何关注敦霍尔德城堡？",a="部落关注敦霍尔德城堡，是因为这座城堡对大酋长萨尔而言，既有个人意义，也有历史意义。埃德拉斯·布莱克摩尔曾在那里将他作为被囚禁的角斗士养大，后来萨尔领导兽人起义，将城堡夷为平地。",al={"为何关注敦霍尔德","萨尔 敦霍尔德","敦霍尔德遗物"}},{q="在哪里可以找到克鲁斯克？",a="克鲁斯克就在塔伦米尔的户外，这座部落定居点位于希尔斯布莱德丘陵北部。",al={"克鲁斯克的位置","克鲁斯克在哪里"}}},fp="5,165,20.607.0,21.339.0,13.160.0,31.205.0,46.223.0,23.97.0"}
P.entries["npc:kuray-bin"] = {n="库莱比",s="库莱比监视着灰谷碎木岗哨外的林间小径。这名黑暗之矛斥候守卫着部落营地，防范暗夜精灵斥候。",h="库莱比监视着灰谷碎木岗哨外的林间小径。这名黑暗之矛斥候守卫着部落营地，防范暗夜精灵斥候。",kw={"灰谷先遣斥候","黑暗之矛","库莱比","银翼要塞","碎木岗哨"},ang={["faction:Horde"]="身为部落的一员，你能明白库莱比为何保持警戒：暗夜精灵游击队可能包围并攻陷碎木岗哨。",["race:Troll"]="身为巨魔，你和库莱比一样，拥有丛林追踪的本能，他正是凭借这种本能发现林间的暗夜精灵斥候。"},sec={{t="林缘的守望",b="在碎木岗哨外，库莱比监视着森林，提防联盟斥候。银翼要塞在树冠间巡逻，并派出行动迅捷的先遣斥候穿越边界。他们的任务是收集部落伐木作业和防御部署的情报。库莱比派遣部落战士猎杀这些先遣斥候，阻止他们返回银翼哨站报告，因为放任斥候活动，他们就可能集结成一支伏击部队。"}},faq={{q="库莱比是谁？",a="库莱比是一名黑暗之矛巨魔守望者，驻守在灰谷的碎木岗哨外。他派遣部落战士猎杀周围林地中的暗夜精灵斥候。",al={"库莱比","库莱比是谁","碎木岗哨巨魔斥候"}},{q="在哪里可以找到库莱比？",a="库莱比就站在灰谷中东部碎木岗哨的寨门外，监视着通往岗哨的道路。",al={"库莱比位置","库莱比在哪里"}},{q="库莱比为什么要杀死银翼信使？",a="银翼 信使是在碎木岗哨附近侦察的银翼要塞斥候。库莱比想要阻止他们，以免他们收集部落阵地的情报，或协调突袭行动。",al={"为什么杀死先遣斥候","灰谷先遣斥候任务背景"}},{q="库莱比还提供其他任务吗？",a="没有。库莱比在岗哨外围的职责是督导针对暗夜精灵先遣斥候的行动。",al={"库莱比任务","库莱比 任务"}}},fp="9,151,23.381.0,17.154.0,27.124.0,55.191.0,37.92.0"}
P.entries["npc:kzan-thornslash"] = {n="克赞·荆条",s="在试炼谷，克赞·荆条为部落新兵供应武器。他是杜隆塔尔的一名兽人商人。",h="在试炼谷，克赞·荆条为部落新兵供应武器。他是杜隆塔尔的一名兽人商人。",kw={"杜隆塔尔","部落","卡赞","兽人","刺斩","试炼谷","武器商","武器"},ang={["class:Warrior"]="作为一名拿着缺口刀刃起步的年轻战士，你可以从 Kzan 那里找到适合不同战斗技艺的钝器和利刃。",["faction:Horde"]="作为部落的一员，你可以看到，部落初建的军队从 Kzan 这样的商人那里起步，他们为每一双能战斗的手供应钢铁武器。"},sec={{t="新兵的武器商",b="克赞·荆条在试炼谷为年轻的兽人和黑暗之矛巨魔供应武器。他们正迈出成为部落战士的第一步。他出售基础的手斧、短剑、棍棒和法杖，供新兵应对当地的野兽和险境。"}},faq={{q="克赞·荆条是谁？",a="克赞·荆条是试炼谷的一名兽人商人。他为部落的新学员供应制式武器，供他们参加最初的战斗试炼。",al={"克赞·荆条","克赞 是谁","试炼谷武器商"}},{q="在哪里可以找到克赞·荆条？",a="你可以在大兽穴里找到克赞·荆条，那是杜隆塔尔西南部试炼谷中的一处洞穴。初出茅庐的冒险者和训练他们的导师都聚集在那里。",al={"克赞 位置","克赞·荆条在哪里","克赞·荆条地图"}},{q="克赞 出售什么装备？",a="克赞 为新兵出售基础武器，包括斧、剑、匕首、法杖和钝器。在新兵获得锻造或寻获的装备之前，这些铁制武器足以可靠地应付战斗。",al={"克赞 卖什么","克赞 物品","克赞 武器"}}},fp="15,136,23.251.0,23.164.0,33.159.0,38.164.0"}
P.entries["npc:lady-anacondra"] = {n="安娜科德拉",s="安娜科德拉是哀嚎洞穴中领导尖牙德鲁伊的毒牙之王之一。她曾是一名暗夜精灵德鲁伊，追随纳拉雷克斯，投身于他治愈贫瘠之地的宏大计划，却在导师与翡翠梦境的交融化为梦魇时迷失了自我。她的心智崩溃了，原本的忠诚也随之扭曲，变成了将这片土地改造成那场扭曲梦境的执念。",h="安娜科德拉是哀嚎洞穴中领导尖牙德鲁伊的毒牙之王之一。她曾是一名暗夜精灵德鲁伊，追随纳拉雷克斯，投身于他治愈贫瘠之地的宏大计划，却在导师与翡翠梦境的交融化为梦魇时迷失了自我。她的心智崩溃了，原本的忠诚也随之扭曲，变成了将这...",kw={"安娜科德拉","贫瘠之地","尖牙德鲁伊","安娜科德拉宝石","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊而言，安娜科德拉的悲剧是一个警示：这名真诚的学徒一心想要治愈大地，却因此给了梦魇可乘之机，使她与梦境的交融化为了疯狂。",["faction:Horde"]="部落不能容许安娜科德拉和毒牙之王威胁贫瘠之地脆弱的生命线，因此，除掉她对于保卫十字路口及附近的绿洲至关重要。",["race:NightElf"]="目睹一位拥有Kaldorei血统的姐妹，为追逐扭曲的蛇形梦境而抛弃自己的传承与形态，令人清醒地意识到翡翠梦境中潜藏的危险。"},sec={{t="从学徒到毒蛇",b="在采用这个蛇形头衔之前，安娜科德拉是纳拉雷克斯麾下的德鲁伊之一。当年长的德鲁伊纳拉雷克斯设想通过翡翠梦境引动贫瘠之地的地下泉水时，她追随他进入了洞穴。然而，她的忠诚最终毁了她。当纳拉雷克斯的心智被黑暗幻象占据时，梦魇从梦境领域渗出，污染了他的弟子，摧毁了她的理智，将她的冥想化作了冰冷的爬行动物般的执念。"},{t="深处的尖牙德鲁伊",b="如今，她自称安娜科德拉，守卫着哀嚎洞穴入口附近的地下洞室。和其他毒牙之王一样，她抛弃了塞纳里奥议会的传统教义，转而崇尚毒蛇的凶残本性。她运用闪电、自然魔法和催眠法术，维持着纳拉雷克斯那扭曲的沉眠，并试图将梦魇的腐化扩散到上方干旱的土地。"}},faq={{q="安娜科德拉原本是什么人？",a="她原本是一名追随纳拉雷克斯、致力于治愈贫瘠之地的暗夜精灵德鲁伊，那时他的梦魇还未腐化他的弟子。",al={"安娜科德拉真名"}},{q="她为何背离塞纳里奥议会？",a="当纳拉雷克斯试图在贫瘠之地地下与翡翠梦境建立联系时，他的心智被梦魇吞噬。同一场梦魇侵入了他那些学徒的心灵，腐化了她，驱使她为扭曲的梦境效力。",al={"安娜科德拉为何堕落","她如何成为尖牙德鲁伊成员"}},{q="她在哀嚎洞穴中扮演什么角色？",a="她是领导尖牙德鲁伊的四名毒牙之王之一。她守卫着洞穴的上层，确保纳拉雷克斯继续困在被腐化的沉眠之中，而尖牙德鲁伊则试图将这片土地改造成他们那扭曲梦境的模样。",al={"安娜科德拉做什么","安娜科德拉的目的","为何杀死安娜科德拉"}},{q="在洞穴中的什么地方能找到她？",a="安娜科德拉在哀嚎洞穴入口附近的第一片大型洞穴群中游荡。她在洞中的迅猛龙和毒蛇之间巡逻，时常在几处歇脚点之间移动。",al={"安娜科德拉位置","安娜科德拉在哪里","安娜科德拉刷新"}},{q="要为塞纳里奥议会从她身上取得什么物品？",a="她携带着安娜科德拉宝石。雷霆崖的德鲁伊纳拉·蛮鬃要求杀死她并取得宝石，以打破毒牙之王对贫瘠之地的控制。",al={"安娜科德拉宝石","尖牙首领安娜科德拉","安娜科德拉任务物品"}},{q="她在战斗中使用什么力量？",a="她运用自然魔法，以灼人的闪电从远处打击敌人，并施放催眠魔法使入侵者失去行动能力，让她的爬行动物盟友发起攻击。",al={"安娜科德拉技能","安娜科德拉法术","安娜科德拉攻击"}}},fx={["1a1ef870"]={q="安娜科德拉效忠于哪一方？",a="安娜科德拉与尖牙德鲁伊站在一起，早已背弃了对塞纳里奥议会的忠诚。她的主人纳拉雷克斯被笼罩其身的翡翠梦魇腐化后，她也随之堕落，如今反抗昔日同胞，守护着哀嚎洞穴中滋长的疯狂。",al={"安娜科德拉的阵营","安娜科德拉效忠于谁","安娜科德拉的忠诚对象"}},ec4c22d8={q="安娜科德拉想要什么？",a="安娜科德拉的心智也遭到腐化，她想要重塑这片土地，让它符合尖牙德鲁伊扭曲的梦境。她守护着哀嚎洞穴中滋长的梦魇，并与其他尖牙领主一同将其传播开来。",al={"安娜科德拉想做什么","安娜科德拉的目标","安娜科德拉的动机"}},f4df78aa={q="安娜科德拉为何在此？",a="她曾是追随暗夜精灵德鲁伊纳拉雷克斯的德鲁伊之一，陪他执行恢复贫瘠之地的任务。她随他进入哀嚎洞穴，探寻地下泉水，却在他的梦境变成梦魇后被困于此，并遭到扭曲。",al={"安娜科德拉为何在哀嚎洞穴","安娜科德拉如何来到这里","安娜科德拉在贫瘠之地的任务"}},["6f9b72fe"]={q="安娜科德拉与谁有联系？",a="安娜科德拉与纳拉雷克斯关系密切。在梦魇摧毁她的心智之前，她曾是这位强大德鲁伊的侍僧。她也与其他尖牙领主——例如科布拉恩和瑟芬迪斯——结为一体，与他们一同统治着扭曲的尖牙德鲁伊教派。",al={"安娜科德拉的主人是谁","安娜科德拉与纳拉雷克斯的关系","谁领导安娜科德拉"}}},fp="14,288,24.302.0,22.347.0,34.136.0,45.182.0,40.227.0,42.176.0,52.148.0,37.173.0"}
P.entries["npc:lady-sarevess"] = {n="萨利维丝",s="在黑暗深渊，萨利维丝在被水淹没的废墟中施展黑暗法术。",h="在黑暗深渊，萨利维丝在被水淹没的废墟中施展黑暗法术。",kw={"阿库麦尔","黑暗深渊","萨利维丝","纳迦","阿斯卡之池","海巫","暮光之锤"},ang={["class:Mage"]="身为法师，你可以看出，历经数百年的海洋腐化，highborne的魔法技艺如何变成了狂暴混乱的闪电与潮汐巫术。",["race:NightElf"]="身为暗夜精灵，萨利维丝盘踞的废墟曾是一座供奉Elune的神圣殿堂。她那些扭曲的纳迦同族玷污着Ask'ar的水域，令人想起Sundering。"},sec={{t="深渊中的洞窟",b="萨利维丝在Pool of Ask'ar内一处被水淹没的洞窟中举行仪式。暮光之锤的教徒也盘踞在这座沉没的神庙中，在洞穴更深处进行他们自己的崇拜活动。"},{t="潮汐巫术",b="萨利维丝掌控着元素水流与噼啪作响的闪电。忠诚的纳迦哨兵和召唤而来的水元素守护着她的圣所，而她则与威胁其黑暗行径的入侵者交战。"}},faq={{q="萨利维丝是谁？",a="萨利维丝栖身于黑暗深渊内部的地下水池阿斯卡之池。这位极度扭曲的纳迦施法者涉足黑暗魔法。",al={"萨利维丝是谁","萨利维丝背景","萨利维丝身世"}},{q="在哪里能找到萨利维丝？",a="萨利维丝的巢穴位于阿斯卡之池，那是灰谷海岸沿线黑暗深渊神庙建筑群前段的一间被水淹没的厅室。",al={"萨利维丝位置","萨利维丝在哪里","阿斯卡之池"}},{q="萨利维丝掌控着哪些力量？",a="萨利维丝运用水与元素魔法，包括猛烈迸发的叉状闪电，攻击任何踏入她那片水湾的人。",al={"萨利维丝魔法","萨利维丝技能"}}},fp="13,81,21.193.0,20.187.0,21.134.0,33.157.0,39.143.0"}
P.entries["npc:laird"] = {n="莱尔德",s="在奥伯丁的旅店里，莱尔德向沿黑海岸海滨往来的旅人出售鱼类和烹饪用品。",h="在奥伯丁的旅店里，莱尔德向沿黑海岸海滨往来的旅人出售鱼类和烹饪用品。",kw={"奥伯丁","黑海岸","狂鱼肉片","鱼商","莱尔德","尼莎·影歌"},ang={["profession:Cooking"]="如果你为了学习烹饪而途经黑海岸，莱尔德会教你如何将卡利姆多水域中凶猛的狂鱼切片并烹制。",["race:NightElf"]="身为暗夜精灵，莱尔德展现了你的同胞如何沿卡利姆多大陆海岸开展贸易，并支持日益发展的沿海贸易网络。"},sec={{t="港口商人",b="莱尔德在奥伯丁的旅店里出售鱼类和补给品。水手、当地居民和旅人都会来找他，而黑海岸的水域危机四伏，远比泰达希尔避风的近岸水域危险。对愿意在雾气笼罩的海滩上抛竿的钓鱼者来说，当地的渔获能带来丰厚的收益。"},{t="海峡两岸的往来",b="莱尔德与海峡对岸泰达希尔的渔业保持着联系。他的渔人同伴尼莎·影歌运来货物，将鲁瑟兰村与大陆港口连在一起，让沿海贸易持续运转。"}},faq={{q="在哪里可以找到莱尔德？",a="莱尔德就在奥伯丁旅店的一楼。奥伯丁是联盟在黑海岸沿岸的主要定居点。",al={"莱尔德位置","莱尔德在哪","莱尔德奥伯丁"}},{q="莱尔德出售什么？",a="莱尔德出售捕获的鱼类、烹饪食材，以及制作狂鱼肉片的烹饪指南。",al={"莱尔德商人","莱尔德卖什么","莱尔德货物"}},{q="哪些任务与莱尔德有关？",a="莱尔德会收到来自鲁瑟兰村的尼莎·影歌送来的货物。随后，他会请冒险者渡海捎回口信。",al={"莱尔德任务","奥伯丁鱼类任务"}},{q="莱尔德为什么认为在黑海岸钓鱼值得冒险？",a="尽管黑海岸雾气笼罩的海滨比泰达希尔宁静的水域更加危险，但这里丰富而奇异的海洋生物能让敢于开拓的渔人获得更丰厚的收益。",al={"莱尔德闲聊","黑海岸适合钓鱼吗"}}},fp="5,95,17.294.0,21.222.0,23.114.0,21.99.0,26.130.0,72.176.0"}
P.entries["npc:lakota-windsong"] = {n="拉克塔·风歌",s="拉克塔·风歌是一名年轻的牛头人，被囚禁在千针石林黑云峰的崖顶。她拒绝了阿纳克·恐怖图腾的求婚，随后遭他强行掳走，如今正等待有人将她从恐怖图腾部族的魔爪中救出。",h="拉克塔·风歌是一名年轻的牛头人，被囚禁在千针石林黑云峰的崖顶。她拒绝了阿纳克·恐怖图腾的求婚，随后遭他强行掳走，如今正等待有人将她从恐怖图腾部族的魔爪中救出。",kw={"阿纳克·恐怖图腾","黑云峰","终于自由","乱风岗","拉克塔·风歌","萨利亚","千针石林"},ang={["faction:Horde"]="救出拉克塔能够打击恐怖图腾对千针石林的控制，并保障在乱风岗歇脚的旅人安全通行。",["race:Tauren"]="拉克塔的遭遇鲜明地揭示了恐怖图腾内部滋生的背叛行径，他们对凯恩·血蹄领导权的反抗时常演变为暴力。"},sec={{t="致命的求婚",b="第三次大战结束后不久，阿纳克·恐怖图腾开始追求拉克塔·风歌。她既不愿加入他的氏族，也不愿接受他的追求，于是拒绝了他的求婚。阿纳克不肯接受她的拒绝；他趁夜返回，杀死了试图阻拦他的拉克塔的兄弟，并将她掳往千针石林嶙峋的高崖。她被囚禁在远高于谷底的黑云峰，至今仍受重兵看守，而阿纳克依然执意要她做自己的新娘。"},{t="下山脱险",b="拉克塔被阴险的恐怖图腾匪徒包围，无法独自杀出一条下山的路。只有勇敢的护送者才能带她穿过吊桥，沿着蜿蜒的小径下到谷底。一旦逃离黑云峰，拉克塔便会奔向安全的乱风岗，将自己获救的消息带给萨利亚和驻守在那里的守卫。"}},faq={{q="拉克塔·风歌为何被囚禁在黑云峰？",a="她拒绝了阿纳克·恐怖图腾的求婚。阿纳克不肯接受她的拒绝，杀害了她的兄弟，并将拉克塔掳走，拖到恐怖图腾在黑云峰的据点，企图逼她就范。",al={"拉克塔为何被俘","谁绑架了拉克塔","拉克塔为何在黑云峰"}},{q="拉克塔获救后会去哪里？",a="安全抵达黑云峰脚下后，拉克塔便会前往乱风岗，在部落守卫的庇护下避难，并向萨利亚讲述自己的遭遇。",al={"拉克塔逃往哪里","护送后她去哪里","拉克塔的目的地"}},{q="阿纳克·恐怖图腾是谁？",a="阿纳克是阴险的恐怖图腾氏族中一名凶暴的战士。拉克塔拒绝嫁给他后，他便杀害了她的兄弟，并将她掳走。",al={"阿纳克 是谁","谁绑架了她","阿纳克 的故事"}}},fx={e2861ac8={q="拉克塔·风歌是谁？",a="拉克塔·风歌是一名被囚禁在黑云峰顶的女性牛头人。阿纳克·恐怖图腾向她求婚时，拉克塔拒绝了他。阿纳克因遭到拒绝而勃然大怒，杀害了她的兄弟，并将她掳到千针石林的恐怖图腾据点，企图强迫她成婚。",al={"拉克塔·风歌是谁","拉克塔是谁","拉克塔的身份"}},["412850e2"]={q="拉克塔·风歌效忠于哪一方？",a="拉克塔与部落中爱好和平的牛头人站在一起，并指望乱风岗的勇士保护自己。她对恐怖图腾氏族深怀仇恨，因为他们残忍地杀害了她的兄弟并绑架了她。",al={"拉克塔·风歌的阵营","拉克塔属于部落吗","拉克塔的效忠对象"}},["2c16a924"]={q="拉克塔·风歌想要什么？",a="拉克塔只想逃离黑云峰，远离恐怖图腾强盗，抵达安全之处。她的兄弟为保护她而丧命，如今她只能指望有人勇敢地突破看守，护送她沿着蜿蜒小路安全抵达乱风岗。",al={"拉克塔·风歌的目标","拉克塔需要什么","拉克塔的愿望"}},["3261173c"]={q="拉克塔·风歌与谁有联系？",a="拉克塔的兄弟曾拼死保护她，却在试图抵挡阿纳克·恐怖图腾时丧命。她也信任萨利亚和驻守乱风岗的守卫。",al={"拉克塔的家人","拉克塔的关系","拉克塔与谁有亲属关系"}}},fp="15,124,18.450.0,17.328.1,56.187.0,41.178.1,23.147.0"}
P.entries["npc:lanka-farshot"] = {n="兰卡·远箭",s="在纳拉其营地，兰卡·远箭引导年轻的牛头人踏上猎人之路。他驻守在红云台地，传授在莫高雷平原上追踪、射击和生存的技巧。",h="在纳拉其营地，兰卡·远箭引导年轻的牛头人踏上猎人之路。他驻守在红云台地，传授在莫高雷平原上追踪、射击和生存的技巧。",kw={"纳拉其营地","猎人训练师","兰卡·远箭","莫高雷","红云台地","牛头人猎人"},ang={["class:Hunter"]="作为一名在莫高雷开始训练的牛头人猎人，你遇到的第一位导师就是兰卡·远箭。他教你射击技巧和野外生存之道。",["race:Tauren"]="作为牛头人，你会看到兰卡·远箭教导猎人，将狩猎视为保护部族、与平原和谐共处的职责。"},sec={{t="红云台地的导师",b="在纳拉其营地，兰卡·远箭迎接响应召唤、踏上猎人之路的牛头人新兵。新兵们带着风化便笺前来，依照便笺的指引向他求教。在他的指导下，他们学习远程作战、追踪猎物，并尊重漫游在莫高雷草原上的野兽。他教导每一位年轻猎人，让他们能够为部族侦察和获取补给。"}},faq={{q="兰卡·远箭是谁？",a="兰卡·远箭在莫高雷红云台地的纳拉其营地训练牛头人猎人。他引导年轻猎人开始接受训练。",al={"兰卡是谁","兰卡·远箭非玩家角色","纳拉其营地猎人"}},{q="兰卡·远箭提供哪些任务？",a="年轻的牛头人猎人抵达纳拉其营地时，风化便笺会指引他们去寻找兰卡·远箭。他引导他们初步掌握猎人的技艺。",al={"兰卡·远箭任务","纳拉其营地猎人任务"}},{q="兰卡·远箭与米希·法索有亲属关系吗？",a="仅凭相同的姓氏，无法证明兰卡·远箭与地精米希·法索有亲属关系。",al={"兰卡与米希有亲属关系吗","米希·法索亲属关系"}}},fp="13,147,28.351.0,21.139.0,37.158.0,42.95.0"}
P.entries["npc:lar-prowltusk"] = {n="拉尔·猎齿",s="在森金村西南方，拉尔·猎齿守望着杜隆塔尔的边境。他守护着这座新建的巨魔定居点，并派遣旅者对付附近的威胁。",h="在森金村西南方，拉尔·猎齿守望着杜隆塔尔的边境。他守护着这座新建的巨魔定居点，并派遣旅者对付附近的威胁。",kw={"黑暗之矛","杜隆塔尔","科卡尔","拉尔·猎齿","北方城堡","森金村","巨魔"},ang={["faction:Horde"]="作为部落的一员，你与拉尔·猎齿并肩奋战，对抗你们新建都城附近的威胁，保卫杜隆塔尔的边境。",["race:Troll"]="作为黑暗之矛巨魔，你依靠拉尔·猎齿这样的斥候，守护部族在杜隆塔尔尚不稳固的新家园，抵御好战的半人马氏族和步步进逼的人类军队。"},sec={{t="海岸守望者",b="拉尔·猎齿守望着森金村西南方的海岸。作为黑暗之矛的哨兵，他协助守护部族的新家园，他的族人逃离沉没的群岛后便在此落脚。巨魔们努力建立永久家园之时，周围的敌对势力仍不断袭扰森金村。拉尔指派斥候和战士监视海岸，遏制这些袭击，尤其是科卡尔半人马的进犯，为定居点争取喘息之机。"}},faq={{q="拉尔·猎齿是谁？",a="拉尔·猎齿是一名黑暗之矛巨魔哨兵，驻守在杜隆塔尔的森金村西南方。他招募部落旅者，在周边的威胁抵达村庄前出击，以此守护定居点的外围。",al={"拉尔·猎齿","拉尔·猎齿是谁","拉尔·猎齿 杜隆塔尔"}},{q="拉尔·猎齿主要关注哪些威胁？",a="拉尔警戒着杜隆塔尔边境的危险，尤其是侵入巨魔领地、四处劫掠的科卡尔半人马群。",al={"拉尔·猎齿任务","拉尔·猎齿想要什么"}},{q="在哪里可以找到拉尔·猎齿？",a="拉尔在杜隆塔尔南部、森金村西南方的小径沿线守望。",al={"拉尔·猎齿位置","拉尔·猎齿在哪里"}}},fp="13,161,20.432.0,21.169.0,41.124.0,33.91.0"}
P.entries["npc:laris-geardawdle"] = {n="拉里斯·空轮",s="在铁炉堡的探险者大厅，拉里斯·空轮用有毒的软泥样本迎接旅人。这位侏儒研究员将毕生学术精力投入到研究艾泽拉斯各地的软泥怪，以及它们奇异的特性与起源。",h="在铁炉堡的探险者大厅，拉里斯·空轮用有毒的软泥样本迎接旅人。这位侏儒研究员将毕生学术精力投入到研究艾泽拉斯各地的软泥怪，以及它们奇异的特性与起源。",kw={"侏儒","探险者大厅","铁炉堡","拉里斯·空轮","图书馆","软泥怪","软泥"},ang={["faction:Alliance"]="身为联盟的一员，你可以在探险者大厅找到拉里斯·空轮。他的工作为League挖掘历史的事业带来了古怪的自然科学研究。",["race:Gnome"]="身为侏儒，你和拉里斯·空轮一样，渴望在旁人忽视的地方探寻知识。有时，这意味着要把手伸进恶臭的沼泽淤泥。"},sec={{t="软泥学者",b="在探险者大厅的图书馆里，拉里斯·空轮研究着软泥怪如何诞生。他的矮人同僚埋首钻研泰坦石板和古老的石刻。拉里斯则从艾泽拉斯那些污秽、胶状的恐怖生物身上，探寻炼金术与生物学的秘密。\n\n他请四处游历的探险者到世界的偏远角落采集腐蚀性样本。他用这些样本检验自己独特的想法，试图弄清这些毫无心智、满怀恶意的泥浆是如何获得生命的。"}},faq={{q="拉里斯·空轮是谁？",a="拉里斯·空轮是铁炉堡探险者大厅图书馆里的一位侏儒研究员。他研究软泥怪与软泥，以及它们奇异的诞生方式。",al={"拉里斯","空轮","拉里斯是谁"}},{q="在哪里可以找到拉里斯·空轮？",a="你可以在铁炉堡北部的探险者大厅及其图书馆内找到拉里斯·空轮。",al={"拉里斯位置","拉里斯在哪","寻找拉里斯·空轮"}},{q="他为什么研究软泥怪？",a="拉里斯·空轮研究软泥怪，是因为他那充满好奇又古怪的头脑，让他对活体软泥的诞生提出了种种理论。他相信，不同软泥怪留下的腐蚀性残渣，能够解释这些奇异生物如何形成与繁殖。",al={"为什么研究软泥怪","拉里斯软泥研究","软泥怪研究"}},{q="他会交给冒险者什么任务？",a="拉里斯·空轮请旅人前往危险的土地采集软泥怪样本。在远方的软泥怪中，他给旅人空的软泥怪采样容器，派他们前往费伍德森林，从被他们杀死的软泥怪身上采集样本。随后，他又请他们寻找纯净、未受腐化的样本。",al={"拉里斯任务","远方的软泥怪"}}},fx={a960bc4a={q="拉里斯·空轮效忠哪一方？",a="拉里斯·空轮坚定地支持联盟和诺莫瑞根流亡者。他在铁炉堡的探险者大厅与矮人学者和研究人员共事，凭借敏锐的头脑和古怪的生物学理论，增进联盟对世界各地奇异现象的认识与理解。",al={"拉里斯·空轮阵营","拉里斯·空轮 联盟","拉里斯·空轮是否友善"}},["114e8ed2"]={q="拉里斯·空轮为什么在铁炉堡？",a="诺莫瑞根沦陷后，许多侏儒前往铁炉堡，在矮人盟友那里寻求庇护。拉里斯·空轮在探险者大厅内的图书馆安了家，这里是理想的避难所，他可以充分查阅丰富的历史和自然档案，继续开展古怪的学术研究，并整理自己关于软泥怪起源的理论。",al={"拉里斯·空轮为何在这里","拉里斯·空轮 探险者大厅","拉里斯为何在铁炉堡"}}},fp="16,216,16.429.0,24.151.0,34.105.0,25.235.0,37.263.0"}
P.entries["npc:lars"] = {n="拉尔斯",s="在寂静河岸北缘的一处营地里，拉尔斯与斯温·约根在暮色森林中艰难求生。周围的林地里潜伏着野兽、亡灵和狼人。",h="在寂静河岸北缘的一处营地里，拉尔斯与斯温·约根在暮色森林中艰难求生。周围的林地里潜伏着野兽、亡灵和狼人。",kw={"营地","暮色森林","寂静河岸","拉尔斯","斯温·约根","狼群","恶狼成群"},ang={["faction:Alliance"]="身为联盟的勇士，你可以驱赶在营地周围徘徊的狼群，帮助拉尔斯这位身处城镇卫兵保护范围之外的人类平民。"},sec={{t="岌岌可危的栖身处",b="拉尔斯住在寂静河岸北缘的一处小营地里，远离夜色镇那难以保障的安全。暮色森林危机四伏，周围的林地里潜伏着凶猛的野兽、亡灵和狼人。他与斯温·约根相依为伴，努力在这片险恶的森林中生存。"},{t="荒野中的威胁",b="饥肠辘辘的恐狼在拉尔斯和斯温的营地周围游荡。拉尔斯独自一人无法兼顾警戒和驱赶狼群，只能依靠旅人削减狼群的数量，以免这些掠食者攻陷营地。"}},faq={{q="拉尔斯是谁？",a="拉尔斯是一名人类幸存者，与同伴斯温·约根在暮色森林扎营。他们在寂静河岸北缘艰难求生，抵御森林中的种种危险。",al={"拉尔斯 暮色森林","拉尔斯是谁","拉尔斯 非玩家角色"}},{q="在哪里可以找到拉尔斯？",a="拉尔斯住在暮色森林西部、寂静河岸北缘的一处小营地里。",al={"拉尔斯在哪里","拉尔斯位置","拉尔斯营地"}},{q="拉尔斯面临什么难题？",a="饥饿的恐狼和其他掠食者威胁着拉尔斯与斯温的营地。拉尔斯请求过路的旅人在狼群攻陷营地之前猎杀它们。",al={"拉尔斯任务","恶狼成群 任务","拉尔斯为何需要帮助"}},{q="拉尔斯与斯温·约根是什么关系？",a="拉尔斯与斯温·约根是一起在荒野中求生的同伴。斯温有着一段黑暗的过往，并在这一带寻求复仇，而拉尔斯则帮忙维持着他们那孤立无援的营地。",al={"拉尔斯与斯温","斯温与拉尔斯的关系"}}},fp="4,162,18.252.0,21.186.0,12.161.0,24.87.0,28.140.0,43.176.0"}
P.entries["npc:laurna-morninglight"] = {n="劳尔娜·晨光",s="在多兰纳尔，劳尔娜·晨光向年轻的暗夜精灵牧师传授Elune的仪式。她忠于Sisterhood of Elune，在威胁逐渐笼罩泰达希尔之际，指导来自幽影谷的学徒学习治疗与精神修行。",h="在多兰纳尔，劳尔娜·晨光向年轻的暗夜精灵牧师传授Elune的仪式。她忠于Sisterhood of Elune，在威胁逐渐笼罩泰达希尔之际，指导来自幽影谷的学徒学习治疗与精神修行。",kw={"多兰纳尔","艾露恩","卡多雷","劳尔娜","晨光","牧师训练师","艾露恩姐妹会","泰达希尔"},ang={["class:Priest"]="作为一名从幽影谷而来的暗夜精灵牧师，你可以向劳尔娜·晨光学习基础法术，并在她的指引下虔诚侍奉Elune。",["race:NightElf"]="作为暗夜精灵，你秉承着kaldorei对月亮女神的信仰。在泰达希尔，牧师之力源自Elune，而非圣光。"},sec={{t="多兰纳尔的引路人",b="在多兰纳尔，劳尔娜·晨光指引着来自幽影谷的年轻牧师。当新入门的学徒深入泰达希尔时，她教导他们加深与Elune的联系。她的课程将治疗与防御仪式相结合，这些都是在日益险恶的荒野中必需的本领。"},{t="对月亮女神的虔诚",b="在卡多雷之中，牧师之道遵循艾露恩，而非人类与矮人所崇敬的圣光。劳尔娜派学生们去领取神圣的长袍，并治疗一名受伤的哨兵。通过这些仪式，学徒们明白了月神赐予他们力量，是为了守护和治愈卡多雷同胞。"}},faq={{q="在哪里可以找到劳尔娜·晨光？",a="劳尔娜·晨光位于泰达希尔中部的多兰纳尔，从幽影谷沿路走不远便能找到她。",al={"劳尔娜位置","劳尔娜在哪里","多兰纳尔牧师训练师"}},{q="劳尔娜·晨光做什么？",a="劳尔娜·晨光训练暗夜精灵牧师。她传授新的法术，提升他们已有的能力，并引导他们完成早期的职业仪式。",al={"她做什么","劳尔娜职责","劳尔娜牧师训练师"}},{q="她提供什么样的任务？",a="劳尔娜·晨光派初出茅庐的牧师去帮助受伤的盟友，并通过仪式法衣与祈祷寻求艾露恩的眷顾。",al={"劳尔娜任务","多兰纳尔牧师任务"}},{q="她也训练其他种族吗？",a="劳尔娜·晨光传承着艾露恩姐妹会的教诲，而联盟的牧师训练师会教导任何寻求精神修行的盟友牧师。",al={"人类能在这里受训吗","牧师训练师所有种族"}},{q="她与月神殿有关联吗？",a="是的。劳尔娜·晨光的誓言与魔法都奉献给了艾露恩，以及达纳苏斯的月神殿所守护的传统。",al={"她属于艾露恩姐妹会吗","劳尔娜月神殿"}},{q="她与其他暗夜精灵有相同的姓氏吗？",a="在泰达希尔的卡多雷之中，没有已知的劳尔娜·晨光的亲属。",al={"晨光家族","劳尔娜亲属"}}},fp="19,191,19.261.0,28.285.0,37.96.0,33.150.0,35.130.0,27.139.0,46.130.0,52.79.0"}
P.entries["npc:lelanai"] = {n="莱兰奈",s="在达纳苏斯，莱兰奈在塞纳里奥区照料暗夜精灵的刃豹坐骑。她向同胞和这座城市信赖的盟友提供夜刃豹和迅捷的战兽。",h="在达纳苏斯，莱兰奈在塞纳里奥区照料暗夜精灵的刃豹坐骑。她向同胞和这座城市信赖的盟友提供夜刃豹和迅捷的战兽。",kw={"塞纳里奥区","达纳苏斯","霜刃豹","贾萨姆","莱兰奈","坐骑商人","夜刃豹"},ang={["faction:Alliance"]="作为联盟英雄，你可以将达纳苏斯的声望提升至崇拜，再向莱兰奈求购刃豹，与kaldorei盟友并肩驰骋。",["race:NightElf"]="作为暗夜精灵，当你准备好驾驭族人传统的猫科坐骑时，就可以去找莱兰奈。"},sec={{t="塞纳里奥区的饲养员",b="莱兰奈在塞纳里奥区照料卡利姆多的大型猫科猛兽，身旁就是骑术训练师贾萨姆。暗夜精灵与北方森林中这些凶猛的掠食者结缘已久。他们训练夜刃豹和霜刃豹，让它们载着哨兵和斥候，以掠食者的矫健身姿穿越崎岖地形。在首都，莱兰奈为骑手们提供这些坐骑。"},{t="超越同族的羁绊",b="莱兰奈向掌握相应骑术的暗夜精灵提供刃豹坐骑，而外族人则面临更高的门槛。这些猫科猛兽被卡多雷视为神圣之物，对陌生人保持着距离。只有在达纳苏斯赢得最高敬意与声望的非暗夜精灵，才能获得她托付的坐骑。"}},faq={{q="在哪里能找到莱兰奈？",a="莱兰奈位于达纳苏斯的塞纳里奥区，就在豹骑术训练师贾萨姆身旁。",al={"莱兰奈位置","莱兰奈在哪里","莱兰奈地图"}},{q="莱兰奈出售什么？",a="莱兰奈出售多个品种的霜刃豹和夜刃豹的缰绳，其中包括供老练骑手驾驭的迅捷披甲坐骑。",al={"莱兰奈的商品","她有哪些坐骑","暗夜精灵坐骑"}},{q="非暗夜精灵能向莱兰奈购买坐骑吗？",a="可以。非暗夜精灵在达纳苏斯的声望达到崇拜后，就能向莱兰奈购买坐骑。声望未达崇拜时，她会拒绝出售坐骑。",al={"人类能买刃豹吗","矮人能骑夜刃豹吗","刃豹所需声望"}},{q="部落玩家能与莱兰奈互动吗？",a="不能。莱兰奈身在达纳苏斯，效忠于联盟。她和附近的塞纳里奥区守卫都将部落成员视为敌对的入侵者。",al={"部落能买刃豹吗","莱兰奈对部落友好吗"}}},fp="7,132,31.349.0,20.273.0,25.87.0,23.119.0,44.147.0,40.125.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="法尔林·奥里涅尔中尉",s="在南海镇的旅店里，法尔林·奥里涅尔中尉喝着酒，把职责推给别人。他对驻守希尔斯布莱德丘陵心怀不满，盼着调往南方。治安官雷德帕斯派他处理沿岸的鱼人。",h="在南海镇的旅店里，法尔林·奥里涅尔中尉喝着酒，把职责推给别人。他对驻守希尔斯布莱德丘陵心怀不满，盼着调往南方。治安官雷德帕斯派他处理沿岸的鱼人。",kw={"法尔林","希尔斯布莱德","治安官雷德帕斯","鱼人","奥里涅尔","调任","南海镇","暴风城"},ang={["faction:Alliance"]="在联盟勇士眼中，奥里涅尔是一名满腹牢骚的南方士兵，驻守在北方一处孤零零的哨站，愿意给任何替他履行职责的人钱币和嘉奖。",["race:Human"]="奥里涅尔是一名远离艾尔文森林的暴风城士兵。他对北方边境驻防任务的厌恶，显露出舒适的都城生活与艰苦的海外驻防之间的鸿沟。"},sec={{t="流放南海镇",b="法尔林·奥里涅尔中尉整日待在南海镇的旅店里，远离他心仪的暴风城。他从暴风城被派往北方，却觉得希尔斯布莱德这片争夺不休的海岸并不适合自己。他不去田野间巡逻，也不与治安官雷德帕斯协调防务，只顾喝酒、抱怨，等着一纸调往南方的命令。"},{t="将职责推给他人",b="治安官雷德帕斯命法尔林·奥里涅尔中尉清剿附近海岸的鱼人。奥里涅尔把泥泞海岸上的差事交给过往的旅人，请他们杀死这些生物，并带回凭证。他希望这些成果能让上级满意，早日让他返回暴风城。"}},faq={{q="法尔林·奥里涅尔中尉是谁？",a="法尔林·奥里涅尔中尉是一名暴风城军官，驻扎在希尔斯布莱德丘陵的南海镇。他在旅店里喝酒，抱怨自己的驻防差事。",al={"法尔林·奥里涅尔","奥里涅尔是谁","南海镇中尉"}},{q="他为什么会在南海镇？",a="他从暴风城被调往北方，支援治安官雷德帕斯和当地驻军。奥里涅尔不喜欢这份差事，想要回家。",al={"法尔林为何在南海镇","奥里涅尔调动"}},{q="他的正式职责是什么？",a="治安官雷德帕斯命令奥里涅尔处理希尔斯布莱德沿岸的敌对鱼人。奥里涅尔更愿意花钱雇旅人去对付它们。",al={"法尔林职责","奥里涅尔任务","法尔林鱼人"}},{q="他会离开南海镇的旅店吗？",a="奥里涅尔几乎把所有时间都花在南海镇的旅店里，不愿面对外面泥泞的海滩和恶劣的天气。",al={"哪里能找到法尔林","法尔林位置","奥里涅尔旅店"}},{q="法尔林最终想要什么？",a="奥里涅尔想得到正式调令，返回暴风城，远离洛丹伦的海岸。",al={"法尔林想要什么","调任"}},{q="奥里涅尔的指挥官是谁？",a="奥里涅尔听命于治安官雷德帕斯，后者指挥着保卫南海镇的联盟分遣队。",al={"法尔林上级","法尔林长官","谁指挥法尔林"}}},fp="26,178,19.324.0,16.289.0,34.155.0,24.138.0,32.143.0,38.121.0,31.87.0,28.95.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="哈格丁中尉",s="哈格丁中尉是一名矮人军官，驻守在奥特兰克山脉的山头。他在通往奥特兰克山谷的坚固大门外站岗，是雷矛卫队的主要征募官和联络官。他考验胸怀壮志的联盟勇士，并奖赏那些在对抗霜狼氏族时证明了自身英勇的人。",h="哈格丁中尉是一名矮人军官，驻守在奥特兰克山脉的山头。他在通往奥特兰克山谷的坚固大门外站岗，是雷矛卫队的主要征募官和联络官。他考验胸怀壮志的联盟勇士，并奖赏那些在对抗霜狼氏族时证明了自身英勇的人。",kw={"奥特兰克","矮人","霜狼","哈格丁","海岬","铁炉堡","中尉","实验场","雷矛"},ang={["faction:Alliance"]="哈格丁中尉是你在奥特兰克山谷外的主要联络人，负责颁发你在与霜狼氏族交战中赢得的资历凭证和正式荣誉。",["faction:Horde"]="哈格丁是一名坚定的哨兵，守卫着联盟通往奥特兰克山谷的传送门，并指挥派去击溃霜狼兽人的援军。",["race:Dwarf"]="哈格丁是雷矛氏族一位自豪的军官，他体现了铁炉堡在奥特兰克白雪覆盖的峭壁间探寻自身泰坦传承的坚定决心。"},sec={{t="山头的守门人",b="哈格丁中尉驻守在希尔斯布莱德丘陵上方、白雪覆盖的山头高地，负责管理联盟持续征战奥特兰克山谷的集结点。矮人的旗帜在巨大的木门旁飘扬，新兵与老兵在他警惕的目光下集结，准备奔赴严寒的战场。"},{t="雷矛卫队的代言人",b="哈格丁为雷矛探险队效力，确保只有经过考验的战士才能代表铁炉堡和大联盟在山谷中作战。他通过实验场等考验，派遣新兵找回旗帜和遗物，并在士兵于雷矛卫队中逐步晋升时，授予正式嘉奖、徽记和军衔。"}},faq={{q="哈格丁中尉是谁？",a="哈格丁中尉是一名代表雷矛卫队的矮人军官。他驻守在奥特兰克山脉山头的奥特兰克山谷入口，负责联盟的征募事务，并为战场上的功勋颁发奖赏。",al={"哈格丁","哈格丁是谁","哈格丁中尉 奥特兰克"}},{q="在哪里可以找到哈格丁中尉？",a="他位于奥特兰克山脉北部的山头，就站在直通奥特兰克山谷的传送门和大门外。",al={"哈格丁位置","哈格丁中尉在哪里","奥特兰克山谷联盟入口"}},{q="哈格丁在雷矛卫队中担任什么职务？",a="他担任战地联络官和军需官，负责实验场等征募试炼，并随着联盟战士在雷矛卫队中的声望提升，授予他们更高的军衔和徽记。",al={"哈格丁职责","哈格丁任务","雷矛卫队军官"}},{q="联盟为何在奥特兰克山谷作战？",a="雷矛探险队进入山谷，意在发掘古代遗物与矮人的历史，但他们的到来引发了与当地霜狼兽人及其部落盟友之间激烈的领土冲突。",al={"为何征战奥特兰克山谷","雷矛探险队目标","奥特兰克冲突"}},{q="部落玩家能与哈格丁中尉互动吗？",a="不能。哈格丁中尉是一名现役联盟军官，会攻击任何胆敢靠近山头大门的部落勇士。",al={"哈格丁是否敌对部落","部落 哈格丁","部落能否与哈格丁交谈"}},{q="实验场试炼是什么？",a="实验场是哈格丁交给有志加入联盟军队者的一项入门任务，旨在他们全力投身奥特兰克山谷战事之前，检验他们的能力与决心。",al={"实验场任务","实验场 奥特兰克","哈格丁 实验场"}}},fx={["9b7a183a"]={q="哈格丁中尉效忠于谁？",a="哈格丁直接隶属于雷矛卫队。雷矛卫队是铁炉堡雷矛远征军的军事力量，由范达尔·雷矛将军率领。他担任军官，负责联络经由奥特兰克山脉抵达的联盟新兵与深入奥特兰克山谷作战的团部。",al={"哈格丁的效忠对象","哈格丁与雷矛卫队","哈格丁效力于谁"}},["1d45d886"]={q="哈格丁中尉效忠于哪一方？",a="哈格丁中尉完全效忠于联盟，具体来说，他隶属于雷矛卫队。他在靠近奥特兰克山谷的丘陵北缘执行任务，担任军官和征召员，协助集结联盟部队对抗霜狼兽人。",al={"哈格丁的阵营","哈格丁是否属于联盟","哈格丁的效忠对象"}},["5fb68a23"]={q="哈格丁中尉想要什么？",a="哈格丁希望有能力的联盟勇士能壮大奥特兰克山谷中雷矛卫队的队伍。他会考验新兵，确保他们能够在冰冷的荒野中生存；随着老兵战功日增，他会授予他们军衔和徽记。他还希望铲除冬斧巨魔勇士科尔拉克等威胁。",al={"哈格丁想要什么","哈格丁的目标","哈格丁的职责"}},["96f37aaa"]={q="哈格丁中尉为什么在奥特兰克丘陵？",a="哈格丁中尉驻守在俯瞰奥特兰克山谷入口的岬角，负责组织并审核前来增援的联盟部队。雷矛远征队与霜狼氏族之间的战斗仍在持续，急需不断增援，因此他驻守在集结地，招募并嘉奖愿意在雪地中奋战的人。",al={"哈格丁为什么在这里","哈格丁为什么在奥特兰克","哈格丁的驻守地点"}}},fp="20,206,26.265.0,28.335.0,28.225.0,38.147.0,53.240.0,47.204.0,53.113.0,34.202.0"}
P.entries["npc:lieutenant-lisande"] = {n="利山德中尉",s="在雷霆崖高耸的台地上，利山德中尉留意着天灾军团的迹象。",h="在雷霆崖高耸的台地上，利山德中尉留意着天灾军团的迹象。",kw={"银色黎明","利山德中尉","莉珊德","莫高雷","天灾军团","天灾军团入侵","雷霆崖"},ang={["faction:Horde"]="Lisande提醒部落，对抗Scourge需要务实，有时还需要与中立的人类组织合作。",["race:Tauren"]="尽管Lisande是个外来者，牛头人仍尊重银色黎明为清除这片土地上的亡灵所做的努力。"},sec={{t="出人意料的使者",b="利山德中尉在雷霆崖为银色黎明效力，那里鲜有人类的身影。这个神圣组织留意着巫妖王污染的迹象，即使在偏远的卡利姆多也不例外。当亡灵部队在下方的平原上蠢蠢欲动时，利山德便召集部落勇士策马前去调查，以免天灾军团玷污这片神圣的土地。"}},faq={{q="为什么雷霆崖会有一个人类？",a="莉珊德代表着银色黎明，这是一个致力于消灭天灾军团的组织。银色黎明欢迎联盟和部落的各个种族加入，其联络员可以进入各大主城，协调抵御亡灵的防御事宜。",al={"雷霆崖的人类","利山德为何在这里","她是否敌对"}},{q="银色黎明为何关注莫高雷？",a="巫妖王的势力威胁着艾泽拉斯的每一个角落，并不局限于东部王国。莉珊德留意着威胁莫高雷的通灵活动或天灾军团部队，让当地的守卫知晓危险。",al={"莫高雷的天灾军团","为何在雷霆崖","牛头人领地的亡灵"}},{q="利山德中尉会交付什么任务？",a="莉珊德派遣冒险者走下崖顶，调查这片领地各处天灾军团的入侵情况，并回来汇报。银色黎明随后便能评估威胁的规模。",al={"利山德的任务","利山德做什么","调查任务"}}},fp="18,85,17.313.0,41.215.0,46.209.0,44.163.0"}
P.entries["npc:lieutenant-nevell"] = {n="奈维尔中尉",s="在丹莫罗的铁炉堡城外，奈维尔中尉警戒着天灾军团的动向。这位银色黎明军官协调当地守军，并提醒初来者提防矮人王国附近的亡灵威胁。",h="在丹莫罗的铁炉堡城外，奈维尔中尉警戒着天灾军团的动向。这位银色黎明军官协调当地守军，并提醒初来者提防矮人王国附近的亡灵威胁。",kw={"银色黎明","丹莫罗","铁炉堡","奈维尔中尉","奈维尔","天灾军团"},ang={["faction:Alliance"]="作为踏入铁炉堡的联盟勇士，你会发现，对抗Scourge的战火早已蔓延到了北方之外。",["race:Dwarf"]="身为矮人，银色黎明守护着你的山间家园，抵御丹莫罗寒冷山坡上的死灵法术。"},sec={{t="雪中守望",b="奈维尔中尉监视着通往铁炉堡的积雪道路，提防天灾军团来袭。银色黎明以坚守洛丹伦满目疮痍的瘟疫之地而闻名，但他们的警戒范围也延伸到了更南方。每当天灾军团在丹莫罗的山口有所异动，奈维尔便从铁炉堡城外调遣新兵和有能力的冒险者奔赴前线。矮人城市的边境因此始终有人守望。"}},faq={{q="奈维尔中尉是谁？",a="奈维尔中尉在丹莫罗的铁炉堡附近为银色黎明效力。他集结当地守军，调查矮人王国附近天灾军团的踪迹。",al={"奈维尔的职责","奈维尔是谁","奈维尔中尉"}},{q="银色黎明为何驻扎在铁炉堡城外？",a="银色黎明的主力虽然驻扎在洛丹伦，却在整片大陆上警戒着亡灵的入侵。奈维尔这样的军官监视着丹莫罗的动向，协调防御，抵御天灾军团的威胁。",al={"丹莫罗的银色黎明","银色黎明 铁炉堡"}},{q="奈维尔中尉要求冒险者做什么？",a="奈维尔中尉派遣有能力的冒险者走出铁炉堡的大门，侦察并打击附近的天灾军团部队，阻止亡灵在山口站稳脚跟。",al={"奈维尔的任务","调查天灾军团"}}},fx={["4853a4a6"]={q="奈维尔中尉效忠哪一方？",a="奈维尔中尉为银色黎明效力，这个坚定的中立组织致力于保护艾泽拉斯免受天灾军团侵害。虽然他是人类，却驻守在铁炉堡大门外，与所有抵抗亡灵威胁的人结盟，同矮人协力组织防御，而非直接为联盟军队效力。",al={"奈维尔中尉阵营","奈维尔中尉为谁而战","奈维尔属于银色黎明吗"}},["5e43a7a7"]={q="奈维尔中尉与谁有关联？",a="奈维尔直接听命于银色黎明的领袖。他驻守在丹莫罗的山坡上，担任银色黎明与铁炉堡守军之间的联络人，召集当地冒险者和巡山人，对抗逐渐渗入这一地区的任何天灾军团威胁。",al={"奈维尔的关系","奈维尔中尉与银色黎明的关系","奈维尔听命于谁"}}},fp="17,196,19.400.0,25.159.0,41.201.0,50.176.0"}
P.entries["npc:lieutenant-orrin"] = {n="奥林中尉",s="暴风城外的天灾军团蠢蠢欲动，奥林中尉在城门口征召斥候。他在英雄谷指派新兵调查亡灵威胁，防止它们逼近首都。",h="暴风城外的天灾军团蠢蠢欲动，奥林中尉在城门口征召斥候。他在英雄谷指派新兵调查亡灵威胁，防止它们逼近首都。",kw={"银色黎明","奥林中尉","死灵水晶","奥林","天灾军团","暴风城","亡灵","英雄谷"},ang={["class:Paladin"]="身为圣骑士，你加入银色黎明的行动，肃清各处滋生的死灵魔法。",["faction:Alliance"]="对于返回暴风城的联盟勇士而言，奥林中尉的守望表明，南方腹地同样面临着巫妖王势力带来的危险。"},sec={{t="城门前的哨兵",b="奥林中尉在英雄谷守望着通往城外的道路。银色黎明坚守在北方废墟的前线，也守卫着更南方的据点，其中就包括暴风城。当死灵魔法在首都之外涌动时，奥林便会发出警报，召集冒险者，赶在亡灵威胁城中百姓之前采取行动。"},{t="监视亡灵",b="奥林中尉负责联络银色黎明与南方王国的志愿者。当暴风城门外出现天灾军团的踪迹时，他会派遣斥候收集情报，并收缴危险的神器。他们带回的物品中有破裂的死灵水晶，能帮助银色黎明了解并抵御亡灵的威胁。"}},faq={{q="奥林中尉是谁？",a="奥林中尉是银色黎明的一名人类军官，驻守在暴风城入口处的英雄谷。当天灾军团威胁周边地区时，他负责协调防御并招募斥候。",al={"奥林是谁","奥林中尉的故事","银色黎明军官是谁"}},{q="银色黎明为何驻守暴风城？",a="银色黎明在暴风城保持警戒，因为天灾军团也威胁着瘟疫之地之外的土地。在首都的城门口，银色黎明的军官监视着死灵魔法的入侵，并招募战士阻挡亡灵。",al={"银色黎明为何在暴风城","银色黎明 暴风城","银色黎明在这里做什么"}},{q="奥林中尉要求冒险者做什么？",a="奥林中尉派遣新兵前往暴风城外侦察，调查天灾军团活动的迹象，并找回破裂的死灵水晶等神器。银色黎明研究这些物品，以了解这些入侵背后的邪恶魔法。",al={"奥林的任务","调查暴风城的天灾军团","奥林想要什么"}}},fx={["3ede5d84"]={q="奥林中尉效忠哪一方？",a="奥林中尉为银色黎明效力，这个坚定的中立联合组织专为对抗天灾军团而成立，无论它们在艾泽拉斯何处构成威胁，都会迎战。虽然他驻守在暴风城的英雄谷，与人类守军同在，但他首先效忠的仍是银色黎明的神圣使命，而非联盟的政治事务。",al={"奥林中尉阵营","奥林为谁效力","奥林中尉是联盟吗"}}},fp="16,201,23.337.0,20.332.0,24.213.0,41.211.0,49.245.0"}
P.entries["npc:loganaar"] = {n="洛甘纳尔",s="洛甘纳尔是一位暗夜精灵德鲁伊导师，居住在月光林地的庇护之所永夜港。他致力于指引来自联盟和部落的新学徒，教导年轻的德鲁伊感应荒野，为翡翠梦境的召唤做好准备。",h="洛甘纳尔是一位暗夜精灵德鲁伊导师，居住在月光林地的庇护之所永夜港。他致力于指引来自联盟和部落的新学徒，教导年轻的德鲁伊感应荒野，为翡翠梦境的召唤做好准备。",kw={"塞纳里奥议会","德鲁伊训练师","翡翠梦境","洛甘纳尔","月光林地","永夜港"},ang={["class:Druid"]="对于来自达纳苏斯和雷霆崖的德鲁伊而言，洛甘纳尔是他们传送至月光林地后最早遇到的导师之一，为他们提供进阶训练和心灵上的指引。",["race:NightElf"]="洛甘纳尔体现了Kaldorei德鲁伊的古老传统，他们在玛法里奥·怒风的引领下，历经数千年与自然交流，并进入翡翠梦境。"},sec={{t="神圣技艺的守护者",b="在永夜港宁静的枝叶间，洛甘纳尔担任着初入德鲁伊之道、前来月光林地的学徒们的主要导师。无论学徒来自达纳苏斯还是雷霆崖，洛甘纳尔都会指引他们掌握平衡与变形之术，并教导他们敬畏自然。他提醒学生，即使身处冰冷的石墙之内或陌生的土地上，也必须从内心寻得真正的宁静。他也热忱地引导那些逐渐深入参与塞纳里奥议会事务的德鲁伊，派遣有潜力的学生去拜访安戈洛环形山的托尔瓦·寻路者等漫游者，或进一步研习古老的林地仪式。"},{t="梦境的召唤",b="除了传授基础法术，洛甘纳尔还让学生为卡利姆多传统守护者共同的最终归宿做好准备：在翡翠梦境中沉睡。他向学徒讲授艾泽拉斯的原始灵界与清醒世界之间的神圣联系，提醒他们，要真正精通德鲁伊之道，终有一天必须沉眠数百年，在半神的指引下，行走于自然最纯净、未受玷污的形态之间。"}},faq={{q="洛甘纳尔是谁？",a="洛甘纳尔是一位暗夜精灵德鲁伊训练师，驻留在月光林地的中心聚落永夜港。他欢迎各种出身的德鲁伊前来研习技艺，并引领他们了解塞纳里奥议会更深层的传统。",al={"洛甘纳尔非玩家角色","洛甘纳尔是谁","洛甘纳尔背景故事"}},{q="洛甘纳尔会训练部落德鲁伊吗？",a="会。月光林地是由塞纳里奥议会监管的神圣中立之地。身为议会的一员，洛甘纳尔将联盟与部落之间的冲突搁置一旁，平等地教导牛头人和暗夜精灵德鲁伊。",al={"牛头人能在洛甘纳尔处训练吗","洛甘纳尔部落","月光林地部落德鲁伊训练师"}},{q="洛甘纳尔如何讲授翡翠梦境？",a="洛甘纳尔教导学生，每一位真正的德鲁伊最终都会感受到翡翠梦境的召唤。他解释说，在漫长而深沉的休眠中，行走于梦境未受腐化的形态之间，正是德鲁伊接受最终修行的方式。",al={"洛甘纳尔梦境","翡翠梦境引语"}},{q="洛甘纳尔会派经验丰富的德鲁伊去哪里？",a="随着德鲁伊的经验日益丰富，洛甘纳尔会指引他们前往外界，观察并修复艾泽拉斯的原始生态系统。在他布置的任务中，就有派遣资深弟子前往安戈洛环形山未经驯服的荒野，协助托尔瓦·寻路者这样的博物学家。",al={"洛甘纳尔任务","托尔瓦·寻路者任务洛甘纳尔"}}},fp="8,158,24.454.0,21.307.0,16.174.0,33.188.0,49.192.0,41.177.0"}
P.entries["npc:lomac-gearstrip"] = {n="洛玛克·链带",s="在铁炉堡的侏儒区，洛玛克·链带潜心钻研侏儒发明。他配制了NG-5炸药，并与卡利姆多的研究同僚保持联系。",h="在铁炉堡的侏儒区，洛玛克·链带潜心钻研侏儒发明。他配制了NG-5炸药，并与卡利姆多的研究同僚保持联系。",kw={"老同事","侏儒工程师","失职＋化学药剂＝快乐","铁炉堡","洛玛克·链带","ng-5炸药","石爪山脉","侏儒区"},ang={["faction:Alliance"]="往返于铁炉堡和卡利姆多远征前哨的联盟特工，经常为洛玛克经手敏感军需品和性质不稳定的配方。",["profession:Engineering"]="洛玛克的NG-5炸药体现了侏儒先进的火工技术，也可能为那些对强效爆破化合物感兴趣的工匠带来灵感。",["race:Gnome"]="身为侏儒，洛玛克也有着侏儒区居民坚韧不拔的干劲，即使流亡在诺莫瑞根之外，仍在开展艰深的技术研究。"},sec={{t="侏儒区的火花",b="洛玛克·链带在铁炉堡的侏儒区研究侏儒军械。和许多逃离诺莫瑞根惨剧的侏儒一样，他将自己的发明工坊迁到了矮人的都城。他的工坊专门研制性质不稳定的化学混合物和特种弹药，用来攻克防御森严的敌方据点。"},{t="NG-5炸药",b="洛玛克在战斗工程领域最引以为傲的成果，就是NG-5炸药。这种化合物旨在产生强大的破坏力，需要精确操作，并使用稀有的化学试剂。为了改进这些危险的发明并将其投入实战，洛玛克与远方战区的旧日同僚保持联系。他们跨越无尽之海，互相传递技术指令和危险物资。"}},faq={{q="在哪里能找到洛玛克·链带？",a="洛玛克在侏儒区工作，那是铁炉堡东部的侏儒区。",al={"洛玛克·链带位置","洛玛克在哪","寻找洛玛克·链带"}},{q="洛玛克·链带以哪项发明闻名？",a="洛玛克最为人所知的成果是配制出NG-5炸药，为侏儒的各项行动提供强大的火力。",al={"洛玛克制造了什么","洛玛克的发明","ng-5炸药发明者"}},{q="洛玛克为什么与卡利姆多的联络人往来？",a="洛玛克与身处石爪山脉等边疆地区的旧日研究伙伴和同僚保持联系。他们协调危险化学原料的供应，并在实际行动中测试他的炸药。",al={"洛玛克石爪山脉","为什么有石爪山脉任务","洛玛克的同僚"}},{q="洛玛克会向冒险者提供什么样的任务？",a="洛玛克委托联盟信使在铁炉堡与海外研究人员之间运送采购订单和性质不稳定的化学试剂。这些运送任务常常与他的NG-5炸药实验有关。",al={"洛玛克的任务","失职 化学药剂 快乐","老同事任务"}},{q="与洛玛克有关的采购订单收据是什么？",a="洛玛克编写了采购订单收据，这份货单用于安排和记录工匠之间运送的专用设备，以及危险且性质不稳定的试剂。",al={"订货单收据","洛玛克的收据"}},{q="洛玛克是诺莫瑞根难民中的一员吗？",a="是的。洛玛克属于流离失所的诺莫瑞根侏儒群体，他们受到铁炉堡矮人的接纳，而他也继续从事工程研究。",al={"洛玛克来自诺莫瑞根吗","洛玛克的阵营"}}},fx={e46167fb={q="洛玛克·链带是谁？",a="洛玛克·链带是一位雄心勃勃的侏儒发明家兼工匠，在矮人要塞铁炉堡的侏儒区开展工作。他潜心钻研危险的实验与化学工程，最为人熟知的成果是NG-5炸药等威力强大的军火。尽管远隔无尽之海，他的人脉与生意往来仍延伸至卡利姆多，以获取所需的稀有材料和实地测试机会。",al={"洛玛克是谁","链带是谁","洛玛克·链带的故事"}},["6618560a"]={q="洛玛克·链带想要什么？",a="洛玛克·链带一心投入爆破工程项目，尤其致力于改进他珍爱的NG-5炸药。为了继续开展化学试验，他需要信使、不稳定的化合物，以及使用他配制的药剂进行的实地测试。他依靠世界各地的旅者和旧识完成采购订单，取得完善这些不稳定发明所需的稀有试剂。",al={"洛玛克想要什么","洛玛克·链带的目标","洛玛克为何需要帮助"}},ca50cdb6={q="洛玛克·链带与谁有关联？",a="洛玛克与远方的伙伴和工匠同行保持联系，其中包括一位身在海外、协助处理订单及专项测试的老同事。他在侏儒区工作，与诺莫瑞根流亡者和铁炉堡当地的工匠相处融洽，派遣信使与冒险者往返联络，连接他位于东部王国的工作台与卡利姆多各处的试验场。",al={"洛玛克与谁合作","洛玛克·链带的伙伴","洛玛克的老同事"}}},fp="15,162,22.308.0,18.379.0,33.69.0,45.107.0,46.205.0,51.198.0,49.170.0,47.147.0"}
P.entries["npc:longbraid-the-grim"] = {n="布莱德·长须",s="在沦陷的丹莫德城外，布莱德·长须守望着湿地北部。他为兄弟的死和萨多尔大桥的失守而悲痛，同时率领幸存的矮人对抗黑铁氏族。",h="在沦陷的丹莫德城外，布莱德·长须守望着湿地北部。他为兄弟的死和萨多尔大桥的失守而悲痛，同时率领幸存的矮人对抗黑铁氏族。",kw={"黑铁","丹莫德","长须","萨多尔大桥","格瑞姆","湿地","维尔加"},ang={["faction:Alliance"]="对联盟而言，长须守卫着卡兹莫丹的北部门户，并为重新打通经萨多尔大桥通往阿拉希的陆路而战。",["race:Dwarf"]="对铁炉堡矮人而言，长须体现了他们与黑铁同族之间深重的血仇，后者曾袭击他们的北部门户。"},sec={{t="苦涩的守望",b="布莱德·长须在通往阿拉希高地的大桥附近集结矮人驻军。黑铁氏族突然发动进攻，重创守军，夺取了丹莫德。长须的兄弟在萨多尔大桥的围攻中阵亡。悲痛与仇恨让长须留在北部边界，指挥旅人与幸存的巡山人打击步步进逼的黑铁部队。"},{t="坚守防线",b="长须还指挥着湿地各处的矮人行动。他曾派士兵护送勘察员维尔加进入沼泽地，并致力于夺回丹莫德失守的防御工事。他发誓要向黑铁破坏者复仇。"}},faq={{q="布莱德·长须是谁？",a="布莱德·长须统率着驻扎在湿地北部丹莫德城外的矮人。他领导当地的联盟抵抗力量，对抗占领这一地区的黑铁矮人。",al={"长须是谁","长须的身份","丹莫德矮人"}},{q="长须为何被称为“严酷者”？",a="长须的兄弟在黑铁对萨多尔大桥的进攻中阵亡，从此他变得冷峻。此后，他一直在为死去的亲人寻求复仇。",al={"他为何冷峻","长须的兄弟","长须的过往"}},{q="丹莫德发生了什么？",a="黑铁氏族伏击了丹莫德的矮人驻军，随后攻陷并占领了那里。他们试图摧毁萨多尔大桥，切断湿地与阿拉希高地之间的主要通道。",al={"丹莫德的沦陷","大桥发生了什么","萨多尔大桥遇袭"}},{q="长须与勘察员维尔加有什么联系？",a="当矮人挖掘队深入危机四伏的湿地探索时，长须从麾下派出士兵，陪同并保护勘察员维尔加。",al={"维尔加 长须","麦琳的信"}}},fp="18,196,14.391.0,16.229.0,26.182.0,35.133.0,26.197.0,53.159.0"}
P.entries["npc:loramus-thalipedes"] = {n="洛拉姆斯·萨里比迪斯",s="洛拉姆斯·萨里比迪斯是一位离群索居的暗夜精灵恶魔猎手，隐居在艾萨拉海岸外的一座偏远岛屿上。他身旁有忠诚的地狱猎犬相伴，一生致力于消灭污染者拉瑟莱克，指引身经百战的勇士完成仪式，击杀这名恐惧魔王。",h="洛拉姆斯·萨里比迪斯是一位离群索居的暗夜精灵恶魔猎手，隐居在艾萨拉海岸外的一座偏远岛屿上。他身旁有忠诚的地狱猎犬相伴，一生致力于消灭污染者拉瑟莱克，指引身经百战的勇士完成仪式，击杀这名恐惧魔王。",kw={"艾萨拉","恶魔猎手","邪魔克星","地狱猎犬","赫塔拉的巢穴","洛拉姆斯","拉瑟莱克","萨里比迪斯"},ang={["class:Warlock"]="术士会从他控制的地狱猎犬身上看出他在奴役恶魔方面的非凡造诣，不过洛拉姆斯束缚恶魔，只为让它们屠杀自己的同类。",["race:NightElf"]="暗夜精灵历来对恶魔猎手怀有深深的恐惧与不信任，认为他们在仪式中自残、与恶魔缔结契约，走上了与伊利丹的背叛如出一辙、不可饶恕的道路。"},sec={{t="群岛上的盲眼猎手",b="洛拉姆斯·萨里比迪斯栖身于赫塔拉的巢穴东南方一座饱受风暴侵袭的孤岛，与其他同胞远远隔绝。他是一名恶魔猎手，也是一名流亡者，曾经历痛苦的仪式，刺瞎双眼以获得幽灵视觉。三只名为雷塔夫、沙希莱尔和撒曼的高大地狱猎犬环绕在洛拉姆斯身旁，他注视着艾泽拉斯各处无形的恶魔腐化暗流，同时警戒着艾萨拉破碎的废墟。"},{t="跨越大陆的复仇",b="洛拉姆斯执着追猎的目标位于大海彼岸的诅咒之地，他一心要消灭恐惧魔王污染者拉瑟莱克。洛拉姆斯深知寻常刀剑无法永久消灭狡猾的恶魔，因此指引旅者完成古老的仪式，要求他们收集艾萨拉水晶和这名恶魔的真名，以便锻造对付他的破魔武器。通过这些秘传的准备工作，他力图剥除拉瑟莱克的防护，束缚这名恶魔的真名，彻底了结这场复仇。"}},faq={{q="洛拉姆斯·萨里比迪斯是谁？",a="洛拉姆斯·萨里比迪斯是一名暗夜精灵恶魔猎手，居住在艾萨拉海岸外的一座孤岛上。他致力于挫败强大的恶魔，尤其是恐惧魔王污染者拉瑟莱克。",al={"洛拉姆斯身份","艾萨拉的恶魔猎手是谁","洛拉姆斯是谁"}},{q="洛拉姆斯为何蒙着双眼？",a="与其他恶魔猎手一样，洛拉姆斯舍弃了自己的双眼。他以凡人的寻常视力为代价，通过这一仪式获得了侦测恶魔能量所必需的幽灵视觉。",al={"洛拉姆斯为何没有双眼","洛拉姆斯失明","恶魔猎手眼罩"}},{q="为何有地狱猎犬守护着他？",a="洛拉姆斯驯服并束缚了三只强大的地狱猎犬——雷塔夫、沙希莱尔和撒曼，使它们的捕食本能服务于他对恶魔的猎杀，而非为燃烧军团效力。",al={"洛拉姆斯的地狱猎犬","洛拉姆斯为何有恶魔","雷塔夫 沙希莱尔 撒曼"}},{q="他与诅咒之地有何关联？",a="他策划了击杀恐惧魔王污染者拉瑟莱克的行动，这名恐惧魔王统治着诅咒之地的高处。洛拉姆斯提供了突破拉瑟莱克防护所需的关键知识、仪式与武器。",al={"洛拉姆斯诅咒之地","拉瑟莱克任务","他为何关心诅咒之地"}}},fp="18,146,29.391.0,28.396.1,26.173.0,27.155.0,37.166.0,44.189.0"}
P.entries["npc:lord-arkkoroc"] = {n="亚考罗克",s="亚考罗克是一位古老而高大的海巨人，栖居在艾萨拉崎岖海岸边的亚考兰神殿废墟中。恶魔猎手洛拉姆斯·萨里比迪斯称他为一位次级神祇，他掌控着周围的水域，统率着奉他为父的低等海巨人。",h="亚考罗克是一位古老而高大的海巨人，栖居在艾萨拉崎岖海岸边的亚考兰神殿废墟中。恶魔猎手洛拉姆斯·萨里比迪斯称他为一位次级神祇，他掌控着周围的水域，统率着奉他为父的低等海巨人。",kw={"亚考兰","亚考罗克","艾萨拉","赫塔拉","洛拉姆斯","海巨人"},ang={["race:NightElf"]="亚考兰神殿的废墟矗立在上层精灵昔日的领地上，如今，一位古老的海洋存在统治着古代卡利姆多衰败的辉煌遗迹。"},sec={{t="沉没海岸之主",b="亚考罗克斜倚在亚考兰神殿结满盐霜的废墟中，远非寻常海巨人可比。在洛拉姆斯·萨里比迪斯这样的隐士眼中，这个庞然大物是一位次级神祇，其神圣意志左右着周围的水域。他的子嗣在神殿周围的峭壁与浅滩间巡逻，维系着他对艾萨拉风浪肆虐的海岸的无声统治。"},{t="向深海复仇",b="尽管拥有强大的神力，亚考罗克仍在波涛之下承受着丧子之痛。一头名为赫塔拉的可怕多头蛇沿着峭壁猎杀了他的许多子嗣。亚考罗克或是无力，或是不愿亲自追杀这头野兽，便以宝贵的知识和秘法援助为报酬，招徕有能力献上杀子凶兽头颅的游历冒险者。"}},faq={{q="亚考罗克是谁？",a="亚考罗克是一位体型庞大的海巨人，居住在艾萨拉的亚考兰神殿中。他被尊为海洋中的一位次级神祇，统治着一群被他视为子嗣的海巨人。",al={"亚考罗克是谁","亚考罗克的传说","神殿海巨人"}},{q="在哪里可以找到亚考罗克？",a="你可以在亚考兰神殿的废墟中找到他，那里位于艾萨拉东部的海岸与岩礁之间。",al={"亚考罗克的位置","亚考罗克在哪里","寻找亚考罗克"}},{q="洛拉姆斯·萨里比迪斯为何派冒险者去找亚考罗克？",a="洛拉姆斯·萨里比迪斯指引旅者前往亚考罗克处，寻求有关一个强大恶魔的奥术知识。身为海洋中的一位次级神祇，亚考罗克掌握着古老的知识，但他要求冒险者先杀死多头蛇赫塔拉，才肯透露自己的秘密。",al={"洛拉姆斯亚考罗克任务","野兽的名字"}},{q="亚考罗克为何对多头蛇赫塔拉怀有怒火？",a="凶残的海兽赫塔拉屠杀了亚考罗克数名在海岸巡逻的子嗣。为了替死去的亲族复仇，这位海巨人要求献上她的头颅。",al={"为何杀死赫塔拉","亚考罗克与多头蛇的仇怨"}}},fp="13,191,24.277.0,26.244.1,21.196.0,31.119.0,57.203.0,45.155.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="鲍雷斯·维沙克公爵",s="在暴风要塞，鲍雷斯·维沙克公爵周旋于请愿者和达官显贵之间。他拖欠酒馆的酒账，又嗜好烈酒，因此逐渐卷入城中更阴暗的勾当。",h="在暴风要塞，鲍雷斯·维沙克公爵周旋于请愿者和达官显贵之间。他拖欠酒馆的酒账，又嗜好烈酒，因此逐渐卷入城中更阴暗的勾当。",kw={"鲍雷斯","贵族","祈求者之厅","已宰的羔羊","暴风要塞","维沙克","加尔德斯"},ang={["class:Warlock"]="身为术士，你知道鲍雷斯·维沙克公爵对已宰的羔羊的调查威胁着暴风城的暗影集会。让他悄无声息地死去，成了集会成员的当务之急。",["race:Human"]="身为人类，在年幼的国王Anduin统治初期，你在Petitioner's Chamber见识到了贵族声名狼藉的腐化与自私。"},sec={{t="贵族的危险好奇心",b="鲍雷斯·维沙克公爵是颇具影响力的贵族的一员，在暴风要塞周旋于请愿者和达官显贵之间。然而，他时常在法师区的破旧酒馆饮酒，尤其常去已宰的羔羊，还拖欠了大笔酒账。在那里，他听说有一个术士集会在地板下的地窖里修习黑暗法术。维沙克打算关闭这家酒馆，并请求其他贵族展开正式调查。在暴风城，揭露恶魔密党的存在，往往会招来报复。"},{t="一杯毒酒",b="为了避开王室的审视，防止术士集会的地下密所遭到调查，黑爪加尔德斯安排人悄悄杀死鲍雷斯·维沙克公爵。术士们利用维沙克对名贵佳酿的嗜好，准备了一杯伪装成上等麦酒的致命毒酒。一名受雇的冒险者被选中，要在城堡守卫的眼皮底下将酒送给维沙克。"}},faq={{q="鲍雷斯·维沙克公爵是谁？",a="鲍雷斯·维沙克公爵是贵族的一员，整日在暴风要塞内的请愿者大厅活动。法师区的酒馆老板都知道，他欠着大笔酒账。",al={"鲍雷斯 维沙克","维沙克是谁","贵族请愿者"}},{q="在哪里能找到维沙克公爵？",a="鲍雷斯·维沙克公爵位于暴风要塞东侧的请愿者大厅。廷臣、外交使节和请愿者聚集在此，等候王室接见。",al={"维沙克位置","维沙克在哪","寻找维沙克公爵"}},{q="已宰的羔羊地下的术士为何想要他死？",a="在已宰的羔羊，鲍雷斯·维沙克公爵得知酒馆地下有一个术士集会在活动。他请求贵族展开正式调查，并希望关闭这家酒馆，这使术士们的活动面临暴露的危险。",al={"为何杀死维沙克","加尔德斯 维沙克","为何毒杀维沙克"}},{q="他是如何遇刺的？",a="黑爪加尔德斯调制了一种致命毒药，将其伪装成美酒。一名代理人将掺毒的酒桶送到暴风要塞，交给鲍雷斯·维沙克公爵。他贪恋美酒，又爱喝免费的酒，因此很容易得手。",al={"维沙克如何死去","维沙克 毒药","贵族的美酒"}}},fx={["255656dc"]={q="鲍雷斯·维沙克公爵效忠哪一方？",a="维沙克公爵是贵族的现任成员，为暴风城王国效力。他的活动严格限于王国贵族圈内，运用政治影响力维护市政与贵族的权威，对抗潜伏在城内的颠覆势力。",al={"维沙克公爵效忠哪一方","维沙克公爵阵营","维沙克为谁效力"}},["59c1fa27"]={q="鲍雷斯·维沙克公爵想要什么？",a="维沙克公爵决心揭露并取缔在已宰的羔羊地下室活动的黑暗密会。发现他们的邪恶仪式后，他正积极游说贵族的同僚，对这家旅店展开全面的官方调查，并将术士从暴风城清除。",al={"维沙克的目标","维沙克想要什么","维沙克公爵的计划"}},["3d37be28"]={q="鲍雷斯·维沙克公爵为什么在暴风要塞？",a="你会在暴风要塞内的请愿者大厅找到维沙克公爵，他在那里履行贵族职责。作为贵族的一员，他经常前往要塞，与其他贵族商议事务，并向王廷请愿。",al={"维沙克为什么在暴风要塞","维沙克公爵为什么在这里","维沙克 请愿者大厅"}},["83d2fff3"]={q="鲍雷斯·维沙克公爵与谁有关联？",a="维沙克公爵隶属于贵族，这是暴风城贵族颇具影响力的治理议会。在宫廷之外，他曾是法师区的已宰的羔羊的常客——他在那里欠下了巨额酒账，之后才发现有术士集会在酒馆隐秘的地下墓穴中修习黑暗法术。",al={"维沙克的关联","维沙克公爵的人脉","维沙克 贵族"}}},fp="23,188,32.473.0,14.350.1,31.193.0,32.186.0,63.232.1,23.239.1"}
P.entries["npc:lord-cobrahn"] = {n="考布莱恩",s="考布莱恩是潜伏在哀嚎洞穴深处的被腐化的尖牙德鲁伊的四位领袖之一。他曾是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团旨在治愈贫瘠之地。后来，他屈服于感染了洞穴泉水的梦魇。考布莱恩化身为致命的毒蛇，如今统领着成群的变异蛇，守卫着这座扭曲的迷宫。",h="考布莱恩是潜伏在哀嚎洞穴深处的被腐化的尖牙德鲁伊的四位领袖之一。他曾是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团旨在治愈贫瘠之地。后来，他屈服于感染了洞穴泉水的梦魇。考布莱恩化身为致命的毒蛇，如今统领着成群的变异蛇...",kw={"考布莱恩","变异蟒","尖牙德鲁伊","尖牙领主","考布莱恩宝石","哀嚎洞穴"},ang={["class:Druid"]="考布莱恩是一个严峻的警示，提醒人们当德鲁伊变形术与梦魇而非自然平衡相连时，会变得多么扭曲。",["faction:Horde"]="部落冒险者寻找考布莱恩，是为了终结蔓延至贫瘠之地的邪恶腐化，并保护卡利姆多平原脆弱的生态系统。",["race:NightElf"]="对于暗夜精灵来说，考布莱恩的堕落是一场悲剧，他们看到塞纳里奥议会的一位技艺精湛的兄弟抛弃了传承，转而在地底深处率领怪物。"},sec={{t="被腐化的德鲁伊",b="在堕落之前，考布莱恩是追随纳拉雷克斯的高尚德鲁伊之一。当纳拉雷克斯冒险进入贫瘠之地地下的哀嚎洞穴，希望能引出其中的地下泉水，让贫瘠的荒地重现生机时，考布莱恩便随行在侧。然而，当纳拉雷克斯与翡翠梦境的沟通堕落为扭曲的梦魇时，考布莱恩和他的兄弟们也随之精神崩溃。"},{t="蛇之拥抱",b="梦魇并没有让他引导塞纳里奥传统的图腾野兽，而是将考布莱恩的变形能力扭曲成了某种掠食性的爬行动物形态。他现在掌握着一种致命的毒蛇形态，并在战斗中将其释放出来。在毒性变异蟒的簇拥下，他挥舞着右手上凶狠的利爪，镇守着他所在的洞穴区域，暴力清除任何试图打破梦魇对洞穴控制的人。"}},faq={{q="考布莱恩在堕落前是谁？",a="在被梦魇侵蚀之前，考布莱恩是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团曾进入哀嚎洞穴，希望利用那里的泉水来治愈贫瘠之地。",al={"考布莱恩的真名","考布莱恩是谁"}},{q="为什么他被称为考布莱恩？",a="没有记载解释过这个名字，但它很适合他。在哀嚎洞穴中被梦魇扭曲后，他化身为致命的毒蛇，身边围绕着变异蟒，而他的尖牙领主同伴安娜科德拉、派萨斯和瑟芬迪斯也有着类似蛇类的名字。",al={"为什么要找考布莱恩","考布莱恩名字含义"}},{q="在哪里可以找到考布莱恩？",a="考布莱恩居住在哀嚎洞穴的深处，这是一个位于贫瘠之地中部的地下扭曲网络，周围环绕着变异蟒和其他被梦魇腐化的野兽。",al={"考布莱恩位置","考布莱恩在哪里","考布莱恩所在的房间"}},{q="冒险者为什么要击败他？",a="他是领导尖牙德鲁伊的主要尖牙领主之一。他携带着考布莱恩宝石，雷霆崖的德鲁伊纳拉·野鬃正试图寻找它，以打破尖牙领主对贫瘠之地的控制。",al={"为什么要杀考布莱恩","尖牙领主考布莱恩"}},{q="他有什么独特的生理特征？",a="与普通的暗夜精灵不同，考布莱恩的身材明显更高大，右手长有锋利的利爪，并且在战斗中可以完全变形成一条巨大的毒蛇。",al={"考布莱恩长什么样","考布莱恩的外观"}},{q="他与其他尖牙德鲁伊有什么联系？",a="考布莱恩与安娜科德拉及其族人是四位主要的尖牙领主之一。他们曾是纳拉雷克斯高尚教团的德鲁伊，随纳拉雷克斯进入洞穴，并共同堕落于梦魇的扭曲腐化之中。",al={"尖牙德鲁伊领袖","考布莱恩与安娜科德拉"}}},fx={["7ca4c072"]={q="考布莱恩为什么会在这里？",a="他最初与纳拉雷克斯一同进入哀嚎洞穴，打算汲取地下水脉的力量，让贫瘠之地恢复为郁郁葱葱的乐土。纳拉雷克斯与翡翠梦境的联系扭曲成噩梦后，能量毒害了弟子们的心智。考布莱恩彻底屈服于腐化，留在洞穴中守护沉睡的大德鲁伊，并孕育噩梦中有毒的生物。",al={"考布莱恩为什么在哀嚎洞穴","考布莱恩为何来到这里"}},ffd3d503={q="考布莱恩是谁？",a="考布莱恩是潜伏在哀嚎洞穴深处的尖牙德鲁伊四名堕落首领之一。他曾是纳拉雷克斯高贵教团中的一名暗夜精灵德鲁伊。该教团曾希望治愈贫瘠之地，但他最终屈服于吞噬洞穴的黑暗梦魇。受到腐化扭曲后，他如今操纵剧毒魔法，并化身为巨大的蛇形猛兽。",al={"考布莱恩是谁","考布莱恩的背景","jarlaxla"}},["3feb6d50"]={q="考布莱恩属于哪一方？",a="考布莱恩效力于尖牙德鲁伊和在哀嚎洞穴中蔓延的梦魇。他已与塞纳里奥议会和暗夜精灵彻底决裂，与纳拉雷克斯堕落的弟子并肩而立，对抗任何胆敢进入洞穴净化腐化的人。",al={"考布莱恩的阵营","考布莱恩效力于谁","考布莱恩的效忠对象"}}},fp="12,247,17.359.0,21.375.0,43.173.0,30.255.0,32.182.0,38.163.0,44.158.0,55.201.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="艾尔罗·埃伯洛克公爵",s="夜色镇的镇长艾尔罗·埃伯洛克公爵在镇政厅处理事务，在日益加剧的危险中维持秩序。暴风城鲜有援助，而镇子正面临周围林中的恐怖威胁。",h="夜色镇的镇长艾尔罗·埃伯洛克公爵在镇政厅处理事务，在日益加剧的危险中维持秩序。暴风城鲜有援助，而镇子正面临周围林中的恐怖威胁。",kw={"亚伯克隆比","阿尔泰娅","议会","夜色镇","暮色森林","埃伯洛克","艾尔罗","湖畔镇","镇长"},ang={["faction:Alliance"]="身为联盟的旅人，你会看到，在联盟被遗忘的边陲，那些孤立无援的镇长如何在暴风城鲜有援助的情况下，带领人民在噩梦般的处境中求生。",["race:Human"]="身为从暴风城出发的人类旅人，埃伯洛克公爵让你清醒地意识到，南方诸省已经衰败到何种地步，又遭受了何等冷落。"},sec={{t="困境中的镇长",b="艾尔罗·埃伯洛克公爵在镇政厅治理夜色镇，而危险正从四面逼近。这座镇子曾是繁荣的乡间乐土大村庄的一部分。如今，永不消散的阴影笼罩着这里，饥饿的食尸鬼、骸骨怪物和凶猛的野兽不断逼近镇子的边界。艾尔罗领导着夜色镇议会，竭力维持镇上仅存的公共事务。镇民为生存而苦苦挣扎，暴风城却鲜有援助。"},{t="分裂的边疆",b="夜色镇依靠守夜人这样的当地志愿民兵，因为暴风城的驻军不肯抽调士兵支援边境。他的亲属阿尔泰娅·埃伯洛克统率着守夜人。湖畔镇的所罗门镇长请求增援，以对抗黑石兽人，但埃伯洛克公爵连一名士兵也抽调不出。他向来自赤脊山的信使解释，派守卫离开森林，就会让夜色镇的家园暴露在周围邪恶势力的威胁之下。"},{t="未察觉的隐士阴谋",b="艾尔罗·埃伯洛克公爵依靠四处游历的冒险者处理林间的异常事件。为了帮助暮色森林的居民，他协调与隐士亚伯克隆比等独居者的通信。艾尔罗读不懂隐士那些晦涩的文字，也未能察觉镇外正在成形的可怖缝合怪物，直到一切几乎无法挽回。"}},faq={{q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵治理夜色镇，并领导夜色镇议会。他在镇政厅主持镇上的防御和公共事务，而这里的人类居民正为生存苦苦挣扎。",al={"艾尔罗是谁","夜色镇镇长","艾尔罗 埃伯洛克的故事"}},{q="他与指挥官阿尔泰娅·埃伯洛克是什么关系？",a="指挥官阿尔泰娅·埃伯洛克是艾尔罗公爵的亲属，统率着守夜人。他负责夜色镇的公共事务和外交事务，她则指挥守卫镇子的民兵。",al={"阿尔泰娅·埃伯洛克的亲属关系","阿尔泰娅是艾尔罗的女儿吗"}},{q="埃伯洛克公爵为何拒绝向湖畔镇派兵？",a="埃伯洛克公爵拒绝了所罗门镇长的请求，未能出兵援助他对抗赤脊山的黑石兽人。夜色镇面临亡灵和其他恐怖威胁，派走守卫会让镇子随时可能被攻陷。",al={"为何不援助赤脊山","前往夜色镇的信使","所罗门镇长 埃伯洛克"}},{q="在哪里能找到艾尔罗·埃伯洛克公爵？",a="艾尔罗·埃伯洛克公爵就在夜色镇大厅内，那里位于暮色森林东部的夜色镇中心。",al={"艾尔罗·埃伯洛克的位置","埃伯洛克镇长在哪里"}},{q="暴风城为何不派兵帮助埃伯洛克公爵？",a="瓦里安·乌瑞恩国王失踪后，内部政治纷争让暴风城的资源捉襟见肘。贵族基本上已经放弃了南部地区，埃伯洛克公爵这样的当地领袖只能自行组织防御。",al={"暴风城为何不援助暮色森林","暴风城的漠视"}},{q="埃伯洛克公爵与亚伯克隆比有何往来？",a="埃伯洛克公爵协助处理与隐士亚伯克隆比的通信，并安排翻译他那些古怪的笔记。",al={"艾尔罗 亚伯克隆比的笔记","翻译亚伯克隆比的笔记"}}},fp="19,159,19.450.0,18.472.0,29.371.1,27.186.0,48.185.0,59.213.0,39.112.0,57.242.0,54.118.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="格雷森·沙东布瑞克公爵",s="在暴风城的光明大教堂，格雷森·沙东布瑞克公爵训练圣光的勇士，指引前途可期的骑士。作为白银之手骑士团身经百战的圣骑士指挥官，他还负责监督资深圣骑士为获得神圣战马而必须完成的试炼。",h="在暴风城的光明大教堂，格雷森·沙东布瑞克公爵训练圣光的勇士，指引前途可期的骑士。作为白银之手骑士团身经百战的圣骑士指挥官，他还负责监督资深圣骑士为获得神圣战马而必须完成的试炼。",kw={"光明大教堂","战马","格雷森","格瑞曼德·艾尔默","圣骑士","通灵学院","驱影者","白银之手"},ang={["class:Paladin"]="身为圣骑士，你可以将格雷森·沙东布瑞克公爵视为联盟中资深的精神导师。他指引你在洛丹伦对抗 Scourge，并主持召唤真正战马的试炼。",["faction:Alliance"]="身为联盟的一员，你可以依靠白银之手的老兵格雷森·沙东布瑞克公爵，加强暴风城的防御，并支援前往战事胶着的北方诸国的远征。"},sec={{t="白银之手的导师",b="在暴风城，格雷森·沙东布瑞克公爵主持白银之手的事务，也是联盟最杰出的守护者之一。作为骑士团的老兵，他训练新兵的战斗技艺，考验他们对圣光的信仰。当前途可期的骑士准备就绪，他便派他们北上，奔赴西瘟疫之地战事胶着的前线。在那里，他们协助驻守寒风营地的指挥官阿什拉姆·瓦罗菲斯特。"},{t="神圣战马的试炼",b="寻求神圣战马的圣骑士，必须在格雷森·沙东布瑞克公爵的指引下证明自己的美德，并作出牺牲。试炼包括行善之举，例如通过高阶牧师洛汉帮助铁炉堡的穷人。他们还必须踏上危险的旅程，驱除恐惧谷的邪灵，并净化厄运之槌中的古老灵魂。在通灵学院，受试者必须面对死亡骑士达克雷尔，并用圣光将一匹邪恶的战马从奴役中解救出来。"}},faq={{q="在哪里可以找到格雷森·沙东布瑞克公爵？",a="格雷森·沙东布瑞克公爵位于暴风城教堂广场的光明大教堂内。他站在主厅中，督导白银之手的圣骑士。",al={"格雷森·沙东布瑞克在哪里","沙东布瑞克 位置","格雷森 公爵在哪里"}},{q="格雷森公爵对圣骑士而言担任什么角色？",a="格雷森·沙东布瑞克公爵训练联盟圣骑士。他派遣年轻骑士前往洛丹伦对抗 天灾军团 的前线，并指引他们完成神圣试炼，制作神圣马铠，获得圣骑士战马。",al={"格雷森 做什么","格雷森·沙东布瑞克的作用","为什么拜访 格雷森 公爵"}},{q="格雷森公爵失去过一只眼睛吗？",a="这一时期的记载没有说明格雷森·沙东布瑞克公爵是否失去过一只眼睛，也没有交代缘由。他以白银之手身经百战的领主和联盟最杰出的圣骑士之一而闻名。",al={"格雷森 如何失去眼睛","格雷森 为什么少一只眼睛","格雷森 眼罩"}},{q="他与被遗忘者有什么联系？",a="没有已知记载表明格雷森·沙东布瑞克公爵或他的家人与被遗忘者有联系。他是白银之手的圣骑士，派遣骑士前往洛丹伦对抗 天灾军团。",al={"格雷森 的姐妹","格雷森 是否有亡灵家人"}},{q="格雷森为什么派圣骑士去找格瑞曼德·艾尔默？",a="多年前，格瑞曼德·艾尔默为格雷森·沙东布瑞克公爵自己的战马锻造了马铠。格雷森派遣合格的受试者去找格瑞曼德，打造他们的奥金马铠，这套马铠必须兼顾坚韧的质地与灵性的和谐。",al={"格雷森 与 格瑞曼德·艾尔默","谁制作圣骑士马铠","奥金马铠任务"}}},fx={["70324968"]={q="格雷森·沙东布瑞克公爵是谁？",a="格雷森·沙东布瑞克公爵是暴风城和联盟最杰出的圣骑士之一。他是白银之手骑士团身经百战的老兵，也是这个神圣骑士团的资深导师，训练并引导有潜力的骑士遵循圣光之道。",al={"格雷森·沙东布瑞克是谁","格雷森公爵是谁","关于格雷森·沙东布瑞克"}},["2db8c97e"]={q="格雷森·沙东布瑞克公爵效忠哪一方？",a="格雷森公爵坚定地支持大联盟、暴风城王国和白银之手骑士团。他全心奉献于圣光，誓要保护生者，抵御天灾军团和其他黑暗威胁。",al={"格雷森·沙东布瑞克的阵营","格雷森为谁效力","格雷森是否属于联盟"}},["88e74201"]={q="格雷森·沙东布瑞克公爵想要什么？",a="格雷森公爵致力于培养新一代神圣勇士，击退正在吞噬艾泽拉斯的黑暗。他以艰苦的精神与武艺试炼考验圣骑士，派他们前往瘟疫之地对抗天灾军团，证明自己有资格获得受祝福的战马。",al={"格雷森·沙东布瑞克的目标","格雷森想要什么","格雷森的动机"}},a5a2c568={q="格雷森·沙东布瑞克公爵为什么在光明大教堂？",a="他驻守在暴风城的光明大教堂，督导城中圣骑士的成长。他以这座信仰核心堡垒为据点，协调针对天灾军团的任务，并引导资深勇士完成召唤神圣战马所需的严苛试炼。",al={"格雷森为什么在暴风城","格雷森为什么在这里","格雷森 光明大教堂"}},c41cec02={q="格雷森·沙东布瑞克公爵与谁有关联？",a="格雷森与铁炉堡的高阶牧师洛汉、铁匠格瑞曼德·艾尔默，以及阿什拉姆·瓦罗菲斯特等在北方对抗天灾军团的指挥官密切合作。",al={"格雷森·沙东布瑞克的盟友","格雷森认识谁","格雷森的侍从"}}},fp="26,279,25.386.0,30.464.1,44.169.0,41.206.0,29.182.0,39.167.0,49.226.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="乔拉齐·拉文霍德公爵",s="乔拉齐·拉文霍德公爵是拉文霍德的主人，这个由精锐潜行者和刺客组成的公会以奥特兰克山脉中一座隐秘的庄园为据点。他指挥组织的秘密行动，训练有潜力的成员，同时与当地的辛迪加匪徒展开激烈交战。",h="乔拉齐·拉文霍德公爵是拉文霍德的主人，这个由精锐潜行者和刺客组成的公会以奥特兰克山脉中一座隐秘的庄园为据点。他指挥组织的秘密行动，训练有潜力的成员，同时与当地的辛迪加匪徒展开激烈交战。",kw={"奥特兰克","刺客联盟","碧蓝钥匙","乔拉齐","拉文霍德","潜行者","辛迪加","克希雷姆"},ang={["class:Rogue"]="拉文霍德公爵是艾泽拉斯潜行大师最显赫的赞助人，为赢得他信任的人提供精英训练、毒药和声名显赫的委托。"},sec={{t="刺客联盟的主人",b="乔拉齐·拉文霍德公爵在奥特兰克与希尔斯布莱德之间的嶙峋山崖中，坐镇隐秘庄园，统领刺客联盟。这位出身神秘的贵族向亡命之徒、扒手和刺客敞开大门，不问其效忠何方，只要求他们技艺出众，并尊重他的权威。在他的统领下，这个组织既是盗窃大师的兄弟会，也是从事暗杀与间谍活动的独立集团。拉文霍德对辛迪加怀有刻骨的仇恨，这伙匪徒由身败名裂的奥特兰克贵族组成，他经常命令部下和来访的独行者破坏他们的营地，劫掠他们的财物。"},{t="暗影中的秘密",b="拉文霍德公爵表面上忙于当地的冲突，实际上却指挥着遍及艾泽拉斯的行动。证明了自身忠诚的潜行者会被委派执行复杂的跨大陆任务，取回受到严密看守的宝物。其中一次便是找回神秘的密封的蓝袋子，它被人从公爵手中盗走，转运到了艾萨拉的熊怪手中，必须借助大法师克希雷姆的奥术解码，以及从沉没的神庙夺来的碧蓝钥匙才能打开。拉文霍德还统筹研发致命的新配方，派遣斥候从各地古老的恐怖生物身上收集剧毒。"}},faq={{q="乔拉齐·拉文霍德公爵是谁？",a="他是刺客联盟的贵族首领，这个潜行者秘密组织的总部设在希尔斯布莱德丘陵上方群山中的拉文霍德庄园。他训练精通潜行的行动人员，并统筹秘密暗杀和情报搜集。",al={"乔拉齐是谁","拉文霍德首领","乔拉齐背景故事"}},{q="拉文霍德为何憎恨辛迪加？",a="拉文霍德的庄园正位于辛迪加争夺的领地之内，这个组织由沦为残暴匪徒的前奥特兰克贵族组成。他视他们粗野的劫掠行径为高地上的毒瘤，并派遣公会的刺客主动清剿他们的据点。",al={"为何与辛迪加为敌","拉文霍德对抗辛迪加","与辛迪加的敌对关系"}},{q="拉文霍德公爵效忠联盟还是部落？",a="拉文霍德始终作为独立组织行事。乔拉齐公爵接纳联盟和部落的潜行者进入庄园，只看重专业技艺、潜行纪律和绝对保密，不在意种族间的政治纷争。",al={"拉文霍德属于联盟吗","乔拉齐属于部落吗","拉文霍德阵营"}},{q="乔拉齐寻找的密封的蓝袋子里装着什么？",a="袋中的物品始终是受到严密保护的秘密。当有人献上碧蓝钥匙，终于打开这个附有魔法的袋子时，乔拉齐公爵沐浴在诡异的金光中，惊讶地凝视着袋内，随即迅速将它收起。",al={"密封的蓝袋子里的物品","蓝袋子之谜","乔拉齐得到了什么"}}},fp="22,140,31.533.0,22.556.1,30.242.0,39.188.0,57.204.0,49.246.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="玛克斯韦尔·泰罗索斯男爵",s="玛克斯韦尔·泰罗索斯男爵是银色黎明的最高指挥官，驻守在东瘟疫之地的前沿堡垒圣光之愿礼拜堂。他是一位参加过第三次战争的白银之手圣骑士老兵，领导这支联合力量讨伐天灾军团，并策划对斯坦索姆等遭受瘟疫侵蚀的要塞发动突袭。",h="玛克斯韦尔·泰罗索斯男爵是银色黎明的最高指挥官，驻守在东瘟疫之地的前沿堡垒圣光之愿礼拜堂。他是一位参加过第三次战争的白银之手圣骑士老兵，领导这支联合力量讨伐天灾军团，并策划对斯坦索姆等遭受瘟疫侵蚀的要塞发动突袭。",kw={"银色黎明","圣光之愿礼拜堂","圣骑士","天灾军团","白银之手","斯坦索姆","泰罗索斯"},ang={["class:Paladin"]="泰罗索斯代表着白银之手不屈的精神，在乌瑟尔死去、骑士团分裂出的派系不幸堕落之后，依然坚守着怜悯、团结与纪律的美德。",["faction:Alliance"]="泰罗索斯虽出身于洛丹伦的贵族，也是联盟的英雄，如今却将麾下部队投入一个独立组织，接纳所有愿意对抗Scourge的人。",["faction:Horde"]="与壁炉谷和血色修道院中的狂热者不同，泰罗索斯长期倡导与非人类种族合作，确保部落的战士与萨满祭司在圣光之愿礼拜堂内得到平等对待。"},sec={{t="洛丹伦的老兵",b="在惨烈的第三次战争中，玛克斯韦尔·泰罗索斯曾与光明使者乌瑟尔并肩作战，在天灾军团横扫王国时守卫安多哈尔的各处出口。洛丹伦陷落后，他加入了银色黎明，这个组织接纳一切愿意对抗天灾军团的人，与血色十字军只容纳人类的狂热信条截然不同。"},{t="黎明的指挥官",b="如今，泰罗索斯领导银色黎明，统管圣光之愿礼拜堂的防务。他在礼拜堂内的指挥所统筹遍及瘟疫之地的大规模军事行动，其中包括由尼古拉斯·瑟伦霍夫公爵率领、针对斯坦索姆废墟中瑞文戴尔男爵的战术突袭。"}},faq={{q="玛克斯韦尔·泰罗索斯男爵是谁？",a="玛克斯韦尔·泰罗索斯男爵是一位身经百战的人类圣骑士，也是银色黎明的最高领袖。他曾在第三次战争中追随光明使者乌瑟尔作战，如今指挥圣光之愿礼拜堂的防御，并统领这支联合力量净化瘟疫之地的战事。",al={"玛克斯韦尔·泰罗索斯是谁","泰罗索斯背景故事","银色黎明领袖","银色黎明首领"}},{q="泰罗索斯为何离开血色十字军？",a="没有任何记录表明泰罗索斯曾加入血色十字军。他领导的银色黎明接纳所有愿意对抗天灾军团的种族，而血色十字军的狂热者只信任信仰纯正的人类。",al={"泰罗索斯为何离开血色十字军","泰罗索斯血色十字军","泰罗索斯是否属于血色十字军"}},{q="在哪里可以找到玛克斯韦尔·泰罗索斯？",a="他位于圣光之愿礼拜堂的圣殿内，这座银色黎明的坚固要塞坐落在东瘟疫之地的最东端。",al={"泰罗索斯位置","玛克斯韦尔·泰罗索斯在哪里","泰罗索斯地图"}},{q="泰罗索斯在对斯坦索姆的战争中担任何种职责？",a="泰罗索斯与尼古拉斯·瑟伦霍夫公爵共同协调总体军事战略，派遣久经考验的冒险者和突击队攻入沦陷的斯坦索姆，消灭巫妖王在这一地区的指挥官瑞文戴尔男爵。",al={"泰罗索斯斯坦索姆","泰罗索斯 瑞文戴尔"}},{q="泰罗索斯允许任何人觐见吗？",a="泰罗索斯多年来深居军议之中，指挥前线战事，很少接见外人。冒险者通常必须赢得银色黎明的深切敬重，或带来关键情报，才能引起他的注意。",al={"能否与泰罗索斯交谈","觐见泰罗索斯"}}},fp="20,207,22.302.0,21.292.0,28.234.0,42.181.0,35.167.0,53.206.0,43.240.0"}
P.entries["npc:lord-pythas"] = {n="皮萨斯",s="皮萨斯曾是一名暗夜精灵战士，如今是哀嚎洞穴中尖牙德鲁伊的四位堕落首领之一。他原本是德鲁伊纳拉雷克斯的贴身护卫之一，却遭到了侵染地下绿洲的梦魇腐蚀。如今，他凭借强悍的武力与扭曲的毒蛇魔法，迎击任何试图接近他沉睡主人的人。",h="皮萨斯曾是一名暗夜精灵战士，如今是哀嚎洞穴中尖牙德鲁伊的四位堕落首领之一。他原本是德鲁伊纳拉雷克斯的贴身护卫之一，却遭到了侵染地下绿洲的梦魇腐蚀。如今，他凭借强悍的武力与扭曲的毒蛇魔法，迎击任何试图接近他沉睡主人的人。",kw={"尖牙德鲁伊","皮萨斯宝石","皮萨斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="皮萨斯展现了一位前途光明的侍徒的悲惨命运：他出于忠诚而研习自然魔法，翡翠梦境的腐化却将他所学的一切扭曲成了毒蛇异端的教义。",["class:Warrior"]="在被腐化为毒蛇教徒之前，皮萨斯是一名纪律严明的暗夜精灵战士，也是一名贴身护卫——他的遭遇令人警醒，仅凭武艺无法抵御心智的疯狂。",["race:NightElf"]="对于任何希望让卡利姆多伤痕累累的土地恢复平衡的暗夜精灵而言，目睹皮萨斯这样一位受人敬重的守护者陷入黑暗与疯狂，都是令人痛心的悲剧。"},sec={{t="守护者的堕落",b="在遭到腐化之前，皮萨斯是一名身经百战的暗夜精灵战士，曾作为德鲁伊纳拉雷克斯的贴身护卫，随探险队深入贫瘠之地的干旱荒野。除了磨炼武艺，他还研习德鲁伊之道，协助纳拉雷克斯实现让这片干旱土地重焕生机的梦想。然而，严苛的身体训练与战斗中的英勇，都无法抵御潜伏在地下裂隙深处、悄然侵袭的腐化。"},{t="致命的哨卫",b="当黑暗梦魇侵占了纳拉雷克斯与翡翠梦境之间的联系时，皮萨斯和其他侍徒的心智也一同沦陷。他抛弃了昔日的忠诚，成为尖牙德鲁伊的首领之一。其他毒蛇领主偏重诡诈的法术或野兽形态，皮萨斯却将致命的战斗技巧与自然魔法融为一体。如今，他游荡在洞穴蜿蜒的隧道中，决意守护梦魇对洞中泉水的扭曲掌控。"}},faq={{q="皮萨斯是谁？",a="皮萨斯原本是一名暗夜精灵战士，担任纳拉雷克斯的贴身护卫，也研习德鲁伊之道，协助主人在贫瘠之地的工作。",al={"皮萨斯是谁","皮萨斯背景故事"}},{q="他为何背弃纳拉雷克斯？",a="皮萨斯并非自愿背叛纳拉雷克斯。当纳拉雷克斯试图借助翡翠梦境的力量治愈贫瘠之地时，梦魇攫住了这位大德鲁伊的思想。腐化的梦境渗入了他麾下侍徒的心智，夺走了皮萨斯的理智，将他变成了一名毒蛇领主。",al={"皮萨斯为何堕落","皮萨斯如何陷入疯狂","他为何成为 尖牙德鲁伊 的一员"}},{q="皮萨斯与其他 尖牙 首领有何不同？",a="其他首领完全依赖自然魔法和野兽形态，皮萨斯则在接受德鲁伊训练之前，就已是一名身经百战的战士。他将战斗技巧与德鲁伊魔法相结合，成为洞穴中近身作战实力最强的守卫之一。",al={"皮萨斯战斗方式","皮萨斯与其他首领的区别"}},{q="冒险者为何需要击败他？",a="皮萨斯携带着完成尖牙德鲁伊任务所需的四颗魔法宝石之一。这个任务由雷霆崖的德鲁伊纳拉·蛮鬃交付，她需要四位 尖牙 首领各自的宝石，才能让贫瘠之地摆脱他们扭曲的梦境。",al={"尖牙德鲁伊 任务","皮萨斯宝石"}},{q="在哪里能找到皮萨斯？",a="皮萨斯潜伏在哀嚎洞穴深处的洞室中，周围尽是遭到腐化的野兽和其他 尖牙 教徒。",al={"皮萨斯位置","皮萨斯在哪里"}},{q="他的宝石最终去了哪里？",a="皮萨斯被击败后，冒险者从他的遗骸中取得皮萨斯宝石。他们将这颗宝石连同其他三位毒蛇领主的宝石一起，带给雷霆崖的纳拉·蛮鬃，以证明 尖牙 的首领已被击溃。",al={"皮萨斯宝石用途","皮萨斯宝石是什么"}}},fx={be91010a={q="皮萨斯效忠于哪一方？",a="皮萨斯效力于尖牙德鲁伊。过去，他曾是纳拉雷克斯忠诚的守护者和追随者；后来噩梦控制了他的心智，扭曲了他的忠诚。如今，他完全站在这个叛变教派一边，挥舞刀刃并施展自然魔法守护噩梦，而非保护他曾发誓守护的主人。",al={"皮萨斯所属阵营","皮萨斯是联盟成员吗","皮萨斯效力于谁"}},a058df7c={q="皮萨斯想要什么？",a="纳拉雷克斯沉睡时遭噩梦侵染，皮萨斯因此陷入疯狂，决意守护哀嚎洞穴，不让任何人前来净化它。失去理智的他只想消灭威胁噩梦控制力的入侵者，将自己的武技和德鲁伊之力尽数用于守护这片被腐化的领地。",al={"皮萨斯的目标","皮萨斯想做什么","皮萨斯的动机"}},d8d94386={q="皮萨斯为什么在哀嚎洞穴？",a="皮萨斯最初进入洞穴，是纳拉雷克斯为恢复贫瘠之地而行动时的贴身护卫之一。纳拉雷克斯的冥想陷入无法摆脱的噩梦后，皮萨斯与其他弟子一同屈服于腐化，留在洞穴深处，成为尖牙德鲁伊的一名堕落守卫。",al={"皮萨斯为什么在哀嚎洞穴","皮萨斯身处此地的原因","皮萨斯如何来到这里"}},d87430fd={q="皮萨斯与哪些人有关联？",a="陷入疯狂之前，皮萨斯曾是德鲁伊纳拉雷克斯的贴身护卫之一。他前往地下泉水处保护纳拉雷克斯，同时学习德鲁伊之道；然而，无处不在的腐化摧毁了他的心智，使他与其他扭曲的尖牙首领沆瀣一气。",al={"皮萨斯与纳拉雷克斯","皮萨斯的人际关系","皮萨斯认识谁"}},eb0bbb13={q="皮萨斯为何令人畏惧？",a="皮萨斯被视为尖牙首领中最强悍的一位。许多追随者只依赖自然法术，而皮萨斯在学习德鲁伊之道前就是一名经验丰富的战士。他兼具致命的近战本领、强悍的体魄和黑暗的德鲁伊魔法，对任何探险队而言都极其危险。",al={"皮萨斯危险吗","皮萨斯为何难以对付","皮萨斯的实力"}}},fp="11,232,16.294.0,19.381.0,19.141.0,32.250.0,56.164.0,38.168.0,31.111.0,24.206.0"}
P.entries["npc:lord-serpentis"] = {n="瑟芬迪斯",s="瑟芬迪斯是一位堕落的暗夜精灵德鲁伊，也是哀嚎洞穴中那些离经叛道的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的德鲁伊，但当纳拉雷克斯的梦境在地底深泉中化为噩梦时，他也随之陷入了疯狂。现在，他在洞穴深处协助指挥那个崇拜毒蛇的教派，而堕落的纳拉雷克斯正沉睡在那里。",h="瑟芬迪斯是一位堕落的暗夜精灵德鲁伊，也是哀嚎洞穴中那些离经叛道的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的德鲁伊，但当纳拉雷克斯的梦境在地底深泉中化为噩梦时，他也随之陷入了疯狂。现在，他在洞穴深...",kw={"尖牙德鲁伊","瑟芬迪斯宝石","尖牙德鲁伊的首领","瑟芬迪斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="瑟芬迪斯代表了潜藏在翡翠梦境中的悲剧性危险，展示了当高尚的愿景变成噩梦时，即使是极其强大的德鲁伊也可能走向扭曲。",["race:NightElf"]="对暗夜精灵而言，瑟芬迪斯和他的追随者是一场痛苦的耻辱——这些曾享有盛誉的卡多雷学者抛弃了对自然的的神圣职责，沦为了可怕的毒蛇领主。",["race:Tauren"]="牛头人将瑟芬迪斯的堕落视为对大地母亲平衡的亵渎，认为这以非自然的疯狂威胁着贫瘠之地脆弱的生态系统。"},sec={{t="从高贵的德鲁伊到毒蛇之王",b="在黑暗笼罩洞穴之泉前，瑟芬迪斯是一位极具力量和威望的德鲁伊，隶属于纳拉雷克斯领导的高贵教团，他们曾希望利用洞穴之泉和翡翠梦境来治愈贫瘠之地。然而，当纳拉雷克斯的愿景变成了一场腐蚀性的噩梦时，瑟芬迪斯与其他德鲁伊一样，心智也随之陷入了疯狂。"},{t="尖牙之王",b="瑟芬迪斯和他的同僚们完全屈服于从纳拉雷克斯扭曲的梦境中散发出的腐蚀力量，成为了尖牙德鲁伊。他们背弃了传统的塞纳里奥平衡和古老的图腾动物，现在试图重塑贫瘠之地以符合他们扭曲的梦境，而非治愈它。瑟芬迪斯与安娜科德拉、考布莱恩和皮萨斯一起，作为四位首领之一统治着这个教派。"},{t="最后的阻碍",b="瑟芬迪斯盘踞在蜿蜒洞穴的深处，他是该离经叛道教派的四位首领之一，每一位首领都携带一颗梦境宝石。那些试图唤醒被困大师或收复绿洲之水的人，必须击倒瑟芬迪斯并夺取他携带的宝石，以此打破毒蛇对这座迷宫的控制。"}},faq={{q="谁是瑟芬迪斯？",a="瑟芬迪斯是哀嚎洞穴深处的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的暗夜精灵德鲁伊，后来和他的同僚们一起被纳拉雷克斯的噩梦所腐蚀。",al={"谁是瑟芬迪斯","瑟芬迪斯背景故事","瑟芬迪斯背景"}},{q="瑟芬迪斯为什么会堕落？",a="当纳拉雷克斯试图通过翡翠梦境治愈贫瘠之地的尝试变成一场噩梦时，腐蚀力量蔓延到了跟随他的德鲁伊身上，导致瑟芬迪斯的心智陷入疯狂并开始崇拜毒蛇。",al={"瑟芬迪斯为何堕落","瑟芬迪斯的腐蚀","瑟芬迪斯为何变邪恶"}},{q="他与纳拉雷克斯是什么关系？",a="瑟芬迪斯曾是跟随纳拉雷克斯进入洞穴的高贵德鲁伊之一。他没有协助大师恢复，反而成为了尖牙德鲁伊的首领，他们现在试图重塑贫瘠之地以符合自己扭曲的梦境。",al={"瑟芬迪斯与纳拉雷克斯","瑟芬迪斯与纳拉雷克斯的关系","纳拉雷克斯的学徒"}},{q="玩家为什么要杀掉他？",a="瑟芬迪斯是尖牙德鲁伊的四位首领之一。消灭他是打破该教派对哀嚎洞穴控制的关键，这能确保玩家获得任务“尖牙德鲁伊的首领”所需的宝石，并为唤醒纳拉雷克斯扫清道路。",al={"为什么要杀瑟芬迪斯","尖牙德鲁伊的首领瑟芬迪斯","瑟芬迪斯宝石"}},{q="什么是尖牙德鲁伊？",a="他们是跟随纳拉雷克斯进入哀嚎洞穴的一群离经叛道的暗夜精灵德鲁伊。在翡翠梦魇的腐蚀下，他们在瑟芬迪斯和其他尖牙领主的指挥下放弃了传统的德鲁伊形态，转而采用毒蛇的外貌、毒液和行为。",al={"尖牙德鲁伊背景故事","什么是尖牙德鲁伊","尖牙德鲁伊"}}},fx={["1f07cf4d"]={q="瑟芬迪斯效忠于哪一方？",a="瑟芬迪斯是尖牙德鲁伊的首领。他受到导师纳拉雷克斯体内噩梦的腐化，背弃了塞纳里奥议会和暗夜精灵的理想，对所有进入洞穴的人都充满敌意。",al={"瑟芬迪斯所属阵营","瑟芬迪斯效力于谁","瑟芬迪斯的忠诚对象"}},e8a94e96={q="瑟芬迪斯想要什么？",a="他曾是纳拉雷克斯弟子中声望卓著、力量强大的德鲁伊，后来心智被噩梦扭曲，陷入疯狂。如今神志错乱的他，妄图与扭曲的追随者一同统治洞穴，自称蛇王。",al={"瑟芬迪斯的目标","瑟芬迪斯想要什么","瑟芬迪斯的动机"}},["33635f36"]={q="瑟芬迪斯为什么在哀嚎洞穴？",a="瑟芬迪斯最初来到哀嚎洞穴时，是纳拉雷克斯的一名德鲁伊，帮助导师汲取地下泉水的力量，让贫瘠之地恢复生机。纳拉雷克斯失去对梦境的控制、噩梦腐化爆发后，瑟芬迪斯也成了精神折磨的受害者，留在洞穴中，成为尖牙德鲁伊的统治者。",al={"瑟芬迪斯为什么在这里","瑟芬迪斯为什么在哀嚎洞穴","瑟芬迪斯身处此地的原因"}}},fp="14,282,32.335.0,18.354.0,18.286.1,22.205.0,28.194.0,36.195.0,32.160.0,31.272.0"}
P.entries["npc:lord-shalzaru"] = {n="沙尔扎鲁",s="沙尔扎鲁是憎世娜迦的暴虐首领，盘踞在菲拉斯近海的恐怖之岛。他以极端残酷的手段统治着蛇形部众，监督他们在沉没的精灵聚落及其废墟中大肆挖掘。他最近发现了一件奇异的古老遗物，引来了外界调查者的注意，他们急于将其从他手中夺走。",h="沙尔扎鲁是憎世娜迦的暴虐首领，盘踞在菲拉斯近海的恐怖之岛。他以极端残酷的手段统治着蛇形部众，监督他们在沉没的精灵聚落及其废墟中大肆挖掘。他最近发现了一件奇异的古老遗物，引来了外界调查者的注意，他们急于将其从他手中夺走。",kw={"菲拉斯","憎世","恐怖之岛","沙尔扎鲁","神秘遗物","娜迦"},ang={["faction:Alliance"]="夺取沙尔扎鲁的遗物并铲除这名憎世军阀，有助于保护菲拉斯荒蛮海岸上偏远的联盟哨站。",["faction:Horde"]="部落斥候密切关注着菲拉斯沿海的威胁，击杀这名娜迦领主，就能消除莫沙彻营地利益范围附近一个难以预测的隐患。",["race:NightElf"]="憎世娜迦亵渎着古老卡利姆多的远古废墟；从沙尔扎鲁手中夺回遗物，便能阻止上层精灵的黑暗遗产为他的蛇形同族增添力量。"},sec={{t="憎世之主",b="沙尔扎鲁统领憎世娜迦，指挥他们在菲拉斯南部海岸活动。他藏身于恐怖之岛一处洞穴内的地下巢穴，凭借残酷手段与冷酷权威维持统治。在他的指挥下，憎世搜遍古老卡利姆多的远古废墟，寻找大分裂遗留下来的失落宝藏与强大遗物。"},{t="神秘遗物",b="在恐怖之岛主要废墟以南的挖掘中，沙尔扎鲁亲手发现了一件奇异的古老遗物。这件神器的用途与力量仍是谜团，但它落入如此强大的娜迦军阀之手，显然构成了威胁。大陆上的密探正在寻找英勇的勇士，深入蛇形生物的巢穴，终结沙尔扎鲁的统治，并在憎世将这件古怪遗物用于更黑暗的目的之前夺取它。"}},faq={{q="沙尔扎鲁是谁？",a="沙尔扎鲁是憎世娜迦残忍的王族首领。他在菲拉斯近海的恐怖之岛上统领娜迦部队，并监督挖掘工作。",al={"沙尔扎鲁背景故事","沙尔扎鲁","沙尔扎鲁是谁"}},{q="在哪里可以找到沙尔扎鲁？",a="他的巢穴位于菲拉斯西南海岸外、隔海相望的恐怖之岛上，在主要精灵废墟以南的一处洞穴中。",al={"沙尔扎鲁位置","沙尔扎鲁在哪里","恐怖之岛洞穴"}},{q="憎世是什么？",a="憎世是一个敌对的娜迦部族，占据着菲拉斯的海岸与岛屿，以在沙尔扎鲁的指挥下搜掠远古废墟、肆虐沿海水域而闻名。",al={"憎世娜迦","憎世部族"}},{q="沙尔扎鲁持有什么遗物？",a="最近在恐怖之岛的一次挖掘中，沙尔扎鲁发现了一件来历与力量皆不明的神秘古老遗物，促使大陆上的势力派遣冒险者前去夺取。",al={"沙尔扎鲁遗物","菲拉斯神秘遗物"}},{q="为什么必须击败沙尔扎鲁？",a="除掉沙尔扎鲁就能瓦解憎世在恐怖之岛上的领导层，让冒险者赶在娜迦利用那件神秘遗物之前，将他最近挖出的遗物夺走。",al={"对抗沙尔扎鲁","击杀沙尔扎鲁"}},{q="憎世在菲拉斯挖掘什么？",a="憎世正在挖掘毁于大灾变的暗夜精灵聚落废墟，寻找埋藏在泥土与波涛之下的强大魔法遗物，以及上层精灵的历史遗存。",al={"憎世挖掘","娜迦为什么在菲拉斯"}}},fp="13,193,23.265.0,20.316.0,21.108.0,33.117.0,22.159.0,38.167.0,35.141.0,46.175.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="博学者诺拉·暴雨图腾",s="在赤色石南边，博学者诺拉·暴雨图腾照看着莫高雷的神圣墓地。他请求旅者赶走侵扰墓地的刺背野猪人。",h="在赤色石南边，博学者诺拉·暴雨图腾照看着莫高雷的神圣墓地。他请求旅者赶走侵扰墓地的刺背野猪人。",kw={"博学者诺拉·暴雨图腾","莫高雷","暴雨图腾","赤色石","神圣墓地"},ang={["class:Shaman"]="身为萨满祭司，帮助暴雨图腾守护赤色石，是你对不安亡灵应尽的职责，能让先祖之灵得到安宁与敬重。",["race:Tauren"]="身为牛头人，帮助暴雨图腾保卫赤色石，既是对先祖的敬重，也能守护族人的丧葬传统。"},sec={{t="赤色石的守望者",b="博学者诺拉·暴雨图腾照看着莫高雷赤色石附近的族人圣墓。刺背干涉者侵扰着这片安息之地，他请求旅者将他们赶走，让先祖得以安息。"},{t="先祖墓地的守护者",b="博学者诺拉·暴雨图腾守护着赤色石的墓地。刺背野猪人侵扰着牛头人酋长和萨满祭司的安息之地。暴雨图腾呼吁旅者为这片墓地及其中的逝者恢复安宁与尊严。"}},faq={{q="在哪里可以找到博学者诺拉·暴雨图腾？",a="博学者诺拉·暴雨图腾位于莫高雷北部，就在赤色石南边，通往先祖崖壁的小路旁。",al={"暴雨图腾位置","博学者诺拉·暴雨图腾在哪","莫高雷寻找暴雨图腾"}},{q="暴雨图腾为何寻求帮助守护墓地？",a="暴雨图腾请求旅者将刺背干涉者赶出赤色石，他们正在那里蹂躏牛头人的神圣墓地。",al={"暴雨图腾神圣墓地","为何帮助暴雨图腾","赤色石墓地"}},{q="暴雨图腾为何需要有人在赤色石帮忙？",a="赤色石是牛头人的神圣墓地，刺背野猪人正在蹂躏这片土地。暴雨图腾请求有能力的旅者整肃这片遭到亵渎的先祖墓地。",al={"赤色石的问题","为何要做神圣墓地任务"}}},fp="20,150,20.215.0,29.236.0,38.114.0,53.124.0,42.163.0"}
P.entries["npc:lorgus-jett"] = {n="洛古斯·杰特",s="在黑暗深渊被水淹没的废墟中，洛古斯·杰特指挥着暮光之锤。部落已将他列为目标。",h="在黑暗深渊被水淹没的废墟中，洛古斯·杰特指挥着暮光之锤。部落已将他列为目标。",kw={"上古之神的仆从","黑暗深渊","洛古斯·杰特","月光神殿废墟","暮光之锤"},ang={["class:Shaman"]="身为萨满祭司，你怀着和谐或敬畏之心驾驭元素；杰特则使用暮光之锤腐化而暴戾的手段。",["faction:Horde"]="身为部落的一员，你可以击杀洛古斯·杰特，帮助铲除灰谷海岸下方暮光之锤的首领。",["race:Human"]="身为人类，你或许会觉得，杰特远在西方的卡利姆多侍奉宇宙中的恐怖存在，令人不寒而栗，也表明了暮光之锤的势力所及之广。"},sec={{t="废墟中的亵渎者",b="洛古斯·杰特是黑暗深渊中暮光之锤的一名人类成员。那里的许多邪教徒都是兽人或牛头人，而杰特的活动范围从上层的月光神殿废墟一直延伸到鱼人亵渎者格里哈斯特所在之处更深处的隧道。他在这片古老的暗夜精灵废墟中统筹邪教的仪式与暴力图谋。"}},faq={{q="洛古斯·杰特是谁？",a="洛古斯·杰特在黑暗深渊内为暮光之锤效力。他监督邪教在月光神殿废墟的活动，并侍奉上古之神。",al={"洛古斯·杰特故事","洛古斯是谁","洛古斯·杰特背景"}},{q="在黑暗深渊的哪里能找到洛古斯·杰特？",a="洛古斯·杰特在月光神殿废墟巡逻。他可能在最初几群暮光邪教徒附近，也可能在越过格里哈斯特的神殿后，更深处被水淹没的通道里。",al={"洛古斯·杰特位置","洛古斯·杰特在哪","寻找洛古斯·杰特"}},{q="部落为何要除掉洛古斯·杰特？",a="部落通过上古之神的仆从任务寻求除掉洛古斯·杰特。他在灰谷的存在威胁着当地的稳定，而他效力的同盟致力于释放足以毁灭世界的远古存在。",al={"为何击杀洛古斯","上古之神的仆从任务"}},{q="一个人类为何会使用萨满之力？",a="暮光之锤与混乱的元素力量及上古之神沟通，而非传统的先祖之灵。这条道路让人类也能驾驭元素的毁灭之力。",al={"洛古斯·杰特魔法","人类萨满祭司洛古斯"}},{q="洛古斯·杰特与格里哈斯特有何关联？",a="洛古斯·杰特和格里哈斯特都居于黑暗深渊的月光神殿废墟，侍奉海底的黑暗力量。杰特经常在格里哈斯特祭坛后方的走廊中巡逻。",al={"洛古斯与格里哈斯特","格里哈斯特的关联"}}},fp="11,122,22.297.0,19.143.0,52.156.0,41.207.0,40.171.0,45.177.0"}
P.entries["npc:loslor-rudge"] = {n="罗斯洛·鲁治",s="在钢架补给站，罗斯洛·鲁治为丹莫罗的工匠供应物资。他的货物翻越积雪的山脊，送到枪械师海格纳·重枪等工匠手中。",h="在钢架补给站，罗斯洛·鲁治为丹莫罗的工匠供应物资。他的货物翻越积雪的山脊，送到枪械师海格纳·重枪等工匠手中。",kw={"弹药","丹莫罗","工程学","灰色洞穴","海格纳·重枪","罗斯洛·鲁治","钢架补给站"},ang={["profession:Engineering"]="罗斯洛备有实用的工程学物资，包括助熔剂、火药、管材和工匠工具包。途经丹莫罗的工程师可以方便地在他的补给站补充物资。",["race:Dwarf"]="和丹莫罗的许多工匠一样，罗斯洛依赖连接各处分散矮人营地的可靠驮运路线。雪怪可能扰乱山间的贸易。"},sec={{t="雪中的供应商",b="罗斯洛·鲁治在钢架补给站供应工程学物资，从卡拉诺斯沿路走不远就能找到他。他的存货包括铜质调节器、青铜管、火药和扳手。恶劣的天气与分散各处的工坊让这些零件始终供不应求，因此罗斯洛忙着为当地的机械爱好者提供补给。\n\n穿越荒野，在哨站之间运送货物可能危机四伏。在灰色洞穴附近，雪怪赶跑了一名抄近路的信使。信使丢下了一批弹药，那原本是要送给罗斯洛的重要客户——枪械师海格纳·重枪的。"}},faq={{q="罗斯洛·鲁治是谁？",a="罗斯洛·鲁治在丹莫罗的钢架补给站供应工程学物资。他的商店为当地的工匠和手艺人提供工具、零件与弹药。",al={"罗斯洛·鲁治","鲁治是谁","钢架补给站工程师"}},{q="罗斯洛遇到了什么麻烦，需要帮助？",a="罗斯洛需要有人找回一批遗落在雪地里的弹药。一名信使原本要给枪械师海格纳·重枪送货，却在灰色洞穴附近被雪怪赶跑，丢下了货箱。",al={"重枪的弹药任务","鲁治需要什么","鲁治的信使"}},{q="钢架补给站在哪里？",a="钢架补给站就在卡拉诺斯以东，位于通往洛克莫丹的大路旁。那里既是矮人的集结地，也是一处机械工坊。",al={"钢架补给站在哪里","钢架补给站位置"}},{q="海格纳·重枪是谁？",a="海格纳·重枪是一名矮人枪械师，驻扎在丹莫罗的一处营地。他依靠罗斯洛·鲁治补充弹药和机械零件。",al={"海格纳是谁","重枪"}}},fx={["774accc1"]={q="罗斯洛·鲁治效忠哪一方？",a="罗斯洛·鲁治是铁炉堡矮人社群和联盟的忠诚一员。他以钢架补给站为据点，经营生意，直接支持丹莫罗各地的矮人火枪手、工匠和附近的聚落。",al={"罗斯洛·鲁治的阵营","罗斯洛·鲁治是否属于联盟","罗斯洛·鲁治为谁效力"}},["1a06e65e"]={q="罗斯洛·鲁治为什么在钢架补给站？",a="罗斯洛在钢架补给站经营生意，是一名工程学供应商和商人。补给站是铁炉堡外繁忙的矮人机械、维修和工业枢纽，因此很适合他出售工匠零件、火药，并为当地的枪械匠制作弹药。",al={"罗斯洛·鲁治为什么在这里","罗斯洛·鲁治在钢架补给站的职责","罗斯洛为什么在补给站"}}},fp="12,164,22.545.0,20.165.0,40.200.0,28.138.0,25.138.0"}
P.entries["npc:lotwil-veriatus"] = {n="鲁特维尔·沃拉图斯",s="鲁特维尔·沃拉图斯是一位古怪的侏儒学者，在荒芜之地尘土飞扬的荒野中进行危险的元素实验。他驻扎在卡加斯以东，与言语尖刻的学徒卢希恩·枪穗和名叫阿布的机械侍从一起，致力于将奥术理论、炼金术和工程学融为一门学科。",h="鲁特维尔·沃拉图斯是一位古怪的侏儒学者，在荒芜之地尘土飞扬的荒野中进行危险的元素实验。他驻扎在卡加斯以东，与言语尖刻的学徒卢希恩·枪穗和名叫阿布的机械侍从一起，致力于将奥术理论、炼金术和工程学融为一门学科。",kw={"荒芜之地","元素","法姆雷托","卡加斯","鲁特维尔","卢希恩","阿布","沃拉图斯"},ang={["profession:Engineering"]="工程师会理解鲁特维尔将机械陀螺和齿轮融入奥术禁锢力场的雄心，也会认出工程学中那种典型的隐患：突如其来、破坏力惊人的故障。",["race:Gnome"]="鲁特维尔将侏儒求知的雄心推向了鲁莽的极端，不顾可能酿成灾难的风险，一心要将工程学与奥术融会贯通。"},sec={{t="混乱的统一领域",b="鲁特维尔来自丹莫罗的卡拉诺斯，梦想着为自己的奥术学、炼金术与工程学启蒙协会建立一所宏伟的大学。他认为，这三门学科不该各自为政，而应相互融合。为了实现这个梦想，他选择环境恶劣的荒芜之地作为实验室，研究当地的岩石元素，并制造能够驾驭元素之力的禁锢镣铐。他曾研究元素机械，也曾击败黑铁构造体，是一位颇有成就的研究者，但他一心扑在研究上，常常忽视野外实验中可能引发爆炸的危险。"},{t="元素镣铐",b="鲁特维尔在荒芜之地的宏大抱负，核心就是测试他的元素禁锢镣铐。他委托冒险者收集岩石元素核心、冷却剂和陀螺仪，为一场旨在降服元素仆从的复杂仪式做准备。然而，当禁锢装置终于启动时，狂暴的魔法、运转失常的机械和不稳定的炼金试剂交织在一起，引发了灾难性的事故，召出一个名叫法姆雷托的高大而狂怒的元素怪物，反过来攻击了它的创造者。"}},faq={{q="鲁特维尔·沃拉图斯是谁？",a="鲁特维尔·沃拉图斯是一位侏儒博学之士，住在荒芜之地卡加斯以东一处偏僻的营地里。他是奥术学、炼金术与工程学启蒙协会的创始成员之一，试图将这三个领域融为一门学科。",al={"鲁特维尔是谁","鲁特维尔·沃拉图斯的故事","荒芜之地的侏儒"}},{q="鲁特维尔为什么会在荒芜之地？",a="鲁特维尔来到荒芜之地，是为了研究这里密集分布的野生岩石元素。开阔的沙漠既能提供原始的元素材料，也有足够的空间进行不稳定的禁锢实验，不至于危及主要的人口聚居地。",al={"鲁特维尔为何在荒芜之地","鲁特维尔在荒芜之地的营地","鲁特维尔在做什么"}},{q="卢希恩·枪穗是谁？",a="卢希恩·枪穗是鲁特维尔饱受折腾的侏儒助手。卢希恩满腹讥诮，早已被师父古怪的絮叨弄得疲惫不堪，负责管理后勤、修理机械仆从阿布，还时常提醒旁人提防鲁特维尔危险的粗心大意。",al={"卢希恩·枪穗","鲁特维尔的助手","鲁特维尔的学徒"}},{q="鲁特维尔完成实验时会发生什么？",a="鲁特维尔试图用自己特制的元素束缚镣铐奴役一个元素构造体。这种融合多门学科的技术出了严重故障，召出一个名叫法姆雷托的巨大岩石元素，狂怒不已，必须在它摧毁营地之前将其击杀。",al={"鲁特维尔实验失败","元素束缚镣铐","法姆雷托"}}},fp="15,258,24.537.0,22.411.1,23.239.0,34.194.0,27.202.0,49.236.1"}
P.entries["npc:lucius"] = {n="卢修斯",s="在湖畔镇的码头，卢修斯为暴风城的SI:7监视着赤脊山沿岸。这位矮人隐姓埋名，协助特工开展侦察并练习专业技能。",h="在湖畔镇的码头，卢修斯为暴风城的SI:7监视着赤脊山沿岸。这位矮人隐姓埋名，协助特工开展侦察并练习专业技能。",kw={"码头","矮人","湖畔镇","开锁","卢修斯","赤脊山","潜行者","si:7"},ang={["class:Rogue"]="作为一名从暴风城被派往东方的潜行者，你可以向卢修斯请教开锁和侦察技巧。",["race:Dwarf"]="身为矮人，卢修斯展现了你们族人的才干如何既用于锻造和前线作战，也为暴风城的秘密行动效力。"},sec={{t="群山中的耳目",b="卢修斯为暴风城的情报机构SI:7监视湖畔镇的码头。他留意贸易往来、异常的人员与货物流动，以及进入赤脊山的威胁。从暴风城向东派出的特工会来找他，协调秘密行动，并练习开锁等实地技能。通过卢修斯，暴风城的力量悄然延伸到了艾尔文森林之外。"}},faq={{q="卢修斯是谁？",a="卢修斯是湖畔镇的一名矮人特工，为暴风城的情报机构SI:7效力。",al={"卢修斯身份","码头上的矮人是谁","卢修斯非玩家角色"}},{q="卢修斯在湖畔镇做什么？",a="卢修斯向秘密特工传授当地的偷窃和开锁技巧，同时监视赤脊山各处的动向。",al={"卢修斯在这里做什么","卢修斯的作用","卢修斯为什么在码头"}},{q="哪些任务与卢修斯有关？",a="卢修斯负责军情七处的“赤脊山的联络员”任务。他还会派年轻的潜行者前往奥瑟尔伐木场，打开那里的箱锁，以取得偷窃技能认证书。",al={"卢修斯任务","赤脊山的联络员任务","奥瑟尔伐木场"}}},fx={f414b59e={q="卢修斯效忠哪一方？",a="卢修斯坚定地支持联盟，并直接听命于SI:7，这是暴风城精锐的情报与秘密行动机构。虽然他在湖畔镇码头一带活动时十分低调，但他直接效忠于首都的间谍首脑。",al={"卢修斯的阵营","卢修斯的效忠对象","卢修斯为谁效力"}},db7d3191={q="卢修斯想要什么？",a="卢修斯是SI:7的一名低调的外勤特工。他密切关注止水湖周围和赤脊山边境的动向，与来访的特工联络，并指引那些受命在群山各处执行敏感任务的潜力探员。",al={"卢修斯在做什么","卢修斯需要什么","卢修斯的目标"}},["2f7f1e59"]={q="卢修斯与谁有联系？",a="卢修斯与以暴风城为基地的情报网络SI:7有直接联系。他是该组织在赤脊山的秘密联络人，与派往当地的其他特工合作，执行秘密侦察和特殊行动。",al={"卢修斯隶属谁","卢修斯的关系","卢修斯 si7"}}},fp="6,167,21.345.0,14.92.0,33.115.0,28.167.0"}
P.entries["npc:lyria-du-lac"] = {n="里瑞亚·杜拉克",s="在闪金镇，里瑞亚·杜拉克在村中铁匠铺后方训练年轻的战士。她指导他们掌握战斗姿态和武器的使用。",h="在闪金镇，里瑞亚·杜拉克在村中铁匠铺后方训练年轻的战士。她指导他们掌握战斗姿态和武器的使用。",kw={"战士的训练","铁匠","艾尔文森林","闪金镇","里瑞亚·杜拉克","战士训练师"},ang={["class:Warrior"]="作为一名刚从北郡修道院出来的战士，你会遇到里瑞亚·杜拉克，她是你在艾尔文森林的第一位重要训练师。她帮助你掌握战斗姿态，磨炼近战战术。",["faction:Alliance"]="在闪金镇的铁匠铺后方，里瑞亚·杜拉克训练当地新兵，保卫暴风城的腹地，抵御迪菲亚匪徒和豺狼人掠夺者。"},sec={{t="闪金镇的战士训练师",b="在闪金镇的铁匠铺后方，里瑞亚·杜拉克训练刚从北郡修道院出来的战士。她判断他们何时准备就绪，并传授专门的战斗技巧。那些为暴风城拿起盾牌与刀剑的人，必须面对艾尔文森林中的危险。"}},faq={{q="在哪里可以找到里瑞亚·杜拉克？",a="在闪金镇，里瑞亚·杜拉克位于铁匠铺后方，就在狮王之傲旅店西边。",al={"里瑞亚·杜拉克位置","里瑞亚在哪里","闪金镇战士训练师"}},{q="里瑞亚·杜拉克提供什么服务？",a="随着战士的技艺日益精进，里瑞亚·杜拉克会教导他们战斗招式、姿态和作战要领。",al={"里瑞亚做什么","里瑞亚·杜拉克职责","里瑞亚教什么"}},{q="哪些任务与里瑞亚·杜拉克有关？",a="里瑞亚·杜拉克向成长中的战士提供“战士的训练”任务。她派他们前往暴风城旧城区的猪和哨声旅店，寻找老兵哈里·伯加德。",al={"里瑞亚·杜拉克任务","闪金镇战士任务"}}},fx={f698c0e4={q="里瑞亚·杜拉克是谁？",a="里瑞亚·杜拉克是一位经验丰富的人类战士，在艾尔文森林担任战斗教官。她驻守在闪金镇的铁匠铺后方，考察并指导那些即将前往王国各地的新手战士，教他们发挥战斗本领，在威胁暴风城边境的种种危险中生存下来。",al={"里瑞亚是谁","里瑞亚·杜拉克的背景","里瑞亚·杜拉克是谁"}},["34434421"]={q="里瑞亚·杜拉克站在哪一边？",a="里瑞亚坚定地效忠于暴风城王国和联盟。她训练新兵抵御强盗和豺狼人等当地威胁，保卫艾尔文森林，在正规驻军兵力捉襟见肘之际，帮助王国加强战备。",al={"里瑞亚·杜拉克的阵营","里瑞亚·杜拉克效忠谁","里瑞亚为谁效力"}},afd6a9c2={q="里瑞亚·杜拉克为什么在闪金镇？",a="闪金镇是离开北郡山谷的旅人的天然集结地，也是向有潜力的冒险者传授武器技艺的理想地点。里瑞亚驻守在铁匠铺正后方，确保每一位来到镇上的年轻战士都接受充分的体能和纪律训练，再去面对更大的危险。",al={"里瑞亚为何在闪金镇","里瑞亚·杜拉克驻留的目的","里瑞亚为何来到这里"}},["277e5774"]={q="里瑞亚·杜拉克想要什么？",a="里瑞亚寻找的是有能力、愿意掌握战斗技艺的学徒。她希望看到年轻战士磨炼自律，掌握战斗姿态与技巧，并运用所学保卫王国，抵御一切威胁和平的动乱。",al={"里瑞亚想要什么","里瑞亚·杜拉克的目标","里瑞亚·杜拉克的动机"}}},fp="12,130,28.251.0,30.94.0,39.101.0,33.159.0"}
P.entries["npc:ma-stonefield"] = {n="斯通菲尔德妈妈",s="在艾尔文西部的斯通菲尔德农场，斯通菲尔德妈妈操心着家门口的种种麻烦。波尼斯老太太陪在她身旁，与她一同应对农场的艰辛、邻里间的纷争和害兽的侵扰。",h="在艾尔文西部的斯通菲尔德农场，斯通菲尔德妈妈操心着家门口的种种麻烦。波尼斯老太太陪在她身旁，与她一同应对农场的艰辛、邻里间的纷争和害兽的侵扰。",kw={"波尼斯·斯通菲尔德","艾尔文森林","斯通菲尔德妈妈","公主","公主必须死","斯通菲尔德农场"},ang={["faction:Alliance"]="作为艾尔文森林中的联盟冒险者，你可以帮助斯通菲尔德妈妈这样勤劳的农户，守护暴风城的农业支柱。"},sec={{t="农庄的烦恼",b="斯通菲尔德妈妈照看着艾尔文森林西南部的农场，家里的小屋就在一旁。波尼斯·斯通菲尔德一直陪在她身边。邻近的马科伦农庄和附近的南瓜田也不太平。野猪威胁着斯通菲尔德一家的庄稼，其中 公主 惹出的麻烦最大。这头体型庞大的获奖母猪践踏田地，吞食着这家人辛苦种出的庄稼。"}},faq={{q="斯通菲尔德妈妈是谁？",a="斯通菲尔德妈妈是斯通菲尔德家族的一位长辈。她与波尼斯老太太等亲人一起，住在艾尔文森林西南部的自家农庄里。",al={"斯通菲尔德妈妈是谁","斯通菲尔德妈妈","斯通菲尔德 妈妈"}},{q="在哪里可以找到斯通菲尔德妈妈？",a="斯通菲尔德妈妈站在斯通菲尔德农场主屋前的空地上，农场位于艾尔文森林的闪金镇以西。",al={"斯通菲尔德妈妈位置","斯通菲尔德妈妈在哪","斯通菲尔德农场位置"}},{q="斯通菲尔德妈妈需要解决什么问题？",a="斯通菲尔德妈妈希望有人帮忙阻止 公主，这头获奖的巨猪一再冲进附近的田地肆虐，吞食当地的庄稼。",al={"斯通菲尔德妈妈任务","公主 母猪任务","公主必须死！ 任务给予者"}}},fx={["51af3003"]={q="斯通菲尔德妈妈站在哪一边？",a="斯通菲尔德妈妈是暴风城王国的忠诚子民，也是联盟的一员。和大多数住在艾尔文森林腹地的乡民一样，她一心操持自家的农场，不过，当地的麻烦一旦超出普通农民的应对能力，她也得依靠联盟冒险者出手相助。",al={"斯通菲尔德妈妈属于联盟吗","斯通菲尔德妈妈的阵营"}},["02537c40"]={q="斯通菲尔德妈妈为什么在这里？",a="斯通菲尔德农场是斯通菲尔德妈妈一辈子的家。她与亲人一起在艾尔文森林生活、耕作，在家族宅邸外操持着乡间日常事务，波尼斯·斯通菲尔德姑妈就住在近旁。",al={"斯通菲尔德妈妈为何在农场","斯通菲尔德妈妈在这里做什么"}},ae4d5db0={q="斯通菲尔德妈妈与谁有联系？",a="斯通菲尔德妈妈是斯通菲尔德家族的女家长之一，与波尼斯·斯通菲尔德姑妈等亲属一起住在艾尔文森林的家族宅邸中。她的家族在这片山谷扎根已久，却也与邻居马科伦家族结下了深重而持久的仇怨。",al={"斯通菲尔德妈妈的家人","斯通菲尔德妈妈与谁有亲属关系"}}},fp="13,179,18.399.0,21.149.0,31.112.0,44.135.0"}
P.entries["npc:mad-magus-tirth"] = {n="大法师提尔斯",s="大法师提尔斯是一位性情古怪的人类巫师，住在千针石林沙漠赛道的盐滩上。他因养鸡和折磨被自己变形的学徒而为当地人所知，同时也是一位深谙奥术的学者，却把珍贵的典籍挥霍在了赛车赌局上。",h="大法师提尔斯是一位性情古怪的人类巫师，住在千针石林沙漠赛道的盐滩上。他因养鸡和折磨被自己变形的学徒而为当地人所知，同时也是一位深谙奥术的学者，却把珍贵的典籍挥霍在了赛车赌局上。",kw={"安科纳小鸡","大法师提尔斯","沙漠赛道","约翰森","能量仪祭","闪光平原","千针石林","提尔斯"},ang={["class:Mage"]="对于希望加深对奥术力量理解的法师而言，提尔斯是一位重要人物，因为他撰写了《能量仪祭》这部至关重要的著作。"},sec={{t="尘土中的巫师",b="与他造诣相当的法师大多在达拉然或暴风城的图书馆中钻研学问，大法师提尔斯却在满是油污与轰鸣声的闪光平原安了家。在疾驰的火箭赛车环绕下，提尔斯向路人兜售鸡只，饮酒赌博，还早已用诅咒把倒霉的学徒“约翰森” 约翰森变成了一只鸡。尽管举止古怪，提尔斯确实精通奥术，曾撰写过探讨魔法力量的深奥典籍，后来却在赛道上肆意下注，将这些典籍输了出去。"},{t="仪祭与赌债",b="提尔斯的学术著作包括《能量仪祭》，这是一本修习魔法的法师们争相寻求的奥术手册。可惜，对于那些渴望精进的施法者来说，提尔斯早已不再拥有自己的这部杰作。在沙漠赛道欠下的累累赌债压得这位法师喘不过气，他只好将典籍卖给一名血色十字军的代理人，以填补亏空，迫使学徒和求知者深入敌境追寻这本书。"}},faq={{q="大法师提尔斯为什么待在沙漠里？",a="提尔斯被赛车的热闹场面和赌局吸引，住在闪光平原的沙漠赛道旁。他没有在大城市里钻研学问，而是观看侏儒和地精的赛车比赛，兜售鸡只，沉溺于自己的恶习。",al={"提尔斯为什么在这里","大法师提尔斯 闪光平原","提尔斯位置"}},{q="他身边的那只鸡是谁？",a="在赛道上游荡的那只鸡是“约翰森” 约翰森，大法师提尔斯的学徒。提尔斯对约翰森施了诅咒，把他变成了一只鸡，如今甚至已经记不起缘由，却坚信这个忘恩负义的小子罪有应得。",al={"约翰森是谁","约翰森","提尔斯 鸡 学徒"}},{q="《能量仪祭》是一本什么书？",a="《能量仪祭》是大法师提尔斯撰写的一部深入探讨奥术能量的著作。对于想要精进技艺的法师来说，这是一本必读之书，但提尔斯为了偿还日益累积的赛车赌债，将它卖了出去。",al={"能量仪祭","提尔斯的书","法师任务书籍"}},{q="为什么他的书很难弄到手？",a="提尔斯手中已经没有《能量仪祭》了。寻找这本书的法师必须根据他讲述的出让典籍的经过继续追查。",al={"能量仪祭在谁手里","提尔斯的赌债","血色十字军 书籍"}}},fx={["8056ee12"]={q="大法师提尔斯是谁？",a="大法师提尔斯是一名古怪的人类施法者，住在闪光平原上的沙漠赛道。显然，他精通秘奥学识，还曾撰写著名的魔法典籍《能量仪祭》；如今，他却把时间花在兜售安科纳鸡、喝酒和赌赛上。",al={"大法师提尔斯是谁","提尔斯是谁","大法师提尔斯的背景"}},f085518f={q="大法师提尔斯站在哪一边？",a="大法师提尔斯始终严守中立。他在闪光平原的盐碱地上与地精和侏儒工程师为伴谋生，乐于向联盟和部落的旅人出售货物并提供魔法建议，却不参与双方更大规模的战争。",al={"大法师提尔斯属于联盟还是部落","提尔斯的阵营","大法师提尔斯是中立的吗"}},["3482f0bf"]={q="大法师提尔斯想要什么？",a="除了向赛场观众出售安科纳鸡、赚些钱糊口，提尔斯最想要的就是一杯新鲜的麦酒，以及下一场比赛的可靠消息。他曾想快速弄到钱来偿还高额赌债，结果把自己的学术研究都卖掉了。",al={"提尔斯想要什么","大法师提尔斯的动机","提尔斯为什么卖鸡"}}},fp="11,214,20.450.0,17.305.1,37.238.0,31.188.0,34.169.0,36.136.0"}
P.entries["npc:madame-eva"] = {n="伊瓦夫人",s="在夜色镇，伊瓦夫人凭借占卜之术，成为备受敬重的家族长者。她精通古老的预言术与纸牌占卜，往往是镇上最先察觉暮色森林各处异常动静的人。镇民与旅人向她求助，探寻阴森谜团的真相，并寻求抵御黑暗侵袭的神秘护符。",h="在夜色镇，伊瓦夫人凭借占卜之术，成为备受敬重的家族长者。她精通古老的预言术与纸牌占卜，往往是镇上最先察觉暮色森林各处异常动静的人。镇民与旅人向她求助，探寻阴森谜团的真相，并寻求抵御黑暗侵袭的神秘护符。",kw={"奥利萨·伊瓦","纸牌占卜","夜色镇","暮色森林","占卜师","幽灵的发丝","伊瓦夫人","斯塔文"},ang={["class:Priest"]="圣光为生者带来慰藉。牧师或许会觉得，艾瓦的纸牌占卜与使用幽魂残留之物的做法，带着乡土气息，与传统的教会仪式相映成趣。",["faction:Alliance"]="对于踏入暮色森林沉重阴影的联盟勇士而言，伊瓦夫人是不可或缺的向导。她的预感能拨开森林中致命的迷雾。",["profession:Tailoring"]="裁缝或许会看重艾瓦对奇异织造材料的了解。她使用的幽魂丝线，直接取自这一带的幽灵。"},sec={{t="夜色镇的占卜师",b="伊瓦夫人在夜色镇以纸牌占卜，施行古老的民间仪式。暴风城大教堂中的许多人会对她的做法心存疑虑。在这片饱受凶兽、亡灵与更黑暗恐怖之物侵扰的土地上，走投无路的镇民与到访的冒险者都来寻求她诡秘的指引。"},{t="血缘与预言",b="伊瓦夫人深爱着家人，包括她的孙女奥利萨·伊瓦和年幼的洛甘。当纸牌显露出威胁奥利萨的凶兆时，艾瓦便请过路的旅人搜寻森林，揭开尘封已久的悲剧，以免往事重演。"},{t="编织抵御黑夜的庇护",b="伊瓦夫人的学识不止于纸牌占卜，还涵盖仪式造物与防护之术。她用幽灵的头发纺成幽灵的发丝，还会制作惩罚图腾这样的民间法器。暮色森林中那些不安的幽魂遵循着诡异晦暗的法则，镇上鲜有人能像她那样深谙其中奥秘。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位年迈的人类占卜师与预言者，住在夜色镇。她借助纸牌占卜与古老的民间技艺，试图窥见潜伏在暮色森林中的无形危机。",al={"伊瓦夫人","艾瓦是谁","夜色镇占卜师"}},{q="伊瓦夫人在斯塔文的谜团中扮演什么角色？",a="伊瓦夫人通过纸牌占卜，察觉到孙女奥利萨身边有一股超自然的危险即将降临。她的占卜指引冒险者查访被遗忘的文书与线索，揭开斯塔文·密斯特曼托阴暗的过往。",al={"艾瓦 斯塔文","斯塔文的传说 艾瓦","艾瓦为何关心斯塔文"}},{q="伊瓦夫人是女巫还是法师？",a="艾瓦是一位先知，研习古老的神秘技艺，包括纸牌占卜、幽魂丝线编织以及民间偶像制作。她的魔法遵循传统的占卜之术与秘学知识，与达拉然体系严整的奥术或圣光不同。",al={"艾瓦是女巫吗","艾瓦魔法类型","艾瓦使用什么魔法"}},{q="夜色镇中谁与伊瓦夫人有亲缘关系？",a="伊瓦夫人是奥利萨·伊瓦和洛尔甘·伊瓦的祖母。在镇上守夜人任职的守夜人艾瓦也被认为与她有亲缘关系。",al={"艾瓦家人","伊瓦夫人的孙辈","奥利萨·伊瓦的祖母"}},{q="幽灵的发丝有什么用途？",a="伊瓦夫人用不安幽魂的头发纺成幽灵的发丝。她说这种丝线有上千种用途，既能束缚邪灵，也能将生命缝入无生命之物；只要有人带来她所需的幽灵头发，她就会为其纺制。",al={"幽灵的发丝","艾瓦丝线任务"}},{q="伊瓦夫人为何制作惩罚图腾？",a="伊瓦夫人制作的惩罚图腾是一种借助感应巫术的黑暗偶像。将特定生物的材料缚在其上，便能把诅咒与伤害施加到那些肆虐森林的凶兽身上。",al={"惩罚图腾","艾瓦图腾"}}},fp="10,303,31.290.0,26.273.0,36.284.0,18.184.0,52.222.0,32.230.0,42.155.0,35.231.0,50.188.0"}
P.entries["npc:magatha-grimtotem"] = {n="玛加萨·野性图腾",s="在长者高地，玛加萨·野性图腾挑战着凯恩·血蹄对牛头人未来的愿景。这位野性图腾部族的女族长兼雷霆崖的长者，是一位强大的萨满祭司，也是一位政治阴谋家。",h="在长者高地，玛加萨·野性图腾挑战着凯恩·血蹄对牛头人未来的愿景。这位野性图腾部族的女族长兼雷霆崖的长者，是一位强大的萨满祭司，也是一位政治阴谋家。",kw={"阿利卡拉","血蹄","凯恩","长者","长者高地","野性图腾","玛加萨","怒焰","雷霆崖","扎玛"},ang={["class:Shaman"]="身为萨满祭司，你面对的是卡利姆多最强大的萨满祭司之一，她对原始元素的掌控，鲜有在世的牛头人能够匹敌。",["faction:Horde"]="身为部落的一员，你或许会发现，玛加萨的援助和建议有助于应对当地的威胁。她对氏族的极端忠诚，以及对其他种族毫不掩饰的蔑视，使她成为一个不可信赖的同伴。",["race:Tauren"]="身为牛头人，你深知野性图腾的恶名。玛加萨在长者高地的存在提醒着你，观念上的分歧正威胁着各部族的团结。",["race:Undead"]="身为被遗忘者，你得到了长者出人意料的热情欢迎，她在预见之池与皇家药剂师学会商议事务。"},sec={{t="长者高地的女族长",b="玛加萨·野性图腾在长者高地领导着野性图腾部族，拥有自己的随从和护卫。她通过一桩包办婚姻获得了权力，随后她的配偶在一次登山意外中突然身亡。这个离群索居的部族奉她为政治与精神领袖。玛加萨宣扬牛头人的霸权，与凯恩·血蹄截然不同。她将其他凡人种族视为卡利姆多的入侵者，认为应当将他们赶尽杀绝或驱逐出去。"},{t="奇异的同盟",b="尽管玛加萨公开蔑视其他种族，她却是最早主张让被遗忘者加入部落的人之一。她声称，牛头人可以教导亡灵寻求精神上的平衡，帮助他们重拾人性。玛加萨还直接与雷霆崖下方的皇家药剂师学会合作，就实用炼金术和奥术遗物向药剂师扎玛等人征询意见。"},{t="政治阴谋",b="玛加萨·野性图腾一边为凯恩出谋划策，一边设法削弱他的权威，并试探潜在威胁的防御。她派冒险者深入险地，从前往怒焰裂谷对抗穴居人势力，到猎杀满怀怨恨的灵魂阿利卡拉。每项任务都在扩大野性图腾的影响力，或为她取代血蹄王朝做准备。"}},faq={{q="玛加萨·野性图腾是谁？",a="玛加萨·野性图腾是长者，也是野性图腾部族的女族长。她自幼便展现出萨满祭司的天赋，在配偶死于登山意外后独揽大权。她居住在雷霆崖的长者高地，是凯恩·血蹄最主要的政治对手。",al={"玛加萨背景故事","长者是谁","雷霆崖长者"}},{q="玛加萨为何支持被遗忘者？",a="玛加萨声称，牛头人的传统和萨满智慧可以引导被遗忘者重新找回人性。许多人怀疑，她与皇家药剂师学会往来，是为了寻求炼金术的秘密，以及凯恩忠实亲信圈子之外的盟友。",al={"玛加萨与亡灵","玛加萨为何喜欢被遗忘者","玛加萨与药剂师扎玛"}},{q="玛加萨与凯恩·血蹄是什么关系？",a="玛加萨认为凯恩·血蹄软弱、天真，不配领导联合起来的牛头人。凯恩主张在部落内部和平共处，并为整个卡利姆多争取和平；玛加萨则认为，野性图腾应当以武力夺回祖地，消灭外来的入侵者。",al={"玛加萨对抗凯恩","玛加萨是否憎恨凯恩","凯恩与玛加萨"}},{q="怒焰裂谷中的任务是什么？",a="玛加萨派玛尔前往奥格瑞玛地下的怒焰裂谷，与那里的穴居人谈判。他们杀死了他，于是她派部落冒险者进入洞穴，取回他的背包，并屠杀穴居人作为报复。",al={"玛加萨怒焰裂谷任务","玛加萨为何派遣玛尔","玛加萨遗失的背包"}},{q="阿利卡拉是谁？",a="阿利卡拉是一个满怀怨恨的风蛇之灵，据说一心要向牛头人复仇。玛加萨声称，阿利卡拉想向凯恩·血蹄复仇，因此派遣能干的勇士，用附魔龙舌兰召唤并杀死这头野兽。",al={"复仇之蛇","阿利卡拉任务","玛加萨与阿利卡拉"}},{q="在哪里可以找到玛加萨·野性图腾？",a="玛加萨住在雷霆崖长者高地顶端的大型主帐篷中，由仆从拉哈罗和两名不苟言笑的野性图腾卫兵侍奉左右。",al={"玛加萨位置","玛加萨在哪里","玛加萨长者高地"}}},fp="17,201,27.409.0,18.391.0,22.347.1,25.263.0,38.232.0,53.252.0,39.211.0,15.228.0,37.135.0"}
P.entries["npc:magga"] = {n="玛卡尔",s="在试炼谷的大兽穴附近，玛卡尔欢迎着新来的人。这位兽人居住在杜隆塔尔，迎接那些刚刚踏上试炼谷旅程的部落旅者。",h="在试炼谷的大兽穴附近，玛卡尔欢迎着新来的人。这位兽人居住在杜隆塔尔，迎接那些刚刚踏上试炼谷旅程的部落旅者。",kw={"杜隆塔尔","部落","旅店老板格罗斯克","玛卡尔","兽人","试炼谷","欢迎"},ang={["faction:Horde"]="作为一名初到严酷的试炼谷的部落新兵，你会收到玛卡尔令人安心的问候，欢迎你来到杜隆塔尔。"},sec={{t="试炼谷中亲切的面孔",b="年轻的兽人和黑暗之矛巨魔在试炼谷初识更广阔的世界。在大兽穴附近，玛卡尔迎接着来到谷中的人。训练师和新兵在附近忙碌，玛卡尔则帮助这个小营地凝聚在一起。"}},faq={{q="玛卡尔是谁？",a="玛卡尔是杜隆塔尔试炼谷大兽穴附近的一名兽人平民，她在那里欢迎新来的部落旅者。",al={"玛卡尔 杜隆塔尔","玛卡尔 试炼谷","玛卡尔是谁"}},{q="玛卡尔与旅店老板格罗斯克有什么关系？",a="玛卡尔与旅店老板格罗斯克没有特殊关系。她留在试炼谷，而旅店老板格罗斯克经营着剃刀岭的旅店，旅者可以在那里获得食物、饮品，并将炉石绑定于此。",al={"玛卡尔与格罗斯克","玛卡尔 旅店老板"}},{q="玛卡尔提供任务吗？",a="玛卡尔是“欢迎!”这项差事的交付对象。冒险者将试炼谷礼品券带给她，她则赠送一只小伙伴，欢迎他们来到艾泽拉斯。",al={"玛卡尔 任务","欢迎任务"}}},fp="5,148,40.221.0,13.105.0,46.208.0,28.159.0"}
P.entries["npc:maggran-earthbinder"] = {n="马格兰",s="马格兰在烈日石居守卫着这处位于石爪山脉的部落营地。凯恩·血蹄派这位久经沙场的牛头人前来，率领守军抵御野兽和鹰身人。",h="马格兰在烈日石居守卫着这处位于石爪山脉的部落营地。凯恩·血蹄派这位久经沙场的牛头人前来，率领守军抵御野兽和鹰身人。",kw={"贝瑟莱斯","血怒","凯恩·血蹄","缚地者","鹰身人","马格兰","石爪山脉","烈日石居"},ang={["faction:Horde"]="身为攀行于石爪山脉陡坡间的部落旅人，你可以指望马格兰协调当地巡逻，清除补给路线上的野兽和鹰身人。",["race:Tauren"]="身为牛头人，你能从马格兰身上看到战争对shu'halo心灵的摧残。即便是Earth Mother最沉稳的子民，也会因战乱而变得冷硬。"},sec={{t="老兵的休憩之所",b="大酋长凯恩·血蹄派马格兰前往石爪山脉，统领烈日石居。无数次小规模冲突和血腥战役让他的心变得冷硬，磨去了牛头人与生俱来的温和。这处前哨站也旨在让他稍作休憩，让暖风和山间的阳光抚慰他饱经战火的心灵。"},{t="山崖间的威胁",b="石爪山脉依旧难得安宁。马格兰在烈日石居统筹防御，抵御在群峰间筑巢的血怒鹰身人，并召集战士对付山崖间的掠食者。他曾在巨型蜘蛛贝瑟莱斯的伏击下幸存，深知荒野有多么致命。他经常征召旅人，猎杀当地的掠食者，以免它们侵袭前哨站。"}},faq={{q="马格兰是谁？",a="马格兰统领着石爪山脉烈日石居的牛头人。在他经历了无数场战斗后，凯恩·血蹄派他驻守此地，保卫聚落，确保补给道路和边界的安全。",al={"马格兰","马格兰是谁","烈日石居首领"}},{q="马格兰为何被派往烈日石居？",a="凯恩·血蹄任命马格兰统领烈日石居，既看重他丰富的领军经验，也希望给他一处休憩之所。戎马一生让他身心俱疲，宁静山间的阳光能带来些许慰藉。",al={"马格兰为何在此","马格兰背景","凯恩·血蹄与马格兰"}},{q="马格兰让冒险者应对哪些威胁？",a="马格兰指挥守军抵御山中的血怒鹰身人，并派战士猎杀当地危险的掠食者。其中就有巨型蜘蛛贝瑟莱斯，马格兰曾遭到她的伏击，险些丧命。",al={"马格兰任务","马格兰想要什么","石爪山脉鹰身人"}},{q="马格兰和贝瑟莱斯之间发生过什么？",a="马格兰曾遭到巨型蜘蛛贝瑟莱斯的伏击，但活了下来。他侥幸逃生，如今派遣有能力的冒险者去杀死她，以免更多人落入她的蛛网。",al={"马格兰 贝瑟莱斯","马格兰蜘蛛任务","蜘蛛恐惧症背景故事"}},{q="马格兰在雷霆崖担任职务吗？",a="马格兰听命于雷霆崖的大酋长凯恩·血蹄。虽然驻守在烈日石居，他的权力和命令都来自这座主城。",al={"马格兰 雷霆崖","马格兰 凯恩·血蹄"}},{q="马格兰对联盟玩家友好吗？",a="不友好。马格兰统领部落守军，对进入烈日石居的联盟冒险者抱有敌意。",al={"联盟能与马格兰交谈吗","马格兰敌对"}}},fp="19,173,17.358.0,20.386.0,27.214.0,41.209.0,55.208.0,44.166.0,42.154.0,52.94.0"}
P.entries["npc:magis-sparkmantle"] = {n="玛济斯·石衣",s="在卡拉诺斯，玛济斯·石衣在雷酒酿制厂内教导侏儒法师。他指引着从寒脊山谷来到丹莫罗的新晋施法者。",h="在卡拉诺斯，玛济斯·石衣在雷酒酿制厂内教导侏儒法师。他指引着从寒脊山谷来到丹莫罗的新晋施法者。",kw={"丹莫罗","侏儒法师","卡拉诺斯","法师训练师","玛济斯","玛济斯·石衣","石衣","雷酒酿制厂"},ang={["class:Mage"]="作为一名途经丹莫罗的联盟法师，你可以向玛济斯学习法术，并由他引荐，接触更广泛的奥术学问。",["race:Gnome"]="作为一名生活在矮人之中的侏儒，你可以向玛济斯这样的导师求教，让你们的学术与奥术传统延续下去。"},sec={{t="酿制厂中的施法者",b="矮人们来到雷酒酿制厂喝麦酒，而玛济斯·石衣就在大大小小的酒桶之间授课。在丹莫罗各地，侏儒法师都与矮人盟友密切合作。玛济斯帮助新晋施法者加深对奥术的理解，并将所学付诸实践。"},{t="指引年轻的奥术师",b="玛济斯教初学者念出最初的咒语，随后引导有潜力的学生更广泛地研习魔法。当他的入门课程已无法满足学生的需要，或学生需要特别指导时，他便会将他们引荐给彬克等其他施法者，或联盟主要城镇中的导师。"}},faq={{q="玛济斯·石衣是谁？",a="玛济斯·石衣在卡拉诺斯训练侏儒法师，向初出茅庐的施法者传授奥术基础。",al={"玛济斯·石衣","玛济斯是谁","卡拉诺斯法师训练师"}},{q="在哪里可以找到玛济斯·石衣？",a="你可以在雷酒酿制厂内找到玛济斯，那里是卡拉诺斯的主要旅店和集会场所。",al={"玛济斯位置","玛济斯在哪","寻找石衣"}},{q="为什么一位侏儒法师训练师会待在矮人的酿制厂里？",a="诺莫瑞根沦陷后，许多侏儒来到丹莫罗，在矮人亲族之间定居。雷酒酿制厂是卡拉诺斯的主要聚集地，因此玛济斯可以在这里指点途经此地的施法者。",al={"为何在酿制厂","酿制厂里的侏儒","为何在雷酒酿制厂"}},{q="玛济斯·石衣会提供任务吗？",a="随着法师们的学业日渐精进，玛济斯会将他们引荐给其他奥术导师，包括彬克和人类领地中的训练师。",al={"石衣任务","玛济斯任务"}}},fx={["1189c3a2"]={q="玛济斯·石衣站在哪一边？",a="玛济斯·石衣坚定地支持诺莫瑞根和大联盟。和许多因家园灾难而逃亡的流亡侏儒一样，他与铁炉堡的矮人一同生活和工作，将自己的奥术知识传授给联盟的保卫者。",al={"玛济斯·石衣的阵营","玛济斯属于联盟吗","石衣为谁效力"}},e3e37731={q="玛济斯·石衣想要什么？",a="玛济斯致力于向初出茅庐的法师传授奥术技艺。他寄居在酿酒厂期间，为新手施法者今后的旅途做好准备，先教授基础魔法，再指引他们去向暴风城的詹妮亚·坎农等资深大师求教。",al={"玛济斯想要什么","玛济斯·石衣的目标","玛济斯为何训练法师"}},["318a77dd"]={q="玛济斯·石衣与谁有联系？",a="作为联盟法师广泛联络网络的一员，玛济斯与王国各地的其他训练师保持联系，包括矮人领地的彬克，以及暴风城法师区的詹妮亚·坎农，确保有潜力的学生能得到进阶指导。",al={"玛济斯·石衣的盟友","石衣与谁有联系","石衣的关系"}}},fp="17,160,31.268.0,25.274.0,25.112.0,37.95.0,60.205.0,40.131.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="赫尼·马雷布镇长",s="在南海镇，赫尼·马雷布镇长维持着秩序，这里是联盟在希尔斯布莱德丘陵的主要沿海据点。这座港口城镇面临着被遗忘者和辛迪加的威胁。",h="在南海镇，赫尼·马雷布镇长维持着秩序，这里是联盟在希尔斯布莱德丘陵的主要沿海据点。这座港口城镇面临着被遗忘者和辛迪加的威胁。",kw={"奥特兰克","刺客","赫尼·马雷布","希尔斯布莱德","马雷布镇长","南海镇","辛迪加"},ang={["class:Rogue"]="身为潜行者，你能明白马雷布为何如此关注潜行与暗杀。他依靠目光敏锐的密探，抢在辛迪加潜伏的杀手之前采取行动。",["faction:Alliance"]="身为希尔斯布莱德的联盟勇士，你可以将马雷布镇长视为这片法外边疆的民政权威。他悬赏缉拿那些危害南海镇安定的辛迪加恶徒。"},sec={{t="南海镇秩序的守护者",b="赫尼·马雷布镇长在南海镇的城镇大厅处理政务，这里是联盟在洛丹伦仅存的几处真正的定居点之一。被遗忘者部队从北面和西面威胁着城镇，拦路强盗则在丘陵间游荡。前任镇长遭到神秘暗杀后，马雷布接任了职务，他认定这起暗杀是辛迪加所为。他决心避免重蹈覆辙。他的调查旨在找出潜伏的刺客、辛迪加的补给网络，以及从奥特兰克废墟指挥他们的贵族。"},{t="贵族的阴谋之网",b="辛迪加的势力遍布这一地区。在南海镇外果园间活动的刺客都是受雇的杀手，为失势的奥特兰克贵族执行刺杀任务。马雷布派出值得信赖的联盟斥候，截获他们的密文计划，并击杀他们的首领。他力图在辛迪加的阴谋重创南海镇的防御之前，打破他们的控制。"}},faq={{q="赫尼·马雷布镇长是谁？",a="赫尼·马雷布镇长负责维持南海镇的公共秩序，这里是联盟在希尔斯布莱德丘陵的一处沿海避风港。他管理镇内的民政事务，并保护城镇免受内部威胁。",al={"赫尼·马雷布","南海镇镇长","马雷布是谁"}},{q="马雷布为什么要调查辛迪加？",a="南海镇的前任镇长遇刺身亡后，马雷布接任了职务。他的调查指向了失势的奥特兰克贵族雇用的辛迪加刺客，他委托联盟冒险者阻止针对他的又一次暗杀。",al={"为什么调查辛迪加","马雷布 辛迪加","南海镇刺客"}},{q="在哪里可以找到马雷布镇长？",a="你可以在希尔斯布莱德丘陵南部的南海镇城镇大厅内找到赫尼·马雷布镇长。",al={"马雷布位置","赫尼·马雷布在哪里","寻找马雷布镇长"}},{q="马雷布在希尔斯布莱德面临哪些威胁？",a="马雷布面临着被遗忘者从北面和西面扩张的威胁，还有潜伏在南海镇郊外、密谋对付镇上掌权者的辛迪加杀手。",al={"南海镇的威胁","马雷布的敌人"}}},fp="22,191,30.474.0,24.346.1,30.183.0,41.226.0,36.103.0,42.136.0"}
P.entries["npc:magistrate-sevren"] = {n="执政官塞弗伦",s="在布瑞尔，执政官塞弗伦指挥着镇子的防务，并派遣新来者前去安定幽暗城周边的土地。",h="在布瑞尔，执政官塞弗伦指挥着镇子的防务，并派遣新来者前去安定幽暗城周边的土地。",kw={"阿加曼德","布瑞尔","被遗忘者","执政官","塞弗伦","提瑞斯法","市政厅","幽暗城"},ang={["faction:Horde"]="作为来到提瑞斯法的部落盟友，你发现塞弗伦正协调各方力量，对抗强盗、Scourge残余和叛乱势力，以平定这一地区。",["race:Undead"]="作为一名刚刚获得解放、离开丧钟镇的被遗忘者，你通过执政官塞弗伦接触到了Sylvanas国度的民政事务。他交给你最初的几项重大任务，让你保卫自己的家园。"},sec={{t="布瑞尔的城镇执政官",b="执政官塞弗伦在布瑞尔的市政厅中，掌管着幽暗城以北地区的民政与战略事务。初到提瑞斯法林地的被遗忘者发现，当地已有危机等待着他们。塞弗伦派遣冒险者恢复秩序、控制废墟，并压制周边丘陵中的威胁。"},{t="守护墓地",b="提瑞斯法的死者及其墓地，是执政官塞弗伦最为关切的事务之一。效忠天灾军团的腐皮豺狼人、盗墓贼和不受管束的亡灵，威胁着这些墓地以及希尔瓦娜斯·风行者日益扩大的领地。塞弗伦力求夺回阿加曼德家族墓穴等先祖陵墓，并阻止逃兵或不愿合作的势力破坏被遗忘者的权威。"}},faq={{q="执政官塞弗伦是谁？",a="执政官塞弗伦在市政厅中治理布瑞尔，并监管这一地区的被遗忘者事务。他派遣从丧钟镇前来的冒险者，为这个初建的国度效力。",al={"执政官塞弗伦","塞弗伦是谁","布瑞尔执政官"}},{q="在哪里可以找到执政官塞弗伦？",a="执政官塞弗伦位于提瑞斯法林地的布瑞尔，就在镇中心的市政厅内。",al={"塞弗伦位置","执政官塞弗伦在哪里","寻找塞弗伦"}},{q="执政官塞弗伦要应对哪些威胁？",a="塞弗伦面对着提瑞斯法林地各处的威胁，包括效忠天灾军团、盗掘坟墓的腐皮豺狼人，亵渎墓穴的天灾军团残余，以及拒绝效忠希尔瓦娜斯女士的不受管束的亡灵。",al={"塞弗伦任务","塞弗伦想要什么","布瑞尔的问题"}},{q="执政官塞弗伦效忠于谁？",a="执政官塞弗伦忠于被遗忘者，代表希尔瓦娜斯·风行者女士和幽暗城治理布瑞尔。",al={"塞弗伦阵营","塞弗伦为谁效力"}},{q="塞弗伦为何派冒险者前往家族墓穴？",a="亡灵和食腐生物占据了阿加曼德家族墓穴。塞弗伦派遣冒险者守住这些先祖的安息之所，防止敌人利用它们。",al={"阿加曼德墓穴","塞弗伦墓穴任务"}},{q="塞弗伦与幽暗城的领导层有联系吗？",a="有。塞弗伦经常与幽暗城的特工和官员合作。冒险者在布瑞尔证明自己的能力后，他便会指引他们深入首都。",al={"塞弗伦幽暗城","塞弗伦瑞里"}}},fp="17,124,24.279.0,19.377.0,25.159.0,37.92.0,46.176.0,39.117.0,53.161.0,50.152.0"}
P.entries["npc:magistrate-solomon"] = {n="所罗门镇长",s="豺狼人和兽人步步逼近，湖畔镇将希望寄托在所罗门镇长身上。他在镇政厅处理地方事务，恳请暴风城派兵援助，但王都无暇他顾，未予支援。",h="豺狼人和兽人步步逼近，湖畔镇将希望寄托在所罗门镇长身上。他在镇政厅处理地方事务，恳请暴风城派兵援助，但王都无暇他顾，未予支援。",kw={"黑石","伯瓦尔","湖畔镇","所罗门镇长","玛瑞斯","普瑞斯托","赤脊山","所罗门","镇政厅"},ang={["faction:Alliance"]="所罗门遭到弃援，暴露出暴风城的联盟内部深刻的裂痕，外围地区只能依靠自由行动的英雄。",["race:Dwarf"]="身为矮人，你或许会看到铁炉堡响应所罗门求救的行动与此事之间悲剧性的联系：远征队遭到伏击，茉艾拉·铜须公主被俘。",["race:Human"]="身为人类旅者，你可以从所罗门口中听到，艾尔文森林腹地之外的王国处境有多么严峻。"},sec={{t="危城之困",b="所罗门镇长治理着湖畔镇，而危险正从四面逼近。赤脊山和暗皮豺狼人游荡在周围的山丘间，黑石兽人则组成战团，从北方进犯。所罗门与治安官马瑞斯竭力维持秩序，组织防御，但湖畔镇的卫兵和民兵已疲于应付。"},{t="求援无应",b="所罗门镇长已派信使奔赴王国各地，向西部荒野、夜色镇和暴风城恳求援助。回信却几乎没有带来希望。西部荒野在迪菲亚潜行者的威胁下苦苦挣扎，暮色森林也面临着悄然蔓延的恐怖，而暴风城拒绝向东部边境派兵。湖畔镇只能独自抵御外敌。"},{t="王廷的拒绝",b="有证据表明黑石兽人与黑龙有关，所罗门镇长因此向伯瓦尔·弗塔根公爵发出警告。王室顾问女伯爵卡特拉娜·普瑞斯托却驳斥了所罗门的求援，声称他是在肆意夸大。听从她的建议，加上暴风城兵力分散，伯瓦尔拒绝出动暴风城军队，只授予所罗门王室许可，准其征召独立佣兵并赋予执法权。"}},faq={{q="所罗门镇长是谁？",a="所罗门镇长负责湖畔镇的民政事务，并主持湖畔镇法庭。他在镇政厅统筹镇务，组织防御，抵挡豺狼人和兽人的进攻。",al={"所罗门镇长背景故事","所罗门是谁","湖畔镇领袖"}},{q="暴风城为何无法派兵援助他？",a="暴风城的军队已分散在数个动荡地区，兵力捉襟见肘。所罗门请求援助时，伯瓦尔·弗塔根公爵受到王室顾问女伯爵卡特拉娜·普瑞斯托的影响，她质疑所罗门的报告，并劝阻他向赤脊山派遣正规军。",al={"为何没有暴风城军队","暴风城为何不援助湖畔镇","伯瓦尔援助赤脊山"}},{q="铁炉堡曾尝试提供援助吗？",a="是的。应所罗门的恳求，国王麦格尼·铜须派出了一支由茉艾拉·铜须公主率领的援军。远征队未能抵达赤脊山；他们在燃烧平原遭到伏击，被俘虏了。",al={"湖畔镇矮人援军","铁炉堡援助赤脊山","茉艾拉·铜须湖畔镇"}},{q="湖畔镇正面临哪些威胁？",a="湖畔镇周围的山丘和道路上有赤脊山和暗皮豺狼人出没，还有黑石兽人从石堡要塞和燃烧平原向南发动袭击。",al={"什么在进攻湖畔镇","赤脊山的敌人","所罗门为何担忧"}},{q="谁与所罗门一同保卫城镇？",a="所罗门主要与指挥当地城镇卫兵的治安官马瑞斯合作。由于没有正规军增援，两位官员便招募过往的冒险者，授予他们执法权，以击退来犯之敌。",al={"湖畔镇守军","治安官马瑞斯与所罗门"}},{q="所罗门为何派信使前往夜色镇和西部荒野？",a="所罗门派信使前往夜色镇和西部荒野，希望与附近的联盟聚居地缔结互助协定。西部荒野受困于迪菲亚潜行者，暮色森林则被亡灵和凶猛的野兽侵扰，双方都无力抽调守军。",al={"前往夜色镇的信使","前往西部荒野的信使","所罗门向其他城镇求援"}}},fp="18,169,18.318.0,20.313.0,19.379.1,26.201.0,44.264.1,31.198.1,37.154.0,42.194.0,57.263.0"}
P.entries["npc:magni-bronzebeard"] = {n="Magni Bronzebeard",s="在铁炉堡，麦格尼·铜须肩负着族人的悲痛与政治压力。他是铁炉堡之主、铜须氏族的族长、卡兹莫丹的统治者，也是一位历经第二次大战的老兵，致力于推动矮人在艾泽拉斯各地的考古事业。",h="在铁炉堡，麦格尼·铜须肩负着族人的悲痛与政治压力。他是铁炉堡之主、铜须氏族的族长、卡兹莫丹的统治者，也是一位历经第二次大战的老兵，致力于推动矮人在艾泽拉斯各地的考古事业。",kw={"布莱恩","铜须","探险者协会","铁炉堡","卡兹莫丹","麦格尼","茉艾拉","穆拉丁"},ang={["faction:Alliance"]="身为联盟的一员，你有麦格尼这位坚定的创立者，与洛丹伦和暴风城并肩。他为联盟带来了强大的军力、精湛的工程技艺和坚定不移的忠诚。",["profession:Blacksmithing"]="身为铁匠，你知道大锻炉的炉火在麦格尼的城市中心熊熊燃烧。在这位国王治下劳作的铁匠，位列联盟最优秀的工匠之中。",["race:Dwarf"]="身为矮人，麦格尼是你无可争议的君主，也是卡兹莫丹的守护者。他领导铜须氏族应对外敌，并探寻你们一族的远古传承。",["race:Gnome"]="身为侏儒，你知道麦格尼国王曾让诺莫瑞根的幸存者在铁炉堡避难。他至今仍是大工匠梅卡托克的挚友和技术盟友。"},sec={{t="山中之王",b="麦格尼·铜须是三兄弟中的长兄，从小就知道自己终有一天会统治这座山城。第二次大战期间，部落大举入侵，他凭借坚不可摧的城门坚守铁炉堡。围城解除后，他承诺让卡兹莫丹加入洛丹伦联盟。在随后的和平岁月里，诺莫瑞根陷落，麦格尼接纳了他的侏儒盟友。他让大工匠格尔宾·梅卡托克和难民们在山中避难。\n\n随后，麦格尼着手联结彼此分离的南北诸国。他请梅卡托克修建矿道地铁，这条前所未有的地下通道将铁炉堡与暴风城直接相连。"},{t="痛失手足",b="麦格尼威严的仪态之下，藏着深深的悲痛。第三次大战期间，诺森德传来消息，他深爱的弟弟穆拉丁在阿尔萨斯·米奈希尔王子的远征中丧生。麦格尼悲痛欲绝，但他和最小的弟弟布莱恩仍然坚定地履行着对矮人族人的职责。麦格尼依然贤明地治理着王国，丧弟之痛却始终压在他的心头。"},{t="发掘往昔",b="麦格尼让矮人社会从商业采矿转向了对古老历史的发掘。地下深处发现的奇异泰坦遗物，促使他与尚在人世的弟弟布莱恩·铜须共同创立了探险者协会。如今，从丹莫罗到卡利姆多，矮人的挖掘场遍布各大陆，探险者协会正寻求矮人传说中起源的真相。\n\n国内的和平依然脆弱。麦格尼的女儿茉艾拉公主失踪了，人们认为她遭到了可恨的黑铁氏族绑架。"}},faq={{q="麦格尼·铜须是谁？",a="麦格尼·铜须以国王的身份统治卡兹莫丹，以族长的身份领导铜须氏族，也是铁炉堡之主。他坐镇铁炉堡的王座厅，是大联盟最坚定的支柱之一。",al={"铁炉堡国王","矮人国王","麦格尼是谁"}},{q="谁锻造了灰烬使者？",a="铁炉堡的档案没有记载灰烬使者由谁锻造。人们记得这把剑是白银之手的大领主亚历山德罗斯·莫格莱尼的武器，没有任何记录表明它出自麦格尼国王之手。",al={"灰烬使者是麦格尼打造的吗","灰烬使者的铸造者","谁打造了灰烬使者"}},{q="麦格尼的弟弟们遭遇了什么？",a="麦格尼是三兄弟中的长兄。穆拉丁曾担任联盟驻洛丹伦的大使，据报在诺森德被阿尔萨斯王子杀害。最小的弟弟布莱恩是一位著名的探险家，他领导着探险者协会，足迹遍及世界的偏远角落。",al={"穆拉丁和布莱恩","麦格尼的兄弟","穆拉丁 铜须的命运"}},{q="茉艾拉公主在哪里？",a="茉艾拉·铜须公主是麦格尼唯一的孩子，她已从铁炉堡失踪。山城中的官方报告称，与他们敌对的黑铁矮人绑架了她，将她囚禁在黑石山深处。",al={"麦格尼的女儿","茉艾拉在哪里","茉艾拉·铜须遭遇了什么"}},{q="侏儒为什么住在铁炉堡？",a="穴居人入侵、诺莫瑞根遭受可怕的辐射污染之后，麦格尼国王向大工匠格尔宾·梅卡托克和幸存的侏儒敞开了铁炉堡的大门。他将整整一个城区交给了他们，如今那里被称为侏儒区。",al={"侏儒区","侏儒为什么在矮人城市","铁炉堡的侏儒难民"}},{q="探险者协会是什么？",a="探险者协会是麦格尼国王与弟弟布莱恩创立的考古组织。古老的泰坦遗迹被发现后，麦格尼将矮人的产业转向发掘本族起源，并派遣勘测队前往艾泽拉斯各地。",al={"探险者协会","矮人考古学家","矮人为什么挖掘"}}},fp="17,237,20.658.0,14.376.0,19.504.0,25.196.0,26.200.0,34.263.0,24.217.0,35.224.0,30.252.0"}
P.entries["npc:magus-rimtori"] = {n="大法师雷姆托里",s="大法师雷姆托里是一名叛离的血精灵女巫，率领一支远征队在艾萨拉的古老废墟中活动。她以冷酷的骗术闻名，曾诱使部落护送她穿越卡利姆多，随后残杀了护送她的兽人士兵。",h="大法师雷姆托里是一名叛离的血精灵女巫，率领一支远征队在艾萨拉的古老废墟中活动。她以冷酷的骗术闻名，曾诱使部落护送她穿越卡利姆多，随后残杀了护送她的兽人士兵。",kw={"艾萨拉","贝尔戈洛姆","血精灵","鹰盔","基姆加尔","大法师雷姆托里","雷姆托里","萨拉斯营地"},ang={["class:Mage"]="雷姆托里搜遍卡利姆多的废墟与恶魔遗物，展现了萨拉斯法师在疯狂追逐奥术力量时会走到何种地步。",["faction:Horde"]="雷姆托里操纵贝尔戈洛姆，并屠杀了奉命护送她的兽人卫兵，因此，渴望为死去同胞复仇的部落勇士将刺杀她视为首要任务。"},sec={{t="致命骗局",b="大法师雷姆托里率领一支出身高贵的血精灵远征队，渡海来到艾萨拉的古老海岸。为了让队伍安然度过卡利姆多的重重险境，她魅惑并摆布兽人贝尔戈洛姆，直到他同意派出武装护卫。士兵们将她安全送达目的地后，雷姆托里便露出了真面目，倒戈袭击自己的保护者，将整支驻军屠戮殆尽。她将部队安置在萨拉斯营地，随后在精锐护卫的陪同下深入沿海荒野，搜寻被遗忘的魔法神器。"},{t="废墟的秘密",b="雷姆托里远征的真正动机依然笼罩在迷雾之中，但她冷酷无情的手段已为她树敌无数。除了背叛部落，她还出卖了当地的雇工，其中就包括地精勘测员基姆加尔，他声称她痴迷于寻找一枚古老的符文。从她留在营地中的恶魔召唤典籍等遗物可见，雷姆托里一直在追逐力量，而遭她无情背叛的部落也因此向她展开了猛烈的报复。"}},faq={{q="部落为何要置雷姆托里于死地？",a="雷姆托里魅惑并操纵兽人贝尔戈洛姆，让他派兵护送她的远征队穿越卡利姆多。安全抵达艾萨拉后，她背信弃义，将贝尔戈洛姆麾下的兽人士兵屠杀殆尽。",al={"为何杀死雷姆托里","贝尔戈洛姆 雷姆托里背景故事","雷姆托里对部落做了什么"}},{q="在哪里能找到大法师雷姆托里？",a="她的远征队建立了萨拉斯营地，而雷姆托里本人则在血精灵贴身护卫的陪同下，游荡于艾萨拉的荒野，搜寻古老的遗物。",al={"雷姆托里位置","大法师雷姆托里在哪里","雷姆托里艾萨拉位置"}},{q="雷姆托里在艾萨拉寻找什么？",a="据那位受她雇用、随后又遭她背叛的地精基姆加尔所说，雷姆托里正痴迷地寻找一枚神秘的古老符文，同时还在搜寻其他强大的遗物，例如一本卡多雷召唤典籍。",al={"雷姆托里想要什么","雷姆托里在艾萨拉的目的","雷姆托里符文"}},{q="玛济斯·鹰盔是谁？",a="玛济斯·鹰盔是一名血精灵军官，受大法师雷姆托里委托，在她调查周围废墟期间，指挥并监管萨拉斯营地。",al={"鹰盔","萨拉斯营地首领","玛济斯·鹰盔 雷姆托里"}}},fp="13,171,18.474.0,20.378.1,37.212.0,33.153.0,42.161.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="迈安",s="在杜隆塔尔的试炼谷，迈安教导年轻的黑暗之矛巨魔学习魔法。她指引初学施法者，帮助他们在部落中踏上自己的道路。",h="在杜隆塔尔的试炼谷，迈安教导年轻的黑暗之矛巨魔学习魔法。她指引初学施法者，帮助他们在部落中踏上自己的道路。",kw={"黑暗之矛","杜隆塔尔","法师训练师","迈安","巨魔","试炼谷"},ang={["class:Mage"]="作为黑暗之矛施法者，你从迈安这里开启魔法之旅。在杜隆塔尔的烈日下，她教你掌握驾驭火焰、冰霜与奥术能量所需的自律。",["race:Troll"]="作为黑暗之矛的年轻一员，你可以在试炼谷从迈安那里获得本族文化的指引。她传授的技艺，在你的兽人盟友中鲜有人研习。"},sec={{t="大兽穴的奥术导师",b="年轻的黑暗之矛巨魔来到试炼谷，向迈安学习魔法。兽人崇尚元素之力或战士之道，而巨魔在研习奥术方面有着罕见的天赋。学徒们带来刻有雕文的文字，迈安则教他们将原始的力量化为可控的咒语。在杜隆塔尔，掌握这种控制力至关重要，因为兽穴之外危机四伏。"}},faq={{q="迈安是谁？",a="迈安在杜隆塔尔的试炼谷训练黑暗之矛巨魔法师。在初学施法者前往部落更广阔的土地之前，她为他们提供最初的指引与教导。",al={"迈安是谁","迈安的故事","巨魔法师训练师"}},{q="为什么兽人的初始区域会有巨魔法师训练师？",a="年轻的黑暗之矛巨魔逃离了正在沉没的海岛家园，随萨尔麾下的兽人在杜隆塔尔定居，之后便与兽人青年一同接受成年试炼。由于过去遭受过恶魔的腐化，兽人文化大多排斥奥术魔法，因此迈安这样的巨魔法师便负责指引自己的同胞。",al={"这里为何有巨魔法师","试炼谷巨魔训练师","杜隆塔尔巨魔法师"}},{q="她在训练新法师时起什么作用？",a="初学法术的巨魔法师会将 雕文羊皮纸 之类的书面指示带给迈安，由她开始对他们进行正式训练。她教授施法的基础知识，让他们能够保卫试炼谷，抵御当地的野兽和擅自潜入的火刃氏族成员。",al={"迈安做什么","雕文羊皮纸 迈安","迈安的任务"}}},fp="6,159,24.352.0,14.189.0,58.284.0,46.257.0"}
P.entries["npc:major-mattingly"] = {n="玛丁雷少校",s="玛丁雷少校在暴风城的正门协助守卫首都，并指导工匠制作抵御巨龙的护具。",h="玛丁雷少校在暴风城的正门协助守卫首都，并指导工匠制作抵御巨龙的护具。",kw={"龙鳞披风","马库斯·乔纳森","玛丁雷少校","玛丁雷","暴风城军队","英雄谷"},ang={["class:Warrior"]="玛丁雷少校是一位纪律严明的老兵，手持长剑驻守暴风城城门，体现了暴风城步兵军官坚定不移的意志。",["faction:Alliance"]="对于挑战奥妮克希亚等强大巨龙的联盟勇士，玛丁雷少校会指导他们用龙鳞制作防护披风。"},sec={{t="首都城门的哨兵",b="玛丁雷少校负责暴风城的陆上防御。他与城中的驻军一同驻守英雄谷，听从马库斯·乔纳森将军的指挥。他负责监督城门巡逻和入城旅客。巨龙凶险致命，玛丁雷会指导技艺娴熟的工匠制作龙鳞装备，供他们深入危险的巢穴。"}},faq={{q="在哪里可以找到玛丁雷少校？",a="玛丁雷少校与驻军一同守卫在暴风城正门内侧的英雄谷。",al={"玛丁雷位置","玛丁雷少校在哪里","寻找玛丁雷少校"}},{q="玛丁雷少校在暴风城担任何种军衔和职务？",a="玛丁雷少校是马库斯·乔纳森将军麾下的暴风城军官。他协助监管城门防务，并为冒险者提供军事指导。",al={"玛丁雷是谁","玛丁雷职责","玛丁雷做什么"}},{q="制皮匠为什么要找玛丁雷少校？",a="制皮匠向玛丁雷少校请教处理黑龙皮的方法，以及如何制作能保护盟友抵御龙焰的鳞片披风。",al={"奥妮克希亚鳞片披风 玛丁雷","玛丁雷任务","一切才刚刚开始 玛丁雷"}},{q="玛丁雷少校是否参与了更大范围的冲突？",a="玛丁雷少校是暴风城王国一位身经百战的老兵。瓦里安·乌瑞恩国王失踪，王国仍面临挥之不去的威胁，他在此期间全心投入保卫王国的职责。",al={"玛丁雷背景","玛丁雷故事"}}},fx={["3133ea98"]={q="玛丁雷少校效忠哪一方？",a="玛丁雷少校全心效忠于暴风城王国与联盟。身为暴风城军队的军官，他直接听命于马库斯·乔纳森将军，守卫着首都的宏伟入口，忠于王座，尽心保卫王国。",al={"玛丁雷阵营","玛丁雷为谁效力","玛丁雷少校效忠谁"}},["3a90c3f3"]={q="玛丁雷少校为什么驻守英雄谷？",a="他驻守在英雄谷内的城门处，负责监督首都的第一道防线。在纪念第二次战争英雄的巍峨雕像下，玛丁雷协助指挥城门卫兵，确保任何敌军都无法不受阻拦地穿过城门。",al={"玛丁雷为什么在这里","玛丁雷为什么在英雄谷","玛丁雷在暴风城做什么"}},["728996ed"]={q="玛丁雷少校与谁有关联？",a="在暴风城军队的指挥体系中，玛丁雷少校直属于马库斯·乔纳森将军。他也与城中居民加妮斯·玛丁雷同姓，不过他的日常职责完全围绕军职及其指挥官展开。",al={"玛丁雷的指挥官","玛丁雷听命于谁","玛丁雷少校的人物关系"}}},fp="15,115,29.335.0,35.117.0,53.160.0,47.142.0,53.191.0"}
P.entries["npc:major-samuelson"] = {n="萨缪尔森少校",s="在暴风要塞，萨缪尔森少校统领城中的卫兵及其军官。他在王座厅任职，曾指导过法尔林·奥里涅尔中尉。",h="在暴风要塞，萨缪尔森少校统领城中的卫兵及其军官。他在王座厅任职，曾指导过法尔林·奥里涅尔中尉。",kw={"法尔林·奥里涅尔","萨缪尔森少校","调任","萨缪尔森","南海镇","暴风城卫兵","暴风要塞"},ang={["faction:Alliance"]="作为联盟军官，萨缪尔森少校在王座厅中统管暴风城的军事人员，其中也包括在希尔斯布莱德等争夺地区服役的人员。"},sec={{t="暴风城卫兵的支柱",b="萨缪尔森少校在王廷中统领暴风城卫兵。他坐镇首都，统管王国各地的军官调派与军令。他曾指导过法尔林·奥里涅尔中尉，后者如今驻扎在希尔斯布莱德丘陵的南海镇。\n\n遥远边疆驻军中的下级指挥官会向萨缪尔森呈交报告和调任申请。当他们遇到困难时，求助信便会送到他在暴风城的案头。"}},faq={{q="萨缪尔森少校是谁？",a="萨缪尔森少校在暴风要塞的王座厅中指挥暴风城卫兵。他负责军官调派和人事事务。",al={"萨缪尔森","萨缪尔森少校身份","要塞里的少校是谁"}},{q="在哪里能找到萨缪尔森少校？",a="萨缪尔森少校位于暴风要塞的王座厅，站在年幼的安度因·乌瑞恩国王和伯瓦尔·弗塔根公爵附近。",al={"萨缪尔森位置","萨缪尔森少校在哪里","寻找萨缪尔森"}},{q="他与南海镇有什么联系？",a="萨缪尔森少校曾指导过法尔林·奥里涅尔中尉，后者驻扎在希尔斯布莱德丘陵的南海镇。北方驻地的重压让奥里涅尔希望通过萨缪尔森申请调任。",al={"萨缪尔森南海镇","法尔林·奥里涅尔中尉的导师","萨缪尔森希尔斯布莱德"}},{q="冒险者为何要找他？",a="来自希尔斯布莱德北方前线的旅人，将法尔林·奥里涅尔中尉的正式调任申请带给暴风要塞的萨缪尔森少校。",al={"进军暴风城任务交付","调任任务","为何与萨缪尔森交谈"}}},fx={["75428c69"]={q="萨缪尔森少校效忠哪一方？",a="萨缪尔森少校为暴风城王国与联盟效力。身为驻守在暴风要塞内的暴风城卫队军官，他的职责是保卫首都、维持军纪，并执行城中领袖的命令。",al={"萨缪尔森阵营","萨缪尔森少校为谁效力","萨缪尔森是联盟吗"}}},fp="15,150,29.427.0,23.128.0,35.117.0,37.191.0,32.149.0"}
P.entries["npc:makaba-flathoof"] = {n="玛卡巴·扁蹄",s="玛卡巴·扁蹄在阿帕拉耶营地的家园被恐怖图腾氏族夺走了。他寻求部落勇士的帮助，反击敌人，保护家人。",h="玛卡巴·扁蹄在阿帕拉耶营地的家园被恐怖图腾氏族夺走了。他寻求部落勇士的帮助，反击敌人，保护家人。",kw={"阿帕拉耶营地","扁蹄","恐怖图腾","格鲁迪格·暗云","卡雅","玛卡巴","石爪山脉"},ang={["faction:Horde"]="身为部落勇士，你可以响应玛卡巴的求助，惩罚那些在和平营地中大肆屠杀的凶徒。",["race:Tauren"]="身为牛头人，你从玛卡巴的遭遇中看到了恐怖图腾令人痛心的背叛。你的一些同胞既不尊重和平，也不珍视团结。"},sec={{t="阿帕拉耶营地的惨剧",b="玛卡巴·扁蹄为他在石爪山脉的家园阿帕拉耶营地悲痛不已。恐怖图腾氏族突然来袭，将这座聚居地夷为平地。许多牛头人在凯恩·血蹄的领导下寻求和平与团结，恐怖图腾却不断散播纷争与暴力。玛卡巴也是那些流离失所、满怀悲痛的幸存者之一。"},{t="复仇的请求",b="玛卡巴·扁蹄无法独自夺回阿帕拉耶营地，于是呼吁部落旅人发起反击。他要让侵占家园的恐怖图腾为屠杀他的族人付出惨痛代价。他最在意的是罪魁祸首，军阀格鲁迪格·暗云。玛卡巴以为女儿卡雅已在袭击中丧生。"}},faq={{q="玛卡巴·扁蹄是谁？",a="玛卡巴·扁蹄是一名牛头人，来自石爪山脉的阿帕拉耶营地，是那里的幸存者。恐怖图腾氏族攻占了他的家园，他正寻求部落勇士的帮助。",al={"玛卡巴","玛卡巴·扁蹄是谁","玛卡巴·扁蹄的故事"}},{q="玛卡巴来自哪里？",a="玛卡巴来自阿帕拉耶营地，那是石爪山脉中的一处牛头人小型聚居地。恐怖图腾袭击并摧毁了那里。",al={"玛卡巴的来历","玛卡巴来自哪里","阿帕拉耶营地 玛卡巴"}},{q="谁袭击了玛卡巴的村庄？",a="恐怖图腾氏族洗劫了阿帕拉耶营地。格鲁迪格·暗云是率领他们进攻那里的头目之一。",al={"谁袭击了阿帕拉耶营地","玛卡巴的敌人","谁洗劫了阿帕拉耶"}},{q="玛卡巴希望部落冒险者做什么？",a="玛卡巴希望部落勇士杀死阿帕拉耶营地的恐怖图腾，并除掉他们的首领格鲁迪格·暗云，为沦陷的家园复仇。",al={"玛卡巴的任务","玛卡巴有何请求","玛卡巴 任务"}},{q="卡雅是玛卡巴的什么人？",a="卡雅·扁蹄是玛卡巴的女儿。她在阿帕拉耶营地遭袭时失踪，家人以为她已在那场袭击中丧生。",al={"卡雅·扁蹄","卡雅是谁","玛卡巴的亲属 卡雅"}},{q="玛卡巴和迪姆·扁蹄有亲属关系吗？",a="玛卡巴和迪姆都姓扁蹄，但他们之间的亲属关系尚未得到证实。",al={"迪姆·扁蹄","玛卡巴和迪姆","扁蹄家族"}}},fp="15,152,23.314.0,20.318.1,23.126.0,27.127.0,30.99.0,46.145.0,22.132.0,34.88.0"}
P.entries["npc:malfurion-stormrage"] = {n="玛法里奥·怒风",s="玛法里奥·怒风在翡翠梦境中昏迷不醒，族人无法与他取得联系。他是首位凡人德鲁伊，也是与高阶女祭司泰兰德·语风共同领导暗夜精灵的崇高领袖，曾在上古之战和第三次大战中协助击败燃烧军团。卡多雷尊称他为珊多，意为尊敬的老师，并等待他醒来，再次给予指引。",h="玛法里奥·怒风在翡翠梦境中昏迷不醒，族人无法与他取得联系。他是首位凡人德鲁伊，也是与高阶女祭司泰兰德·语风共同领导暗夜精灵的崇高领袖，曾在上古之战和第三次大战中协助击败燃烧军团。卡多雷尊称他为珊多，意为尊敬的老师，并等待...",kw={"大德鲁伊","塞纳留斯","翡翠梦境","弗里奥","海加尔山","伊利丹","玛法里奥","衫多","怒风","泰兰德"},ang={["class:Druid"]="身为德鲁伊，你所学的教义可以追溯到玛法里奥，他曾直接师从塞纳留斯。他滞留翡翠梦境，令塞纳里奥议会深感忧虑。",["class:Priest"]="身为牧师，你知道玛法里奥是高阶女祭司泰兰德·语风深爱的伴侣，将对Elune的虔诚与守护自然的神圣职责联系在一起。",["race:NightElf"]="身为暗夜精灵，你尊崇玛法里奥，视他为族人古老的守护者与救星。在他沉睡期间，由泰兰德和大德鲁伊范达尔·鹿盔共同治理。"},sec={{t="首位德鲁伊",b="一万年前，玛法里奥·怒风放弃奥术，转而追随自然。在大灾变撕裂古老的卡利姆多之前，他曾师从半神塞纳留斯。当艾萨拉女王和她麾下的上层精灵深入探究永恒之井的奥术力量时，玛法里奥成为了艾泽拉斯首位凡人德鲁伊。当艾萨拉的法术为萨格拉斯和燃烧军团打开通道，引发上古之战时，他的忧虑应验了。"},{t="卡利姆多的救星",b="玛法里奥·怒风协助击退恶魔，关闭了永恒之井上方的传送门。他曾与塞纳留斯、泰兰德·语风以及自己的孪生兄弟伊利丹并肩作战。世界破碎后，玛法里奥带领德鲁伊进入翡翠梦境，重建并守护艾泽拉斯的生灵世界。一万年后，泰兰德唤醒了他，让他在第三次大战中迎战阿克蒙德。在海加尔山，他召集森林之灵，再次重创了燃烧军团。"},{t="迷失梦境",b="第三次大战结束后，玛法里奥·怒风回到月光林地沉睡，寻求进入翡翠梦境，恢复耗尽的力量。他的灵魂始终没有回到躯体，令他陷入了非自然的昏迷。在达纳苏斯，大德鲁伊范达尔·鹿盔承担着领导塞纳里奥议会的职责。泰兰德和姐妹会守候着，盼望她们的珊多醒来。"}},faq={{q="玛法里奥·怒风现在在哪里？",a="玛法里奥·怒风沉睡在月光林地的兽穴中，而他的意识仍留在翡翠梦境深处。他的躯体昏迷不醒，大多数冒险者都无法接近。",al={"玛法里奥在哪里","哪里能找到玛法里奥","玛法里奥位置","玛法里奥在游戏中吗"}},{q="玛法里奥为什么沉睡？",a="德鲁伊在翡翠梦境中休眠，与自然沟通，维系世间的动植物，并恢复精神力量。在海加尔山击败阿克蒙德耗费了巨大的魔法力量，之后玛法里奥进入梦境休养，但一种非自然的病症切断了他的灵魂与躯体之间的联系。",al={"玛法里奥为什么沉睡","他为什么昏迷","玛法里奥发生了什么"}},{q="玛法里奥沉睡期间，由谁统治暗夜精灵？",a="高阶女祭司泰兰德·语风在达纳苏斯的月神殿统治卡多雷，领导哨兵和艾露恩姐妹会。大德鲁伊范达尔·鹿盔负责管理塞纳里奥议会和德鲁伊事务。",al={"谁领导暗夜精灵","暗夜精灵领袖是谁","暗夜精灵统治者"}},{q="“珊多”是什么意思？",a="在达纳苏斯语中，珊多意为尊敬的老师。这是对德鲁伊大师极为尊崇的称谓，尤其用于玛法里奥·怒风，他在塞纳留斯的教导下，首次将德鲁伊之道带给凡人。",al={"杉多含义","杉多是什么","杉多"}},{q="玛法里奥的兄弟是谁？",a="玛法里奥的孪生兄弟是伊利丹怒风。他们在苏拉玛共同度过了年少时光，但伊利丹对奥术魔法的痴迷和对恶魔力量的追求，使兄弟二人在上古之战期间产生了深刻的裂痕。玛法里奥将他囚禁了数千年。",al={"玛法里奥的兄弟","伊利丹与玛法里奥的关系","怒风兄弟"}},{q="玛法里奥在海加尔山之战中做了什么？",a="在第三次大战的决战时刻，玛法里奥在世界之树诺达希尔下吹响塞纳留斯号角，召来了成千上万被称为小精灵的先祖森林之灵。它们蜂拥扑向阿克蒙德并引爆自身，消灭了这个恶魔，也焚毁了世界之树，拯救了卡利姆多。",al={"玛法里奥 海加尔山","海加尔山之战玛法里奥","玛法里奥如何击败阿克蒙德"}}},fp="19,301,15.461.0,18.471.0,17.357.0,39.181.0,24.304.0,49.223.0,25.193.0,27.258.0,51.269.0"}
P.entries["npc:mangletooth"] = {n="碎牙",s="在陶拉祖营地，碎牙被关在部落的笼中，等待处决，并与前来探望的人讨价还价。他以对手的情报和阿迦玛甘的古老传说为筹码，换取他们的帮助。",h="在陶拉祖营地，碎牙被关在部落的笼中，等待处决，并与前来探望的人讨价还价。他以对手的情报和阿迦玛甘的古老传说为筹码，换取他们的帮助。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","刺背","陶拉祖营地","碎牙","野猪人","钢鬃"},ang={["faction:Horde"]="在陶拉祖营地，部落守卫将碎牙关在笼中，而部落也利用他满腔的怨恨，打击遍布贫瘠之地的野猪人据点。",["race:Tauren"]="身为牛头人，你深知平原上牛头人猎手与野猪人之间不断的冲突。碎牙愿意与自己的同族为敌，这让他成为一份宝贵却令人不安的军事助力。"},sec={{t="身陷囹圄的人质",b="牛头人猎手和兽人哨兵将碎牙关在陶拉祖营地的笼中。这个被俘的钢鬃野猪人等待着处决，却仍试图说动看守和来访的部落冒险者。他催促他们打击自己部族的敌人，希望借此证明自身的价值，或是重获自由。"},{t="内部的背叛",b="碎牙起初指引部落战士对抗敌对的刺背部族，试图赢得氏族的感激。随后，他得知钢鬃的首领纳克、卡兹和洛克·奥克班恩已经抛弃了他。他怒不可遏，转而与同族为敌，派冒险者去处决昔日的盟友。"},{t="血岩碎片的力量",b="碎牙熟知族人的宗教历史。在古老的上古之战中，阿迦玛甘洒落的鲜血催生了贫瘠之地巨大的荆棘。碎牙从死去的刺背族人身上收集红色结晶血岩碎片，并引导其中残存的神力，为帮助他的人赐予古老的祝福。"}},faq={{q="碎牙是谁？",a="碎牙是一个被俘的钢鬃野猪人，被关在陶拉祖营地的笼中。面对即将到来的处决，他与冒险者讨价还价，以指引和古老的祝福换取他们的帮助。",al={"碎牙","碎牙是谁","陶拉祖笼中野猪人"}},{q="碎牙为什么被关在笼中？",a="碎牙在部落与野猪人在南贫瘠之地的冲突中被俘。陶拉祖营地的牛头人和兽人守卫将他关在笼中，等待处决。",al={"碎牙为何被俘","为何关在笼中","为何成为陶拉祖的囚犯"}},{q="碎牙为什么要求你攻击其他钢鬃野猪人？",a="碎牙要求你攻击其他钢鬃野猪人，是因为纳克、卡兹和洛克·奥克班恩没有设法营救他，而是任由他等死。他怒火中烧，想让旅人处决他们，以泄心头之恨。",al={"为何攻击钢鬃","内部的背叛背景","为何杀死纳克和卡兹"}},{q="血岩碎片是什么？",a="阿迦玛甘在上古之战中倒下时，鲜血渗入大地，血岩碎片就是在这些地方形成的结晶。刺背野猪人经常随身携带它们。",al={"血岩碎片","血岩碎片背景","阿迦玛甘的鲜血"}},{q="把血岩碎片交给碎牙有什么用？",a="当你将血岩碎片带给碎牙时，他会引导阿迦玛甘的神圣力量，赋予你暂时的祝福。这些祝福能提升力量、敏捷、韧性、精神或速度。",al={"血岩碎片增益","交付血岩碎片","碎牙给予什么"}},{q="碎牙说阿迦玛甘死在何处？",a="碎牙说，阿迦玛甘在上古之战中战死。他洒落的鲜血催生了巨大的荆棘尖塔，而他庞大的头骨坐落在南方，笼罩着一处洞穴。",al={"阿迦玛甘背景","阿迦玛甘在何处倒下","野猪之神的头骨"}}},fp="11,169,19.294.0,20.285.1,25.333.0,19.180.0,29.176.0,64.196.1,22.164.0,49.177.0,42.192.0"}
P.entries["npc:mankrik"] = {n="曼科里克",s="在十字路口，曼科里克满怀悲痛，渴望复仇。一场野猪人的伏击让他与妻子奥格拉失散，如今他在贫瘠之地四处猎杀这些浑身鬃毛的野兽。",h="在十字路口，曼科里克满怀悲痛，渴望复仇。一场野猪人的伏击让他与妻子奥格拉失散，如今他在贫瘠之地四处猎杀这些浑身鬃毛的野兽。",kw={"贫瘠之地","十字路口","黄金之路","曼科里克","奥格拉","野猪人","索克"},ang={["faction:Horde"]="在十字路口，你面对着贫瘠之地上成群鬃毛野猪人带来的持续威胁。",["race:Orc"]="身为兽人，你深知在卡利姆多荒野边疆的重重威胁之下，家庭与荣誉时刻经受着考验。"},sec={{t="尘土中的伏击",b="曼科里克和妻子奥格拉途经贫瘠之地时，在一处牛头人小聚落的冲突中遭到野猪人的围攻。战斗将两人冲散，曼科里克眼看着奥格拉消失在獠牙与荆棘编织的武器之下。狂怒驱使他不顾一切地战斗，直到一记重击让他失去了知觉。在黄金之路沿途，一位路过的牛头人德鲁伊发现曼科里克血流不止，便为他包扎了伤口。他在伏击中活了下来，奥格拉却不见了。"},{t="复仇之火",b="曼科里克在十字路口养伤，悲痛让他无所适从，嗜血的欲望吞噬着他。索克和其他当地领袖告诫他，仇恨已蒙蔽了他的判断，并拒绝正式派遣战斗队伍。曼科里克始终无法释怀。他不知道奥格拉的命运，便请求所有愿意帮忙的部落旅人，在贫瘠之地寻找失散伴侣的踪迹，并杀死沿途遇到的所有野猪人。"}},faq={{q="曼科里克是谁？",a="在贫瘠之地的十字路口，兽人战士曼科里克深陷悲痛与愤怒之中。一场野猪人的伏击让他与妻子失散，如今他一心寻求复仇。",al={"曼科里克背景故事","曼科里克是谁","曼科里克的故事"}},{q="曼科里克的妻子遭遇了什么？",a="在一处牛头人聚落的冲突中，成群的野猪人将曼科里克和奥格拉冲散。曼科里克在混乱中被击倒，奥格拉则在战斗中不知所踪。",al={"曼科里克的妻子","曼科里克的妻子在哪里","奥格拉遭遇了什么","奥格拉的命运"}},{q="曼科里克是如何在战斗中幸存的？",a="曼科里克在野猪人的围攻下昏迷后，一位牛头人德鲁伊在黄金之路沿途发现了血流不止的他。德鲁伊为他包扎了伤口，并将他带到安全的地方。",al={"曼科里克如何幸存","谁救了曼科里克"}},{q="索克为什么拒绝帮助曼科里克？",a="十字路口的领袖索克认为，曼科里克的愤怒和复仇欲望蒙蔽了他的判断，使他无法理智行事。",al={"索克为什么不帮忙","索克与曼科里克"}}},fp="7,157,18.413.0,21.387.0,15.162.0,32.154.0,35.167.0,38.160.0"}
P.entries["npc:marcus-redpath"] = {n="Marcus Redpath",s="在南海镇，治安官Marcus Redpath守卫着洛丹伦南部最后的海岸堡垒。他组织巡逻，发布悬赏，对付附近的食人魔、鱼人和纳迦。",h="在南海镇，治安官Marcus Redpath守卫着洛丹伦南部最后的海岸堡垒。他组织巡逻，发布悬赏，对付附近的食人魔、鱼人和纳迦。",kw={"破碎岭","希尔斯布莱德","马库斯·雷德帕斯","治安官","南海镇"},ang={["faction:Alliance"]="作为联盟的勇士，你可以协助治安官雷德帕斯保卫希尔斯布莱德，抵御步步进逼的食人魔和沿海的威胁。",["race:Human"]="身为人类，你看到雷德帕斯正守卫着人类在洛丹伦最后的几处据点之一。周围的王国已成废墟，他仍让南海镇屹立不倒。"},sec={{t="南海镇的哨兵",b="治安官马库斯·雷德帕斯守卫着南海镇，这座联盟港口坐落在希尔斯布莱德丘陵的南部海岸。小镇挺过了洛丹伦都城的陷落和天灾军团毁灭性的入侵。如今，雷德帕斯领导着小镇的防御，保护仍留在这里的幸存者。"},{t="坚守海岸",b="面对从四面八方逼近的敌对势力，南海镇几乎孤立无援。治安官雷德帕斯统筹希尔斯布莱德丘陵各地的防御，并征召经验丰富的冒险者，击退从奥特兰克进犯的破碎岭食人魔。他也派遣他们对付沿海危险的纳迦和鱼人营地。被遗忘者占据着北方，附近的塔伦米尔戒备森严。雷德帕斯时刻保持警惕，帮助联盟在这片地区站稳脚跟，免于溃败。"}},faq={{q="马库斯·雷德帕斯是谁？",a="马库斯·雷德帕斯是南海镇的治安官，也是希尔斯布莱德丘陵的军事长官。他负责小镇的防御，抵御周围荒野和敌对邻居带来的威胁。",al={"马库斯·雷德帕斯背景故事","南海镇的治安官是谁","马库斯·雷德帕斯资料"}},{q="他在第二次大战中扮演了什么角色？",a="关于第二次大战的记载中，没有提及雷德帕斯在其中的经历。如今，这位南海镇治安官守卫着小镇，抵御希尔斯布莱德丘陵的食人魔、鱼人和纳迦。",al={"第二次战争中的马库斯","马库斯·雷德帕斯是否见过洛萨"}},{q="他主要对抗哪些威胁？",a="雷德帕斯组织人手，对付当地的掠食者和向南海镇逼近的入侵者。他发布悬赏和任务，目标包括奥特兰克山麓的破碎岭食人魔部族、沿海的鱼人，以及前来劫掠的纳迦。",al={"马库斯·雷德帕斯任务","雷德帕斯要消灭什么"}},{q="他与达隆郡的雷德帕斯家族有亲缘关系吗？",a="马库斯·雷德帕斯与东瘟疫之地达隆郡的约瑟夫·雷德帕斯上尉同姓，这个姓氏因后者而闻名。除了同样出身于洛丹伦王国之外，两人之间尚未证实存在直接的亲缘关系。",al={"雷德帕斯家族","马库斯与约瑟夫·雷德帕斯是否有亲缘关系","雷德帕斯的亲属"}},{q="在哪里可以找到马库斯·雷德帕斯？",a="治安官雷德帕斯驻守在南海镇中心，这座小镇是联盟在希尔斯布莱德丘陵南部海岸的避风港。",al={"马库斯·雷德帕斯在哪里","马库斯·雷德帕斯位置"}}},fp="14,174,24.245.0,17.470.0,22.183.0,40.170.0,39.215.0,45.187.0,34.119.0"}
P.entries["npc:mardant-strongoak"] = {n="玛丹特·硬木",s="在奥达希尔，玛丹特·硬木指引年轻的暗夜精灵踏上德鲁伊之路。他教导他们与自然交流，并了解翡翠梦境。",h="在奥达希尔，玛丹特·硬木指引年轻的暗夜精灵踏上德鲁伊之路。他教导他们与自然交流，并了解翡翠梦境。",kw={"奥达希尔","德鲁伊","翡翠梦境","玛丹特","幽影谷","硬木","泰达希尔","训练师"},ang={["class:Druid"]="作为一名年轻的暗夜精灵德鲁伊，你可以向玛丹特·硬木求教，初步学习塞纳里奥议会的神圣职责。",["race:NightElf"]="在奥达希尔的中心，玛丹特体现了kaldorei与泰达希尔不断生长的生态环境和谐共处的信念。"},sec={{t="荒野导师",b="在奥达希尔，感受到荒野召唤的年轻暗夜精灵会向玛丹特·硬木求教。他教导初入门的德鲁伊敞开感官，感知自然之灵，聆听它们的低语，并引导治疗魔法。\n\n那些刚开始肩负荒野守护职责的德鲁伊，最先接受的就是他的教导。他向他们介绍翡翠梦境的奥秘，以及其中古老的危险。"}},faq={{q="玛丹特·硬木是谁？",a="玛丹特·硬木在幽影谷的奥达希尔内训练暗夜精灵德鲁伊。他指引泰达希尔上初入门的德鲁伊与自然交流，并学习基础法术。",al={"玛丹特·硬木背景故事","玛丹特是谁","玛丹特 奥达希尔"}},{q="他教导初入门的德鲁伊什么？",a="玛丹特·硬木教导初入门的德鲁伊理解荒野之灵，施放月火等简单法术，并使用治疗魔法。他也教导他们有关翡翠梦境的知识。",al={"玛丹特教什么","玛丹特技能","幽影谷德鲁伊训练师"}},{q="在哪里可以找到玛丹特·硬木？",a="玛丹特·硬木就在幽影谷的奥达希尔内或附近，幽影谷是泰达希尔上暗夜精灵的起始山谷。",al={"玛丹特位置","玛丹特·硬木在哪里"}},{q="绿色符记是什么？",a="这枚符记是交给幽影谷年轻暗夜精灵德鲁伊的指引信物。它指引他们前往玛丹特·硬木处，接受入门训练。",al={"绿色符记任务","交给玛丹特的符记"}}},fx={ff8559f4={q="玛丹特·硬木想要什么？",a="玛丹特希望年轻的暗夜精灵学徒加深与自然的联系。他致力于引导新德鲁伊度过最初的试炼，帮助他们解读灵魂的低语，并应对翡翠梦境深邃的奥秘与危险。",al={"玛丹特想要什么","玛丹特·硬木的目标","玛丹特的目标是什么"}},b78651d9={q="玛丹特·硬木为什么在这里？",a="玛丹特驻守在奥达希尔中空的枝干间，担任新觉醒德鲁伊的导师，陪伴他们在泰达希尔迈出最初的步伐。他留在幽影谷照看新手，教导他们运用与生俱来的力量，并指引他们前往林间空地各处帮助有需要的人。",al={"玛丹特为什么在奥达希尔","玛丹特·硬木为什么在这里","玛丹特·硬木在此地的原因"}},dec3bef7={q="玛丹特·硬木与谁有关联？",a="玛丹特与塞纳里奥议会以及奥达希尔的其他教师关系密切，例如艾露恩的女祭司和守护圣所的哨兵。他们共同引导并培养暗夜精灵年轻的守卫者。",al={"玛丹特·硬木的盟友","玛丹特与谁有关联","玛丹特的人脉关系"}},a3bbc1b2={q="玛丹特·硬木效忠哪一方？",a="玛丹特·硬木忠于暗夜精灵、联盟，以及塞纳里奥议会的神圣信条。他坚定地驻守在幽影谷，守护初生的世界之树，并确保卡多雷德鲁伊的传统在这动荡时期得以延续。",al={"玛丹特·硬木的阵营","玛丹特效忠谁","玛丹特是联盟成员吗"}}},fp="17,159,23.349.0,25.168.0,30.170.0,35.119.0,26.145.0"}
P.entries["npc:marek-ironheart"] = {n="马雷克·铁心",s="在洛克莫丹东南部的旅行者营地，马雷克·铁心考验着那些希望赢得营地认可的猎人。这位经验丰富的矮人恪守荒野的传统。",h="在洛克莫丹东南部的旅行者营地，马雷克·铁心考验着那些希望赢得营地认可的猎人。这位经验丰富的矮人恪守荒野的传统。",kw={"猎杀鳄鱼","旅行者营地","猎人","狩猎","铁心","洛克莫丹","马雷克·铁心"},ang={["class:Hunter"]="身为猎人，你能在考验射击准头和追踪当地野生动物本领的挑战中，体会马雷克·铁心所恪守的旅行者营地传统。",["race:Dwarf"]="身为矮人，你能从马雷克身上看到许多卡兹莫丹矮人珍视的荒野生活传统。他选择在群山中静静守望，而非与铁炉堡的炉火为伴。"},sec={{t="狩猎大师",b="旅行者营地坐落在湖畔上方的山脊上，汇聚了来自矮人各地的神射手和追踪者。马雷克并不在意头衔或夸口。来访者要凭借对付洛克莫丹野兽的本领，以及真正猎人应有的耐心与胆识，赢得猎人们的尊重。"}},faq={{q="马雷克·铁心是谁？",a="在洛克莫丹的旅行者营地，马雷克·铁心考验着那些希望得到营地追踪者和荒野行者接纳的来访者。",al={"马雷克·铁心","马雷克是谁"}},{q="在哪里可以找到马雷克·铁心？",a="马雷克·铁心就在旅行者营地，位于洛克莫丹东南岸沿线的丘陵中。",al={"马雷克·铁心位置","马雷克在哪"}},{q="马雷克提供什么样的任务？",a="马雷克派猎人到湖畔追踪并猎杀当地的野生动物，以控制它们的数量。危险的鳄鱼考验着他们的生存本领。",al={"马雷克·铁心任务","马雷克任务"}},{q="马雷克与其他知名矮人有亲属关系吗？",a="马雷克·铁心可能与考古学家阿达曼特·铁心和伊米·铁心有亲属关系，他们都拥有这个引人注目的矮人姓氏。马雷克将一生投入狩猎，而非发掘遗物。",al={"铁心家族","马雷克亲属"}}},fx={ac3880c9={q="马雷克·铁心站在哪一边？",a="马雷克支持联盟和铁炉堡的矮人氏族。他以洛克莫丹东南部荒野中的旅行者营地为据点，欢迎联盟旅人征服周边荒野，证明自己的实力。",al={"马雷克·铁心的阵营","马雷克·铁心联盟","马雷克·铁心是联盟吗"}},["2928b65a"]={q="马雷克·铁心想要什么？",a="马雷克在洛克莫丹的旅行者营地活动，邀请猎人前去猎杀湖畔的鳄鱼。",al={"马雷克想要什么","马雷克·铁心的目标","为什么与马雷克·铁心交谈"}},ddec60fb={q="马雷克·铁心为什么在旅行者营地？",a="马雷克定居旅行者营地，是为了在洛克莫丹未经驯服的丘陵中考验和训练林地猎手。他从这座偏远的哨站观察当地野生动物，并指引那些想在高地荒野中磨炼野外技艺的猎人。",al={"马雷克为什么在洛克莫丹","马雷克·铁心在旅行者营地的目的","马雷克为什么在这里"}}},fp="15,168,18.283.0,23.124.0,33.108.0,36.120.0,44.185.0"}
P.entries["npc:marisa-du-paige"] = {n="玛里莎·杜派格",s="在死亡矿井外的洞穴中，玛里莎·杜派格与月溪镇的亡命之徒并肩作战。在西部荒野西南部，他们之中的劳工和拦路强盗很少有人能施展奥术魔法。",h="在死亡矿井外的洞穴中，玛里莎·杜派格与月溪镇的亡命之徒并肩作战。在西部荒野西南部，他们之中的劳工和拦路强盗很少有人能施展奥术魔法。",kw={"死亡矿井","人类","法师","玛里莎·杜派格","月溪镇","西部荒野"},ang={["class:Mage"]="玛里莎·杜派格表明，王国中的奥术传承并不局限于肯瑞托的高塔和暴风城的巫师圣所。离经叛道的施法者将自己的本领卖给犯罪团伙。",["faction:Alliance"]="身为联盟冒险者，在月溪镇下方的坑道中，要时刻提防杜派格。扒手之中若有一名施法者，一场小规模交锋也可能迅速变得致命。"},sec={{t="坑道中的奥术之才",b="月溪镇下方的洞穴通往死亡矿井。扒手、叛逃的矿工和暴徒守卫着这些坑道。玛里莎·杜派格也在其中，她是一名技艺娴熟的人类法师。许多施法者在暴风城的法师区接受训练，或为肯瑞托效力，但玛里莎却加入了西部荒野的亡命之徒和强盗，栖身于他们的地下通道。"}},faq={{q="玛里莎·杜派格是谁？",a="玛里莎·杜派格是通往死亡矿井的外围洞穴中的一名稀有人类法师。盗贼和劳工在那些通道中巡逻，而她则施展奥术法术，守卫这片地下通道网。",al={"玛里莎·杜派格","玛里莎是谁","死亡矿井洞穴稀有"}},{q="在哪里能找到她？",a="玛里莎·杜派格偶尔会出现在西部荒野月溪镇下方的非副本洞穴区域。可以在死亡矿井副本传送门外的坑道中找到她。",al={"玛里莎·杜派格位置","玛里莎·杜派格在哪","玛里莎刷新"}},{q="一名人类法师为何藏身于死亡矿井的洞穴中？",a="一些奥术修习者离开了暴风城的高塔。逃兵、叛徒和心怀同情的平民加入了遍布西部荒野的亡命之徒，将刀剑与魔法带到了月溪镇下方的据点。",al={"她为何在这里","玛里莎背景故事","玛里莎·杜派格阵营"}}},fx={["5e8e0d23"]={q="玛里莎·杜派格站在哪一边？",a="玛里莎·杜派格身穿迪菲亚潜行者的服饰，穿行于他们的地下大厅。她潜伏在月溪镇通往死亡矿井的洞穴深处，支持艾德温·范克里夫领导的叛乱兄弟会，用奥术法术攻击任何威胁其据点的入侵者。",al={"玛里莎·杜派格的阵营","玛里莎·杜派格是迪菲亚成员吗","玛里莎·杜派格为谁效力"}}},fp="15,168,28.324.0,23.193.0,23.181.0,50.211.0"}
P.entries["npc:marleth-barleybrew"] = {n="马莱斯·麦酒",s="在烈酒村，马莱斯·麦酒努力证明，自家的麦酒足以媲美雷霆麦酒。雷酒氏族对当地啤酒贸易的垄断令她十分不满，她想让酒客们喝上麦酒家族酿的酒。",h="在烈酒村，马莱斯·麦酒努力证明，自家的麦酒足以媲美雷霆麦酒。雷酒氏族对当地啤酒贸易的垄断令她十分不满，她想让酒客们喝上麦酒家族酿的酒。",kw={"针锋相对","烈酒村","矮人酿酒师","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒"},ang={["race:Dwarf"]="身为矮人，你知道酿酒是一门关乎氏族声望的技艺。马莱斯与雷酒家族的争斗，源于强烈的家族自豪感。"},sec={{t="酿酒之争",b="在丹莫罗，啤酒与钢铁同样重要，麦酒与雷酒两家的竞争早已成为传奇。拉格纳·雷酒和他的族人凭借卡拉诺斯的酿酒厂，控制着几乎所有的啤酒贸易。马莱斯·麦酒相信自家的酒同样醇烈，但她不愿公开挑战雷酒家族。于是，她招募旅人，偷偷将卡拉诺斯酒馆里的酒桶换成麦酒家族的酒。"}},faq={{q="马莱斯·麦酒是谁？",a="马莱斯·麦酒是丹莫罗西部烈酒村的一位矮人酿酒大师。她代表麦酒家族，挑战雷酒家族对当地啤酒贸易的垄断。",al={"马莱斯是谁","马莱斯的故事","马莱斯·麦酒"}},{q="在哪里可以找到马莱斯·麦酒？",a="你可以在丹莫罗西部、涌冰湖附近的烈酒村找到马莱斯·麦酒。",al={"马莱斯的位置","马莱斯在哪里","寻找马莱斯"}},{q="马莱斯为什么想调换雷酒家族的啤酒？",a="马莱斯相信，自家的麦酒不逊于雷霆麦酒，甚至更胜一筹。雷酒家族主导着卡拉诺斯的啤酒贸易，因此她雇用旅人，偷偷将酒馆的酒桶换成麦酒家族的存酒，并带回一份雷霆麦酒样品供她研究。",al={"为什么调换啤酒","针锋相对 任务缘由","为什么憎恨 雷酒 家族"}},{q="麦酒家族还有哪些成员？",a="马莱斯的氏族亲族中，还有从事酿酒和贸易的 马尔金、雷杰德、维拉特和犹鲁斯·麦酒。他们都致力于传承矮人的传统酿酒技艺。",al={"麦酒 家族","马莱斯的亲属"}}},fx={c401045b={q="马莱斯·麦酒站在哪一边？",a="马莱斯是一位自豪的铁炉堡矮人，效忠联盟，不过她眼下的日常心思全放在生意上。她出身于麦酒酿酒家族，竭力捍卫自家的酿造技艺，与当地竞争对手较量。",al={"马莱斯·麦酒效忠谁","马莱斯·麦酒为谁效力","马莱斯的阵营"}},["716c9dd7"]={q="马莱斯·麦酒为什么在烈酒村？",a="烈酒村坐落在丹莫罗白雪覆盖的丘陵间，是当地的一处酿酒据点。马莱斯在这里酿造自己的特色啤酒，并谋划打入被雷酒家族垄断的更大市场。",al={"马莱斯为什么在这里","马莱斯·麦酒烈酒村","马莱斯·麦酒为什么在丹莫罗"}}},fp="18,216,19.414.0,26.192.0,36.93.0,49.272.0,51.160.0"}
P.entries["npc:marryk-nurribit"] = {n="玛瑞克·斯托纳尔",s="玛瑞克·斯托纳尔在寒脊山谷的安威玛尔教导年轻侏儒学习基础奥术。本地的美酒常常让他在授课时分心，他还会向学生讨些零钱买酒喝。",h="玛瑞克·斯托纳尔在寒脊山谷的安威玛尔教导年轻侏儒学习基础奥术。本地的美酒常常让他在授课时分心，他还会向学生讨些零钱买酒喝。",kw={"安威玛尔","啤酒","寒脊","侏儒","法师","玛瑞克","斯托纳尔","训练师"},ang={["class:Mage"]="作为一名在寒脊山谷起步的侏儒法师，你要向玛瑞克学习最初的法术，并领取你的雕文备忘录。",["race:Gnome"]="作为一名在丹莫罗避难的侏儒，你知道玛瑞克是位学者，而且很快就适应了矮人的酒馆生活。"},sec={{t="奥术与麦酒",b="每位初到寒脊山谷的侏儒法师，起初都是玛瑞克的学生。然而，比起授课，一大杯矮人麦酒更能吸引他的注意。他向新来的学生讨些零花钱，还告诫有志研习法术的人，寒脊山谷之外的诺莫瑞根废墟中有辐射，穴居人也在那里肆虐。"}},faq={{q="玛瑞克·斯托纳尔是谁？",a="玛瑞克·斯托纳尔在丹莫罗寒脊山谷的安威玛尔向侏儒传授奥术基础。他负责训练初来乍到的侏儒法师。",al={"玛瑞克·斯托纳尔","玛瑞克是谁","安威玛尔法师训练师"}},{q="玛瑞克为什么总是讨钱买啤酒？",a="玛瑞克喜爱本地的烈酒，常常向学生讨些零钱，去酒馆买啤酒喝。",al={"玛瑞克喝酒","玛瑞克啤酒","他为什么讨零钱"}},{q="玛瑞克对诺莫瑞根说过些什么？",a="玛瑞克告诫新来的法师，不要低估诺莫瑞根遭受辐射的废墟中的危险。",al={"玛瑞克诺莫瑞根","诺莫瑞根警告"}}},fx={["42f80152"]={q="玛瑞克·斯托纳尔站在哪一边？",a="玛瑞克效忠诺莫瑞根流亡者，坚定地支持联盟。他在丹莫罗的矮人东道主身边避难，为初入寒脊山谷的侏儒新手传授奥术知识。",al={"玛瑞克·斯托纳尔的阵营","玛瑞克为谁效力","玛瑞克效忠谁"}},["241b0acf"]={q="玛瑞克·斯托纳尔为什么在安威玛尔？",a="诺莫瑞根在石腭怪肆虐和有毒辐射尘的侵袭下悲惨沦陷后，玛瑞克和幸存的族人逃到了丹莫罗。他如今留在寒脊山谷的安威玛尔，名义上的职责是向侏儒法师新手传授奥术技艺。",al={"玛瑞克为什么在这里","玛瑞克·斯托纳尔安威玛尔","玛瑞克在丹莫罗的目的"}}},fp="15,204,22.307.0,23.145.0,47.99.0,38.89.0"}
P.entries["npc:marshal-dughan"] = {n="治安官杜汉",s="在闪金镇，治安官杜汉守卫着道路，抵御来自矿洞和林地的威胁。他指挥着暴风城的一支小型驻军，狗头人、豺狼人和强盗的侵扰让这支部队疲于应付。为了保卫城镇和附近的农场，他不得不依靠独立行动的冒险者。",h="在闪金镇，治安官杜汉守卫着道路，抵御来自矿洞和林地的威胁。他指挥着暴风城的一支小型驻军，狗头人、豺狼人和强盗的侵扰让这支部队疲于应付。为了保卫城镇和附近的农场，他不得不依靠独立行动的冒险者。",kw={"艾尔文森林","法戈第","闪金镇","霍格","玉石","治安官杜汉","暴风城军队","西泉要塞"},ang={["class:Warrior"]="身为战士，你看到暴风城的步兵即使兵力不足、面对几乎无法战胜的强敌，仍凭借严明的纪律坚守战线。",["faction:Alliance"]="身为艾尔文的联盟新兵，你最初的军事任务由治安官杜汉交付，他是暴风城在当地的掌权者。"},sec={{t="十字路口的指挥官",b="治安官杜汉在闪金镇的狮王之傲旅店外，指挥艾尔文森林的防务。林中的麻烦日益增多，暴风城的士兵却被其他地方的事务牵制。狗头人挤满矿洞，豺狼人聚集在河岸，拦路强盗则在国王大道上骚扰旅人。由于步兵不足，杜汉派遣新兵增援哨站，侦察危险地带。"},{t="四境皆有威胁",b="狗头人占据了法戈第矿洞和玉石矿洞，威胁着闪金镇的矿产供应。镇子西边，霍格麾下的河爪豺狼人不断进逼西泉要塞。东边，卫兵托马斯报告说，凶恶的鱼人正在沿河杀害巡逻士兵。杜汉的士兵太少，无法应对每一处威胁，因此需要能干的雇佣兵协助遏制敌人。"}},faq={{q="治安官杜汉是谁？",a="治安官杜汉指挥着驻扎在闪金镇的一支暴风城军队。他统筹艾尔文森林的防务，抵御盗贼、豺狼人和狗头人。",al={"杜汉","治安官杜汉背景故事","闪金镇治安官"}},{q="杜汉为什么不派更多卫兵支援西泉要塞或东部地区？",a="暴风城的兵力分散，留给杜汉的卫兵仅够维持闪金镇的秩序。他没有足够的士兵守卫每一座农场和边境哨站，只能依靠途经此地的冒险者侦察险情、传递公文，并应对当地的威胁。",al={"为何没有卫兵","闪金镇驻军兵力","杜汉部队"}},{q="杜汉如何看待艾尔文的鱼人威胁？",a="起初，杜汉并未把雷米 '两次'关于鱼人威胁这一地区的警告放在心上。卫兵托马斯报告了罗尔夫·哈特弗德和马拉凯·史东在东部水道沿岸遇害的消息，这才让他确信危险确实存在。",al={"杜汉鱼人","“两次”雷米 鱼人","杜汉 鱼人"}},{q="杜汉如何处理当地的犯罪和滋事平民？",a="杜汉负责维持闪金镇及周边地区的安宁。他说，艾尔文新近出现的麻烦已让维持秩序变得十分艰难，因此他把精力集中在北边的狗头人，以及西边的豺狼人和盗贼身上。",al={"杜汉犯罪","闪金镇法律","监狱威胁"}},{q="杜汉为什么担忧矿洞的状况？",a="法戈第矿洞和玉石矿洞为暴风城供应黄金和矿石。狗头人占据了这两座矿洞，赶走了矿工，还可能在艾尔文各处定居点下方挖掘隧道。",al={"法戈第矿洞杜汉","玉石矿洞杜汉","狗头人侵扰"}},{q="治安官杜汉会与西部荒野协调行动吗？",a="会。在你于艾尔文森林证明自己的能力后，杜汉会派你前往西部荒野的哨兵岭，向格里安·斯托曼报到。人民军需要经验丰富的人手协助对抗迪菲亚潜行者。",al={"杜汉格里安","前往西部荒野报到","杜汉哨兵岭"}}},fx={["72888056"]={q="治安官杜汉站在哪一边？",a="治安官杜汉为暴风城王国和联盟效力。作为暴风城军队的一名军官，他直接听命于王国的军事指挥体系，尽管王室援军日益减少，仍执行王命，维持秩序，保护王国腹地。",al={"杜汉的阵营","杜汉为谁效力","治安官杜汉效忠谁"}},["9141816c"]={q="治安官杜汉想要什么？",a="杜汉希望确保艾尔文森林的安全，保护闪金镇免受日益增多的威胁。他的驻军兵力捉襟见肘，因此他寻求能干的冒险者，侦察遭到盘踞的法戈第和玉石矿洞，遏制西部的迪菲亚匪徒和豺狼人，并评估河岸沿线日益增长的危险。",al={"杜汉的目标","杜汉需要什么","杜汉的任务目标"}},["8808e7de"]={q="治安官杜汉为什么驻守闪金镇？",a="杜汉作为当地暴风城军队分遣队的指挥官，驻守在闪金镇。他负责艾尔文中部的防务，监督镇内治安，协调西泉要塞等哨站，并组织防御，抵挡那些威胁首都粮仓的野兽、狗头人和罪犯。",al={"杜汉为什么在闪金镇","治安官杜汉在这里的目的","杜汉的驻地"}},["156c33b1"]={q="治安官杜汉与谁有联系？",a="杜汉与艾尔文各地前哨的指挥官密切合作，例如西泉要塞的瑞尼尔副队长，以及东部桥梁一带的卫兵托马斯。在艾尔文之外，他与西部荒野的格里安·斯托曼等军中同僚保持联络，分享有关地区犯罪活动的情报。",al={"杜汉的联系","杜汉与谁合作","杜汉的盟友"}}},fp="14,256,27.377.0,23.343.0,22.143.0,75.255.0,53.208.1,55.213.0,40.179.0,45.196.0"}
P.entries["npc:marshal-marris"] = {n="治安官马瑞斯",s="在湖畔镇的桥头，治安官马瑞斯指挥着兵力单薄的卫队，抵挡黑石的进攻。暴风城的军队迟迟未至，他只得求助于途经此地的战士，阻缓兽人在赤脊山的推进。",h="在湖畔镇的桥头，治安官马瑞斯指挥着兵力单薄的卫队，抵挡黑石的进攻。暴风城的军队迟迟未至，他只得求助于途经此地的战士，阻缓兽人在赤脊山的推进。",kw={"黑石","桥","湖畔镇","玛瑞斯","治安官马瑞斯","赤脊山","石堡","萨瑞尔祖恩"},ang={["class:Warrior"]="身为战士，你深知正面作战时严明军纪的价值。Marris派前线战士进入石堡，迎战身经百战的黑石老兵。",["faction:Alliance"]="对联盟而言，治安官马瑞斯的处境表明，当暴风城无力行动时，乡间地区是何等缺乏保护。湖畔镇必须独自奋战，才能生存下去。",["race:Human"]="身为王国的人类子民，你能从Marris身上看到一名边境守卫，坚守防线，抵御Old Horde的残余势力。"},sec={{t="围困中的小镇",b="湖畔镇西有豺狼人，东有黑石氏族。治安官马瑞斯指挥着镇上主桥的守卫，但补给匮乏，士兵也疲于应付。暴风城没有派来王国援军，马瑞斯只能独力守住小镇，防止它被攻陷。"},{t="击溃黑石先锋",b="治安官马瑞斯深知，仅靠防守无法挽救赤脊山，因此下令突袭兽人营地。他派战士们对付黑石战士和暗影法师，随后再去击杀盘踞在石堡要塞废墟中的指挥官萨瑞尔祖恩。马瑞斯打算在兽人大举攻陷湖畔镇之前，先摧毁他们的指挥体系。"}},faq={{q="治安官马瑞斯是谁？",a="治安官马瑞斯负责指挥湖畔镇的防务。他在镇上桥梁的西端附近驻守，致力于加固这处聚居地，抵御来袭之敌。",al={"马瑞斯","治安官马瑞斯的故事","湖畔镇桥头的守卫是谁"}},{q="治安官马瑞斯为何雇用独立冒险者？",a="暴风城派往赤脊山的援军太少，湖畔镇的卫队寡不敌众。豺狼人和黑石兽人步步紧逼，马瑞斯只得雇用佣兵出击，应对这些威胁。",al={"马瑞斯为何需要帮助","暴风城军队为何未至"}},{q="治安官马瑞斯正在对抗哪些威胁？",a="豺狼人侵扰着镇子外围，但治安官马瑞斯主要对抗的是占据石堡要塞的黑石兽人。萨瑞尔祖恩统领着他们，而他们的暗影法师也让湖畔镇和王国面临更大的危险。",al={"马瑞斯的敌人","谁在进攻湖畔镇"}},{q="治安官马瑞斯与纳萨诺斯·玛瑞斯有亲属关系吗？",a="洛丹伦和暴风城这两个人类王国中，都有人以马瑞斯为姓。没有任何记载证实，驻守赤脊山的治安官马瑞斯与北方那位著名游侠纳萨诺斯·玛瑞斯之间存在亲属关系。",al={"马瑞斯与纳萨诺斯有亲属关系吗","马瑞斯的家族"}},{q="马瑞斯打算如何击败黑石氏族？",a="马瑞斯命令战士们击杀黑石步兵，从他们的暗影法师身上收集施法材料，并进入石堡要塞击杀萨瑞尔祖恩。",al={"马瑞斯的计划","如何击败黑石兽人"}},{q="在哪里可以找到治安官马瑞斯？",a="治安官马瑞斯位于赤脊山的湖畔镇，就在镇子中央附近的桥边。",al={"马瑞斯的位置","治安官马瑞斯在哪里"}}},fp="14,193,18.282.0,31.312.0,22.153.0,53.203.0,48.209.0,45.196.0,51.163.0,34.98.0"}
P.entries["npc:marshal-maxwell"] = {n="麦克斯韦尔元帅",s="麦克斯韦尔元帅是暴风城军队的高级军官，驻守在燃烧平原的摩根的岗哨。他奉命守住赤脊山上方联盟最北端的设防山脊，抵御黑石氏族与黑铁矮人，并指挥斥候深入下方危机四伏的峭壁地带。他还在协调各方查明被俘战友雷吉纳德·温德索尔元帅下落的行动中发挥着关键作用。",h="麦克斯韦尔元帅是暴风城军队的高级军官，驻守在燃烧平原的摩根的岗哨。他奉命守住赤脊山上方联盟最北端的设防山脊，抵御黑石氏族与黑铁矮人，并指挥斥候深入下方危机四伏的峭壁地带。他还在协调各方查明被俘战友雷吉纳德·温德索尔元帅下...",kw={"黑石深渊","燃烧平原","达基萨斯将军","麦克斯韦尔元帅","麦克斯韦尔","摩根的岗哨","雷吉纳德·温德索尔","暴风城军队"},ang={["class:Warrior"]="麦克斯韦尔体现了暴风城前线军人的严明纪律，他屹立于火山灰中，协调深入敌后的突袭行动。",["faction:Alliance"]="对于冒着燃烧平原灼热高温前行的联盟勇士而言，麦克斯韦尔元帅代表着暴风城的权威，也是进攻黑石山的先锋。"},sec={{t="平原上的孤哨",b="摩根的岗哨坐落于燃烧平原南缘，处境岌岌可危，俯瞰着一片遍布灰烬、龙类和黑石兽人的荒原。麦克斯韦尔元帅指挥着驻扎于此的暴风城分遣队，为冒险穿越炽热峭壁的旅人带来难得的友善身影。他从这座岩石堡垒统筹防御行动，将山中的敌军牵制在原地，阻止他们向南席卷赤脊山和艾尔文。"},{t="探寻山中真相",b="除了日常的牵制任务，麦克斯韦尔还是深入黑石塔与黑石深渊腹地的行动的主要战地联络官。当传闻称被俘的雷吉纳德·温德索尔元帅可能仍活在黑铁矮人的地牢中时，正是麦克斯韦尔接收情报、筛查报告，并指派值得信赖的勇士展开营救。他的哨站成为一座关键桥梁，将边境侦察与暴风城城门内酝酿的政治动荡联系起来。"}},faq={{q="麦克斯韦尔元帅是谁？",a="麦克斯韦尔元帅是暴风城军队的一名指挥官，驻守在燃烧平原的摩根的岗哨。他率领当地联盟部队，监视着黑石兽人、黑龙和黑铁矮人。",al={"麦克斯韦尔元帅背景故事","麦克斯韦尔是谁"}},{q="麦克斯韦尔元帅为何驻守摩根的岗哨？",a="摩根的岗哨是联盟位于燃烧平原边缘的前线营地。麦克斯韦尔奉命驻守此地，确保通往下方赤脊山的山口安全，并监视从黑石山涌出的威胁。",al={"麦克斯韦尔为何在燃烧平原","摩根的岗哨指挥官"}},{q="麦克斯韦尔与温德索尔元帅有什么关系？",a="雷吉纳德·温德索尔元帅被俘后遭押入黑石深渊，麦克斯韦尔是协助搜寻他的关键指挥官。麦克斯韦尔协助协调营救行动，并将有关温德索尔的重要情报传回暴风城。",al={"麦克斯韦尔与温德索尔","被遗弃的希望任务背景故事"}},{q="麦克斯韦尔元帅是否协助组织对黑石塔的进攻？",a="是的。麦克斯韦尔指挥身经百战的联盟勇士铲除黑石氏族的高层，向盘踞在黑石塔高处的达基萨斯将军及其部队下达打击指令。",al={"麦克斯韦尔 达基萨斯","麦克斯韦尔的任务"}}},fp="15,237,28.363.0,36.371.1,23.198.0,51.176.0,48.208.0,67.191.0"}
P.entries["npc:marshal-mcbride"] = {n="治安官玛克布莱德",s="狗头人威胁着山谷中的农场和矿洞，北郡修道院的治安官杜格拉斯·玛克布莱德向新兵寻求援助。他统率着驻扎在那里的暴风城守军，代表军队在北郡行使职权。",h="狗头人威胁着山谷中的农场和矿洞，北郡修道院的治安官杜格拉斯·玛克布莱德向新兵寻求援助。他统率着驻扎在那里的暴风城守军，代表军队在北郡行使职权。",kw={"杜格拉斯·玛克布莱德","回音山","艾尔文","狗头人","治安官玛克布莱德","北郡","北郡修道院"},ang={["class:Warrior"]="身为战士，你可以协助玛克布莱德清除回音山地道中的狗头人，为王国效力。",["faction:Alliance"]="身为联盟新兵，你的旅程始于人类腹地的Grand Alliance边疆。在那里，玛克布莱德引领新兵为王室效力。",["race:Human"]="身为从北郡启程的人类，你最先见到的是治安官玛克布莱德，他代表暴风城王室在山谷中行使职权。"},sec={{t="北郡的指挥官",b="治安官玛克布莱德只有寥寥几名宣誓效忠的卫兵，负责维持山谷的安宁，保护当地的粮食和资源。王国各地的动荡使各处驻军兵力不足。初出茅庐的新兵来到修道院，希望接受导师们的训练，于是玛克布莱德便派他们去保卫山谷。"},{t="狗头人的入侵",b="北郡周围的狗头人变得愈发猖獗。它们蔓延至林间，还占据了当地一处重要的资源产地——回音山矿洞。由于正规军人手不足，玛克布莱德召集圣骑士、战士和其他新手，击退这些挖掘地道的狗头人。他需要他们在山谷与外界的联系被切断之前，查明狗头人究竟侵占了多大范围。"}},faq={{q="治安官玛克布莱德是谁？",a="治安官玛克布莱德统率着驻扎在北郡修道院的暴风城守军。他保卫北郡山谷，并指派新兵执行任务。",al={"治安官玛克布莱德","玛克布莱德是谁","北郡指挥官"}},{q="玛克布莱德为什么让新兵对付狗头人？",a="狗头人已经占据了北郡周围的树林和回音山矿洞。暴风城的兵力捉襟见肘，因此玛克布莱德派新来的冒险者驱逐它们，确保这一带的安全。",al={"为何消灭狗头人","狗头人问题","回音山的问题"}},{q="玛克布莱德接下来会派新兵去哪里？",a="新兵处理完北郡山谷的威胁后，玛克布莱德便会派他们沿路南下，前往闪金镇协助治安官杜汉。",al={"完成玛克布莱德的任务后去哪里","离开北郡之后","下一个城镇"}},{q="回音山矿洞是什么地方？",a="回音山矿洞位于北郡山谷北缘，矿产丰富。狗头人已经占据了这里，玛克布莱德已多次下令夺回矿洞。",al={"回音山","北郡的矿洞"}},{q="玛克布莱德也掌管修道院本身吗？",a="不。北郡修道院由信奉圣光的神圣教团和牧师管理。玛克布莱德统率的是保卫修道院及周围山谷的驻军。",al={"玛克布莱德掌管北郡修道院吗","谁负责管理修道院"}},{q="除了狗头人，玛克布莱德还担忧其他威胁吗？",a="狗头人是玛克布莱德眼下最迫切的忧患，但山谷边缘仍有强盗和不法之徒盘踞。这些迹象表明，艾尔文森林各处都存在动荡。",al={"北郡的迪菲亚","北郡安全吗"}}},fx={["05ea779e"]={q="治安官玛克布莱德效忠谁？",a="治安官玛克布莱德是忠于暴风城军队和大联盟的军官。他听命于暴风城王室，守卫北郡山谷，确保王国居民和受训新兵的安全。",al={"玛克布莱德效忠谁","玛克布莱德的效忠对象","玛克布莱德属于哪个阵营"}},b6028054={q="治安官玛克布莱德想要什么？",a="玛克布莱德想要抵御日益加剧的当地威胁，保卫北郡山谷。暴风城军队兵力捉襟见肘，因此他寻求动员新兵、圣骑士和志愿者，清剿盘踞山谷的凶恶狗头人，夺回回音山矿洞。",al={"玛克布莱德的目标","玛克布莱德想做什么","玛克布莱德的计划"}},cc66b2df={q="治安官玛克布莱德为什么在这里？",a="玛克布莱德是山谷驻军的指挥官，驻守在北郡修道院外。暴风城命他维持秩序、组织防御并训练新来者，再将经受过考验的士兵派往艾尔文森林及更远的地方。",al={"玛克布莱德为何在北郡","玛克布莱德的驻地","治安官玛克布莱德为何在修道院"}},["307fdf7d"]={q="治安官玛克布莱德与谁有联系？",a="玛克布莱德听命于暴风城军队最高指挥部，并与艾尔文各地的地方官员协调，最终将有能力的战士引荐给闪金镇的治安官杜汉。他与修道院的神职人员和训练师合作，为王国培养新的守卫者。",al={"玛克布莱德的联系","玛克布莱德向谁汇报","玛克布莱德 暴风城军队"}}},fp="15,192,23.304.0,20.340.0,23.134.0,45.195.0,38.134.0,24.163.0,38.169.0,50.152.0"}
P.entries["npc:martie-jainrose"] = {n="玛蒂·詹罗斯",s="在湖畔镇，玛蒂·詹罗斯照料着止水湖畔的一座花园。她为镇民采集草药和鲜花，野兽却时常威胁她的园圃，而她似乎对卫兵帕克颇有好感。",h="在湖畔镇，玛蒂·詹罗斯照料着止水湖畔的一座花园。她为镇民采集草药和鲜花，野兽却时常威胁她的园圃，而她似乎对卫兵帕克颇有好感。",kw={"贝利格拉布","水仙花","卫兵帕克","草药师","湖畔镇","玛蒂·詹罗斯","赤脊山"},ang={["faction:Alliance"]="身为联盟的旅人，你能在湖畔镇看到玛蒂的坚持。暴风城基本上任由这座镇子自谋生路，赤脊山的居民却仍维持着平凡的生活。",["profession:Herbalism"]="身为途经赤脊山的草药师，你和玛蒂一样关爱着脆弱的植物，即使野猪和步步逼近的敌人正威胁着它们。"},sec={{t="湖畔的花园",b="玛蒂·詹罗斯是湖畔镇的草药师，为镇子栽培草药和鲜花。黑石兽人、豺狼人和当地的强盗威胁着赤脊山，但玛蒂仍为镇子供应新鲜草药和插花。野兽时常妨碍她的工作，尤其是贝利格拉布，这头巨大的野猪经常糟蹋她的花圃。玛蒂似乎还对卫兵帕克颇有好感。帕克正在追求达希，而达希称玛蒂是个心怀嫉妒的情敌。"}},faq={{q="玛蒂·詹罗斯是谁？",a="玛蒂·詹罗斯在赤脊山的湖畔镇照料草药。她的花园坐落在止水湖畔，她在那里种植草木，为当地居民配制药剂。",al={"玛蒂·詹罗斯","玛蒂是谁","湖畔镇草药师"}},{q="当地的野兽给玛蒂带来了什么麻烦？",a="贝利格拉布是一头庞大而顽固的野猪，时常闯入玛蒂的花园。它践踏她的植物，还没等她采收，就吃掉了她的草药。",al={"玛蒂的野猪麻烦","贝利格拉布花园","谁在破坏她的花园"}},{q="玛蒂喜欢湖畔镇的谁？",a="玛蒂似乎对湖畔镇的守卫之一，卫兵帕克颇有好感。帕克正在追求达希。他送给达希一束玛蒂种的水仙花时，特意叮嘱不要告诉玛蒂花是送给谁的。",al={"玛蒂的心上人","玛蒂卫兵帕克","送水仙花的恋情"}}},fp="15,184,20.437.0,23.173.0,54.138.0,35.187.0"}
P.entries["npc:marukai"] = {n="玛鲁凯",s="在佐拉姆加前哨站，玛鲁凯坚守着部落偏远的海滩据点，抵御怒尾娜迦的进攻。这位黑暗之矛丛林巨魔统筹战事，要将灰谷西北部雾气笼罩的海岸上的娜迦击退。",h="在佐拉姆加前哨站，玛鲁凯坚守着部落偏远的海滩据点，抵御怒尾娜迦的进攻。这位黑暗之矛丛林巨魔统筹战事，要将灰谷西北部雾气笼罩的海岸上的娜迦击退。",kw={"灰谷","黑暗之矛","丛林巨魔","玛鲁凯","娜迦","怒尾","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="在暗夜精灵的领地上，玛鲁凯支撑着部落处境最为险峻的海岸营地之一。她依靠盟友中的勇士，阻止当地的娜迦攻陷他们的阵地。",["race:Troll"]="远离森金村温暖的回响，玛鲁凯展现出黑暗之矛部族的坚韧，他们正为部落在卡利姆多各地开辟坚固的据点。"},sec={{t="坚守海岸",b="在佐拉姆加前哨站，玛鲁凯竭力守住营地，防止它被敌人攻陷。前哨站坐落在佐拉姆海岸北端，周围是古老的废墟、敌对的暗夜精灵领地和波涛汹涌的大海。怒尾娜迦从海中和古老的精灵废墟里大举涌出，企图占据海岸。玛鲁凯指挥部落勇士将它们赶回海中，并收集它们的头颅，让前哨站得以继续充当海岸上的坚固据点。"}},faq={{q="玛鲁凯是谁？",a="玛鲁凯是一名丛林巨魔，守卫着佐拉姆加前哨站——部落在灰谷西北海岸上的孤立营地。",al={"玛鲁凯故事","玛鲁凯是谁","玛鲁凯非玩家角色"}},{q="玛鲁凯为什么与娜迦作战？",a="怒尾娜迦已经盘踞在附近的佐拉姆海岸及周边废墟中。为了保卫前哨站的边界，确保部落能在海岸上生存，玛鲁凯雇用冒险者直接猎杀它们，削减它们的数量。",al={"为什么杀娜迦","玛鲁凯娜迦任务","佐拉姆海岸娜迦"}},{q="玛鲁凯在哪里？",a="玛鲁凯与她的族人驻守在佐拉姆加前哨站，位于灰谷西北部的佐拉姆海岸入口处，就在沉入水中的黑暗深渊废墟以南。",al={"玛鲁凯在哪里","玛鲁凯位置","寻找玛鲁凯"}}},fp="7,164,18.400.0,15.119.0,33.201.0,25.165.0"}
P.entries["npc:master-apothecary-faranell"] = {n="大药剂师法拉尼尔",s="在幽暗城，大药剂师法拉尼尔从炼金房深处领导着皇家药剂师学会。他曾是备受尊敬的达拉然学者，如今却指挥被遗忘者研究新的瘟疫，企图消灭天灾军团和所有生者。",h="在幽暗城，大药剂师法拉尼尔从炼金房深处领导着皇家药剂师学会。他曾是备受尊敬的达拉然学者，如今却指挥被遗忘者研究新的瘟疫，企图消灭天灾军团和所有生者。",kw={"憎恶","炼金房","凋零","法拉尼尔","大药剂师法拉尼尔","新的瘟疫","伦弗利尔","皇家药剂师学会","希尔瓦娜斯","幽暗城"},ang={["faction:Horde"]="身为部落的一员，你可能会对绿色软泥和笼中的实验对象感到不安。法拉尼尔的研究被视为对抗Scourge的重要作战手段，因此得以受到容忍。",["profession:Herbalism"]="身为草药师，你知道珍稀植物、苔藓和真菌提取物如何填满法拉尼尔的药池。他的工作将植物研究引向了毁灭。",["race:Undead"]="身为被遗忘者，你能看到法拉尼尔正在研制武器，意图粉碎巫妖王的力量，保障你族人的未来。"},sec={{t="被死亡扭曲的心智",b="在第三次大战之前，法拉尼尔曾花费数十年，与达拉然博学的法师们一同钻研炼金术。生前，他致力于寻找疗法、药物和药剂，改善凡人的健康。天灾军团的瘟疫夺走了他的生命，但他又以拥有自由意志的被遗忘者之身复生。他对科学的求知欲变得残酷，用于疗伤的药膏也被灾难性的试剂取代。他渊博的学识，使他成为希尔瓦娜斯·风行者女王在洛丹伦陷落的都城深处最为器重的研究者之一。"},{t="炼金房之主",b="法拉尼尔在炼金房统筹皇家药剂师学会遍布各地的研究。他监督制造行动迟缓的憎恶，并指挥驻扎在洛丹伦及更远地区的药剂师。各大陆的外勤研究员搜集奇异的毒液、受污染的血液和被诅咒的植物。每一批材料都要送入他的药池，经过蒸馏和提纯。"},{t="研制新的瘟疫",b="法拉尼尔致力于执行黑暗女王的命令，研制出新的瘟疫。他寻求一种能消灭阿尔萨斯及其麾下无意识的天灾军团的疫病。为此，他统筹收集多种试剂。他派遣冒险者前往焚木村，取回已故同僚药剂师博拉尔德的研究笔记。他还需要剃刀沼泽幽深巢穴中的蝙蝠粪便，并用血色修道院狂热者的器官测试酸性胶质。"}},faq={{q="大药剂师法拉尼尔是谁？",a="法拉尼尔领导着皇家药剂师学会，这是幽暗城中效忠希尔瓦娜斯·风行者女士的炼金术组织。他监督毒素、缝合憎恶和新的瘟疫的研究。",al={"法拉尼尔是谁","法拉尼尔背景故事","药剂师首领"}},{q="在哪里能找到法拉尼尔？",a="法拉尼尔居住在炼金房，也就是幽暗城西部的炼金区。他的周围摆着冒泡的药锅和关押实验对象的牢笼，还有他手下的药剂师。",al={"法拉尼尔位置","大药剂师法拉尼尔在哪里","寻找法拉尼尔"}},{q="法拉尼尔生前有怎样的经历？",a="生前的法拉尼尔是一位享有盛名的炼金师和医师，曾与达拉然的巫师一同学习。他曾研制治疗疾病的药物，直到瘟疫夺走他的生命，将他的求知欲引向致命毒素。",al={"法拉尼尔历史","法拉尼尔曾在达拉然吗","法拉尼尔生前"}},{q="皇家药剂师学会试图制造什么？",a="在希尔瓦娜斯女王的指示下，皇家药剂师学会正在研制新的瘟疫。这个组织寻求一种毒性足以消灭天灾军团的武器，让被遗忘者向巫妖王复仇，同时保护他们免受凡人敌人的侵害。",al={"新的瘟疫是什么","药剂师在制造什么","药剂师的目标"}},{q="法拉尼尔为什么派冒险者前往焚木村？",a="法拉尼尔想要找回前同僚药剂师博拉尔德的研究日志，后者在焚木村陷入疯狂，并屈服于狼人的诅咒。博拉尔德的实地笔记记载了有关有毒物质的关键数据，是改进瘟疫实验所必需的。",al={"死亡配方任务 法拉尼尔","为什么去焚木村","药剂师博拉尔德日志"}},{q="他为什么需要剃刀沼泽和血色修道院的试剂？",a="法拉尼尔测试不稳定化合物之间如何相互作用。他用剃刀野猪人巢穴中的沼泽蝙蝠粪便，以及刚从血色十字军狂热者身上取出的心脏，测试酸性胶质和生物污染。",al={"沼泽蝙蝠粪便 法拉尼尔","狂热之心","血色修道院心脏"}}},fp="26,227,24.462.0,30.369.0,23.482.1,34.193.0,28.188.0,46.209.0,54.242.0,55.238.0,72.205.0"}
P.entries["npc:master-apothecary-lydon"] = {n="药剂师林度恩",s="在塔伦米尔，药剂师林度恩为皇家药剂师学会研究毒药。他百无聊赖，沉浸在忧郁之中，却以致命药剂及其造成的痛苦为乐。他的研究旨在为被遗忘者巩固对希尔斯布莱德的控制，并推进Sylvanas的新的瘟疫研制。",h="在塔伦米尔，药剂师林度恩为皇家药剂师学会研究毒药。他百无聊赖，沉浸在忧郁之中，却以致命药剂及其造成的痛苦为乐。他的研究旨在为被遗忘者巩固对希尔斯布莱德的控制，并推进Sylvanas的新的瘟疫研制。",kw={"药剂师","苦楚药剂","法拉尼尔","希尔斯布莱德","林度恩","皇家药剂师学会","塔伦米尔","乌比"},ang={["faction:Alliance"]="在南海镇的人类眼中，林度恩是个可怕的存在，他调制致命疫病，不加区分地拿被俘的希尔斯布莱德农夫和野生动物进行试验。",["profession:Herbalism"]="林度恩的工作间里堆放着材料、药锅和腐烂的植物，展现了皇家药剂师学会如何将传统的采集技艺用于自身的研究。",["race:Undead"]="身为亡灵，林度恩体现了皇家药剂师学会的使命：研制新的瘟疫，为被遗忘者争取未来，并消灭生者。"},sec={{t="塔伦米尔的隐士",b="在塔伦米尔已被改作实验室的礼拜堂里，药剂师林度恩从事着皇家药剂师学会的冷酷工作。盛开的鲜花和希尔斯布莱德丘陵的清新空气，只会加深他那慵懒的忧郁。死亡技艺是唯一能驱散他愁绪的消遣。独处时，他一边等待新的材料送来，一边反复毒死、解剖并复活他的宠物青蛙乌比。"},{t="痛苦的配方",b="林度恩与幽暗城的大药剂师法拉尼尔合作，在希尔斯布莱德各地开展实地试验。他的研究从受难药剂逐步推进到毒性猛烈的苦楚药剂。他派冒险者在当地的野生动物、家畜和被俘的人类农夫身上试验这些药剂。他全心效忠黑暗女王，渴望他们最终制成的新的瘟疫能净化生者的世界。"},{t="洛阿的毒液",b="林度恩也研究神秘的毒药。当神秘的毒液瓶出现在这一带时，他请加德林大师等巨魔秘术师追查其来源。线索指向辛特兰的蜘蛛女神沙德拉。收集到的原始毒液会被送往幽暗城的炼金房，以推进被遗忘者的瘟疫研制。"}},faq={{q="药剂师林度恩是谁？",a="林度恩在希尔斯布莱德丘陵的塔伦米尔担任皇家药剂师学会的炼金师。他为希尔瓦娜斯·风行者女士负责试验性瘟疫与毒素的研究。",al={"林度恩是谁","林度恩 塔伦米尔","药剂师林度恩背景故事"}},{q="林度恩为何如此消沉？",a="林度恩沉浸在忧郁之中，对希尔斯布莱德的自然美景和新鲜空气深感厌恶。只有残酷的实验、生者的痛苦，以及炼金防腐液的气味，才能让他振作起来。",al={"他为何悲伤","林度恩的忧郁","林度恩为何忧郁"}},{q="乌比是谁？",a="乌比是林度恩养在工作间里的青蛙，他戏谑地称她为自己的助手。为了排遣无聊，他反复给她下毒，将她杀死，再让她复活。",al={"林度恩的青蛙","青蛙是谁","乌比背景故事"}},{q="苦楚药剂是什么？",a="苦楚药剂是林度恩用泥头花调制的试验性毒药，之后再用大药剂师法拉尼尔的腐烂的胶质加以精炼。他用强力巨魔之血药水、刺脊纳迦的鳞片和碎鳍鱼人的眼球将其激活，再掺入一桶从丹加洛克矮人那里偷来的烈性啤酒中，用希尔斯布莱德被俘的农夫进行试验。",al={"苦楚药剂任务","苦楚药剂是什么","林度恩的药剂"}},{q="林度恩是如何成为被遗忘者的？",a="没有记录说明林度恩如何死去，又如何复生。和其他被遗忘者一样，他在希尔瓦娜斯的领导下摆脱了巫妖王的控制，如今将自己的亡灵生涯献给黑暗女王及其新的瘟疫。",al={"林度恩的过去","林度恩曾是人类吗","林度恩 第三次大战"}},{q="林度恩向幽暗城运送什么？",a="在辛特兰找到古老的毒液容器，并协助击败巨魔蜘蛛神沙德拉之后，林度恩收集了她浓缩的神圣毒液。他将毒液直接送给大药剂师法拉尼尔，以加强皇家药剂师学会的瘟疫研究。",al={"林度恩 幽暗城 毒液","沙德拉毒液任务"}}},fp="16,262,26.337.0,20.394.1,16.348.1,24.176.0,26.225.0,12.149.0,28.349.1,30.194.0,38.265.1"}
P.entries["npc:master-gadrin"] = {n="加德林大师",s="在森金村，加德林大师指引黑暗之矛度过流亡与丧失亲友的苦难。这位年长的巫医曾与扎拉赞恩一同教导部族的牧师和法师。如今，他帮助族人，设法解除笼罩着回音群岛故土的黑暗诅咒。",h="在森金村，加德林大师指引黑暗之矛度过流亡与丧失亲友的苦难。这位年长的巫医曾与扎拉赞恩一同教导部族的牧师和法师。如今，他帮助族人，设法解除笼罩着回音群岛故土的黑暗诅咒。",kw={"黑暗之矛","杜隆塔尔","回音群岛","加德林","加德林大师","明希纳","森金村","沃金","巫医","扎拉赞恩"},ang={["class:Mage"]="身为法师，你走的是加德林大师在第三次大战之后向黑暗之矛传授奥术时开辟的道路。他的教导表明，巨魔魔法所能企及的领域，可以超越原始的仪式魔精。",["class:Priest"]="身为牧师，你承袭着加德林大师传授给黑暗之矛的传统：与灵魂及洛阿沟通，这些传统融汇着丛林巨魔的暗影之道与信仰。",["faction:Horde"]="身为部落的一员，你可以将加德林大师视为沃金最信任的顾问之一。他守望着杜隆塔尔的海岸，当黑暗教团威胁杜隆塔尔这个新生国度时，便向剃刀岭发出警告。",["race:Troll"]="身为黑暗之矛巨魔，加德林大师是你与祖先故土及森金传统之间活生生的纽带。他培养了部族数代精神领袖，也如父亲一般，为回音群岛的悲剧而哀痛。"},sec={{t="黑暗之矛的导师",b="在黑暗之矛抵达卡利姆多之前，加德林大师已在南海指引了数代族人。他在族人世代居住的岛屿上担任巫医，传授部族的神秘法门。"},{t="扎拉赞恩的背叛",b="在回音群岛，加德林大师曾与年轻的巫医扎拉赞恩一同教导部族的牧师和法师。扎拉赞恩受到自己试图驾驭的黑暗巫毒引诱，陷入了疯狂。他奴役族人的心智，将沃金和未受腐化的黑暗之矛赶到了杜隆塔尔的大陆上。如今身在森金村，加德林承受着亲眼看见同伴沦为暴君的悲痛。他努力让遇害的族人安息，并终结扎拉赞恩的统治。"},{t="古老学识的守护者",b="加德林大师对巨魔通灵之术与洛阿知识的了解，在部落现存的成员中几乎无人能及。学者、萨满祭司和皇家药剂师学会都向他请教奥术与炼金术的奥秘。当火刃氏族威胁杜隆塔尔，或远方的研究者需要失传的仪式时，加德林便会运用自己的学识。他派冒险者前往祖尔法拉克，阅读记载着蜘蛛洛阿沙德拉真名的石板。随后，他制作这种仪式所需的束缚之物。"}},faq={{q="加德林大师是谁？",a="加德林大师是一位巫医，也是年长的精神领袖，指引着黑暗之矛。他住在杜隆塔尔海岸的森金村，为酋长沃金提供建议。",al={"加德林大师背景故事","加德林是谁","加德林 角色"}},{q="加德林与扎拉赞恩有怎样的过往？",a="加德林大师和年轻的巫医扎拉赞恩曾在回音群岛教导黑暗之矛的牧师和法师。加德林亲眼看着扎拉赞恩堕入黑暗魔法，丧失理智，将部族赶出了岛上的家园。",al={"加德林与扎拉赞恩","加德林如何认识扎拉赞恩","扎拉赞恩的导师"}},{q="加德林为何留在森金村？",a="加德林大师留在森金村，那是幸存者被扎拉赞恩的诅咒逐出回音群岛后，在杜隆塔尔南部海岸建起的避难所。他为难民提供指引，留意当地的威胁，并指挥对扎拉赞恩势力的袭击。",al={"加德林为何在此","加德林在森金村做什么"}},{q="明希纳是谁？",a="明希纳是加德林大师的兄弟。他死于回音群岛的动乱，此后，他不得安息的灵魂开始在梦中呼唤加德林。加德林请信得过的冒险者找回兄弟的颅骨，让明希纳的灵魂得以安息。",al={"明希纳兄弟","明希纳的颅骨任务背景","明希纳是谁"}},{q="加德林会协助对付火刃氏族教团吗？",a="会。在祖雷萨报告火刃氏族渗入试炼谷后，加德林大师便开始留意森金村附近的教团动向。他看出这会危及杜隆塔尔，于是派新兵北上，到剃刀岭向奥戈尼尔·魂痕报告。",al={"火刃氏族 杜隆塔尔 加德林","奥戈尼尔·魂痕 加德林"}},{q="加德林对洛阿沙德拉有何了解？",a="加德林大师通晓巨魔神学的古老教义。当被遗忘者的药剂师林度恩寻找辛特兰枯木巨魔使用的一种强效毒液时，加德林认出那是蜘蛛洛阿沙德拉的恩赐。他派冒险者前往祖尔法拉克，阅读刻有她真名的石板，因为他需要用这个名字书写召唤法术。",al={"沙德拉 蜘蛛洛阿 加德林","加德林 蜘蛛之神"}}},fp="13,209,23.197.0,24.466.0,22.465.0,21.158.0,39.218.0,41.247.0,16.238.0,45.248.0,43.334.0"}
P.entries["npc:master-vornal"] = {n="沃纳尔大师",s="在森金村，沃纳尔大师为黑暗之矛巨魔调制药剂和烈酒，却对自己的技艺守口如瓶。这位年迈的丛林巨魔精通炼金术，却不肯收徒。",h="在森金村，沃纳尔大师为黑暗之矛巨魔调制药剂和烈酒，却对自己的技艺守口如瓶。这位年迈的丛林巨魔精通炼金术，却不肯收徒。",kw={"沃纳尔大师","黑暗之矛","杜隆塔尔","森金村","巨魔","沃纳尔"},ang={["profession:Herbalism"]="掌握采药技能的你能看出，沃纳尔大师正在为他的溶剂寻找稀有的催化剂和性质猛烈的天然试剂。",["race:Troll"]="身为黑暗之矛巨魔，你能看出，沃纳尔大师也是那些固执的老工匠之一，在部族逃离海岛家园后，曾帮助建立森金村。"},sec={{t="森金的固执酿酒师",b="沃纳尔大师在森金村为黑暗之矛巨魔同胞调制药剂和烈酒。年岁渐长，他却依旧执意独自做事，不肯教导学徒。他的药物和不稳定的混合药剂都由自己亲手调配。"},{t="烈性之魂",b="沃纳尔大师有时会派年轻的冒险者到周边地区，收集性质猛烈或不寻常的原料。这些材料会被用来调配溶剂和其他混合物。他会酬谢帮忙的人，却严守自己的手法和配方，调制工作始终由自己完成。"}},faq={{q="沃纳尔大师是谁？",a="沃纳尔大师是一位年迈的黑暗之矛丛林巨魔，在森金村调制烈酒和药物。他坚持独自做事，不收学徒。",al={"沃纳尔大师","沃纳尔","森金 沃纳尔大师","沃纳尔是谁"}},{q="在哪里可以找到沃纳尔大师？",a="沃纳尔大师就在森金村的茅屋之间。村子位于杜隆塔尔南部海岸，就在回音群岛以北。",al={"沃纳尔位置","沃纳尔大师在哪里","寻找沃纳尔大师"}},{q="沃纳尔大师为什么不肯收徒？",a="沃纳尔大师说，还没有值得他教导的巨魔或兽人前来求学。他的视力日渐衰退，越来越依赖炼金术，但他宁愿独自做事，也不愿教导不配学习这门技艺的人。",al={"沃纳尔学徒","为什么不收徒","沃纳尔学生"}},{q="他会交给冒险者什么任务？",a="沃纳尔大师会派游历者前往这一带各处，为他的溶剂收集原料。他依靠旅人提供材料，调制工作则由自己完成。",al={"沃纳尔大师任务","溶剂","沃纳尔任务"}}},fp="13,180,30.247.0,16.280.0,21.146.0,31.119.0,50.190.0,37.182.0"}
P.entries["npc:mastok-wrilehiss"] = {n="马斯托克·维尔西斯",s="在灰谷东部的碎木岗哨，马斯托克·维尔西斯协助部落守住阵地。他指派斥候和战士监视附近的边界，在暗夜精灵的敌意中对抗腐化的元素力量。",h="在灰谷东部的碎木岗哨，马斯托克·维尔西斯协助部落守住阵地。他指派斥候和战士监视附近的边界，在暗夜精灵的敌意中对抗腐化的元素力量。",kw={"灰谷","大地之环","马斯托克","兽人","碎木岗哨","石爪山脉","维尔西斯"},ang={["class:Shaman"]="身为萨满祭司，你可能会受马斯托克指派，前往Zoram'gar Strand，就元素生物遭到腐化的问题寻求大地之环的指引。",["faction:Alliance"]="马斯托克代表着兽人在灰谷的驻军力量，守卫碎木岗哨，抵御暗夜精灵Sentinels的进攻。",["faction:Horde"]="身为部落的勇士，你可以向马斯托克领取任务，帮助部落守住灰谷的边疆。"},sec={{t="古老林地中的亡灵壁垒",b="在灰谷茂密的树冠之下，碎木岗哨四周都是怀有敌意的暗夜精灵领地。马斯托克·维尔西斯协助保卫这座岗哨，监视补给路线和周围的森林。哨兵认为这处定居点是对其土地的侵占与破坏，只要发现一丝破绽，就会迅速出击。"},{t="协调前线",b="马斯托克在营地的围栅内，向过往的冒险者分派与部落防务有关的任务。他监视通往石爪山脉的边界，并派遣斥候前去与萨满祭司交谈，其中就有驻留在佐拉姆加海岸的大地之环成员耶努萨克雷。他也在追查侵蚀当地元素生物的诡异腐化。"}},faq={{q="马斯托克·维尔西斯是谁？",a="马斯托克·维尔西斯是驻守灰谷碎木岗哨的一名兽人军官。他协助岗哨抵御暗夜精灵的进攻，并调查这一地区的威胁。",al={"马斯托克是谁","马斯托克·维尔西斯的职责","这个兽人是谁"}},{q="在哪里可以找到马斯托克·维尔西斯？",a="你可以在碎木岗哨内找到马斯托克·维尔西斯。这座设有防御工事的部落岗哨位于灰谷中东部，坐落在穿越森林的主路旁。",al={"马斯托克的位置","马斯托克·维尔西斯在哪里","马斯托克地图"}},{q="马斯托克会向冒险者分派哪些任务？",a="马斯托克指派部落冒险者调查遭到腐化的元素生物，确保通往石爪山脉的路线安全，并向大地之环的耶努萨克雷传递消息。",al={"马斯托克的任务","马斯托克提供的任务"}},{q="碎木岗哨为何始终承受着压力？",a="碎木岗哨是部落在灰谷的伐木枢纽和据点。暗夜精灵认为兽人的驻留和伐木行为亵渎了神圣的土地，双方的小规模冲突持续不断。",al={"暗夜精灵为何攻击碎木岗哨","碎木岗哨的冲突"}},{q="马斯托克为何派旅行者去找耶努萨克雷？",a="马斯托克派旅行者去找耶努萨克雷，是因为大地之环的萨满祭司正在研究并平息灰谷的元素失衡。他们的知识有助于应对遭到污染的水元素和种种异常扰动。",al={"为何联系大地之环","马斯托克与耶努萨克雷"}},{q="马斯托克·维尔西斯是否敌视联盟玩家？",a="是的。马斯托克为部落效力，守卫着碎木岗哨。他会攻击靠近营地的联盟成员。",al={"联盟能否与马斯托克交谈","马斯托克能否被击杀"}}},fp="16,214,30.301.0,22.327.0,24.163.0,36.135.0,45.160.0,49.187.0,49.209.0,48.118.0"}
P.entries["npc:mathias-shaw"] = {n="Mathias Shaw",s="在旧城区，马迪亚斯·肖尔执掌暴风城的秘密情报机构SI:7。他从暗中派出间谍与斥候，守护王国，抵御内部的阴谋与外界的恐怖威胁。",h="在旧城区，马迪亚斯·肖尔执掌暴风城的秘密情报机构SI:7。他从暗中派出间谍与斥候，守护王国，抵御内部的阴谋与外界的恐怖威胁。",kw={"刺客","凋零者","吉尔妮","马迪亚斯·肖尔","旧城区","si:7","间谍首领","暴风城","范克里夫"},ang={["class:Rogue"]="作为潜行者，你可以将马迪亚斯·肖尔视为精通人类潜行者技艺的大师。联盟潜行者经常被派往他那里，接受高阶战术任务并领取特制毒药。",["faction:Alliance"]="作为联盟的一员，你可以信赖肖尔为伯瓦尔·弗塔根公爵和少年国王Anduin搜集军事情报。他的间谍守护着王国，防范颠覆阴谋。",["race:Human"]="作为人类，你可以将迪菲亚潜行者的叛乱视为暴风城王国重建后深刻分裂的一部分。"},sec={{t="SI:7的首领",b="马迪亚斯·肖尔在旧城区兵营后方的SI:7秘密总部，统领暴风城的间谍与刺客。他的秘密情报网遍布东部王国，甚至延伸至更远的地方。肖尔忠于乌瑞恩家族，审慎地权衡每一项威胁。暗中的匕首与窃取的密信，如同铠甲和宫廷卫兵一样，守护着暴风城。"},{t="范克里夫的阴影",b="马迪亚斯·肖尔曾称艾德温·范克里夫为儿时的伙伴。他教导范克里夫潜行与暗杀之术，希望这位才华出众的石匠能与自己一同为王国效力。然而，暴风城重建后，石匠行会遭到驱逐，范克里夫便用这些本领对抗王室。如今，肖尔指挥着遍布西部荒野的监视与渗透行动，试图粉碎旧友的叛乱。"},{t="遍布诸国的耳目",b="除了西部荒野与艾尔文的动乱，马迪亚斯·肖尔还关注着更远处的威胁。有关被遗忘者在东瘟疫之地异常行动的报告，促使他派出五名最优秀的密探前去调查。只有一人活着归来，口中胡乱念叨着“纳萨诺斯”和“凋零者”，几天后便在睡梦中死去。如今，肖尔依靠值得信赖的勇士前往斥候失踪之地，查明王国边境正在聚集的危险。"}},faq={{q="马迪亚斯·肖尔是谁？",a="马迪亚斯·肖尔领导着SI:7，这是暴风城的情报机构，也是刺客公会。他坐镇旧城区，奉王室之命，指挥王国的间谍与秘密防卫行动。",al={"肖尔是谁","si7首领","马迪亚斯·肖尔背景故事","暴风城间谍首领"}},{q="在哪里可以找到马迪亚斯·肖尔？",a="马迪亚斯·肖尔位于暴风城旧城区的SI:7总部内，就在兵营后方。",al={"肖尔位置","马迪亚斯·肖尔在哪里","寻找马迪亚斯·肖尔"}},{q="他与艾德温·范克里夫有什么关系？",a="肖尔与艾德温·范克里夫的关系，是西部荒野的秘密之一。他在写给格里安·斯托曼的报告中，记录了SI:7所掌握的石匠行会情报。将迪菲亚潜行者的线索追查到底，便能了解两人的关系有多深。",al={"肖尔与范克里夫","范克里夫的朋友","马迪亚斯与艾德温"}},{q="SI:7代表什么？",a="SI:7是暴风城最主要的情报组织。其密探搜集情报、从事间谍活动，并执行秘密暗杀，以保护王国与联盟的利益。",al={"si:7是什么","si7是什么意思","暴风城情报"}},{q="马迪亚斯·肖尔为何关注西部荒野？",a="肖尔关注西部荒野，是因为那里是迪菲亚潜行者的据点。他在那里部署密探，监视叛军，破坏他们针对暴风城的阴谋。",al={"肖尔西部荒野","si7西部荒野","克拉文之塔"}},{q="肖尔派往瘟疫之地的密探遭遇了什么？",a="肖尔派出五名密探，调查被遗忘者在东瘟疫之地的可疑动向。其中四人再也没有回来。唯一的幸存者口中胡乱念叨着“纳萨诺斯”和“凋零者”，几天后便在睡梦中死去。",al={"肖尔 瘟疫之地任务","肖尔五名斥候","玛瑞斯农场斥候"}}},fx={ad27d291={q="马迪亚斯·肖尔效忠哪一方？",a="马迪亚斯·肖尔坚定不移地效忠于联盟、乌瑞恩王室和暴风城王国。作为王国情报机构的首领，他监督的每一次秘密行动、指挥的每一名间谍，都致力于保护暴风城免受内部颠覆和外来威胁。",al={"马迪亚斯·肖尔 阵营","肖尔 为谁效力","马迪亚斯·肖尔 是否忠诚"}},["14719004"]={q="马迪亚斯·肖尔想要什么？",a="肖尔最关心的是在威胁发动袭击之前，消除危及暴风城存亡的隐患。他指挥SI:7的秘密情报网，瓦解迪菲亚潜行者的阴谋，监视北方被遗忘者的危险动向，并收集必要的情报，在政局极为脆弱的时期维护王国的安全。",al={"马迪亚斯·肖尔 目标","肖尔 想要什么","肖尔 动机"}},a0b783f7={q="马迪亚斯·肖尔为何闻名，又为何令人畏惧？",a="肖尔以间谍大师和刺客大师之名闻名于整个王国。他精通潜行、渗透和无声杀戮，技艺超群，声名远扬。他的情报网遍布各地，王国中几乎没有什么事能逃过他的耳目，或避开他手中利刃的干预。",al={"马迪亚斯·肖尔 为何闻名","肖尔 为何令人畏惧","刺客大师"}}},fp="12,191,14.340.0,18.409.1,24.442.0,20.182.0,32.116.0,41.240.0,25.189.0,43.168.0,57.225.0"}
P.entries["npc:mathredis-firestar"] = {n="玛瑟迪斯·火芒",s="玛瑟迪斯·火芒是一位性情古怪的血精灵法师，住在燃烧平原的烈焰峰。他利用已故导师留下的奥术研究，制作名为次级秘药的强大附魔。在此过程中，他吸取魔法绑定时释放的残余能量，以缓解自身的魔瘾。",h="玛瑟迪斯·火芒是一位性情古怪的血精灵法师，住在燃烧平原的烈焰峰。他利用已故导师留下的奥术研究，制作名为次级秘药的强大附魔。在此过程中，他吸取魔法绑定时释放的残余能量，以缓解自身的魔瘾。",kw={"秘药","燃烧平原","寻梦者","火芒","烈焰峰","圣典","玛瑟迪斯","特尔米斯"},ang={["class:Mage"]="法师们会看出，玛瑟迪斯合成秘药的手法，是一种从物品绑定过程中汲取原始魔法滋养的绝望之举，充满了不稳定性。"},sec={{t="导师的遗产与魔瘾",b="玛瑟迪斯·火芒从导师泰尔米斯·寻梦者那里学会了制作秘药的技艺，这种宝石凝聚着强化装备的奥术力量。泰尔米斯试图从辛德拉手中夺取魔法秘密，却在厄运之槌的古老废墟中惨遭杀害。这些魔法绑定之术虽然出自泰尔米斯之手，但玛瑟迪斯尚未掌握制作其中最强大秘药的技艺。他专精于制作次级秘药。对玛瑟迪斯而言，这项工作远不止是学术研究：自太阳之井陷落以来，他和所有血精灵一样，饱受对奥术力量的渴求折磨。将材料与古老圣典绑定时，魔法能量会猛烈迸发，玛瑟迪斯便从中汲取能量，维持自身。"},{t="秘药之艺",b="冒险者若为玛瑟迪斯带来合适的典籍，例如体质圣典、恢复、沉思、坚韧或贪婪，以及稀有的施法材料，他便会乐于提供自己的手艺。这道工序将不稳定的魔法材料直接与典籍文字绑定，把其中的精华凝聚成秘药，为头部或腿部护甲施加永久附魔。只要冒险者提供材料，玛瑟迪斯就既能得到报酬，也能从周围的奥术能量中获得他迫切渴求的滋养。"}},faq={{q="玛瑟迪斯·火芒是谁？",a="玛瑟迪斯·火芒是一位血精灵法师，驻留在燃烧平原的中立哨站烈焰峰。他是一名奥术师，能够制作次级秘药，为护甲附魔。",al={"玛瑟迪斯的故事","玛瑟迪斯·火芒是谁","火芒 血精灵"}},{q="玛瑟迪斯为何制作秘药？",a="太阳之井被毁后，血精灵陷入了严重的魔法戒断之苦。玛瑟迪斯吸取制作和绑定秘药时释放的原始魔法残余能量，以缓解族人与生俱来的魔瘾。",al={"为何制作秘药","玛瑟迪斯的动机","为何需要圣典"}},{q="泰尔米斯·寻梦者是谁？",a="泰尔米斯·寻梦者是玛瑟迪斯已故的导师，也是秘药最初的发明者。泰尔米斯前往厄运之槌的废墟，试图从辛德拉那里获取知识，却在传授完全部技艺之前便在那里遭人杀害。",al={"泰尔米斯","玛瑟迪斯的导师","他的导师是谁"}},{q="玛瑟迪斯能制作哪些秘药？",a="玛瑟迪斯能够制作体质、恢复、沉思、坚韧和贪婪次级秘药。最强大秘药的制作方法只有他的导师泰尔米斯知晓，玛瑟迪斯至今仍未掌握。",al={"哪些秘药","次级秘药","圣典列表"}}},fp="18,163,37.561.0,22.419.0,26.143.0,35.189.0,28.190.0,42.159.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="玛斯雷·驭熊者",s="在达纳苏斯，玛斯雷·驭熊者于塞纳里奥区指引联盟德鲁伊。他曾是范达尔·鹿盔的直属助手，帮助年轻的德鲁伊面对精神试炼、学习变形，并在卡利姆多各地效力。",h="在达纳苏斯，玛斯雷·驭熊者于塞纳里奥区指引联盟德鲁伊。他曾是范达尔·鹿盔的直属助手，帮助年轻的德鲁伊面对精神试炼、学习变形，并在卡利姆多各地效力。",kw={"水栖形态","熊形态","驭熊者","塞纳里奥议会","塞纳里奥区","达纳苏斯","利爪德鲁伊","德鲁伊训练师","范达尔·鹿盔","玛斯雷·驭熊者","晨光麦","泰达希尔"},ang={["class:Druid"]="作为联盟德鲁伊，你可以在往返达纳苏斯与月光林地时向玛斯雷寻求指引。他传授Bear Form、水栖形态，以及用草药治疗致命毒素的方法。",["faction:Alliance"]="在达纳苏斯，玛斯雷为塞纳里奥议会提供稳健而传统的领导。他温和的处事方式与范达尔·鹿盔咄咄逼人的姿态形成鲜明对比。",["race:NightElf"]="作为暗夜精灵，你可以将玛斯雷视为第三次战争后，随着泰达希尔生长，Kaldorei献身自然与平衡的榜样。"},sec={{t="塞纳里奥区的导师",b="在达纳苏斯的塞纳里奥区，玛斯雷·驭熊者指引联盟德鲁伊完成最初的仪式。作为塞纳里奥议会中备受尊敬的长者，他派遣学徒前往月光林地进行交流，并判断他们是否已准备好化身为野兽。玛斯雷仍记得自己与巨熊之灵交流时的困惑。他要求每位学徒先与神圣的枭兽月爪枭兽较量，考验自己的精神，然后再踏上利爪德鲁伊的道路。"},{t="辅佐大德鲁伊",b="多年来，玛斯雷一直担任范达尔·鹿盔的副手，处理塞纳里奥议会的日常事务，并为大德鲁伊的计划招募人手。当范达尔需要大量晨光麦时，玛斯雷安排归来的冒险者收集这种植物。私下里，他承认这种植物不自然的本质令他不安。他还协调联盟对月光林地召唤的响应，并在范达尔将注意力转向卡利姆多南部时，处理议会中微妙的政治事务。"},{t="更开阔的眼界",b="玛斯雷的思想比范达尔·鹿盔更为开明，后者的傲慢与对其他种族的蔑视早已广为人知。德鲁伊穆格雷斯·深水在西瘟疫之地对抗天灾军团时战死，他的遗物随后被送到了达纳苏斯。得知这位调查者是一名牛头人，玛斯雷深受触动。他想到，塞纳里奥议会有着共同的使命，牛头人或许并没有像范达尔所说的那样，远远背离塞纳留斯的教诲。"}},faq={{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者在达纳苏斯的塞纳里奥区指引德鲁伊。他是一位经验丰富的暗夜精灵德鲁伊，也是备受尊敬的长者，教导德鲁伊学习变形、净化毒素，并为塞纳里奥议会效力。",al={"玛斯雷是谁","玛斯雷的职责","驭熊者"}},{q="他与范达尔·鹿盔是什么关系？",a="玛斯雷曾担任范达尔·鹿盔的直属助手和副手。他处理范达尔交办的事务，包括收集晨光麦和分派任务，同时也在心中对大德鲁伊的某些观点和计划存有疑虑。",al={"范达尔的助手","鹿盔与玛斯雷"}},{q="玛斯雷帮助德鲁伊学习哪些形态？",a="玛斯雷指引年轻的德鲁伊前往月光林地朝圣，并与月爪枭兽交流，从而掌握熊形态。他还负责他们在黑海岸和西部荒野的试炼，帮助他们掌握水栖形态。",al={"达纳苏斯熊形态任务","达纳苏斯水栖形态任务","玛斯雷德鲁伊形态"}},{q="玛斯雷为什么收集晨光麦？",a="玛斯雷收集冒险者培育的晨光麦，帮助大德鲁伊范达尔·鹿盔开展有关泰达希尔的植物研究。他曾承认，待在这种植物旁边会让他感到不安。",al={"晨光麦任务","达纳苏斯为何收集晨光麦"}},{q="玛斯雷如何看待牛头人德鲁伊？",a="范达尔·鹿盔对牛头人德鲁伊持怀疑态度，而玛斯雷对他们的看法更为审慎。在思考一位牛头人德鲁伊于西瘟疫之地对抗天灾军团时的牺牲后，玛斯雷表示，牛头人对塞纳留斯教诲的遵循，或许比范达尔愿意承认的更为忠实。",al={"牛头人德鲁伊","玛斯雷牛头人"}},{q="他如何处理噩梦碎片？",a="当冒险者将一块被腐化的噩梦碎片带给菲拉·古风时，她会让他们去找玛斯雷。他检查碎片时大为震惊，并感到腐化正悄然逼近翡翠梦境。",al={"噩梦碎片玛斯雷","在噩梦中任务"}}},fp="21,206,30.454.0,24.512.0,21.430.0,29.195.0,47.217.0,45.195.0,40.183.0,45.289.0,41.182.0"}
P.entries["npc:maur-grimtotem"] = {n="玛尔·恐怖图腾",s="在奥格瑞玛地下的怒焰裂谷深处，玛尔·恐怖图腾已然殒命。年迈的女长者玛加萨·野性图腾派他去向穴居人求和，他的遗体和背包至今仍留在洞穴中。",h="在奥格瑞玛地下的怒焰裂谷深处，玛尔·恐怖图腾已然殒命。年迈的女长者玛加萨·野性图腾派他去向穴居人求和，他的遗体和背包至今仍留在洞穴中。",kw={"恐怖图腾","玛加萨","玛尔","奥格弗林特","奥格瑞玛","怒焰","背包","穴居人"},ang={["faction:Horde"]="身为部落的一员，你面对着奥格瑞玛地下一处致命洞穴中的危险。派使者独自前去与穴居人交涉，最终酿成了灾难。",["race:Tauren"]="身为牛头人，你知道恐怖图腾氏族与雷霆崖其他部族的关系并不融洽。Maur在穴居人隧道中送命，让人们对玛加萨的图谋愈发怀疑。"},sec={{t="注定失败的交涉",b="玛尔·恐怖图腾作为出使穴居人的使者，进入了奥格瑞玛地下的怒焰裂谷。部落大多数成员都认为穴居人是无法交涉的野蛮凶徒，但年迈的女长者玛加萨·野性图腾却认为和平或许有望，至少她是这么说的。玛尔带着她的提议走进蜿蜒的洞穴。穴居人杀死了他，他的尸体至今仍由他们的酋长奥格弗林特看守。"},{t="女长者的盘算",b="玛尔死后，玛加萨寻找冒险者，请他们取回他带进洞穴的背包，并为他报仇。玛尔是否相信能与穴居人达成和平，至今无人知晓。找到他遗物的人或许仍会疑惑，玛加萨究竟把他当作真正的使者派去，还是仅仅把他当作阴谋中的一枚棋子。"}},faq={{q="玛尔·恐怖图腾是谁？",a="玛尔·恐怖图腾是恐怖图腾氏族的一名牛头人。玛加萨·野性图腾派他出使奥格瑞玛地下怒焰裂谷中的穴居人，他在那里被穴居人杀害。",al={"玛尔是谁","玛尔·恐怖图腾的故事","玛尔在做什么"}},{q="他为何试图与穴居人交涉？",a="年迈的女长者玛加萨声称，她派玛尔前去寻求和平，并试探这些地下敌人的实力。她是否另有动机，至今仍无定论。",al={"为何与穴居人求和","穴居人交涉","为何与穴居人谈判"}},{q="是谁杀死了玛尔·恐怖图腾？",a="怒焰裂谷的穴居人杀死了玛尔。他们的酋长奥格弗林特看守着他的尸体。",al={"玛尔如何死去","谁杀了他","玛尔之死"}},{q="他的遗体和随身物品后来怎样了？",a="玛尔的遗体仍在怒焰裂谷中，就在奥格弗林特附近。雷霆崖的拉哈罗派冒险者找回玛尔遗失的背包，并将其带到长者高地交给他，以便转交玛加萨·野性图腾。",al={"玛尔的尸体","遗失的背包","玛尔的背包"}}},fp="14,180,18.372.0,27.309.1,23.167.0,40.160.0,26.98.0,41.189.0"}
P.entries["npc:maur-raincaller"] = {n="茂尔·祈雨",s="在血蹄村，茂尔·祈雨照看着莫高雷的兽群与野生动物。他处理与这片草原的自然和灵性息息相关的事务。",h="在血蹄村，茂尔·祈雨照看着莫高雷的兽群与野生动物。他处理与这片草原的自然和灵性息息相关的事务。",kw={"血蹄村","茂尔·祈雨","马兹拉纳其","莫高雷","陆行鸟","牛头人"},ang={["class:Hunter"]="茂尔·祈雨派你到草原各处猎杀狼、美洲狮、陆行鸟和猛鹫，收集它们的身体部位，治疗马兹拉纳其造成的咬伤。",["race:Tauren"]="作为一名离开纳拉其营地的年轻牛头人，你可以帮助保护族人的祖地，抵御四处游荡的掠食者和肆意破坏的野兽。"},sec={{t="血蹄村的居民",b="茂尔·祈雨住在血蹄村中心附近的石牛湖岸边。他照管着与莫高雷的野生动物和元素平衡有关的事务。陆行鸟马兹拉纳其咬伤了他，导致伤口感染，于是他请年轻的旅行者收集动物的身体部位来配制药剂。"}},faq={{q="茂尔·祈雨是谁？",a="茂尔·祈雨是一名牛头人，住在莫高雷的血蹄村。他请旅行者对付附近那些不安分的野生动物。",al={"茂尔·祈雨的职责","茂尔是谁","茂尔·祈雨的故事"}},{q="在哪里能找到茂尔·祈雨？",a="茂尔·祈雨就在血蹄村的露天处，周围是锥形帐篷和炉火。村庄位于雷霆崖以南，坐落在石牛湖东岸。",al={"茂尔·祈雨的位置","茂尔在哪里","茂尔的坐标"}},{q="茂尔遇到了什么麻烦？",a="茂尔·祈雨被马兹拉纳其咬伤后，伤口发生了感染。他请旅行者带来莫高雷的狼、美洲狮、陆行鸟和猛鹫的身体部位，以便配制药剂。",al={"茂尔·祈雨的任务","马兹拉纳其的麻烦","茂尔想要什么"}}},fx={fd24c378={q="茂尔·祈雨效忠于哪一方？",a="茂尔·祈雨是忠诚的血蹄氏族牛头人，也是部落的一员。他住在血蹄村，坚定地效忠于大酋长凯恩·血蹄，并致力于守护莫高雷的平原。",al={"茂尔·祈雨的阵营","茂尔·祈雨属于部落吗","茂尔为谁效力"}},["231da345"]={q="茂尔·祈雨为何在血蹄村？",a="茂尔住在血蹄村，这里是血蹄氏族在莫高雷平原上的家园。可怕的长蹄怪马兹拉纳切咬伤了他，伤口随后感染，因此他留在村中，请旅人带来制作药剂所需的野兽部件。",al={"茂尔为何在血蹄村","茂尔·祈雨在莫高雷的目的","茂尔在这里做什么"}}},fp="15,151,31.282.0,23.122.0,33.171.0,34.184.0"}
P.entries["npc:maurin-bonesplitter"] = {n="玛乌林·碎骨",s="玛乌林·碎骨是一名驻扎在凄凉之地幽灵岗哨的被遗忘者学者兼施法者。他受科尔丹委派，监视恶魔教派的活动，并凭借对古老知识的深刻理解瓦解火刃氏族。玛乌林对这些教徒满怀鄙夷，认为他们都是愚蠢之徒，看不清在幕后操纵他们的黑暗存在。",h="玛乌林·碎骨是一名驻扎在凄凉之地幽灵岗哨的被遗忘者学者兼施法者。他受科尔丹委派，监视恶魔教派的活动，并凭借对古老知识的深刻理解瓦解火刃氏族。玛乌林对这些教徒满怀鄙夷，认为他们都是愚蠢之徒，看不清在幕后操纵他们的黑暗存在。",kw={"火刃氏族","堕落者","凄凉之地","被遗忘者","幽灵岗哨","科尔丹","玛乌林·碎骨"},ang={["class:Mage"]="造访幽灵岗哨的法师能够欣赏玛乌林的行事方式：他深思熟虑，凭借学识，以专门的克制手段破解黑暗仪式。",["class:Warlock"]="术士会看出玛乌林对恶魔契约的深刻理解，而他的鄙夷也鲜明地提醒着他们，为更强大的恶魔效力会招致怎样的危险。",["faction:Horde"]="玛乌林代表着幽暗城对部落西部前哨的专门支援，以黑暗学识协助牛头人盟友对抗恶魔腐化。",["race:Undead"]="玛乌林表明，被遗忘者的力量既依靠强大的通灵之力，也同样依靠精巧的奥术研究和对敌人弱点的利用。"},sec={{t="流亡者中的学者",b="幽灵岗哨坐落于凄凉之地的干旱荒野，主要是牛头人和部落的前哨，而玛乌林·碎骨是其中为数不多的亡灵居民之一，显得格外不同。玛乌林是一名博学的施法者，深谙禁忌历史与神秘力量，并非粗野的士兵。他的奥术天赋和敏锐才智引起了科尔丹的注意，后者将他派往此地，观察日益壮大的恶魔势力，并协调针对性的打击。"},{t="对火刃氏族的鄙夷",b="玛乌林将大部分恶意都倾注在盘踞于凄凉之地各处的火刃氏族教派身上。他极为厌恶这些教徒鲁莽的野心，嘲笑他们不明白借来的力量只会让他们沦为恶魔主人的奴仆。玛乌林凭借占卜法术和仪式知识，招募部落冒险者，有条不紊地破坏教派的召唤仪式，挫败他们在这片贫瘠荒野上的行动。"}},faq={{q="玛乌林·碎骨是谁？",a="玛乌林·碎骨是一名居住在凄凉之地幽灵岗哨的被遗忘者术士兼学者。他受科尔丹委派，运用古老知识和黑暗魔法，铲除在当地活动的火刃氏族教派。",al={"玛乌林 碎骨的故事","玛乌林是谁","玛乌林 凄凉之地"}},{q="为什么一个亡灵会待在牛头人的岗哨？",a="幽灵岗哨是部落在凄凉之地的一处重要聚居地。科尔丹特意将玛乌林派驻于此，因为这座前哨是监视和打击周边荒野中肆虐的火刃氏族教徒的理想据点。",al={"玛乌林为何在幽灵岗哨","凄凉之地的亡灵"}},{q="玛乌林如何看待火刃氏族？",a="玛乌林对火刃氏族深怀鄙夷。在他眼里，这些人是可悲而无知的棋子，妄以为自己掌握着真正的力量，却全然不知自己只是恶魔主人的傀儡。",al={"玛乌林 火刃氏族","玛乌林为何憎恨火刃氏族"}},{q="是谁将玛乌林·碎骨派往凄凉之地？",a="玛乌林在凄凉之地的职务由科尔丹委任。科尔丹看重玛乌林对教派活动和古老知识的广博见识，命他积极阻挠火刃氏族，并最终将其从这片区域彻底铲除。",al={"谁派来了玛乌林","玛乌林 科尔丹","玛乌林的上司"}},{q="玛乌林会交给冒险者什么任务？",a="玛乌林要求冒险者调查火刃氏族，并收集一块怨怒巡影者的头皮和一枚纳迦的神谕水晶。他用这些材料破解阻挡占卜的结界，找出教派背后的恶魔领主。",al={"玛乌林的任务","玛乌林想要什么"}},{q="玛乌林隶属于塞纳里奥议会还是部落？",a="玛乌林是被遗忘者的忠诚成员，为部落效力。他始终以幽灵岗哨的部落营地为据点，协助部落勇士肃清荒野中的教徒活动。",al={"玛乌林属于部落吗","玛乌林的阵营"}}},fp="19,276,24.385.0,30.407.0,27.208.0,42.160.0,46.180.0,41.198.0,48.215.0,59.126.0"}
P.entries["npc:maxan-anvol"] = {n="马克萨恩·安沃尔",s="在卡拉诺斯的雷酒酿制厂，马克萨恩·安沃尔向矮人牧师传授圣光之道。在侍僧获授教会的法衣之前，他会考验他们的信仰。",h="在卡拉诺斯的雷酒酿制厂，马克萨恩·安沃尔向矮人牧师传授圣光之道。在侍僧获授教会的法衣之前，他会考验他们的信仰。",kw={"绝望祷言","丹莫罗","圣光之衣","圣光","卡拉诺斯","马克萨恩·安沃尔","牧师训练师","雷酒酿制厂"},ang={["class:Priest"]="身为牧师，你很早就会在丹莫罗遇见马克萨恩·安沃尔，开始学习神圣修行的基础。他会传授绝望祷言等种族祷言，并授予你第一件教会长袍。",["faction:Alliance"]="身为联盟成员，你会看到马克萨恩照料巡山人和斥候的身体与精神，让他们做好准备，守护丹莫罗，抵御穴居人、冰霜巨魔和荒野野兽。",["race:Dwarf"]="身为矮人，你能在卡拉诺斯的麦酒桶旁、众人聚集之处，看到铁炉堡务实的信仰。"},sec={{t="酒馆中的牧师",b="马克萨恩·安沃尔在雷酒酿制厂照料卡拉诺斯居民的精神需求。旅人、巡山人和侍僧聚集于此，因为这座村镇坐落在寒脊山谷与铁炉堡之间。这里的旅店吸引着过往行人。马克萨恩为每一位来客祈祷并提供指引，手边便是烈性啤酒。"},{t="信徒的考验",b="在初学的牧师踏入更广阔的世界之前，马克萨恩·安沃尔会考验他们的信仰与技艺。他派遣入门者，用简单的治疗祷言救治丹莫罗受伤的守卫。证明自己虔诚而技艺娴熟的人，会获得第一套牧师法衣，象征着他们在圣光教会中的一席之地。"}},faq={{q="在哪里可以找到马克萨恩·安沃尔？",a="你可以在卡拉诺斯的雷酒酿制厂内找到马克萨恩·安沃尔。这家旅店是镇民和穿越丹莫罗的旅人聚集的地方。",al={"马克萨恩·安沃尔位置","马克萨恩在哪","卡拉诺斯牧师训练师"}},{q="马克萨恩·安沃尔传授什么？",a="马克萨恩·安沃尔向初学和中阶牧师传授神圣治疗、暗影控制与神圣防护。矮人牧师还可以学习绝望祷言等祷言。",al={"他传授什么","马克萨恩·安沃尔法术"}},{q="为什么一位神圣牧师会待在酿酒厂里？",a="矮人的日常生活与庆典总是围绕着酿酒和酒馆展开。雷酒酿制厂是卡拉诺斯的公共聚会场所，也是旅人的歇脚处，马克萨恩在这里为镇民、守卫和过路人提供精神慰藉。",al={"为何在酿酒厂","酒馆里的牧师"}},{q="马克萨恩·安沃尔会交付什么特殊任务吗？",a="会。马克萨恩·安沃尔通过“圣光的恩赐”和“圣光之衣”等试炼，考验立志成为牧师的人。他派他们去救治雪地里受伤的巡山人，成功者便能获得侍僧长袍。",al={"马克萨恩任务","圣光之衣"}},{q="他会对牧师以外的人说什么？",a="马克萨恩·安沃尔告诫冒险者，永远不要背弃圣光。神圣的恩典或许会在战斗中救他们一命。",al={"马克萨恩对话","马克萨恩台词"}},{q="侏儒能向马克萨恩·安沃尔学习吗？",a="能。侏儒可以接受训练成为牧师，而马克萨恩欢迎所有立誓追随圣光的联盟成员。",al={"侏儒能和他交谈吗","侏儒牧师训练师"}}},fx={["32034ea0"]={q="马克萨恩·安沃尔是谁？",a="马克萨恩·安沃尔是一位驻留卡拉诺斯、信奉圣光的矮人牧师。他在丹莫罗指导初入信仰之门的信徒，考验年轻侍僧的修行和他们与圣光的交流，然后才授予符合其教会身份的长袍。",al={"马克萨恩 是谁","马克萨恩·安沃尔 背景故事","卡拉诺斯 牧师训练师"}},["310c3ecc"]={q="马克萨恩·安沃尔效忠哪一方？",a="他忠于铁炉堡王国、圣光和大联盟。他致力于保护丹莫罗当地的民众，并培养新的牧师，让他们在联盟各地守护信仰。",al={"马克萨恩 阵营","马克萨恩 是否属于联盟","马克萨恩·安沃尔 效忠对象"}},["1141108e"]={q="马克萨恩·安沃尔想要什么？",a="马克萨恩希望培养人们对圣光的虔诚，并确保新晋牧师做好充分准备，迎接世间的考验。他考验求学者，确保他们配得上神圣的长袍，同时提醒所有路人，永远不要背弃圣光的恩典。",al={"马克萨恩·安沃尔 目标","马克萨恩 想要什么","马克萨恩·安沃尔 动机"}}},fp="11,186,19.302.0,20.309.0,29.152.0,28.167.0,49.229.0,41.214.0,32.119.0,34.109.0"}
P.entries["npc:maybell-maclure"] = {n="梅贝尔·马科伦",s="在马科伦农场，梅贝尔·马科伦爱上了斯通菲尔德家的人，但两家的世仇让她无法与托米·乔·斯通菲尔德相守。",h="在马科伦农场，梅贝尔·马科伦爱上了斯通菲尔德家的人，但两家的世仇让她无法与托米·乔·斯通菲尔德相守。",kw={"恋人","马科伦","梅贝尔","斯通菲尔德","托米·乔","葡萄园"},ang={["faction:Alliance"]="对穿行于艾尔文森林的联盟旅人而言，梅贝尔的恋情表明，即使在王国腹地，个人的烦恼与陈年的积怨也依然存在。"},sec={{t="葡萄园里的苦命鸳鸯",b="梅贝尔·马科伦照料着家中的葡萄园，旁边就是斯通菲尔德农场。她爱着托米·乔·斯通菲尔德，他是邻近农场的继承人。两家长久以来的仇怨让他们无法相守，梅贝尔想找个办法，避开家人警惕的目光，与他说上话。"},{t="为真爱调制的药剂",b="梅贝尔无法公开往来于两座农场之间，于是向心怀同情的旅人和米莱德·斯通菲尔德求助。闪金镇的炼金师威廉·匹斯特调制了隐形水。梅贝尔喝下隐形水，悄悄离开马科伦家，在河岸边与托米·乔相会。"}},faq={{q="为什么梅贝尔和托米·乔不能见面？",a="马科伦家和斯通菲尔德家多年来积怨甚深。两家都禁止彼此往来，因此梅贝尔和托米·乔向亲人隐瞒了恋情。",al={"家族为何结仇","马科伦与斯通菲尔德的世仇","为何无法相守"}},{q="是什么让梅贝尔无法离开葡萄园？",a="由于与斯通菲尔德家的仇怨，梅贝尔的家人对她看管得很严。她需要帮助，才能避开家人的注意，与托米·乔见面。",al={"梅贝尔如何偷偷溜走","艾尔文隐形药水","她如何与托米见面"}},{q="梅贝尔在哪里与托米·乔见面？",a="托米·乔在马科伦农场与斯通菲尔德农场交界处的河岸边等候，那里避开了两处农庄的视线。",al={"相会地点","他们在哪里相会","托米·乔在哪里"}},{q="谁在帮助梅贝尔成就这段恋情？",a="米莱德·斯通菲尔德同情这对恋人，让愿意帮忙的旅人去找闪金镇的炼金师威廉·匹斯特。他提供了他们秘密相会所需的东西。",al={"谁帮助梅贝尔","斯通菲尔德的帮手"}}},fx={c4338ded={q="梅贝尔·马科伦是谁？",a="梅贝尔·马科伦是一位年轻的人类女子，住在艾尔文森林的马科伦农场。她深深爱上了托米·乔·斯通菲尔德，因此被卷入自家与邻居斯通菲尔德家族之间由来已久的激烈争斗。",al={"梅贝尔 是谁","梅贝尔·马科伦是谁","梅贝尔·马科伦 背景故事"}},["9f94442c"]={q="梅贝尔·马科伦效忠哪一方？",a="她是联盟的忠诚子民，也是马科伦家族的女儿。然而，面对马科伦家族与斯通菲尔德家族之间狭隘而激烈的争斗，她完全拒绝这份仇恨，选择了对托米·乔的爱，而非家族的宿怨。",al={"梅贝尔 是否属于联盟","梅贝尔 效忠哪一方","梅贝尔 阵营"}},cbd5fa72={q="梅贝尔·马科伦想要什么？",a="梅贝尔只想与托米·乔·斯通菲尔德在一起。由于双方家族彼此深恶痛绝，她向富有同情心的旅人和值得信赖的知己寻求帮助，设法与他秘密见面而不被发现。",al={"梅贝尔 想要什么","梅贝尔·马科伦 目标","梅贝尔 为何需要帮助"}},b079e731={q="梅贝尔·马科伦为什么在这里？",a="梅贝尔住在马科伦农场，那是她家位于艾尔文森林南部的产业。亲人们严密看管着她，让她无法离开葡萄园，她盼望着能有机会溜出去，与心上人相会。",al={"梅贝尔·马科伦为何在这里","梅贝尔为何在葡萄园"}},["26be6d7a"]={q="梅贝尔·马科伦与谁有关联？",a="梅贝尔出身于拥有葡萄园的马科伦家族。她与敌对的斯通菲尔德农庄继承人托米·乔·斯通菲尔德相恋，还与米莱德·斯通菲尔德保持着秘密联系，后者支持这对年轻人的地下恋情。",al={"梅贝尔·马科伦的人际关系","梅贝尔与谁有亲属关系","梅贝尔的关联"}}},fp="15,132,29.261.0,26.285.1,47.179.0,48.146.1,34.136.0,35.169.1"}
P.entries["npc:mebok-mizzyrix"] = {n="麦伯克·米希瑞克斯",s="麦伯克·米希瑞克斯在棘齿城雇用旅行者，前往贫瘠之地及更远的地方搜集奇异之物。这个地精商人希望靠不寻常的动植物牟利。他最出名的生意是一种用迅猛龙角制成的饮料，据说能让头脑更加敏锐。",h="麦伯克·米希瑞克斯在棘齿城雇用旅行者，前往贫瘠之地及更远的地方搜集奇异之物。这个地精商人希望靠不寻常的动植物牟利。他最出名的生意是一种用迅猛龙角制成的饮料，据说能让头脑更加敏锐。",kw={"贫瘠之地","蓝叶薯","麦伯克","米希瑞克斯","迅猛龙角","棘齿城","智慧饮料","热砂港"},ang={["faction:Alliance"]="从藏宝海湾乘船抵达的联盟旅行者，可以在中立的棘齿城找到麦伯克，无须担心敌对卫兵。",["faction:Horde"]="穿越贫瘠之地、途经棘齿城的部落旅行者，可以通过清除附近的危险野兽赚取钱财。",["profession:Cooking"]="麦伯克的饮料配方可能会让厨师犯难：他坚持用磨碎的迅猛龙角来调制饮料。",["profession:Herbalism"]="麦伯克对Blueleaf块茎的兴趣，展现了采集卡利姆多奇异植物的商业价值。"},sec={{t="精于生意的炼金师",b="麦伯克·米希瑞克斯在棘齿城经营生意，这座中立港口汇聚了水手、海盗和商人。他秉承热砂港的精神，不放过任何赚钱的机会。他不经营矿石或布料，而是搜寻卡利姆多荒野中的珍稀动植物。他相信，这些东西能制成值钱的饮剂和商品。"},{t="智慧饮料生意",b="麦伯克的主要生意是一种饮料，他希望它能提高饮用者的智力。他相信，当地迅猛龙的狡黠与凶猛源自它们鼻端的角。因此，他雇用猎人，从贫瘠之地各处带回完整的迅猛龙角。比起道德和口味，他更在乎能否卖出一种让顾客相信有效的饮剂。"},{t="奇异的试剂与植物",b="除了迅猛龙角，麦伯克也在寻找其他奇异的样本。他想要性质不稳定的深苔蜘蛛卵，以及埋在剃刀沼泽荆棘丛中的稀有蓝叶薯。这些委托让雇佣兵深入险境。麦伯克相信，任何具有奇异特性的动植物，都能装进瓶子出售。"}},faq={{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是棘齿城的一名地精商人，棘齿城是贫瘠之地的中立港口城镇。他雇用旅行者，为自己的生意搜集奇异的动植物。",al={"麦伯克是谁","麦伯克·米希瑞克斯背景故事","棘齿城地精麦伯克"}},{q="智慧饮料是什么？",a="智慧饮料是麦伯克·米希瑞克斯希望酿制并出售的试验性补剂，旨在提高饮用者的智力。他相信，贫瘠之地那些聪明的迅猛龙的角，能赋予饮用者敏锐的本能和狡黠的头脑。",al={"智慧饮料","智慧饮料任务","迅猛龙角药水"}},{q="在哪里能找到麦伯克·米希瑞克斯？",a="在贫瘠之地东海岸的棘齿城建筑之间，可以找到麦伯克·米希瑞克斯。这座港口向部落和联盟的旅行者开放。",al={"麦伯克位置","麦伯克在哪里","寻找麦伯克·米希瑞克斯"}},{q="麦伯克为什么想要迅猛龙角？",a="麦伯克相信，贫瘠之地迅猛龙的狡黠源自它们的角。他打算把这些角磨成粉，作为提高智力的饮料的主要原料。",al={"为什么要迅猛龙角","迅猛龙角用途","麦伯克用迅猛龙角做什么"}},{q="麦伯克为什么派人去剃刀沼泽？",a="麦伯克派旅行者进入剃刀沼泽，借助受过训练的嗅探兽挖掘蓝叶薯。他寻找这种稀有植物，是看中了它珍贵而独特的性质。",al={"为什么去剃刀沼泽","麦伯克剃刀沼泽任务","剃刀沼泽蓝叶块茎"}},{q="麦伯克为部落还是联盟效力？",a="麦伯克属于热砂港，在中立的棘齿城独立经营。他与部落和联盟的旅行者做买卖、签订契约，一心追逐钱财。",al={"麦伯克属于部落吗","麦伯克属于联盟吗","麦伯克阵营"}}},fx={["55f078f0"]={q="麦伯克·米希瑞克斯想要什么？",a="麦伯克热衷于调制稀奇古怪的新炼金药剂，尤其是他试验中的“聪明饮料”。为了完善这些古怪配方，他派冒险者搜遍贫瘠之地及其危险的深处，寻找各种奇特材料，从完整的迅猛龙角到稀有的根茎样本和蜘蛛卵。",al={"麦伯克想要什么","麦伯克需要什么","麦伯克·米希瑞克斯的目标"}},c521482b={q="麦伯克·米希瑞克斯为何在棘齿城？",a="棘齿城是雄心勃勃的地精首选的港口城镇，他们可以在此轻松获取卡利姆多的野生资源。麦伯克以这里为据点，能轻易雇用来自任意阵营、刚刚抵达的佣兵，让他们深入危险的草原，采集他实验所需的野生样本。",al={"麦伯克为何在这里","麦伯克为何在棘齿城","麦伯克·米希瑞克斯与贫瘠之地"}}},fp="14,263,25.317.0,23.334.0,25.306.0,22.172.0,22.215.0,34.146.0,33.158.0,45.156.0,46.169.0"}
P.entries["npc:melithar-staghelm"] = {n="麦利萨尔·鹿盔",s="在幽影谷的奥达希尔外，麦利萨尔·鹿盔为年轻的暗夜精灵指引道路。他派他们去了解树妖塔琳德拉为何重返林间空地。鹿盔这个姓氏将他与大德鲁伊范达尔·鹿盔联系在一起，但他们之间的关系尚不明确。",h="在幽影谷的奥达希尔外，麦利萨尔·鹿盔为年轻的暗夜精灵指引道路。他派他们去了解树妖塔琳德拉为何重返林间空地。鹿盔这个姓氏将他与大德鲁伊范达尔·鹿盔联系在一起，但他们之间的关系尚不明确。",kw={"奥达希尔","麦利萨尔","幽影谷","鹿盔","泰达希尔","训练师"},ang={["race:NightElf"]="作为一名从幽影谷启程的暗夜精灵，你离开奥达希尔的庇护后不久，就会遇见麦利萨尔。"},sec={{t="奥达希尔的引路人",b="麦利萨尔·鹿盔在奥达希尔外等候，那里是暗夜精灵初入世界的地方。他是一位聆听森林之灵的德鲁伊，得知林地守护者塔琳德拉在离开多年后回到了幽影谷。麦利萨尔察觉到异样，便派初来者前往奥达希尔西南方，寻找那位树妖，了解她为何重返林地。"},{t="鹿盔之名",b="鹿盔这个姓氏引人注目，因为在玛法里奥·怒风消失于翡翠梦境之后，大德鲁伊范达尔·鹿盔便在达纳苏斯领导塞纳里奥议会。麦利萨尔从未声称自己出身显赫，也从不谈及自己的血统。他究竟是大德鲁伊的家人，还是仅仅与他共用一个古老的卡多雷姓氏，至今仍无人知晓。眼下，麦利萨尔仍在奥达希尔的树根旁履行着平凡的职责。"}},faq={{q="麦利萨尔·鹿盔是谁？",a="麦利萨尔·鹿盔是一名暗夜精灵，在幽影谷的奥达希尔外为初来者指引道路。他派他们去寻找树妖塔琳德拉。",al={"麦利萨尔","麦利萨尔是谁","麦利萨尔 幽影谷"}},{q="麦利萨尔与大德鲁伊范达尔·鹿盔有亲属关系吗？",a="他们确切的亲属关系尚不明确。麦利萨尔从未说过，自己是否与大德鲁伊范达尔·鹿盔或范达尔已故的儿子瓦斯坦恩有亲属关系。他可能是一位远亲，也可能只是与他们共用一个卡多雷姓氏。",al={"范达尔的亲属","范达尔的兄弟","鹿盔家族"}},{q="麦利萨尔为新冒险者提供什么指引？",a="麦利萨尔派初来者前往奥达希尔西南方，寻找在离开多年后重返幽影谷的林地守护者塔琳德拉。森林之灵告诉了他她归来的消息，他希望初来者去了解她为何来到这片林地。",al={"麦利萨尔的任务","麦利萨尔做什么"}},{q="在哪里可以找到麦利萨尔·鹿盔？",a="麦利萨尔·鹿盔站在泰达希尔的幽影谷中央，位于奥达希尔入口外的木制坡道上。",al={"麦利萨尔的位置","麦利萨尔在哪里","寻找麦利萨尔·鹿盔"}}},fp="17,228,20.362.0,17.403.0,25.126.0,50.210.0,49.239.0,35.116.0"}
P.entries["npc:melor-stonehoof"] = {n="梅洛·石蹄",s="在雷霆崖的猎人高地，梅洛·石蹄为猎人设下艰难的试炼。他派部落猎人前往贫瘠之地和千针石林，追猎危险的野兽，考验他们的追踪本领与胆魄。",h="在雷霆崖的猎人高地，梅洛·石蹄为猎人设下艰难的试炼。他派部落猎人前往贫瘠之地和千针石林，追猎危险的野兽，考验他们的追踪本领与胆魄。",kw={"死沼巨鳄","霜喉雪人","猎人高地","猎人之道","梅洛","瑟格拉·黑棘","钢齿土狼","石蹄","雷霆崖"},ang={["class:Hunter"]="身为猎人，你沿着神圣的狩猎之路，接受梅洛的追踪试炼。",["faction:Horde"]="身为部落的一员，你要面对那些危及莫高雷至千针石林各处聚落的野兽。梅洛磨炼战士与猎手，让他们能够承担这项职责。",["race:Tauren"]="身为牛头人，你在梅洛身上看到了对狩猎的深切敬畏，这场力量的试炼与Earth Mother保持着平衡。"},sec={{t="荒野导师",b="梅洛·石蹄在雷霆崖的猎人高地上守望着平原。对牛头人而言，狩猎将生存、灵性的平衡以及对自然界强大掠食者的敬意融为一体。梅洛教导那些为部落执弓持刃的人尊重这种平衡，并派有潜力的猎手挑战传说中的野兽，检验他们的技艺。"},{t="狩猎试炼",b="梅洛派猎人追猎那些行踪难觅、威胁荒野的野兽。他们在贫瘠之地的十字路口协助女猎手瑟格拉·黑棘，随后前往千针石林，追猎狡诈凶恶的土狼钢齿土狼。这些试炼考验猎人能否凭借智慧与武力，战胜卡利姆多中部最致命的生物。"},{t="远方的巨兽",b="在贫瘠之地证明了本领的猎人，还要面对远方的野兽。梅洛派经验丰富的猎人前去追猎死沼巨鳄，一头栖息在尘泥沼泽中的古老鳄鱼，以及霜喉雪人，一头出没于奥特兰克山脉的凶猛雪人。每次狩猎都在检验猎手是否掌握了猎人之道。"}},faq={{q="在哪里能找到梅洛·石蹄？",a="梅洛·石蹄位于雷霆崖的猎人高地。这座台地位于牛头人主城的主崖南侧，可经由绳桥抵达。",al={"梅洛·石蹄位置","梅洛在哪","梅洛·石蹄坐标"}},{q="梅洛·石蹄提供哪些任务？",a="梅洛为中等级的冒险者提供一系列狩猎挑战。他指引猎人去贫瘠之地寻找瑟格拉·黑棘，派他们追猎凶猛的土狼钢齿土狼，并指引他们前往尘泥沼泽寻找死沼巨鳄，前往奥特兰克山脉寻找霜喉雪人。",al={"梅洛任务","梅洛做什么","梅洛·石蹄任务线"}},{q="梅洛为什么派猎人追猎钢齿土狼？",a="钢齿土狼是一头凶恶狡诈的土狼，在千针石林游荡。梅洛派有能力的猎人追踪并杀死它，考验他们在荒野中的技巧、耐力与勇气。",al={"为什么杀钢齿土狼","钢齿土狼任务背景"}},{q="死沼巨鳄是什么？",a="死沼巨鳄是尘泥沼泽中的一头鳄鱼，体型异常庞大，极具攻击性。梅洛要求猎人杀死它，以此考验他们的本领。",al={"死沼巨鳄是谁","死沼巨鳄背景","死沼巨鳄野兽"}},{q="必须是猎人职业才能接受他的任务吗？",a="不必。任何有能力、为部落而战的冒险者，都可以接受梅洛的狩猎试炼。这些试炼体现了猎人之道，也适合猎人职业。",al={"梅洛仅限猎人","其他职业能做梅洛任务吗"}},{q="瑟格拉·黑棘是谁，梅洛为什么派你去找她？",a="瑟格拉·黑棘是贫瘠之地十字路口的一位兽人女猎手。梅洛派有潜力的猎人去协助她制服平原上桀骜不驯的掠食者，并向另一位荒野老手学习。",al={"梅洛与瑟格拉的关系","瑟格拉·黑棘任务"}}},fp="15,173,21.312.0,18.305.0,29.294.0,33.137.0,39.264.0,44.175.0,17.145.0,52.144.0,60.197.0"}
P.entries["npc:menara-voidrender"] = {n="梅纳拉·沃伦德",s="在棘齿城，梅纳拉·沃伦德向两个阵营的术士传授黑暗法术。这位人类术士在卡利姆多的一处避风港中，分享她对束缚恶魔的神器和奥术工艺的知识，远离正统势力的管束。",h="在棘齿城，梅纳拉·沃伦德向两个阵营的术士传授黑暗法术。这位人类术士在卡利姆多的一处避风港中，分享她对束缚恶魔的神器和奥术工艺的知识，远离正统势力的管束。",kw={"贫瘠之地","血袍","恶魔学","梅纳拉","欧拉赫","棘齿城","塔贝萨","沃伦德","术士"},ang={["class:Warlock"]="身为术士，你可以向梅纳拉学习，她教导两个阵营的修习者制作附魔长袍，并将恶魔束缚在聚能宝珠中。",["profession:Tailoring"]="身为裁缝，你可以了解梅纳拉如何将高级裁缝材料与邪能材料结合，织造能引导恶魔之力的耐用法衣。",["race:Human"]="身为人类，你会看到梅纳拉在中立领地钻研黑暗法术，远离暴风城的地下墓穴，也不受对王国的忠诚所牵绊。"},sec={{t="棘齿城的避风港",b="梅纳拉·沃伦德在贫瘠之地的中立地精港口棘齿城开展研究。东部王国的许多术士在城市地下的地窖或隐秘屠宰场中钻研，而棘齿城让梅纳拉远离肯瑞托、暴风城的卫兵和奥格瑞玛的监工。在那里，她可以公开研究秘术。无论属于哪个阵营，只要学徒有足够的能力，她都会传授知识，因此她成了黑暗法术修习者之间少有的交汇点。"},{t="束缚术大师",b="资深的召唤师都知道，梅纳拉是研究囚禁并驾驭恶魔之魂的宝珠的权威。她运用配制复杂的材料，指导学徒完成严苛的仪式，制作附魔衣物和束缚法器。她的技艺远近闻名，就连铁炉堡和幽暗城也有耳闻，艾泽拉斯各地的高阶术士都会派遣最有潜力的学生渡海向她求教。"},{t="与沼泽的渊源",b="梅纳拉·沃伦德与塔贝萨有一段旧日渊源，后者是一位隐居法师，独自住在尘泥沼泽深处。塔贝萨钻研奥术，而梅纳拉研究邪能束缚和恶魔学。当奥拉赫宝珠这样的强大圣物需要修复，或需要特殊知识时，她们共同的过去便在卡利姆多的荒野之间架起桥梁。"}},faq={{q="梅纳拉·沃伦德是谁？",a="梅纳拉·沃伦德是一位人类术士，居住在贫瘠之地的中立港口棘齿城。她向成长中的术士传授制作仪式和束缚恶魔的法术。",al={"梅纳拉是谁","梅纳拉·沃伦德的故事","棘齿城的术士是谁"}},{q="为什么一位人类术士会住在贫瘠之地？",a="棘齿城让梅纳拉得以保持中立，远离各大政权的监视。在这座地精港口，她修习禁忌法术，教导两个阵营的学生，不受圣骑士、法师或城市卫兵的干涉。",al={"梅纳拉为何在棘齿城","她为何在贫瘠之地","术士为何在棘齿城"}},{q="梅纳拉擅长哪种魔法？",a="梅纳拉专精于恶魔学、附魔黑暗织物，以及囚禁恶魔的容器。她尤其以制作和修复奥拉赫宝珠这样的束缚宝珠而闻名。",al={"梅纳拉教什么","梅纳拉·沃伦德的能力","梅纳拉擅长什么"}},{q="梅纳拉与塔贝萨有什么关系？",a="梅纳拉与塔贝萨过去就有交情。塔贝萨隐居在尘泥沼泽，修习传统法术；寻求奥拉赫宝珠相关知识的术士会发现，这两位女性都了解彼此的才能。",al={"梅纳拉与塔贝萨","她如何认识塔贝萨","与塔贝萨的关系"}},{q="梅纳拉偏向联盟还是部落？",a="梅纳拉在棘齿城保持中立。只要术士有能力、有抱负，能够驾驭邪能，无论来自联盟还是部落，她都会传授知识并提供制作服务。",al={"梅纳拉属于联盟还是部落","梅纳拉的阵营","梅纳拉为谁效力"}},{q="她帮助制作哪些重要神器？",a="梅纳拉指导学徒织造魔化金线血袍，这件衣袍灌注了恶魔之力。她还帮助修为高深的修习者找回并组装奥拉赫宝珠所需的部件。",al={"梅纳拉的任务","她制作什么","魔化金线血袍 梅纳拉"}}},fp="17,223,19.444.0,19.388.0,17.345.1,25.157.0,45.239.0,45.188.0,39.225.0,44.173.0,42.196.0"}
